#![feature(portable_simd)]
#![forbid(unsafe_code)]

//! Statistical distributions for FrankenSciPy.
//!
//! Matches `scipy.stats` core continuous distributions:
//! - `norm` — Normal (Gaussian) distribution
//! - `t` — Student's t-distribution
//! - `chi2` — Chi-squared distribution
//! - `uniform` — Uniform distribution
//!
//! Each distribution implements pdf, cdf, sf, ppf (inverse CDF), mean, var, std.

pub mod audit;
pub mod qmc;
pub use audit::{
    SyncSharedAuditLedger, record_bounded_recovery, record_fail_closed, sync_audit_ledger,
};
pub use qmc::{
    DiscrepancyMethod, GeometricDiscrepancyMethod, HaltonSampler, LatinHypercubeSampler,
    MultinomialQmc, MultivariateNormalQmc, PoissonDiskSampler, QmcEngine, SobolSampler,
    centered_discrepancy, centered_discrepancy_iterative, discrepancy, geometric_discrepancy,
    l2_star_discrepancy, l2_star_discrepancy_iterative, mixture_discrepancy,
    mixture_discrepancy_iterative, scale as qmc_scale, update_centered_discrepancy,
    update_discrepancy, wraparound_discrepancy, wraparound_discrepancy_iterative,
};

use std::{
    f64::consts::{FRAC_1_SQRT_2, LN_2, PI},
    sync::OnceLock,
};

use fsci_runtime::RuntimeMode;
use rand::{Rng, RngExt, SeedableRng, rngs::StdRng, seq::SliceRandom};

const EULER_MASCHERONI: f64 = 0.577_215_664_901_532_9;
/// Largest sample size for which `ks_2samp` computes the EXACT p-value.
///
/// This mirrors `scipy.stats.ks_2samp`'s `MAX_AUTO_N`, and the predicate is
/// deliberately `max(n1, n2)` rather than the product `n1 * n2`:
/// ```text
/// mode = 'exact' if max(n1, n2) <= MAX_AUTO_N else 'asymp'
/// ```
/// A product-based cap disagrees with SciPy over a large region -- any
/// roughly-balanced pair with `n1 * n2 > 1e6` but `max(n1, n2) <= 10000` gets
/// the exact p-value from SciPy and the asymptotic one from a product gate. At
/// `n1 = n2 = 1100` that is a 5% relative error on the p-value
/// (exact 0.005122654178708466 vs asymptotic 0.004866628830199581).
/// See `frankenscipy-6ozha`; same defect class as `frankenscipy-ksk1u`.
///
/// The exact path is O(n1*n2) time and O(n2) memory, which is the same
/// asymptotic cost SciPy pays in `_attempt_exact_2kssamp`. The lcm
/// `checked_mul` below still falls back to asymptotic on overflow, mirroring
/// SciPy's own int32 lcm guard.
const KS_2SAMP_EXACT_MAX_N: usize = 10_000;

/// Error type for stats APIs that validate structured inputs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StatsError {
    InvalidArgument(String),
    ShapeMismatch {
        expected: usize,
        actual: usize,
    },
    NonFiniteInput {
        argument: &'static str,
    },
    DataTooSmall {
        required: usize,
        got: usize,
    },
    MissingParameter {
        name: &'static str,
    },
    Unsupported {
        operation: &'static str,
        distribution: &'static str,
    },
    Arithmetic {
        detail: String,
    },
}

impl std::fmt::Display for StatsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidArgument(msg) => write!(f, "invalid argument: {msg}"),
            Self::ShapeMismatch { expected, actual } => {
                write!(f, "shape mismatch: expected {expected}, got {actual}")
            }
            Self::NonFiniteInput { argument } => {
                write!(f, "non-finite input in {argument}")
            }
            Self::DataTooSmall { required, got } => {
                write!(f, "data too small: required {required}, got {got}")
            }
            Self::MissingParameter { name } => write!(f, "missing parameter: {name}"),
            Self::Unsupported {
                operation,
                distribution,
            } => write!(f, "{operation} is unsupported for {distribution}"),
            Self::Arithmetic { detail } => write!(f, "arithmetic failure: {detail}"),
        }
    }
}

impl std::error::Error for StatsError {}

/// Error type for `ContinuousDistribution::try_fit` — the non-panicking
/// counterpart to `fit()`. Callers that cannot tolerate a panic on
/// distributions without MLE support should use `try_fit` and match on
/// this error.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FitError {
    /// MLE is not implemented for this distribution. The default
    /// `try_fit` returns this variant; individual distributions can
    /// override to provide a closed-form or numerical MLE.
    NotImplemented { distribution: &'static str },
    /// The provided sample is too small (or degenerate) to fit.
    InsufficientData { required: usize, actual: usize },
    /// The sample violates a distribution-specific support constraint
    /// (e.g. negative values for HalfNormal, data not in `[0,1]` for Beta).
    UnsupportedData(String),
    /// Numerical fitting did not converge within the configured budget.
    NonConvergent(String),
}

impl std::fmt::Display for FitError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented { distribution } => {
                write!(f, "fit not implemented for {distribution}")
            }
            Self::InsufficientData { required, actual } => {
                write!(f, "insufficient data: need {required}, got {actual}")
            }
            Self::UnsupportedData(msg) => write!(f, "unsupported data: {msg}"),
            Self::NonConvergent(msg) => write!(f, "fit did not converge: {msg}"),
        }
    }
}

impl std::error::Error for FitError {}

impl From<FitError> for StatsError {
    fn from(value: FitError) -> Self {
        match value {
            FitError::NotImplemented { distribution } => Self::Unsupported {
                operation: "fit",
                distribution,
            },
            FitError::InsufficientData { required, actual } => Self::DataTooSmall {
                required,
                got: actual,
            },
            FitError::UnsupportedData(detail) => Self::InvalidArgument(detail),
            FitError::NonConvergent(detail) => Self::Arithmetic { detail },
        }
    }
}

fn unsupported_distribution_moment(
    value: f64,
    operation: &'static str,
    distribution: &'static str,
) -> Result<f64, StatsError> {
    if value.is_nan() {
        Err(StatsError::Unsupported {
            operation,
            distribution,
        })
    } else {
        Ok(value)
    }
}

/// Trait for continuous probability distributions.
pub trait ContinuousDistribution {
    /// Probability density function.
    fn pdf(&self, x: f64) -> f64;
    /// Log probability density function.
    fn logpdf(&self, x: f64) -> f64 {
        log_probability(self.pdf(x))
    }
    /// Cumulative distribution function.
    fn cdf(&self, x: f64) -> f64;

    /// Whether `cdf`/`sf` are CHEAP closed forms (≤ a couple transcendentals, e.g. one
    /// `exp`/`atan`/`powf`). The default `cdf_many`/`sf_many` gate is tuned for COSTLY
    /// gammainc/betainc cdfs (2048 elts/thread); a cheap 1-exp/1-atan cdf does too little
    /// work to amortise the thread spawn and runs ~7-9x SLOWER parallel at n≈4096 (measured).
    /// Override to `true` for elementary closed-form cdf/sf so those `*_many` use a high gate
    /// (stay serial until the array is genuinely large). Byte-identical either way.
    fn cdf_sf_is_cheap(&self) -> bool {
        false
    }

    /// Cumulative distribution at many points — work-gated parallel map of the per-point `cdf`,
    /// byte-identical to mapping it. Wins for dists with a costly special-function cdf; the gate
    /// is raised for cheap closed-form cdfs (see [`cdf_sf_is_cheap`](Self::cdf_sf_is_cheap)) so the
    /// thread spawn does not pessimise them. Default for all continuous dists.
    /// Parallel gate (min elts/thread) for `cdf_many`/`sf_many`. Default derives from
    /// [`cdf_sf_is_cheap`](Self::cdf_sf_is_cheap) (65536 cheap-elementary, else 2048 costly
    /// gammainc/betainc). Erf/lgamma-class cdfs with an INTERMEDIATE per-elt cost (~25-50ns,
    /// break-even ~50k — e.g. Normal/erfc) override this to ~32768 directly, since they are
    /// neither elementary-cheap nor costly. Higher = stays serial longer.
    fn cdf_sf_par_min(&self) -> usize {
        if self.cdf_sf_is_cheap() { 65536 } else { 2048 }
    }

    #[must_use]
    fn cdf_many(&self, xs: &[f64]) -> Vec<f64>
    where
        Self: Sync,
    {
        par_continuous_map_min(xs, self.cdf_sf_par_min(), |x| self.cdf(x))
    }

    /// Survival function at many points — work-gated parallel map of the per-point `sf`.
    #[must_use]
    fn sf_many(&self, xs: &[f64]) -> Vec<f64>
    where
        Self: Sync,
    {
        par_continuous_map_min(xs, self.cdf_sf_par_min(), |x| self.sf(x))
    }

    /// Whether `ppf`/`isf` are CHEAP closed forms (analytic quantile, e.g. one
    /// `ln`/`tan`/`powf`). Distinct from [`cdf_sf_is_cheap`](Self::cdf_sf_is_cheap):
    /// a dist can have a cheap cdf but an EXPENSIVE bisection/Newton ppf (no closed
    /// inverse) — those must stay eager. Override to `true` ONLY when both ppf and
    /// isf are elementary closed forms, so `ppf_many`/`isf_many` use a high gate
    /// (the default 2048 gate pessimises a cheap 1-ln ppf ~10x at n≈4096, measured).
    fn ppf_isf_is_cheap(&self) -> bool {
        false
    }

    /// Parallel gate (min elts/thread) for `ppf_many`/`isf_many`. Default derives from
    /// [`ppf_isf_is_cheap`](Self::ppf_isf_is_cheap). Erf-inverse-class quantiles (ndtri,
    /// ~50ns, break-even ~90k — e.g. Normal) override directly.
    fn ppf_isf_par_min(&self) -> usize {
        if self.ppf_isf_is_cheap() { 65536 } else { 2048 }
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point `ppf`.
    /// Gate raised for cheap closed-form quantiles (see [`ppf_isf_is_cheap`](Self::ppf_isf_is_cheap)).
    #[must_use]
    fn ppf_many(&self, qs: &[f64]) -> Vec<f64>
    where
        Self: Sync,
    {
        par_continuous_map_min(qs, self.ppf_isf_par_min(), |q| self.ppf(q))
    }

    /// Inverse survival at many probabilities — work-gated parallel map of the per-point `isf`.
    #[must_use]
    fn isf_many(&self, qs: &[f64]) -> Vec<f64>
    where
        Self: Sync,
    {
        par_continuous_map_min(qs, self.ppf_isf_par_min(), |q| self.isf(q))
    }
    /// Log cumulative distribution function.
    fn logcdf(&self, x: f64) -> f64 {
        log_probability(self.cdf(x))
    }
    /// Survival function: 1 - cdf(x).
    ///
    /// # Precision
    ///
    /// **The default `1.0 - self.cdf(x)` loses precision in the right
    /// tail** (per frankenscipy-wofb). For x far in the tail where
    /// cdf(x) is near 1, the subtraction drops most significant digits
    /// (Normal.sf(10) via default returns 0.0 vs. true ~7.6e-24).
    ///
    /// Distribution implementations that have a precision-preserving
    /// closed form SHOULD override this method. Examples already
    /// overriding sf():
    ///
    /// - Weibull (line ~1567): exp(-(x/scale)^c)
    /// - Normal (line ~400):   erfc(x/sqrt(2))/2
    ///
    /// Distributions inheriting the default expose the precision loss
    /// for tail p-values.
    fn sf(&self, x: f64) -> f64 {
        1.0 - self.cdf(x)
    }
    /// Log survival function.
    ///
    /// Inherits the precision loss of the default `sf()` (per
    /// frankenscipy-wofb). For tail work, distributions should override
    /// logsf directly (e.g. using log1p(-cdf(x)) or a closed form).
    fn logsf(&self, x: f64) -> f64 {
        log_probability(self.sf(x))
    }
    /// Percent point function (inverse CDF) via bisection.
    /// Override for distributions with analytic inverses.
    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std())
    }
    /// Inverse survival function: the `x` such that `sf(x) = q`.
    ///
    /// Mathematically `isf(q) = ppf(1 - q)`, but `1 - q` underflows to
    /// exactly `1.0` once `q` drops below machine epsilon (~1.1e-16), so the
    /// naive route returns `+inf` for every distribution in the deep right
    /// tail (per frankenscipy isf-tail audit: `norm.isf(1e-30)` gave `inf`
    /// vs SciPy's `~11.46`). When `1 - q` is exactly representable we keep the
    /// historical `ppf(1 - q)` route bit-for-bit; otherwise we invert the
    /// precision-preserving survival function `sf(x) = q` directly.
    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        let p = 1.0 - q;
        if p < 1.0 {
            // 1 - q is representable: identical to the historical behaviour.
            return self.ppf(p);
        }
        // Deep right tail: 1 - q rounds to 1.0, so ppf(1 - q) loses all
        // precision. Invert sf(x) = q on the (overridden, accurate) survival
        // function instead.
        isf_bisection(|x| self.sf(x), q, self.mean(), self.std())
    }
    /// Mean of the distribution.
    fn mean(&self) -> f64;
    /// Variance of the distribution.
    fn var(&self) -> f64;
    /// Standard deviation.
    fn std(&self) -> f64 {
        self.var().sqrt()
    }

    /// Generate `n` random variates via inverse transform sampling.
    fn rvs(&self, n: usize, rng: &mut impl Rng) -> Vec<f64> {
        (0..n)
            .map(|_| {
                let u: f64 = rng.random();
                self.ppf(u)
            })
            .collect()
    }

    /// Fit distribution to data (maximum likelihood estimation).
    ///
    /// # Default behavior (per frankenscipy-wofb)
    ///
    /// **Default panics with `FitError::NotImplemented`**. Asymmetric vs. the
    /// `entropy`/`skewness`/`kurtosis` defaults which return NaN.
    /// Callers working generically over distributions must either:
    ///   (a) restrict to distribution types that override `fit`, or
    ///   (b) wrap invocations in `std::panic::catch_unwind`, or
    ///   (c) use [`Self::try_fit`] which returns a typed error instead
    ///       of panicking (br-d692).
    ///
    /// Consider this contract unstable: the asymmetry (panic vs NaN)
    /// is tracked for consolidation.
    fn fit(_data: &[f64]) -> Self
    where
        Self: Sized,
    {
        match Self::try_fit(_data) {
            Ok(fitted) => fitted,
            Err(err) => std::panic::panic_any(err),
        }
    }

    /// Non-panicking MLE fit. Returns `Err(FitError::NotImplemented { … })`
    /// by default; distributions override to provide a closed-form or
    /// numerical fit. Callers that must not panic (generic driver code,
    /// fuzz harnesses, library consumers) should use `try_fit` and match
    /// on `FitError` variants.
    ///
    /// When overriding, return the same typed errors used by other
    /// distributions — `InsufficientData` for degenerate samples,
    /// `UnsupportedData` for values outside the support.
    fn try_fit(_data: &[f64]) -> Result<Self, FitError>
    where
        Self: Sized,
    {
        Err(FitError::NotImplemented {
            distribution: std::any::type_name::<Self>(),
        })
    }

    /// Audit-emitting counterpart to `try_fit` (br-egba-3). Delegates
    /// to `try_fit`, and on any `FitError` records an
    /// `AuditAction::FailClosed` event on the provided ledger. Useful
    /// under Hardened-mode deployments where callers need a forensic
    /// trail of which samples were rejected.
    fn try_fit_with_audit(data: &[f64], ledger: &SyncSharedAuditLedger) -> Result<Self, FitError>
    where
        Self: Sized,
    {
        let result = Self::try_fit(data);
        if let Err(err) = &result {
            let reason = format!("fit::{err}");
            // Fingerprint the first few bytes of the sample so
            // repeated identical rejections collide under the same
            // event hash.
            let head: Vec<u8> = data.iter().take(8).flat_map(|v| v.to_le_bytes()).collect();
            record_fail_closed(ledger, &head, &reason, "rejected");
        }
        result
    }

    /// Differential entropy H(X) = -∫ f(x) log f(x) dx.
    /// Returns entropy in nats (natural logarithm base).
    /// Matches `scipy.stats.<dist>.entropy()`.
    ///
    /// # Default behavior (per frankenscipy-wofb)
    ///
    /// **Default returns `f64::NAN`**, silently indistinguishable from
    /// a genuinely-undefined entropy. Distributions that don't
    /// override this method appear to have undefined entropy; callers
    /// cannot tell unimplemented apart from legitimately NaN without
    /// inspecting the impl.
    fn entropy(&self) -> f64 {
        f64::NAN
    }

    /// Fallible entropy accessor for generic callers that need to
    /// distinguish an inherited unsupported default from a numeric
    /// result. Existing distribution-specific `entropy()` overrides are
    /// reused automatically; inherited NaN defaults become a typed
    /// `StatsError::Unsupported` instead of a silent sentinel.
    fn try_entropy(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.entropy(), "entropy", std::any::type_name::<Self>())
    }

    /// Median of the distribution (50th percentile).
    /// Default uses ppf(0.5); override for analytic formulas.
    fn median(&self) -> f64 {
        self.ppf(0.5)
    }

    /// Skewness (third standardized moment).
    /// Returns 0 for symmetric distributions.
    /// Matches `scipy.stats.<dist>.stats(moments='s')`.
    fn skewness(&self) -> f64 {
        f64::NAN
    }

    /// Fallible skewness accessor for generic callers. Inherited NaN
    /// defaults become `StatsError::Unsupported`.
    fn try_skewness(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.skewness(), "skewness", std::any::type_name::<Self>())
    }

    /// Excess kurtosis (fourth standardized moment minus 3).
    /// Normal distribution has excess kurtosis 0.
    /// Matches `scipy.stats.<dist>.stats(moments='k')`.
    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    /// Fallible excess-kurtosis accessor for generic callers. Inherited
    /// NaN defaults become `StatsError::Unsupported`.
    fn try_kurtosis(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.kurtosis(), "kurtosis", std::any::type_name::<Self>())
    }

    /// Mode of the distribution (value where PDF is maximized).
    /// Returns NaN for distributions with undefined or non-unique mode.
    fn mode(&self) -> f64 {
        f64::NAN
    }

    /// Confidence interval containing `alpha` fraction of probability mass.
    /// Returns (lower, upper) bounds centered around the median.
    /// Matches `scipy.stats.<dist>.interval(alpha)`.
    fn interval(&self, alpha: f64) -> (f64, f64) {
        if !(0.0..=1.0).contains(&alpha) {
            return (f64::NAN, f64::NAN);
        }
        let lower = self.ppf((1.0 - alpha) / 2.0);
        let upper = self.ppf((1.0 + alpha) / 2.0);
        (lower, upper)
    }
}

/// Generic fitting helper for continuous distributions with built-in MLE support.
///
/// This is the Rust-generic equivalent of SciPy's distribution-specific fit surface
/// for the implemented continuous distributions in this crate.
#[must_use]
pub fn fit<D>(data: &[f64]) -> D
where
    D: ContinuousDistribution,
{
    D::fit(data)
}

/// Vectorised maximum-likelihood [`fit`] over `n` independent datasets — parallel
/// across the batch. `scipy.stats.<dist>.fit` loops in Python, and for
/// distributions WITHOUT a closed form (e.g. `weibull_min`, `beta`) it runs a
/// Nelder-Mead optimiser calling the Python likelihood repeatedly (slow); fsci's
/// per-dataset `D::fit` is an inlined Rust solver, fanned whole-dataset across
/// cores. Entry `k` equals `fit::<D>(&datasets[k])`, so the result is identical to
/// the serial map. (Fit ACCURACY vs SciPy is per-distribution — both approximate
/// the same MLE; e.g. Weibull agrees to ~1e-5, the optimiser-tolerance gap.)
#[must_use]
pub fn fit_many<D>(datasets: &[Vec<f64>]) -> Vec<D>
where
    D: ContinuousDistribution + Send,
{
    let nrows = datasets.len();
    if nrows == 0 {
        return Vec::new();
    }
    let cores = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let nthreads = cores.min(nrows);
    if nthreads <= 1 || nrows < 8 {
        return datasets.iter().map(|d| D::fit(d)).collect();
    }
    let chunk = nrows.div_ceil(nthreads);
    let parts: Vec<Vec<D>> = std::thread::scope(|scope| {
        datasets
            .chunks(chunk)
            .map(|c| scope.spawn(move || c.iter().map(|d| D::fit(d)).collect::<Vec<D>>()))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("fit_many worker panicked"))
            .collect()
    });
    let mut out = Vec::with_capacity(nrows);
    for part in parts {
        out.extend(part);
    }
    out
}

fn log_probability(probability: f64) -> f64 {
    if probability < 0.0 {
        f64::NAN
    } else {
        probability.ln()
    }
}

/// Helper: validate fit() data for parameterless / standardized distributions.
/// Requires at least one observation and rejects non-finite values. Used by
/// the no-op fit() implementations on parameterless distributions where the
/// only thing to check is whether the data is well-formed.
fn validate_parameterless_fit_data(data: &[f64]) -> Result<(), FitError> {
    if data.is_empty() {
        return Err(FitError::InsufficientData {
            required: 1,
            actual: 0,
        });
    }
    for &x in data {
        if !x.is_finite() {
            return Err(FitError::UnsupportedData(format!(
                "fit data contains non-finite value: {x}"
            )));
        }
    }
    Ok(())
}

fn validate_finite_fit_data(
    data: &[f64],
    required: usize,
    distribution: &str,
) -> Result<(), FitError> {
    if data.len() < required {
        return Err(FitError::InsufficientData {
            required,
            actual: data.len(),
        });
    }
    for &x in data {
        if !x.is_finite() {
            return Err(FitError::UnsupportedData(format!(
                "{distribution} data contains non-finite value: {x}"
            )));
        }
    }
    Ok(())
}

fn sample_population_variance(data: &[f64]) -> f64 {
    let mean = sample_mean(data);
    data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / data.len() as f64
}

fn sample_standardized_skewness(data: &[f64]) -> f64 {
    let mean = sample_mean(data);
    let mut m2 = 0.0_f64;
    let mut m3 = 0.0_f64;
    for &x in data {
        let centered = x - mean;
        m2 += centered * centered;
        m3 += centered * centered * centered;
    }
    m2 /= data.len() as f64;
    m3 /= data.len() as f64;
    if m2 <= 0.0 {
        f64::NAN
    } else {
        m3 / m2.powf(1.5)
    }
}

/// Maximum-likelihood shape `c` for Weibull-shaped data on strictly
/// positive samples `y_i > 0`. Returns `Err(...)` if the data is empty,
/// non-finite, non-positive, or numerically unable to bracket a finite
/// root.
///
/// This is the profile-likelihood form of the joint Weibull (c, λ)
/// MLE: the score equation
///   g(c) = 1/c + mean(ln y) − Σ y^c ln y / Σ y^c = 0
/// is the derivative of the log-likelihood with respect to `c` after
/// profiling out `λ̂(c)^c = (1/n) Σ y^c`, monotonically decreasing in
/// `c`. The returned `c` is the maximum-likelihood shape for the data
/// at any scale; the (discarded) scale estimate is `λ̂ = ((1/n) Σ y^c)^{1/c}`.
/// We bracket a sign change on a logarithmically spaced grid of
/// candidate shapes and refine with the secant method (with bisection
/// fallback when the secant step escapes the bracket). Caller is
/// responsible for any sign-mirror or absolute-value transform.
fn fit_standard_weibull_shape_mle(
    positive_data: &[f64],
    distribution_label: &str,
) -> Result<f64, FitError> {
    let n = positive_data.len();
    if n < 2 {
        return Err(FitError::InsufficientData {
            required: 2,
            actual: n,
        });
    }
    if let Some(&bad) = positive_data.iter().find(|&&y| !y.is_finite() || y <= 0.0) {
        return Err(FitError::UnsupportedData(format!(
            "{distribution_label} fit requires positive finite samples; got {bad}"
        )));
    }
    let logs: Vec<f64> = positive_data.iter().map(|y| y.ln()).collect();
    let log_mean = logs.iter().sum::<f64>() / n as f64;

    // Score g(c) = 1/c + log_mean − Σ y^c ln y / Σ y^c.
    let score = |c: f64| -> f64 {
        // Compute Σ y^c and Σ y^c ln y in a numerically stable manner
        // by anchoring the powers to the data max.
        let cln_max = logs.iter().copied().fold(f64::NEG_INFINITY, f64::max) * c;
        let mut s_w = 0.0_f64;
        let mut s_w_log = 0.0_f64;
        for (&ly, &y) in logs.iter().zip(positive_data.iter()) {
            let w = (c * ly - cln_max).exp(); // = y^c / max(y)^c
            s_w += w;
            s_w_log += w * y.ln();
        }
        1.0 / c + log_mean - s_w_log / s_w
    };

    // Logarithmic search on c ∈ [1e-3, 1e3] for a sign change.
    let candidates: Vec<f64> = (-30..=30).map(|k| 10.0_f64.powf(k as f64 / 10.0)).collect();
    let mut lo = None::<(f64, f64)>;
    let mut hi = None::<(f64, f64)>;
    for &c in &candidates {
        let g = score(c);
        if !g.is_finite() {
            continue;
        }
        if g > 0.0 {
            lo = Some((c, g));
        } else {
            hi = Some((c, g));
            break;
        }
    }
    let ((mut a, mut ga), (mut b, mut gb)) = match (lo, hi) {
        (Some(a), Some(b)) => (a, b),
        _ => {
            return Err(FitError::NonConvergent(format!(
                "{distribution_label} MLE could not bracket a positive shape root"
            )));
        }
    };

    // Secant refinement, with bisection fallback when the secant step
    // escapes the bracket.
    for _ in 0..200 {
        if (b - a).abs() < 1e-12 * a.abs().max(1e-12) {
            break;
        }
        let mut c = b - gb * (b - a) / (gb - ga);
        if !c.is_finite() || c <= a.min(b) || c >= a.max(b) {
            c = 0.5 * (a + b);
        }
        let gc = score(c);
        if !gc.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "{distribution_label} MLE produced non-finite score at c={c}"
            )));
        }
        if gc > 0.0 {
            a = c;
            ga = gc;
        } else {
            b = c;
            gb = gc;
        }
    }
    let c_hat = 0.5 * (a + b);
    if c_hat.is_finite() && c_hat > 0.0 {
        Ok(c_hat)
    } else {
        Err(FitError::NonConvergent(format!(
            "{distribution_label} MLE did not converge to a positive shape"
        )))
    }
}

/// Generic inverse CDF via bisection search.
fn ppf_bisection(cdf: impl Fn(f64) -> f64, q: f64, mean: f64, std: f64) -> f64 {
    // Initial bracket: start around mean ± 10*std
    let half_width = if std.is_finite() && std > 0.0 {
        10.0 * std
    } else {
        100.0
    };
    let center = if mean.is_finite() { mean } else { 0.0 };
    let mut lo = center - half_width;
    let mut hi = center + half_width;
    let mut step = half_width;

    // Expand bracket if needed (bounded to prevent infinite loops)
    for _ in 0..60 {
        if cdf(lo) <= q {
            break;
        }
        step *= 2.0;
        lo -= step;
    }
    step = half_width;
    for _ in 0..60 {
        if cdf(hi) >= q {
            break;
        }
        step *= 2.0;
        hi += step;
    }

    // Bisection
    for _ in 0..100 {
        let mid = 0.5 * (lo + hi);
        if (hi - lo).abs() < 1e-12 * mid.abs().max(1.0) {
            return mid;
        }
        if cdf(mid) < q {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    0.5 * (lo + hi)
}

/// Generic inverse survival function via bisection: find `x` with `sf(x) = q`.
///
/// Mirror of [`ppf_bisection`] for the *decreasing* survival function. Used by
/// the default `isf` only in the deep right tail where `1 - q` underflows to
/// `1.0` and the `ppf(1 - q)` route would lose all precision. The bracket
/// expansion tolerates heavy tails (many doublings) while keeping `hi` finite.
fn isf_bisection(sf: impl Fn(f64) -> f64, q: f64, mean: f64, std: f64) -> f64 {
    let half_width = if std.is_finite() && std > 0.0 {
        10.0 * std
    } else {
        100.0
    };
    let center = if mean.is_finite() { mean } else { 0.0 };
    let mut lo = center - half_width;
    let mut hi = center + half_width;

    // Expand hi rightward until sf(hi) <= q (sf decreasing -> deep tail).
    let mut step = half_width.max(1.0);
    for _ in 0..1100 {
        if sf(hi) <= q {
            break;
        }
        let next = hi + step;
        if !next.is_finite() {
            break;
        }
        hi = next;
        step *= 2.0;
    }
    // Expand lo leftward until sf(lo) >= q (usually already true at the start).
    step = half_width.max(1.0);
    for _ in 0..1100 {
        if sf(lo) >= q {
            break;
        }
        let next = lo - step;
        if !next.is_finite() {
            break;
        }
        lo = next;
        step *= 2.0;
    }

    for _ in 0..200 {
        let mid = 0.5 * (lo + hi);
        if (hi - lo).abs() < 1e-12 * mid.abs().max(1.0) {
            return mid;
        }
        if sf(mid) > q {
            // mid lies too far left (survival probability too high).
            lo = mid;
        } else {
            hi = mid;
        }
    }
    0.5 * (lo + hi)
}

fn gumbel_fit_loc_scale(data: &[f64]) -> (f64, f64) {
    if data.is_empty() || data.iter().any(|&x| !x.is_finite()) {
        return (f64::NAN, f64::NAN);
    }

    let n = data.len() as f64;
    let mean = data.iter().sum::<f64>() / n;
    let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
    if !var.is_finite() {
        return (f64::NAN, f64::NAN);
    }
    if var == 0.0 {
        return (mean, 0.0);
    }

    let mut scale = (6.0 * var).sqrt() / PI;
    if !scale.is_finite() || scale <= 0.0 {
        return (f64::NAN, f64::NAN);
    }

    for _ in 0..32 {
        let inv_scale = 1.0 / scale;
        let max_exponent = data
            .iter()
            .map(|&x| -x * inv_scale)
            .fold(f64::NEG_INFINITY, f64::max);
        let mut sum_w = 0.0;
        let mut sum_xw = 0.0;
        let mut sum_x2w = 0.0;
        for &x in data {
            let w = (-x * inv_scale - max_exponent).exp();
            sum_w += w;
            sum_xw += x * w;
            sum_x2w += x * x * w;
        }
        if !sum_w.is_finite() || sum_w == 0.0 {
            break;
        }

        let weighted_mean = sum_xw / sum_w;
        let weighted_var = (sum_x2w / sum_w - weighted_mean * weighted_mean).max(0.0);
        let residual = mean - weighted_mean - scale;
        if residual.abs() <= 1.0e-12 * scale.max(1.0) {
            break;
        }

        let derivative = -weighted_var / (scale * scale) - 1.0;
        let next_scale = scale - residual / derivative;
        if !next_scale.is_finite() || next_scale <= 0.0 {
            break;
        }
        scale = next_scale;
    }

    let inv_scale = 1.0 / scale;
    let max_exponent = data
        .iter()
        .map(|&x| -x * inv_scale)
        .fold(f64::NEG_INFINITY, f64::max);
    let sum_w = data
        .iter()
        .map(|&x| (-x * inv_scale - max_exponent).exp())
        .sum::<f64>();
    if !sum_w.is_finite() || sum_w == 0.0 {
        return (mean - EULER_MASCHERONI * scale, scale);
    }

    let loc = -scale * (max_exponent + (sum_w / n).ln());
    (loc, scale)
}

fn simpson_integrate(f: impl Fn(f64) -> f64, a: f64, b: f64, n: usize) -> f64 {
    let n = n + (n % 2);
    let h = (b - a) / n as f64;
    let mut sum = f(a) + f(b);
    for i in 1..n {
        let x = a + i as f64 * h;
        let w = if i % 2 == 0 { 2.0 } else { 4.0 };
        sum += w * f(x);
    }
    sum * h / 3.0
}

/// Double-exponential (tanh-sinh) quadrature on a finite interval `[a, b]`.
///
/// Unlike composite Simpson, the change of variables
/// `x = (a+b)/2 + (b-a)/2 · tanh((π/2)·sinh(t))` samples only the **open**
/// interval `(a, b)` and assigns doubly-exponentially small weights as
/// `t → ±∞`. This makes the rule converge geometrically even when the
/// integrand has *integrable* endpoint singularities — e.g. the `1/√(x(1−x))`
/// blow-ups of the Arcsine pdf, where Simpson samples `f(a)=f(b)=+∞` and
/// returns `inf` (per frankenscipy-p2olp). Endpoint terms whose weight·value
/// is non-finite (weight underflowed to 0 against an `inf` sample) contribute
/// 0, which is the correct limit for an integrable singularity.
///
/// The gate the original comment reserved has been claimed: `OrderStatistic`'s
/// `mean`/`var` integrate the base quantile against a Beta weight over `(0, 1)`,
/// which is exactly the open-interval, endpoint-clustered case this rule exists
/// for (the base `ppf` diverges at both ends for an unbounded support). It is
/// therefore no longer `#[cfg(test)]`; the pdf-normalization guards still use it.
fn tanh_sinh_integrate(f: impl Fn(f64) -> f64, a: f64, b: f64) -> f64 {
    // NOT `a >= b` (frankenscipy-023vy). This guard is deliberately NaN-aware:
    // with a NaN endpoint every comparison is false, so `!(a < b)` is true and
    // the integral short-circuits to 0.0, whereas `a >= b` would be false and
    // let a NaN interval through. `partial_cmp` says exactly "not Less",
    // including the incomparable case, which is the contract meant here.
    if !matches!(a.partial_cmp(&b), Some(std::cmp::Ordering::Less)) {
        return 0.0;
    }
    let c = 0.5 * (b - a);
    let d = 0.5 * (a + b);
    let half_pi = std::f64::consts::FRAC_PI_2;
    // One abscissa/weight contribution at parameter t.
    let term = |t: f64| -> f64 {
        let s = t.sinh();
        let arg = half_pi * s;
        let x = d + c * arg.tanh();
        let ch = arg.cosh();
        let w = c * half_pi * t.cosh() / (ch * ch);
        let v = w * f(x);
        if v.is_finite() { v } else { 0.0 }
    };
    // Beyond |t| ≈ 3.5 the weights are ~1e-15 of the peak, so truncating there
    // loses nothing at double precision.
    let t_max = 3.5;
    let level_sum = |h: f64| -> f64 {
        let mut sum = term(0.0);
        let mut k = 1;
        loop {
            let t = k as f64 * h;
            if t > t_max {
                break;
            }
            sum += term(t) + term(-t);
            k += 1;
        }
        sum * h
    };
    let mut h = 0.5;
    let mut prev = level_sum(h);
    for _ in 0..12 {
        h *= 0.5;
        let curr = level_sum(h);
        if (curr - prev).abs() <= 1e-13 + 1e-12 * curr.abs() {
            return curr;
        }
        prev = curr;
    }
    prev
}

fn simpson_integrate_adaptive(
    f: impl Fn(f64) -> f64,
    a: f64,
    b: f64,
    initial_n: usize,
    rel_tol: f64,
    abs_tol: f64,
    max_refinements: usize,
) -> f64 {
    let mut n = initial_n.max(2);
    n += n % 2;
    let mut prev = simpson_integrate(&f, a, b, n);
    for _ in 0..max_refinements {
        n *= 2;
        let curr = simpson_integrate(&f, a, b, n);
        let refined = curr + (curr - prev) / 15.0;
        let err = (refined - curr).abs();
        let tol = abs_tol.max(rel_tol * refined.abs());
        if err <= tol {
            return refined;
        }
        prev = curr;
    }
    prev
}

// ══════════════════════════════════════════════════════════════════════
// Normal (Gaussian) Distribution
// ══════════════════════════════════════════════════════════════════════

/// Normal distribution N(loc, scale²).
///
/// Matches `scipy.stats.norm(loc=mu, scale=sigma)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Normal {
    pub loc: f64,
    pub scale: f64,
}

impl Default for Normal {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl Normal {
    /// Standard normal distribution N(0, 1).
    #[must_use]
    pub fn standard() -> Self {
        Self::default()
    }

    /// Create N(loc, scale²). Panics if scale <= 0.
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }

    /// Percent point function (inverse CDF) using rational approximation.
    ///
    /// Matches `scipy.stats.norm.ppf(q)`.
    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        self.loc + self.scale * standard_normal_ppf(q)
    }
}

impl ContinuousDistribution for Normal {
    // erfc cdf/ndtri ppf are intermediate-cost (~25-50ns): pessimized ~4x@n=4096 under the
    // default 2048 gate; measured break-even ~55k (cdf) / ~90k (ppf). Gate them to the
    // moderate tier (cdf 32768 → parallel@65k; ppf 65536 → parallel@131k) so small/medium
    // arrays stay serial. Byte-identical (order-preserving). Normal is the most common dist.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        (-0.5 * z * z).exp() / (self.scale * (2.0 * PI).sqrt())
    }

    fn logpdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        -0.5 * z * z - self.scale.ln() - 0.5 * (2.0 * PI).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        // Delegate to standard_normal_cdf for deep-tail precision.
        // The naïve 0.5·(1 + erf(z·FRAC_1_SQRT_2)) form catastrophically
        // cancels for z ≲ -3; standard_normal_cdf switches to the
        // 0.5·erfc(-z·FRAC_1_SQRT_2) path for z < 0. Resolves
        // [frankenscipy-701x0]; see also [frankenscipy-6exgz].
        let z = (x - self.loc) / self.scale;
        standard_normal_cdf(z)
    }

    fn logcdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        fsci_special::log_ndtr_scalar(z)
    }

    fn sf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        0.5 * fsci_special::erfc_scalar(z * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        fsci_special::log_ndtr_scalar(-z)
    }

    fn ppf(&self, q: f64) -> f64 {
        // Use the specialized rational approximation
        Normal::ppf(self, q)
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        // Normal is symmetric: isf(q)=ppf(1−q)=loc−scale·ndtri(q). The trait
        // default computes 1−q first, and ndtri near 1 is ill-conditioned, so a
        // ~1e-16 error in 1−q blew up to ~4.4e-7 at q=1e-12. ndtri(q) on the
        // small argument is well-conditioned and matches scipy.stats.norm.isf.
        // frankenscipy-d2gag
        self.loc - self.scale * fsci_special::ndtri_scalar(q)
    }

    fn mean(&self) -> f64 {
        self.loc
    }

    fn var(&self) -> f64 {
        self.scale * self.scale
    }

    fn fit(data: &[f64]) -> Self {
        let n = data.len() as f64;
        if n == 0.0 {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        Self {
            loc: mean,
            scale: var.sqrt(),
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|v| !v.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Normal::fit: non-finite samples".to_owned(),
            ));
        }
        Ok(Self::fit(data))
    }

    fn entropy(&self) -> f64 {
        0.5 * (2.0 * PI * std::f64::consts::E * self.scale * self.scale).ln()
    }

    fn skewness(&self) -> f64 {
        0.0 // Normal is symmetric
    }

    fn kurtosis(&self) -> f64 {
        0.0 // Normal has excess kurtosis 0 by definition
    }

    fn mode(&self) -> f64 {
        self.loc
    }
}

// ══════════════════════════════════════════════════════════════════════
// Student's t-Distribution
// ══════════════════════════════════════════════════════════════════════

/// Student's t-distribution with `df` degrees of freedom.
///
/// Matches `scipy.stats.t(df)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct StudentT {
    pub df: f64,
}

impl StudentT {
    #[must_use]
    pub fn new(df: f64) -> Self {
        assert!(df > 0.0, "df must be positive, got {df}");
        Self { df }
    }

    /// Density at many points, hoisting the `gamma_ratio_t(df)` coefficient (a
    /// gamma-ratio) out of the per-point loop. Byte-identical to mapping `pdf`
    /// (same `coeff * (...).powf(...)`, coefficient computed once).
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let v = self.df;
        let coeff = gamma_ratio_t(v);
        par_continuous_map_min(xs, 65536, |x| {
            coeff * (1.0 + x * x / v).powf(-0.5 * (v + 1.0))
        })
    }

    /// Log-density at many points; hoists `gamma_ratio_t(df).ln()` like
    /// [`pdf_many`](Self::pdf_many). Byte-identical to mapping `logpdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let v = self.df;
        let log_coeff = gamma_ratio_t(v).ln();
        par_continuous_map_min(xs, 65536, |x| {
            log_coeff - 0.5 * (v + 1.0) * (1.0 + x * x / v).ln()
        })
    }

    /// Cumulative distribution at many points — work-gated parallel map of the per-point
    /// cdf, byte-identical to mapping `cdf`.
    #[must_use]
    pub fn cdf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.cdf(x))
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point
    /// `ppf`, byte-identical to mapping `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.ppf(q))
    }

    /// Survival function at many points — work-gated parallel map of the per-point sf,
    /// byte-identical to mapping `sf`.
    #[must_use]
    pub fn sf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.sf(x))
    }

    /// Inverse survival function at many points — work-gated parallel map of the per-point isf,
    /// byte-identical to mapping `isf`.
    #[must_use]
    pub fn isf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.isf(q))
    }
}

impl ContinuousDistribution for StudentT {
    fn pdf(&self, x: f64) -> f64 {
        let v = self.df;
        let coeff = gamma_ratio_t(v);
        coeff * (1.0 + x * x / v).powf(-0.5 * (v + 1.0))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // log coeff − ½(v+1)·ln(1 + x²/v); finite in the power-law tail where
        // pdf underflows to 0. frankenscipy-p82v7
        let v = self.df;
        gamma_ratio_t(v).ln() - 0.5 * (v + 1.0) * (1.0 + x * x / v).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let v = self.df;
        if x == 0.0 {
            return 0.5;
        }
        // Use regularized incomplete beta function
        let t2 = x * x;
        let w = v / (v + t2);
        let ib = regularized_incomplete_beta(0.5 * v, 0.5, w);
        if x > 0.0 { 1.0 - 0.5 * ib } else { 0.5 * ib }
    }

    fn sf(&self, x: f64) -> f64 {
        let v = self.df;
        if x == 0.0 {
            return 0.5;
        }
        // Use regularized incomplete beta function
        let t2 = x * x;
        let w = v / (v + t2);
        let ib = regularized_incomplete_beta(0.5 * v, 0.5, w);
        if x > 0.0 { 0.5 * ib } else { 1.0 - 0.5 * ib }
    }

    fn logcdf(&self, x: f64) -> f64 {
        let v = self.df;
        if x == 0.0 {
            return -std::f64::consts::LN_2;
        }
        let w = v / (v + x * x);
        if x > 0.0 {
            // cdf = 1 − ½·I_w(v/2,1/2); near 1 → ln1p(−½·I_w).
            (-0.5 * regularized_incomplete_beta(0.5 * v, 0.5, w)).ln_1p()
        } else {
            // cdf = ½·I_w; left tail → −ln2 + log I_w, finite where I underflows.
            -std::f64::consts::LN_2 + fsci_special::log_betainc_scalar(0.5 * v, 0.5, w)
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        let v = self.df;
        if x == 0.0 {
            return -std::f64::consts::LN_2;
        }
        let w = v / (v + x * x);
        if x > 0.0 {
            // sf = ½·I_w; right tail (t-test log p-value) → −ln2 + log I_w.
            -std::f64::consts::LN_2 + fsci_special::log_betainc_scalar(0.5 * v, 0.5, w)
        } else {
            (-0.5 * regularized_incomplete_beta(0.5 * v, 0.5, w)).ln_1p()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        if q == 0.5 {
            return 0.0;
        }
        let v = self.df;
        let (p, sign) = if q < 0.5 {
            (2.0 * q, -1.0)
        } else {
            (2.0 * (1.0 - q), 1.0)
        };
        let w = fsci_special::betaincinv_scalar(0.5 * v, 0.5, p);
        let mut x = sign * (v * (1.0 - w) / w).sqrt();
        // Newton refinement for accuracy
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x -= err / dx;
            }
        }
        x
    }

    fn isf(&self, q: f64) -> f64 {
        // Student's t is symmetric about 0: isf(q)=ppf(1−q)=−ppf(q). For
        // representable 1−q, route through −ppf(q) to avoid the trait default's
        // 1−q cancellation (isf(1e-12) was ~4.4e-6 off scipy). In the ultra-deep
        // tail (q ≲ 1e-16, 1−q underflows to 1.0) ppf's betaincinv seed can't
        // reach, so fall back to direct sf-inversion as the default does.
        // frankenscipy-d2gag
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        if 1.0 - q < 1.0 {
            -self.ppf(q)
        } else {
            isf_bisection(|x| self.sf(x), q, 0.0, 1.0)
        }
    }

    fn mean(&self) -> f64 {
        if self.df > 1.0 { 0.0 } else { f64::NAN }
    }

    fn var(&self) -> f64 {
        if self.df > 2.0 {
            self.df / (self.df - 2.0)
        } else if self.df > 1.0 {
            f64::INFINITY
        } else {
            f64::NAN
        }
    }

    fn entropy(&self) -> f64 {
        // h(T(df)) = (df+1)/2 · (ψ((df+1)/2) − ψ(df/2))
        //          + 0.5 · ln(df) + ln B(df/2, 1/2)
        //          = (df+1)/2 · (ψ((df+1)/2) − ψ(df/2))
        //          + 0.5 · ln(df) + ln Γ(df/2) + 0.5·ln(π) − ln Γ((df+1)/2).
        let df = self.df;
        let half_df = df / 2.0;
        let half_dfp1 = (df + 1.0) / 2.0;
        half_dfp1
            * (fsci_special::digamma_scalar(half_dfp1) - fsci_special::digamma_scalar(half_df))
            + 0.5 * df.ln()
            + ln_gamma(half_df)
            + 0.5 * PI.ln()
            - ln_gamma(half_dfp1)
    }

    fn fit(data: &[f64]) -> Self {
        fn consider_student_t_df(
            best_df: &mut f64,
            best_error: &mut f64,
            observed_ratio: f64,
            df: f64,
        ) {
            let model = StudentT { df };
            let model_q75 = model.ppf(0.75);
            let model_q95 = model.ppf(0.95);
            if !model_q75.is_finite() || !model_q95.is_finite() || model_q75 <= 0.0 {
                return;
            }
            let error = (model_q95 / model_q75 - observed_ratio).abs();
            if error < *best_error {
                *best_error = error;
                *best_df = df;
            }
        }

        if data.is_empty() || data.iter().any(|&x| !x.is_finite()) {
            return Self { df: f64::NAN };
        }

        let qs = quantile(data, &[0.5, 0.75, 0.95]);
        let median = qs[0];
        let upper_quartile = qs[1];
        let upper_tail = qs[2];
        let interquantile = upper_quartile - median;
        let tail_span = upper_tail - median;
        if !interquantile.is_finite()
            || !tail_span.is_finite()
            || interquantile <= 0.0
            || tail_span <= 0.0
        {
            return Self { df: f64::NAN };
        }

        let observed_ratio = tail_span / interquantile;
        let mut best_df = f64::NAN;
        let mut best_error = f64::INFINITY;

        // Match a scale-free upper-tail quantile ratio so arbitrary loc/scale factors cancel out.
        for step in 0..=796 {
            consider_student_t_df(
                &mut best_df,
                &mut best_error,
                observed_ratio,
                1.0 + 0.25 * step as f64,
            );
        }
        for &df in &[250.0, 500.0, 1.0e3, 1.0e4, 1.0e6] {
            consider_student_t_df(&mut best_df, &mut best_error, observed_ratio, df);
        }
        if best_df.is_finite() {
            let start = (best_df - 1.0).max(1.01);
            let end = (best_df + 1.0).min(1.0e6);
            let mut df = start;
            while df <= end {
                consider_student_t_df(&mut best_df, &mut best_error, observed_ratio, df);
                df += 0.01;
            }
        }

        Self {
            df: if best_df.is_finite() && best_df > 0.0 {
                best_df
            } else {
                f64::NAN
            },
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 3 {
            return Err(FitError::InsufficientData {
                required: 3,
                actual: data.len(),
            });
        }
        if let Some(&x) = data.iter().find(|&&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(format!(
                "StudentT fit data contains non-finite value: {x}"
            )));
        }

        let fitted = Self::fit(data);
        if fitted.df.is_finite() && fitted.df > 0.0 {
            Ok(fitted)
        } else {
            Err(FitError::NonConvergent(
                "StudentT fit could not estimate positive degrees of freedom".to_owned(),
            ))
        }
    }

    fn skewness(&self) -> f64 {
        if self.df > 3.0 { 0.0 } else { f64::NAN }
    }

    fn kurtosis(&self) -> f64 {
        if self.df > 4.0 {
            6.0 / (self.df - 4.0)
        } else {
            f64::NAN
        }
    }

    fn mode(&self) -> f64 {
        // StudentT mode = 0 (symmetric around origin) [frankenscipy-71mv5].
        0.0
    }
}

// ══════════════════════════════════════════════════════════════════════
// Non-central t-Distribution
// ══════════════════════════════════════════════════════════════════════

/// Non-central t-distribution.
///
/// Raw moment E[T^k] for NoncentralT(df, nc), valid for df > k:
///   E[T^k] = (df/2)^{k/2} · Γ((df−k)/2)/Γ(df/2) · M_k(nc)
/// where M_k(nc) = E[(Z+nc)^k] = Σ_{j=0..⌊k/2⌋} C(k, 2j)·nc^{k−2j}·(2j)!/(2^j·j!).
/// Returns NaN when df ≤ k.
fn nct_raw_moment(df: f64, nc: f64, k: u32) -> f64 {
    if df <= k as f64 {
        return f64::NAN;
    }
    // (2j)!/(2^j · j!) gives the standard-normal central moment E[Z^{2j}].
    fn double_factorial_quotient(j: u32) -> f64 {
        let mut acc = 1.0_f64;
        for i in 1..=j {
            acc *= (2 * i - 1) as f64;
        }
        acc
    }
    fn binomial_coef(k: u32, m: u32) -> f64 {
        let mut acc = 1.0_f64;
        for i in 0..m {
            acc *= (k - i) as f64 / (i + 1) as f64;
        }
        acc
    }
    let mut m_k = 0.0_f64;
    for j in 0..=(k / 2) {
        let coef = binomial_coef(k, 2 * j);
        let z_moment = double_factorial_quotient(j);
        m_k += coef * nc.powi((k - 2 * j) as i32) * z_moment;
    }
    let log_scale =
        (k as f64 * 0.5) * (df / 2.0).ln() + ln_gamma((df - k as f64) / 2.0) - ln_gamma(df / 2.0);
    log_scale.exp() * m_k
}

/// Matches `scipy.stats.nct(df, nc)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NoncentralT {
    pub df: f64,
    pub nc: f64,
}

impl NoncentralT {
    #[must_use]
    pub fn new(df: f64, nc: f64) -> Self {
        assert!(df > 0.0, "df must be positive, got {df}");
        Self { df, nc }
    }

    /// Upper integration limit S_max for the chi-scaled variable
    /// S = sqrt(W/ν) so that P(S > S_max) is below ~1e-19 for the
    /// supported range of ν. Uses the Cornish-Fisher tail expansion
    /// for χ²(ν) at z = 10 standard deviations beyond the mean.
    fn cdf_pdf_s_max(nu: f64) -> f64 {
        let z_max: f64 = 10.0;
        let w_max = nu + z_max * (2.0 * nu).sqrt() + (z_max * z_max - 1.0) * (2.0 / 3.0);
        (w_max / nu).sqrt()
    }

    /// log of the density of S = sqrt(W/ν) for W ~ χ²(ν).
    fn log_pdf_s(nu: f64, s: f64) -> f64 {
        // pdf_S(s) = ν^(ν/2) · s^(ν-1) · exp(-ν s² / 2) / (2^(ν/2 - 1) · Γ(ν/2))
        let log_norm = (nu / 2.0) * nu.ln() - (nu / 2.0 - 1.0) * 2.0_f64.ln() - ln_gamma(nu / 2.0);
        log_norm + (nu - 1.0) * s.ln() - 0.5 * nu * s * s
    }

    /// CDF via numerical integration over the chi-scaled distribution.
    ///
    /// F_nct(t; ν, μ) = E_W[Φ(t·sqrt(W/ν) - μ)] for W ~ χ²(ν), which after
    /// substituting S = sqrt(W/ν) becomes
    ///   F_nct(t; ν, μ) = ∫_0^∞ Φ(t·s - μ) · pdf_S(s) ds.
    /// Computed via composite Simpson's rule on [0, s_max] where the
    /// chi-scaled tail is below ~1e-19.
    /// RETIRED (frankenscipy-19hon). Superseded by `fsci_special::nctdtr`, which
    /// 3d9c58831 routed the public cdf/sf/ppf to for a measured 9-40x (cdf) and
    /// 38-102x (ppf) self-speedup — same Lenth series, implemented in the special
    /// crate. Kept as the in-crate reference for that series rather than deleted;
    /// it is still reachable from `nct_sf_integrate` below, which is retired for
    /// the same reason.
    #[allow(dead_code)]
    fn nct_cdf_integrate(&self, t: f64) -> f64 {
        if t.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if t.is_infinite() {
            return if t > 0.0 { 1.0 } else { 0.0 };
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).cdf(t);
        }

        let nu = self.df;
        let delta = self.nc;
        // Reflect the left tail: F(t;ν,δ) = 1 − F(−t;ν,−δ).
        if t < 0.0 {
            return 1.0 - NoncentralT::new(nu, -delta).nct_cdf_integrate(-t);
        }
        // Lenth (1989) noncentral-t CDF series (t ≥ 0):
        //   F = Φ(−δ) + ½ Σ_j [ p_j·I_y(j+½, ν/2) + q_j·I_y(j+1, ν/2) ],  y = t²/(t²+ν),
        //   p_j = e^{−δ²/2}(δ²/2)^j / j!,  q_j/q_{j−1} = (δ²/2)/(j+½).
        // Replaces a per-point 2000-panel Simpson quadrature (≈2000 norm.cdf evals/point);
        // verified to 1e-15 vs scipy.stats.nct.cdf over a (ν,δ,t) sweep. frankenscipy-9i8vd
        let y = t * t / (t * t + nu);
        let half = 0.5 * delta * delta;
        let phi_neg_delta = standard_normal_cdf(-delta);
        let mut p = (-half).exp();
        let mut q = (-half).exp() * delta / std::f64::consts::SQRT_2 / ln_gamma(1.5).exp();
        let peak = half.floor().max(0.0);
        let mut series = 0.0;
        let mut j: u64 = 0;
        loop {
            let jf = j as f64;
            series += p * regularized_incomplete_beta(jf + 0.5, 0.5 * nu, y)
                + q * regularized_incomplete_beta(jf + 1.0, 0.5 * nu, y);
            if (jf > peak && (p + q) < 1.0e-18) || j > 100_000 {
                break;
            }
            j += 1;
            let jf2 = j as f64;
            p *= half / jf2;
            q *= half / (jf2 + 0.5);
        }
        (phi_neg_delta + 0.5 * series).clamp(0.0, 1.0)
    }

    /// PDF via the same chi-scaled quadrature.
    ///
    /// pdf_T_nc(x; ν, μ) = ∂/∂x F_nct(x; ν, μ)
    ///                   = ∫_0^∞ s · φ(x·s - μ) · pdf_S(s) ds
    /// where φ is the standard normal pdf.
    fn nct_pdf_integrate(&self, x: f64) -> f64 {
        if x.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if !x.is_finite() {
            return 0.0;
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).pdf(x);
        }

        let nu = self.df;
        let mu = self.nc;

        let s_max = Self::cdf_pdf_s_max(nu);
        let steps = 2000usize;
        let h = s_max / steps as f64;

        let log_phi_const = -0.5 * (2.0 * PI).ln();

        let integrand = |s: f64| -> f64 {
            if s <= 0.0 {
                return 0.0;
            }
            let arg = x * s - mu;
            let log_total = Self::log_pdf_s(nu, s) + log_phi_const - 0.5 * arg * arg + s.ln();
            if log_total < -700.0 {
                return 0.0;
            }
            log_total.exp()
        };

        let mut sum = integrand(0.0) + integrand(s_max);
        for i in 1..steps {
            let s = i as f64 * h;
            let coef = if i % 2 == 0 { 2.0 } else { 4.0 };
            sum += coef * integrand(s);
        }
        (sum * h / 3.0).max(0.0)
    }

    /// log-PDF via a peak-centered (Laplace) Simpson quadrature in log-space.
    ///
    /// The log-integrand `g(s) = log_pdf_S(ν,s) + ln s − ½(x·s−μ)² − ½ln(2π)`
    /// is strictly concave; its peak is the positive root of
    /// `(ν+x²)s² − xμ·s − ν = 0`. For large |x| the peak sits at `s* ∝ 1/x`,
    /// which the fixed `[0, s_max]` grid in `nct_pdf_integrate` cannot resolve
    /// (so the pdf collapses to 0). Centering the grid on `s*` with width set by
    /// the local curvature resolves the peak for any x, and the log-space
    /// (logsumexp) accumulation stays finite where the linear integral
    /// underflows. frankenscipy-7m3xk
    fn nct_logpdf_integrate(&self, x: f64) -> f64 {
        if x.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if !x.is_finite() {
            return f64::NEG_INFINITY;
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).logpdf(x);
        }
        let nu = self.df;
        let mu = self.nc;
        // Peak s* = root of (ν+x²)s² − xμ·s − ν = 0 (the +√ root is positive).
        let aa = nu + x * x;
        let disc = (x * mu * x * mu + 4.0 * aa * nu).sqrt();
        let s_star = (x * mu + disc) / (2.0 * aa);
        // −g''(s*) = ν/s*² + ν + x²; width is one curvature std.
        let width = 1.0 / (nu / (s_star * s_star) + nu + x * x).sqrt();
        let lo = (s_star - 10.0 * width).max(1.0e-12);
        let hi = s_star + 10.0 * width;
        let steps = 1024usize;
        let h = (hi - lo) / steps as f64;
        let log_phi_const = -0.5 * (2.0 * PI).ln();
        let g = |s: f64| -> f64 {
            if s <= 0.0 {
                return f64::NEG_INFINITY;
            }
            let arg = x * s - mu;
            Self::log_pdf_s(nu, s) + s.ln() + log_phi_const - 0.5 * arg * arg
        };
        let mut max = f64::NEG_INFINITY;
        let mut terms: Vec<f64> = Vec::with_capacity(steps + 1);
        for i in 0..=steps {
            let s = lo + i as f64 * h;
            let coef: f64 = if i == 0 || i == steps {
                1.0
            } else if i % 2 == 1 {
                4.0
            } else {
                2.0
            };
            let t = coef.ln() + g(s);
            if t.is_finite() {
                if t > max {
                    max = t;
                }
                terms.push(t);
            }
        }
        if !max.is_finite() {
            return f64::NEG_INFINITY;
        }
        let lse = max + terms.iter().map(|&t| (t - max).exp()).sum::<f64>().ln();
        (h / 3.0).ln() + lse
    }

    /// Survival function via the complementary Lenth (1989) series.
    ///
    /// Applying `I_y(a,b) = 1 − I_{1−y}(b,a)` to the cdf series (see
    /// `nct_cdf_integrate`) gives a directly tail-stable survival series with
    /// no additive Φ term to cancel against:
    ///   sf(t;ν,δ) = ½ Σ_j [ p_j·I_ȳ(ν/2, j+½) + q_j·I_ȳ(ν/2, j+1) ],
    ///   ȳ = ν/(t²+ν),  p_j = e^{−δ²/2}(δ²/2)^j / j!,  q_j/q_{j−1} = (δ²/2)/(j+½).
    /// Each term is a small positive number, so the deep right tail (where the
    /// default `1 − cdf` collapses to 0) stays full-precision. This replaces a
    /// 2000-panel Simpson quadrature (≈2000 erfc evals/point) and was verified
    /// to ~2e-14 abs vs scipy.stats.nct.sf over a (ν,δ,t) sweep incl. the deep
    /// tail. frankenscipy-9i8vd
    /// RETIRED (frankenscipy-19hon). Superseded together with
    /// [`Self::nct_cdf_integrate`] when 3d9c58831 routed the public sf to
    /// `fsci_special::nctdtr` with reflected arguments.
    #[allow(dead_code)]
    fn nct_sf_integrate(&self, t: f64) -> f64 {
        if t.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if t.is_infinite() {
            return if t > 0.0 { 0.0 } else { 1.0 };
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).sf(t);
        }

        let nu = self.df;
        let delta = self.nc;
        // Reflect the left tail: sf(t;ν,δ) = F(−t;ν,−δ) (the well-conditioned
        // cdf series at a positive argument).
        if t < 0.0 {
            return NoncentralT::new(nu, -delta).nct_cdf_integrate(-t);
        }
        let ybar = nu / (t * t + nu);
        let half = 0.5 * delta * delta;
        let mut p = (-half).exp();
        let mut q = (-half).exp() * delta / std::f64::consts::SQRT_2 / ln_gamma(1.5).exp();
        let peak = half.floor().max(0.0);
        let mut series = 0.0;
        let mut j: u64 = 0;
        loop {
            let jf = j as f64;
            series += p * regularized_incomplete_beta(0.5 * nu, jf + 0.5, ybar)
                + q * regularized_incomplete_beta(0.5 * nu, jf + 1.0, ybar);
            if (jf > peak && (p + q) < 1.0e-18) || j > 100_000 {
                break;
            }
            j += 1;
            let jf2 = j as f64;
            p *= half / jf2;
            q *= half / (jf2 + 0.5);
        }
        (0.5 * series).clamp(0.0, 1.0)
    }
}

impl ContinuousDistribution for NoncentralT {
    fn pdf(&self, x: f64) -> f64 {
        self.nct_pdf_integrate(x)
    }

    fn logpdf(&self, x: f64) -> f64 {
        self.nct_logpdf_integrate(x)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if x.is_infinite() {
            return if x > 0.0 { 1.0 } else { 0.0 };
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).cdf(x);
        }
        // Delegate to the special kernel `nctdtr` (same Lenth series, in
        // fsci-special) — ~9-40× faster than this crate's local reimplementation,
        // agreeing to ≤3.4e-15 (machine precision).
        fsci_special::nctdtr(self.df, self.nc, x).clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        if x.is_nan() || self.nc.is_nan() || self.df.is_nan() {
            return f64::NAN;
        }
        if x.is_infinite() {
            return if x > 0.0 { 0.0 } else { 1.0 };
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).sf(x);
        }
        // sf(t; ν, δ) = 1 − F(t) = F(−t; ν, −δ) (noncentral-t reflection), so
        // evaluate the tail DIRECTLY via `nctdtr` with reflected args — fast and
        // cancellation-free (no 1 − cdf), matching the former local tail integrate.
        fsci_special::nctdtr(self.df, -self.nc, -x).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if q.is_nan() || !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        if self.nc.abs() < 1e-10 {
            return StudentT::new(self.df).ppf(q);
        }

        // Invert via `nctdtrit` (Illinois over nctdtr) — ~37-100× faster than the
        // local bracket-bisection over the Lenth cdf. Round-trip guard falls back
        // to the bisection below on any drift (no regression, no correctness risk).
        let x_fast = fsci_special::nctdtrit(self.df, self.nc, q);
        if x_fast.is_finite() && (self.cdf(x_fast) - q).abs() < 1e-6 {
            return x_fast;
        }

        let nu = self.df;
        let mu = self.nc;

        // Initial bracket centred on (central StudentT.ppf shifted by the
        // approximate location of nct), with width ≈ 6 · approximate std.
        let central_ppf = StudentT::new(nu).ppf(q);
        let approx_loc = if nu > 1.0 {
            mu * (nu / 2.0).sqrt() * (ln_gamma((nu - 1.0) / 2.0) - ln_gamma(nu / 2.0)).exp()
        } else {
            mu
        };
        let approx_var = if nu > 2.0 {
            nu * (1.0 + mu * mu) / (nu - 2.0) - approx_loc * approx_loc
        } else {
            nu + mu * mu + 1.0
        };
        let scale = approx_var.abs().sqrt().max(1.0);

        let mut lo = central_ppf + approx_loc - 6.0 * scale;
        let mut hi = central_ppf + approx_loc + 6.0 * scale;

        // Expand bracket until cdf(lo) ≤ q ≤ cdf(hi).
        for _ in 0..40 {
            let cdf_lo = self.cdf(lo);
            let cdf_hi = self.cdf(hi);
            if cdf_lo <= q && cdf_hi >= q {
                break;
            }
            if cdf_lo > q {
                lo -= 4.0 * scale;
            }
            if cdf_hi < q {
                hi += 4.0 * scale;
            }
        }

        // Bisection. Converge on the BRACKET WIDTH, not |cdf−q|: an absolute cdf
        // tolerance (the old 1e-10) is the same order as q itself for extreme
        // quantiles, so it returned the first mid with cdf<2·q — far out in the
        // tail — instead of the crossing point (nct(10,5).ppf(1e-10) gave −12.96
        // vs −1.81). frankenscipy-ybqjc
        for _ in 0..120 {
            let mid = 0.5 * (lo + hi);
            if (hi - lo).abs() <= 1e-13 * mid.abs().max(1.0) {
                return mid;
            }
            if self.cdf(mid) < q {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        0.5 * (lo + hi)
    }

    fn mean(&self) -> f64 {
        if self.df > 1.0 {
            self.nc * (self.df / 2.0).sqrt() * ln_gamma((self.df - 1.0) / 2.0).exp()
                / ln_gamma(self.df / 2.0).exp()
        } else {
            f64::NAN
        }
    }

    fn var(&self) -> f64 {
        if self.df > 2.0 {
            let mu = self.mean();
            self.df * (1.0 + self.nc * self.nc) / (self.df - 2.0) - mu * mu
        } else {
            f64::NAN
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 3, "NoncentralT")?;
        let mean = sample_mean(data);
        let var = sample_population_variance(data);
        if !var.is_finite() || var <= 0.0 {
            return Err(FitError::NonConvergent(
                "NoncentralT fit needs positive sample variance".to_owned(),
            ));
        }

        let mut best = None::<(f64, f64, f64)>;
        for step in 0..=1980 {
            let df = 2.05 + 0.1 * step as f64;
            let log_a = 0.5 * (df / 2.0).ln() + ln_gamma((df - 1.0) / 2.0) - ln_gamma(df / 2.0);
            let a = log_a.exp();
            if !a.is_finite() || a <= 0.0 {
                continue;
            }
            let nc = mean / a;
            let candidate = Self { df, nc };
            let model_var = candidate.var();
            if !model_var.is_finite() || model_var <= 0.0 {
                continue;
            }
            let error = ((model_var / var).ln()).abs();
            if best.is_none_or(|(_, _, best_error)| error < best_error) {
                best = Some((df, nc, error));
            }
        }

        if let Some((df, nc, _)) = best {
            Ok(Self { df, nc })
        } else {
            Err(FitError::NonConvergent(
                "NoncentralT moment fit did not find finite df/nc".to_owned(),
            ))
        }
    }

    fn skewness(&self) -> f64 {
        // Closed-form raw-moment derivation (frankenscipy-4tew7):
        //   E[T^k] = (df/2)^{k/2} · Γ((df−k)/2)/Γ(df/2) · E[(Z+nc)^k]
        // with E[(Z+nc)^k] = Σ_{j=0..⌊k/2⌋} C(k, 2j)·nc^{k−2j}·(2j)!/(2^j·j!).
        // Skew requires df > 3 (else third raw moment diverges).
        if self.df <= 3.0 {
            return f64::NAN;
        }
        let m1 = nct_raw_moment(self.df, self.nc, 1);
        let m2 = nct_raw_moment(self.df, self.nc, 2);
        let m3 = nct_raw_moment(self.df, self.nc, 3);
        let var = m2 - m1 * m1;
        if !(var > 0.0 && var.is_finite()) {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis. Requires df > 4 (fourth raw moment).
        if self.df <= 4.0 {
            return f64::NAN;
        }
        let m1 = nct_raw_moment(self.df, self.nc, 1);
        let m2 = nct_raw_moment(self.df, self.nc, 2);
        let m3 = nct_raw_moment(self.df, self.nc, 3);
        let m4 = nct_raw_moment(self.df, self.nc, 4);
        let var = m2 - m1 * m1;
        if !(var > 0.0 && var.is_finite()) {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Non-central T has Student-t-like tails (1/x^{df+1}); arctan
        // compactify to keep the integrand bounded on both sides.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            -PI / 2.0 + 1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

// ══════════════════════════════════════════════════════════════════════
// Chi-Squared Distribution
// ══════════════════════════════════════════════════════════════════════

/// Chi-squared distribution with `df` degrees of freedom.
///
/// Matches `scipy.stats.chi2(df)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ChiSquared {
    pub df: f64,
}

impl ChiSquared {
    #[must_use]
    pub fn new(df: f64) -> Self {
        assert!(df > 0.0, "df must be positive, got {df}");
        Self { df }
    }

    /// Log-density at many points, hoisting `ln_gamma(df/2)` and `(df/2)·ln(2)` out
    /// of the per-point loop. Byte-identical to mapping `logpdf`: the normalizer
    /// terms stay as SEPARATE subtractions (a − b − c ≠ a − (b+c) in f64), matching
    /// the arithmetic order exactly; the x<0 / x==0 special cases are preserved.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k2 = 0.5 * self.df;
        let k2_ln2 = k2 * 2.0_f64.ln();
        let lg = ln_gamma(k2);
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return f64::NEG_INFINITY;
            }
            if x == 0.0 {
                return if self.df == 2.0 {
                    0.5_f64.ln()
                } else if self.df > 2.0 {
                    f64::NEG_INFINITY
                } else {
                    f64::INFINITY
                };
            }
            (k2 - 1.0) * x.ln() - 0.5 * x - k2_ln2 - lg
        })
    }

    /// Density at many points; hoists `ln_gamma(df/2)` like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k2 = 0.5 * self.df;
        let k2_ln2 = k2 * 2.0_f64.ln();
        let lg = ln_gamma(k2);
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            if x == 0.0 {
                return if self.df == 2.0 {
                    0.5
                } else if self.df > 2.0 {
                    0.0
                } else {
                    f64::INFINITY
                };
            }
            ((k2 - 1.0) * x.ln() - 0.5 * x - k2_ln2 - lg).exp()
        })
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point
    /// `ppf`, byte-identical to mapping `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.ppf(q))
    }

    /// Survival function at many points — work-gated parallel map of the per-point sf,
    /// byte-identical to mapping `sf`.
    #[must_use]
    pub fn sf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.sf(x))
    }

    /// Inverse survival function at many points — work-gated parallel map of the per-point isf,
    /// byte-identical to mapping `isf`.
    #[must_use]
    pub fn isf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.isf(q))
    }
}

impl ContinuousDistribution for ChiSquared {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.df == 2.0 {
                0.5
            } else if self.df > 2.0 {
                0.0
            } else {
                f64::INFINITY
            };
        }
        let k2 = 0.5 * self.df;
        let ln_pdf = (k2 - 1.0) * x.ln() - 0.5 * x - k2 * 2.0_f64.ln() - ln_gamma(k2);
        ln_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // log of the chi-squared density; finite in the tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let k2 = 0.5 * self.df;
        if x == 0.0 {
            return if self.df == 2.0 {
                0.5_f64.ln()
            } else if self.df > 2.0 {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            };
        }
        (k2 - 1.0) * x.ln() - 0.5 * x - k2 * 2.0_f64.ln() - ln_gamma(k2)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // CDF of chi2(k) = regularized lower incomplete gamma P(k/2, x/2)
        lower_regularized_gamma(0.5 * self.df, 0.5 * x)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log P(k/2, x/2); finite in the left tail where P underflows. frankenscipy-s14mf
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_gammainc_scalar(0.5 * self.df, 0.5 * x)
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(0.5 * self.df, 0.5 * x)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let mut x = 2.0 * fsci_special::gammaincinv_scalar(0.5 * self.df, q);
        // Fall back to bisection if gammaincinv gave a degenerate result
        if x <= 0.0 || !x.is_finite() || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // scipy.stats.chi2.isf via gammainccinv(k/2, q) (upper-tail inverse),
        // well-conditioned for small q; the trait-default ppf(1-q) route lost
        // precision in the right tail (isf(1e-12) ~1.7e-5 off). frankenscipy-d2gag
        let mut x = 2.0 * fsci_special::gammainccinv_scalar(0.5 * self.df, q);
        if x <= 0.0 || !x.is_finite() || (self.sf(x) - q).abs() > 0.1 {
            return isf_bisection(|v| self.sf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.sf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x + err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        self.df
    }

    fn var(&self) -> f64 {
        2.0 * self.df
    }

    fn entropy(&self) -> f64 {
        // h(χ²(k)) = k/2 + ln(2·Γ(k/2)) + (1 − k/2)·ψ(k/2).
        let half_k = self.df / 2.0;
        half_k
            + 2.0_f64.ln()
            + ln_gamma(half_k)
            + (1.0 - half_k) * fsci_special::digamma_scalar(half_k)
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self { df: f64::NAN };
        }

        let mean = data.iter().sum::<f64>() / data.len() as f64;
        if !mean.is_finite() || mean <= 0.0 {
            return Self { df: f64::NAN };
        }

        Self { df: mean }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if let Some(&x) = data.iter().find(|&&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(format!(
                "ChiSquared fit data contains non-finite value: {x}"
            )));
        }
        if let Some(&x) = data.iter().find(|&&x| x < 0.0) {
            return Err(FitError::UnsupportedData(format!(
                "ChiSquared support is [0, infinity); got {x}"
            )));
        }

        let fitted = Self::fit(data);
        if fitted.df.is_finite() && fitted.df > 0.0 {
            Ok(fitted)
        } else {
            Err(FitError::NonConvergent(
                "ChiSquared fit produced non-positive degrees of freedom".to_owned(),
            ))
        }
    }

    fn skewness(&self) -> f64 {
        (8.0 / self.df).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        12.0 / self.df
    }

    fn mode(&self) -> f64 {
        // ChiSquared mode = max(df - 2, 0) [frankenscipy-cxgdg].
        (self.df - 2.0).max(0.0)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Non-central Chi-Squared Distribution
// ══════════════════════════════════════════════════════════════════════

/// Non-central chi-squared distribution with `df` degrees of freedom
/// and non-centrality parameter `nc`.
///
/// Matches `scipy.stats.ncx2(df, nc)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NoncentralChiSquared {
    pub df: f64,
    pub nc: f64,
}

impl NoncentralChiSquared {
    #[must_use]
    pub fn new(df: f64, nc: f64) -> Self {
        assert!(df > 0.0, "df must be positive, got {df}");
        assert!(nc >= 0.0, "nc must be non-negative, got {nc}");
        Self { df, nc }
    }
}

impl ContinuousDistribution for NoncentralChiSquared {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 || x.is_nan() {
            return if x.is_nan() { f64::NAN } else { 0.0 };
        }
        if self.nc == 0.0 {
            return ChiSquared::new(self.df).pdf(x);
        }
        if x == 0.0 {
            return if self.df >= 2.0 { 0.0 } else { f64::INFINITY };
        }

        // PDF: 0.5 * exp(-(x+λ)/2) * (x/λ)^((k/4)-(1/2)) * I_{k/2-1}(sqrt(λx))
        let k = self.df;
        let lam = self.nc;

        let nu = k / 2.0 - 1.0;
        let sqrt_lam_x = (lam * x).sqrt();

        // Use ive_scalar and convert: I_v(z) = ive(v, z) * exp(|z|)
        let ive_val = fsci_special::ive_scalar(nu, sqrt_lam_x);
        let iv_val = ive_val * sqrt_lam_x.abs().exp();

        if iv_val <= 0.0 || !iv_val.is_finite() {
            return 0.0;
        }

        let log_pdf = -(x + lam) / 2.0 + ((k / 4.0) - 0.5) * (x / lam).ln() + iv_val.ln() - LN_2;

        log_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // Pure log-space form: ln I_ν(z) = ln(ive(ν,z)) + z (z≥0), avoiding the
        // I_ν overflow that makes pdf() collapse to 0 for large λx. Finite deep
        // in the tail where the density underflows. frankenscipy-7m3xk
        if x < 0.0 || x.is_nan() {
            return if x.is_nan() {
                f64::NAN
            } else {
                f64::NEG_INFINITY
            };
        }
        if self.nc == 0.0 {
            return ChiSquared::new(self.df).logpdf(x);
        }
        if x == 0.0 {
            return if self.df >= 2.0 {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            };
        }
        let k = self.df;
        let lam = self.nc;
        let nu = k / 2.0 - 1.0;
        let sqrt_lam_x = (lam * x).sqrt();
        // ln I_ν(z) = log_ive(ν, z) + z; stays finite for all z (vs the pdf's
        // I_ν = ive·e^z which overflows for z > 709).
        let log_iv = fsci_special::log_ive_scalar(nu, sqrt_lam_x) + sqrt_lam_x;
        if !log_iv.is_finite() {
            return f64::NEG_INFINITY;
        }
        -(x + lam) / 2.0 + ((k / 4.0) - 0.5) * (x / lam).ln() + log_iv - LN_2
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x.is_nan() {
            return f64::NAN;
        }
        if self.nc == 0.0 {
            return ChiSquared::new(self.df).cdf(x);
        }

        // Delegate the noncentral χ² CDF to the recurrence-optimized special
        // kernel: `chndtr` sums the Poisson-mixture with one incomplete-gamma at
        // the mode + O(√nc) recurrence steps, vs this crate's former window of
        // ~O(√nc) fresh `lower_regularized_gamma` calls. Measured 16.7–39.5×
        // faster, agreeing to ≤3e-14 (machine precision) with the old window sum.
        fsci_special::gamma::chndtr(x, self.df, self.nc).clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        // Survival computed DIRECTLY, never as 1 − cdf. The cdf saturates to 1.0
        // in the right tail, where the subtraction returns exactly 0 while
        // scipy.stats.ncx2.sf(150, 3, 2) = 1.0449270275534266e-26 — and it is
        // already wrong in the 4th digit by x = 80. `chndtrc` walks the same
        // Poisson mixture as `chndtr` with the UPPER incomplete gamma; the stable
        // recurrence direction reverses between the two. frankenscipy-wofb.
        if x.is_nan() {
            return f64::NAN;
        }
        if x <= 0.0 {
            return 1.0;
        }
        if self.nc == 0.0 {
            return ChiSquared::new(self.df).sf(x);
        }
        fsci_special::gamma::chndtrc(x, self.df, self.nc).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        // Invert the noncentral χ² CDF directly with the purpose-built `chndtrix`
        // (recurrence-optimized `chndtr` kernel + Illinois — much cheaper than
        // bisecting this crate's local Poisson-sum cdf ~40×). Guard with a
        // round-trip check against the local cdf so any parametrization drift
        // falls back to the exact bisection (no regression, no correctness risk).
        let x = fsci_special::chndtrix(q, self.df, self.nc);
        if x.is_finite() && x > 0.0 && (self.cdf(x) - q).abs() < 1e-6 {
            return x;
        }
        ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std())
    }

    fn mean(&self) -> f64 {
        self.df + self.nc
    }

    fn var(&self) -> f64 {
        2.0 * (self.df + 2.0 * self.nc)
    }

    fn entropy(&self) -> f64 {
        // No closed form; scipy evaluates it numerically. h = −∫ pdf·ln pdf dx
        // over the bulk (mean + ~14σ captures the tail; the integrable x→0
        // behaviour for df<2 is handled by the adaptive refinement from a small
        // lower bound). Matches scipy to ~1e-8. frankenscipy-8qidg
        let mean = self.df + self.nc;
        let std = (2.0 * (self.df + 2.0 * self.nc)).sqrt();
        let hi = mean + 14.0 * std;
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            hi,
            4_096,
            1e-12,
            1e-12,
            12,
        )
    }

    fn fit(_data: &[f64]) -> Self {
        Self {
            df: f64::NAN,
            nc: f64::NAN,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Method-of-moments fit (consistent with the crate's pragmatic per-
        // distribution estimators). For NCS: E[X] = df + nc and
        // Var[X] = 2(df + 2*nc), which invert in closed form to
        //   nc = var/2 - mean,  df = 2*mean - var/2.
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let n = data.len() as f64;
        let mut sum = 0.0;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "NoncentralChiSquared data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "NoncentralChiSquared support is [0, ∞); got {x}"
                )));
            }
            sum += x;
        }
        let mean = sum / n;
        let var = data.iter().map(|&x| (x - mean) * (x - mean)).sum::<f64>() / n;
        let nc = var / 2.0 - mean;
        let df = 2.0 * mean - var / 2.0;
        if !df.is_finite() || df <= 0.0 || !nc.is_finite() || nc < 0.0 {
            return Err(FitError::NonConvergent(format!(
                "NoncentralChiSquared MoM produced invalid parameters: df={df}, nc={nc}"
            )));
        }
        Ok(Self { df, nc })
    }

    fn skewness(&self) -> f64 {
        // scipy: γ₁ = 2^{3/2}·(k + 3λ)/(k + 2λ)^{3/2}. The old
        // √(8(k+3λ))/(k+2λ) square-rooted (k+3λ) and used the wrong denominator
        // power, leaving skew(4,2) at 1.118 vs scipy 1.25. frankenscipy-8qidg
        let k = self.df;
        let lam = self.nc;
        2.0_f64.powf(1.5) * (k + 3.0 * lam) / (k + 2.0 * lam).powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let k = self.df;
        let lam = self.nc;
        12.0 * (k + 4.0 * lam) / ((k + 2.0 * lam).powi(2))
    }

    fn mode(&self) -> f64 {
        // Approximate: df + nc - 2 for large df
        (self.df + self.nc - 2.0).max(0.0)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Uniform Distribution
// ══════════════════════════════════════════════════════════════════════

/// Uniform distribution on [loc, loc + scale].
///
/// Matches `scipy.stats.uniform(loc, scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Uniform {
    pub loc: f64,
    pub scale: f64,
}

impl Default for Uniform {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl Uniform {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for Uniform {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x >= self.loc && x <= self.loc + self.scale {
            1.0 / self.scale
        } else {
            0.0
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −ln(scale) on support, −inf outside. frankenscipy-p82v7
        if x >= self.loc && x <= self.loc + self.scale {
            -self.scale.ln()
        } else {
            f64::NEG_INFINITY
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < self.loc {
            0.0
        } else if x > self.loc + self.scale {
            1.0
        } else {
            (x - self.loc) / self.scale
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.loc;
        }
        if q == 1.0 {
            return self.loc + self.scale;
        }
        self.loc + q * self.scale
    }

    fn mean(&self) -> f64 {
        self.loc + 0.5 * self.scale
    }

    fn var(&self) -> f64 {
        self.scale * self.scale / 12.0
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;
        for &x in data {
            if x < min {
                min = x;
            }
            if x > max {
                max = x;
            }
        }
        Self {
            loc: min,
            scale: max - min,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|v| !v.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Uniform::fit: non-finite samples".to_owned(),
            ));
        }
        Ok(Self::fit(data))
    }

    fn entropy(&self) -> f64 {
        self.scale.ln()
    }

    fn skewness(&self) -> f64 {
        0.0 // Uniform is symmetric
    }

    fn kurtosis(&self) -> f64 {
        -1.2 // Uniform excess kurtosis = -6/5
    }
}

// ══════════════════════════════════════════════════════════════════════
// Exponential Distribution
// ══════════════════════════════════════════════════════════════════════

/// Exponential distribution with rate parameter `lambda` (= 1/scale).
///
/// Matches `scipy.stats.expon(scale=1/lambda)`.
/// The PDF is: f(x) = lambda * exp(-lambda * x) for x >= 0.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Exponential {
    pub lambda: f64,
}

impl Default for Exponential {
    fn default() -> Self {
        Self { lambda: 1.0 }
    }
}

impl Exponential {
    #[must_use]
    pub fn new(lambda: f64) -> Self {
        assert!(lambda > 0.0, "lambda must be positive, got {lambda}");
        Self { lambda }
    }

    /// Create from scale parameter (= 1/lambda), matching SciPy convention.
    #[must_use]
    pub fn from_scale(scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self {
            lambda: 1.0 / scale,
        }
    }

    /// Percent point function (inverse CDF).
    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // ln(1 - q) via ln_1p(-q) keeps full precision for small q; the naive
        // (1.0 - q).ln() cancels (ppf(1e-12) gave 9.99978e-13 vs scipy 1e-12).
        -(-q).ln_1p() / self.lambda
    }
}

impl ContinuousDistribution for Exponential {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            self.lambda * (-self.lambda * x).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // log λ − λx; finite in the tail where pdf underflows to 0. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        self.lambda.ln() - self.lambda * x
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            -(-self.lambda * x).exp_m1()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        if x < 0.0 {
            1.0
        } else {
            (-self.lambda * x).exp()
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // logsf = -lambda*x; the default ln(sf) underflows to -inf once sf -> 0
        // (expon.logsf(1000)=-inf vs scipy -1000).
        if x < 0.0 { 0.0 } else { -self.lambda * x }
    }

    fn ppf(&self, q: f64) -> f64 {
        Exponential::ppf(self, q)
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // sf(x)=exp(−λx)=q ⇒ x=−ln(q)/λ. The trait default ppf(1−q) recomputes
        // 1−(1−q) and cancels for small q (isf(1e-12) was ~8e-7 off scipy).
        // frankenscipy-d2gag
        -q.ln() / self.lambda
    }

    fn mean(&self) -> f64 {
        1.0 / self.lambda
    }

    fn var(&self) -> f64 {
        1.0 / (self.lambda * self.lambda)
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self { lambda: f64::NAN };
        }

        let mean = data.iter().sum::<f64>() / data.len() as f64;
        if !mean.is_finite() {
            return Self { lambda: f64::NAN };
        }
        if mean == 0.0 {
            return Self {
                lambda: f64::INFINITY,
            };
        }

        Self { lambda: 1.0 / mean }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Exponential::fit: non-finite samples".to_owned(),
            ));
        }
        if data.iter().any(|&x| x < 0.0) {
            return Err(FitError::UnsupportedData(
                "Exponential::fit: negative sample (support is x >= 0)".to_owned(),
            ));
        }
        Ok(Self::fit(data))
    }

    fn entropy(&self) -> f64 {
        1.0 - self.lambda.ln()
    }

    fn skewness(&self) -> f64 {
        2.0 // Exponential always has skewness 2
    }

    fn kurtosis(&self) -> f64 {
        6.0 // Exponential excess kurtosis is always 6
    }

    fn mode(&self) -> f64 {
        0.0
    }
}

// ══════════════════════════════════════════════════════════════════════
// Generalized Exponential Distribution
// ══════════════════════════════════════════════════════════════════════

/// Generalized exponential distribution.
///
/// Matches `scipy.stats.genexpon(a, b, c)`.
/// PDF: f(x) = (a + b*(1 - exp(-c*x))) * exp(-a*x - b*x + (b/c)*(1-exp(-c*x)))
/// for x >= 0, a > 0, b > 0, c > 0.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GeneralizedExponential {
    pub a: f64,
    pub b: f64,
    pub c: f64,
}

impl GeneralizedExponential {
    #[must_use]
    pub fn new(a: f64, b: f64, c: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(b > 0.0, "b must be positive, got {b}");
        assert!(c > 0.0, "c must be positive, got {c}");
        Self { a, b, c }
    }

    /// Raw moment E[Xᵏ] = ∫₀^∞ xᵏ f(x) dx by adaptive quadrature. The pdf decays
    /// at rate a+b in the tail, so a window of ~50 e-foldings captures it.
    fn raw_moment(&self, k: u32) -> f64 {
        let w = (50.0 / (self.a + self.b)).clamp(5.0, 1.0e4);
        simpson_integrate_adaptive(
            |x| x.powi(k as i32) * self.pdf(x),
            0.0,
            w,
            256,
            1e-12,
            1e-15,
            18,
        )
    }
}

impl ContinuousDistribution for GeneralizedExponential {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let ecx = (-self.c * x).exp();
        let term1 = self.a + self.b * (1.0 - ecx);
        let exponent = -self.a * x - self.b * x + (self.b / self.c) * (1.0 - ecx);
        term1 * exponent.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(a + b(1−e^{−cx})) + exponent; the prefactor is O(1), exponent
        // carries the tail decay, so logpdf stays finite. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let ecx = (-self.c * x).exp();
        let term1 = self.a + self.b * (1.0 - ecx);
        let exponent = -self.a * x - self.b * x + (self.b / self.c) * (1.0 - ecx);
        term1.ln() + exponent
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let ecx = (-self.c * x).exp();
        let exponent = -self.a * x - self.b * x + (self.b / self.c) * (1.0 - ecx);
        1.0 - exponent.exp()
    }

    fn sf(&self, x: f64) -> f64 {
        // cdf = 1 − e^{exponent}, so sf = e^{exponent} directly — keeps the right
        // tail accurate where the default 1−cdf collapses to 0. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let ecx = (-self.c * x).exp();
        let exponent = -self.a * x - self.b * x + (self.b / self.c) * (1.0 - ecx);
        exponent.exp()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let target = 1.0 - q;
        let lo = 0.0_f64;
        let mut hi = 100.0_f64;
        let mut fhi = target - self.sf(hi);
        while fhi < 0.0 && hi < 1e10 {
            hi *= 2.0;
            fhi = target - self.sf(hi);
        }
        // sf is monotone DECREASING, so g(x) = (1−q) − sf(x) is increasing with
        // g(0) = −q < 0 ≤ fhi (sf(0) = 1). Keeping the sf form (not cdf−q) stays
        // tail-accurate for q→1. Illinois converges in ~12 evals vs the former
        // fixed 60 bisection steps of this repeated exp kernel.
        illinois_root_increasing(|x| target - self.sf(x), lo, hi, -q, fhi)
    }

    fn mean(&self) -> f64 {
        self.raw_moment(1)
    }

    fn var(&self) -> f64 {
        let m1 = self.raw_moment(1);
        self.raw_moment(2) - m1 * m1
    }

    fn fit(_data: &[f64]) -> Self {
        Self {
            a: f64::NAN,
            b: f64::NAN,
            c: f64::NAN,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Maximum-likelihood fit (standardized genexpon, loc=0/scale=1) via
        // multi-start Nelder-Mead over (ln a, ln b, ln c); matches
        // scipy.stats.genexpon.fit(.., floc=0, fscale=1). The likelihood is
        // bounded but flat in the b/c ridge (the fit is weakly identifiable, as
        // in scipy), so b is capped to keep the pdf in its numerically-accurate
        // regime; the likelihood-optimality of the result is what's verified.
        if data.len() < 3 {
            return Err(FitError::InsufficientData {
                required: 3,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "GeneralizedExponential data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "GeneralizedExponential support is [0, ∞); got {x}"
                )));
            }
        }
        let owned: Vec<f64> = data.to_vec();
        let nll = |p: &[f64]| -> f64 {
            let (a, b, c) = (p[0].exp(), p[1].exp(), p[2].exp());
            // Cap b to the numerically-accurate regime (the ridge extends to
            // b->inf with the same likelihood; large b loses precision in the
            // cancelling exp argument).
            if !a.is_finite() || !b.is_finite() || !c.is_finite() || b > 1.0e3 {
                return f64::INFINITY;
            }
            let dist = GeneralizedExponential { a, b, c };
            let mut total = 0.0;
            for &x in &owned {
                let d = dist.pdf(x);
                if d <= 0.0 || !d.is_finite() {
                    return f64::INFINITY;
                }
                total -= d.ln();
            }
            total
        };
        let starts = [
            [2.0_f64, 3.0, 1.5],
            [3.0, 50.0, 0.006],
            [1.0, 10.0, 0.1],
            [4.0, 1.0, 1.0],
        ];
        let mut best: Option<(f64, [f64; 3])> = None;
        for s in &starts {
            let x0 = [s[0].ln(), s[1].ln(), s[2].ln()];
            let opts = fsci_opt::MinimizeOptions {
                maxiter: Some(3000),
                maxfev: Some(6000),
                tol: Some(1e-10),
                ..Default::default()
            };
            if let Ok(res) = fsci_opt::nelder_mead(&nll, &x0, opts)
                && let Some(f) = res.fun
                && f.is_finite()
                && best.as_ref().is_none_or(|(bf, _)| f < *bf)
            {
                best = Some((f, [res.x[0].exp(), res.x[1].exp(), res.x[2].exp()]));
            }
        }
        match best {
            Some((_, p))
                if p[0] > 0.0 && p[1] > 0.0 && p[2] > 0.0 && p.iter().all(|v| v.is_finite()) =>
            {
                Ok(Self {
                    a: p[0],
                    b: p[1],
                    c: p[2],
                })
            }
            _ => Err(FitError::NonConvergent(
                "GeneralizedExponential MLE failed to converge".to_owned(),
            )),
        }
    }

    fn entropy(&self) -> f64 {
        // h = −∫ f ln f over [0, ∞); no closed form (scipy genexpon integrates
        // too). Use logpdf for the −f·ln f integrand so it stays valid in the tail.
        let w = (50.0 / (self.a + self.b)).clamp(5.0, 1.0e4);
        simpson_integrate_adaptive(
            |x| {
                let f = self.pdf(x);
                if f > 0.0 { -f * self.logpdf(x) } else { 0.0 }
            },
            0.0,
            w,
            256,
            1e-12,
            1e-15,
            18,
        )
    }

    fn skewness(&self) -> f64 {
        // μ₃/μ₂^{3/2} from the raw moments about the mean.
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let var = m2 - m1 * m1;
        let mu3 = m3 - 3.0 * m1 * m2 + 2.0 * m1 * m1 * m1;
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis μ₄/μ₂² − 3 from the raw moments about the mean.
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let m4 = self.raw_moment(4);
        let var = m2 - m1 * m1;
        let mu4 = m4 - 4.0 * m1 * m3 + 6.0 * m1 * m1 * m2 - 3.0 * m1 * m1 * m1 * m1;
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        0.0
    }
}

// ══════════════════════════════════════════════════════════════════════
// F-Distribution
// ══════════════════════════════════════════════════════════════════════

/// F-distribution with `dfn` (numerator) and `dfd` (denominator) degrees of freedom.
///
/// Matches `scipy.stats.f(dfn, dfd)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FDistribution {
    pub dfn: f64,
    pub dfd: f64,
}

impl FDistribution {
    #[must_use]
    pub fn new(dfn: f64, dfd: f64) -> Self {
        assert!(dfn > 0.0, "dfn must be positive, got {dfn}");
        assert!(dfd > 0.0, "dfd must be positive, got {dfd}");
        Self { dfn, dfd }
    }

    /// Log-density at many points, hoisting the constant `0.5·d1·ln(d1/d2)` lead
    /// term and the `ln_beta(d1/2, d2/2)` normalizer (three lgamma evals) out of the
    /// per-point loop. Byte-identical to mapping `logpdf`: the lead term is kept as
    /// the FIRST addend and `ln_beta` as the LAST subtraction, matching the
    /// arithmetic order exactly; x≤0 delegates to `pdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let d1 = self.dfn;
        let d2 = self.dfd;
        let lead = 0.5 * d1 * (d1 / d2).ln();
        let lb = ln_beta(0.5 * d1, 0.5 * d2);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return self.pdf(x).ln();
            }
            lead + (0.5 * d1 - 1.0) * x.ln() - 0.5 * (d1 + d2) * (1.0 + d1 * x / d2).ln() - lb
        })
    }

    /// Density at many points; hoists the lead term and `ln_beta` like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let d1 = self.dfn;
        let d2 = self.dfd;
        let lead = 0.5 * d1 * (d1 / d2).ln();
        let lb = ln_beta(0.5 * d1, 0.5 * d2);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return 0.0;
            }
            (lead + (0.5 * d1 - 1.0) * x.ln() - 0.5 * (d1 + d2) * (1.0 + d1 * x / d2).ln() - lb)
                .exp()
        })
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point
    /// `ppf`, byte-identical to mapping `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.ppf(q))
    }

    /// Survival function at many points — work-gated parallel map of the per-point sf,
    /// byte-identical to mapping `sf`.
    #[must_use]
    pub fn sf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.sf(x))
    }

    /// Inverse survival function at many points — work-gated parallel map of the per-point isf,
    /// byte-identical to mapping `isf`.
    #[must_use]
    pub fn isf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.isf(q))
    }
}

impl ContinuousDistribution for FDistribution {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let ln_pdf = 0.5 * d1 * (d1 / d2).ln() + (0.5 * d1 - 1.0) * x.ln()
            - 0.5 * (d1 + d2) * (1.0 + d1 * x / d2).ln()
            - ln_beta(0.5 * d1, 0.5 * d2);
        ln_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // log of the F density; finite in the tail where pdf underflows. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        0.5 * d1 * (d1 / d2).ln() + (0.5 * d1 - 1.0) * x.ln()
            - 0.5 * (d1 + d2) * (1.0 + d1 * x / d2).ln()
            - ln_beta(0.5 * d1, 0.5 * d2)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let w = d1 * x / (d1 * x + d2);
        regularized_incomplete_beta(0.5 * d1, 0.5 * d2, w)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log I_w(d1/2, d2/2), w = d1·x/(d1·x+d2); finite in the left tail. frankenscipy-r4933
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let w = d1 * x / (d1 * x + d2);
        fsci_special::log_betainc_scalar(0.5 * d1, 0.5 * d2, w)
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival: 1 − I_w(d1/2, d2/2) = I_{1−w}(d2/2, d1/2), with
        // 1−w = d2/(d1·x+d2). Computing it directly avoids the catastrophic loss
        // of the default 1−cdf in the right tail (F.sf returned 0 where scipy
        // gives e.g. 9.8e-18 — ANOVA tail p-values). frankenscipy-…
        if x <= 0.0 {
            return 1.0;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let w_comp = d2 / (d1 * x + d2);
        regularized_incomplete_beta(0.5 * d2, 0.5 * d1, w_comp)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log I_{w'}(d2/2, d1/2), w' = d2/(d1·x+d2); finite in the right tail
        // (ANOVA log p-value) where the survival underflows. frankenscipy-r4933
        if x <= 0.0 {
            return 0.0;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let w_comp = d2 / (d1 * x + d2);
        fsci_special::log_betainc_scalar(0.5 * d2, 0.5 * d1, w_comp)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let w = fsci_special::betaincinv_scalar(0.5 * d1, 0.5 * d2, q);
        if w >= 1.0 {
            return f64::INFINITY;
        }
        let mut x = d2 * w / (d1 * (1.0 - w));
        if !x.is_finite() || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        if self.dfd > 2.0 {
            self.dfd / (self.dfd - 2.0)
        } else {
            f64::NAN
        }
    }

    fn var(&self) -> f64 {
        if self.dfd > 4.0 {
            let d1 = self.dfn;
            let d2 = self.dfd;
            2.0 * d2 * d2 * (d1 + d2 - 2.0) / (d1 * (d2 - 2.0).powi(2) * (d2 - 4.0))
        } else {
            f64::NAN
        }
    }

    fn skewness(&self) -> f64 {
        // ((2·d1 + d2 − 2) · √(8(d2 − 4))) / ((d2 − 6) · √(d1 · (d1 + d2 − 2)))
        // for d2 > 6, NaN otherwise. (frankenscipy-zhiof)
        let d1 = self.dfn;
        let d2 = self.dfd;
        if d2 > 6.0 {
            (2.0 * d1 + d2 - 2.0) * (8.0 * (d2 - 4.0)).sqrt()
                / ((d2 - 6.0) * (d1 * (d1 + d2 - 2.0)).sqrt())
        } else {
            f64::NAN
        }
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis for d2 > 8 (frankenscipy-zhiof):
        //   12·(d1·(5d2 − 22)·(d1 + d2 − 2) + (d2 − 4)·(d2 − 2)²)
        //   / (d1·(d2 − 6)·(d2 − 8)·(d1 + d2 − 2))
        let d1 = self.dfn;
        let d2 = self.dfd;
        if d2 > 8.0 {
            let num =
                12.0 * (d1 * (5.0 * d2 - 22.0) * (d1 + d2 - 2.0) + (d2 - 4.0) * (d2 - 2.0).powi(2));
            let den = d1 * (d2 - 6.0) * (d2 - 8.0) * (d1 + d2 - 2.0);
            num / den
        } else {
            f64::NAN
        }
    }

    fn entropy(&self) -> f64 {
        // h(F(d1, d2)) = ln(d2/d1 · B(d1/2, d2/2))
        //              + (1 − d1/2) ψ(d1/2)
        //              − (1 + d2/2) ψ(d2/2)
        //              + ((d1 + d2)/2) ψ((d1 + d2)/2).
        let (d1, d2) = (self.dfn, self.dfd);
        let log_beta = ln_gamma(d1 / 2.0) + ln_gamma(d2 / 2.0) - ln_gamma((d1 + d2) / 2.0);
        (d2 / d1).ln() + log_beta + (1.0 - d1 / 2.0) * fsci_special::digamma_scalar(d1 / 2.0)
            - (1.0 + d2 / 2.0) * fsci_special::digamma_scalar(d2 / 2.0)
            + ((d1 + d2) / 2.0) * fsci_special::digamma_scalar((d1 + d2) / 2.0)
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self {
                dfn: f64::NAN,
                dfd: f64::NAN,
            };
        }

        let n = data.len() as f64;
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        if !mean.is_finite() || !var.is_finite() || mean <= 1.0 || var <= 0.0 {
            return Self {
                dfn: f64::NAN,
                dfd: f64::NAN,
            };
        }

        let dfd = 2.0 * mean / (mean - 1.0);
        if !dfd.is_finite() || dfd <= 4.0 {
            return Self {
                dfn: f64::NAN,
                dfd: f64::NAN,
            };
        }

        let base_variance = 2.0 * dfd * dfd / ((dfd - 2.0).powi(2) * (dfd - 4.0));
        let variance_ratio = var / base_variance;
        if !variance_ratio.is_finite() || variance_ratio <= 1.0 {
            return Self {
                dfn: f64::NAN,
                dfd: f64::NAN,
            };
        }

        let dfn = (dfd - 2.0) / (variance_ratio - 1.0);
        if !dfn.is_finite() || dfn <= 0.0 {
            return Self {
                dfn: f64::NAN,
                dfd: f64::NAN,
            };
        }

        Self { dfn, dfd }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        if let Some(&x) = data.iter().find(|&&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(format!(
                "FDistribution fit data contains non-finite value: {x}"
            )));
        }
        if let Some(&x) = data.iter().find(|&&x| x < 0.0) {
            return Err(FitError::UnsupportedData(format!(
                "FDistribution support is [0, infinity); got {x}"
            )));
        }

        let fitted = Self::fit(data);
        if fitted.dfn.is_finite() && fitted.dfn > 0.0 && fitted.dfd.is_finite() && fitted.dfd > 4.0
        {
            Ok(fitted)
        } else {
            Err(FitError::NonConvergent(
                "FDistribution moment fit could not estimate valid degrees of freedom".to_owned(),
            ))
        }
    }

    fn mode(&self) -> f64 {
        // Standard result: mode = ((dfn − 2)/dfn) · (dfd/(dfd + 2)) for
        // dfn > 2 (else pdf is monotone decreasing and the mode collapses
        // to 0); requires dfd > 0 throughout. frankenscipy-tlw2q.
        if self.dfn > 2.0 {
            ((self.dfn - 2.0) / self.dfn) * (self.dfd / (self.dfd + 2.0))
        } else {
            0.0
        }
    }
}

// ══════════════════════════════════════════════════════════════════════
// Non-central F Distribution
// ══════════════════════════════════════════════════════════════════════

/// Non-central F distribution with numerator df `dfn`, denominator df `dfd`,
/// and non-centrality parameter `nc`.
///
/// Matches `scipy.stats.ncf(dfn, dfd, nc)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NoncentralF {
    pub dfn: f64,
    pub dfd: f64,
    pub nc: f64,
}

impl NoncentralF {
    #[must_use]
    pub fn new(dfn: f64, dfd: f64, nc: f64) -> Self {
        assert!(dfn > 0.0, "dfn must be positive, got {dfn}");
        assert!(dfd > 0.0, "dfd must be positive, got {dfd}");
        assert!(nc >= 0.0, "nc must be non-negative, got {nc}");
        Self { dfn, dfd, nc }
    }
}

/// k-th raw moment of the noncentral F. F = (Y/d1)/(W/d2) with Y ~ ncx2(d1, λ)
/// and W ~ χ²(d2) independent, so E[F^k] = (d2/d1)^k · E[Y^k] · E[W^{-k}].
/// ncx2 cumulants are κ_n = 2^{n-1}(n-1)!(d1 + nλ); E[χ²(d2)^{-k}] =
/// 1/Π_{j=1..k}(d2 − 2j) (finite only for d2 > 2k). frankenscipy-1mlrz
fn ncf_raw_moment(d1: f64, d2: f64, lam: f64, k: u32) -> f64 {
    let k1 = d1 + lam;
    let k2 = 2.0 * (d1 + 2.0 * lam);
    let k3 = 8.0 * (d1 + 3.0 * lam);
    let k4 = 48.0 * (d1 + 4.0 * lam);
    let mu_y = match k {
        1 => k1,
        2 => k2 + k1 * k1,
        3 => k3 + 3.0 * k2 * k1 + k1 * k1 * k1,
        4 => k4 + 4.0 * k3 * k1 + 3.0 * k2 * k2 + 6.0 * k2 * k1 * k1 + k1 * k1 * k1 * k1,
        _ => return f64::NAN,
    };
    let mut inv = 1.0;
    for j in 1..=k {
        inv *= d2 - 2.0 * f64::from(j);
    }
    (d2 / d1).powi(k as i32) * mu_y / inv
}

impl ContinuousDistribution for NoncentralF {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 || x.is_nan() {
            return if x.is_nan() { f64::NAN } else { 0.0 };
        }
        if self.nc == 0.0 {
            return FDistribution::new(self.dfn, self.dfd).pdf(x);
        }

        // pdf = exp(logpdf). The former direct series seeded the Poisson mixture
        // with `e^{-nc/2}`, which stays below the `1e-20 && j>10` break threshold
        // through the first terms for nc ≳ 150 (the seed is tiny long before the
        // Poisson peak at j≈nc/2), so the loop broke at j=11 — before the peak —
        // and returned ~0. `logpdf` sums the same mixture in log space (peak-safe,
        // logsumexp), so exponentiating it is correct for all nc.
        self.logpdf(x).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // logsumexp over the Poisson(λ/2)-weighted F-mixture:
        //   log f = logsumexp_j [ (−λ/2 + j·ln(λ/2) − lnΓ(j+1)) + F(d1+2j, d2).logpdf(x) ]
        // Finite deep in the tail where the summed pdf underflows to 0. frankenscipy-7m3xk
        if x <= 0.0 || x.is_nan() {
            return if x.is_nan() {
                f64::NAN
            } else {
                f64::NEG_INFINITY
            };
        }
        if self.nc == 0.0 {
            return FDistribution::new(self.dfn, self.dfd).logpdf(x);
        }
        let d1 = self.dfn;
        let d2 = self.dfd;
        let half_lam = self.nc / 2.0;
        let ln_half_lam = half_lam.ln();
        let mut terms: Vec<f64> = Vec::new();
        let mut max = f64::NEG_INFINITY;
        for j in 0..400usize {
            let jf = j as f64;
            let log_pois = -half_lam + jf * ln_half_lam - ln_gamma(jf + 1.0);
            // Component k is c_k·G, G ~ F(d1+2k, d2), c_k = (d1+2k)/d1, so
            // log pdf_k = log_pois − ln c_k + F_logpdf(x/c_k). frankenscipy-t9cj2
            let ck = (d1 + 2.0 * jf) / d1;
            let term = log_pois - ck.ln() + FDistribution::new(d1 + 2.0 * jf, d2).logpdf(x / ck);
            if term.is_finite() {
                terms.push(term);
                if term > max {
                    max = term;
                }
            }
            // Past the Poisson peak, stop once the term is negligible vs the max.
            if jf > half_lam && term < max - 60.0 {
                break;
            }
        }
        if !max.is_finite() {
            return f64::NEG_INFINITY;
        }
        let s: f64 = terms.iter().map(|&t| (t - max).exp()).sum();
        max + s.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x.is_nan() {
            return f64::NAN;
        }
        if self.nc == 0.0 {
            return FDistribution::new(self.dfn, self.dfd).cdf(x);
        }

        // Delegate the noncentral-F CDF to the special kernel `ncfdtr`. Besides
        // being much faster than this crate's Poisson-weighted sum of central-F
        // CDFs, it is also CORRECT for large nc: the old sum seeded
        // `poisson_term = e^{-nc/2}` which underflows to 0 for nc ≳ 40 (the same
        // bug the noncentral χ² path already fixed), returning ~0 there.
        fsci_special::ncfdtr(self.dfn, self.dfd, self.nc, x).clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        // Survival computed DIRECTLY, never as 1 − cdf — the same correction
        // `FDistribution::sf` already carries, and for the same reason. The F tail
        // is polynomial, so the subtraction erodes silently long before it
        // collapses: against scipy.stats.ncf.sf at dfn=3, dfd=5, nc=2 it holds 3
        // digits at f=1e6 and returns 0.0 at f=1e12 (true 2.3303549e-29); at
        // dfn=5, dfd=200, nc=3, f=1e4 it returns 0.0 for a true 4.4981732e-230.
        // frankenscipy-wofb.
        if x.is_nan() {
            return f64::NAN;
        }
        if x <= 0.0 {
            return 1.0;
        }
        if self.nc == 0.0 {
            return FDistribution::new(self.dfn, self.dfd).sf(x);
        }
        fsci_special::ncfdtrc(self.dfn, self.dfd, self.nc, x).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        // Invert the noncentral-F CDF directly with the purpose-built `ncfdtri`
        // (Illinois over `ncfdtr`) instead of bisecting this crate's local
        // Poisson-sum-of-central-F cdf. Round-trip guard falls back to the exact
        // bisection on any drift (no regression, no correctness risk).
        let x = fsci_special::ncfdtri(self.dfn, self.dfd, self.nc, q);
        if x.is_finite() && x > 0.0 && (self.cdf(x) - q).abs() < 1e-6 {
            return x;
        }
        ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std())
    }

    fn mean(&self) -> f64 {
        if self.dfd > 2.0 {
            self.dfd * (self.dfn + self.nc) / (self.dfn * (self.dfd - 2.0))
        } else {
            f64::NAN
        }
    }

    fn var(&self) -> f64 {
        if self.dfd > 4.0 {
            let d1 = self.dfn;
            let d2 = self.dfd;
            let lam = self.nc;

            2.0 * (d2 / d1).powi(2) * ((d1 + lam).powi(2) + (d1 + 2.0 * lam) * (d2 - 2.0))
                / ((d2 - 2.0).powi(2) * (d2 - 4.0))
        } else {
            f64::NAN
        }
    }

    fn entropy(&self) -> f64 {
        // No closed form; h = −∫ pdf·ln pdf dx numerically (now that the pdf is
        // correct, frankenscipy-t9cj2). Heavy-tailed, so take the upper bound
        // from a far quantile; the pdf is a Poisson-series so keep the grid
        // modest. Matches scipy ~1e-7. frankenscipy-1mlrz
        let hi = self.ppf(1.0 - 1e-10);
        if !hi.is_finite() || hi <= 0.0 {
            return f64::NAN;
        }
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            hi,
            2_048,
            1e-10,
            1e-12,
            10,
        )
    }

    fn fit(_data: &[f64]) -> Self {
        Self {
            dfn: f64::NAN,
            dfd: f64::NAN,
            nc: f64::NAN,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Maximum-likelihood fit (standardized NCF, loc=0/scale=1) via
        // multi-start Nelder-Mead over (ln dfn, ln dfd, ln nc); matches
        // scipy.stats.ncf.fit(.., floc=0, fscale=1). Moments are insufficient
        // (3 params), but the likelihood is well-behaved, so MLE recovers the
        // parameters reliably.
        if data.len() < 3 {
            return Err(FitError::InsufficientData {
                required: 3,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "NoncentralF data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "NoncentralF support is (0, ∞); got {x}"
                )));
            }
        }
        let owned: Vec<f64> = data.to_vec();
        let nll = |p: &[f64]| -> f64 {
            let (dfn, dfd, nc) = (p[0].exp(), p[1].exp(), p[2].exp());
            if !dfn.is_finite() || !dfd.is_finite() || !nc.is_finite() {
                return f64::INFINITY;
            }
            let dist = NoncentralF { dfn, dfd, nc };
            let mut total = 0.0;
            for &x in &owned {
                let d = dist.pdf(x);
                if d <= 0.0 || !d.is_finite() {
                    return f64::INFINITY;
                }
                total -= d.ln();
            }
            total
        };
        let starts = [[2.0_f64, 10.0, 1.0], [5.0, 10.0, 3.0], [1.5, 5.0, 0.5]];
        let mut best: Option<(f64, [f64; 3])> = None;
        for s in &starts {
            let x0 = [s[0].ln(), s[1].ln(), s[2].ln()];
            let opts = fsci_opt::MinimizeOptions {
                maxiter: Some(2000),
                maxfev: Some(4000),
                tol: Some(1e-9),
                ..Default::default()
            };
            if let Ok(res) = fsci_opt::nelder_mead(&nll, &x0, opts)
                && let Some(f) = res.fun
                && f.is_finite()
                && best.as_ref().is_none_or(|(bf, _)| f < *bf)
            {
                best = Some((f, [res.x[0].exp(), res.x[1].exp(), res.x[2].exp()]));
            }
        }
        match best {
            Some((_, p))
                if p[0] > 0.0 && p[1] > 0.0 && p[2] >= 0.0 && p.iter().all(|v| v.is_finite()) =>
            {
                Ok(Self {
                    dfn: p[0],
                    dfd: p[1],
                    nc: p[2],
                })
            }
            _ => Err(FitError::NonConvergent(
                "NoncentralF MLE failed to converge".to_owned(),
            )),
        }
    }

    fn skewness(&self) -> f64 {
        // Third moment exists only for dfd > 6. frankenscipy-1mlrz
        if self.dfd <= 6.0 {
            return f64::NAN;
        }
        let m = |k: u32| ncf_raw_moment(self.dfn, self.dfd, self.nc, k);
        let (m1, m2, m3) = (m(1), m(2), m(3));
        let var = m2 - m1 * m1;
        let mu3 = m3 - 3.0 * m1 * m2 + 2.0 * m1 * m1 * m1;
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Fourth moment exists only for dfd > 8. frankenscipy-1mlrz
        if self.dfd <= 8.0 {
            return f64::NAN;
        }
        let m = |k: u32| ncf_raw_moment(self.dfn, self.dfd, self.nc, k);
        let (m1, m2, m3, m4) = (m(1), m(2), m(3), m(4));
        let var = m2 - m1 * m1;
        let mu4 = m4 - 4.0 * m1 * m3 + 6.0 * m1 * m1 * m2 - 3.0 * m1 * m1 * m1 * m1;
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        f64::NAN
    }
}

// ══════════════════════════════════════════════════════════════════════
// Beta Distribution
// ══════════════════════════════════════════════════════════════════════

/// Beta distribution with shape parameters `a` and `b`.
///
/// Matches `scipy.stats.beta(a, b)`.
/// Supported on [0, 1].
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct BetaDist {
    pub a: f64,
    pub b: f64,
}

impl BetaDist {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(b > 0.0, "b must be positive, got {b}");
        Self { a, b }
    }

    /// Log-density at many points, hoisting the `ln_beta(a, b)` normalizer (three
    /// lgamma evaluations) out of the per-point loop. Byte-identical to mapping
    /// `logpdf` (same single `- lb` subtraction; boundaries delegate to `pdf`).
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let lb = ln_beta(self.a, self.b);
        par_continuous_map_min(xs, 65536, |x| {
            if !(0.0..1.0).contains(&x) || x == 0.0 {
                return self.pdf(x).ln();
            }
            (self.a - 1.0) * x.ln() + (self.b - 1.0) * (1.0 - x).ln() - lb
        })
    }

    /// Density at many points; hoists `ln_beta(a, b)` like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let lb = ln_beta(self.a, self.b);
        par_continuous_map_min(xs, 65536, |x| {
            if !(0.0..=1.0).contains(&x) {
                return 0.0;
            }
            if x == 0.0 {
                return if self.a < 1.0 {
                    f64::INFINITY
                } else if self.a == 1.0 {
                    (-lb).exp()
                } else {
                    0.0
                };
            }
            if x == 1.0 {
                return if self.b < 1.0 {
                    f64::INFINITY
                } else if self.b == 1.0 {
                    (-lb).exp()
                } else {
                    0.0
                };
            }
            ((self.a - 1.0) * x.ln() + (self.b - 1.0) * (1.0 - x).ln() - lb).exp()
        })
    }

    /// Cumulative distribution at many points — work-gated parallel map of the per-point
    /// cdf, byte-identical to mapping `cdf`.
    #[must_use]
    pub fn cdf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.cdf(x))
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point
    /// `ppf`, byte-identical to mapping `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.ppf(q))
    }

    /// Survival function at many points — work-gated parallel map of the per-point sf,
    /// byte-identical to mapping `sf`.
    #[must_use]
    pub fn sf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.sf(x))
    }

    /// Inverse survival function at many points — work-gated parallel map of the per-point isf,
    /// byte-identical to mapping `isf`.
    #[must_use]
    pub fn isf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.isf(q))
    }
}

impl ContinuousDistribution for BetaDist {
    fn pdf(&self, x: f64) -> f64 {
        // /testing-metamorphic boundary [frankenscipy-rsx33]: scipy.stats.beta
        // returns the limit of x^(a-1)·(1-x)^(b-1)/B(a,b) at the boundary
        // — finite when the relevant exponent is zero, +inf when it is
        // negative. The previous short-circuit "x ≤ 0 || x ≥ 1 → 0" was
        // wrong for both a=1 (pdf(0) = 1/B(1, b)) and a<1 (pdf(0) = ∞).
        if !(0.0..=1.0).contains(&x) {
            return 0.0;
        }
        if x == 0.0 {
            return if self.a < 1.0 {
                f64::INFINITY
            } else if self.a == 1.0 {
                (-ln_beta(self.a, self.b)).exp()
            } else {
                0.0
            };
        }
        if x == 1.0 {
            return if self.b < 1.0 {
                f64::INFINITY
            } else if self.b == 1.0 {
                (-ln_beta(self.a, self.b)).exp()
            } else {
                0.0
            };
        }
        let ln_pdf =
            (self.a - 1.0) * x.ln() + (self.b - 1.0) * (1.0 - x).ln() - ln_beta(self.a, self.b);
        ln_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // (a−1)·ln(x) + (b−1)·ln(1−x) − lnB(a,b); the shape-dependent
        // boundaries (x∉(0,1), x=0, x=1) delegate to pdf. frankenscipy-p82v7
        if !(0.0..1.0).contains(&x) || x == 0.0 {
            return self.pdf(x).ln();
        }
        (self.a - 1.0) * x.ln() + (self.b - 1.0) * (1.0 - x).ln() - ln_beta(self.a, self.b)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return 1.0;
        }
        regularized_incomplete_beta(self.a, self.b, x)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log I_x(a,b); finite in the left tail where I underflows to 0. frankenscipy-r4933
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        if x >= 1.0 {
            return 0.0;
        }
        fsci_special::log_betainc_scalar(self.a, self.b, x)
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival: 1 − I_x(a,b) = I_{1−x}(b,a). Computing it directly
        // avoids the default 1−cdf collapsing to 0 as x→1 (beta(2,8).sf(0.999)
        // returned 0 where scipy gives 9e-24). frankenscipy-…
        if x <= 0.0 {
            return 1.0;
        }
        if x >= 1.0 {
            return 0.0;
        }
        regularized_incomplete_beta(self.b, self.a, 1.0 - x)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log I_{1-x}(b,a); finite as x→1 where the survival underflows. frankenscipy-r4933
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_betainc_scalar(self.b, self.a, 1.0 - x)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        let mut x = fsci_special::betaincinv_scalar(self.a, self.b, q);
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).clamp(0.0, 1.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        self.a / (self.a + self.b)
    }

    fn var(&self) -> f64 {
        let ab = self.a + self.b;
        self.a * self.b / (ab * ab * (ab + 1.0))
    }

    fn entropy(&self) -> f64 {
        // h(Beta(a, b)) = ln B(a, b) − (a − 1) ψ(a) − (b − 1) ψ(b)
        //               + (a + b − 2) ψ(a + b).
        let (a, b) = (self.a, self.b);
        let log_beta = ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b);
        log_beta
            - (a - 1.0) * fsci_special::digamma_scalar(a)
            - (b - 1.0) * fsci_special::digamma_scalar(b)
            + (a + b - 2.0) * fsci_special::digamma_scalar(a + b)
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty()
            || data
                .iter()
                .any(|&x| !x.is_finite() || !(0.0..=1.0).contains(&x))
        {
            return Self {
                a: f64::NAN,
                b: f64::NAN,
            };
        }

        let n = data.len() as f64;
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        if !mean.is_finite() || !var.is_finite() || mean <= 0.0 || mean >= 1.0 || var <= 0.0 {
            return Self {
                a: f64::NAN,
                b: f64::NAN,
            };
        }

        let common = mean * (1.0 - mean) / var - 1.0;
        if !common.is_finite() || common <= 0.0 {
            return Self {
                a: f64::NAN,
                b: f64::NAN,
            };
        }

        Self {
            a: mean * common,
            b: (1.0 - mean) * common,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data
            .iter()
            .any(|&x| !x.is_finite() || !(0.0..=1.0).contains(&x))
        {
            return Err(FitError::UnsupportedData(
                "BetaDist support is [0, 1]".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.a.is_finite() || !fitted.b.is_finite() {
            return Err(FitError::NonConvergent(
                "BetaDist fit produced non-finite parameters".into(),
            ));
        }
        Ok(fitted)
    }

    fn skewness(&self) -> f64 {
        let (a, b) = (self.a, self.b);
        2.0 * (b - a) * (a + b + 1.0).sqrt() / ((a + b + 2.0) * (a * b).sqrt())
    }

    fn kurtosis(&self) -> f64 {
        let (a, b) = (self.a, self.b);
        let ab = a + b;
        let num = 6.0 * ((a - b).powi(2) * (ab + 1.0) - a * b * (ab + 2.0));
        let den = a * b * (ab + 2.0) * (ab + 3.0);
        num / den
    }

    fn mode(&self) -> f64 {
        // BetaDist mode = (a-1)/(a+b-2) for a > 1 and b > 1
        // [frankenscipy-71mv5]. Outside this regime the mode is at a
        // boundary (0 or 1) or the pdf has no interior maximum;
        // return NaN to match the trait-default contract for such cases.
        if self.a > 1.0 && self.b > 1.0 {
            (self.a - 1.0) / (self.a + self.b - 2.0)
        } else {
            f64::NAN
        }
    }
}

// ══════════════════════════════════════════════════════════════════════
// Studentized Range Distribution
// ══════════════════════════════════════════════════════════════════════

/// Studentized Range distribution for k groups with df degrees of freedom.
///
/// This is the distribution of (max - min)/S where max and min are the
/// extreme values of k independent standard normal random variables,
/// and S is an independent estimate of the standard deviation with df
/// degrees of freedom.
///
/// Matches `scipy.stats.studentized_range(k, df)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct StudentizedRange {
    /// Number of groups being compared (k >= 2)
    pub k: usize,
    /// Degrees of freedom (df > 0)
    pub df: f64,
}

impl StudentizedRange {
    #[must_use]
    pub fn new(k: usize, df: f64) -> Self {
        assert!(k >= 2, "k must be >= 2, got {k}");
        assert!(df > 0.0, "df must be positive, got {df}");
        Self { k, df }
    }

    /// CDF of the range of k standard normal variables at value w.
    /// F_R(w) = integral_{-inf}^{inf} k * phi(x) * [Phi(x+w) - Phi(x)]^{k-1} dx
    fn range_cdf(k: usize, w: f64) -> f64 {
        if w <= 0.0 {
            return 0.0;
        }
        if !w.is_finite() {
            return 1.0;
        }
        let k_f = k as f64;
        let integrand = |x: f64| {
            let phi_x = (-0.5 * x * x).exp() / (2.0 * PI).sqrt();
            let cdf_x = standard_normal_cdf(x);
            let cdf_xw = standard_normal_cdf(x + w);
            let diff = (cdf_xw - cdf_x).max(0.0);
            k_f * phi_x * diff.powf(k_f - 1.0)
        };
        simpson_integrate_adaptive(integrand, -12.0, 12.0, 64, 1e-10, 1e-14, 12).clamp(0.0, 1.0)
    }

    /// Survival function: P(Q > q)
    pub fn sf(&self, q: f64) -> f64 {
        if q <= 0.0 {
            return 1.0;
        }
        if !q.is_finite() {
            return 0.0;
        }
        1.0 - self.cdf(q)
    }

    /// Cumulative distribution function: P(Q <= q)
    ///
    /// Computed by integrating over the chi-scaled variable:
    /// F_Q(q) = integral_0^inf f_chi(s; df) * F_R(q*s) ds
    ///
    /// where f_chi is the PDF of sqrt(chi2(df)/df).
    pub fn cdf(&self, q: f64) -> f64 {
        if q <= 0.0 {
            return 0.0;
        }
        if !q.is_finite() {
            return 1.0;
        }

        let df = self.df;
        let k = self.k;

        // For the scaled chi distribution (s = sqrt(chi2/df)), we integrate
        // using the change of variables. Let u = chi2/df, then s = sqrt(u).
        // We integrate over u from 0 to infinity.
        //
        // chi2 has PDF: f(x) = x^(df/2-1) * exp(-x/2) / (2^(df/2) * Gamma(df/2))
        // u = x/df has PDF: f(u) = (df*u)^(df/2-1) * exp(-df*u/2) * df / (2^(df/2) * Gamma(df/2))
        //                       = df^(df/2) * u^(df/2-1) * exp(-df*u/2) / (2^(df/2) * Gamma(df/2))

        // More direct: integrate using the chi2 distribution directly
        // F_Q(q) = integral_0^inf f_chi2(v; df) * F_R(q * sqrt(v/df)) dv

        let half_df = df / 2.0;
        let log_norm = half_df * 2.0_f64.ln() + ln_gamma(half_df);

        let integrand = |v: f64| {
            if v <= 0.0 {
                return 0.0;
            }
            let log_chi2_pdf = (half_df - 1.0) * v.ln() - v / 2.0 - log_norm;
            let chi2_pdf = log_chi2_pdf.exp();
            let s = (v / df).sqrt();
            let range_cdf = Self::range_cdf(k, q * s);
            chi2_pdf * range_cdf
        };

        // Integrate from 0 to a reasonable upper bound (chi2 tails decay fast)
        let upper = (df + 10.0 * (2.0 * df).sqrt()).max(50.0);
        simpson_integrate_adaptive(integrand, 1e-10, upper, 128, 1e-9, 1e-12, 14).clamp(0.0, 1.0)
    }

    /// Density of the range of `k` standard normals at `w`: `d/dw F_R(w)`.
    /// `F_R'(w) = k(k-1) ∫ φ(x)·φ(x+w)·[Φ(x+w) − Φ(x)]^{k-2} dx`.
    fn range_pdf(k: usize, w: f64) -> f64 {
        if w <= 0.0 || !w.is_finite() {
            return 0.0;
        }
        let k_f = k as f64;
        let integrand = |x: f64| {
            let inv = 1.0 / (2.0 * PI).sqrt();
            let phi_x = (-0.5 * x * x).exp() * inv;
            let xw = x + w;
            let phi_xw = (-0.5 * xw * xw).exp() * inv;
            let diff = (standard_normal_cdf(xw) - standard_normal_cdf(x)).max(0.0);
            k_f * (k_f - 1.0) * phi_x * phi_xw * diff.powf(k_f - 2.0)
        };
        simpson_integrate_adaptive(integrand, -12.0, 12.0, 64, 1e-10, 1e-14, 12).max(0.0)
    }

    /// Probability density function `f_Q(q)`.
    ///
    /// `f_Q(q) = ∫_0^∞ f_chi2(v; df) · F_R'(q·s) · s dv`, `s = sqrt(v/df)`.
    pub fn pdf(&self, q: f64) -> f64 {
        if q <= 0.0 || !q.is_finite() {
            return 0.0;
        }
        let df = self.df;
        let k = self.k;
        let half_df = df / 2.0;
        let log_norm = half_df * 2.0_f64.ln() + ln_gamma(half_df);
        let integrand = |v: f64| {
            if v <= 0.0 {
                return 0.0;
            }
            let log_chi2_pdf = (half_df - 1.0) * v.ln() - v / 2.0 - log_norm;
            let chi2_pdf = log_chi2_pdf.exp();
            let s = (v / df).sqrt();
            chi2_pdf * Self::range_pdf(k, q * s) * s
        };
        let upper = (df + 10.0 * (2.0 * df).sqrt()).max(50.0);
        simpson_integrate_adaptive(integrand, 1e-10, upper, 128, 1e-9, 1e-12, 14).max(0.0)
    }

    /// Percent-point (inverse CDF) function via bisection on the monotone CDF.
    /// Percent-point function. `p` outside `[0, 1]` is NaN, matching scipy and matching
    /// every other `ppf` in this crate.
    ///
    /// This used to clamp instead: `p <= 0.0` returned 0.0 and `p >= 1.0` returned
    /// infinity, so `ppf(-0.5)` reported the support's lower bound and `ppf(1.5)` reported
    /// infinity — both plausible-looking answers to a question with no answer. scipy 1.17.1
    /// with `k = 3, df = 10` gives NaN for both, and 0.0 / inf only at exactly 0 and 1.
    ///
    /// In-range behaviour is unchanged: `p == 0.0` still yields 0.0, `p == 1.0` still yields
    /// infinity, and the Illinois root-find below is untouched.
    pub fn ppf(&self, p: f64) -> f64 {
        if !(0.0..=1.0).contains(&p) {
            return f64::NAN;
        }
        if p == 0.0 {
            return 0.0;
        }
        if p == 1.0 {
            return f64::INFINITY;
        }
        let lo = 0.0_f64;
        let mut hi = 1.0_f64;
        let mut fhi = self.cdf(hi) - p;
        while fhi < 0.0 && hi < 1e6 {
            hi *= 2.0;
            fhi = self.cdf(hi) - p;
        }
        // cdf(0) = 0 (guarded above), so f(lo) = -p < 0 ≤ fhi and the
        // studentized-range cdf is monotone increasing in q. Illinois converges
        // superlinearly (~12 evals) vs the former ~40 bisection steps — each eval
        // is an expensive adaptive-Simpson double integral, so fewer wins.
        illinois_root_increasing(|x| self.cdf(x) - p, lo, hi, -p, fhi)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Gamma Distribution
// ══════════════════════════════════════════════════════════════════════

/// Gamma distribution with shape `a` and rate `1/scale`.
///
/// Matches `scipy.stats.gamma(a, scale=scale)`.
/// PDF: f(x) = x^(a-1) * exp(-x/scale) / (scale^a * Γ(a))
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GammaDist {
    pub a: f64,
    pub scale: f64,
}

impl GammaDist {
    #[must_use]
    pub fn new(a: f64, scale: f64) -> Self {
        assert!(a > 0.0, "shape a must be positive, got {a}");
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { a, scale }
    }

    /// Log-density at many points (the realistic dataset-likelihood workload),
    /// hoisting the expensive `ln_gamma(a)` and `a·ln(scale)` normalizer terms out
    /// of the per-point loop. Byte-identical to mapping `logpdf`: the two normalizer
    /// terms are kept as SEPARATE subtractions (a − b − c ≠ a − (b+c) in f64), so the
    /// arithmetic order matches `logpdf` exactly.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a_scale_ln = self.a * self.scale.ln();
        let lg = ln_gamma(self.a);
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return f64::NEG_INFINITY;
            }
            if x == 0.0 {
                return if self.a == 1.0 {
                    -self.scale.ln()
                } else if self.a > 1.0 {
                    f64::NEG_INFINITY
                } else {
                    f64::INFINITY
                };
            }
            (self.a - 1.0) * x.ln() - x / self.scale - a_scale_ln - lg
        })
    }

    /// Density at many points; hoists `ln_gamma(a)` out of the loop like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a_scale_ln = self.a * self.scale.ln();
        let lg = ln_gamma(self.a);
        // Cheap kernel (1 ln + 1 exp): the hoisted `lg`/`a_scale_ln` are the real
        // win vs scipy; thread-spawn does not amortise until the array is large,
        // so use a high parallel gate (small/medium arrays stay serial+hoisted).
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            if x == 0.0 {
                return if self.a == 1.0 {
                    1.0 / self.scale
                } else if self.a > 1.0 {
                    0.0
                } else {
                    f64::INFINITY
                };
            }
            ((self.a - 1.0) * x.ln() - x / self.scale - a_scale_ln - lg).exp()
        })
    }

    /// Cumulative distribution at many points — parallel map of the per-point regularized gamma
    /// (costly enough to amortise thread spawn at scale; work-gated). Byte-identical to mapping `cdf`.
    #[must_use]
    pub fn cdf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.cdf(x))
    }

    /// Inverse cdf at many probabilities — work-gated parallel map of the per-point `ppf`
    /// (gammaincinv + Newton refine, costly enough to amortise spawn). Byte-identical to mapping `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.ppf(q))
    }
    /// Survival function at many points — work-gated parallel map of the per-point sf,
    /// byte-identical to mapping `sf`.
    #[must_use]
    pub fn sf_many(&self, xs: &[f64]) -> Vec<f64> {
        par_continuous_map(xs, |x| self.sf(x))
    }

    /// Inverse survival function at many points — work-gated parallel map of the per-point isf,
    /// byte-identical to mapping `isf`.
    #[must_use]
    pub fn isf_many(&self, qs: &[f64]) -> Vec<f64> {
        par_continuous_map(qs, |q| self.isf(q))
    }
}

impl ContinuousDistribution for GammaDist {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.a == 1.0 {
                1.0 / self.scale
            } else if self.a > 1.0 {
                0.0
            } else {
                f64::INFINITY
            };
        }
        let ln_pdf =
            (self.a - 1.0) * x.ln() - x / self.scale - self.a * self.scale.ln() - ln_gamma(self.a);
        ln_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // log of the gamma density; finite in the tail where pdf underflows. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        if x == 0.0 {
            return if self.a == 1.0 {
                -self.scale.ln()
            } else if self.a > 1.0 {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            };
        }
        (self.a - 1.0) * x.ln() - x / self.scale - self.a * self.scale.ln() - ln_gamma(self.a)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        lower_regularized_gamma(self.a, x / self.scale)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log P(a, x/scale); finite in the left tail where P underflows to 0. frankenscipy-s14mf
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_gammainc_scalar(self.a, x / self.scale)
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(self.a, x / self.scale)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let mut x = self.scale * fsci_special::gammaincinv_scalar(self.a, q);
        if x <= 0.0 || !x.is_finite() || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // scipy.stats.gamma.isf delegates to gammainccinv (upper-tail inverse),
        // which is well-conditioned for small q. The trait-default isf routes
        // ppf(1-q) → gammaincinv near 1, losing precision in the right tail
        // (isf(1e-12) was ~1.7e-5 off scipy). frankenscipy-d2gag
        let mut x = self.scale * fsci_special::gammainccinv_scalar(self.a, q);
        if x <= 0.0 || !x.is_finite() || (self.sf(x) - q).abs() > 0.1 {
            return isf_bisection(|v| self.sf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.sf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                // sf is decreasing: d(sf)/dx = -pdf, so x -= err / (-pdf).
                x = (x + err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        self.a * self.scale
    }

    fn var(&self) -> f64 {
        self.a * self.scale * self.scale
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self {
                a: f64::NAN,
                scale: f64::NAN,
            };
        }
        let n = data.len() as f64;
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        if var <= 0.0 || mean <= 0.0 {
            return Self {
                a: f64::NAN,
                scale: f64::NAN,
            };
        }
        let a = mean * mean / var;
        let scale = var / mean;
        Self { a, scale }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Err(FitError::UnsupportedData(
                "GammaDist requires non-negative finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.a.is_finite() || !fitted.scale.is_finite() {
            return Err(FitError::NonConvergent(
                "GammaDist fit produced non-finite parameters".into(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        // H = a + ln(scale) + ln(Gamma(a)) + (1-a)*psi(a)
        self.a + self.scale.ln() + ln_gamma(self.a) + (1.0 - self.a) * digamma(self.a)
    }

    fn mode(&self) -> f64 {
        if self.a >= 1.0 {
            (self.a - 1.0) * self.scale
        } else {
            0.0
        }
    }

    fn skewness(&self) -> f64 {
        2.0 / self.a.sqrt()
    }

    fn kurtosis(&self) -> f64 {
        6.0 / self.a
    }
}

// ══════════════════════════════════════════════════════════════════════
// Generalized Gamma Distribution
// ══════════════════════════════════════════════════════════════════════

/// Generalized gamma distribution.
///
/// Matches `scipy.stats.gengamma(a, c)`.
/// PDF: |c| * x^(c*a - 1) * exp(-x^c) / Γ(a) for x > 0.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GenGamma {
    pub a: f64,
    pub c: f64,
}

/// Same-binary A/B toggle for the GenGamma density shape term: when `true`, the
/// original `x.ln()` + `x.powf(c)` form runs (powf recomputes `ln(x)`); when
/// `false` (default) `ln(x)` is computed once and reused as `(c·lx).exp()`,
/// dropping one `ln` per element. Agrees with the powf form to ~1e-15.
pub static GENGAMMA_LN_REUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// GenGamma log-density shape term `(c·a−1)·ln(x) − x^c`, reusing a single
/// `ln(x)` (so `x^c = exp(c·ln(x))`) instead of letting `powf` recompute it.
#[inline]
fn gengamma_shape_term(x: f64, c: f64, ca_minus_1: f64, reuse: bool) -> f64 {
    if reuse {
        let lx = x.ln();
        ca_minus_1 * lx - (c * lx).exp()
    } else {
        ca_minus_1 * x.ln() - x.powf(c)
    }
}

impl GenGamma {
    #[must_use]
    pub fn new(a: f64, c: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(
            c != 0.0 && c.is_finite(),
            "c must be non-zero and finite, got {c}"
        );
        Self { a, c }
    }

    /// Log-density at many points, hoisting `ln|c|` and `lnΓ(a)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (`ln|c|` kept leading,
    /// `lnΓ(a)` kept as the last subtraction); x≤0 → −∞.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let c = self.c;
        let lead = c.abs().ln();
        let lg = ln_gamma(a);
        let ca1 = c * a - 1.0;
        let reuse = !GENGAMMA_LN_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return f64::NEG_INFINITY;
            }
            lead + gengamma_shape_term(x, c, ca1, reuse) - lg
        })
    }

    /// Density at many points; hoists `ln|c|` and `lnΓ(a)` like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let c = self.c;
        let lead = c.abs().ln();
        let lg = ln_gamma(a);
        let ca1 = c * a - 1.0;
        let reuse = !GENGAMMA_LN_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return 0.0;
            }
            (lead + gengamma_shape_term(x, c, ca1, reuse) - lg).exp()
        })
    }
}

impl ContinuousDistribution for GenGamma {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let a = self.a;
        let c = self.c;
        let reuse = !GENGAMMA_LN_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed);
        let ln_pdf = c.abs().ln() + gengamma_shape_term(x, c, c * a - 1.0, reuse) - ln_gamma(a);
        ln_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // |c|·... log of the generalized-gamma density; finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let a = self.a;
        let c = self.c;
        let reuse = !GENGAMMA_LN_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed);
        c.abs().ln() + gengamma_shape_term(x, c, c * a - 1.0, reuse) - ln_gamma(a)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let a = self.a;
        let c = self.c;
        let y = x.powf(c.abs());
        if c > 0.0 {
            lower_regularized_gamma(a, y)
        } else {
            upper_regularized_gamma(a, y)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival = complement of the cdf's regularized gamma,
        // computed directly so the right tail doesn't collapse to 0 under the
        // default 1−cdf (gengamma(2,1).sf(80) returned 0 vs scipy 1.5e-33).
        // frankenscipy-…
        if x <= 0.0 {
            return 1.0;
        }
        let a = self.a;
        let c = self.c;
        let y = x.powf(c.abs());
        if c > 0.0 {
            upper_regularized_gamma(a, y)
        } else {
            lower_regularized_gamma(a, y)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let a = self.a;
        let c = self.c;
        let q_adj = if c > 0.0 { q } else { 1.0 - q };
        let y = fsci_special::gammaincinv_scalar(a, q_adj);
        y.powf(1.0 / c.abs())
    }

    fn mean(&self) -> f64 {
        let a = self.a;
        let c = self.c;
        (ln_gamma(a + 1.0 / c) - ln_gamma(a)).exp()
    }

    fn var(&self) -> f64 {
        let a = self.a;
        let c = self.c;
        let g1 = (ln_gamma(a + 1.0 / c) - ln_gamma(a)).exp();
        let g2 = (ln_gamma(a + 2.0 / c) - ln_gamma(a)).exp();
        g2 - g1 * g1
    }

    fn entropy(&self) -> f64 {
        // Differential entropy of the generalized gamma. With X^c ~ Gamma(a, 1):
        //   h = ln(Γ(a)/|c|) + a − (a − 1/c)·ψ(a).
        // Matches scipy.stats.gengamma(a, c).entropy().
        let a = self.a;
        let c = self.c;
        ln_gamma(a) - c.abs().ln() + a - (a - 1.0 / c) * digamma(a)
    }

    fn fit(_data: &[f64]) -> Self {
        Self {
            a: f64::NAN,
            c: f64::NAN,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Maximum-likelihood fit (standardized GenGamma, loc=0/scale=1) via
        // multi-start Nelder-Mead over (ln a, c); matches
        // scipy.stats.gengamma.fit(.., floc=0, fscale=1). The 2-parameter
        // moment system is ill-conditioned, so fit by likelihood instead.
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "GenGamma data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "GenGamma support is (0, ∞); got {x}"
                )));
            }
        }
        let owned: Vec<f64> = data.to_vec();
        let nll = |p: &[f64]| -> f64 {
            let a = p[0].exp();
            let c = p[1];
            if !a.is_finite() || !c.is_finite() || c.abs() < 1e-8 {
                return f64::INFINITY;
            }
            let dist = GenGamma { a, c };
            let mut total = 0.0;
            for &x in &owned {
                let d = dist.pdf(x);
                if d <= 0.0 || !d.is_finite() {
                    return f64::INFINITY;
                }
                total -= d.ln();
            }
            total
        };
        let starts = [[1.0_f64, 1.0], [2.0, 1.5], [0.5, 0.8]];
        let mut best: Option<(f64, [f64; 2])> = None;
        for s in &starts {
            let x0 = [s[0].ln(), s[1]];
            let opts = fsci_opt::MinimizeOptions {
                maxiter: Some(2000),
                maxfev: Some(4000),
                tol: Some(1e-9),
                ..Default::default()
            };
            if let Ok(res) = fsci_opt::nelder_mead(&nll, &x0, opts)
                && let Some(f) = res.fun
                && f.is_finite()
                && best.as_ref().is_none_or(|(bf, _)| f < *bf)
            {
                best = Some((f, [res.x[0].exp(), res.x[1]]));
            }
        }
        match best {
            Some((_, p)) if p[0] > 0.0 && p[1].abs() > 1e-8 && p.iter().all(|v| v.is_finite()) => {
                Ok(Self { a: p[0], c: p[1] })
            }
            _ => Err(FitError::NonConvergent(
                "GenGamma MLE failed to converge".to_owned(),
            )),
        }
    }

    fn skewness(&self) -> f64 {
        let a = self.a;
        let c = self.c;
        let g1 = (ln_gamma(a + 1.0 / c) - ln_gamma(a)).exp();
        let g2 = (ln_gamma(a + 2.0 / c) - ln_gamma(a)).exp();
        let g3 = (ln_gamma(a + 3.0 / c) - ln_gamma(a)).exp();
        let mu = g1;
        let var = g2 - g1 * g1;
        let sigma = var.sqrt();
        (g3 - 3.0 * mu * var - mu * mu * mu) / (sigma * sigma * sigma)
    }

    fn kurtosis(&self) -> f64 {
        let a = self.a;
        let c = self.c;
        let g1 = (ln_gamma(a + 1.0 / c) - ln_gamma(a)).exp();
        let g2 = (ln_gamma(a + 2.0 / c) - ln_gamma(a)).exp();
        let g3 = (ln_gamma(a + 3.0 / c) - ln_gamma(a)).exp();
        let g4 = (ln_gamma(a + 4.0 / c) - ln_gamma(a)).exp();
        let mu = g1;
        let var = g2 - g1 * g1;
        let mu4 = g4 - 4.0 * mu * g3 + 6.0 * mu * mu * g2 - 3.0 * mu.powi(4);
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        let a = self.a;
        let c = self.c;
        if c * a >= 1.0 {
            ((c * a - 1.0) / c).powf(1.0 / c)
        } else {
            0.0
        }
    }
}

// ══════════════════════════════════════════════════════════════════════
// Weibull Distribution
// ══════════════════════════════════════════════════════════════════════

/// Weibull (minimum) distribution with shape `c` and scale `scale`.
///
/// Matches `scipy.stats.weibull_min(c, scale=scale)`.
/// PDF: f(x) = (c/scale) * (x/scale)^(c-1) * exp(-(x/scale)^c)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Weibull {
    pub c: f64,
    pub scale: f64,
}

impl Weibull {
    #[must_use]
    pub fn new(c: f64, scale: f64) -> Self {
        assert!(c > 0.0, "shape c must be positive, got {c}");
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { c, scale }
    }

    /// Inverse CDF (analytic).
    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // ln(1 - q) via ln_1p(-q) avoids cancellation for small q.
        self.scale * (-(-q).ln_1p()).powf(1.0 / self.c)
    }
}

/// Same-binary A/B toggle for `Weibull::fit`: when `true`, the MLE Newton loop
/// recomputes `x.powf(c)` each iteration (powf recomputes `ln(x)`); when `false`
/// (default) it reuses the precomputed `ln_data` as `(c·lx).exp()`, dropping one
/// `ln` per element per iteration. Agrees to ~1e-15; the fixed point is unchanged.
pub static WEIBULL_FIT_LN_REUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Same-binary A/B toggle for the Weibull/WeibullMax density shape factors.
pub static WEIBULL_DENSITY_REUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

#[inline]
fn weibull_density_reuse() -> bool {
    !WEIBULL_DENSITY_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed)
}

/// Weibull-family pdf shape factor `base^(c−1)·exp(−base^c)` (base > 0). Computes
/// `bc = base^c` once, so `base^(c−1) = bc/base` — ONE `powf` instead of two.
#[inline]
fn weibull_pdf_shape(base: f64, c: f64, reuse: bool) -> f64 {
    if reuse {
        let bc = base.powf(c);
        (bc / base) * (-bc).exp()
    } else {
        base.powf(c - 1.0) * (-base.powf(c)).exp()
    }
}

/// Weibull-family logpdf shape term `(c−1)·ln(base) − base^c` (base > 0). Reuses a
/// single `ln(base)` (so `base^c = exp(c·ln(base))`) — ONE `ln` instead of two.
#[inline]
fn weibull_logpdf_shape(base: f64, c: f64, reuse: bool) -> f64 {
    if reuse {
        let lb = base.ln();
        (c - 1.0) * lb - (c * lb).exp()
    } else {
        (c - 1.0) * base.ln() - base.powf(c)
    }
}

impl ContinuousDistribution for Weibull {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.c == 1.0 {
                1.0 / self.scale
            } else if self.c > 1.0 {
                0.0
            } else {
                f64::INFINITY
            };
        }
        let z = x / self.scale;
        (self.c / self.scale) * weibull_pdf_shape(z, self.c, weibull_density_reuse())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c/scale) + (c−1)·ln(z) − z^c, z = x/scale; finite in the tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        if x == 0.0 {
            return if self.c == 1.0 {
                -self.scale.ln()
            } else if self.c > 1.0 {
                f64::NEG_INFINITY
            } else {
                f64::INFINITY
            };
        }
        let z = x / self.scale;
        (self.c / self.scale).ln() + weibull_logpdf_shape(z, self.c, weibull_density_reuse())
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        -(-(x / self.scale).powf(self.c)).exp_m1()
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        (-(x / self.scale).powf(self.c)).exp()
    }

    fn logsf(&self, x: f64) -> f64 {
        // logsf = -(x/scale)^c; the default ln(sf) underflows to -inf once sf->0
        // (weibull_min(1.5).logsf(200)=-inf vs scipy -2828).
        if x <= 0.0 {
            return 0.0;
        }
        -(x / self.scale).powf(self.c)
    }

    fn ppf(&self, q: f64) -> f64 {
        Weibull::ppf(self, q)
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // sf(x)=exp(−(x/scale)^c)=q ⇒ x=scale·(−ln q)^(1/c). The trait default
        // ppf(1−q) recomputes 1−(1−q) and cancels for small q (isf(1e-12) was
        // ~5e-7 off scipy). Matches scipy.stats.weibull_min.isf. frankenscipy-d2gag
        self.scale * (-q.ln()).powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        self.scale * ln_gamma(1.0 + 1.0 / self.c).exp()
    }

    fn var(&self) -> f64 {
        let g1 = ln_gamma(1.0 + 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / self.c).exp();
        self.scale * self.scale * (g2 - g1 * g1)
    }

    fn entropy(&self) -> f64 {
        // H = gamma_euler*(1 - 1/c) + ln(scale/c) + 1
        EULER_MASCHERONI * (1.0 - 1.0 / self.c) + (self.scale / self.c).ln() + 1.0
    }

    fn skewness(&self) -> f64 {
        let g1 = ln_gamma(1.0 + 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / self.c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / self.c).exp();
        let var = g2 - g1 * g1;
        let std = var.sqrt();
        (g3 - 3.0 * g1 * var - g1.powi(3)) / std.powi(3)
    }

    fn kurtosis(&self) -> f64 {
        let g1 = ln_gamma(1.0 + 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / self.c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / self.c).exp();
        let g4 = ln_gamma(1.0 + 4.0 / self.c).exp();
        let var = g2 - g1 * g1;
        let skew_num = g3 - 3.0 * g1 * var - g1.powi(3);
        (g4 - 4.0 * g1 * skew_num - 6.0 * g1 * g1 * var - g1.powi(4)) / var.powi(2) - 3.0
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|v| !v.is_finite() || *v <= 0.0) {
            return Self {
                c: f64::NAN,
                scale: f64::NAN,
            };
        }
        let n = data.len() as f64;
        let ln_data: Vec<f64> = data.iter().map(|&x| x.ln()).collect();
        let mean_ln: f64 = ln_data.iter().sum::<f64>() / n;
        // powf(x,c) = exp(c·ln(x)); ln(x) is already in `ln_data`, so reuse it and
        // drop powf's internal `ln` on every element of every Newton iteration.
        let reuse = !WEIBULL_FIT_LN_REUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed);
        let pow_c = |c: f64| -> Vec<f64> {
            if reuse {
                ln_data.iter().map(|&lx| (c * lx).exp()).collect()
            } else {
                data.iter().map(|&x| x.powf(c)).collect()
            }
        };

        let mut c = 1.0;
        for _ in 0..50 {
            let xc: Vec<f64> = pow_c(c);
            let sum_xc: f64 = xc.iter().sum();
            let sum_xc_ln: f64 = xc.iter().zip(ln_data.iter()).map(|(&x, &lx)| x * lx).sum();
            let f = 1.0 / c + mean_ln - sum_xc_ln / sum_xc;
            if f.abs() < 1e-10 {
                break;
            }
            let sum_xc_ln2: f64 = xc
                .iter()
                .zip(ln_data.iter())
                .map(|(&x, &lx)| x * lx * lx)
                .sum();
            let df =
                -1.0 / (c * c) - (sum_xc * sum_xc_ln2 - sum_xc_ln * sum_xc_ln) / (sum_xc * sum_xc);
            if df.abs() < 1e-15 {
                break;
            }
            c -= f / df;
            c = c.max(1e-6);
        }
        let xc_sum: f64 = pow_c(c).iter().sum();
        let scale = (xc_sum / n).powf(1.0 / c);
        Self { c, scale }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        if let Some(&x) = data.iter().find(|&&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(format!(
                "Weibull fit data contains non-finite value: {x}"
            )));
        }
        if let Some(&x) = data.iter().find(|&&x| x <= 0.0) {
            return Err(FitError::UnsupportedData(format!(
                "Weibull support is (0, infinity); got {x}"
            )));
        }

        let fitted = Self::fit(data);
        if fitted.c.is_finite() && fitted.c > 0.0 && fitted.scale.is_finite() && fitted.scale > 0.0
        {
            Ok(fitted)
        } else {
            Err(FitError::NonConvergent(
                "Weibull MLE could not estimate positive shape and scale".to_owned(),
            ))
        }
    }

    fn mode(&self) -> f64 {
        // Standard Weibull(c, scale): mode = scale·((c−1)/c)^{1/c} for
        // c > 1, else the pdf is monotone decreasing and the mode
        // collapses to the boundary 0 (frankenscipy-tlw2q).
        if self.c > 1.0 {
            self.scale * ((self.c - 1.0) / self.c).powf(1.0 / self.c)
        } else {
            0.0
        }
    }
}

/// Reverse Weibull (sign-flipped) distribution with shape `c > 0`.
///
/// Matches `scipy.stats.weibull_max(c)`. Resolves [frankenscipy-9nttn].
/// Distribution of `-X` for `X ~ weibull_min(c)`. Support: x ≤ 0.
///
///   pdf(x; c) = c · (−x)^(c − 1) · exp(−(−x)^c)   for x ≤ 0
///   cdf(x; c) = exp(−(−x)^c)
///   sf(x; c)  = 1 − exp(−(−x)^c)
///   ppf(q; c) = −(−ln q)^(1/c)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct WeibullMax {
    pub c: f64,
}

impl WeibullMax {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0 && c.is_finite(), "c must be positive and finite");
        Self { c }
    }
}

impl ContinuousDistribution for WeibullMax {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x > 0.0 || !x.is_finite() {
            return 0.0;
        }
        if x == 0.0 {
            // Limit depends on c: c<1 → ∞, c=1 → 1, c>1 → 0.
            // scipy returns 0 here (boundary); follow that.
            return 0.0;
        }
        let c = self.c;
        let neg = -x;
        c * weibull_pdf_shape(neg, c, weibull_density_reuse())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // Support x<0; ln(c) + (c−1)·ln(−x) − (−x)^c. x≥0 delegates to pdf. frankenscipy-p82v7
        if x >= 0.0 || !x.is_finite() {
            return self.pdf(x).ln();
        }
        let neg = -x;
        self.c.ln() + weibull_logpdf_shape(neg, self.c, weibull_density_reuse())
    }

    fn cdf(&self, x: f64) -> f64 {
        if x >= 0.0 {
            return 1.0;
        }
        if !x.is_finite() {
            return 0.0;
        }
        let c = self.c;
        (-((-x).powf(c))).exp()
    }

    fn sf(&self, x: f64) -> f64 {
        // Support x≤0; sf = 1 − exp(−(−x)^c) = −expm1(−(−x)^c), stable as x→0⁻
        // where cdf→1 and the default 1−cdf collapses. frankenscipy-w3f6m
        if x >= 0.0 {
            return 0.0;
        }
        if !x.is_finite() {
            return 1.0;
        }
        -(-((-x).powf(self.c))).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        let c = self.c;
        -((-q.ln()).powf(1.0 / c))
    }

    fn mean(&self) -> f64 {
        // E[X] = -E[Y] where Y ~ weibull_min(c) → -Γ(1 + 1/c).
        -ln_gamma(1.0 + 1.0 / self.c).exp()
    }

    fn var(&self) -> f64 {
        // Var(X) = Var(Y) (sign flip preserves variance).
        let g1 = ln_gamma(1.0 + 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / self.c).exp();
        g2 - g1 * g1
    }

    fn entropy(&self) -> f64 {
        // WeibullMax(c) = -WeibullMin(c, scale=1); entropy is
        // reflection-invariant (h(-X) = h(X)), so it matches
        // Weibull(c, 1) entropy = γ(1 - 1/c) - ln(c) + 1.
        EULER_MASCHERONI * (1.0 - 1.0 / self.c) - self.c.ln() + 1.0
    }

    fn skewness(&self) -> f64 {
        // WeibullMax(c) = -WeibullMin(c). Sign flip negates skewness.
        // (frankenscipy-lu2e1)
        let c = self.c;
        let g1 = ln_gamma(1.0 + 1.0 / c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / c).exp();
        let var = g2 - g1 * g1;
        let mu3 = g3 - 3.0 * g1 * g2 + 2.0 * g1 * g1 * g1;
        -mu3 / var.powf(1.5) // negation: mirror flips skew
    }

    fn kurtosis(&self) -> f64 {
        // Kurtosis is invariant under sign-flip — identical to WeibullMin.
        // (frankenscipy-lu2e1)
        let c = self.c;
        let g1 = ln_gamma(1.0 + 1.0 / c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / c).exp();
        let g4 = ln_gamma(1.0 + 4.0 / c).exp();
        let var = g2 - g1 * g1;
        let mu4 = g4 - 4.0 * g1 * g3 + 6.0 * g1 * g1 * g2 - 3.0 * g1 * g1 * g1 * g1;
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        // WeibullMax is the sign-flip of WeibullMin, so its mode lives
        // at −Weibull mode (frankenscipy-tlw2q).
        if self.c > 1.0 {
            -((self.c - 1.0) / self.c).powf(1.0 / self.c)
        } else {
            0.0
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // WeibullMax has support (−∞, 0] with PDF c·(−x)^{c−1}·exp(−(−x)^c)
        // and CDF exp(−(−x)^c). Setting y = −x maps to the standard
        // Weibull (scale = 1) on positive reals, so MLE for shape c
        // matches the standard-Weibull MLE on −data.
        validate_finite_fit_data(data, 2, "WeibullMax")?;
        if let Some(&bad) = data.iter().find(|&&x| x > 0.0) {
            return Err(FitError::UnsupportedData(format!(
                "WeibullMax support is (−∞, 0]; got {bad}"
            )));
        }
        // Negate; reject x == 0 since the log-likelihood is −∞ there
        // for c < 1 and the standard MLE assumes strictly positive y.
        let mut negated: Vec<f64> = Vec::with_capacity(data.len());
        for &x in data {
            let y = -x;
            if y <= 0.0 {
                return Err(FitError::UnsupportedData(
                    "WeibullMax fit requires every sample to be strictly negative".to_owned(),
                ));
            }
            negated.push(y);
        }
        let c = fit_standard_weibull_shape_mle(&negated, "WeibullMax")?;
        Ok(Self { c })
    }
}

// ══════════════════════════════════════════════════════════════════════
// Lognormal Distribution
// ══════════════════════════════════════════════════════════════════════

/// Lognormal distribution: X = exp(μ + σZ) where Z ~ N(0,1).
///
/// Matches `scipy.stats.lognorm(s, scale=exp(mu))` where s=σ.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Lognormal {
    /// Shape parameter σ (standard deviation of the underlying normal).
    pub s: f64,
    /// Scale parameter (= exp(μ)).
    pub scale: f64,
}

impl Lognormal {
    #[must_use]
    pub fn new(s: f64, scale: f64) -> Self {
        assert!(s > 0.0, "s must be positive, got {s}");
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { s, scale }
    }
}

impl ContinuousDistribution for Lognormal {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let z = (x / self.scale).ln() / self.s;
        (-0.5 * z * z).exp() / (x * self.s * (2.0 * PI).sqrt())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −z²/2 − ln(x) − ln(s) − ½ln(2π), z = ln(x/scale)/s; finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let z = (x / self.scale).ln() / self.s;
        -0.5 * z * z - x.ln() - self.s.ln() - 0.5 * (2.0 * PI).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // Delegate to standard_normal_cdf for deep-tail precision
        // (very small x → very negative z → catastrophic cancellation
        // in the naïve 0.5·(1 + erf) form). Resolves [frankenscipy-tkpgq].
        let z = (x / self.scale).ln() / self.s;
        standard_normal_cdf(z)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log Φ(z), z = ln(x/scale)/s; finite in the left tail. frankenscipy-osnge
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_ndtr_scalar((x / self.scale).ln() / self.s)
    }

    fn sf(&self, x: f64) -> f64 {
        // Survival Φ(−z) = ½·erfc(z/√2) directly — the default 1−cdf returned 0
        // in the deep right tail (lognorm.sf(1e4,1) scipy 1.6e-20). frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        let z = (x / self.scale).ln() / self.s;
        0.5 * fsci_special::erfc_scalar(z * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = log Φ(−z), z = ln(x/scale)/s; log_ndtr stays finite in the
        // ultra-extreme tail where ln(sf) would be −inf. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        let z = (x / self.scale).ln() / self.s;
        fsci_special::log_ndtr_scalar(-z)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // If X ~ Lognormal(mu, sigma), then ln(X) ~ Normal(mu, sigma)
        // ppf(q) = exp(mu + sigma * ndtri(q)) where mu = ln(scale)
        self.scale * (self.s * fsci_special::ndtri_scalar(q)).exp()
    }

    fn mean(&self) -> f64 {
        self.scale * (0.5 * self.s * self.s).exp()
    }

    fn var(&self) -> f64 {
        let s2 = self.s * self.s;
        self.scale * self.scale * s2.exp() * (s2.exp() - 1.0)
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
            return Self {
                s: f64::NAN,
                scale: f64::NAN,
            };
        }
        let n = data.len() as f64;
        let log_data: Vec<f64> = data.iter().map(|&x| x.ln()).collect();
        let mu = log_data.iter().sum::<f64>() / n;
        let var = log_data.iter().map(|&lx| (lx - mu).powi(2)).sum::<f64>() / n;
        Self {
            s: var.sqrt(),
            scale: mu.exp(),
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
            return Err(FitError::UnsupportedData(
                "Lognormal requires positive finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.s.is_finite() || !fitted.scale.is_finite() {
            return Err(FitError::NonConvergent(
                "Lognormal fit produced non-finite parameters".into(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        // H = 0.5 + 0.5*ln(2*pi) + ln(s) + ln(scale)
        0.5 + 0.5 * (2.0 * PI).ln() + self.s.ln() + self.scale.ln()
    }

    fn skewness(&self) -> f64 {
        let es2 = (self.s * self.s).exp();
        (es2 + 2.0) * (es2 - 1.0).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        let s2 = self.s * self.s;
        (4.0 * s2).exp() + 2.0 * (3.0 * s2).exp() + 3.0 * (2.0 * s2).exp() - 6.0
    }

    fn mode(&self) -> f64 {
        // Lognormal mode = scale · exp(-s²) = exp(μ - σ²) where
        // μ = ln(scale), σ = s [frankenscipy-cxgdg].
        self.scale * (-self.s * self.s).exp()
    }
}

// ══════════════════════════════════════════════════════════════════════
// Gibrat Distribution
// ══════════════════════════════════════════════════════════════════════

/// Gibrat continuous random variable.
///
/// Matches `scipy.stats.gibrat`. Special case of Lognormal with s=1.
/// PDF: f(x) = exp(-0.5 * ln(x)^2) / (x * sqrt(2*pi)) for x > 0.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Gibrat;

impl Gibrat {
    #[must_use]
    pub const fn new() -> Self {
        Self
    }
}

impl ContinuousDistribution for Gibrat {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let lnx = x.ln();
        (-0.5 * lnx * lnx).exp() / (x * (2.0 * PI).sqrt())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −½·(ln x)² − ln(x) − ½ln(2π); finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let lnx = x.ln();
        -0.5 * lnx * lnx - lnx - 0.5 * (2.0 * PI).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        standard_normal_cdf(x.ln())
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log Φ(ln x); finite in the left tail where Φ underflows to 0. frankenscipy-osnge
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_ndtr_scalar(x.ln())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Φ(−ln x) = ½·erfc(ln x/√2); direct so the right tail does not
        // collapse like the default 1−cdf. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        0.5 * fsci_special::erfc_scalar(x.ln() * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = log Φ(−ln x); finite in the ultra-extreme tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_ndtr_scalar(-x.ln())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        fsci_special::ndtri_scalar(q).exp()
    }

    fn mean(&self) -> f64 {
        core::f64::consts::E.sqrt()
    }

    fn var(&self) -> f64 {
        core::f64::consts::E * (core::f64::consts::E - 1.0)
    }

    fn fit(_data: &[f64]) -> Self {
        Self
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
            return Err(FitError::UnsupportedData(
                "Gibrat requires positive finite samples".into(),
            ));
        }
        Ok(Self)
    }

    fn entropy(&self) -> f64 {
        0.5 + 0.5 * (2.0 * PI).ln()
    }

    fn skewness(&self) -> f64 {
        (core::f64::consts::E + 2.0) * (core::f64::consts::E - 1.0).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        core::f64::consts::E.powi(4)
            + 2.0 * core::f64::consts::E.powi(3)
            + 3.0 * core::f64::consts::E.powi(2)
            - 6.0
    }

    fn mode(&self) -> f64 {
        (-1.0_f64).exp()
    }
}

// ══════════════════════════════════════════════════════════════════════
// Pareto Distribution
// ══════════════════════════════════════════════════════════════════════

/// Pareto distribution with shape `b` and scale `scale`.
///
/// Matches `scipy.stats.pareto(b, scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Pareto {
    pub b: f64,
    pub scale: f64,
}

impl Pareto {
    #[must_use]
    pub fn new(b: f64, scale: f64) -> Self {
        assert!(b > 0.0, "shape b must be positive, got {b}");
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { b, scale }
    }
}

impl ContinuousDistribution for Pareto {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < self.scale {
            0.0
        } else {
            self.b * self.scale.powf(self.b) / x.powf(self.b + 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(b) + b·ln(scale) − (b+1)·ln(x); finite in the power-law tail. frankenscipy-p82v7
        if x < self.scale {
            return f64::NEG_INFINITY;
        }
        self.b.ln() + self.b * self.scale.ln() - (self.b + 1.0) * x.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < self.scale {
            0.0
        } else {
            1.0 - (self.scale / x).powf(self.b)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-h36zm]:
        //   sf(x) = (scale / x)^b   for x ≥ scale.
        // The default 1 - (1 - (scale/x)^b) loses all precision in
        // the deep right tail where (scale/x)^b ≈ 0.
        if x < self.scale {
            1.0
        } else {
            (self.scale / x).powf(self.b)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.scale;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        self.scale / (1.0 - q).powf(1.0 / self.b)
    }

    fn mean(&self) -> f64 {
        if self.b <= 1.0 {
            f64::INFINITY
        } else {
            self.b * self.scale / (self.b - 1.0)
        }
    }

    fn var(&self) -> f64 {
        if self.b <= 2.0 {
            f64::INFINITY
        } else {
            self.scale * self.scale * self.b / ((self.b - 1.0).powi(2) * (self.b - 2.0))
        }
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
            return Self {
                b: f64::NAN,
                scale: f64::NAN,
            };
        }

        let scale = data.iter().copied().fold(f64::INFINITY, f64::min);
        let log_sum = data.iter().map(|&x| (x / scale).ln()).sum::<f64>();
        let b = if log_sum == 0.0 {
            f64::INFINITY
        } else {
            data.len() as f64 / log_sum
        };
        Self { b, scale }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-covaj]: typed-error counterpart to fit().
        // Pareto MLE: scale = min(data), b = N / Σ ln(x_i / scale).
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
            return Err(FitError::UnsupportedData(
                "Pareto fit requires positive finite samples".into(),
            ));
        }
        let scale = data.iter().copied().fold(f64::INFINITY, f64::min);
        let log_sum = data.iter().map(|&x| (x / scale).ln()).sum::<f64>();
        let b = if log_sum == 0.0 {
            f64::INFINITY
        } else {
            data.len() as f64 / log_sum
        };
        Ok(Self { b, scale })
    }

    fn mode(&self) -> f64 {
        // Pareto mode = scale (lower endpoint of support) [frankenscipy-cxgdg].
        self.scale
    }

    fn entropy(&self) -> f64 {
        // H(Pareto) = ln(scale/b) + 1/b + 1 [frankenscipy-vngzr].
        (self.scale / self.b).ln() + 1.0 / self.b + 1.0
    }

    fn skewness(&self) -> f64 {
        // Pareto skewness = 2·(1+b)/(b-3)·√((b-2)/b) for b > 3;
        // NaN otherwise (third moment doesn't exist) [frankenscipy-y718j].
        if self.b > 3.0 {
            2.0 * (1.0 + self.b) / (self.b - 3.0) * ((self.b - 2.0) / self.b).sqrt()
        } else {
            f64::NAN
        }
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 6(b³ + b² − 6b − 2) / (b(b-3)(b-4)) for b > 4;
        // NaN otherwise (fourth moment diverges). (frankenscipy-026b5)
        if self.b > 4.0 {
            let b = self.b;
            6.0 * (b * b * b + b * b - 6.0 * b - 2.0) / (b * (b - 3.0) * (b - 4.0))
        } else {
            f64::NAN
        }
    }
}

/// Lomax distribution.
///
/// Matches `scipy.stats.lomax(c)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Lomax {
    pub c: f64,
}

impl Lomax {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "shape c must be positive, got {c}");
        Self { c }
    }
}

impl ContinuousDistribution for Lomax {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            self.c / (1.0 + x).powf(self.c + 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) − (c+1)·ln1p(x); finite in the power-law tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        self.c.ln() - (self.c + 1.0) * x.ln_1p()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            -(-self.c * x.ln_1p()).exp_m1()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-h36zm]:
        //   sf(x) = (1 + x)^(-c) = exp(-c · ln(1+x))   for x ≥ 0.
        // The default 1 - cdf would re-add the cancelling pair
        // (1 - exp_m1(...)) and lose precision deep in the tail.
        if x < 0.0 {
            1.0
        } else {
            (-self.c * x.ln_1p()).exp()
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // ln sf = −c·ln(1+x). The default ln(sf) returns −inf once sf=(1+x)^−c
        // underflows below ~1e-308 (lomax(3).logsf(1e150) was −inf vs −1036.16).
        // frankenscipy-zghyi
        if x < 0.0 { 0.0 } else { -self.c * x.ln_1p() }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        (-(-q).ln_1p() / self.c).exp_m1()
    }

    fn mean(&self) -> f64 {
        if self.c <= 1.0 {
            f64::INFINITY
        } else {
            1.0 / (self.c - 1.0)
        }
    }

    fn var(&self) -> f64 {
        if self.c <= 2.0 {
            f64::INFINITY
        } else {
            self.c / ((self.c - 1.0).powi(2) * (self.c - 2.0))
        }
    }

    fn skewness(&self) -> f64 {
        // Lomax (Pareto-Type-II with location -1) inherits Pareto's
        // shape-only third-moment formula: 2·(1+c)/(c-3)·√((c-2)/c)
        // for c > 3. (frankenscipy-3moif)
        if self.c > 3.0 {
            2.0 * (1.0 + self.c) / (self.c - 3.0) * ((self.c - 2.0) / self.c).sqrt()
        } else {
            f64::NAN
        }
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 6(c³+c²-6c-2) / (c(c-3)(c-4)) for c > 4.
        // (frankenscipy-3moif)
        if self.c > 4.0 {
            let c = self.c;
            6.0 * (c * c * c + c * c - 6.0 * c - 2.0) / (c * (c - 3.0) * (c - 4.0))
        } else {
            f64::NAN
        }
    }

    fn mode(&self) -> f64 {
        // Lomax pdf = α·(1+x)^{-(α+1)} on x ≥ 0 is strictly decreasing,
        // so the mode is the boundary 0 (frankenscipy-rt24d).
        0.0
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|v| !v.is_finite() || *v < 0.0) {
            return Self { c: f64::NAN };
        }
        let n = data.len() as f64;
        let log_sum: f64 = data.iter().map(|&x| (1.0 + x).ln()).sum();
        if log_sum <= 0.0 {
            return Self { c: f64::NAN };
        }
        Self { c: n / log_sum }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-covaj]: typed-error counterpart to fit().
        // Lomax MLE: c = N / Σ ln(1 + x_i).
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|v| !v.is_finite() || *v < 0.0) {
            return Err(FitError::UnsupportedData(
                "Lomax fit requires non-negative finite samples".into(),
            ));
        }
        let n = data.len() as f64;
        let log_sum: f64 = data.iter().map(|&x| (1.0 + x).ln()).sum();
        if log_sum <= 0.0 {
            return Err(FitError::NonConvergent(
                "Lomax fit: ln(1+x) sum is non-positive (degenerate sample)".into(),
            ));
        }
        Ok(Self { c: n / log_sum })
    }

    fn entropy(&self) -> f64 {
        // H(Lomax(c)) = 1 + 1/c − ln(c) for unit scale.
        // Derivation: pdf = c/(1+x)^(c+1); E[log(1+x)] = 1/c, so
        // H = -log(c) + (c+1)/c = 1 + 1/c − log(c). [frankenscipy-2ea4i].
        1.0 + 1.0 / self.c - self.c.ln()
    }
}

// ══════════════════════════════════════════════════════════════════════
// Normal-Inverse Gaussian Distribution
// ══════════════════════════════════════════════════════════════════════

/// Normal-Inverse Gaussian distribution.
///
/// Matches `scipy.stats.norminvgauss(a, b)`.
/// PDF: f(x) = (a/π) · K₁(a·√(1+x²)) · exp(b·x + γ) / √(1+x²)
/// where γ = √(a² - b²).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NormInvGauss {
    pub a: f64,
    pub b: f64,
}

impl NormInvGauss {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(b.abs() < a, "|b| must be < a, got b={b}, a={a}");
        Self { a, b }
    }

    fn gamma(&self) -> f64 {
        (self.a * self.a - self.b * self.b).sqrt()
    }
}

/// Illinois modified false-position root of an INCREASING `f` on `[lo, hi]` with
/// `flo = f(lo) <= 0 <= fhi = f(hi)`. Converges superlinearly (~12-15 evals) vs
/// bisection's ~50 — a large win when each `f` eval is expensive (e.g. inverting
/// the NormInvGauss cdf, which is a per-call adaptive quadrature). `mid` is seeded
/// NaN so a root on a bracket endpoint can't trigger a spurious first-iter return.
fn illinois_root_increasing(
    f: impl Fn(f64) -> f64,
    mut lo: f64,
    mut hi: f64,
    mut flo: f64,
    mut fhi: f64,
) -> f64 {
    let mut side = 0i32;
    let mut mid = f64::NAN;
    for _ in 0..80 {
        let denom = fhi - flo;
        let interp = if denom.is_finite() && denom != 0.0 {
            (lo * fhi - hi * flo) / denom
        } else {
            f64::NAN
        };
        let next = if interp > lo && interp < hi {
            interp
        } else {
            0.5 * (lo + hi)
        };
        let tol = 4.0 * f64::EPSILON * next.abs().max(1.0);
        if (next - mid).abs() <= tol || (hi - lo).abs() <= tol {
            return next;
        }
        mid = next;
        let fmid = f(mid);
        if fmid == 0.0 {
            return mid;
        }
        if fmid > 0.0 {
            hi = mid;
            fhi = fmid;
            if side == 1 {
                flo *= 0.5;
            }
            side = 1;
        } else {
            lo = mid;
            flo = fmid;
            if side == -1 {
                fhi *= 0.5;
            }
            side = -1;
        }
    }
    mid
}

impl ContinuousDistribution for NormInvGauss {
    fn pdf(&self, x: f64) -> f64 {
        if !x.is_finite() {
            return 0.0;
        }
        let a = self.a;
        let b = self.b;
        let gamma = self.gamma();
        let q = (1.0 + x * x).sqrt();
        let k1_arg = a * q;
        let k1_val = fsci_special::bessel::k1_scalar(k1_arg);
        (a / std::f64::consts::PI) * k1_val * (b * x + gamma).exp() / q
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(a) − ln(π) + ln K₁(a·q) + (b·x+γ) − ln(q), q=√(1+x²); ln K₁(z) =
        // ln(kve(1,z)) − z (kve is properly exp-scaled, finite past z≈745 where
        // K₁ underflows and the pdf collapses to NaN/0). frankenscipy-7m3xk
        if !x.is_finite() {
            return f64::NEG_INFINITY;
        }
        let a = self.a;
        let b = self.b;
        let gamma = self.gamma();
        let q = (1.0 + x * x).sqrt();
        let aq = a * q;
        let kve = fsci_special::bessel::kve_scalar(1.0, aq);
        if kve <= 0.0 || !kve.is_finite() {
            return f64::NEG_INFINITY;
        }
        a.ln() - std::f64::consts::PI.ln() + (kve.ln() - aq) + (b * x + gamma) - q.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x == f64::NEG_INFINITY {
            return 0.0;
        }
        if x == f64::INFINITY {
            return 1.0;
        }
        // The NIG cdf is ∫_{-∞}^x pdf. The left tail decays exponentially at rate
        // a+b (>0 since |b|<a). The bulk window [mean−20σ, x] integrates fine, but
        // for x far in the left tail it sat ABOVE x — the window inverted and the
        // integral clamped to 0 (cdf(-60) = 0 vs scipy ~1e-42). There the integrand
        // is concentrated just below x, so integrate a local window [x−W, x] with
        // W ≈ 25/(a+b) e-foldings (captures the mass to ~1e-11; the deeper tail is
        // negligible). abs_tol = 0 lets a tiny tail integral converge on relative
        // error instead of stopping at the first refinement. frankenscipy-vk2l2
        // Integrate the (smooth, unimodal, Bessel-K) pdf with the adaptive
        // Gauss-Kronrod `quad` (QUADPACK-style). The former `simpson_integrate_adaptive`
        // UNIFORMLY doubled the grid, so resolving this peaked integrand over the wide
        // [mean−20σ, x] window took ~8000 pdf(=Bessel-K) evals (~940µs); Gauss-Kronrod
        // concentrates nodes at the peak and reaches the same tolerance in ~10-30× fewer.
        let sigma = self.var().sqrt();
        let bulk_lower = (self.mean() - 20.0 * sigma).max(-100.0);
        if x < bulk_lower {
            let window = (25.0 / (self.a + self.b)).clamp(1.0, 200.0);
            return fsci_integrate::quad(
                |t| self.pdf(t),
                x - window,
                x,
                fsci_integrate::QuadOptions {
                    epsabs: 0.0,
                    epsrel: 1e-10,
                    limit: 100,
                },
            )
            .map(|r| r.integral)
            .unwrap_or(0.0)
            .clamp(0.0, 1.0);
        }
        let upper = x.min(self.mean() + 50.0 * sigma);
        fsci_integrate::quad(
            |t| self.pdf(t),
            bulk_lower,
            upper,
            fsci_integrate::QuadOptions {
                epsabs: 1e-13,
                epsrel: 1e-10,
                limit: 100,
            },
        )
        .map(|r| r.integral)
        .unwrap_or(0.0)
        .clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let mu = self.mean();
        let sigma = self.var().sqrt();
        let mut lo = mu - 10.0 * sigma;
        let mut hi = mu + 10.0 * sigma;
        // Illinois false-position over the (expensive per-call, adaptive-quadrature)
        // cdf — ~12-15 cdf evals vs the former fixed 60-step bisection. The cdf is
        // increasing, so f(x)=cdf(x)−q is increasing with f(lo)≤0≤f(hi) once the
        // bracket straddles q; if not (extreme tail), fall back to bisection on the
        // same bracket (identical endpoint-clamping behaviour as before).
        let flo = self.cdf(lo) - q;
        let fhi = self.cdf(hi) - q;
        if flo.is_finite() && fhi.is_finite() && flo <= 0.0 && fhi >= 0.0 {
            return illinois_root_increasing(|x| self.cdf(x) - q, lo, hi, flo, fhi);
        }
        for _ in 0..60 {
            let mid = 0.5 * (lo + hi);
            if self.cdf(mid) < q {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        0.5 * (lo + hi)
    }

    fn mean(&self) -> f64 {
        self.b / self.gamma()
    }

    fn var(&self) -> f64 {
        let gamma = self.gamma();
        self.a * self.a / (gamma * gamma * gamma)
    }

    fn fit(_data: &[f64]) -> Self {
        Self {
            a: f64::NAN,
            b: f64::NAN,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Method-of-moments fit (standardized NIG, loc=0/scale=1), consistent
        // with the crate's pragmatic per-distribution estimators. With
        // gamma = sqrt(a^2 - b^2): E[X] = b/gamma and Var[X] = a^2/gamma^3.
        // Letting s = 1 + mean^2, these invert in closed form to
        //   gamma = s/var,  a = s^1.5/var,  b = mean*s/var
        // (NIG support is all of R, so negative observations are valid).
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let n = data.len() as f64;
        let mut sum = 0.0;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "NormInvGauss data contains non-finite value: {x}"
                )));
            }
            sum += x;
        }
        let mean = sum / n;
        let var = data.iter().map(|&x| (x - mean) * (x - mean)).sum::<f64>() / n;
        if !var.is_finite() || var <= 0.0 {
            return Err(FitError::NonConvergent(
                "NormInvGauss fit requires a positive sample variance".to_owned(),
            ));
        }
        let s = 1.0 + mean * mean;
        let a = s.powf(1.5) / var;
        let b = mean * s / var;
        if !a.is_finite() || a <= 0.0 || !b.is_finite() || b.abs() >= a {
            return Err(FitError::NonConvergent(format!(
                "NormInvGauss MoM produced invalid parameters: a={a}, b={b}"
            )));
        }
        Ok(Self { a, b })
    }

    fn skewness(&self) -> f64 {
        let gamma = self.gamma();
        3.0 * self.b / (self.a * gamma.sqrt())
    }

    fn kurtosis(&self) -> f64 {
        // Excess (Fisher) kurtosis of NIG: 3(1 + 4β²/α²)/(δγ) with δ=1. This
        // closed form is ALREADY the excess kurtosis — scipy.stats.norminvgauss
        // .stats('k') returns exactly this — so it must NOT have a further 3
        // subtracted (the old `- 3.0` drove e.g. norminvgauss(1,0.5) to 3.928
        // vs scipy 6.928, and even produced impossible negatives).
        let gamma = self.gamma();
        let a2 = self.a * self.a;
        let b2 = self.b * self.b;
        3.0 * (1.0 + 4.0 * b2 / a2) / gamma
    }

    fn entropy(&self) -> f64 {
        // Differential entropy h = −∫ f ln f has no closed form for NIG; scipy
        // computes it by numerical integration too. Integrate over a wide window
        // (the tails decay exponentially at rate a∓b), using the accurate logpdf
        // so the −f·ln f integrand stays valid deep in the tails. frankenscipy.
        let sigma = self.var().sqrt();
        let mu = self.mean();
        let lo = mu - 60.0 * sigma;
        let hi = mu + 60.0 * sigma;
        simpson_integrate_adaptive(
            |x| {
                let f = self.pdf(x);
                if f > 0.0 { -f * self.logpdf(x) } else { 0.0 }
            },
            lo,
            hi,
            128,
            1e-11,
            1e-14,
            16,
        )
    }

    fn mode(&self) -> f64 {
        f64::NAN
    }
}

// ══════════════════════════════════════════════════════════════════════
// Relativistic Breit-Wigner Distribution
// ══════════════════════════════════════════════════════════════════════

/// Relativistic Breit-Wigner distribution.
///
/// Matches `scipy.stats.rel_breitwigner(rho)`.
/// PDF: f(k) = k / ((1 - k²)² + ρ²) × normalization for k > 0.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RelBreitWigner {
    pub rho: f64,
}

impl RelBreitWigner {
    #[must_use]
    pub fn new(rho: f64) -> Self {
        assert!(
            rho > 0.0 && rho.is_finite(),
            "rho must be positive and finite, got {rho}"
        );
        Self { rho }
    }

    /// Normalizing constant `k` from SciPy's `rel_breitwigner` definition:
    /// k = 2*sqrt(2)*rho^2*sqrt(rho^2+1) / (pi*sqrt(rho^2 + rho*sqrt(rho^2+1))).
    fn k_const(&self) -> f64 {
        let r2 = self.rho * self.rho;
        let s = (r2 + 1.0).sqrt();
        2.0 * std::f64::consts::SQRT_2 * r2 * s / (PI * (r2 + self.rho * s).sqrt())
    }
}

impl ContinuousDistribution for RelBreitWigner {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        // SciPy: f(x, rho) = k / ((x^2 - rho^2)^2 + rho^2). The resonance peak
        // is at x = rho (not a fixed x = 1).
        let r2 = self.rho * self.rho;
        let d = x * x - r2;
        self.k_const() / (d * d + r2)
    }

    fn cdf(&self, k: f64) -> f64 {
        if k <= 0.0 {
            return 0.0;
        }
        // Closed form: the pdf k_c/((x²−ρ²)²+ρ²) is rational. Factor the quartic
        // as (x²−2αx+β)(x²+2αx+β), β=ρ√(ρ²+1), α=√((β+ρ²)/2), γ=√((β−ρ²)/2);
        // then F(x)=k_c·[−ln(Q/R)/(8αβ) + (atan((x−α)/γ)+atan((x+α)/γ))/(4βγ)],
        // Q=x²−2αx+β, R=x²+2αx+β. Replaces the adaptive Simpson over the sharply
        // peaked pdf (~3e-7 off for small ρ); now ~1e-14 vs scipy.
        // frankenscipy-hh2zz
        let rho = self.rho;
        let r2 = rho * rho;
        let beta = rho * (r2 + 1.0).sqrt();
        let alpha = ((beta + r2) / 2.0).sqrt();
        let gamma = ((beta - r2) / 2.0).sqrt();
        let x = k;
        let q = (x - alpha).mul_add(x - alpha, beta - alpha * alpha); // x²−2αx+β
        let r = (x + alpha).mul_add(x + alpha, beta - alpha * alpha); // x²+2αx+β
        let val = -(q / r).ln() / (8.0 * alpha * beta)
            + (((x - alpha) / gamma).atan() + ((x + alpha) / gamma).atan()) / (4.0 * beta * gamma);
        (self.k_const() * val).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let mut lo = 1e-10;
        let mut hi = 10.0;
        while self.cdf(hi) < q && hi < 1e10 {
            hi *= 2.0;
        }
        for _ in 0..60 {
            let mid = 0.5 * (lo + hi);
            if self.cdf(mid) < q {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        0.5 * (lo + hi)
    }

    fn mean(&self) -> f64 {
        // E[X] = ∫₀^∞ x f(x) dx. The pdf decays as k/x^4, so x·f ~ k/x^3 and
        // the tail beyond b contributes ≈ k/(2 b^2); add it analytically since
        // truncating the heavy tail otherwise converges slowly.
        let b = (200.0 * self.rho).max(200.0);
        let body = simpson_integrate_adaptive(|x| x * self.pdf(x), 0.0, b, 256, 1e-12, 1e-14, 20);
        body + self.k_const() / (2.0 * b * b)
    }

    fn var(&self) -> f64 {
        // Var = E[X^2] - E[X]^2. x^2·f ~ k/x^2, so the tail beyond b is ≈ k/b.
        let mean = self.mean();
        let b = (200.0 * self.rho).max(200.0);
        let m2_body =
            simpson_integrate_adaptive(|x| x * x * self.pdf(x), 0.0, b, 256, 1e-12, 1e-14, 20);
        let m2 = m2_body + self.k_const() / b;
        m2 - mean * mean
    }

    fn fit(data: &[f64]) -> Self {
        Self::try_fit(data).unwrap_or(Self { rho: f64::NAN })
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Maximum-likelihood fit (scale=1) of the single shape parameter rho
        // via multi-start Nelder-Mead over ln(rho); matches
        // scipy.stats.rel_breitwigner.fit(.., floc=0, fscale=1). Uses only the
        // (cheap, closed-form) pdf — no cdf/ppf integration.
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "RelBreitWigner data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "RelBreitWigner support is [0, ∞); got {x}"
                )));
            }
        }
        let owned: Vec<f64> = data.to_vec();
        let nll = |p: &[f64]| -> f64 {
            let rho = p[0].exp();
            if !rho.is_finite() || rho <= 0.0 {
                return f64::INFINITY;
            }
            let dist = RelBreitWigner { rho };
            let mut total = 0.0;
            for &x in &owned {
                let d = dist.pdf(x);
                if d <= 0.0 || !d.is_finite() {
                    return f64::INFINITY;
                }
                total -= d.ln();
            }
            total
        };
        let mut best: Option<(f64, f64)> = None;
        for &start in &[0.3_f64, 1.0, 3.0] {
            let x0 = [start.ln()];
            let opts = fsci_opt::MinimizeOptions {
                maxiter: Some(1000),
                maxfev: Some(2000),
                tol: Some(1e-10),
                ..Default::default()
            };
            if let Ok(res) = fsci_opt::nelder_mead(&nll, &x0, opts)
                && let Some(f) = res.fun
                && f.is_finite()
                && best.as_ref().is_none_or(|(bf, _)| f < *bf)
            {
                best = Some((f, res.x[0].exp()));
            }
        }
        match best {
            Some((_, rho)) if rho > 0.0 && rho.is_finite() => Ok(Self { rho }),
            _ => Err(FitError::NonConvergent(
                "RelBreitWigner MLE failed to converge".to_owned(),
            )),
        }
    }

    fn skewness(&self) -> f64 {
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // No closed form; h = −∫ pdf·ln pdf dx numerically. RelBreitWigner is
        // heavy-tailed (~x^{−3}), so take the upper bound from a far quantile.
        // Matches scipy ~1e-7. frankenscipy-1mlrz
        let hi = self.ppf(1.0 - 1e-10);
        if !hi.is_finite() || hi <= 0.0 {
            return f64::NAN;
        }
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            hi,
            2_048,
            1e-10,
            1e-12,
            10,
        )
    }

    fn mode(&self) -> f64 {
        // The denominator (x^2 - rho^2)^2 + rho^2 is minimized at x = rho.
        self.rho
    }
}

// ══════════════════════════════════════════════════════════════════════
// Rayleigh Distribution
// ══════════════════════════════════════════════════════════════════════

/// Rayleigh distribution with scale parameter `scale`.
///
/// Matches `scipy.stats.rayleigh(scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rayleigh {
    pub scale: f64,
}

impl Rayleigh {
    #[must_use]
    pub fn new(scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { scale }
    }
}

impl ContinuousDistribution for Rayleigh {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            let sigma_sq = self.scale * self.scale;
            x / sigma_sq * (-(x * x) / (2.0 * sigma_sq)).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(x) − 2·ln(scale) − x²/(2σ²); finite in the tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let sigma_sq = self.scale * self.scale;
        x.ln() - 2.0 * self.scale.ln() - x * x / (2.0 * sigma_sq)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            -(-(x * x) / (2.0 * self.scale * self.scale)).exp_m1()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-f66lp]:
        //   sf(x) = exp(-x²/(2σ²)) for x ≥ 0.
        // Direct exponential — preserves the deep-tail value where
        // the default 1 - cdf would round to 0 (cdf rounds to 1).
        if x < 0.0 {
            1.0
        } else {
            (-(x * x) / (2.0 * self.scale * self.scale)).exp()
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // logsf = -x^2/(2*scale^2); the default ln(sf) underflows to -inf once
        // sf -> 0 in the tail (rayleigh.logsf(40)=-inf vs scipy -800).
        if x < 0.0 {
            0.0
        } else {
            -(x * x) / (2.0 * self.scale * self.scale)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // ln(1 - q) via ln_1p(-q) keeps precision for small q (ppf(1e-12) was
        // ~1.1e-5 off scipy with the naive (1.0 - q).ln()).
        self.scale * (-2.0 * (-q).ln_1p()).sqrt()
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // sf(x)=exp(−x²/(2σ²))=q ⇒ x=σ·sqrt(−2·ln q). The trait default ppf(1−q)
        // recomputes 1−(1−q) and cancels for small q (isf(1e-12) was ~4e-7 off
        // scipy). Matches scipy.stats.rayleigh.isf. frankenscipy-d2gag
        self.scale * (-2.0 * q.ln()).sqrt()
    }

    fn mean(&self) -> f64 {
        self.scale * (PI / 2.0).sqrt()
    }

    fn var(&self) -> f64 {
        (2.0 - PI / 2.0) * self.scale * self.scale
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self { scale: f64::NAN };
        }
        let n = data.len() as f64;
        let sum_sq = data.iter().map(|&x| x * x).sum::<f64>();
        Self {
            scale: (sum_sq / (2.0 * n)).sqrt(),
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Err(FitError::UnsupportedData(
                "Rayleigh requires non-negative finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "Rayleigh fit produced non-finite or non-positive scale".into(),
            ));
        }
        Ok(fitted)
    }

    fn mode(&self) -> f64 {
        // Rayleigh mode = scale [frankenscipy-cxgdg].
        self.scale
    }

    fn entropy(&self) -> f64 {
        // H(Rayleigh) = 1 + ln(σ/√2) + γ/2 [frankenscipy-vngzr].
        1.0 + (self.scale / std::f64::consts::SQRT_2).ln() + EULER_MASCHERONI / 2.0
    }

    fn skewness(&self) -> f64 {
        // Rayleigh skewness = 2·(π-3)·√π / (4-π)^(3/2) ≈ 0.6311
        // [frankenscipy-y718j]; constant in scale.
        2.0 * (PI - 3.0) * PI.sqrt() / (4.0 - PI).powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: (24π − 6π² − 16) / (4 − π)² ≈ 0.24509
        // (scale-invariant). (frankenscipy-5cd0j)
        let four_minus_pi = 4.0 - PI;
        (24.0 * PI - 6.0 * PI * PI - 16.0) / (four_minus_pi * four_minus_pi)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Gumbel Distribution
// ══════════════════════════════════════════════════════════════════════

/// Gumbel (extreme value type I) distribution.
///
/// Matches `scipy.stats.gumbel_r(loc=loc, scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Gumbel {
    pub loc: f64,
    pub scale: f64,
}

impl Gumbel {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for Gumbel {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        let exp_neg_z = (-z).exp();
        (-(z + exp_neg_z)).exp() / self.scale
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −z − e^{−z} − ln(scale); finite in the right tail where pdf
        // underflows (the left tail decays double-exponentially → −inf). frankenscipy-p82v7
        let z = (x - self.loc) / self.scale;
        -z - (-z).exp() - self.scale.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        (-(-z).exp()).exp()
    }

    fn logcdf(&self, x: f64) -> f64 {
        // ln(cdf) = ln(exp(-e^{-z})) = -e^{-z}. The default log_probability(cdf)
        // collapses to -inf once cdf underflows in the LEFT tail (z < ~-6.6,
        // exp(-z) > 745); the closed form stays exact (matches scipy.gumbel_r
        // .logcdf to 0 ULP).
        let z = (x - self.loc) / self.scale;
        -(-z).exp()
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-6uo0s]:
        //   sf = 1 - exp(-exp(-z)) = -expm1(-exp(-z))
        // Default 1 - cdf evaluates 1 - exp(-tiny) which collapses to 0
        // for z far in the right tail; expm1 preserves the exact value.
        let z = (x - self.loc) / self.scale;
        -((-(-z).exp()).exp_m1())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        self.loc - self.scale * (-q.ln()).ln()
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        // isf(q)=ppf(1−q)=loc − scale·ln(−ln(1−q)); −ln(1−q) via −ln_1p(−q)
        // avoids the 1−q cancellation in the trait default (isf(1e-12) was
        // ~8e-7 off scipy). Matches scipy.stats.gumbel_r.isf. frankenscipy-d2gag
        self.loc - self.scale * (-(-q).ln_1p()).ln()
    }

    fn mean(&self) -> f64 {
        const EULER_GAMMA: f64 = 0.577_215_664_901_532_9;
        self.loc + EULER_GAMMA * self.scale
    }

    fn var(&self) -> f64 {
        PI * PI * self.scale * self.scale / 6.0
    }

    fn fit(data: &[f64]) -> Self {
        let (loc, scale) = gumbel_fit_loc_scale(data);
        Self { loc, scale }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Gumbel requires finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.loc.is_finite() || !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "Gumbel fit produced non-finite or non-positive parameters".into(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        self.scale.ln() + EULER_MASCHERONI + 1.0
    }

    fn mode(&self) -> f64 {
        self.loc
    }

    fn skewness(&self) -> f64 {
        1.139_547_099_404_648_7
    }

    fn kurtosis(&self) -> f64 {
        2.4
    }
}

/// Left-skewed Gumbel (extreme value type I) distribution.
///
/// Matches `scipy.stats.gumbel_l(loc=loc, scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GumbelLeft {
    pub loc: f64,
    pub scale: f64,
}

impl GumbelLeft {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for GumbelLeft {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        (z - z.exp()).exp() / self.scale
    }

    fn logpdf(&self, x: f64) -> f64 {
        // z − e^z − ln(scale); finite in the left tail where pdf underflows. frankenscipy-p82v7
        let z = (x - self.loc) / self.scale;
        z - z.exp() - self.scale.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        -(-z.exp()).exp_m1()
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-6uo0s]:
        //   sf = exp(-exp(z))
        // Default 1 - cdf collapses when cdf ≈ 1 in the right tail
        // (z large positive); the direct exp form preserves the value.
        let z = (x - self.loc) / self.scale;
        (-z.exp()).exp()
    }

    fn logsf(&self, x: f64) -> f64 {
        // ln(sf) = ln(exp(-e^{z})) = -e^{z}. The default log_probability(sf)
        // collapses to -inf once sf underflows in the RIGHT tail (z > ~6.6,
        // exp(z) > 745); the closed form stays exact (matches scipy.gumbel_l
        // .logsf to 0 ULP).
        let z = (x - self.loc) / self.scale;
        -z.exp()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        self.loc + self.scale * (-(-q).ln_1p()).ln()
    }

    fn mean(&self) -> f64 {
        const EULER_GAMMA: f64 = 0.577_215_664_901_532_9;
        self.loc - EULER_GAMMA * self.scale
    }

    fn var(&self) -> f64 {
        PI * PI * self.scale * self.scale / 6.0
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite()) {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }

        let mirrored: Vec<f64> = data.iter().map(|&x| -x).collect();
        let (mirrored_loc, scale) = gumbel_fit_loc_scale(&mirrored);
        Self {
            loc: -mirrored_loc,
            scale,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "GumbelLeft requires finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.loc.is_finite() || !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "GumbelLeft fit produced non-finite or non-positive parameters".into(),
            ));
        }
        Ok(fitted)
    }

    fn mode(&self) -> f64 {
        // GumbelLeft mode = loc [frankenscipy-cxgdg].
        self.loc
    }

    fn entropy(&self) -> f64 {
        // H(GumbelLeft) = ln(scale) + γ + 1; same as right Gumbel by
        // symmetry [frankenscipy-vngzr].
        self.scale.ln() + EULER_MASCHERONI + 1.0
    }

    fn skewness(&self) -> f64 {
        // GumbelLeft skewness = -12·√6·ζ(3)/π³ — mirror of right
        // Gumbel (= -1.139547...) [frankenscipy-y718j].
        -1.139_547_099_404_648_7
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis = 12/5 (constant, identical to right
        // Gumbel — the family has the same fourth central moment).
        // (frankenscipy-25tcp)
        12.0 / 5.0
    }
}

// ══════════════════════════════════════════════════════════════════════
// Logistic Distribution
// ══════════════════════════════════════════════════════════════════════

/// Logistic distribution with location `loc` and scale `scale`.
///
/// Matches `scipy.stats.logistic(loc=loc, scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Logistic {
    pub loc: f64,
    pub scale: f64,
}

impl Logistic {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for Logistic {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        let exp_neg_z = (-z).exp();
        exp_neg_z / (self.scale * (1.0 + exp_neg_z).powi(2))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −z − ln(scale) − 2·softplus(−z); the stable softplus keeps both tails
        // finite where pdf underflows. frankenscipy-p82v7
        let z = (x - self.loc) / self.scale;
        // softplus(−z) = ln(1 + e^{−z}) without overflow.
        let softplus_neg_z = if z <= 0.0 {
            -z + z.exp().ln_1p()
        } else {
            (-z).exp().ln_1p()
        };
        -z - self.scale.ln() - 2.0 * softplus_neg_z
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        1.0 / (1.0 + (-z).exp())
    }

    fn logcdf(&self, x: f64) -> f64 {
        // logcdf = ln(expit(z)) = -softplus(-z). The default ln(cdf) underflows
        // for z << 0 (cdf -> 0, logcdf(-1000)=-inf vs scipy -1000). Reuse the
        // same stable softplus the logpdf/sf use.
        let z = (x - self.loc) / self.scale;
        let softplus_neg_z = if z <= 0.0 {
            -z + z.exp().ln_1p()
        } else {
            (-z).exp().ln_1p()
        };
        -softplus_neg_z
    }

    fn logsf(&self, x: f64) -> f64 {
        // logsf = ln(sf) = -softplus(z). The default ln(sf) underflows for z >> 0
        // (sf=1/(1+exp(z))->0, logsf(1000)=-inf vs scipy -1000).
        let z = (x - self.loc) / self.scale;
        let softplus_z = if z <= 0.0 {
            z.exp().ln_1p()
        } else {
            z + (-z).exp().ln_1p()
        };
        -softplus_z
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-h36zm]:
        //   sf = 1/(1 + exp(z))  vs.  the imprecise default 1 - cdf.
        // For large positive z (deep right tail), 1 - 1/(1 + exp(-z))
        // catastrophically cancels.
        let z = (x - self.loc) / self.scale;
        1.0 / (1.0 + z.exp())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        self.loc + self.scale * (q / (1.0 - q)).ln()
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        // isf(q)=ppf(1−q)=loc + scale·ln((1−q)/q)=loc + scale·(ln(1−q) − ln q).
        // ln(1−q) via ln_1p(−q) avoids the trait default's 1−q cancellation
        // (isf(1e-12) was ~8e-7 off scipy). Matches scipy.stats.logistic.isf.
        // frankenscipy-d2gag
        self.loc + self.scale * ((-q).ln_1p() - q.ln())
    }

    fn mean(&self) -> f64 {
        self.loc
    }

    fn var(&self) -> f64 {
        PI * PI * self.scale * self.scale / 3.0
    }

    fn fit(data: &[f64]) -> Self {
        let n = data.len() as f64;
        if n == 0.0 {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        Self {
            loc: mean,
            scale: var.sqrt() * 3.0_f64.sqrt() / PI,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-covaj]: previously inherited the trait-default
        // try_fit which returned NotImplemented even though fit() had a
        // working method-of-moments closed form. Surface typed errors
        // to non-panicking callers without touching fit() (which keeps
        // its existing NaN-on-bad-input behavior for back-compat).
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Logistic fit requires all-finite samples".into(),
            ));
        }
        let n = data.len() as f64;
        let mean = data.iter().sum::<f64>() / n;
        let var = data.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        Ok(Self {
            loc: mean,
            scale: var.sqrt() * 3.0_f64.sqrt() / PI,
        })
    }

    fn entropy(&self) -> f64 {
        self.scale.ln() + 2.0
    }

    fn mode(&self) -> f64 {
        self.loc
    }

    fn skewness(&self) -> f64 {
        0.0
    }

    fn kurtosis(&self) -> f64 {
        1.2
    }
}

/// Hyperbolic secant distribution.
///
/// Matches `scipy.stats.hypsecant`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HypSecant;

impl ContinuousDistribution for HypSecant {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let exp_neg_abs_x = (-x.abs()).exp();
        2.0 * exp_neg_abs_x / (PI * (1.0 + exp_neg_abs_x * exp_neg_abs_x))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln2 − |x| − ln(π) − ln1p(e^{−2|x|}); finite in the tail. frankenscipy-p82v7
        2.0_f64.ln() - x.abs() - PI.ln() - (-2.0 * x.abs()).exp().ln_1p()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x >= 0.0 {
            1.0 - 2.0 / PI * (-x).exp().atan()
        } else {
            2.0 / PI * x.exp().atan()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Complement of the atan cdf: x≥0 → (2/π)·atan(e^{-x}) (exp tail, the
        // default 1−cdf collapses); x<0 → 1 − (2/π)·atan(e^x). frankenscipy-w3f6m
        if x >= 0.0 {
            2.0 / PI * (-x).exp().atan()
        } else {
            1.0 - 2.0 / PI * x.exp().atan()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        (0.5 * PI * q).tan().ln()
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        PI * PI / 4.0
    }

    fn skewness(&self) -> f64 {
        // HypSecant is symmetric around 0.
        0.0
    }

    fn mode(&self) -> f64 {
        // HypSecant pdf ∝ sech(πx/2) is symmetric and peaks at 0
        // (frankenscipy-rt24d).
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-a1kjq]: scipy.stats.hypsecant
        // reports excess kurtosis = 2.
        2.0
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-a1kjq]: scipy.stats.hypsecant
        // reports differential entropy = ln(2π).
        (2.0 * PI).ln()
    }

    // fit() inherits the trait default which delegates to try_fit and
    // panics on FitError. Resolves [frankenscipy-v6rct]: previously
    // HypSecant.fit silently accepted any data (including NaN/empty)
    // while HypSecant.try_fit validated, inverting the trait's
    // panic-vs-Result contract.

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        Ok(Self)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Maxwell Distribution
// ══════════════════════════════════════════════════════════════════════

/// Maxwell distribution with scale parameter `scale`.
///
/// Matches `scipy.stats.maxwell(scale=scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Maxwell {
    pub scale: f64,
}

impl Maxwell {
    #[must_use]
    pub fn new(scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { scale }
    }
}

impl ContinuousDistribution for Maxwell {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            (2.0 / PI).sqrt() * x * x / self.scale.powi(3)
                * (-(x * x) / (2.0 * self.scale * self.scale)).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // Closed form so the deep tail stays finite (default ln(pdf) → −inf once
        // the Gaussian factor underflows, e.g. x≈41). frankenscipy.
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let s = self.scale;
        0.5 * (2.0 / PI).ln() + 2.0 * x.ln() - 3.0 * s.ln() - x * x / (2.0 * s * s)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            let sqrt_two_over_pi = (2.0 / PI).sqrt();
            let z = x / (self.scale * 2.0_f64.sqrt());
            fsci_special::erf_scalar(z)
                - sqrt_two_over_pi
                    * (x / self.scale)
                    * (-(x * x) / (2.0 * self.scale * self.scale)).exp()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Maxwell cdf = P(3/2, x²/(2σ²)); survival = Q(3/2, x²/(2σ²)) directly,
        // avoiding the default 1−cdf collapse in the tail. frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(1.5, x * x / (2.0 * self.scale * self.scale))
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(3/2, x²/(2σ²)); finite in the ultra-extreme tail. frankenscipy-pkaua
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammaincc_scalar(1.5, x * x / (2.0 * self.scale * self.scale))
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let mut x = self.scale * (2.0 * fsci_special::gammaincinv_scalar(1.5, q)).sqrt();
        if x <= 0.0 || !x.is_finite() || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // sf(x)=Q(3/2, x²/(2σ²))=q ⇒ x=σ·sqrt(2·gammainccinv(3/2,q)). The trait
        // default ppf(1−q)→gammaincinv near 1 is ill-conditioned (isf(1e-12) was
        // ~1.2e-5 off); gammainccinv is well-conditioned. frankenscipy-d2gag
        let mut x = self.scale * (2.0 * fsci_special::gammainccinv_scalar(1.5, q)).sqrt();
        if x <= 0.0 || !x.is_finite() || (self.sf(x) - q).abs() > 0.1 {
            return isf_bisection(|v| self.sf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.sf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                // sf decreasing: d(sf)/dx = −pdf, so x += err/pdf.
                x = (x + err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        2.0 * self.scale * (2.0 / PI).sqrt()
    }

    fn var(&self) -> f64 {
        self.scale * self.scale * (3.0 - 8.0 / PI)
    }

    fn entropy(&self) -> f64 {
        // h(Maxwell(σ)) = ln(σ · √(2π)) + γ − 1/2.
        (self.scale * (2.0 * PI).sqrt()).ln() + EULER_MASCHERONI - 0.5
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Self { scale: f64::NAN };
        }
        let n = data.len() as f64;
        let sum_sq = data.iter().map(|&x| x * x).sum::<f64>();
        Self {
            scale: (sum_sq / (3.0 * n)).sqrt(),
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Err(FitError::UnsupportedData(
                "Maxwell requires non-negative finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "Maxwell fit produced non-finite or non-positive scale".into(),
            ));
        }
        Ok(fitted)
    }

    fn mode(&self) -> f64 {
        // Maxwell mode = scale · √2 [frankenscipy-cxgdg].
        self.scale * std::f64::consts::SQRT_2
    }

    fn skewness(&self) -> f64 {
        // Maxwell skewness = 2·√2·(16 - 5π) / (3π - 8)^(3/2) ≈ 0.4857
        // [frankenscipy-y718j]; constant in scale.
        2.0 * std::f64::consts::SQRT_2 * (16.0 - 5.0 * PI) / (3.0 * PI - 8.0).powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 4·(40π − 3π² − 96) / (3π − 8)² ≈ 0.10816
        // (scale-invariant). (frankenscipy-5cd0j)
        let three_pi_minus_8 = 3.0 * PI - 8.0;
        4.0 * (40.0 * PI - 3.0 * PI * PI - 96.0) / (three_pi_minus_8 * three_pi_minus_8)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Multivariate Normal Distribution
// ══════════════════════════════════════════════════════════════════════

/// Multivariate normal distribution with cached Cholesky factorization.
///
/// Matches `scipy.stats.multivariate_normal(mean, cov)` for the default
/// `allow_singular=False` path.
#[derive(Debug, Clone, PartialEq)]
pub struct MultivariateNormal {
    pub mean: Vec<f64>,
    pub cov: Vec<Vec<f64>>,
    chol: Vec<Vec<f64>>,
    log_det: f64,
}

impl MultivariateNormal {
    pub fn new(mean: &[f64], cov: &[Vec<f64>]) -> Result<Self, StatsError> {
        if mean.is_empty() {
            return Err(StatsError::InvalidArgument(
                "mean must be non-empty".to_string(),
            ));
        }
        if cov.len() != mean.len() {
            return Err(StatsError::InvalidArgument(format!(
                "cov row count ({}) must match mean length ({})",
                cov.len(),
                mean.len()
            )));
        }
        for (row_idx, row) in cov.iter().enumerate() {
            if row.len() != mean.len() {
                return Err(StatsError::InvalidArgument(format!(
                    "cov row {row_idx} has length {}, expected {}",
                    row.len(),
                    mean.len()
                )));
            }
        }
        for (i, row_i) in cov.iter().enumerate() {
            for (j, row_j) in cov.iter().enumerate() {
                if (row_i[j] - row_j[i]).abs() > 1e-12 {
                    return Err(StatsError::InvalidArgument(
                        "covariance matrix must be symmetric".to_string(),
                    ));
                }
            }
        }

        let chol = cholesky_decompose(cov)?;
        let log_det = 2.0 * (0..chol.len()).map(|i| chol[i][i].ln()).sum::<f64>();
        Ok(Self {
            mean: mean.to_vec(),
            cov: cov.to_vec(),
            chol,
            log_det,
        })
    }

    pub fn logpdf(&self, x: &[f64]) -> Result<f64, StatsError> {
        if x.len() != self.mean.len() {
            return Err(StatsError::InvalidArgument(format!(
                "x length ({}) must match dimension ({})",
                x.len(),
                self.mean.len()
            )));
        }
        let centered: Vec<f64> = x
            .iter()
            .zip(self.mean.iter())
            .map(|(&xi, &mi)| xi - mi)
            .collect();
        let solved = solve_lower_triangular(&self.chol, &centered)?;
        let mahalanobis = solved.iter().map(|value| value * value).sum::<f64>();
        let dim = self.mean.len() as f64;
        Ok(-0.5 * (dim * (2.0 * PI).ln() + self.log_det + mahalanobis))
    }

    pub fn pdf(&self, x: &[f64]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }

    /// Log-density at many points (the realistic dataset-likelihood workload,
    /// matching `scipy.stats.multivariate_normal.logpdf` on an array of points).
    ///
    /// Byte-identical to mapping [`logpdf`](Self::logpdf): the `dim·ln(2π)+log_det`
    /// constant is computed once and the centered/forward-solve scratch buffers are
    /// reused across points instead of reallocated per point.
    pub fn logpdf_many(&self, xs: &[Vec<f64>]) -> Result<Vec<f64>, StatsError> {
        let n = self.mean.len();
        let dim = n as f64;
        let const_term = dim * (2.0 * PI).ln() + self.log_det;
        if xs.is_empty() {
            return Ok(Vec::new());
        }
        // Validate up front (same errors the sequential map would surface: a length
        // mismatch short-circuits the whole result to Err before any value is
        // returned; a singular factor — unreachable for a validly-constructed SPD
        // covariance — is a property of `self`, identical for every point).
        for x in xs {
            if x.len() != n {
                return Err(StatsError::InvalidArgument(format!(
                    "x length ({}) must match dimension ({})",
                    x.len(),
                    n
                )));
            }
        }
        if (0..n).any(|i| self.chol[i][i] == 0.0) {
            return Err(StatsError::InvalidArgument(
                "singular lower-triangular system".to_string(),
            ));
        }

        // Pure per-point log-density (forward-substitution Mahalanobis). Identical
        // arithmetic and order regardless of the owning thread, so the parallel
        // path is bit-identical to the sequential map.
        // Batch Mahalanobis log-density for a slice of points via ONE multi-RHS
        // forward substitution instead of a per-point single-RHS solve. For each
        // coordinate i, `acc[p] = Σ_{k<i} L[i][k]·w[k][p]` then `w[i][p] =
        // (x_p[i] - mean[i] - acc[p]) / L[i][i]`, with the inner per-point loops
        // contiguous so they vectorize across the points. BYTE-IDENTICAL to the
        // per-point forward-sub: `acc[p]` left-folds k in 0..i exactly like the
        // per-point `(0..i).map(..).sum()`, and `maha = Σ_i w[i][p]²` — verified
        // EXACT (and 1.65-2.35x faster) in `bin/perf_mvn_maha_ab.rs`.
        let eval_batch = |xs_chunk: &[Vec<f64>]| -> Vec<f64> {
            let b = xs_chunk.len();
            let mut w = vec![vec![0.0_f64; b]; n];
            let mut acc = vec![0.0_f64; b];
            for i in 0..n {
                let lii = self.chol[i][i];
                for a in acc.iter_mut() {
                    *a = 0.0;
                }
                for (k, wk) in w.iter().enumerate().take(i) {
                    let lik = self.chol[i][k];
                    for (a, &wkp) in acc.iter_mut().zip(wk.iter()) {
                        *a += lik * wkp;
                    }
                }
                let mean_i = self.mean[i];
                let wi = &mut w[i];
                for (p, x) in xs_chunk.iter().enumerate() {
                    wi[p] = (x[i] - mean_i - acc[p]) / lii;
                }
            }
            (0..b)
                .map(|p| {
                    let maha: f64 = (0..n).map(|i| w[i][p] * w[i][p]).sum();
                    -0.5 * (const_term + maha)
                })
                .collect()
        };

        let m = xs.len();
        let work = (m as u64).saturating_mul((n * n) as u64);
        let threads = std::thread::available_parallelism()
            .map(|c| c.get())
            .unwrap_or(1)
            .min(m);
        // Parallelize only for dimension n >= 5: at low n the batch solve is cheap
        // (memory-bound), so thread overhead regresses it. Common 2-D/3-D data
        // stays on the already-scipy-beating sequential (single-batch) path.
        if n < 5 || work < 1 << 18 || threads <= 1 || m < 4 {
            return Ok(eval_batch(xs));
        }
        let mut out = vec![0.0f64; m];
        let chunk = m.div_ceil(threads);
        let eval_batch = &eval_batch;
        std::thread::scope(|scope| {
            for (xchunk, ochunk) in xs.chunks(chunk).zip(out.chunks_mut(chunk)) {
                scope.spawn(move || {
                    ochunk.copy_from_slice(&eval_batch(xchunk));
                });
            }
        });
        Ok(out)
    }

    /// Density at many points (`exp` of [`logpdf_many`](Self::logpdf_many)).
    pub fn pdf_many(&self, xs: &[Vec<f64>]) -> Result<Vec<f64>, StatsError> {
        let mut values = self.logpdf_many(xs)?;
        for value in &mut values {
            *value = value.exp();
        }
        Ok(values)
    }

    pub fn rvs(&self, n: usize, rng: &mut impl Rng) -> Vec<Vec<f64>> {
        let mut samples = Vec::with_capacity(n);
        for _ in 0..n {
            let z = sample_standard_normals(self.mean.len(), rng);
            let mut sample = self.mean.clone();
            for (i, row) in self.chol.iter().enumerate() {
                for (j, &zj) in z.iter().take(i + 1).enumerate() {
                    sample[i] += row[j] * zj;
                }
            }
            samples.push(sample);
        }
        samples
    }
}

// ══════════════════════════════════════════════════════════════════════
// Dirichlet Distribution
// ══════════════════════════════════════════════════════════════════════

/// Dirichlet distribution - multivariate generalization of Beta.
///
/// Matches `scipy.stats.dirichlet(alpha)`.
#[derive(Debug, Clone, PartialEq)]
pub struct Dirichlet {
    pub alpha: Vec<f64>,
    alpha_sum: f64,
    log_norm: f64,
}

impl Dirichlet {
    /// Create a Dirichlet distribution with concentration parameters alpha.
    pub fn new(alpha: &[f64]) -> Self {
        assert!(!alpha.is_empty(), "alpha must be non-empty");
        assert!(
            alpha.iter().all(|&a| a > 0.0),
            "all alpha values must be positive"
        );

        let alpha_sum: f64 = alpha.iter().sum();
        let log_norm = alpha.iter().map(|&a| ln_gamma(a)).sum::<f64>() - ln_gamma(alpha_sum);

        Self {
            alpha: alpha.to_vec(),
            alpha_sum,
            log_norm,
        }
    }

    /// Log probability density function.
    pub fn logpdf(&self, x: &[f64]) -> f64 {
        if x.len() != self.alpha.len() {
            return f64::NEG_INFINITY;
        }

        let sum: f64 = x.iter().sum();
        if (sum - 1.0).abs() > 1e-10 || x.iter().any(|&xi| !(0.0..=1.0).contains(&xi)) {
            return f64::NEG_INFINITY;
        }

        let log_x: f64 = x
            .iter()
            .zip(&self.alpha)
            .map(|(&xi, &ai)| (ai - 1.0) * xi.ln())
            .sum();

        log_x - self.log_norm
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[f64]) -> f64 {
        self.logpdf(x).exp()
    }

    /// Mean of the distribution.
    pub fn mean(&self) -> Vec<f64> {
        self.alpha.iter().map(|&a| a / self.alpha_sum).collect()
    }

    /// Variance of each component.
    pub fn var(&self) -> Vec<f64> {
        let s = self.alpha_sum;
        let denom = s * s * (s + 1.0);
        self.alpha.iter().map(|&a| a * (s - a) / denom).collect()
    }

    /// Generate random variates from the distribution.
    pub fn rvs(&self, n: usize, rng: &mut impl Rng) -> Vec<Vec<f64>> {
        let mut samples = Vec::with_capacity(n);
        for _ in 0..n {
            let gamma_samples: Vec<f64> = self
                .alpha
                .iter()
                .map(|&a| {
                    let gamma = GammaDist::new(a, 1.0);
                    gamma.rvs(1, rng)[0]
                })
                .collect();
            let sum: f64 = gamma_samples.iter().sum();
            let normalized: Vec<f64> = gamma_samples.iter().map(|&g| g / sum).collect();
            samples.push(normalized);
        }
        samples
    }

    /// Entropy of the distribution.
    pub fn entropy(&self) -> f64 {
        let k = self.alpha.len() as f64;
        self.log_norm
            - (k - self.alpha_sum) * digamma(self.alpha_sum)
            - self
                .alpha
                .iter()
                .map(|&a| (a - 1.0) * digamma(a))
                .sum::<f64>()
    }
}

/// The multinomial distribution, matching `scipy.stats.multinomial(n, p)`.
pub struct Multinomial {
    pub n: usize,
    pub p: Vec<f64>,
}

impl Multinomial {
    /// Create a multinomial distribution for `n` trials with category
    /// probabilities `p` (which should sum to 1).
    pub fn new(n: usize, p: &[f64]) -> Self {
        assert!(!p.is_empty(), "p must be non-empty");
        Self { n, p: p.to_vec() }
    }

    /// Log probability mass function. Returns `-inf` unless the counts are non-negative
    /// INTEGERS summing EXACTLY to `n`.
    ///
    /// Both conditions are the incumbent's, verified against scipy 1.17.1 rather than
    /// assumed. `multinomial.logpmf` returns `-inf` for a sum that misses `n` by 5e-10, and
    /// `-inf` for `[2.5, 3, 4.5]` with `n = 10` — which sums to `n` exactly but is not a
    /// count vector.
    ///
    /// This used to admit a `1e-9` tolerance on the sum and never checked integrality, so it
    /// returned a FINITE value in both of those cases while claiming to follow "scipy's
    /// convention". That is the same defect shape as `frankenscipy-clttw`: a tolerance
    /// standing in for an exact predicate the reference actually uses.
    ///
    /// Conforming input — non-negative integers summing to `n` — is unaffected: it passed
    /// the old check and passes the new one, and nothing downstream of the guard changed.
    pub fn logpmf(&self, x: &[f64]) -> f64 {
        if x.len() != self.p.len() {
            return f64::NEG_INFINITY;
        }
        let sum: f64 = x.iter().sum();
        if sum != self.n as f64
            || x.iter().any(|&xi| xi < 0.0 || xi.floor() != xi)
        {
            return f64::NEG_INFINITY;
        }
        let mut lp = ln_gamma(self.n as f64 + 1.0);
        for (&xi, &pi) in x.iter().zip(&self.p) {
            lp -= ln_gamma(xi + 1.0);
            if xi > 0.0 {
                // 0 * ln(0) = 0; a positive count with zero probability is impossible.
                lp += if pi > 0.0 {
                    xi * pi.ln()
                } else {
                    f64::NEG_INFINITY
                };
            }
        }
        lp
    }

    /// Probability mass function.
    pub fn pmf(&self, x: &[f64]) -> f64 {
        self.logpmf(x).exp()
    }

    /// Mean vector `n·p`.
    pub fn mean(&self) -> Vec<f64> {
        self.p.iter().map(|&pi| self.n as f64 * pi).collect()
    }

    /// Covariance matrix `cov[i][j] = n·p_i·(δ_ij − p_j)`.
    pub fn cov(&self) -> Vec<Vec<f64>> {
        let k = self.p.len();
        let nf = self.n as f64;
        (0..k)
            .map(|i| {
                (0..k)
                    .map(|j| {
                        let delta = if i == j { 1.0 } else { 0.0 };
                        nf * self.p[i] * (delta - self.p[j])
                    })
                    .collect()
            })
            .collect()
    }

    /// Differential entropy, matching scipy's expression
    /// `−ln n! − n Σ p_i ln p_i + Σ_i Σ_{x=1}^{n} Binom(x; n, p_i)·ln x!`.
    pub fn entropy(&self) -> f64 {
        let nf = self.n as f64;
        // term1 = n·Σ entr(p_i) − ln(n!), entr(p) = −p ln p.
        let mut h = -ln_gamma(nf + 1.0);
        for &pi in &self.p {
            if pi > 0.0 {
                h += nf * (-pi * pi.ln());
            }
        }
        // term2 = Σ_i Σ_{x=1}^{n} C(n,x) p_i^x (1−p_i)^{n−x} · ln(x!).
        let ln_n_fact = ln_gamma(nf + 1.0);
        for &pi in &self.p {
            if pi <= 0.0 || pi >= 1.0 {
                continue;
            }
            let (lp, lq) = (pi.ln(), (1.0 - pi).ln());
            for xk in 1..=self.n {
                let xf = xk as f64;
                let log_binom = ln_n_fact - ln_gamma(xf + 1.0) - ln_gamma(nf - xf + 1.0)
                    + xf * lp
                    + (nf - xf) * lq;
                h += log_binom.exp() * ln_gamma(xf + 1.0);
            }
        }
        h
    }
}

/// The Poisson binomial distribution — the number of successes in `n`
/// independent Bernoulli trials with (possibly different) success
/// probabilities `p`, matching `scipy.stats.poisson_binom(p)`.
pub struct PoissonBinom {
    p: Vec<f64>,
    /// pmf[k] = P(X = k), k = 0..=n, computed by the exact convolution DP.
    pmf: Vec<f64>,
}

impl PoissonBinom {
    /// Create a Poisson binomial distribution from per-trial success
    /// probabilities `p` (each in `[0, 1]`).
    pub fn new(p: &[f64]) -> Self {
        // DP: fold each Bernoulli in, dp[j] = dp[j](1-p_i) + dp[j-1] p_i.
        let mut pmf = vec![1.0_f64];
        for &pi in p {
            let mut next = vec![0.0_f64; pmf.len() + 1];
            for (j, &v) in pmf.iter().enumerate() {
                next[j] += v * (1.0 - pi);
                next[j + 1] += v * pi;
            }
            pmf = next;
        }
        Self { p: p.to_vec(), pmf }
    }

    /// Probability mass function `P(X = k)`.
    pub fn pmf(&self, k: usize) -> f64 {
        self.pmf.get(k).copied().unwrap_or(0.0)
    }

    /// Cumulative distribution function `P(X ≤ k)`.
    pub fn cdf(&self, k: usize) -> f64 {
        self.pmf.iter().take(k + 1).sum()
    }

    /// Mean `Σ p_i`.
    pub fn mean(&self) -> f64 {
        self.p.iter().sum()
    }

    /// Variance `Σ p_i(1 − p_i)`.
    pub fn var(&self) -> f64 {
        self.p.iter().map(|&pi| pi * (1.0 - pi)).sum()
    }
}

/// The multivariate hypergeometric distribution — drawing `n` items without
/// replacement from a collection with `m_i` items of each color, matching
/// `scipy.stats.multivariate_hypergeom(m, n)`.
pub struct MultivariateHypergeom {
    m: Vec<usize>,
    n: usize,
    total: usize,
}

impl MultivariateHypergeom {
    /// Create the distribution: `m[i]` items of color `i`, drawing `n` total.
    pub fn new(m: &[usize], n: usize) -> Self {
        let total: usize = m.iter().sum();
        Self {
            m: m.to_vec(),
            n,
            total,
        }
    }

    /// Probability mass function `Π C(m_i, x_i) / C(M, n)`; zero unless the
    /// draw is valid (`0 ≤ x_i ≤ m_i` and `Σ x_i = n`).
    pub fn pmf(&self, x: &[usize]) -> f64 {
        if x.len() != self.m.len()
            || x.iter().sum::<usize>() != self.n
            || x.iter().zip(&self.m).any(|(&xi, &mi)| xi > mi)
        {
            return 0.0;
        }
        let ln_c = |a: usize, b: usize| -> f64 {
            ln_gamma(a as f64 + 1.0) - ln_gamma(b as f64 + 1.0) - ln_gamma((a - b) as f64 + 1.0)
        };
        let mut ln_p = -ln_c(self.total, self.n);
        for (&xi, &mi) in x.iter().zip(&self.m) {
            ln_p += ln_c(mi, xi);
        }
        ln_p.exp()
    }

    /// Mean vector `n·m_i/M`.
    pub fn mean(&self) -> Vec<f64> {
        let (nf, mf) = (self.n as f64, self.total as f64);
        self.m.iter().map(|&mi| nf * mi as f64 / mf).collect()
    }

    /// Variance of each component, the diagonal of [`cov`](Self::cov).
    pub fn var(&self) -> Vec<f64> {
        let cov = self.cov();
        (0..self.m.len()).map(|i| cov[i][i]).collect()
    }

    /// Covariance `cov_ij = n·(M−n)/(M−1)·(m_i/M)·(δ_ij − m_j/M)`.
    pub fn cov(&self) -> Vec<Vec<f64>> {
        let k = self.m.len();
        let (nf, mf) = (self.n as f64, self.total as f64);
        let factor = nf * (mf - nf) / (mf - 1.0);
        (0..k)
            .map(|i| {
                let pi = self.m[i] as f64 / mf;
                (0..k)
                    .map(|j| {
                        let pj = self.m[j] as f64 / mf;
                        let delta = if i == j { 1.0 } else { 0.0 };
                        factor * pi * (delta - pj)
                    })
                    .collect()
            })
            .collect()
    }
}

/// The Dirichlet-multinomial (compound) distribution, matching
/// `scipy.stats.dirichlet_multinomial(alpha, n)`.
pub struct DirichletMultinomial {
    alpha: Vec<f64>,
    n: usize,
    alpha_sum: f64,
}

impl DirichletMultinomial {
    /// Create the distribution with concentration `alpha` and `n` trials.
    pub fn new(alpha: &[f64], n: usize) -> Self {
        assert!(!alpha.is_empty(), "alpha must be non-empty");
        assert!(alpha.iter().all(|&a| a > 0.0), "alpha must be positive");
        let alpha_sum = alpha.iter().sum();
        Self {
            alpha: alpha.to_vec(),
            n,
            alpha_sum,
        }
    }

    /// Log probability mass function. Returns `-inf` unless the counts are non-negative
    /// INTEGERS summing EXACTLY to `n`.
    ///
    /// Both conditions are the incumbent's, checked against scipy 1.17.1 rather than
    /// assumed. With `alpha = [1, 2, 3]`, `n = 6`:
    ///   `logpmf([1, 2, 3])`  -> -2.7343675094195836
    ///   `logpmf([1, 2, 4])`  -> -inf                       (integers, wrong sum: exact test)
    ///   `logpmf([1, 2, 3.0000000005])` -> **raises** `ValueError: x must contain only
    ///   non-negative integers` — scipy rejects non-integer counts at validation.
    ///
    /// This used to admit a `1e-9` tolerance on the sum and never tested integrality, so
    /// that third case returned a FINITE value. Since this returns `f64` and cannot raise,
    /// `-inf` is the mapping: it is the value scipy gives for every other out-of-support
    /// input, and it keeps a non-count vector from producing a plausible density.
    /// Deliberate deviation, recorded rather than silent — the API shape differs, the
    /// admitted SET does not.
    ///
    /// Conforming input — non-negative integers summing to `n` — is unaffected: sums of
    /// integers differ from `n` by at least 1, so the old tolerance never bit there, and
    /// nothing downstream of the guard changed.
    pub fn logpmf(&self, x: &[f64]) -> f64 {
        if x.len() != self.alpha.len() {
            return f64::NEG_INFINITY;
        }
        let sum: f64 = x.iter().sum();
        if sum != self.n as f64 || x.iter().any(|&xi| xi < 0.0 || xi.floor() != xi) {
            return f64::NEG_INFINITY;
        }
        let mut lp = ln_gamma(self.alpha_sum) - ln_gamma(self.n as f64 + self.alpha_sum)
            + ln_gamma(self.n as f64 + 1.0);
        for (&xi, &ai) in x.iter().zip(&self.alpha) {
            lp += ln_gamma(xi + ai) - ln_gamma(ai) - ln_gamma(xi + 1.0);
        }
        lp
    }

    /// Probability mass function.
    pub fn pmf(&self, x: &[f64]) -> f64 {
        self.logpmf(x).exp()
    }

    /// Mean vector `n·α_i/α₀`.
    pub fn mean(&self) -> Vec<f64> {
        let nf = self.n as f64;
        self.alpha
            .iter()
            .map(|&ai| nf * ai / self.alpha_sum)
            .collect()
    }

    /// Variance of each component (the diagonal of [`cov`](Self::cov)).
    pub fn var(&self) -> Vec<f64> {
        let cov = self.cov();
        (0..self.alpha.len()).map(|i| cov[i][i]).collect()
    }

    /// Covariance `cov_ij = n·p_i(δ_ij − p_j)·(n+α₀)/(1+α₀)`, `p_i = α_i/α₀`.
    pub fn cov(&self) -> Vec<Vec<f64>> {
        let k = self.alpha.len();
        let nf = self.n as f64;
        let overdisp = (nf + self.alpha_sum) / (1.0 + self.alpha_sum);
        (0..k)
            .map(|i| {
                let pi = self.alpha[i] / self.alpha_sum;
                (0..k)
                    .map(|j| {
                        let pj = self.alpha[j] / self.alpha_sum;
                        let delta = if i == j { 1.0 } else { 0.0 };
                        nf * pi * (delta - pj) * overdisp
                    })
                    .collect()
            })
            .collect()
    }
}

/// The multivariate Student-t distribution, matching
/// `scipy.stats.multivariate_t(loc, shape, df)`.
pub struct MultivariateT {
    pub loc: Vec<f64>,
    df: f64,
    chol: Vec<Vec<f64>>,
    log_det: f64,
}

impl MultivariateT {
    /// Create the distribution with location `loc`, positive-definite `shape`
    /// matrix, and `df` degrees of freedom.
    pub fn new(loc: &[f64], shape: &[Vec<f64>], df: f64) -> Result<Self, StatsError> {
        if loc.is_empty() {
            return Err(StatsError::InvalidArgument(
                "loc must be non-empty".to_string(),
            ));
        }
        if shape.len() != loc.len() {
            return Err(StatsError::InvalidArgument(
                "shape dimension must match loc".to_string(),
            ));
        }
        let chol = cholesky_decompose(shape)?;
        let log_det = 2.0 * (0..chol.len()).map(|i| chol[i][i].ln()).sum::<f64>();
        Ok(Self {
            loc: loc.to_vec(),
            df,
            chol,
            log_det,
        })
    }

    /// Log probability density function.
    pub fn logpdf(&self, x: &[f64]) -> Result<f64, StatsError> {
        if x.len() != self.loc.len() {
            return Err(StatsError::InvalidArgument(
                "x length must match dimension".to_string(),
            ));
        }
        let centered: Vec<f64> = x.iter().zip(&self.loc).map(|(&xi, &li)| xi - li).collect();
        let solved = solve_lower_triangular(&self.chol, &centered)?;
        let maha: f64 = solved.iter().map(|v| v * v).sum();
        let p = self.loc.len() as f64;
        let df = self.df;
        let pi = std::f64::consts::PI;
        let logpdf = ln_gamma(0.5 * (df + p))
            - ln_gamma(0.5 * df)
            - 0.5 * p * (df.ln() + pi.ln())
            - 0.5 * self.log_det
            - 0.5 * (df + p) * (1.0 + maha / df).ln();
        Ok(logpdf)
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[f64]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }

    /// Log-density at many points. Bit-identical to mapping [`logpdf`](Self::logpdf)
    /// but hoists the per-call `lgamma` normalizer (2 `ln_gamma` calls) out of the
    /// loop and, for dimension `n >= 5`, fans the independent points across threads
    /// (per-thread scratch buffers; the per-point arithmetic and order are
    /// unchanged). Below n=5 the O(n²) solve is too cheap to amortize threads, so it
    /// stays sequential (still faster than the per-point map thanks to the hoist).
    pub fn logpdf_many(&self, xs: &[Vec<f64>]) -> Result<Vec<f64>, StatsError> {
        let n = self.loc.len();
        if xs.is_empty() {
            return Ok(Vec::new());
        }
        for x in xs {
            if x.len() != n {
                return Err(StatsError::InvalidArgument(
                    "x length must match dimension".to_string(),
                ));
            }
        }
        let p = n as f64;
        let df = self.df;
        let pi = std::f64::consts::PI;
        // Hoisted constant: lgamma(½(df+p)) − lgamma(½df) − ½p(ln df + ln π) − ½log_det,
        // evaluated in the same left-to-right order as the scalar `logpdf`.
        let const_part = ln_gamma(0.5 * (df + p))
            - ln_gamma(0.5 * df)
            - 0.5 * p * (df.ln() + pi.ln())
            - 0.5 * self.log_det;
        // Batch Mahalanobis via ONE multi-RHS forward substitution per chunk
        // (acc[p] = Σ_{k<i} L[i][k]·w[k][p]; w[i][p] = (xₚ[i] − loc[i] − acc[p]) /
        // L[i][i]), inner per-point loops contiguous so they vectorize across
        // points. BYTE-IDENTICAL to the per-point forward-sub (acc[p] left-folds k
        // in 0..i like the per-point `.sum()`; maha = Σ_i w[i][p]²) — same kernel
        // measured 1.65-2.35x in `bin/perf_mvn_maha_ab.rs` (MVN sibling).
        let eval_batch = |xs_chunk: &[Vec<f64>]| -> Vec<f64> {
            let b = xs_chunk.len();
            let mut w = vec![vec![0.0_f64; b]; n];
            let mut acc = vec![0.0_f64; b];
            for i in 0..n {
                let lii = self.chol[i][i];
                for a in acc.iter_mut() {
                    *a = 0.0;
                }
                for (k, wk) in w.iter().enumerate().take(i) {
                    let lik = self.chol[i][k];
                    for (a, &wkp) in acc.iter_mut().zip(wk.iter()) {
                        *a += lik * wkp;
                    }
                }
                let loc_i = self.loc[i];
                let wi = &mut w[i];
                for (pp, x) in xs_chunk.iter().enumerate() {
                    wi[pp] = (x[i] - loc_i - acc[pp]) / lii;
                }
            }
            (0..b)
                .map(|pp| {
                    let maha: f64 = (0..n).map(|i| w[i][pp] * w[i][pp]).sum();
                    const_part - 0.5 * (df + p) * (1.0 + maha / df).ln()
                })
                .collect()
        };

        let m = xs.len();
        let work = (m as u64).saturating_mul((n * n) as u64);
        let threads = std::thread::available_parallelism()
            .map(|c| c.get())
            .unwrap_or(1)
            .min(m);
        if n < 5 || work < 1 << 18 || threads <= 1 || m < 4 {
            return Ok(eval_batch(xs));
        }
        let mut out = vec![0.0f64; m];
        let chunk = m.div_ceil(threads);
        let eval_batch = &eval_batch;
        std::thread::scope(|scope| {
            for (xchunk, ochunk) in xs.chunks(chunk).zip(out.chunks_mut(chunk)) {
                scope.spawn(move || {
                    ochunk.copy_from_slice(&eval_batch(xchunk));
                });
            }
        });
        Ok(out)
    }

    /// Density at many points (`exp` of [`logpdf_many`](Self::logpdf_many)).
    pub fn pdf_many(&self, xs: &[Vec<f64>]) -> Result<Vec<f64>, StatsError> {
        let mut values = self.logpdf_many(xs)?;
        for value in &mut values {
            *value = value.exp();
        }
        Ok(values)
    }

    /// Mean vector (defined as `loc` for `df > 1`).
    pub fn mean(&self) -> Vec<f64> {
        self.loc.clone()
    }
}

/// The matrix normal distribution, matching
/// `scipy.stats.matrix_normal(mean, rowcov, colcov)`.
pub struct MatrixNormal {
    mean: Vec<Vec<f64>>,
    chol_u: Vec<Vec<f64>>,
    chol_v: Vec<Vec<f64>>,
    log_det_u: f64,
    log_det_v: f64,
}

impl MatrixNormal {
    /// Create the distribution: `mean` is `n×p`, `rowcov` is the `n×n`
    /// among-row covariance `U`, `colcov` the `p×p` among-column covariance `V`.
    pub fn new(
        mean: &[Vec<f64>],
        rowcov: &[Vec<f64>],
        colcov: &[Vec<f64>],
    ) -> Result<Self, StatsError> {
        if mean.is_empty() || mean[0].is_empty() {
            return Err(StatsError::InvalidArgument(
                "mean must be non-empty".to_string(),
            ));
        }
        let (nrow, ncol) = (mean.len(), mean[0].len());
        if rowcov.len() != nrow || colcov.len() != ncol {
            return Err(StatsError::InvalidArgument(
                "rowcov/colcov dimensions must match mean".to_string(),
            ));
        }
        let chol_u = cholesky_decompose(rowcov)?;
        let chol_v = cholesky_decompose(colcov)?;
        let log_det_u = 2.0 * (0..nrow).map(|i| chol_u[i][i].ln()).sum::<f64>();
        let log_det_v = 2.0 * (0..ncol).map(|i| chol_v[i][i].ln()).sum::<f64>();
        Ok(Self {
            mean: mean.to_vec(),
            chol_u,
            chol_v,
            log_det_u,
            log_det_v,
        })
    }

    /// Log probability density function.
    pub fn logpdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        let (n, p) = (self.mean.len(), self.mean[0].len());
        if x.len() != n || x.iter().any(|r| r.len() != p) {
            return Err(StatsError::InvalidArgument(
                "x dimensions must match mean".to_string(),
            ));
        }
        // A = X - M.
        let a: Vec<Vec<f64>> = (0..n)
            .map(|i| (0..p).map(|j| x[i][j] - self.mean[i][j]).collect())
            .collect();
        // Y = L_U⁻¹ A via ONE multi-RHS forward substitution over all p columns
        // instead of p separate single-RHS solves. `acc[j] = Σ_{k<i} L[i][k]·Y[k][j]`
        // accumulates k in 0..i order — the same left-fold (from 0.0) as the
        // per-column `(0..i).map(..).sum()` — so Y is BYTE-IDENTICAL, while the
        // contiguous inner j-loops vectorize (axpy across RHS) and the per-column
        // gather/alloc/scatter is gone.
        let mut y = vec![vec![0.0_f64; p]; n];
        let mut acc = vec![0.0_f64; p];
        for i in 0..n {
            let lii = self.chol_u[i][i];
            if lii == 0.0 {
                return Err(StatsError::InvalidArgument(
                    "singular lower-triangular system".to_string(),
                ));
            }
            for av in acc.iter_mut() {
                *av = 0.0;
            }
            for (k, yk) in y.iter().enumerate().take(i) {
                let lik = self.chol_u[i][k];
                for (av, &ykj) in acc.iter_mut().zip(yk.iter()) {
                    *av += lik * ykj;
                }
            }
            let yi = &mut y[i];
            for j in 0..p {
                yi[j] = (a[i][j] - acc[j]) / lii;
            }
        }
        // maha = ‖Y L_V⁻ᵀ‖_F² = Σ_i ‖L_V⁻¹·y[i]‖² via ONE multi-RHS forward
        // substitution: transpose Y (n×p) so the n RHS columns (= y rows) are
        // contiguous, solve all at once (acc[i] left-folds k in 0..r — the same
        // order as the per-row `(0..r).map(..).sum()`), then accumulate ‖·‖²
        // i-outer/r-inner to match the per-row ‖wi‖² loop term-for-term.
        // BYTE-IDENTICAL, with the contiguous inner i-loops vectorizing.
        let mut yt = vec![vec![0.0_f64; n]; p];
        for (i, yi) in y.iter().enumerate() {
            for (r, &v) in yi.iter().enumerate() {
                yt[r][i] = v;
            }
        }
        let mut wmat = vec![vec![0.0_f64; n]; p];
        let mut acc2 = vec![0.0_f64; n];
        for r in 0..p {
            let lrr = self.chol_v[r][r];
            if lrr == 0.0 {
                return Err(StatsError::InvalidArgument(
                    "singular lower-triangular system".to_string(),
                ));
            }
            for av in acc2.iter_mut() {
                *av = 0.0;
            }
            for (k, wk) in wmat.iter().enumerate().take(r) {
                let lrk = self.chol_v[r][k];
                for (av, &wki) in acc2.iter_mut().zip(wk.iter()) {
                    *av += lrk * wki;
                }
            }
            let wr = &mut wmat[r];
            for i in 0..n {
                wr[i] = (yt[r][i] - acc2[i]) / lrr;
            }
        }
        let mut maha = 0.0_f64;
        // Column-wise sum of a row-major matrix, as above: `i` is the inner
        // index across p rows of `wmat`.
        #[allow(clippy::needless_range_loop)]
        for i in 0..n {
            maha += (0..p).map(|r| wmat[r][i] * wmat[r][i]).sum::<f64>();
        }
        let (nf, pf) = (n as f64, p as f64);
        let two_pi = 2.0 * std::f64::consts::PI;
        Ok(-0.5 * (nf * pf * two_pi.ln() + pf * self.log_det_u + nf * self.log_det_v + maha))
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }
}

/// Log of the multivariate gamma function `Γ_p(a) = π^{p(p-1)/4} Π Γ(a+(1-i)/2)`.
fn ln_multivariate_gamma(p: usize, a: f64) -> f64 {
    let pf = p as f64;
    let mut s = pf * (pf - 1.0) / 4.0 * std::f64::consts::PI.ln();
    for i in 1..=p {
        s += ln_gamma(a + (1.0 - i as f64) / 2.0);
    }
    s
}

/// The Wishart distribution, matching `scipy.stats.wishart(df, scale)`.
pub struct Wishart {
    df: f64,
    scale: Vec<Vec<f64>>,
    chol_v: Vec<Vec<f64>>,
    ln_det_v: f64,
    p: usize,
}

impl Wishart {
    /// Create the distribution with `df` degrees of freedom and `p×p` positive
    /// definite `scale` matrix.
    pub fn new(df: f64, scale: &[Vec<f64>]) -> Result<Self, StatsError> {
        let p = scale.len();
        if p == 0 {
            return Err(StatsError::InvalidArgument(
                "scale must be non-empty".to_string(),
            ));
        }
        let chol_v = cholesky_decompose(scale)?;
        let ln_det_v = 2.0 * (0..p).map(|i| chol_v[i][i].ln()).sum::<f64>();
        Ok(Self {
            df,
            scale: scale.to_vec(),
            chol_v,
            ln_det_v,
            p,
        })
    }

    /// Log probability density function at a `p×p` symmetric positive-definite
    /// matrix `x`.
    pub fn logpdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        let p = self.p;
        if x.len() != p || x.iter().any(|r| r.len() != p) {
            return Err(StatsError::InvalidArgument(
                "x dimension must match scale".to_string(),
            ));
        }
        let chol_x = cholesky_decompose(x)?;
        let ln_det_x = 2.0 * (0..p).map(|i| chol_x[i][i].ln()).sum::<f64>();
        // tr(V⁻¹X) = ‖L_V⁻¹ · chol(X)‖_F² (X = chol_x·chol_xᵀ), via one multi-RHS
        // solve (byte-identical to the per-column ‖solve(L_V, col_j)‖² loop).
        let tr = frob_sq_inv_chol_cols(&self.chol_v, &chol_x, p)?;
        let (n, pf) = (self.df, p as f64);
        Ok((n - pf - 1.0) / 2.0 * ln_det_x
            - 0.5 * tr
            - n * pf / 2.0 * 2.0_f64.ln()
            - n / 2.0 * self.ln_det_v
            - ln_multivariate_gamma(p, n / 2.0))
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }

    /// Mean `df · scale`.
    pub fn mean(&self) -> Vec<Vec<f64>> {
        self.scale
            .iter()
            .map(|row| row.iter().map(|&v| self.df * v).collect())
            .collect()
    }
}

/// The inverse Wishart distribution, matching `scipy.stats.invwishart(df, scale)`.
pub struct InvWishart {
    df: f64,
    scale: Vec<Vec<f64>>,
    chol_v: Vec<Vec<f64>>,
    ln_det_v: f64,
    p: usize,
}

impl InvWishart {
    /// Create the distribution with `df` degrees of freedom and `p×p` positive
    /// definite `scale` matrix.
    pub fn new(df: f64, scale: &[Vec<f64>]) -> Result<Self, StatsError> {
        let p = scale.len();
        if p == 0 {
            return Err(StatsError::InvalidArgument(
                "scale must be non-empty".to_string(),
            ));
        }
        let chol_v = cholesky_decompose(scale)?;
        let ln_det_v = 2.0 * (0..p).map(|i| chol_v[i][i].ln()).sum::<f64>();
        Ok(Self {
            df,
            scale: scale.to_vec(),
            chol_v,
            ln_det_v,
            p,
        })
    }

    /// Log probability density function at a `p×p` symmetric positive-definite
    /// matrix `x`.
    pub fn logpdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        let p = self.p;
        if x.len() != p || x.iter().any(|r| r.len() != p) {
            return Err(StatsError::InvalidArgument(
                "x dimension must match scale".to_string(),
            ));
        }
        let chol_x = cholesky_decompose(x)?;
        let ln_det_x = 2.0 * (0..p).map(|i| chol_x[i][i].ln()).sum::<f64>();
        // tr(V·X⁻¹) = ‖L_X⁻¹ · chol(V)‖_F² (V = chol_v·chol_vᵀ), via one multi-RHS
        // solve (byte-identical to the per-column ‖solve(L_X, col_j)‖² loop).
        let tr = frob_sq_inv_chol_cols(&chol_x, &self.chol_v, p)?;
        let (n, pf) = (self.df, p as f64);
        Ok(n / 2.0 * self.ln_det_v
            - n * pf / 2.0 * 2.0_f64.ln()
            - ln_multivariate_gamma(p, n / 2.0)
            - (n + pf + 1.0) / 2.0 * ln_det_x
            - 0.5 * tr)
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }

    /// Mean `scale / (df − p − 1)` (defined for `df > p + 1`).
    pub fn mean(&self) -> Vec<Vec<f64>> {
        let denom = self.df - self.p as f64 - 1.0;
        self.scale
            .iter()
            .map(|row| row.iter().map(|&v| v / denom).collect())
            .collect()
    }
}

/// The normal-inverse-gamma distribution over `(x, σ²)`, matching
/// `scipy.stats.normal_inverse_gamma(mu, lmbda, a, b)`: `x | σ² ~
/// Normal(μ, σ²/λ)`, `σ² ~ InvGamma(a, b)`.
pub struct NormalInverseGamma {
    mu: f64,
    lmbda: f64,
    a: f64,
    b: f64,
}

impl NormalInverseGamma {
    /// Create the distribution with location `mu`, precision-scale `lmbda`, and
    /// inverse-gamma shape/scale `a`/`b` (all of `lmbda`, `a`, `b` positive).
    pub fn new(mu: f64, lmbda: f64, a: f64, b: f64) -> Self {
        Self { mu, lmbda, a, b }
    }

    /// Joint log probability density at `(x, s2)`; `-inf` for `s2 ≤ 0`.
    pub fn logpdf(&self, x: f64, s2: f64) -> f64 {
        if s2 <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let two_pi = 2.0 * std::f64::consts::PI;
        0.5 * self.lmbda.ln() - 0.5 * two_pi.ln() + self.a * self.b.ln()
            - ln_gamma(self.a)
            - (self.a + 1.5) * s2.ln()
            - (self.lmbda * (x - self.mu).powi(2) + 2.0 * self.b) / (2.0 * s2)
    }

    /// Joint probability density at `(x, s2)`.
    pub fn pdf(&self, x: f64, s2: f64) -> f64 {
        self.logpdf(x, s2).exp()
    }
}

/// The von Mises-Fisher distribution on the unit `(p−1)`-sphere, matching
/// `scipy.stats.vonmises_fisher(mu, kappa)`.
pub struct VonMisesFisher {
    mu: Vec<f64>,
    kappa: f64,
}

impl VonMisesFisher {
    /// Create the distribution with mean direction `mu` (a unit vector) and
    /// concentration `kappa`.
    pub fn new(mu: &[f64], kappa: f64) -> Self {
        Self {
            mu: mu.to_vec(),
            kappa,
        }
    }

    /// Log probability density at a unit vector `x`:
    /// `(p/2−1)ln κ − (p/2)ln 2π − ln I_{p/2−1}(κ) + κ·μᵀx`.
    pub fn logpdf(&self, x: &[f64]) -> f64 {
        if x.len() != self.mu.len() {
            return f64::NEG_INFINITY;
        }
        let p = self.mu.len() as f64;
        let v = p / 2.0 - 1.0;
        let dot: f64 = self.mu.iter().zip(x).map(|(&mi, &xi)| mi * xi).sum();
        // ln I_v(κ) = ln(I_v(κ)·e^{−κ}) + κ, stable for large κ.
        let ln_iv = fsci_special::ive_scalar(v, self.kappa).ln() + self.kappa;
        v * self.kappa.ln() - (p / 2.0) * (2.0 * std::f64::consts::PI).ln() - ln_iv
            + self.kappa * dot
    }

    /// Probability density at a unit vector `x`.
    pub fn pdf(&self, x: &[f64]) -> f64 {
        self.logpdf(x).exp()
    }
}

/// Fisher's noncentral hypergeometric distribution, matching
/// `scipy.stats.nchypergeom_fisher(M, n, N, odds)`.
pub struct NoncentralHypergeomFisher {
    lo: usize,
    /// pmf over the support, indexed from `lo`.
    pmf: Vec<f64>,
}

impl NoncentralHypergeomFisher {
    /// Create the distribution: `m_total` items, `n_type1` of type 1, `n_draw`
    /// drawn, with odds ratio `odds`.
    pub fn new(m_total: usize, n_type1: usize, n_draw: usize, odds: f64) -> Self {
        let lo = n_draw.saturating_sub(m_total - n_type1);
        let hi = n_type1.min(n_draw);
        let ln_c = |a: usize, b: usize| -> f64 {
            ln_gamma(a as f64 + 1.0) - ln_gamma(b as f64 + 1.0) - ln_gamma((a - b) as f64 + 1.0)
        };
        // Unnormalized log-weights w_k = lnC(n,k)+lnC(M-n,N-k)+k·ln(odds).
        let logw: Vec<f64> = (lo..=hi)
            .map(|k| ln_c(n_type1, k) + ln_c(m_total - n_type1, n_draw - k) + k as f64 * odds.ln())
            .collect();
        let max = logw.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let denom: f64 = logw.iter().map(|&w| (w - max).exp()).sum();
        let pmf: Vec<f64> = logw.iter().map(|&w| (w - max).exp() / denom).collect();
        Self { lo, pmf }
    }

    /// Probability mass function `P(X = k)`.
    pub fn pmf(&self, k: usize) -> f64 {
        if k < self.lo {
            return 0.0;
        }
        self.pmf.get(k - self.lo).copied().unwrap_or(0.0)
    }

    /// Cumulative distribution function `P(X ≤ k)`.
    pub fn cdf(&self, k: usize) -> f64 {
        if k < self.lo {
            return 0.0;
        }
        self.pmf.iter().take(k - self.lo + 1).sum()
    }

    /// Mean `Σ k·P(X=k)`.
    pub fn mean(&self) -> f64 {
        self.pmf
            .iter()
            .enumerate()
            .map(|(i, &p)| (self.lo + i) as f64 * p)
            .sum()
    }

    /// Variance `Σ k²·P(X=k) − mean²`.
    pub fn var(&self) -> f64 {
        let m = self.mean();
        let e2: f64 = self
            .pmf
            .iter()
            .enumerate()
            .map(|(i, &p)| ((self.lo + i) as f64).powi(2) * p)
            .sum();
        e2 - m * m
    }
}

/// The matrix t-distribution, matching `scipy.stats.matrix_t(mean, row_spread,
/// col_spread, df)`.
pub struct MatrixT {
    mean: Vec<Vec<f64>>,
    df: f64,
    chol_u: Vec<Vec<f64>>,
    chol_v: Vec<Vec<f64>>,
    ln_det_u: f64,
    ln_det_v: f64,
}

impl MatrixT {
    /// Create the distribution: `mean` is `m×n`, `row_spread` the `m×m` matrix
    /// `U`, `col_spread` the `n×n` matrix `V`, with `df` degrees of freedom.
    pub fn new(
        mean: &[Vec<f64>],
        row_spread: &[Vec<f64>],
        col_spread: &[Vec<f64>],
        df: f64,
    ) -> Result<Self, StatsError> {
        if mean.is_empty() || mean[0].is_empty() {
            return Err(StatsError::InvalidArgument(
                "mean must be non-empty".to_string(),
            ));
        }
        let (m, n) = (mean.len(), mean[0].len());
        if row_spread.len() != m || col_spread.len() != n {
            return Err(StatsError::InvalidArgument(
                "spread dimensions must match mean".to_string(),
            ));
        }
        let chol_u = cholesky_decompose(row_spread)?;
        let chol_v = cholesky_decompose(col_spread)?;
        let ln_det_u = 2.0 * (0..m).map(|i| chol_u[i][i].ln()).sum::<f64>();
        let ln_det_v = 2.0 * (0..n).map(|i| chol_v[i][i].ln()).sum::<f64>();
        Ok(Self {
            mean: mean.to_vec(),
            df,
            chol_u,
            chol_v,
            ln_det_u,
            ln_det_v,
        })
    }

    /// Log probability density function at an `m×n` matrix `x`.
    pub fn logpdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        let (m, n) = (self.mean.len(), self.mean[0].len());
        if x.len() != m || x.iter().any(|r| r.len() != n) {
            return Err(StatsError::InvalidArgument(
                "x dimension must match mean".to_string(),
            ));
        }
        // C = X - M.
        let c: Vec<Vec<f64>> = (0..m)
            .map(|i| (0..n).map(|j| x[i][j] - self.mean[i][j]).collect())
            .collect();
        // W = L_U⁻¹ C (m×n), solved as ONE multi-RHS forward substitution over all
        // n columns instead of n separate single-RHS solves. For each row i,
        // `acc[j] = Σ_{k<i} L[i][k]·w[k][j]` accumulates k in 0..i order — the same
        // left-fold (from 0.0) as the per-column `(0..i).map(..).sum()` — so the
        // result is BYTE-IDENTICAL, while the contiguous inner j-loops vectorize
        // (axpy across RHS) and the per-column gather/alloc/scatter is gone.
        let mut w = vec![vec![0.0_f64; n]; m];
        let mut acc = vec![0.0_f64; n];
        for i in 0..m {
            let lii = self.chol_u[i][i];
            if lii == 0.0 {
                return Err(StatsError::InvalidArgument(
                    "singular lower-triangular system".to_string(),
                ));
            }
            for a in acc.iter_mut() {
                *a = 0.0;
            }
            for (k, wk) in w.iter().enumerate().take(i) {
                let lik = self.chol_u[i][k];
                for (a, &wkj) in acc.iter_mut().zip(wk.iter()) {
                    *a += lik * wkj;
                }
            }
            let wi = &mut w[i];
            for j in 0..n {
                wi[j] = (c[i][j] - acc[j]) / lii;
            }
        }
        // V + A (n×n), then ln det via Cholesky; ln|I + CᵀU⁻¹C·V⁻¹| = ln|V+A| - ln|V|.
        // V + A is symmetric (A = WᵀW; col_spread reconstructs V = L_V·L_Vᵀ),
        // so compute the upper triangle once and mirror it — halves the
        // O(m·n²) Gram sums. Each entry is bit-identical to the full build
        // (products commute, summed in the same r-order), so va[j][i] = va[i][j]
        // exactly.
        let mut va = vec![vec![0.0_f64; n]; n];
        for i in 0..n {
            for j in i..n {
                let a_ij: f64 = (0..m).map(|r| w[r][i] * w[r][j]).sum();
                va[i][j] = a_ij + self.col_spread_entry(i, j);
            }
        }
        // Mirror the upper triangle into the lower. Both indices address `va`, and
        // the loop WRITES va[i][j] while READING va[j][i], so an iterator form
        // would need split_at_mut and would be strictly harder to read than the
        // index form. The bounds are the point of the loop, not an accident.
        #[allow(clippy::needless_range_loop)]
        for i in 0..n {
            for j in 0..i {
                va[i][j] = va[j][i];
            }
        }
        let chol_va = cholesky_decompose(&va)?;
        let ln_det_va = 2.0 * (0..n).map(|i| chol_va[i][i].ln()).sum::<f64>();
        let logdet = ln_det_va - self.ln_det_v;

        let (mf, nf) = (m as f64, n as f64);
        let df = self.df;
        let pi = std::f64::consts::PI;
        Ok(-(df + mf + nf - 1.0) / 2.0 * logdet
            + ln_multivariate_gamma(n, (df + mf + nf - 1.0) / 2.0)
            - ln_multivariate_gamma(n, (df + nf - 1.0) / 2.0)
            - mf * nf / 2.0 * pi.ln()
            - nf / 2.0 * self.ln_det_u
            - mf / 2.0 * self.ln_det_v)
    }

    /// Reconstruct the `(i, j)` entry of the column-spread matrix `V` from its
    /// Cholesky factor: `V = L_V·L_Vᵀ`, so `V[i][j] = Σ_k L[i][k]·L[j][k]`.
    fn col_spread_entry(&self, i: usize, j: usize) -> f64 {
        (0..=i.min(j))
            .map(|k| self.chol_v[i][k] * self.chol_v[j][k])
            .sum()
    }

    /// Probability density function.
    pub fn pdf(&self, x: &[Vec<f64>]) -> Result<f64, StatsError> {
        Ok(self.logpdf(x)?.exp())
    }
}

/// The generalized inverse Gaussian distribution, matching
/// `scipy.stats.geninvgauss(p, b)` (support `x > 0`).
pub struct GenInvGauss {
    p: f64,
    b: f64,
}

impl GenInvGauss {
    /// Create the distribution with shape parameters `p` and `b > 0`.
    pub fn new(p: f64, b: f64) -> Self {
        Self { p, b }
    }

    /// Log-density at many positive samples, computing the parameter-only
    /// `ln K_p(b)` normalizer once for the complete batch. Each output keeps
    /// the scalar [`Self::logpdf`] operation order.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let ln_kp = fsci_special::bessel::kve_scalar(self.p.abs(), self.b).ln() - self.b;
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return f64::NEG_INFINITY;
            }
            (self.p - 1.0) * x.ln() - self.b * (x + 1.0 / x) / 2.0 - 2.0_f64.ln() - ln_kp
        })
    }

    /// Log probability density at `x` (`-inf` for `x ≤ 0`):
    /// `(p−1)ln x − b(x+1/x)/2 − ln 2 − ln K_p(b)`.
    pub fn logpdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        // ln K_p(b) = ln(K_p(b)·e^b) − b, K_{-p}=K_p so use |p|.
        let ln_kp = fsci_special::bessel::kve_scalar(self.p.abs(), self.b).ln() - self.b;
        (self.p - 1.0) * x.ln() - self.b * (x + 1.0 / x) / 2.0 - 2.0_f64.ln() - ln_kp
    }

    /// Probability density at `x`.
    pub fn pdf(&self, x: f64) -> f64 {
        self.logpdf(x).exp()
    }
}

/// Stable log of the modified Bessel function of the second kind `ln K_v(z)`,
/// `z > 0`, via fsci-special's exponentially-scaled `kve` (`K_{-v}=K_v`).
fn ln_bessel_k(v: f64, z: f64) -> f64 {
    fsci_special::bessel::kve_scalar(v.abs(), z).ln() - z
}

/// The generalized hyperbolic distribution, matching
/// `scipy.stats.genhyperbolic(p, a, b)` (`|b| < a`).
pub struct GenHyperbolic {
    p: f64,
    a: f64,
    b: f64,
}

impl GenHyperbolic {
    /// Create the distribution with tail/shape `p`, `a` and skew `b` (`|b| < a`).
    pub fn new(p: f64, a: f64, b: f64) -> Self {
        Self { p, a, b }
    }

    /// Log-density at many samples, computing the parameter-only Bessel-K
    /// normalizer once. Each output preserves scalar operation order.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let (p, a, b) = (self.p, self.a, self.b);
        let t = (a * a - b * b).sqrt();
        let ln_kpt = ln_bessel_k(p, t);
        par_continuous_map_min(xs, 65536, |x| {
            let r = (1.0 + x * x).sqrt();
            (p / 2.0) * (a * a - b * b).ln()
                - 0.5 * (2.0 * std::f64::consts::PI).ln()
                - (p - 0.5) * a.ln()
                - ln_kpt
                + (p - 0.5) * r.ln()
                + ln_bessel_k(p - 0.5, a * r)
                + b * x
        })
    }

    /// Log probability density at `x`.
    pub fn logpdf(&self, x: f64) -> f64 {
        let (p, a, b) = (self.p, self.a, self.b);
        let t = (a * a - b * b).sqrt();
        let r = (1.0 + x * x).sqrt();
        (p / 2.0) * (a * a - b * b).ln()
            - 0.5 * (2.0 * std::f64::consts::PI).ln()
            - (p - 0.5) * a.ln()
            - ln_bessel_k(p, t)
            + (p - 0.5) * r.ln()
            + ln_bessel_k(p - 0.5, a * r)
            + b * x
    }

    /// Probability density at `x`.
    pub fn pdf(&self, x: f64) -> f64 {
        self.logpdf(x).exp()
    }
}

/// The Jones and Faddy skew-t distribution, matching
/// `scipy.stats.jf_skew_t(a, b)`.
pub struct JfSkewT {
    a: f64,
    b: f64,
}

impl JfSkewT {
    /// Create the distribution with shape parameters `a`, `b > 0`.
    pub fn new(a: f64, b: f64) -> Self {
        Self { a, b }
    }

    /// Log-density at many samples, computing the parameter-only beta
    /// normalizer once. Each output preserves scalar operation order.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let (a, b) = (self.a, self.b);
        let ln_beta = ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b);
        par_continuous_map_min(xs, 65536, |x| {
            let s = (a + b + x * x).sqrt();
            let u = x / s;
            -(a + b - 1.0) * 2.0_f64.ln() - ln_beta - 0.5 * (a + b).ln()
                + (a + 0.5) * (1.0 + u).ln()
                + (b + 0.5) * (1.0 - u).ln()
        })
    }

    /// Log probability density at `x`.
    pub fn logpdf(&self, x: f64) -> f64 {
        let (a, b) = (self.a, self.b);
        let s = (a + b + x * x).sqrt();
        let u = x / s;
        // ln c = -(a+b-1)ln2 - lnB(a,b) - ½ln(a+b); lnB = lnΓ(a)+lnΓ(b)-lnΓ(a+b).
        let ln_beta = ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b);
        -(a + b - 1.0) * 2.0_f64.ln() - ln_beta - 0.5 * (a + b).ln()
            + (a + 0.5) * (1.0 + u).ln()
            + (b + 0.5) * (1.0 - u).ln()
    }

    /// Probability density at `x`.
    pub fn pdf(&self, x: f64) -> f64 {
        self.logpdf(x).exp()
    }
}

/// Scalar Gauss hypergeometric `₂F₁(a, b; c; z)` via fsci-special's tensor API.
fn hyp2f1_scalar(a: f64, b: f64, c: f64, z: f64) -> f64 {
    match fsci_special::hyp2f1(
        &fsci_special::SpecialTensor::RealScalar(a),
        &fsci_special::SpecialTensor::RealScalar(b),
        &fsci_special::SpecialTensor::RealScalar(c),
        &fsci_special::SpecialTensor::RealScalar(z),
        RuntimeMode::Strict,
    ) {
        Ok(fsci_special::SpecialTensor::RealScalar(v)) => v,
        _ => f64::NAN,
    }
}

/// The Gauss hypergeometric distribution, matching
/// `scipy.stats.gausshyper(a, b, c, z)` (support `x ∈ (0, 1)`).
pub struct GaussHyper {
    a: f64,
    b: f64,
    c: f64,
    z: f64,
    log_norm: f64,
}

impl GaussHyper {
    /// Create the distribution with parameters `a, b > 0`, `c`, `z > -1`.
    pub fn new(a: f64, b: f64, c: f64, z: f64) -> Self {
        // Normalizing constant 1 / (B(a,b)·₂F₁(c, a; a+b; −z)).
        let ln_beta = ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b);
        let log_norm = ln_beta + hyp2f1_scalar(c, a, a + b, -z).ln();
        Self {
            a,
            b,
            c,
            z,
            log_norm,
        }
    }

    /// Log probability density at `x` (`-inf` outside `(0, 1)`):
    /// `(a−1)ln x + (b−1)ln(1−x) − c·ln(1+zx) − ln[B(a,b)·₂F₁(c,a;a+b;−z)]`.
    pub fn logpdf(&self, x: f64) -> f64 {
        if x <= 0.0 || x >= 1.0 {
            return f64::NEG_INFINITY;
        }
        (self.a - 1.0) * x.ln() + (self.b - 1.0) * (1.0 - x).ln()
            - self.c * (1.0 + self.z * x).ln()
            - self.log_norm
    }

    /// Probability density at `x`.
    pub fn pdf(&self, x: f64) -> f64 {
        self.logpdf(x).exp()
    }
}

/// The double Pareto-lognormal distribution, matching
/// `scipy.stats.dpareto_lognorm(u, s, a, b)` (support `x > 0`).
pub struct DparetoLognorm {
    u: f64,
    s: f64,
    a: f64,
    b: f64,
}

impl DparetoLognorm {
    /// Create the distribution with lognormal location `u`, scale `s > 0`, and
    /// Pareto tail indices `a, b > 0`.
    pub fn new(u: f64, s: f64, a: f64, b: f64) -> Self {
        Self { u, s, a, b }
    }

    /// Log probability density at `x` (`-inf` for `x ≤ 0`).
    pub fn logpdf(&self, x: f64) -> f64 {
        if x <= 0.0 || !x.is_finite() {
            return f64::NEG_INFINITY;
        }
        let half_ln_2pi = 0.5 * (2.0 * std::f64::consts::PI).ln();
        // log standard-normal pdf.
        let log_phi = |t: f64| -0.5 * t * t - half_ln_2pi;
        // log Mills ratio: log Φ(−t) − log φ(t).
        let log_r = |t: f64| fsci_special::log_ndtr_scalar(-t) - log_phi(t);

        let log_y = x.ln();
        let z = (log_y - self.u) / self.s;
        let x1 = self.a * self.s - z;
        let x2 = self.b * self.s + z;
        let (r1, r2) = (log_r(x1), log_r(x2));
        let m = r1.max(r2);
        let logaddexp = m + ((r1 - m).exp() + (r2 - m).exp()).ln();

        self.a.ln() + self.b.ln() - (self.a + self.b).ln() - log_y + log_phi(z) + logaddexp
    }

    /// Probability density at `x`.
    pub fn pdf(&self, x: f64) -> f64 {
        self.logpdf(x).exp()
    }
}

/// The Kolmogorov-Smirnov one-sided (Smirnov) distribution of the statistic
/// `D⁺_n`, matching `scipy.stats.ksone(n)`.
pub struct KsOne {
    n: usize,
}

impl KsOne {
    /// Create the distribution for sample size `n`.
    pub fn new(n: usize) -> Self {
        Self { n }
    }

    /// Survival function `P(D⁺_n ≥ d)` via Smirnov's exact formula
    /// `d·Σ_{j=0}^{⌊n(1−d)⌋} C(n,j)(1−d−j/n)^{n−j}(d+j/n)^{j−1}`.
    pub fn sf(&self, d: f64) -> f64 {
        if d <= 0.0 {
            return 1.0;
        }
        if d >= 1.0 {
            return 0.0;
        }
        let nf = self.n as f64;
        let jmax = (nf * (1.0 - d)).floor() as usize;
        let ln_n_fact = ln_gamma(nf + 1.0);
        let mut sum = 0.0_f64;
        for j in 0..=jmax {
            let jf = j as f64;
            let base1 = 1.0 - d - jf / nf;
            if base1 < 0.0 {
                break;
            }
            let base2 = d + jf / nf;
            let lnc = ln_n_fact - ln_gamma(jf + 1.0) - ln_gamma(nf - jf + 1.0);
            // (n-j) ≥ 1 here, so base1==0 ⇒ ln term -inf ⇒ exp 0 (no 0·-inf NaN).
            let log_term = lnc + (nf - jf) * base1.ln() + (jf - 1.0) * base2.ln();
            sum += log_term.exp();
        }
        (d * sum).clamp(0.0, 1.0)
    }

    /// Cumulative distribution function `P(D⁺_n ≤ d)`.
    pub fn cdf(&self, d: f64) -> f64 {
        1.0 - self.sf(d)
    }
}

// ══════════════════════════════════════════════════════════════════════
// Von Mises Distribution
// ══════════════════════════════════════════════════════════════════════

/// Von Mises circular distribution.
///
/// Matches `scipy.stats.vonmises(kappa, loc=loc)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct VonMises {
    pub kappa: f64,
    pub loc: f64,
}

/// Ratios `I_k(κ)/I_0(κ)` for `k = 0..=k_max` (r[0] = 1) via one Miller DOWNWARD
/// recurrence `r_{k−1} = r_{k+1} + (2k/κ) r_k` (seed r_m=0, normalize by r_0, with
/// overflow rescaling). O(k_max) total, vs O(k_max) FRESH `I_k` Bessel evals (each
/// O(κ) work ⇒ O(κ²)). Requires κ > 0. Shared by VonMises cdf/var/kurtosis.
fn von_mises_bessel_i0_ratios(kappa: f64, k_max: usize) -> Vec<f64> {
    let m = k_max + 20 + (40.0 * kappa).sqrt() as usize + 10;
    let mut r = vec![0.0_f64; k_max + 2];
    let mut r_kp1 = 0.0_f64;
    let mut r_k = 1.0e-30_f64;
    for k in (1..=m).rev() {
        let r_km1 = r_kp1 + (2.0 * k as f64 / kappa) * r_k;
        if k - 1 <= k_max + 1 {
            r[k - 1] = r_km1;
        }
        r_kp1 = r_k;
        r_k = r_km1;
        if r_k > 1.0e250 {
            let s = 1.0e-250;
            r_k *= s;
            r_kp1 *= s;
            for v in r.iter_mut() {
                *v *= s;
            }
        }
    }
    let inv0 = 1.0 / r_k; // r_k holds r_0 after the descent to k = 1
    for v in r.iter_mut() {
        *v *= inv0;
    }
    r.truncate(k_max + 1);
    r
}

/// Number of significant Bessel-Fourier terms for VonMises at concentration κ
/// (ratios decay super-exponentially past k ≈ κ).
fn von_mises_k_max(kappa: f64) -> usize {
    (kappa + 12.0 * kappa.sqrt() + 20.0).ceil().max(3.0) as usize
}

impl VonMises {
    #[must_use]
    pub fn new(kappa: f64, loc: f64) -> Self {
        assert!(kappa >= 0.0, "kappa must be non-negative, got {kappa}");
        Self { kappa, loc }
    }

    /// Log-density at many angles, hoisting `ln(2π)` and `ln I₀(κ)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (same `− ln2π − ln_i0`
    /// subtraction order).
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let ln_2pi = (2.0 * PI).ln();
        let ln_i0 = fsci_special::log_ive_scalar(0.0, self.kappa) + self.kappa;
        par_continuous_map_min(xs, 65536, |x| {
            self.kappa * (x - self.loc).cos() - ln_2pi - ln_i0
        })
    }

    /// Density at many angles; hoists the `2π·I₀(κ)` denominator (Bessel I₀) like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let denom = 2.0 * PI * modified_bessel_i(0.0, self.kappa);
        par_continuous_map_min(xs, 65536, |x| {
            (self.kappa * (x - self.loc).cos()).exp() / denom
        })
    }

    fn period_start(&self) -> f64 {
        self.loc - PI
    }

    fn base_cdf(&self, x: f64) -> f64 {
        let start = self.period_start();
        let end = start + 2.0 * PI;
        if x <= start {
            return 0.0;
        }
        if x >= end {
            return 1.0;
        }

        // Exact Bessel–Fourier series instead of trapezoidal integration of the
        // pdf, whose O(h²) error grew with κ (≈4e-6 at κ=50) as the pdf sharpens:
        //   F(z) = (z+π)/(2π) + (1/π) Σ_{k≥1} (I_k(κ)/I_0(κ))/k · sin(kz),
        // with z = x − loc ∈ (−π, π). Exponentially-scaled ratios
        // ive_k/ive_0 = I_k/I_0 stay overflow-safe for all κ. Matches scipy to
        // ~1e-15 for κ≲20 and the true value beyond (where scipy's own cdf
        // drifts ~3e-6, confirmed against mpmath). frankenscipy-1qmf4
        let z = x - self.loc;
        let kappa = self.kappa;
        if kappa <= 0.0 {
            // κ = 0 is the circular uniform.
            return ((z + PI) / (2.0 * PI)).clamp(0.0, 1.0);
        }
        // F(z) = (z+π)/2π + (1/π) Σ_k (I_k(κ)/I_0(κ))/k sin(kz). Stream all ratios
        // via one Miller recurrence (O(κ)) — see `von_mises_bessel_i0_ratios`.
        let k_max = von_mises_k_max(kappa);
        let r = von_mises_bessel_i0_ratios(kappa, k_max);
        let mut sum = 0.0_f64;
        for (kk, &ratio) in r.iter().enumerate().take(k_max + 1).skip(1) {
            let kf = kk as f64;
            sum += ratio / kf * (kf * z).sin();
            if kk > 2 && ratio / kf < 1.0e-17 {
                break;
            }
        }
        ((z + PI) / (2.0 * PI) + sum / PI).clamp(0.0, 1.0)
    }

    #[must_use]
    pub fn circular_variance(&self) -> f64 {
        self.var()
    }
}

impl ContinuousDistribution for VonMises {
    fn pdf(&self, x: f64) -> f64 {
        let i0 = modified_bessel_i(0.0, self.kappa);
        (self.kappa * (x - self.loc).cos()).exp() / (2.0 * PI * i0)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // κ·cos(x−loc) − ln(2π) − ln I₀(κ); ln I₀(κ) = log_ive(0,κ) + κ stays
        // finite for large κ where the pdf's I₀(κ) overflows. frankenscipy-7m3xk
        let ln_i0 = fsci_special::log_ive_scalar(0.0, self.kappa) + self.kappa;
        self.kappa * (x - self.loc).cos() - (2.0 * PI).ln() - ln_i0
    }

    fn cdf(&self, x: f64) -> f64 {
        let start = self.period_start();
        let period = 2.0 * PI;
        let cycles = ((x - start) / period).floor();
        let reduced = x - cycles * period;
        cycles + self.base_cdf(reduced)
    }

    fn mean(&self) -> f64 {
        self.loc
    }

    fn var(&self) -> f64 {
        // scipy.stats.vonmises reports the LINEAR variance over the principal
        // period [−π, π], not the circular variance 1 − I₁/I₀. The Fourier
        // expansion of the pdf gives
        //   var = π²/3 + (4/I₀(κ)) Σ_{k≥1} (−1)^k I_k(κ)/k².
        // frankenscipy.
        if self.kappa <= 0.0 {
            return PI * PI / 3.0; // circular uniform on [−π, π]
        }
        // var = π²/3 + 4 Σ_{k≥1} (−1)^k (I_k/I_0)/k². Stream I_k/I_0 (O(κ), and no
        // 256-term truncation for large κ — see `von_mises_bessel_i0_ratios`).
        let k_max = von_mises_k_max(self.kappa);
        let r = von_mises_bessel_i0_ratios(self.kappa, k_max);
        let mut sum = 0.0_f64;
        for (k, &rk) in r.iter().enumerate().take(k_max + 1).skip(1) {
            let kf = k as f64;
            let sign = if k % 2 == 0 { 1.0 } else { -1.0 };
            let term = sign * rk / (kf * kf);
            sum += term;
            if k > 2 && term.abs() <= 1e-18 * (1.0 + sum.abs()) {
                break;
            }
        }
        PI * PI / 3.0 + 4.0 * sum
    }

    fn entropy(&self) -> f64 {
        // PDF = exp(κ cos(x − loc)) / (2π · I_0(κ)).
        // E[cos(X − loc)] = I_1(κ)/I_0(κ), so
        //   h = ln(2π · I_0(κ)) − κ · I_1(κ)/I_0(κ).
        let i0 = modified_bessel_i(0.0, self.kappa);
        let i1 = modified_bessel_i(1.0, self.kappa);
        (2.0 * PI * i0).ln() - self.kappa * i1 / i0
    }

    fn skewness(&self) -> f64 {
        // VonMises is symmetric about its mean, so every odd central moment
        // vanishes: skewness = 0 (matches scipy.stats.vonmises). frankenscipy.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis of the LINEAR moments on [−π, π] (scipy convention):
        //   μ₄ = π⁴/5 + (8/I₀(κ)) Σ_{k≥1} (−1)^k (π²/k² − 6/k⁴) I_k(κ),
        //   kurt = μ₄/var² − 3. frankenscipy.
        if self.kappa <= 0.0 {
            return -6.0 / 5.0; // excess kurtosis of the uniform on [−π, π]
        }
        // μ₄ = π⁴/5 + 8 Σ_{k≥1} (−1)^k (π²/k² − 6/k⁴)(I_k/I_0). Stream I_k/I_0 (O(κ)).
        let k_max = von_mises_k_max(self.kappa);
        let r = von_mises_bessel_i0_ratios(self.kappa, k_max);
        let mut sum = 0.0_f64;
        for (k, &rk) in r.iter().enumerate().take(k_max + 1).skip(1) {
            let kf = k as f64;
            let sign = if k % 2 == 0 { 1.0 } else { -1.0 };
            let term = sign * (PI * PI / (kf * kf) - 6.0 / (kf * kf * kf * kf)) * rk;
            sum += term;
            if k > 2 && term.abs() <= 1e-18 * (1.0 + sum.abs()) {
                break;
            }
        }
        let mu4 = PI.powi(4) / 5.0 + 8.0 * sum;
        let v = self.var();
        mu4 / (v * v) - 3.0
    }

    fn mode(&self) -> f64 {
        // VonMises pdf ∝ exp(κ cos(x − loc)) peaks at x = loc
        // (the mean direction); frankenscipy-rt24d.
        self.loc
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 2, "VonMises")?;
        let n = data.len() as f64;
        let sin_mean = data.iter().map(|x| x.sin()).sum::<f64>() / n;
        let cos_mean = data.iter().map(|x| x.cos()).sum::<f64>() / n;
        let r = sin_mean.hypot(cos_mean).clamp(0.0, 1.0 - f64::EPSILON);
        let loc = sin_mean.atan2(cos_mean);
        let kappa = if r < 1.0e-12 {
            0.0
        } else if r < 0.53 {
            2.0 * r + r.powi(3) + 5.0 * r.powi(5) / 6.0
        } else if r < 0.85 {
            -0.4 + 1.39 * r + 0.43 / (1.0 - r)
        } else {
            1.0 / (r.powi(3) - 4.0 * r.powi(2) + 3.0 * r)
        };
        if kappa.is_finite() && kappa >= 0.0 {
            Ok(Self { kappa, loc })
        } else {
            Err(FitError::NonConvergent(format!(
                "VonMises circular fit produced invalid kappa: {kappa}"
            )))
        }
    }
}

// ══════════════════════════════════════════════════════════════════════
// Poisson Distribution (discrete, but commonly needed)
// ══════════════════════════════════════════════════════════════════════

/// When `true`, the discrete `ppf_many` methods (e.g. [`Poisson::ppf_many`]) evaluate their query
/// quantiles serially (the ORIG behaviour); default `false` fans the independent per-quantile
/// CDF-table binary searches across cores for large query sets. Byte-identical. A/B knob.
#[doc(hidden)]
pub static DISCRETE_PPF_MANY_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Poisson distribution with rate parameter `mu`.
///
/// Matches `scipy.stats.poisson(mu)`.
/// PMF: P(k) = mu^k * exp(-mu) / k!
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Poisson {
    pub mu: f64,
}

impl Poisson {
    #[must_use]
    pub fn new(mu: f64) -> Self {
        assert!(mu > 0.0, "mu must be positive, got {mu}");
        Self { mu }
    }

    /// Probability mass at many outcomes (full-support / count-data workload),
    /// hoisting `ln(μ)` out of the per-`k` loop (the `lnΓ(k+1)` term varies with `k`
    /// and stays). Byte-identical to mapping `pmf`: same `k·ln_mu − μ − lnΓ(k+1)`
    /// order and the same μ==0 special case.
    #[must_use]
    pub fn pmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let ln_mu = self.mu.ln();
        par_discrete_map(ks, |k| {
            if self.mu == 0.0 {
                return if k == 0 { 1.0 } else { 0.0 };
            }
            let ln_pmf = k as f64 * ln_mu - self.mu - ln_gamma(k as f64 + 1.0);
            ln_pmf.exp()
        })
    }

    /// Log probability mass at many outcomes, hoisting `ln(μ)` out of the
    /// per-`k` loop. Byte-identical to mapping `logpmf`: same `k·ln_mu - μ -
    /// lnΓ(k+1)` operation order and the same μ==0 special case.
    #[must_use]
    pub fn logpmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let ln_mu = self.mu.ln();
        par_discrete_map(ks, |k| {
            if self.mu == 0.0 {
                return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
            }
            k as f64 * ln_mu - self.mu - ln_gamma(k as f64 + 1.0)
        })
    }

    /// Cumulative distribution at many points, computed by a mode-anchored pmf recurrence + prefix
    /// sum (O(max_k) cheap mults) instead of a per-point regularized-gamma evaluation. Anchoring at
    /// the mode (pmf computed once via lnΓ) avoids the pmf(0)=exp(-mu) underflow for large mu.
    /// Matches scipy.stats.poisson.cdf to ~1e-13 (absolute).
    #[must_use]
    pub fn cdf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        if self.mu == 0.0 {
            // All mass at 0: cdf(k) = 1 for every k >= 0.
            return ks.iter().map(|_| 1.0).collect();
        }
        let max_k = *ks.iter().max().unwrap() as usize;
        let mu = self.mu;
        let ln_mu = mu.ln();
        let mode = (mu as usize).min(max_k);
        let mut pmf = vec![0.0f64; max_k + 1];
        pmf[mode] = (mode as f64 * ln_mu - mu - ln_gamma(mode as f64 + 1.0)).exp();
        for j in (mode + 1)..=max_k {
            pmf[j] = pmf[j - 1] * mu / j as f64;
        }
        for j in (0..mode).rev() {
            pmf[j] = pmf[j + 1] * (j + 1) as f64 / mu;
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; max_k + 1];
        for j in 0..=max_k {
            acc += pmf[j];
            cdf[j] = acc.min(1.0);
        }
        ks.iter().map(|&k| cdf[k as usize]).collect()
    }

    /// Survival function P(X>k) at many points via a mode-anchored pmf recurrence + suffix sum
    /// (O(max_k) cheap mults) instead of a per-point regularized gamma. Tail-accurate (direct upper
    /// sum, not 1-cdf). Matches scipy.stats.poisson.sf to ~1e-13 in the bulk/moderate tail; values
    /// below ~1e-15 underflow to 0 (use the scalar `sf` for the deep tail).
    #[must_use]
    pub fn sf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        if self.mu == 0.0 {
            return ks.iter().map(|_| 0.0).collect();
        }
        let mu = self.mu;
        let ln_mu = mu.ln();
        let max_k = *ks.iter().max().unwrap() as usize;
        // Extend past the mode so the upper tail is captured even when max_k < mu.
        let k_hi = max_k.max(mu as usize + (12.0 * mu.sqrt()) as usize + 12);
        let mode = (mu as usize).min(k_hi);
        let mut pmf = vec![0.0f64; k_hi + 1];
        pmf[mode] = (mode as f64 * ln_mu - mu - ln_gamma(mode as f64 + 1.0)).exp();
        for j in (mode + 1)..=k_hi {
            pmf[j] = pmf[j - 1] * mu / j as f64;
        }
        for j in (0..mode).rev() {
            pmf[j] = pmf[j + 1] * (j + 1) as f64 / mu;
        }
        let mut suf = vec![0.0f64; k_hi + 2];
        for k in (0..k_hi).rev() {
            suf[k] = suf[k + 1] + pmf[k + 1];
        }
        ks.iter()
            .map(|&k| suf[(k as usize).min(k_hi)].clamp(0.0, 1.0))
            .collect()
    }

    /// Inverse cdf (quantile) at many probabilities: build the cdf table once via the mode-anchored
    /// recurrence + prefix sum, then binary-search it per quantile — O(K + Q·logK) vs Q independent
    /// regularized-gamma bisections. Matches scipy.stats.poisson.ppf exactly on the table range;
    /// quantiles past the table fall back to the scalar `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        if qs.is_empty() {
            return Vec::new();
        }
        let mu = self.mu;
        if mu == 0.0 {
            return qs
                .iter()
                .map(|&q| {
                    if q <= 0.0 {
                        -1.0
                    } else if q >= 1.0 {
                        f64::INFINITY
                    } else {
                        0.0
                    }
                })
                .collect();
        }
        let ln_mu = mu.ln();
        let k_hi = mu as usize + (15.0 * mu.sqrt()) as usize + 15;
        let mode = (mu as usize).min(k_hi);
        let mut pmf = vec![0.0f64; k_hi + 1];
        pmf[mode] = (mode as f64 * ln_mu - mu - ln_gamma(mode as f64 + 1.0)).exp();
        for j in (mode + 1)..=k_hi {
            pmf[j] = pmf[j - 1] * mu / j as f64;
        }
        for j in (0..mode).rev() {
            pmf[j] = pmf[j + 1] * (j + 1) as f64 / mu;
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; k_hi + 1];
        for j in 0..=k_hi {
            acc += pmf[j];
            cdf[j] = acc.min(1.0);
        }
        // Each quantile is an INDEPENDENT `partition_point` binary search into the shared CDF table
        // (tail overflow falls back to the scalar `ppf`), so fan the query points across cores for
        // large `qs` via the order-preserving `par_continuous_map_min` — BYTE-IDENTICAL (same integer
        // index per quantile, same order). Below 800k use the direct serial map (helper fallback has
        // ~20% overhead at small sizes). `DISCRETE_PPF_MANY_FORCE_SERIAL`.
        let cdf_ref = &cdf;
        let this = self;
        let eval = move |q: f64| -> f64 {
            if q <= 0.0 {
                -1.0
            } else if q >= 1.0 {
                f64::INFINITY
            } else {
                let idx = cdf_ref.partition_point(|&c| c < q);
                if idx <= k_hi { idx as f64 } else { this.ppf(q) }
            }
        };
        if DISCRETE_PPF_MANY_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
            || qs.len() < 800_000
        {
            qs.iter().map(|&q| eval(q)).collect()
        } else {
            par_continuous_map_min(qs, 400_000, eval)
        }
    }

    /// Probability mass function.
    pub fn pmf(&self, k: u64) -> f64 {
        if self.mu == 0.0 {
            return if k == 0 { 1.0 } else { 0.0 };
        }
        let ln_pmf = k as f64 * self.mu.ln() - self.mu - ln_gamma(k as f64 + 1.0);
        ln_pmf.exp()
    }

    /// Cumulative distribution function.
    pub fn cdf(&self, k: u64) -> f64 {
        // Closed form P(X <= k) = Q(k+1, mu) (regularized upper incomplete
        // gamma), matching scipy's pdtr. O(1) vs the old O(k) pmf summation,
        // and accurate for large k where the running sum accumulates error.
        // frankenscipy-7kq9d
        upper_regularized_gamma(k as f64 + 1.0, self.mu)
    }

    /// Mean of the distribution.
    pub fn mean(&self) -> f64 {
        self.mu
    }

    /// Variance of the distribution.
    pub fn var(&self) -> f64 {
        self.mu
    }
}

// ══════════════════════════════════════════════════════════════════════
// Discrete Distribution Trait and Implementations
// ══════════════════════════════════════════════════════════════════════

/// Trait for discrete probability distributions.
pub trait DiscreteDistribution {
    /// Probability mass function.
    fn pmf(&self, k: u64) -> f64;
    /// Cumulative distribution function: P(X <= k).
    fn cdf(&self, k: u64) -> f64 {
        (0..=k).map(|i| self.pmf(i)).sum::<f64>().min(1.0)
    }
    /// Survival function: P(X > k) = 1 - cdf(k).
    fn sf(&self, k: u64) -> f64 {
        1.0 - self.cdf(k)
    }
    /// Log CDF. Default `ln(cdf)` loses precision in the left tail; override
    /// with a log-space closed form (e.g. `log_gammaincc`/`log_betainc`) for
    /// distributions whose CDF underflows.
    fn logcdf(&self, k: u64) -> f64 {
        log_probability(self.cdf(k))
    }
    /// Log survival function. Default `ln(sf)` loses precision in the right
    /// tail; override with a log-space closed form where `sf` underflows.
    fn logsf(&self, k: u64) -> f64 {
        log_probability(self.sf(k))
    }
    /// Log probability mass function. Default `ln(pmf)` loses precision (returns
    /// `-inf`) where the pmf underflows; override with a closed log-space form
    /// (the workhorse of count-data GLM log-likelihoods).
    fn logpmf(&self, k: u64) -> f64 {
        log_probability(self.pmf(k))
    }
    /// Mean of the distribution.
    fn mean(&self) -> f64;
    /// Variance of the distribution.
    fn var(&self) -> f64;
    /// Standard deviation.
    fn std(&self) -> f64 {
        self.var().sqrt()
    }
    /// Entropy in nats. Default returns NaN.
    fn entropy(&self) -> f64 {
        f64::NAN
    }
    /// Fallible entropy accessor. Inherited NaN defaults become a typed
    /// unsupported-operation error for generic callers.
    fn try_entropy(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.entropy(), "entropy", std::any::type_name::<Self>())
    }
    /// Skewness. Default returns NaN.
    fn skewness(&self) -> f64 {
        f64::NAN
    }
    /// Fallible skewness accessor. Inherited NaN defaults become a typed
    /// unsupported-operation error for generic callers.
    fn try_skewness(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.skewness(), "skewness", std::any::type_name::<Self>())
    }
    /// Excess kurtosis. Default returns NaN.
    fn kurtosis(&self) -> f64 {
        f64::NAN
    }
    /// Fallible excess-kurtosis accessor. Inherited NaN defaults become
    /// a typed unsupported-operation error for generic callers.
    fn try_kurtosis(&self) -> Result<f64, StatsError> {
        unsupported_distribution_moment(self.kurtosis(), "kurtosis", std::any::type_name::<Self>())
    }
    /// Mode (most likely value). Default returns NaN.
    fn mode(&self) -> f64 {
        f64::NAN
    }
    /// Percent-point (inverse CDF) function: the smallest integer `k` with
    /// `cdf(k) >= q`. Matches SciPy's discrete `ppf`: `q == 0` returns the
    /// support's lower bound minus one, `q == 1` returns `+inf`, and `q` outside
    /// `[0, 1]` returns `NaN`. Default via monotone-CDF binary search; override
    /// when a closed-form quantile is available.
    fn ppf(&self, q: f64) -> f64 {
        if q.is_nan() || !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return discrete_support_lower(self) as f64 - 1.0;
        }
        if q >= 1.0 {
            return f64::INFINITY;
        }
        let mut hi: u64 = 1;
        while self.cdf(hi) < q {
            if hi > (1u64 << 62) {
                return f64::INFINITY;
            }
            hi = hi.saturating_mul(2);
        }
        let mut lo: u64 = 0;
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            if self.cdf(mid) >= q {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        lo as f64
    }
    /// Inverse survival function: the smallest integer `k` with `sf(k) <= q`.
    /// Matches SciPy's discrete `isf`: `q == 0` returns `+inf`, `q == 1` returns
    /// the support's lower bound minus one, and `q` outside `[0, 1]` returns `NaN`.
    fn isf(&self, q: f64) -> f64 {
        if q.is_nan() || !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q >= 1.0 {
            return discrete_support_lower(self) as f64 - 1.0;
        }
        let mut hi: u64 = 1;
        while self.sf(hi) > q {
            if hi > (1u64 << 62) {
                return f64::INFINITY;
            }
            hi = hi.saturating_mul(2);
        }
        let mut lo: u64 = 0;
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            if self.sf(mid) <= q {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        lo as f64
    }
}

/// Smallest `k` with `cdf(k) > 0`, i.e. the lower bound of a discrete
/// distribution's support (used by the default `ppf`/`isf` boundary handling).
fn discrete_support_lower<D: DiscreteDistribution + ?Sized>(dist: &D) -> u64 {
    let mut a = 0u64;
    while a < (1u64 << 20) && dist.cdf(a) <= 0.0 {
        a += 1;
    }
    a
}

impl DiscreteDistribution for Poisson {
    fn pmf(&self, k: u64) -> f64 {
        Poisson::pmf(self, k)
    }
    fn cdf(&self, k: u64) -> f64 {
        Poisson::cdf(self, k)
    }
    fn sf(&self, k: u64) -> f64 {
        // P(X>k) = P(k+1, mu) (lower regularized gamma); direct so the right
        // tail does not collapse like the default 1-cdf. frankenscipy-r4933
        lower_regularized_gamma(k as f64 + 1.0, self.mu)
    }
    fn logcdf(&self, k: u64) -> f64 {
        // log P(X<=k) = log Q(k+1, mu); finite in the left tail. frankenscipy-r4933
        fsci_special::log_gammaincc_scalar(k as f64 + 1.0, self.mu)
    }
    fn logsf(&self, k: u64) -> f64 {
        // log P(X>k) = log P(k+1, mu); finite in the right tail. frankenscipy-r4933
        fsci_special::log_gammainc_scalar(k as f64 + 1.0, self.mu)
    }
    fn logpmf(&self, k: u64) -> f64 {
        // k·ln(mu) − mu − lnΓ(k+1); finite where pmf underflows (Poisson-GLM
        // log-likelihood term). frankenscipy-7m3xk
        if self.mu == 0.0 {
            return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
        }
        k as f64 * self.mu.ln() - self.mu - ln_gamma(k as f64 + 1.0)
    }
    fn mean(&self) -> f64 {
        Poisson::mean(self)
    }
    fn var(&self) -> f64 {
        Poisson::var(self)
    }
    fn entropy(&self) -> f64 {
        let mu = self.mu;
        // The Sterling-type asymptotic series below is only valid for large μ
        // (it diverges for small μ — ~20% high at μ=0.7, 250% at μ=0.3). For
        // μ < 1000 sum the pmf directly, which matches scipy.stats.poisson to
        // machine precision; keep the (now-accurate) asymptotic beyond that to
        // avoid an ever-growing summation.
        if mu < 1000.0 {
            // Joint pmf/ln-pmf recurrence (pmf(k+1)/pmf(k) = μ/(k+1)) anchored at the
            // mode ⌊μ⌋ — one ln_gamma-based pmf at the mode + O(kmax) with a single ln
            // per term, instead of a fresh ln_gamma pmf per term. Same [0, kmax] window
            // and `pmf > 0` skip, so it reproduces the direct sum (≤7.3e-13 vs
            // scipy.stats.poisson.entropy).
            let kmax = (mu + 12.0 * mu.sqrt() + 12.0).ceil() as u64;
            let m = (mu.floor() as u64).min(kmax);
            let lp_m = self.logpmf(m);
            let pm = lp_m.exp();
            let mut h = if pm > 0.0 { -pm * lp_m } else { 0.0 };
            // Downward from the mode to 0.
            let mut pk = pm;
            let mut lpk = lp_m;
            let mut i = m;
            while i > 0 {
                let r = i as f64 / mu; // pmf(i−1)/pmf(i)
                pk *= r;
                lpk += r.ln();
                i -= 1;
                if pk > 0.0 {
                    h -= pk * lpk;
                }
            }
            // Upward from the mode to kmax.
            pk = pm;
            lpk = lp_m;
            i = m;
            while i < kmax {
                let r = mu / (i as f64 + 1.0); // pmf(i+1)/pmf(i)
                pk *= r;
                lpk += r.ln();
                i += 1;
                if pk > 0.0 {
                    h -= pk * lpk;
                }
            }
            h
        } else {
            0.5 * (2.0 * PI * std::f64::consts::E * mu).ln()
                - 1.0 / (12.0 * mu)
                - 1.0 / (24.0 * mu * mu)
                - 19.0 / (360.0 * mu * mu * mu)
        }
    }
    fn skewness(&self) -> f64 {
        1.0 / self.mu.sqrt()
    }
    fn kurtosis(&self) -> f64 {
        1.0 / self.mu
    }
    fn mode(&self) -> f64 {
        self.mu.floor()
    }
}

// ══════════════════════════════════════════════════════════════════════
// Skellam Distribution
// ══════════════════════════════════════════════════════════════════════

/// Skellam distribution: difference of two independent Poisson random variables.
///
/// Matches `scipy.stats.skellam(mu1, mu2)`.
/// PMF: P(k) = exp(-(μ1+μ2)) * (μ1/μ2)^(k/2) * I_|k|(2*sqrt(μ1*μ2))
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Skellam {
    pub mu1: f64,
    pub mu2: f64,
}

impl Skellam {
    #[must_use]
    pub fn new(mu1: f64, mu2: f64) -> Self {
        assert!(
            mu1 >= 0.0 && mu1.is_finite(),
            "mu1 must be non-negative and finite"
        );
        assert!(
            mu2 >= 0.0 && mu2.is_finite(),
            "mu2 must be non-negative and finite"
        );
        Self { mu1, mu2 }
    }

    pub fn pmf_signed(&self, k: i64) -> f64 {
        if self.mu1 == 0.0 && self.mu2 == 0.0 {
            return if k == 0 { 1.0 } else { 0.0 };
        }
        let exp_term = (-(self.mu1 + self.mu2)).exp();
        let ratio = if self.mu2 == 0.0 {
            if k >= 0 { f64::INFINITY } else { 0.0 }
        } else if self.mu1 == 0.0 {
            if k <= 0 { f64::INFINITY } else { 0.0 }
        } else {
            (self.mu1 / self.mu2).powf(k as f64 / 2.0)
        };
        if self.mu1 == 0.0 {
            if k > 0 {
                return 0.0;
            }
            return (-self.mu2).exp() * self.mu2.powi((-k) as i32)
                / ln_gamma((-k + 1) as f64).exp();
        }
        if self.mu2 == 0.0 {
            if k < 0 {
                return 0.0;
            }
            return (-self.mu1).exp() * self.mu1.powi(k as i32) / ln_gamma((k + 1) as f64).exp();
        }
        let bessel_arg = 2.0 * (self.mu1 * self.mu2).sqrt();
        let bessel_val = fsci_special::bessel::ive_scalar(k.unsigned_abs() as f64, bessel_arg)
            * bessel_arg.exp();
        exp_term * ratio * bessel_val
    }
}

impl DiscreteDistribution for Skellam {
    // Skellam has full-integer (signed) support; the u64 `DiscreteDistribution`
    // ppf/isf cannot represent negative quantiles, so they are unsupported here
    // (the default would silently clamp to 0). Use the signed pmf/cdf API instead.
    fn ppf(&self, _q: f64) -> f64 {
        f64::NAN
    }
    fn isf(&self, _q: f64) -> f64 {
        f64::NAN
    }
    fn pmf(&self, k: u64) -> f64 {
        self.pmf_signed(k as i64)
    }
    fn logpmf(&self, k: u64) -> f64 {
        // −(μ1+μ2) + (k/2)·ln(μ1/μ2) + ln I_k(2√(μ1μ2)), with ln I_k=log_ive(k,z)+z
        // — finite for large μ1·μ2 where the pmf's I_k overflows to NaN.
        // frankenscipy-7m3xk
        let kf = k as f64;
        let (mu1, mu2) = (self.mu1, self.mu2);
        if mu1 == 0.0 && mu2 == 0.0 {
            return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
        }
        if mu1 == 0.0 {
            return if k == 0 { -mu2 } else { f64::NEG_INFINITY };
        }
        if mu2 == 0.0 {
            // Poisson(μ1) on k ≥ 0.
            return -mu1 + kf * mu1.ln() - ln_gamma(kf + 1.0);
        }
        let z = 2.0 * (mu1 * mu2).sqrt();
        -(mu1 + mu2) + 0.5 * kf * (mu1 / mu2).ln() + fsci_special::log_ive_scalar(kf, z) + z
    }

    fn cdf(&self, k: u64) -> f64 {
        // scipy.stats.skellam.cdf via the noncentral chi-square (ncx2) identity:
        // for k ≥ 0, P(X ≤ k) = 1 − ncx2.cdf(2·μ1; df = 2(k+1), nc = 2·μ2)
        //                     = 1 − chndtr(2·μ1, 2(k+1), 2·μ2).
        // This is O(√nc) cheap regularized-gamma terms (chndtr's Poisson mixture)
        // instead of the prior O(σ) per-point Bessel-`ive` window sum, and it
        // reproduces P(X ≤ k) over Skellam's FULL integer support — the negative
        // tail is folded into the identity, no manual window needed. Verified vs
        // scipy to ≤4.4e-16 across μ∈[0,1000], k∈[0,50]. Exact at the degenerate
        // edges: μ1=0 ⇒ chndtr(0,·,·)=0 ⇒ cdf=1; μ2=0 ⇒ Poisson(μ1) cdf.
        let kf = k.min(i64::MAX as u64) as f64;
        (1.0 - fsci_special::gamma::chndtr(2.0 * self.mu1, 2.0 * (kf + 1.0), 2.0 * self.mu2))
            .clamp(0.0, 1.0)
    }

    fn sf(&self, k: u64) -> f64 {
        // sf(k) = 1 − cdf(k) = chndtr(2·μ1, 2(k+1), 2·μ2) directly — the small
        // upper-tail probability WITHOUT a 1−cdf cancellation, matching scipy's
        // ncx2-based skellam.sf to ≤4.7e-16. O(√nc) gamma terms vs the prior
        // O(σ) Bessel-`ive` window sum.
        let kf = k.min(i64::MAX as u64) as f64;
        fsci_special::gamma::chndtr(2.0 * self.mu1, 2.0 * (kf + 1.0), 2.0 * self.mu2)
            .clamp(0.0, 1.0)
    }

    fn mean(&self) -> f64 {
        self.mu1 - self.mu2
    }

    fn var(&self) -> f64 {
        self.mu1 + self.mu2
    }

    fn skewness(&self) -> f64 {
        let var = self.var();
        if var == 0.0 {
            return 0.0;
        }
        (self.mu1 - self.mu2) / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let var = self.var();
        if var == 0.0 {
            return f64::NAN;
        }
        1.0 / var
    }

    fn mode(&self) -> f64 {
        (self.mu1 - self.mu2).round()
    }

    fn entropy(&self) -> f64 {
        // Skellam has no closed-form entropy; scipy evaluates it numerically
        // over the (bi-infinite) integer support. Sum −Σ p·ln(p) across the same
        // window the cdf uses (mean ± 12σ ± 40), which captures the support to
        // machine precision. frankenscipy-3zent
        let mean = self.mu1 - self.mu2;
        let std = (self.mu1 + self.mu2).sqrt();
        let lo = (mean - 12.0 * std - 40.0).floor() as i64;
        let hi = (mean + 12.0 * std + 40.0).ceil() as i64;
        let mut acc = 0.0_f64;
        for j in lo..=hi {
            let p = self.pmf_signed(j);
            if p > 0.0 {
                acc -= p * p.ln();
            }
        }
        acc
    }
}

/// Binomial distribution: number of successes in n independent Bernoulli trials.
///
/// Matches `scipy.stats.binom(n, p)`.
/// PMF: P(k) = C(n,k) * p^k * (1-p)^(n-k)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Binomial {
    pub n: u64,
    pub p: f64,
}

impl Binomial {
    #[must_use]
    pub fn new(n: u64, p: f64) -> Self {
        assert!((0.0..=1.0).contains(&p), "p must be in [0, 1], got {p}");
        Self { n, p }
    }

    /// Probability mass at many outcomes (the realistic full-support / count-data
    /// workload). Hoists the parameter-only terms `lnΓ(n+1)`, `ln p`, and `ln(1−p)`
    /// out of the per-`k` loop (the `lnΓ(k+1)` and `lnΓ(n−k+1)` terms vary with `k`
    /// and stay). Byte-identical to mapping `pmf`: same `ln_comb`/`ln_pmf` operation
    /// order and the same p∈{0,1} and k>n special cases.
    #[must_use]
    pub fn pmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let lg_n1 = ln_gamma(self.n as f64 + 1.0);
        let ln_p = self.p.ln();
        let ln_1mp = (1.0 - self.p).ln();
        par_discrete_map(ks, |k| {
            if k > self.n {
                return 0.0;
            }
            if self.p == 0.0 {
                return if k == 0 { 1.0 } else { 0.0 };
            }
            if self.p == 1.0 {
                return if k == self.n { 1.0 } else { 0.0 };
            }
            let ln_comb = lg_n1 - ln_gamma(k as f64 + 1.0) - ln_gamma((self.n - k) as f64 + 1.0);
            let ln_pmf = ln_comb + k as f64 * ln_p + (self.n - k) as f64 * ln_1mp;
            ln_pmf.exp()
        })
    }

    /// Cumulative distribution at many points via a mode-anchored pmf recurrence + prefix sum
    /// (O(max_k) cheap mults) instead of a per-point regularized incomplete beta. Anchoring at the
    /// mode (pmf via lnΓ once) avoids underflow at the tails. Matches scipy.stats.binom.cdf ~1e-12.
    #[must_use]
    pub fn cdf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p == 0.0 {
            return ks.iter().map(|_| 1.0).collect();
        }
        if p == 1.0 {
            return ks.iter().map(|&k| if k >= n { 1.0 } else { 0.0 }).collect();
        }
        let max_k = *ks.iter().max().unwrap();
        let table_hi = max_k.min(n) as usize;
        let nf = n as f64;
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let ratio = p / (1.0 - p);
        let mode = (((nf + 1.0) * p) as usize).min(table_hi);
        let mut pmf = vec![0.0f64; table_hi + 1];
        pmf[mode] =
            (ln_gamma(nf + 1.0) - ln_gamma(mode as f64 + 1.0) - ln_gamma(nf - mode as f64 + 1.0)
                + mode as f64 * ln_p
                + (nf - mode as f64) * ln_1mp)
                .exp();
        for k in (mode + 1)..=table_hi {
            pmf[k] = pmf[k - 1] * ((nf - k as f64 + 1.0) / k as f64) * ratio;
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * ((k as f64 + 1.0) / (nf - k as f64)) / ratio;
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; table_hi + 1];
        for k in 0..=table_hi {
            acc += pmf[k];
            cdf[k] = acc.min(1.0);
        }
        ks.iter()
            .map(|&k| if k >= n { 1.0 } else { cdf[k as usize] })
            .collect()
    }

    /// Survival function P(X>k) at many points via a mode-anchored pmf recurrence + suffix sum.
    /// Tail-accurate (direct upper sum). Matches scipy.stats.binom.sf to ~1e-12 in the bulk; deep
    /// tail (<~1e-15) underflows to 0 (use the scalar `sf`).
    #[must_use]
    pub fn sf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p == 0.0 {
            return ks.iter().map(|_| 0.0).collect();
        }
        if p == 1.0 {
            return ks.iter().map(|&k| if k < n { 1.0 } else { 0.0 }).collect();
        }
        let nf = n as f64;
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let ratio = p / (1.0 - p);
        let k_hi = n as usize;
        let mode = (((nf + 1.0) * p) as usize).min(k_hi);
        let mut pmf = vec![0.0f64; k_hi + 1];
        pmf[mode] =
            (ln_gamma(nf + 1.0) - ln_gamma(mode as f64 + 1.0) - ln_gamma(nf - mode as f64 + 1.0)
                + mode as f64 * ln_p
                + (nf - mode as f64) * ln_1mp)
                .exp();
        for k in (mode + 1)..=k_hi {
            pmf[k] = pmf[k - 1] * ((nf - k as f64 + 1.0) / k as f64) * ratio;
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * ((k as f64 + 1.0) / (nf - k as f64)) / ratio;
        }
        let mut suf = vec![0.0f64; k_hi + 2];
        for k in (0..k_hi).rev() {
            suf[k] = suf[k + 1] + pmf[k + 1];
        }
        ks.iter()
            .map(|&k| {
                if k as usize >= k_hi {
                    0.0
                } else {
                    suf[k as usize].clamp(0.0, 1.0)
                }
            })
            .collect()
    }

    /// Inverse cdf at many probabilities: build the cdf table once (mode-anchored recurrence + prefix
    /// sum over [0,n]) then binary-search per quantile. A guarded scalar-cdf check disambiguates the
    /// rare quantile that lands within ~1e-11 of a cdf step (where the ~1e-13 cumsum error could
    /// mis-rank), so the result equals the scalar `ppf`. O(n + Q·logn).
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        if qs.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p <= 0.0 {
            return qs
                .iter()
                .map(|&q| if q <= 0.0 { -1.0 } else { 0.0 })
                .collect();
        }
        if p >= 1.0 {
            return qs
                .iter()
                .map(|&q| if q <= 0.0 { -1.0 } else { n as f64 })
                .collect();
        }
        let nf = n as f64;
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let ratio = p / (1.0 - p);
        let nn = n as usize;
        let mode = (((nf + 1.0) * p) as usize).min(nn);
        let mut pmf = vec![0.0f64; nn + 1];
        pmf[mode] =
            (ln_gamma(nf + 1.0) - ln_gamma(mode as f64 + 1.0) - ln_gamma(nf - mode as f64 + 1.0)
                + mode as f64 * ln_p
                + (nf - mode as f64) * ln_1mp)
                .exp();
        for k in (mode + 1)..=nn {
            pmf[k] = pmf[k - 1] * ((nf - k as f64 + 1.0) / k as f64) * ratio;
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * ((k as f64 + 1.0) / (nf - k as f64)) / ratio;
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; nn + 1];
        for k in 0..=nn {
            acc += pmf[k];
            cdf[k] = acc.min(1.0);
        }
        // Independent per-quantile `partition_point` + boundary refinement into the shared CDF table,
        // so fan across cores for large `qs` via the order-preserving `par_continuous_map_min` —
        // BYTE-IDENTICAL (same index per quantile, same order). Below 800k use the direct serial map.
        let cdf_ref = &cdf;
        let this = self;
        let eval = move |q: f64| -> f64 {
            if q <= 0.0 {
                return -1.0;
            }
            if q >= 1.0 {
                return nf;
            }
            let idx = cdf_ref.partition_point(|&c| c < q).min(nn);
            let mut k = idx;
            let near = (k > 0 && q - cdf_ref[k - 1] < 1e-11) || (cdf_ref[k] - q < 1e-11);
            if near {
                while k > 0 && this.cdf((k - 1) as u64) >= q {
                    k -= 1;
                }
                while (k as u64) < n && this.cdf(k as u64) < q {
                    k += 1;
                }
            }
            k as f64
        };
        if DISCRETE_PPF_MANY_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
            || qs.len() < 800_000
        {
            qs.iter().map(|&q| eval(q)).collect()
        } else {
            par_continuous_map_min(qs, 400_000, eval)
        }
    }
}

impl DiscreteDistribution for Binomial {
    fn pmf(&self, k: u64) -> f64 {
        if k > self.n {
            return 0.0;
        }
        if self.p == 0.0 {
            return if k == 0 { 1.0 } else { 0.0 };
        }
        if self.p == 1.0 {
            return if k == self.n { 1.0 } else { 0.0 };
        }
        let ln_comb = ln_gamma(self.n as f64 + 1.0)
            - ln_gamma(k as f64 + 1.0)
            - ln_gamma((self.n - k) as f64 + 1.0);
        let ln_pmf = ln_comb + k as f64 * self.p.ln() + (self.n - k) as f64 * (1.0 - self.p).ln();
        ln_pmf.exp()
    }

    fn cdf(&self, k: u64) -> f64 {
        // Closed form P(X<=k) = I_{1-p}(n-k, k+1), matching scipy's bdtr. O(1)
        // vs the old O(k) pmf summation. frankenscipy-7kq9d
        if k >= self.n {
            return 1.0;
        }
        regularized_incomplete_beta((self.n - k) as f64, k as f64 + 1.0, 1.0 - self.p)
    }
    fn logpmf(&self, k: u64) -> f64 {
        // ln C(n,k) + k·ln(p) + (n−k)·ln(1−p); finite where pmf underflows
        // (binomial/logistic-GLM log-likelihood term). frankenscipy-7m3xk
        if k > self.n {
            return f64::NEG_INFINITY;
        }
        if self.p == 0.0 {
            return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
        }
        if self.p == 1.0 {
            return if k == self.n { 0.0 } else { f64::NEG_INFINITY };
        }
        let ln_comb = ln_gamma(self.n as f64 + 1.0)
            - ln_gamma(k as f64 + 1.0)
            - ln_gamma((self.n - k) as f64 + 1.0);
        ln_comb + k as f64 * self.p.ln() + (self.n - k) as f64 * (1.0 - self.p).ln()
    }
    fn sf(&self, k: u64) -> f64 {
        // P(X>k) = I_p(k+1, n-k); direct so the right tail does not collapse
        // like the default 1-cdf. frankenscipy-r4933
        if k >= self.n {
            return 0.0;
        }
        regularized_incomplete_beta(k as f64 + 1.0, (self.n - k) as f64, self.p)
    }
    fn logcdf(&self, k: u64) -> f64 {
        // log P(X<=k) = log I_{1-p}(n-k, k+1); finite in the left tail. frankenscipy-r4933
        if k >= self.n {
            return 0.0;
        }
        fsci_special::log_betainc_scalar((self.n - k) as f64, k as f64 + 1.0, 1.0 - self.p)
    }
    fn logsf(&self, k: u64) -> f64 {
        // log P(X>k) = log I_p(k+1, n-k); finite in the right tail. frankenscipy-r4933
        if k >= self.n {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_betainc_scalar(k as f64 + 1.0, (self.n - k) as f64, self.p)
    }

    fn mean(&self) -> f64 {
        self.n as f64 * self.p
    }

    fn var(&self) -> f64 {
        self.n as f64 * self.p * (1.0 - self.p)
    }

    fn skewness(&self) -> f64 {
        let q = 1.0 - self.p;
        (1.0 - 2.0 * self.p) / (self.n as f64 * self.p * q).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        let q = 1.0 - self.p;
        (1.0 - 6.0 * self.p * q) / (self.n as f64 * self.p * q)
    }

    fn mode(&self) -> f64 {
        ((self.n as f64 + 1.0) * self.p).floor()
    }

    fn entropy(&self) -> f64 {
        // Binomial entropy −∑ pmf·ln pmf over [0,n]. The fresh-pmf loop paid ~3
        // ln_gamma PER term; instead track pmf and ln(pmf) jointly via the pmf-ratio
        // recurrence (pmf(k+1)/pmf(k) = (n−k)/(k+1) · p/(1−p)), anchored at the mode
        // so the pmf never underflows. One ln_gamma-based pmf at the mode + O(n)
        // (one ln per term). Verified vs scipy.stats.binom.entropy to ≤1.2e-11.
        if self.p == 0.0 || self.p == 1.0 {
            return 0.0;
        }
        let n = self.n;
        let nf = n as f64;
        let p = self.p;
        let odds = p / (1.0 - p);
        let m = (((nf + 1.0) * p).floor() as u64).min(n);
        let lp_m = self.logpmf(m);
        let pm = lp_m.exp();
        let mut h = if pm > 0.0 { -pm * lp_m } else { 0.0 };
        // Downward from the mode to 0.
        let mut pk = pm;
        let mut lpk = lp_m;
        let mut i = m;
        while i > 0 {
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i/(n−i+1) · (1−p)/p
            let r = fi / ((nf - fi + 1.0) * odds);
            pk *= r;
            lpk += r.ln();
            i -= 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        // Upward from the mode to n.
        pk = pm;
        lpk = lp_m;
        i = m;
        while i < n {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (n−i)/(i+1) · p/(1−p)
            let r = (nf - fi) / (fi + 1.0) * odds;
            pk *= r;
            lpk += r.ln();
            i += 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        h
    }
}

/// Beta-binomial distribution.
///
/// Matches `scipy.stats.betabinom(n, a, b)`.
/// PMF: P(k) = C(n,k) * B(k+a, n-k+b) / B(a, b)
/// where B is the beta function.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct BetaBinomial {
    pub n: u64,
    pub a: f64,
    pub b: f64,
}

impl BetaBinomial {
    #[must_use]
    pub fn new(n: u64, a: f64, b: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(b > 0.0, "b must be positive, got {b}");
        Self { n, a, b }
    }

    /// Log-pmf at many outcomes, hoisting the FIVE parameter-only lgamma terms
    /// (`lnΓ(n+1)`, `lnΓ(n+a+b)`, and the whole `ln_beta_den = lnΓ(a)+lnΓ(b)−lnΓ(a+b)`)
    /// out of the per-`k` loop. Byte-identical to mapping `logpmf` (same ln_comb /
    /// ln_beta_num operation order; k>n → −∞).
    #[must_use]
    pub fn logpmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let lg_n1 = ln_gamma(self.n as f64 + 1.0);
        let lg_nab = ln_gamma(self.n as f64 + self.a + self.b);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        par_discrete_map(ks, |k| {
            if k > self.n {
                return f64::NEG_INFINITY;
            }
            let kf = k as f64;
            let ln_comb = lg_n1 - ln_gamma(kf + 1.0) - ln_gamma((self.n - k) as f64 + 1.0);
            let ln_beta_num =
                ln_gamma(kf + self.a) + ln_gamma((self.n - k) as f64 + self.b) - lg_nab;
            ln_comb + ln_beta_num - ln_beta_den
        })
    }

    /// Pmf at many outcomes; hoists the same five lgamma terms as
    /// [`logpmf_many`](Self::logpmf_many). Byte-identical to mapping `pmf`.
    #[must_use]
    pub fn pmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let lg_n1 = ln_gamma(self.n as f64 + 1.0);
        let lg_nab = ln_gamma(self.n as f64 + self.a + self.b);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        par_discrete_map(ks, |k| {
            if k > self.n {
                return 0.0;
            }
            let kf = k as f64;
            let ln_comb = lg_n1 - ln_gamma(kf + 1.0) - ln_gamma((self.n - k) as f64 + 1.0);
            let ln_beta_num =
                ln_gamma(kf + self.a) + ln_gamma((self.n - k) as f64 + self.b) - lg_nab;
            (ln_comb + ln_beta_num - ln_beta_den).exp()
        })
    }
}

impl DiscreteDistribution for BetaBinomial {
    fn pmf(&self, k: u64) -> f64 {
        if k > self.n {
            return 0.0;
        }
        let ln_comb = ln_gamma(self.n as f64 + 1.0)
            - ln_gamma(k as f64 + 1.0)
            - ln_gamma((self.n - k) as f64 + 1.0);
        let ln_beta_num = ln_gamma(k as f64 + self.a) + ln_gamma((self.n - k) as f64 + self.b)
            - ln_gamma(self.n as f64 + self.a + self.b);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        (ln_comb + ln_beta_num - ln_beta_den).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln C(n,k) + ln B(k+a, n−k+b) − ln B(a,b); finite where pmf underflows
        // (the pmf already forms this then exp's it). frankenscipy-7m3xk
        if k > self.n {
            return f64::NEG_INFINITY;
        }
        let ln_comb = ln_gamma(self.n as f64 + 1.0)
            - ln_gamma(k as f64 + 1.0)
            - ln_gamma((self.n - k) as f64 + 1.0);
        let ln_beta_num = ln_gamma(k as f64 + self.a) + ln_gamma((self.n - k) as f64 + self.b)
            - ln_gamma(self.n as f64 + self.a + self.b);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        ln_comb + ln_beta_num - ln_beta_den
    }

    fn cdf(&self, k: u64) -> f64 {
        // Default DiscreteDistribution::cdf sums pmf(0..=k) and each BetaBinomial
        // pmf costs ~6 ln_gamma calls — O(k) lgamma. Instead walk the pmf RATIO
        // recurrence (each consecutive pmf is one multiply):
        //   pmf(i+1)/pmf(i) = (n−i)(i+a) / ((i+1)(n−i−1+b)).
        // Anchor at the mode (the largest pmf, ≥ 1/(n+1), so never underflows) and
        // sweep outward, summing the [0, k] window. One ln_gamma-based pmf at the
        // mode + O(n) multiply/adds. Verified vs scipy.stats.betabinom.cdf to
        // ≤6.7e-13 rel incl. deep tails to 1e-46.
        let n = self.n;
        if k >= n {
            return 1.0;
        }
        let nf = n as f64;
        let (a, b) = (self.a, self.b);
        let m = (self.mode() as u64).min(n);
        let pm = self.logpmf(m).exp();
        let mut total = 0.0_f64;
        // Downward from the mode to 0, counting indices ≤ k.
        let mut pk = pm;
        let mut i = m;
        loop {
            if i <= k {
                total += pk;
            }
            if i == 0 {
                break;
            }
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(n−i+b) / ((n−i+1)(i−1+a))
            pk *= fi * (nf - fi + b) / ((nf - fi + 1.0) * (fi - 1.0 + a));
            i -= 1;
        }
        // Upward from the mode to k (only when k > mode).
        pk = pm;
        i = m;
        while i < k {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (n−i)(i+a) / ((i+1)(n−i−1+b))
            pk *= (nf - fi) * (fi + a) / ((fi + 1.0) * (nf - fi - 1.0 + b));
            i += 1;
            total += pk;
        }
        total.clamp(0.0, 1.0)
    }

    fn mean(&self) -> f64 {
        self.n as f64 * self.a / (self.a + self.b)
    }

    fn var(&self) -> f64 {
        let n = self.n as f64;
        let ab = self.a + self.b;
        n * self.a * self.b * (ab + n) / (ab * ab * (ab + 1.0))
    }

    fn skewness(&self) -> f64 {
        let n = self.n as f64;
        let a = self.a;
        let b = self.b;
        let ab = a + b;
        (ab + 2.0 * n) * (b - a) / (ab + 2.0) * ((1.0 + ab) / (n * a * b * (ab + n))).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        // Excess (Fisher) kurtosis. The hand-rolled closed form was wrong
        // (betabinom(20,2,3) gave -0.824 vs scipy -0.657); compute the 4th
        // central moment exactly from the finite (n+1)-term pmf instead, which
        // matches scipy.stats.betabinom to machine precision. m4 via the pmf-ratio
        // recurrence (mode-anchored: one ln_gamma pmf + O(n) mults) instead of a
        // fresh-lgamma pmf per term; var() stays the closed form. Reproduces the
        // fresh-pmf m4 to ≤2e-11 (loop reassociation only).
        let mu = self.mean();
        let var = self.var();
        let n = self.n;
        let nf = n as f64;
        let (a, b) = (self.a, self.b);
        let m = (self.mode() as u64).min(n);
        let pm = self.logpmf(m).exp();
        let d0 = m as f64 - mu;
        let mut m4 = pm * d0 * d0 * d0 * d0;
        // Downward from the mode to 0.
        let mut pk = pm;
        let mut i = m;
        while i > 0 {
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(n−i+b) / ((n−i+1)(i−1+a))
            pk *= fi * (nf - fi + b) / ((nf - fi + 1.0) * (fi - 1.0 + a));
            i -= 1;
            let d = i as f64 - mu;
            m4 += pk * d * d * d * d;
        }
        // Upward from the mode to n.
        pk = pm;
        i = m;
        while i < n {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (n−i)(i+a) / ((i+1)(n−i−1+b))
            pk *= (nf - fi) * (fi + a) / ((fi + 1.0) * (nf - fi - 1.0 + b));
            i += 1;
            let d = i as f64 - mu;
            m4 += pk * d * d * d * d;
        }
        m4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        if self.a > 1.0 && self.b > 1.0 {
            ((self.n as f64 + self.a - 1.0) * (self.a - 1.0) / (self.a + self.b - 2.0)).floor()
        } else if self.a <= 1.0 && self.b > 1.0 {
            0.0
        } else if self.a > 1.0 && self.b <= 1.0 {
            self.n as f64
        } else {
            0.0
        }
    }

    fn entropy(&self) -> f64 {
        // H = −Σ pmf·ln(pmf) over [0,n]. The fresh-pmf loop paid ~6 ln_gamma PER
        // term; instead track pmf and ln(pmf) jointly via the pmf-ratio recurrence
        // (pmf(i+1)/pmf(i) = (n−i)(i+a)/((i+1)(n−i−1+b))), anchored at the mode so
        // the pmf never underflows. One ln_gamma-based pmf at the mode + O(n) (one
        // ln per term). Verified vs scipy.stats.betabinom.entropy to ≤5.7e-13.
        let n = self.n;
        let nf = n as f64;
        let (a, b) = (self.a, self.b);
        let m = (self.mode() as u64).min(n);
        let lp_m = self.logpmf(m);
        let pm = lp_m.exp();
        let mut h = if pm > 0.0 { -pm * lp_m } else { 0.0 };
        // Downward from the mode to 0.
        let mut pk = pm;
        let mut lpk = lp_m;
        let mut i = m;
        while i > 0 {
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(n−i+b) / ((n−i+1)(i−1+a))
            let r = fi * (nf - fi + b) / ((nf - fi + 1.0) * (fi - 1.0 + a));
            pk *= r;
            lpk += r.ln();
            i -= 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        // Upward from the mode to n.
        pk = pm;
        lpk = lp_m;
        i = m;
        while i < n {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (n−i)(i+a) / ((i+1)(n−i−1+b))
            let r = (nf - fi) * (fi + a) / ((fi + 1.0) * (nf - fi - 1.0 + b));
            pk *= r;
            lpk += r.ln();
            i += 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        h
    }
}

/// Beta-negative-binomial distribution.
///
/// Matches `scipy.stats.betanbinom(n, a, b)`.
/// PMF: P(k) = C(n+k-1,k) * B(a+n, b+k) / B(a, b)
/// where B is the beta function.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct BetaNegativeBinomial {
    pub n: u64,
    pub a: f64,
    pub b: f64,
}

/// Same-binary A/B toggle for [`BetaNegativeBinomial::cdf_many`]. When `true`,
/// the batch API maps the legacy scalar `cdf(k)` per query; when `false`, it
/// builds one prefix table up to `max(k)` and indexes it.
pub static BETANBINOM_CDF_MANY_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

impl BetaNegativeBinomial {
    #[must_use]
    pub fn new(n: u64, a: f64, b: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        assert!(b > 0.0, "b must be positive, got {b}");
        Self { n, a, b }
    }

    fn entropy_tail_estimate(a: f64, k: u64, p: f64, logp: f64) -> f64 {
        let x = k as f64;
        p * x * ((-logp) / a + (a + 1.0) / (a * a))
    }

    /// Cumulative distribution at many integer outcomes.
    ///
    /// The scalar `cdf(k)` walks the pmf recurrence from 0 to `k` for every
    /// query. A batch of monotone or repeated queries can instead materialize
    /// the recurrence prefix once, then answer each query by table lookup. Each
    /// table entry is accumulated in the identical order as the scalar path, so
    /// `cdf_many(&ks)[i] == cdf(ks[i])` bit-for-bit while the budget gate holds.
    #[must_use]
    pub fn cdf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        if BETANBINOM_CDF_MANY_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
            return ks.iter().map(|&k| self.cdf(k)).collect();
        }
        let max_k = *ks.iter().max().expect("non-empty ks");
        const MAX_PREFIX_K: u64 = 1_000_000;
        if max_k > MAX_PREFIX_K {
            return ks.iter().map(|&k| self.cdf(k)).collect();
        }

        let nf = self.n as f64;
        let (a, b) = (self.a, self.b);
        let mut table = Vec::with_capacity(max_k as usize + 1);
        let mut p = self.pmf(0);
        let mut total = p;
        table.push(total.min(1.0));
        for i in 0..max_k {
            let fi = i as f64;
            p *= (nf + fi) * (b + fi) / ((fi + 1.0) * (a + nf + b + fi));
            total += p;
            table.push(total.min(1.0));
        }

        ks.iter().map(|&k| table[k as usize]).collect()
    }
}

impl DiscreteDistribution for BetaNegativeBinomial {
    fn pmf(&self, k: u64) -> f64 {
        let n = self.n as f64;
        let kf = k as f64;
        let ln_comb = ln_gamma(n + kf) - ln_gamma(kf + 1.0) - ln_gamma(n);
        let ln_beta_num =
            ln_gamma(self.a + n) + ln_gamma(self.b + kf) - ln_gamma(self.a + n + self.b + kf);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        (ln_comb + ln_beta_num - ln_beta_den).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln C(n+k-1,k) + ln B(a+n, b+k) − ln B(a,b); finite where pmf underflows
        // (pmf forms this then exp's it). frankenscipy-7m3xk
        let n = self.n as f64;
        let kf = k as f64;
        let ln_comb = ln_gamma(n + kf) - ln_gamma(kf + 1.0) - ln_gamma(n);
        let ln_beta_num =
            ln_gamma(self.a + n) + ln_gamma(self.b + kf) - ln_gamma(self.a + n + self.b + kf);
        let ln_beta_den = ln_gamma(self.a) + ln_gamma(self.b) - ln_gamma(self.a + self.b);
        ln_comb + ln_beta_num - ln_beta_den
    }

    fn cdf(&self, k: u64) -> f64 {
        // Default DiscreteDistribution::cdf sums pmf(0..=k) and each pmf costs ~6
        // ln_gamma. The pmf has a closed ratio and the mode is 0, so pmf(0) is the
        // largest term (never underflows): pmf(i+1)/pmf(i) = (n+i)(b+i)/((i+1)(a+n+b+i)).
        // One ln_gamma-based pmf(0) + O(k) multiply/adds. Verified vs
        // scipy.stats.betanbinom.cdf to ≤2.7e-15.
        let nf = self.n as f64;
        let (a, b) = (self.a, self.b);
        let mut p = self.pmf(0); // = B(a+n, b)/B(a,b), the mode
        let mut total = p;
        let mut i = 0u64;
        while i < k {
            let fi = i as f64;
            p *= (nf + fi) * (b + fi) / ((fi + 1.0) * (a + nf + b + fi));
            i += 1;
            total += p;
        }
        total.min(1.0)
    }

    // Moments follow scipy.stats.betanbinom._stats (Wolfram BetaNegativeBinomial
    // [a,b,n]) exactly; the previous fsci closed forms used a broken
    // parametrization (mean(10,3,4) gave 4.44 vs the true 20). They diverge for
    // small a (heavy tail), where scipy returns +inf. frankenscipy.
    fn mean(&self) -> f64 {
        let (n, a, b) = (self.n as f64, self.a, self.b);
        if a <= 1.0 {
            return f64::INFINITY;
        }
        n * b / (a - 1.0)
    }

    fn var(&self) -> f64 {
        let (n, a, b) = (self.n as f64, self.a, self.b);
        if a <= 2.0 {
            return f64::INFINITY;
        }
        n * b * (n + a - 1.0) * (a + b - 1.0) / ((a - 2.0) * (a - 1.0) * (a - 1.0))
    }

    fn skewness(&self) -> f64 {
        let (n, a, b) = (self.n as f64, self.a, self.b);
        if a <= 3.0 {
            return f64::INFINITY;
        }
        (2.0 * n + a - 1.0) * (2.0 * b + a - 1.0)
            / ((a - 3.0) * (n * b * (n + a - 1.0) * (b + a - 1.0) / (a - 2.0)).sqrt())
    }

    fn kurtosis(&self) -> f64 {
        let (n, a, b) = (self.n as f64, self.a, self.b);
        if a <= 4.0 {
            return f64::INFINITY;
        }
        let term = a - 2.0;
        let am1_sq = (a - 1.0) * (a - 1.0);
        let inner = (a + 5.0) * b * b + (a + 5.0) * (a - 1.0) * b + 2.0 * am1_sq;
        let term2 = am1_sq * (a * a + a * (6.0 * b - 1.0) + 6.0 * (b - 1.0) * b)
            + 3.0 * n * n * inner
            + 3.0 * (a - 1.0) * n * inner;
        let denom = (a - 4.0) * (a - 3.0) * b * n * (a + b - 1.0) * (a + n - 1.0);
        term * term2 / denom - 3.0
    }

    fn mode(&self) -> f64 {
        0.0
    }

    fn entropy(&self) -> f64 {
        // Support is infinite but the pmf tail decays polynomially, so
        // h = −Σ pmf·ln pmf converges (scipy betanbinom sums it too). The
        // recurrence prefix is exact; once the tail is smooth, splice in the
        // integral of p(k) ~ C/k^(a+1) instead of waiting for cumulative mass to
        // cross a threshold that can be lost to f64 summation saturation.
        let mut h = 0.0_f64;
        let nf = self.n as f64;
        let (a, b) = (self.a, self.b);
        let mut k = 0u64;
        let mut logp = self.logpmf(0);
        let mut p = logp.exp();
        loop {
            if p > 0.0 {
                h -= p * logp;
            }
            if k >= 50_000_000 {
                break;
            }
            let fi = k as f64;
            let r = (nf + fi) * (b + fi) / ((fi + 1.0) * (a + nf + b + fi));
            p *= r;
            logp += r.ln();
            k += 1;
            if a >= 2.0 && k >= 8192 && p > 0.0 && logp < -1.0 {
                let tail = Self::entropy_tail_estimate(a, k, p, logp);
                if tail.is_finite() && tail / (k as f64) <= 1e-12 {
                    return h + tail;
                }
            }
        }
        h
    }
}

/// Bernoulli distribution: single trial with probability p.
///
/// Matches `scipy.stats.bernoulli(p)`.
/// Special case of Binomial(1, p).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Bernoulli {
    pub p: f64,
}

impl Bernoulli {
    #[must_use]
    pub fn new(p: f64) -> Self {
        assert!((0.0..=1.0).contains(&p), "p must be in [0, 1], got {p}");
        Self { p }
    }
}

impl DiscreteDistribution for Bernoulli {
    fn pmf(&self, k: u64) -> f64 {
        match k {
            0 => 1.0 - self.p,
            1 => self.p,
            _ => 0.0,
        }
    }
    fn logpmf(&self, k: u64) -> f64 {
        // ln(1−p) / ln(p); finite where pmf underflows. frankenscipy-7m3xk
        match k {
            0 => (1.0 - self.p).ln(),
            1 => self.p.ln(),
            _ => f64::NEG_INFINITY,
        }
    }

    fn cdf(&self, k: u64) -> f64 {
        if k == 0 { 1.0 - self.p } else { 1.0 }
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k): p at k=0, else 0. The default 1−cdf at k=0 is
        // 1−(1−p)=p but cancels; the closed form is exact. frankenscipy-k0sce
        if k == 0 { self.p } else { 0.0 }
    }

    fn logsf(&self, k: u64) -> f64 {
        if k == 0 {
            self.p.ln()
        } else {
            f64::NEG_INFINITY
        }
    }

    fn mean(&self) -> f64 {
        self.p
    }

    fn var(&self) -> f64 {
        self.p * (1.0 - self.p)
    }

    fn entropy(&self) -> f64 {
        if self.p == 0.0 || self.p == 1.0 {
            return 0.0;
        }
        -self.p * self.p.ln() - (1.0 - self.p) * (1.0 - self.p).ln()
    }

    fn skewness(&self) -> f64 {
        let q = 1.0 - self.p;
        (1.0 - 2.0 * self.p) / (self.p * q).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        let q = 1.0 - self.p;
        (1.0 - 6.0 * self.p * q) / (self.p * q)
    }

    fn mode(&self) -> f64 {
        if self.p > 0.5 {
            1.0
        } else if self.p < 0.5 {
            0.0
        } else {
            f64::NAN
        }
    }
}

/// Geometric distribution: number of trials until first success.
///
/// Matches `scipy.stats.geom(p)`.
/// PMF: P(k) = p * (1-p)^(k-1) for k = 1, 2, 3, ...
/// Note: SciPy uses k >= 1 convention (first success on trial k).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Geometric {
    pub p: f64,
}

impl Geometric {
    #[must_use]
    pub fn new(p: f64) -> Self {
        assert!(p > 0.0 && p <= 1.0, "p must be in (0, 1], got {p}");
        Self { p }
    }
}

/// Boltzmann (truncated geometric) distribution.
///
/// Matches `scipy.stats.boltzmann(lambda_, N)`. Resolves
/// [frankenscipy-nvrxh]. Two parameters: rate `lambda > 0` and
/// truncation `n` (positive integer). Support: k ∈ {0, 1, …, n−1}.
///
///   pmf(k; λ, n) = (1 − e^(−λ)) · e^(−λk) / (1 − e^(−λn))
///   cdf(k; λ, n) = (1 − e^(−λ(k+1))) / (1 − e^(−λn))
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Boltzmann {
    pub lambda: f64,
    pub n: u32,
}

impl Boltzmann {
    #[must_use]
    pub fn new(lambda: f64, n: u32) -> Self {
        assert!(
            lambda > 0.0 && lambda.is_finite(),
            "lambda must be positive and finite"
        );
        assert!(n >= 1, "n must be at least 1");
        Self { lambda, n }
    }

    #[inline]
    fn z(&self) -> f64 {
        // Normalization: Z = 1 − e^(−λn).
        -(-self.lambda * self.n as f64).exp_m1()
    }
}

impl DiscreteDistribution for Boltzmann {
    fn pmf(&self, k: u64) -> f64 {
        if k >= self.n as u64 {
            return 0.0;
        }
        let kf = k as f64;
        // (1 − e^(−λ)) · e^(−λk) / (1 − e^(−λn))
        (-(-self.lambda).exp_m1()) * (-self.lambda * kf).exp() / self.z()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln(1 − e^{−λ}) − λk − ln(z); finite where pmf underflows. frankenscipy-7m3xk
        if k >= self.n as u64 {
            return f64::NEG_INFINITY;
        }
        (-(-self.lambda).exp_m1()).ln() - self.lambda * k as f64 - self.z().ln()
    }

    fn cdf(&self, k: u64) -> f64 {
        if k >= self.n as u64 {
            return 1.0;
        }
        let kp1 = (k + 1) as f64;
        // (1 − e^(−λ(k+1))) / (1 − e^(−λn))
        (-(-self.lambda * kp1).exp_m1()) / self.z()
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k) = (e^(−λ(k+1)) − e^(−λn)) / z. The default 1−cdf cancels near
        // the upper edge (k → n−1). Factor as e^(−λ(k+1))·(1−e^(−λ(n−k−1))) so the
        // last terms stay exact (sf(n−1)=0). frankenscipy-k0sce
        if k >= self.n as u64 {
            return 0.0;
        }
        let m = (self.n as u64 - 1 - k) as f64; // n−(k+1) ≥ 0
        (-self.lambda * (k + 1) as f64).exp() * (-(-self.lambda * m).exp_m1()) / self.z()
    }

    fn logsf(&self, k: u64) -> f64 {
        if k >= self.n as u64 {
            return f64::NEG_INFINITY;
        }
        let m = (self.n as u64 - 1 - k) as f64;
        -self.lambda * (k + 1) as f64 + (-(-self.lambda * m).exp_m1()).ln() - self.z().ln()
    }

    fn mean(&self) -> f64 {
        // ⟨k⟩ = (e^(−λ) − n · e^(−λn) + (n−1) · e^(−λ(n+1)))
        //       / ((1 − e^(−λ)) · (1 − e^(−λn)))
        // Equivalent canonical form via geometric-sum derivative:
        //   ⟨k⟩ = 1/(e^λ − 1) − n / (e^(λn) − 1)
        let nf = self.n as f64;
        let lam = self.lambda;
        1.0 / lam.exp_m1() - nf / (lam * nf).exp_m1()
    }

    fn var(&self) -> f64 {
        // Closed form: ⟨k²⟩ − ⟨k⟩².
        // ⟨k²⟩ has a known form too — compute via the same trick:
        //   ⟨k²⟩ = (e^λ + 1) / (e^λ − 1)² − n²/((e^(λn) − 1)·(e^(λn)·(1 − e^(−λn))/(1 − e^(−λ))))
        // For simplicity and robustness, fall back to the direct
        // sum since n is bounded.
        let m = self.mean();
        let mut e_k_sq = 0.0_f64;
        for k in 0..self.n as u64 {
            let kf = k as f64;
            e_k_sq += kf * kf * self.pmf(k);
        }
        (e_k_sq - m * m).max(0.0)
    }

    fn skewness(&self) -> f64 {
        // Boltzmann (truncated geometric) — no clean elementary closed
        // form, direct-sum E[X^k] via the bounded support [0, n−1]
        // (same pattern as var). Cost is O(n).
        let mut m1 = 0.0;
        let mut m2 = 0.0;
        let mut m3 = 0.0;
        for k in 0..self.n as u64 {
            let kf = k as f64;
            let p = self.pmf(k);
            m1 += kf * p;
            m2 += kf * kf * p;
            m3 += kf * kf * kf * p;
        }
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let mut m1 = 0.0;
        let mut m2 = 0.0;
        let mut m3 = 0.0;
        let mut m4 = 0.0;
        for k in 0..self.n as u64 {
            let kf = k as f64;
            let p = self.pmf(k);
            m1 += kf * p;
            m2 += kf * kf * p;
            m3 += kf * kf * kf * p;
            m4 += kf * kf * kf * kf * p;
        }
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // logpmf(k) = logpmf(0) − λk, so H = −E[logpmf(X)] = −logpmf(0) + λE[X].
        -self.logpmf(0) + self.lambda * self.mean()
    }

    fn mode(&self) -> f64 {
        // Truncated geometric pmf ∝ e^{−λk} is strictly decreasing in k,
        // so the mode is the leftmost support point (frankenscipy-ckykz).
        0.0
    }
}

/// Discrete Laplace distribution.
///
/// Matches `scipy.stats.dlaplace(a)`.
/// PMF: P(k) = tanh(a/2) * exp(-a * |k|)
/// Support: all integers.
///
/// Note: The trait uses u64 for k, so pmf/cdf take non-negative k.
/// Use `pmf_signed` for signed integer support.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DiscreteLaplace {
    pub a: f64,
}

impl DiscreteLaplace {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0, "a must be positive, got {a}");
        Self { a }
    }

    pub fn pmf_signed(&self, k: i64) -> f64 {
        (self.a / 2.0).tanh() * (-self.a * k.unsigned_abs() as f64).exp()
    }
}

impl DiscreteDistribution for DiscreteLaplace {
    // DiscreteLaplace has full-integer (signed) support; the u64 ppf/isf cannot
    // represent negative quantiles, so they are unsupported here (the default
    // would silently clamp to 0).
    fn ppf(&self, _q: f64) -> f64 {
        f64::NAN
    }
    fn isf(&self, _q: f64) -> f64 {
        f64::NAN
    }
    fn pmf(&self, k: u64) -> f64 {
        (self.a / 2.0).tanh() * (-self.a * k as f64).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln(tanh(a/2)) − a·k; finite where pmf underflows. frankenscipy-7m3xk
        (self.a / 2.0).tanh().ln() - self.a * k as f64
    }

    fn cdf(&self, k: u64) -> f64 {
        let kf = k as f64;
        let ea = (-self.a).exp();
        let norm = (self.a / 2.0).tanh();
        let sum_neg = ea / (1.0 - ea);
        let sum_zero_to_k = (1.0 - (-self.a * (kf + 1.0)).exp()) / (1.0 - ea);
        norm * (sum_neg + sum_zero_to_k)
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        let ea = (-self.a).exp();
        2.0 * ea / ((1.0 - ea) * (1.0 - ea))
    }

    fn skewness(&self) -> f64 {
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // `2·fourth_raw/var²` is ALREADY the excess (Fisher) kurtosis that
        // scipy.stats.dlaplace.stats('k') reports — the old trailing `- 3.0`
        // over-subtracted (dlaplace(0.5) gave 0.128 vs scipy 3.128).
        let ea = (-self.a).exp();
        let var = 2.0 * ea / ((1.0 - ea) * (1.0 - ea));
        let fourth_raw =
            ea * (1.0 + 4.0 * ea + ea * ea) / ((1.0 - ea) * (1.0 - ea) * (1.0 - ea) * (1.0 - ea));
        2.0 * fourth_raw / (var * var)
    }

    fn mode(&self) -> f64 {
        0.0
    }

    fn entropy(&self) -> f64 {
        // H = -ln(tanh(a/2)) + a·E|k|, with E|k| = 2·tanh(a/2)·e^-a/(1-e^-a)².
        // The old term used e^-a/(1-e^-a) (wrong E|k|), giving up to ~30% error.
        let ea = (-self.a).exp();
        let norm = (self.a / 2.0).tanh();
        let mean_abs = 2.0 * norm * ea / ((1.0 - ea) * (1.0 - ea));
        -norm.ln() + self.a * mean_abs
    }
}

/// Yule-Simon distribution.
///
/// Matches `scipy.stats.yulesimon(alpha)`. Resolves [frankenscipy-1obtd].
/// One parameter `alpha > 0`. Support: k ∈ {1, 2, 3, …}.
///
///   pmf(k; α) = α · B(k, α + 1)
///   cdf(k; α) = 1 − k · B(k, α + 1)
///   mean      = α / (α − 1)             [α > 1, ∞ otherwise]
///   var       = α² / ((α − 1)² · (α − 2))  [α > 2, ∞ otherwise]
///
/// where B is the Beta function. Computed via log-gamma to
/// avoid overflow for large k.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct YuleSimon {
    pub alpha: f64,
}

impl YuleSimon {
    #[must_use]
    pub fn new(alpha: f64) -> Self {
        assert!(
            alpha > 0.0 && alpha.is_finite(),
            "alpha must be positive and finite"
        );
        Self { alpha }
    }

    #[inline]
    fn ln_beta_k(&self, kf: f64) -> f64 {
        // ln B(k, α + 1) = ln Γ(k) + ln Γ(α + 1) − ln Γ(k + α + 1)
        ln_gamma(kf) + ln_gamma(self.alpha + 1.0) - ln_gamma(kf + self.alpha + 1.0)
    }
}

impl DiscreteDistribution for YuleSimon {
    fn pmf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        let kf = k as f64;
        // α · B(k, α + 1) = α · exp(ln B(k, α + 1))
        self.alpha * self.ln_beta_k(kf).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln(α) + ln B(k, α+1); finite power-law tail. frankenscipy-7m3xk
        if k == 0 {
            return f64::NEG_INFINITY;
        }
        self.alpha.ln() + self.ln_beta_k(k as f64)
    }

    fn cdf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        let kf = k as f64;
        // 1 − k · B(k, α + 1)
        (1.0 - kf * self.ln_beta_k(kf).exp()).clamp(0.0, 1.0)
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k) = k · B(k, α + 1) directly (the default 1 − cdf cancels and
        // underflows to 0 in the power-law tail). Matches scipy yulesimon._sf.
        // frankenscipy.
        if k == 0 {
            return 1.0;
        }
        let kf = k as f64;
        (kf * self.ln_beta_k(kf).exp()).clamp(0.0, 1.0)
    }

    fn logsf(&self, k: u64) -> f64 {
        // ln(k) + ln B(k, α + 1); finite deep in the tail where ln(sf) → −inf.
        // Matches scipy yulesimon._logsf. frankenscipy.
        if k == 0 {
            return 0.0;
        }
        (k as f64).ln() + self.ln_beta_k(k as f64)
    }

    fn mean(&self) -> f64 {
        if self.alpha > 1.0 {
            self.alpha / (self.alpha - 1.0)
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        if self.alpha > 2.0 {
            let am1 = self.alpha - 1.0;
            self.alpha * self.alpha / (am1 * am1 * (self.alpha - 2.0))
        } else {
            f64::INFINITY
        }
    }

    fn skewness(&self) -> f64 {
        // YuleSimon closed-form skew (scipy.stats.yulesimon):
        //   skew = √(α − 2) · (α + 1)² / (α · (α − 3))   for α > 3
        if self.alpha <= 3.0 {
            return f64::INFINITY;
        }
        let a = self.alpha;
        (a - 2.0).sqrt() * (a + 1.0).powi(2) / (a * (a - 3.0))
    }

    fn kurtosis(&self) -> f64 {
        // YuleSimon closed-form excess kurt:
        //   κ = α + 3 + (11 α³ − 49 α − 22) / (α · (α − 3) · (α − 4))
        // for α > 4.
        if self.alpha <= 4.0 {
            return f64::INFINITY;
        }
        let a = self.alpha;
        a + 3.0
            + 11.0_f64.mul_add(a.powi(3), (-49.0_f64).mul_add(a, -22.0))
                / (a * (a - 3.0) * (a - 4.0))
    }

    fn mode(&self) -> f64 {
        // YuleSimon pmf α · B(k, α+1) is strictly decreasing in k for
        // every α > 0; mode is the leftmost support point k=1
        // (frankenscipy-ckykz).
        1.0
    }

    fn entropy(&self) -> f64 {
        // YuleSimon pmf decays like α / k^{α+1}. Sum −p ln p over k = 1..K
        // until the cumulative tail bound α · ∫_K^∞ k^{-(α+1)} ln k dk
        // is below abs tolerance. In practice K ≈ 1e6 is more than enough
        // for α ≥ 1 and the per-term cost is just two ln_gamma evals.
        let mut h = 0.0_f64;
        let max_k: u64 = 2_000_000;
        for k in 1..=max_k {
            let p = self.pmf(k);
            if p <= 0.0 {
                if k > 100 {
                    break;
                }
                continue;
            }
            h -= p * p.ln();
            // Tail residual approx: p ~ α/k^{α+1}; ln pmf ≈ −(α+1) ln k.
            // Once the per-term contribution drops below 1e-15, the
            // remainder is negligible at f64 precision.
            if k > 100 && p * p.ln().abs() < 1e-15 {
                break;
            }
        }
        h
    }
}

/// Planck (untruncated geometric) distribution.
///
/// Matches `scipy.stats.planck(lambda_)`. Resolves [frankenscipy-lp6dv].
/// One parameter `lambda > 0`. Support: k ∈ {0, 1, 2, …}.
///
///   pmf(k; λ) = (1 − e^(−λ)) · e^(−λk)
///   cdf(k; λ) = 1 − e^(−λ(k+1))
///   mean      = 1 / (e^λ − 1)
///   var       = e^λ / (e^λ − 1)²
///
/// This is the `N → ∞` limit of `Boltzmann(λ, N)`. Pinned via
/// the `boltzmann_geometric_limit` metamorphic test.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Planck {
    pub lambda: f64,
}

impl Planck {
    #[must_use]
    pub fn new(lambda: f64) -> Self {
        assert!(
            lambda > 0.0 && lambda.is_finite(),
            "lambda must be positive and finite"
        );
        Self { lambda }
    }
}

impl DiscreteDistribution for Planck {
    fn pmf(&self, k: u64) -> f64 {
        let kf = k as f64;
        // (1 − e^(−λ)) · e^(−λk) — expm1 keeps precision when λ is small.
        (-(-self.lambda).exp_m1()) * (-self.lambda * kf).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln(1 − e^{−λ}) − λk; finite where pmf underflows. frankenscipy-7m3xk
        (-(-self.lambda).exp_m1()).ln() - self.lambda * k as f64
    }

    fn cdf(&self, k: u64) -> f64 {
        let kp1 = (k + 1) as f64;
        // 1 − e^(−λ(k+1))
        -(-self.lambda * kp1).exp_m1()
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k) = e^(−λ(k+1)). The default 1−cdf underflows to 0 in the
        // right tail (sf(150,0.5) gave 0 vs scipy 1.6e-33). frankenscipy-k0sce
        (-self.lambda * (k + 1) as f64).exp()
    }

    fn logsf(&self, k: u64) -> f64 {
        // ln(sf) = −λ(k+1); finite where sf underflows (default gave −inf).
        -self.lambda * (k + 1) as f64
    }

    fn mean(&self) -> f64 {
        1.0 / self.lambda.exp_m1()
    }

    fn var(&self) -> f64 {
        let em = self.lambda.exp_m1();
        // Var = e^λ / (e^λ − 1)² = (1 + (e^λ − 1)) / (e^λ − 1)²
        //                      = 1/em + 1/em²
        let inv = 1.0 / em;
        inv * (1.0 + inv)
    }

    fn skewness(&self) -> f64 {
        // Planck is Geometric(p = 1 − e^{−λ}) shifted to start at 0;
        // (2 − p)/√(1 − p) = (1 + e^{−λ}) · e^{λ/2} = 2·cosh(λ/2).
        2.0 * (self.lambda / 2.0).cosh()
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurt = 6 + (1 − e^{−λ})²/e^{−λ} = 4 + 2·cosh(λ).
        2.0_f64.mul_add(self.lambda.cosh(), 4.0)
    }

    fn entropy(&self) -> f64 {
        // Planck = Geometric(p = 1 − e^{−λ}) shifted to start at 0.
        //   h = −ln(1 − e^{−λ}) + λ / (e^λ − 1)
        // Uses log1p / expm1 for stable evaluation at small λ;
        // (−e^{−λ}).ln_1p() = ln(1 − e^{−λ}).
        -(-(-self.lambda).exp()).ln_1p() + self.lambda / self.lambda.exp_m1()
    }

    fn mode(&self) -> f64 {
        // Geometric-like pmf ∝ e^{−λk} (strictly decreasing in k);
        // mode at the leftmost support point (frankenscipy-ckykz).
        0.0
    }
}

impl DiscreteDistribution for Geometric {
    fn pmf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        self.p * (1.0 - self.p).powi((k - 1) as i32)
    }

    fn logpmf(&self, k: u64) -> f64 {
        // ln(p) + (k−1)·ln(1−p); finite where pmf underflows. frankenscipy-7m3xk
        if k == 0 {
            return f64::NEG_INFINITY;
        }
        self.p.ln() + (k - 1) as f64 * (1.0 - self.p).ln()
    }

    fn cdf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        1.0 - (1.0 - self.p).powi(k as i32)
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k) = (1−p)^k. The default 1−cdf underflows to 0 in the right
        // tail (sf(700,0.1) gave 0 vs scipy 9.3e-33) and cancels mid-tail
        // (sf(300) was 1.25e-3 off). frankenscipy-k0sce
        (1.0 - self.p).powi(k as i32)
    }

    fn logsf(&self, k: u64) -> f64 {
        // ln(sf) = k·ln(1−p); finite where sf underflows (default gave −inf).
        k as f64 * (-self.p).ln_1p()
    }

    fn mean(&self) -> f64 {
        1.0 / self.p
    }

    fn var(&self) -> f64 {
        (1.0 - self.p) / (self.p * self.p)
    }

    fn entropy(&self) -> f64 {
        let q = 1.0 - self.p;
        (-(q) * q.ln() - self.p * self.p.ln()) / self.p
    }

    fn skewness(&self) -> f64 {
        (2.0 - self.p) / (1.0 - self.p).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        6.0 + self.p * self.p / (1.0 - self.p)
    }

    fn mode(&self) -> f64 {
        1.0
    }
}

/// Negative binomial distribution: number of failures before n successes.
///
/// Matches `scipy.stats.nbinom(n, p)`.
/// PMF: P(k) = C(k+n-1, k) * p^n * (1-p)^k for k = 0, 1, 2, ...
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NegBinomial {
    /// Number of successes required.
    pub n: f64,
    /// Probability of success on each trial.
    pub p: f64,
}

impl NegBinomial {
    #[must_use]
    pub fn new(n: f64, p: f64) -> Self {
        assert!(n > 0.0, "n must be positive, got {n}");
        assert!(p > 0.0 && p <= 1.0, "p must be in (0, 1], got {p}");
        Self { n, p }
    }

    /// Probability mass at many outcomes (overdispersed count-data workload). Hoists
    /// the parameter-only terms `lnΓ(n)`, `n·ln(p)`, and `ln(1−p)` out of the
    /// per-`k` loop (the `lnΓ(k+n)`/`lnΓ(k+1)` terms vary with `k` and stay). Byte-
    /// identical to mapping `pmf`: same `ln_comb`/`ln_pmf` order, same p==1 case.
    #[must_use]
    pub fn pmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let lg_n = ln_gamma(self.n);
        let n_ln_p = self.n * self.p.ln();
        let ln_1mp = (1.0 - self.p).ln();
        par_discrete_map(ks, |k| {
            if self.p == 1.0 {
                return if k == 0 { 1.0 } else { 0.0 };
            }
            let kf = k as f64;
            let ln_comb = ln_gamma(kf + self.n) - ln_gamma(kf + 1.0) - lg_n;
            let ln_pmf = ln_comb + n_ln_p + kf * ln_1mp;
            ln_pmf.exp()
        })
    }

    /// Cumulative distribution at many points via a mode-anchored pmf recurrence + prefix sum
    /// (O(max_k) cheap mults) instead of a per-point regularized incomplete beta. Anchoring at the
    /// mode (pmf via lnΓ once) avoids the pmf(0)=p^n underflow for large n. Matches
    /// scipy.stats.nbinom.cdf to ~1e-13 in the bulk; deep left tail (<~1e-15) underflows to 0.
    #[must_use]
    pub fn cdf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p >= 1.0 {
            return ks.iter().map(|_| 1.0).collect();
        }
        let max_k = *ks.iter().max().unwrap() as usize;
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let mode = (if n > 1.0 {
            ((n - 1.0) * (1.0 - p) / p) as usize
        } else {
            0
        })
        .min(max_k);
        let mut pmf = vec![0.0f64; max_k + 1];
        pmf[mode] = (ln_gamma(mode as f64 + n) - ln_gamma(n) - ln_gamma(mode as f64 + 1.0)
            + n * ln_p
            + mode as f64 * ln_1mp)
            .exp();
        for k in (mode + 1)..=max_k {
            pmf[k] = pmf[k - 1] * ((k as f64 + n - 1.0) / k as f64) * (1.0 - p);
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * (k as f64 + 1.0) / ((k as f64 + n) * (1.0 - p));
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; max_k + 1];
        for k in 0..=max_k {
            acc += pmf[k];
            cdf[k] = acc.min(1.0);
        }
        ks.iter().map(|&k| cdf[k as usize]).collect()
    }

    /// Survival function P(X>k) at many points via a mode-anchored recurrence + suffix sum. The
    /// table extends ~12σ past the mean so the upper tail is captured when max_k is small.
    /// Tail-accurate; matches scipy.stats.nbinom.sf to ~1e-13 in the bulk.
    #[must_use]
    pub fn sf_many(&self, ks: &[u64]) -> Vec<f64> {
        if ks.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p >= 1.0 {
            return ks.iter().map(|_| 0.0).collect();
        }
        let max_k = *ks.iter().max().unwrap() as usize;
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let mean = n * (1.0 - p) / p;
        let std = (n * (1.0 - p)).sqrt() / p;
        let k_hi = max_k.max((mean + 12.0 * std + 12.0) as usize);
        let mode = (if n > 1.0 {
            ((n - 1.0) * (1.0 - p) / p) as usize
        } else {
            0
        })
        .min(k_hi);
        let mut pmf = vec![0.0f64; k_hi + 1];
        pmf[mode] = (ln_gamma(mode as f64 + n) - ln_gamma(n) - ln_gamma(mode as f64 + 1.0)
            + n * ln_p
            + mode as f64 * ln_1mp)
            .exp();
        for k in (mode + 1)..=k_hi {
            pmf[k] = pmf[k - 1] * ((k as f64 + n - 1.0) / k as f64) * (1.0 - p);
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * (k as f64 + 1.0) / ((k as f64 + n) * (1.0 - p));
        }
        let mut suf = vec![0.0f64; k_hi + 2];
        for k in (0..k_hi).rev() {
            suf[k] = suf[k + 1] + pmf[k + 1];
        }
        ks.iter()
            .map(|&k| suf[(k as usize).min(k_hi)].clamp(0.0, 1.0))
            .collect()
    }

    /// Inverse cdf at many probabilities: cdf table (mode-anchored recurrence + prefix sum, extended
    /// ~15σ past the mean) + binary search, with a guarded scalar-cdf disambiguation near cdf steps
    /// so it equals the scalar `ppf`. Quantiles past the table fall back to the scalar `ppf`.
    #[must_use]
    pub fn ppf_many(&self, qs: &[f64]) -> Vec<f64> {
        if qs.is_empty() {
            return Vec::new();
        }
        let n = self.n;
        let p = self.p;
        if p >= 1.0 {
            return qs
                .iter()
                .map(|&q| if q <= 0.0 { -1.0 } else { 0.0 })
                .collect();
        }
        let ln_p = p.ln();
        let ln_1mp = (1.0 - p).ln();
        let mean = n * (1.0 - p) / p;
        let std = (n * (1.0 - p)).sqrt() / p;
        let k_hi = (mean + 15.0 * std + 15.0) as usize;
        let mode = (if n > 1.0 {
            ((n - 1.0) * (1.0 - p) / p) as usize
        } else {
            0
        })
        .min(k_hi);
        let mut pmf = vec![0.0f64; k_hi + 1];
        pmf[mode] = (ln_gamma(mode as f64 + n) - ln_gamma(n) - ln_gamma(mode as f64 + 1.0)
            + n * ln_p
            + mode as f64 * ln_1mp)
            .exp();
        for k in (mode + 1)..=k_hi {
            pmf[k] = pmf[k - 1] * ((k as f64 + n - 1.0) / k as f64) * (1.0 - p);
        }
        for k in (0..mode).rev() {
            pmf[k] = pmf[k + 1] * (k as f64 + 1.0) / ((k as f64 + n) * (1.0 - p));
        }
        let mut acc = 0.0;
        let mut cdf = vec![0.0f64; k_hi + 1];
        for k in 0..=k_hi {
            acc += pmf[k];
            cdf[k] = acc.min(1.0);
        }
        // Independent per-quantile `partition_point` + boundary refinement into the shared CDF table,
        // so fan across cores for large `qs` via the order-preserving `par_continuous_map_min` —
        // BYTE-IDENTICAL (same index per quantile, tail overflow → scalar `ppf`, same order). Below
        // 800k use the direct serial map. Shares `DISCRETE_PPF_MANY_FORCE_SERIAL`.
        let cdf_ref = &cdf;
        let this = self;
        let eval = move |q: f64| -> f64 {
            if q <= 0.0 {
                return -1.0;
            }
            if q >= 1.0 {
                return f64::INFINITY;
            }
            let idx = cdf_ref.partition_point(|&c| c < q);
            if idx > k_hi {
                return this.ppf(q);
            }
            let mut k = idx;
            let near = (k > 0 && q - cdf_ref[k - 1] < 1e-11) || (cdf_ref[k] - q < 1e-11);
            if near {
                while k > 0 && this.cdf((k - 1) as u64) >= q {
                    k -= 1;
                }
                while k < k_hi && this.cdf(k as u64) < q {
                    k += 1;
                }
            }
            k as f64
        };
        if DISCRETE_PPF_MANY_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
            || qs.len() < 800_000
        {
            qs.iter().map(|&q| eval(q)).collect()
        } else {
            par_continuous_map_min(qs, 400_000, eval)
        }
    }
}

impl DiscreteDistribution for NegBinomial {
    fn pmf(&self, k: u64) -> f64 {
        // Limit case: with p=1 every trial succeeds, so the count of
        // failures is 0 with probability 1. Without this short-circuit
        // the formula evaluates 0 · ln(0) = NaN at k=0.
        if self.p == 1.0 {
            return if k == 0 { 1.0 } else { 0.0 };
        }
        let kf = k as f64;
        // C(k+n-1, k) = Γ(k+n) / (Γ(k+1) * Γ(n))
        let ln_comb = ln_gamma(kf + self.n) - ln_gamma(kf + 1.0) - ln_gamma(self.n);
        let ln_pmf = ln_comb + self.n * self.p.ln() + kf * (1.0 - self.p).ln();
        ln_pmf.exp()
    }

    fn cdf(&self, k: u64) -> f64 {
        // Closed form P(X<=k) = I_p(n, k+1), matching scipy's nbdtr. O(1) vs the
        // old O(k) pmf summation. frankenscipy-7kq9d
        regularized_incomplete_beta(self.n, k as f64 + 1.0, self.p)
    }
    fn logpmf(&self, k: u64) -> f64 {
        // ln C(k+n−1,k) + n·ln(p) + k·ln(1−p); finite where pmf underflows
        // (negative-binomial-GLM log-likelihood term). frankenscipy-7m3xk
        if self.p == 1.0 {
            return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
        }
        let kf = k as f64;
        let ln_comb = ln_gamma(kf + self.n) - ln_gamma(kf + 1.0) - ln_gamma(self.n);
        ln_comb + self.n * self.p.ln() + kf * (1.0 - self.p).ln()
    }
    fn sf(&self, k: u64) -> f64 {
        // P(X>k) = I_{1-p}(k+1, n); direct so the right tail does not collapse
        // like the default 1-cdf. frankenscipy-r4933
        regularized_incomplete_beta(k as f64 + 1.0, self.n, 1.0 - self.p)
    }
    fn logcdf(&self, k: u64) -> f64 {
        // log P(X<=k) = log I_p(n, k+1); finite in the left tail. frankenscipy-r4933
        fsci_special::log_betainc_scalar(self.n, k as f64 + 1.0, self.p)
    }
    fn logsf(&self, k: u64) -> f64 {
        // log P(X>k) = log I_{1-p}(k+1, n); finite in the right tail. frankenscipy-r4933
        fsci_special::log_betainc_scalar(k as f64 + 1.0, self.n, 1.0 - self.p)
    }

    fn mean(&self) -> f64 {
        self.n * (1.0 - self.p) / self.p
    }

    fn var(&self) -> f64 {
        self.n * (1.0 - self.p) / (self.p * self.p)
    }

    fn skewness(&self) -> f64 {
        let q = 1.0 - self.p;
        (2.0 - self.p) / (self.n * q).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        let q = 1.0 - self.p;
        6.0 / self.n + self.p * self.p / (self.n * q)
    }

    fn mode(&self) -> f64 {
        if self.n > 1.0 {
            ((self.n - 1.0) * (1.0 - self.p) / self.p).floor()
        } else {
            0.0
        }
    }

    fn entropy(&self) -> f64 {
        // Unbounded support k ∈ {0, 1, …}, but pmf decays geometrically
        // as (1−p)^k for fixed n. Cap K so the truncated tail is below
        // f64 round-off (~1e-15); a safety ceiling avoids runaway when p
        // is tiny.
        if self.p == 1.0 {
            return 0.0;
        }
        let mut h = 0.0_f64;
        let max_k: u64 = 1_000_000;
        let mut tail = 1.0_f64;
        for k in 0..=max_k {
            let p = self.pmf(k);
            if p > 0.0 {
                h -= p * p.ln();
                tail -= p;
            }
            if k > 32 && tail < 1e-15 {
                break;
            }
        }
        h
    }
}

/// Hypergeometric distribution: draws without replacement.
///
/// Matches `scipy.stats.hypergeom(M, n, N)`.
/// PMF: P(k) = C(n, k) * C(M-n, N-k) / C(M, N)
///
/// M = total population, n = success states in population, N = draws.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Hypergeometric {
    /// Total population size.
    pub big_m: u64,
    /// Number of success states in population.
    pub n: u64,
    /// Number of draws.
    pub big_n: u64,
}

impl Hypergeometric {
    #[must_use]
    pub fn new(big_m: u64, n: u64, big_n: u64) -> Self {
        assert!(n <= big_m, "n must be <= M, got n={n}, M={big_m}");
        assert!(big_n <= big_m, "N must be <= M, got N={big_n}, M={big_m}");
        Self { big_m, n, big_n }
    }

    /// Log-pmf at many outcomes, hoisting the FIVE parameter-only lgamma terms
    /// (`lnΓ(n+1)`, `lnΓ(M−n+1)`, `lnΓ(M+1)`, `lnΓ(N+1)`, `lnΓ(M−N+1)`) out of the
    /// per-`k` loop — each substituted IN PLACE so the interleaved +/− operation
    /// order matches `logpmf` exactly (the four `k`-dependent lgammas stay). Byte-
    /// identical to mapping `logpmf`, same out-of-support → −∞.
    #[must_use]
    pub fn logpmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        let g_n1 = ln_gamma(n + 1.0);
        let g_mn1 = ln_gamma(m - n + 1.0);
        let g_m1 = ln_gamma(m + 1.0);
        let g_bign1 = ln_gamma(big_n + 1.0);
        let g_mbign1 = ln_gamma(m - big_n + 1.0);
        let k_min = if self.big_n.saturating_add(self.n) > self.big_m {
            (self.big_n + self.n - self.big_m) as f64
        } else {
            0.0
        };
        let k_max = n.min(big_n);
        par_discrete_map(ks, |k| {
            let kf = k as f64;
            if kf < k_min || kf > k_max {
                return f64::NEG_INFINITY;
            }
            g_n1 - ln_gamma(kf + 1.0) - ln_gamma(n - kf + 1.0) + g_mn1
                - ln_gamma(big_n - kf + 1.0)
                - ln_gamma(m - n - big_n + kf + 1.0)
                - g_m1
                + g_bign1
                + g_mbign1
        })
    }

    /// Pmf at many outcomes; hoists the same five lgamma terms as
    /// [`logpmf_many`](Self::logpmf_many). Byte-identical to mapping `pmf`.
    #[must_use]
    pub fn pmf_many(&self, ks: &[u64]) -> Vec<f64> {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        let k_min = if self.big_n.saturating_add(self.n) > self.big_m {
            (self.big_n + self.n - self.big_m) as f64
        } else {
            0.0
        };
        let k_max = n.min(big_n);
        // k_min == 0 (N + n <= M): hoist pmf(0) once, then the exact ratio recurrence per k. This is
        // byte-identical to the single `pmf` (same pmf0, same per-k ratio loop) and ~1 ULP accurate,
        // vs the ~5e-14 cancellation of the lgamma log-pmf (hypergeometric_sf_tail_match_scipy).
        if k_min == 0.0 {
            // Sweep pmf(0..=max_k) once via the ratio recurrence into a table, then index. table[k]
            // = pmf0·r1·…·rk is the same left-associated product as the single pmf(k), so this stays
            // byte-identical to mapping pmf — but O(N + max_k + K) instead of O(N + Σk) per-k.
            let max_k = ks
                .iter()
                .copied()
                .filter(|&k| (k as f64) <= k_max)
                .max()
                .unwrap_or(0);
            let mut table = vec![0.0_f64; max_k as usize + 1];
            let mut p = self.pmf0_recurrence();
            table[0] = p;
            for i in 1..=max_k {
                let fi = i as f64;
                p *= ((n - fi + 1.0) * (big_n - fi + 1.0)) / (fi * (m - n - big_n + fi));
                table[i as usize] = p;
            }
            return ks
                .iter()
                .map(|&k| {
                    let kf = k as f64;
                    if kf < k_min || kf > k_max {
                        0.0
                    } else {
                        table[k as usize]
                    }
                })
                .collect();
        }
        let g_n1 = ln_gamma(n + 1.0);
        let g_mn1 = ln_gamma(m - n + 1.0);
        let g_m1 = ln_gamma(m + 1.0);
        let g_bign1 = ln_gamma(big_n + 1.0);
        let g_mbign1 = ln_gamma(m - big_n + 1.0);
        // General regime (k_min != 0): each in-range k is an INDEPENDENT 5-`ln_gamma` log-pmf, so fan
        // the query points across cores via the order-preserving `par_discrete_map` (the same helper
        // the sibling discrete pmf/logpmf use) — BYTE-IDENTICAL to `ks.iter().map(..).collect()`.
        par_discrete_map(ks, |k| {
            let kf = k as f64;
            if kf < k_min || kf > k_max {
                return 0.0;
            }
            let ln_pmf = g_n1 - ln_gamma(kf + 1.0) - ln_gamma(n - kf + 1.0) + g_mn1
                - ln_gamma(big_n - kf + 1.0)
                - ln_gamma(m - n - big_n + kf + 1.0)
                - g_m1
                + g_bign1
                + g_mbign1;
            ln_pmf.exp()
        })
    }

    /// pmf(0) = C(M-n, N)/C(M,N) built as a product of N ratios (no large-lgamma cancellation).
    /// Only valid when k_min == 0 (N + n <= M), where every factor stays positive.
    fn pmf0_recurrence(&self) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let mut p = 1.0;
        let mut j = 0u64;
        while j < self.big_n {
            p *= (m - n - j as f64) / (m - j as f64);
            j += 1;
        }
        p
    }

    /// pmf(k) from pmf(0) via the exact ratio recurrence
    /// pmf(k)/pmf(k-1) = (n-k+1)(N-k+1) / [k (M-n-N+k)].
    fn pmf_from0(&self, p0: f64, k: u64) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        let mut p = p0;
        for i in 1..=k {
            let fi = i as f64;
            p *= ((n - fi + 1.0) * (big_n - fi + 1.0)) / (fi * (m - n - big_n + fi));
        }
        p
    }
}

impl DiscreteDistribution for Hypergeometric {
    fn pmf(&self, k: u64) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        let kf = k as f64;

        // Valid range: max(0, N+n-M) <= k <= min(n, N)
        // Use saturating_add to avoid u64 overflow
        let k_min = if self.big_n.saturating_add(self.n) > self.big_m {
            (self.big_n + self.n - self.big_m) as f64
        } else {
            0.0
        };
        let k_max = n.min(big_n);
        if kf < k_min || kf > k_max {
            return 0.0;
        }

        // k_min == 0: exact ratio recurrence — byte-identical to pmf_many, ~1 ULP vs the lgamma
        // log-pmf's ~5e-14 cancellation (hypergeometric_sf_tail_match_scipy).
        if k_min == 0.0 {
            return self.pmf_from0(self.pmf0_recurrence(), k);
        }

        // ln(C(n,k)) + ln(C(M-n, N-k)) - ln(C(M, N))
        let ln_pmf = ln_gamma(n + 1.0) - ln_gamma(kf + 1.0) - ln_gamma(n - kf + 1.0)
            + ln_gamma(m - n + 1.0)
            - ln_gamma(big_n - kf + 1.0)
            - ln_gamma(m - n - big_n + kf + 1.0)
            - ln_gamma(m + 1.0)
            + ln_gamma(big_n + 1.0)
            + ln_gamma(m - big_n + 1.0);
        ln_pmf.exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // log of the hypergeometric pmf (the pmf forms this then exp's it);
        // finite where pmf underflows. frankenscipy-7m3xk
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        let kf = k as f64;
        let k_min = if self.big_n.saturating_add(self.n) > self.big_m {
            (self.big_n + self.n - self.big_m) as f64
        } else {
            0.0
        };
        if kf < k_min || kf > n.min(big_n) {
            return f64::NEG_INFINITY;
        }
        ln_gamma(n + 1.0) - ln_gamma(kf + 1.0) - ln_gamma(n - kf + 1.0) + ln_gamma(m - n + 1.0)
            - ln_gamma(big_n - kf + 1.0)
            - ln_gamma(m - n - big_n + kf + 1.0)
            - ln_gamma(m + 1.0)
            + ln_gamma(big_n + 1.0)
            + ln_gamma(m - big_n + 1.0)
    }

    fn mean(&self) -> f64 {
        self.big_n as f64 * self.n as f64 / self.big_m as f64
    }

    fn var(&self) -> f64 {
        let m = self.big_m as f64;
        if m <= 1.0 {
            return 0.0; // Degenerate: single-element population has no variance
        }
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        big_n * (n / m) * ((m - n) / m) * ((m - big_n) / (m - 1.0))
    }

    fn cdf(&self, k: u64) -> f64 {
        // Lower-tail sum via the recurrence sweep (pmf_many) instead of the trait default
        // (0..=k).map(self.pmf).sum(), which is O(k·N) now that the single pmf is O(N+k). pmf(i)=0
        // for i>k_max so capping the range is byte-identical; pmf_many==map(pmf). O(N+k).
        let k_max = self.n.min(self.big_n);
        let hi = k.min(k_max);
        let ks: Vec<u64> = (0..=hi).collect();
        self.pmf_many(&ks).iter().sum::<f64>().min(1.0)
    }

    fn sf(&self, k: u64) -> f64 {
        // P(X > k) summed DIRECTLY over the upper tail [k+1, k_max]. The trait
        // default 1 - cdf cancels and underflows to 0 deep in the right tail
        // (e.g. hypergeom(500,50,100).sf(40) = 5.9e-24 vs 0.0 from 1-cdf, and
        // already ~7e-6 off at sf(30)). Matches scipy.stats.hypergeom.sf, same
        // direct-sum approach used for geom/skellam/yulesimon.
        let k_max = self.n.min(self.big_n);
        if k >= k_max {
            return 0.0;
        }
        // Sum pmf over the upper tail via the recurrence sweep (pmf_many), O(N + k_max) instead of
        // O((k_max-k)·N) from per-j self.pmf (each rebuilds pmf0). Byte-identical (pmf_many==map pmf).
        let ks: Vec<u64> = ((k + 1)..=k_max).collect();
        self.pmf_many(&ks).iter().sum::<f64>().clamp(0.0, 1.0)
    }

    fn skewness(&self) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        if m <= 2.0 {
            return f64::NAN;
        }
        let num = (m - 2.0 * n) * (m - 2.0 * big_n) * (m - 1.0).sqrt();
        let den = (m - 2.0) * (n * big_n * (m - n) * (m - big_n)).sqrt();
        num / den
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis of the hypergeometric distribution. The
        // closed form already returns excess (k4 − 3); pre-fix the
        // c-coefficient was wrong (3 instead of 6, and M+6 instead
        // of 5M-6) AND the result was further reduced by an
        // unjustified `- 3.0`, which together landed ~3.57 abs off
        // scipy at (M=50, n=20, N=10). frankenscipy-r863g.
        //
        // Wikipedia / Johnson-Kotz closed form for excess kurtosis:
        //   num = (M-1)·M²·(M(M+1) − 6n(M-n) − 6N(M-N))
        //       + 6·n·N·(M-n)·(M-N)·(5M-6)
        //   den = n·N·(M-n)·(M-N)·(M-2)·(M-3)
        //   excess = num / den.
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        if m <= 3.0 {
            return f64::NAN;
        }
        let a = (m - 1.0) * m * m;
        let b = m * (m + 1.0) - 6.0 * n * (m - n) - 6.0 * big_n * (m - big_n);
        let c = 6.0 * n * big_n * (m - n) * (m - big_n) * (5.0 * m - 6.0);
        let num = a * b + c;
        let den = n * big_n * (m - n) * (m - big_n) * (m - 2.0) * (m - 3.0);
        num / den
    }

    fn mode(&self) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let big_n = self.big_n as f64;
        ((n + 1.0) * (big_n + 1.0) / (m + 2.0)).floor()
    }

    fn entropy(&self) -> f64 {
        // Hypergeometric is supported on a bounded range
        // [max(0, N+n-M), min(n, N)]. Direct sum over that range is exact.
        let k_lo = if self.big_n.saturating_add(self.n) > self.big_m {
            self.big_n + self.n - self.big_m
        } else {
            0
        };
        let k_hi = self.n.min(self.big_n);
        // Direct entropy sum via the recurrence sweep (pmf_many), O(N + k_hi) instead of O(K·N) from
        // per-k self.pmf. Byte-identical: same pmf values, and h - x == h + (-x) in IEEE.
        let ks: Vec<u64> = (k_lo..=k_hi).collect();
        self.pmf_many(&ks)
            .iter()
            .map(|&p| if p > 0.0 { -p * p.ln() } else { 0.0 })
            .sum()
    }
}

// ══════════════════════════════════════════════════════════════════════
// Wallenius' Noncentral Hypergeometric Distribution
// ══════════════════════════════════════════════════════════════════════

/// Wallenius' noncentral hypergeometric distribution.
///
/// Matches `scipy.stats.nchypergeom_wallenius(M, n, N, odds)`: a population of
/// `M` objects, `n` of Type I, from which `N` are drawn one at a time with the
/// Type-I items weighted by the `odds` ratio (biased urn). Support is
/// `max(0, N-(M-n)) ..= min(n, N)`.
///
/// PMF (Fog 2008), after the regularizing substitution `u = t^{1/D}`:
/// `P(x) = C(n,x) C(M-n,N-x) · D ∫_0^1 (1-u^ω)^x (1-u)^{N-x} u^{D-1} du`,
/// with `D = ω(n-x) + (M-n-N+x)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NchypergeomWallenius {
    /// Total population size `M`.
    pub big_m: u64,
    /// Number of Type I objects `n`.
    pub n: u64,
    /// Number of objects drawn `N`.
    pub big_n: u64,
    /// Odds ratio `ω > 0` for drawing a Type I object.
    pub odds: f64,
}

impl NchypergeomWallenius {
    #[must_use]
    pub fn new(big_m: u64, n: u64, big_n: u64, odds: f64) -> Self {
        assert!(n <= big_m, "n must be <= M, got n={n}, M={big_m}");
        assert!(big_n <= big_m, "N must be <= M, got N={big_n}, M={big_m}");
        assert!(odds > 0.0, "odds must be > 0, got {odds}");
        Self {
            big_m,
            n,
            big_n,
            odds,
        }
    }

    fn support(&self) -> (u64, u64) {
        let lo = self.big_n.saturating_sub(self.big_m - self.n);
        let hi = self.n.min(self.big_n);
        (lo, hi)
    }
}

impl DiscreteDistribution for NchypergeomWallenius {
    fn pmf(&self, k: u64) -> f64 {
        let (lo, hi) = self.support();
        if k < lo || k > hi {
            return 0.0;
        }
        let m = self.big_m as f64;
        let n = self.n as f64;
        let bn = self.big_n as f64;
        let w = self.odds;
        let x = k as f64;
        let d = w * (n - x) + (m - n - bn + x);
        // Regularized Wallenius integrand on [0, 1].
        let integ = simpson_integrate_adaptive(
            |u| {
                if u <= 0.0 || u >= 1.0 {
                    return 0.0;
                }
                let v = (1.0 - u.powf(w)).powf(x) * (1.0 - u).powf(bn - x) * u.powf(d - 1.0);
                if v.is_finite() { v } else { 0.0 }
            },
            0.0,
            1.0,
            128,
            1e-13,
            1e-15,
            40,
        );
        comb(n, x) * comb(m - n, bn - x) * d * integ
    }

    fn mean(&self) -> f64 {
        let (lo, hi) = self.support();
        (lo..=hi).map(|x| x as f64 * self.pmf(x)).sum()
    }

    fn var(&self) -> f64 {
        let (lo, hi) = self.support();
        let mean = self.mean();
        let e2: f64 = (lo..=hi).map(|x| (x as f64).powi(2) * self.pmf(x)).sum();
        e2 - mean * mean
    }
}

// ══════════════════════════════════════════════════════════════════════
// Negative Hypergeometric Distribution
// ══════════════════════════════════════════════════════════════════════

/// Negative hypergeometric distribution.
///
/// Matches `scipy.stats.nhypergeom(M, n, r)`: a population of `M` objects with
/// `n` of Type I; sample without replacement until `r` Type I are drawn; the
/// variable is the number of Type II drawn before then. Support is `0..=n`.
/// PMF: P(k) = C(k+r-1, k) * C(M-r-k, n-k) / C(M, n)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct NegHypergeometric {
    pub big_m: u64,
    pub n: u64,
    pub r: u64,
}

impl NegHypergeometric {
    #[must_use]
    pub fn new(big_m: u64, n: u64, r: u64) -> Self {
        assert!(n <= big_m, "n must be <= M, got n={n}, M={big_m}");
        assert!(
            r <= big_m - n,
            "r must be <= M - n, got r={r}, M-n={}",
            big_m - n
        );
        Self { big_m, n, r }
    }

    fn ln_comb(n: u64, k: u64) -> f64 {
        if k > n {
            return f64::NEG_INFINITY;
        }
        ln_gamma(n as f64 + 1.0) - ln_gamma(k as f64 + 1.0) - ln_gamma((n - k) as f64 + 1.0)
    }

    /// Central moments (m2, m3, m4) over the support, via the same mode-anchored
    /// pmf-ratio recurrence used by `cdf`/`entropy` — one ln_gamma-based pmf at the
    /// mode + O(n) multiply/adds, instead of ~6 ln_gamma per term in a fresh-pmf
    /// loop. Reproduces the fresh-pmf central-moment sums to ≤2e-11 (the loop order
    /// reassociates; the residual vs SciPy is a pre-existing summation characteristic
    /// shared by both, not introduced here). Used by skewness and kurtosis.
    fn central_moments(&self, mu: f64) -> (f64, f64, f64) {
        let (m_i, n_i, r_i) = (self.big_m, self.n, self.r);
        if r_i == 0 {
            return (0.0, 0.0, 0.0); // all mass at k=0
        }
        let (mf, nf, rf) = (m_i as f64, n_i as f64, r_i as f64);
        let denom = mf - nf - 1.0;
        let mode = if denom <= 0.0 {
            0.0
        } else {
            ((rf * (nf + 1.0) - mf) / denom).floor()
        };
        let m = mode.clamp(0.0, nf) as u64;
        let pm = self.logpmf(m).exp();
        let (mut m2, mut m3, mut m4) = (0.0_f64, 0.0_f64, 0.0_f64);
        let d = m as f64 - mu;
        let d2 = d * d;
        m2 += pm * d2;
        m3 += pm * d2 * d;
        m4 += pm * d2 * d2;
        // Downward from the mode to 0.
        let mut pk = pm;
        let mut i = m;
        while i > 0 {
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(M−r−i+1) / ((i−1+r)(n−i+1))
            pk *= fi * (mf - rf - fi + 1.0) / ((fi - 1.0 + rf) * (nf - fi + 1.0));
            i -= 1;
            let d = i as f64 - mu;
            let d2 = d * d;
            m2 += pk * d2;
            m3 += pk * d2 * d;
            m4 += pk * d2 * d2;
        }
        // Upward from the mode to n.
        pk = pm;
        i = m;
        while i < n_i {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (i+r)(n−i) / ((i+1)(M−r−i))
            pk *= (fi + rf) * (nf - fi) / ((fi + 1.0) * (mf - rf - fi));
            i += 1;
            let d = i as f64 - mu;
            let d2 = d * d;
            m2 += pk * d2;
            m3 += pk * d2 * d;
            m4 += pk * d2 * d2;
        }
        (m2, m3, m4)
    }
}

impl DiscreteDistribution for NegHypergeometric {
    fn pmf(&self, k: u64) -> f64 {
        let m = self.big_m;
        let n = self.n;
        let r = self.r;
        if r == 0 {
            return if k == 0 { 1.0 } else { 0.0 };
        }
        let max_k = n;
        if k > max_k {
            return 0.0;
        }
        let ln_num1 = Self::ln_comb(k + r - 1, k);
        let ln_num2 = Self::ln_comb(m - r - k, n - k);
        let ln_den = Self::ln_comb(m, n);
        (ln_num1 + ln_num2 - ln_den).exp()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // log of the negative-hypergeometric pmf (pmf forms this then exp's it);
        // finite where pmf underflows. frankenscipy-7m3xk
        let m = self.big_m;
        let n = self.n;
        let r = self.r;
        if r == 0 {
            return if k == 0 { 0.0 } else { f64::NEG_INFINITY };
        }
        if k > n {
            return f64::NEG_INFINITY;
        }
        Self::ln_comb(k + r - 1, k) + Self::ln_comb(m - r - k, n - k) - Self::ln_comb(m, n)
    }

    fn cdf(&self, k: u64) -> f64 {
        // The fresh-pmf sum below paid 3 ln_comb (~6 ln_gamma) PER term. The pmf has
        // a closed ratio: pmf(i+1)/pmf(i) = (i+r)(n−i) / ((i+1)(M−r−i)). Anchor at
        // the mode (the largest pmf — never underflows; the constructor guarantees
        // M−r ≥ n so every denominator stays ≥ 1) and sweep outward, summing [0,k].
        // One ln_gamma-based pmf at the mode + O(n) multiply/adds. Verified vs
        // scipy.stats.nhypergeom.cdf to ≤8.3e-13 incl. a 1e-29 tail.
        let (m_i, n_i, r_i) = (self.big_m, self.n, self.r);
        if r_i == 0 {
            return 1.0; // degenerate: all mass at k=0
        }
        let k = k.min(n_i);
        let (mf, nf, rf) = (m_i as f64, n_i as f64, r_i as f64);
        // Mode = floor((r(n+1) − M)/(M − n − 1)) clamped to [0, n], in f64 so the
        // numerator may go negative without u64 underflow. An off-by-one vs the true
        // argmax is harmless — the anchor pmf is still ~max and representable.
        let denom = mf - nf - 1.0;
        let mode = if denom <= 0.0 {
            0.0
        } else {
            ((rf * (nf + 1.0) - mf) / denom).floor()
        };
        let m = mode.clamp(0.0, nf) as u64;
        let pm = self.logpmf(m).exp();
        let mut total = 0.0_f64;
        // Downward from the mode to 0, counting indices ≤ k.
        let mut pk = pm;
        let mut i = m;
        loop {
            if i <= k {
                total += pk;
            }
            if i == 0 {
                break;
            }
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(M−r−i+1) / ((i−1+r)(n−i+1))
            pk *= fi * (mf - rf - fi + 1.0) / ((fi - 1.0 + rf) * (nf - fi + 1.0));
            i -= 1;
        }
        // Upward from the mode to k.
        pk = pm;
        i = m;
        while i < k {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (i+r)(n−i) / ((i+1)(M−r−i))
            pk *= (fi + rf) * (nf - fi) / ((fi + 1.0) * (mf - rf - fi));
            i += 1;
            total += pk;
        }
        total.min(1.0)
    }

    fn mean(&self) -> f64 {
        let m = self.big_m as f64;
        let n = self.n as f64;
        let r = self.r as f64;
        r * n / (m - n + 1.0)
    }

    fn var(&self) -> f64 {
        // scipy.stats.nhypergeom variance:
        // r·n·(M+1)·(M−n+1−r) / ((M−n+1)²·(M−n+2)).
        let m = self.big_m as f64;
        let n = self.n as f64;
        let r = self.r as f64;
        let mn1 = m - n + 1.0;
        r * n * (m + 1.0) * (mn1 - r) / (mn1 * mn1 * (mn1 + 1.0))
    }

    fn skewness(&self) -> f64 {
        // Finite support [0, n]: central moments via the pmf-ratio recurrence
        // (see `central_moments`) instead of a fresh-lgamma pmf per term.
        let mu = self.mean();
        let (m2, m3, _) = self.central_moments(mu);
        m3 / m2.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis from the recurrence-summed central moments over [0, n].
        let mu = self.mean();
        let (m2, _, m4) = self.central_moments(mu);
        m4 / (m2 * m2) - 3.0
    }

    fn mode(&self) -> f64 {
        0.0
    }

    fn entropy(&self) -> f64 {
        // H = −Σ pmf·ln(pmf) over [0,n]. Same lever as the cdf: track pmf and ln(pmf)
        // jointly via the pmf-ratio recurrence (pmf(i+1)/pmf(i)=(i+r)(n−i)/((i+1)(M−r−i))),
        // anchored at the mode so the pmf never underflows (and r≤M−n ⇒ denominators ≥ 1).
        // One ln_gamma-based pmf at the mode + O(n) (one ln per term). Verified vs
        // scipy.stats.nhypergeom.entropy to ≤4.2e-13.
        let (m_i, n_i, r_i) = (self.big_m, self.n, self.r);
        if r_i == 0 {
            return 0.0; // degenerate: all mass at k=0, H=0
        }
        let (mf, nf, rf) = (m_i as f64, n_i as f64, r_i as f64);
        let denom = mf - nf - 1.0;
        let mode = if denom <= 0.0 {
            0.0
        } else {
            ((rf * (nf + 1.0) - mf) / denom).floor()
        };
        let m = mode.clamp(0.0, nf) as u64;
        let lp_m = self.logpmf(m);
        let pm = lp_m.exp();
        let mut h = if pm > 0.0 { -pm * lp_m } else { 0.0 };
        // Downward from the mode to 0.
        let mut pk = pm;
        let mut lpk = lp_m;
        let mut i = m;
        while i > 0 {
            let fi = i as f64;
            // pmf(i−1)/pmf(i) = i(M−r−i+1) / ((i−1+r)(n−i+1))
            let r = fi * (mf - rf - fi + 1.0) / ((fi - 1.0 + rf) * (nf - fi + 1.0));
            pk *= r;
            lpk += r.ln();
            i -= 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        // Upward from the mode to n.
        pk = pm;
        lpk = lp_m;
        i = m;
        while i < n_i {
            let fi = i as f64;
            // pmf(i+1)/pmf(i) = (i+r)(n−i) / ((i+1)(M−r−i))
            let r = (fi + rf) * (nf - fi) / ((fi + 1.0) * (mf - rf - fi));
            pk *= r;
            lpk += r.ln();
            i += 1;
            if pk > 0.0 {
                h -= pk * lpk;
            }
        }
        h
    }
}

/// Logarithmic (log-series) distribution.
///
/// Matches `scipy.stats.logser`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LogSeries {
    pub p: f64,
}

impl LogSeries {
    #[must_use]
    pub fn new(p: f64) -> Self {
        assert!(p > 0.0 && p < 1.0, "p must be in (0, 1), got {p}");
        Self { p }
    }

    fn norm(&self) -> f64 {
        -(-self.p).ln_1p()
    }

    /// Percent point function (inverse CDF).
    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        // Accumulate the cdf term-by-term. pmf(k) = p^k / (k·norm); carry p^k
        // incrementally (pk *= p) instead of a powf per step — the mass is a
        // streaming sum so it must stay sequential, but each term is now ~1 mul.
        let norm = self.norm();
        let mut sum = 0.0;
        let mut k: u64 = 1;
        let mut pk = self.p; // p^k, starting at p^1
        loop {
            sum += pk / (k as f64 * norm);
            if sum >= q || k >= 1_000_000 {
                return k as f64;
            }
            k += 1;
            pk *= self.p;
        }
    }
}

impl DiscreteDistribution for LogSeries {
    fn pmf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        self.p.powf(k as f64) / (k as f64 * self.norm())
    }

    fn logpmf(&self, k: u64) -> f64 {
        // k·ln(p) − ln(k) − ln(norm); finite where pmf underflows. frankenscipy-7m3xk
        if k == 0 {
            return f64::NEG_INFINITY;
        }
        k as f64 * self.p.ln() - (k as f64).ln() - self.norm().ln()
    }

    fn cdf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        let norm = self.norm();
        // Stream the p^i factor (term *= p) instead of a fresh `p.powf(i)` per
        // term — a `powf` (~15-25ns) → one multiply per iteration, ~15× cheaper
        // over this O(k) sum (and the ppf that bisects over it). `term = p^i`.
        let mut sum = 0.0;
        let mut term = self.p; // p^1
        for i in 1..=k {
            sum += term / (i as f64 * norm);
            term *= self.p;
        }
        sum.min(1.0)
    }

    fn mean(&self) -> f64 {
        self.p / ((1.0 - self.p) * self.norm())
    }

    fn var(&self) -> f64 {
        let norm = self.norm();
        self.p * (norm - self.p) / ((1.0 - self.p).powi(2) * norm * norm)
    }

    fn skewness(&self) -> f64 {
        // Raw moments via differentiating the MGF (scipy.stats.logser._stats):
        //   m_1 = p / ((p − 1) r)
        //   m_2 = −p / (r (p − 1)²)
        //   m_3 = −p (1 + p) / (r (1 − p)³)
        //   m_4 = −p (1/(p−1)² − 6p/(p−1)³ + 6p²/(p−1)⁴) / r
        // where r = ln(1 − p). Compose central moments and standardize.
        let (p, r) = (self.p, (1.0 - self.p).ln());
        let pm1 = p - 1.0;
        let omp = 1.0 - p;
        let m1 = p / (pm1 * r);
        let m2 = -p / (r * pm1 * pm1);
        let m3 = -p * (1.0 + p) / (r * omp.powi(3));
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let (p, r) = (self.p, (1.0 - self.p).ln());
        let pm1 = p - 1.0;
        let omp = 1.0 - p;
        let m1 = p / (pm1 * r);
        let m2 = -p / (r * pm1 * pm1);
        let m3 = -p * (1.0 + p) / (r * omp.powi(3));
        let m4 = -p * (1.0 / (pm1 * pm1) - 6.0 * p / pm1.powi(3) + 6.0 * p * p / pm1.powi(4)) / r;
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        1.0
    }

    fn entropy(&self) -> f64 {
        // LogSeries pmf = p^k / (k · −ln(1−p)). Sum on k = 1.. until the
        // running tail probability falls below f64 round-off.
        let mut h = 0.0_f64;
        let mut tail = 1.0_f64;
        let max_k: u64 = 1_000_000;
        for k in 1..=max_k {
            let p_k = self.pmf(k);
            if p_k > 0.0 {
                h -= p_k * p_k.ln();
                tail -= p_k;
            }
            if k > 32 && tail < 1e-15 {
                break;
            }
        }
        h
    }
}

/// Discrete uniform distribution over integers in `[low, high)`.
///
/// Matches `scipy.stats.randint(low, high)`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RandInt {
    pub low: i64,
    pub high: i64,
}

impl RandInt {
    #[must_use]
    pub fn new(low: i64, high: i64) -> Self {
        assert!(high > low, "high must be greater than low");
        Self { low, high }
    }

    fn width(&self) -> i64 {
        self.high - self.low
    }

    pub fn pmf(&self, k: i64) -> f64 {
        if (self.low..self.high).contains(&k) {
            1.0 / self.width() as f64
        } else {
            0.0
        }
    }

    pub fn cdf(&self, k: i64) -> f64 {
        if k < self.low {
            0.0
        } else if k >= self.high - 1 {
            1.0
        } else {
            (k - self.low + 1) as f64 / self.width() as f64
        }
    }

    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return (self.low - 1) as f64;
        }
        if q == 1.0 {
            return (self.high - 1) as f64;
        }

        (self.low + (q * self.width() as f64).ceil() as i64 - 1) as f64
    }

    pub fn mean(&self) -> f64 {
        self.low as f64 + (self.width() as f64 - 1.0) / 2.0
    }

    pub fn var(&self) -> f64 {
        let n = self.width() as f64;
        (n * n - 1.0) / 12.0
    }
}

/// Log of the Beta function: ln(B(a,b)) = ln(Γ(a)) + ln(Γ(b)) - ln(Γ(a+b))
fn ln_beta(a: f64, b: f64) -> f64 {
    ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b)
}

// ══════════════════════════════════════════════════════════════════════
// Internal Helper Functions
// ══════════════════════════════════════════════════════════════════════

/// Standard normal inverse CDF (Beasley-Springer-Moro algorithm).
fn standard_normal_ppf(p: f64) -> f64 {
    // SciPy's `scipy.stats.norm.ppf` delegates to `scipy.special.ndtri`.
    // Route through the same Cephes-style inverse so the deep tail matches
    // SciPy to machine precision: the old Wichura AS241 polynomial below was
    // off by ~1.8e-4 at p=1e-12 (q=ppf(1e-12) gave -7.03573 vs SciPy's
    // -7.03448). `ndtri_scalar` is bit-for-bit with `scipy.special.ndtri`
    // across the full tail (verified to ~2.5e-16 down to p=1e-300).
    if p <= 0.0 {
        return f64::NEG_INFINITY;
    }
    if p >= 1.0 {
        return f64::INFINITY;
    }
    fsci_special::ndtri_scalar(p)
}

/// Legacy Wichura (1988) AS241 rational approximation, retained for reference.
/// Superseded by `ndtri_scalar` routing in `standard_normal_ppf`; lower tail
/// accuracy (~1e-4 at p≈1e-12) made it disagree with SciPy.
#[allow(dead_code)]
fn standard_normal_ppf_as241(p: f64) -> f64 {
    // Rational approximation for the central region
    if p <= 0.0 {
        return f64::NEG_INFINITY;
    }
    if p >= 1.0 {
        return f64::INFINITY;
    }

    let q = p - 0.5;
    if q.abs() <= 0.425 {
        // Central region: |q| <= 0.425
        let r = 0.180_625 - q * q;
        let num = q
            * (((((((2.509_080_928_730_122_7e3 * r + 3.343_054_881_277_247_5e4) * r
                + 6.726_577_092_700_87e4)
                * r
                + 4.592_195_393_154_987e4)
                * r
                + 1.373_169_376_550_946e4)
                * r
                + 1.971_590_950_306_551_4e3)
                * r
                + 1.331_416_678_917_843_8e2)
                * r
                + 3.387_132_872_796_366_5);
        let den = ((((((5.226_495_278_852_854e3 * r + 2.872_908_573_572_194_3e4) * r
            + 3.930_789_580_009_271e4)
            * r
            + 2.121_379_430_158_993_7e4)
            * r
            + 5.394_196_021_424_751e3)
            * r
            + 6.871_870_741_484_02e2)
            * r
            + 4.231_333_070_160_091e1)
            * r
            + 1.0;
        return num / den;
    }

    // Tail region
    let r = if q < 0.0 { p } else { 1.0 - p };
    let r = (-r.ln()).sqrt();

    #[allow(clippy::excessive_precision)]
    let result = if r <= 5.0 {
        // Wichura (1988) AS241 coefficients for intermediate tail region
        let r = r - 1.6;
        let num = ((((((7.745_450_142_772_702_5e-4 * r + 2.272_388_412_100_731_05e-2) * r
            + 2.417_807_251_774_506_12e-1)
            * r
            + 1.270_458_252_452_368_38)
            * r
            + 3.647_848_324_763_204_60)
            * r
            + 5.769_497_221_460_691_41)
            * r
            + 4.630_337_846_156_545_30)
            * r
            + 1.423_437_110_749_683_58;
        let den = ((((((1.050_750_071_644_416_84e-9 * r + 5.475_938_084_995_344_95e-4) * r
            + 1.519_866_656_361_645_72e-2)
            * r
            + 1.481_039_764_274_800_75e-1)
            * r
            + 6.897_673_349_851_000_05e-1)
            * r
            + 1.676_384_830_183_803_8)
            * r
            + 2.053_191_626_637_759)
            * r
            + 1.0;
        num / den
    } else {
        let r = r - 5.0;
        let num = ((((((2.010_334_399_292_288_2e-7 * r + 2.711_555_568_743_487_6e-5) * r
            + 1.242_660_947_388_078_4e-3)
            * r
            + 2.653_218_952_657_612_4e-2)
            * r
            + 2.965_605_718_285_048_7e-1)
            * r
            + 1.784_826_539_917_291_3)
            * r
            + 5.463_784_911_164_114)
            * r
            + 6.657_904_643_501_103;
        let den = ((((((2.044_263_103_389_939_7e-15 * r + 1.421_511_758_316_446e-7) * r
            + 1.846_318_317_510_054_8e-5)
            * r
            + 7.868_691_311_456_133e-4)
            * r
            + 1.487_536_129_085_061_5e-2)
            * r
            + 1.369_298_809_227_358e-1)
            * r
            + 5.990_260_257_979_974e-1)
            * r
            + 1.0;
        num / den
    };

    if q < 0.0 { -result } else { result }
}

/// Gamma function ratio for Student's t PDF coefficient.
fn gamma_ratio_t(v: f64) -> f64 {
    // Γ((v+1)/2) / (sqrt(v*π) * Γ(v/2))
    let ln_coeff = ln_gamma(0.5 * (v + 1.0)) - ln_gamma(0.5 * v) - 0.5 * (v * PI).ln();
    ln_coeff.exp()
}

fn ln_gamma(x: f64) -> f64 {
    fsci_special::gammaln_scalar(x, RuntimeMode::Strict).unwrap_or(f64::NAN)
}

fn digamma(x: f64) -> f64 {
    fsci_special::digamma_scalar(x)
}

fn lower_regularized_gamma(a: f64, x: f64) -> f64 {
    fsci_special::gammainc_scalar(a, x, RuntimeMode::Strict).unwrap_or(f64::NAN)
}

fn upper_regularized_gamma(a: f64, x: f64) -> f64 {
    fsci_special::gammaincc_scalar(a, x, RuntimeMode::Strict).unwrap_or(f64::NAN)
}

fn regularized_incomplete_beta(a: f64, b: f64, x: f64) -> f64 {
    fsci_special::betainc_scalar(a, b, x, RuntimeMode::Strict).unwrap_or(f64::NAN)
}

fn modified_bessel_i(order: f64, x: f64) -> f64 {
    match fsci_special::iv(
        &fsci_special::SpecialTensor::RealScalar(order),
        &fsci_special::SpecialTensor::RealScalar(x),
        RuntimeMode::Strict,
    ) {
        Ok(fsci_special::SpecialTensor::RealScalar(value)) => value,
        _ => f64::NAN,
    }
}

fn modified_bessel_k(order: f64, x: f64) -> f64 {
    match fsci_special::kv(
        &fsci_special::SpecialTensor::RealScalar(order),
        &fsci_special::SpecialTensor::RealScalar(x),
        RuntimeMode::Strict,
    ) {
        Ok(fsci_special::SpecialTensor::RealScalar(value)) => value,
        _ => f64::NAN,
    }
}

fn dot(a: &[f64], b: &[f64]) -> f64 {
    a.iter().zip(b.iter()).map(|(&x, &y)| x * y).sum()
}

fn matvec_mul(matrix: &[Vec<f64>], vector: &[f64]) -> Vec<f64> {
    matrix.iter().map(|row| dot(row, vector)).collect()
}

fn identity_matrix(n: usize) -> Vec<Vec<f64>> {
    let mut out = vec![vec![0.0; n]; n];
    for (i, row) in out.iter_mut().enumerate() {
        row[i] = 1.0;
    }
    out
}

fn covariance_biased(samples: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if samples.is_empty() {
        return Vec::new();
    }
    let n = samples.len();
    let dim = samples[0].len();
    let mut means = vec![0.0; dim];
    for sample in samples {
        for (j, &value) in sample.iter().enumerate() {
            means[j] += value;
        }
    }
    for mean in &mut means {
        *mean /= n as f64;
    }

    let mut cov = vec![vec![0.0; dim]; dim];
    for sample in samples {
        let centered: Vec<f64> = sample
            .iter()
            .zip(means.iter())
            .map(|(&x, &m)| x - m)
            .collect();
        for (i, row) in cov.iter_mut().enumerate() {
            for (j, value) in row.iter_mut().enumerate() {
                *value += centered[i] * centered[j];
            }
        }
    }
    for row in &mut cov {
        for value in row {
            *value /= n as f64;
        }
    }
    cov
}

fn jacobi_symmetric_eigendecomposition(a: &[Vec<f64>]) -> (Vec<f64>, Vec<Vec<f64>>) {
    let n = a.len();
    let mut matrix = a.to_vec();
    let mut eigenvectors = identity_matrix(n);
    if n == 0 {
        return (Vec::new(), Vec::new());
    }

    for _ in 0..(n * n * 32).max(32) {
        let mut p = 0;
        let mut q = 1.min(n.saturating_sub(1));
        let mut max_off = 0.0;
        for (i, row) in matrix.iter().enumerate() {
            for (j, value) in row.iter().enumerate().skip(i + 1) {
                if value.abs() > max_off {
                    max_off = value.abs();
                    p = i;
                    q = j;
                }
            }
        }
        if max_off < 1e-12 {
            break;
        }

        let app = matrix[p][p];
        let aqq = matrix[q][q];
        let apq = matrix[p][q];
        // apq is the max off-diagonal element (abs >= 1e-12 from convergence check),
        // but guard explicitly against pathological zero to prevent NaN propagation.
        if apq.abs() < f64::MIN_POSITIVE {
            break;
        }
        let tau = (aqq - app) / (2.0 * apq);
        let t = tau.signum() / (tau.abs() + (1.0 + tau * tau).sqrt());
        let c = 1.0 / (1.0 + t * t).sqrt();
        let s = t * c;

        for row in &mut matrix {
            let mkp = row[p];
            let mkq = row[q];
            row[p] = c * mkp - s * mkq;
            row[q] = s * mkp + c * mkq;
        }
        let row_p_old = matrix[p].clone();
        let row_q_old = matrix[q].clone();
        for (j, (&mpj, &mqj)) in row_p_old.iter().zip(row_q_old.iter()).enumerate() {
            matrix[p][j] = c * mpj - s * mqj;
            matrix[q][j] = s * mpj + c * mqj;
        }
        matrix[p][q] = 0.0;
        matrix[q][p] = 0.0;
        matrix[p][p] = c * c * app - 2.0 * s * c * apq + s * s * aqq;
        matrix[q][q] = s * s * app + 2.0 * s * c * apq + c * c * aqq;

        for row in &mut eigenvectors {
            let vkp = row[p];
            let vkq = row[q];
            row[p] = c * vkp - s * vkq;
            row[q] = s * vkp + c * vkq;
        }
    }

    let eigenvalues = matrix.iter().enumerate().map(|(i, row)| row[i]).collect();
    (eigenvalues, eigenvectors)
}

fn symmetric_pseudoinverse_and_rank(matrix: &[Vec<f64>]) -> (Vec<Vec<f64>>, usize) {
    let n = matrix.len();
    if n == 0 {
        return (Vec::new(), 0);
    }
    let (eigenvalues, eigenvectors) = jacobi_symmetric_eigendecomposition(matrix);
    let max_eigen = eigenvalues.iter().copied().fold(0.0_f64, |a, b| {
        if a.is_nan() || b.is_nan() {
            f64::NAN
        } else {
            a.max(b.abs())
        }
    });
    if max_eigen.is_nan() {
        return (vec![vec![f64::NAN; n]; n], 0);
    }
    let threshold = (n as f64) * f64::EPSILON * max_eigen.max(1.0);
    let mut pinv = vec![vec![0.0; n]; n];
    let mut rank = 0usize;
    for (idx, &eigenvalue) in eigenvalues.iter().enumerate() {
        if eigenvalue.abs() <= threshold {
            continue;
        }
        rank += 1;
        let inv = 1.0 / eigenvalue;
        for (i, row) in pinv.iter_mut().enumerate() {
            for (j, value) in row.iter_mut().enumerate() {
                *value += inv * eigenvectors[i][idx] * eigenvectors[j][idx];
            }
        }
    }
    (pinv, rank)
}

fn cholesky_decompose(matrix: &[Vec<f64>]) -> Result<Vec<Vec<f64>>, StatsError> {
    let n = matrix.len();
    let mut lower = vec![vec![0.0; n]; n];
    for i in 0..n {
        for j in 0..=i {
            let sum = (0..j).map(|k| lower[i][k] * lower[j][k]).sum::<f64>();
            if i == j {
                let value = matrix[i][i] - sum;
                if value <= 0.0 || !value.is_finite() {
                    return Err(StatsError::InvalidArgument(
                        "covariance matrix must be symmetric positive definite".to_string(),
                    ));
                }
                lower[i][j] = value.sqrt();
            } else {
                lower[i][j] = (matrix[i][j] - sum) / lower[j][j];
            }
        }
    }
    Ok(lower)
}

fn solve_lower_triangular(lower: &[Vec<f64>], rhs: &[f64]) -> Result<Vec<f64>, StatsError> {
    let n = lower.len();
    let mut solution = vec![0.0; n];
    for i in 0..n {
        let sum = (0..i).map(|j| lower[i][j] * solution[j]).sum::<f64>();
        if lower[i][i] == 0.0 {
            return Err(StatsError::InvalidArgument(
                "singular lower-triangular system".to_string(),
            ));
        }
        solution[i] = (rhs[i] - sum) / lower[i][i];
    }
    Ok(solution)
}

/// Frobenius² of `L⁻¹ · rhs` (both p×p, `L` lower-triangular), i.e.
/// `Σ_{i,j} (L⁻¹ rhs)[i][j]²`. Solves all p columns at once via a single
/// multi-RHS forward substitution (`acc[j] = Σ_{k<i} L[i][k]·W[k][j]`,
/// contiguous inner j-loop = axpy across RHS, auto-vectorized) instead of p
/// separate `solve_lower_triangular` calls. BYTE-IDENTICAL to the per-column
/// loop: `acc[j]` left-folds k in 0..i from 0.0 (same as `(0..i).map(..).sum()`),
/// and the trace is accumulated column-major to match `Σ_j ‖solve(L, col_j)‖²`
/// term-for-term. Replaces the gather/alloc/solve/‖·‖² loop used by the
/// Wishart / inverse-Wishart logpdf trace terms.
fn frob_sq_inv_chol_cols(l: &[Vec<f64>], rhs: &[Vec<f64>], p: usize) -> Result<f64, StatsError> {
    let mut w = vec![vec![0.0_f64; p]; p];
    let mut acc = vec![0.0_f64; p];
    for i in 0..p {
        let lii = l[i][i];
        if lii == 0.0 {
            return Err(StatsError::InvalidArgument(
                "singular lower-triangular system".to_string(),
            ));
        }
        for a in acc.iter_mut() {
            *a = 0.0;
        }
        for k in 0..i {
            let lik = l[i][k];
            let wk = &w[k];
            for (a, &wkj) in acc.iter_mut().zip(wk.iter()) {
                *a += lik * wkj;
            }
        }
        let wi = &mut w[i];
        for j in 0..p {
            wi[j] = (rhs[i][j] - acc[j]) / lii;
        }
    }
    let mut tr = 0.0_f64;
    // Column-wise sum of a row-major matrix: `j` is the INNER index across p
    // separate rows, so there is no one collection to iterate over.
    #[allow(clippy::needless_range_loop)]
    for j in 0..p {
        tr += (0..p).map(|i| w[i][j] * w[i][j]).sum::<f64>();
    }
    Ok(tr)
}

fn sample_standard_normals(n: usize, rng: &mut impl Rng) -> Vec<f64> {
    let mut values = Vec::with_capacity(n);
    while values.len() < n {
        let u1 = rng.random::<f64>().max(1e-15);
        let u2 = rng.random::<f64>();
        let radius = (-2.0 * u1.ln()).sqrt();
        let angle = 2.0 * PI * u2;
        values.push(radius * angle.cos());
        if values.len() < n {
            values.push(radius * angle.sin());
        }
    }
    values
}

// ══════════════════════════════════════════════════════════════════════
// Cauchy Distribution
// ══════════════════════════════════════════════════════════════════════

/// Cauchy distribution (Lorentzian) with location `loc` and scale `scale`.
///
/// Matches `scipy.stats.cauchy(loc, scale)`.
/// PDF: f(x) = 1 / (π * scale * (1 + ((x - loc)/scale)²))
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cauchy {
    pub loc: f64,
    pub scale: f64,
}

impl Default for Cauchy {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl Cauchy {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for Cauchy {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        1.0 / (PI * self.scale * (1.0 + z * z))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −ln(π) − ln(scale) − ln(1+z²); finite in the heavy tail. frankenscipy-p82v7
        let z = (x - self.loc) / self.scale;
        -PI.ln() - self.scale.ln() - (1.0 + z * z).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        // Closed-form symmetric to sf(): for x < loc the naive 0.5 + atan(z)/π
        // cancels (cdf → 0 as 0.5 + (−≈0.5)), losing all tail precision — ~2e-4
        // relative error by x ≈ loc − 1e12·scale, ~13% by 1e15·scale. The arctan
        // reciprocal identity gives the exact left tail cdf = atan(scale/(loc−x))/π
        // (loc − x > 0), matching scipy bit-for-bit. x ≥ loc keeps the direct form.
        let dz = x - self.loc;
        if dz < 0.0 {
            (self.scale / (self.loc - x)).atan() / PI
        } else {
            0.5 + (dz / self.scale).atan() / PI
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-ltdct]: for x > loc use
        // the arctan reciprocal identity arctan(z) = π/2 - arctan(1/z)
        // (z > 0) so sf = arctan(scale/(x-loc))/π. The default
        // 1 - cdf collapses to 0 in the very deep tail (x ≈ loc + 1e30·scale)
        // when cdf rounds to 1.0 — the closed form returns the actual value.
        let dz = x - self.loc;
        if dz > 0.0 {
            (self.scale / dz).atan() / PI
        } else {
            // For x <= loc, the default 1 - cdf works fine because cdf is
            // bounded away from 1; compute it explicitly.
            0.5 - (dz / self.scale).atan() / PI
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        if q == 0.5 {
            return self.loc;
        }
        // tan(π·(q−0.5)) is ill-conditioned near q→0/1 (argument near ±π/2):
        // a ~1e-16 error in the argument blows up through tan's diverging
        // derivative (ppf(1e-12) was 1.4e-5 off scipy). The reciprocal-tangent
        // identity tan(π·(q−0.5)) = ∓1/tan(π·min(q,1−q)) keeps the small angle
        // well-conditioned, matching scipy.stats.cauchy.ppf bit-for-bit.
        let z = if q < 0.5 {
            -1.0 / (PI * q).tan()
        } else {
            1.0 / (PI * (1.0 - q)).tan()
        };
        self.loc + self.scale * z
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        if q == 0.5 {
            return self.loc;
        }
        // isf(q) = ppf(1-q); computing 1-q first cancels for small q. Use the
        // reciprocal-tangent identity directly on q so the deep right tail
        // stays accurate (isf(1e-12) was 2.2e-5 off via the trait default).
        let z = if q < 0.5 {
            1.0 / (PI * q).tan()
        } else {
            -1.0 / (PI * (1.0 - q)).tan()
        };
        self.loc + self.scale * z
    }

    fn mean(&self) -> f64 {
        f64::NAN // Cauchy has no finite mean
    }

    fn var(&self) -> f64 {
        f64::NAN // Cauchy has no finite variance
    }

    fn skewness(&self) -> f64 {
        // Heavy 1/x² tails → all moments diverge. scipy reports NaN.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite()) {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }

        let qs = quantile(data, &[0.25, 0.5, 0.75]);
        let loc = qs[1];
        let scale = 0.5 * (qs[2] - qs[0]);
        if !loc.is_finite() || !scale.is_finite() || scale <= 0.0 {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }

        Self { loc, scale }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Cauchy requires finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.loc.is_finite() || !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "Cauchy fit produced non-finite or non-positive parameters (degenerate quantiles)"
                    .into(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        (4.0 * PI * self.scale).ln()
    }

    fn mode(&self) -> f64 {
        self.loc
    }
}

// ══════════════════════════════════════════════════════════════════════
// Laplace Distribution
// ══════════════════════════════════════════════════════════════════════

/// Laplace (double exponential) distribution.
///
/// Matches `scipy.stats.laplace(loc, scale)`.
/// PDF: f(x) = exp(-|x - loc|/scale) / (2 * scale)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Laplace {
    pub loc: f64,
    pub scale: f64,
}

impl Default for Laplace {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl Laplace {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive, got {scale}");
        Self { loc, scale }
    }
}

impl ContinuousDistribution for Laplace {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = ((x - self.loc) / self.scale).abs();
        (-z).exp() / (2.0 * self.scale)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −|z| − ln(2·scale); finite in the tail where pdf underflows. frankenscipy-p82v7
        let z = ((x - self.loc) / self.scale).abs();
        -z - (2.0 * self.scale).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        if z < 0.0 {
            0.5 * z.exp()
        } else {
            1.0 - 0.5 * (-z).exp()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-6uo0s]:
        //   z >= 0: sf = 0.5 · exp(-z)
        //   z < 0:  sf = 1 - 0.5 · exp(z)
        // The right tail (z >= 0) is the precision-sensitive case;
        // the default 1 - cdf computes 1 - (1 - 0.5·exp(-z)) and
        // catastrophically cancels when 0.5·exp(-z) drops below ULP.
        let z = (x - self.loc) / self.scale;
        if z >= 0.0 {
            0.5 * (-z).exp()
        } else {
            1.0 - 0.5 * z.exp()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        if q < 0.5 {
            self.loc + self.scale * (2.0 * q).ln()
        } else {
            self.loc - self.scale * (2.0 * (1.0 - q)).ln()
        }
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return f64::NEG_INFINITY;
        }
        // isf(q)=ppf(1−q); computing 1−q first cancels for small q. Use q
        // directly: right tail (q≤0.5) is loc − scale·ln(2q), no cancellation.
        // Matches scipy.stats.laplace.isf bit-for-bit. frankenscipy-d2gag
        if q <= 0.5 {
            self.loc - self.scale * (2.0 * q).ln()
        } else {
            self.loc + self.scale * (2.0 * (1.0 - q)).ln()
        }
    }

    fn mean(&self) -> f64 {
        self.loc
    }

    fn var(&self) -> f64 {
        2.0 * self.scale * self.scale
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() {
            return Self {
                loc: f64::NAN,
                scale: f64::NAN,
            };
        }
        let loc = median(data);
        let scale = data.iter().map(|&x| (x - loc).abs()).sum::<f64>() / data.len() as f64;
        Self {
            loc,
            scale: if scale > 0.0 { scale } else { f64::NAN },
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|v| !v.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Laplace::fit: non-finite samples".to_owned(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.scale.is_finite() || fitted.scale <= 0.0 {
            return Err(FitError::NonConvergent(
                "Laplace::fit: degenerate sample (all values equal median)".to_owned(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        1.0 + (2.0 * self.scale).ln()
    }

    fn skewness(&self) -> f64 {
        0.0 // Laplace is symmetric
    }

    fn kurtosis(&self) -> f64 {
        3.0 // Laplace excess kurtosis is 3
    }

    fn mode(&self) -> f64 {
        self.loc
    }
}

// ══════════════════════════════════════════════════════════════════════
// Triangular Distribution
// ══════════════════════════════════════════════════════════════════════

/// When `true`, [`Triangular`]'s `fit` runs its finite-check/min/max/Σ as four separate passes
/// (the ORIG behaviour); default `false` fuses them into one traversal. Byte-identical.
#[doc(hidden)]
pub static TRIANGULAR_FIT_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Triangular distribution on [left, right] with mode `mode`.
///
/// Matches `scipy.stats.triang(c, loc, scale)` where c=(mode-left)/(right-left).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Triangular {
    pub left: f64,
    pub mode: f64,
    pub right: f64,
}

impl Triangular {
    #[must_use]
    pub fn new(left: f64, mode: f64, right: f64) -> Self {
        // scipy.stats.triang allows c = 0 (mode at left edge) and
        // c = 1 (mode at right edge), so we need `left ≤ mode ≤ right`
        // with strict `left < right` to keep the support
        // non-degenerate. Caught by [frankenscipy-fkq6j] diff
        // harness — the previous `left < mode` panicked at c = 0.
        assert!(left < right, "left must be < right (degenerate support)");
        assert!(
            (left..=right).contains(&mode),
            "mode must be in [left, right]"
        );
        Self { left, mode, right }
    }
}

impl ContinuousDistribution for Triangular {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let (a, c, b) = (self.left, self.mode, self.right);
        if x < a || x > b {
            0.0
        } else if c == b {
            // Degenerate: right-skewed triangle (mode == right)
            if x == b {
                2.0 / (b - a)
            } else {
                2.0 * (x - a) / ((b - a) * (b - a))
            }
        } else if x < c {
            2.0 * (x - a) / ((b - a) * (c - a))
        } else if x == c {
            2.0 / (b - a)
        } else {
            2.0 * (b - x) / ((b - a) * (b - c))
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        let (a, c, b) = (self.left, self.mode, self.right);
        if x <= a {
            0.0
        } else if c == b {
            // Degenerate: mode == right
            if x >= b {
                1.0
            } else {
                (x - a).powi(2) / ((b - a) * (b - a))
            }
        } else if x <= c {
            (x - a).powi(2) / ((b - a) * (c - a))
        } else if x < b {
            1.0 - (b - x).powi(2) / ((b - a) * (b - c))
        } else {
            1.0
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.left;
        }
        if q == 1.0 {
            return self.right;
        }
        let (a, c, b) = (self.left, self.mode, self.right);
        let fc = (c - a) / (b - a);
        if q < fc {
            a + (q * (b - a) * (c - a)).sqrt()
        } else {
            b - ((1.0 - q) * (b - a) * (b - c)).sqrt()
        }
    }

    fn mean(&self) -> f64 {
        (self.left + self.mode + self.right) / 3.0
    }

    fn var(&self) -> f64 {
        let (a, c, b) = (self.left, self.mode, self.right);
        (a * a + b * b + c * c - a * b - a * c - b * c) / 18.0
    }

    fn skewness(&self) -> f64 {
        // Standardised parameter c = (mode − left) / (right − left); skew
        // is shift-and-scale invariant so the formula uses only c
        //   skew(c) = √2 · (2c − 1) · (c − 2) · (c + 1)
        //           / (5 · (c² − c + 1)^{3/2})
        // (frankenscipy-mrmul)
        let c = (self.mode - self.left) / (self.right - self.left);
        let denom_base = c * c - c + 1.0;
        std::f64::consts::SQRT_2 * (2.0 * c - 1.0) * (c - 2.0) * (c + 1.0)
            / (5.0 * denom_base.powf(1.5))
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis is the constant -3/5 (independent of mode
        // location and scale). (frankenscipy-mrmul)
        -3.0 / 5.0
    }

    fn mode(&self) -> f64 {
        // Triangular pdf peaks at the apex parameter `mode`
        // (frankenscipy-rt24d).
        self.mode
    }

    fn fit(data: &[f64]) -> Self {
        let nan = Self {
            left: f64::NAN,
            mode: f64::NAN,
            right: f64::NAN,
        };
        if data.len() < 3 {
            return nan;
        }
        let (left, right, sum, all_finite) =
            if TRIANGULAR_FIT_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
                // ORIG: four separate traversals (finite-check, min, max, sum).
                if data.iter().any(|v| !v.is_finite()) {
                    return nan;
                }
                (
                    data.iter().cloned().fold(f64::INFINITY, f64::min),
                    data.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
                    data.iter().sum::<f64>(),
                    true,
                )
            } else {
                // FUSED: finite-check + min + max + Σ in ONE pass. BYTE-IDENTICAL — Σ stays a
                // left-to-right `+=` from 0.0 (== iter().sum()), min/max use the same f64::min/max
                // (order-independent), and the finite guard is carried as a flag; if it trips we
                // return `nan` exactly as the original early-out would (partial min/max/Σ discarded).
                let mut left = f64::INFINITY;
                let mut right = f64::NEG_INFINITY;
                let mut sum = 0.0f64;
                let mut all_finite = true;
                for &v in data {
                    if !v.is_finite() {
                        all_finite = false;
                    }
                    left = f64::min(left, v);
                    right = f64::max(right, v);
                    sum += v;
                }
                (left, right, sum, all_finite)
            };
        if !all_finite || left >= right {
            return nan;
        }
        let n = data.len() as f64;
        let mean = sum / n;
        let mode = 3.0 * mean - left - right;
        let mode = mode.clamp(left, right);
        Self { left, mode, right }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // [frankenscipy-sf2ax]: typed-error counterpart to fit().
        if data.len() < 3 {
            return Err(FitError::InsufficientData {
                required: 3,
                actual: data.len(),
            });
        }
        if data.iter().any(|v| !v.is_finite()) {
            return Err(FitError::UnsupportedData(
                "Triangular requires finite samples".into(),
            ));
        }
        let fitted = Self::fit(data);
        if !fitted.left.is_finite() || !fitted.right.is_finite() || fitted.left >= fitted.right {
            return Err(FitError::NonConvergent(
                "Triangular fit produced degenerate (left >= right) bounds".into(),
            ));
        }
        Ok(fitted)
    }

    fn entropy(&self) -> f64 {
        // H(Triangular) = 0.5 + ln((right - left) / 2)
        // [frankenscipy-vngzr].
        0.5 + ((self.right - self.left) / 2.0).ln()
    }
}

/// Trapezoidal distribution on `[loc, loc + scale]` with flat top spanning
/// `[loc + c * scale, loc + d * scale]`.
///
/// Matches `scipy.stats.trapezoid(c, d, loc, scale)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Trapezoid {
    pub c: f64,
    pub d: f64,
    pub loc: f64,
    pub scale: f64,
}

impl Trapezoid {
    #[must_use]
    pub fn new(c: f64, d: f64, loc: f64, scale: f64) -> Self {
        assert!((0.0..=1.0).contains(&c), "c must be in [0, 1]");
        assert!((0.0..=1.0).contains(&d), "d must be in [0, 1]");
        assert!(d >= c, "d must be >= c");
        assert!(scale > 0.0, "scale must be positive");
        Self { c, d, loc, scale }
    }

    fn standard_moment(&self, n: usize) -> f64 {
        let c = self.c;
        let d = self.d;
        let den = 1.0 + d - c;
        let ab_term = c.powf((n + 1) as f64);
        let dc_term = if d == 0.0 {
            1.0
        } else if d < 1.0 {
            (d.powf((n + 2) as f64) - 1.0) / (d - 1.0)
        } else {
            (n + 2) as f64
        };
        2.0 * (dc_term - ab_term) / (den * (n as f64 + 1.0) * (n as f64 + 2.0))
    }
}

impl ContinuousDistribution for Trapezoid {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        if !(0.0..=1.0).contains(&z) {
            return 0.0;
        }
        let height = 2.0 / (1.0 + self.d - self.c);
        let standard_pdf = if z < self.c {
            height * z / self.c
        } else if z <= self.d {
            height
        } else {
            height * (1.0 - z) / (1.0 - self.d)
        };
        standard_pdf / self.scale
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = (x - self.loc) / self.scale;
        if z <= 0.0 {
            return 0.0;
        }
        if z >= 1.0 {
            return 1.0;
        }
        let den = 1.0 + self.d - self.c;
        if z < self.c {
            z * z / (self.c * den)
        } else if z <= self.d {
            (self.c + 2.0 * (z - self.c)) / den
        } else {
            1.0 - (1.0 - z).powi(2) / ((1.0 - self.d) * den)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.loc;
        }
        if q == 1.0 {
            return self.loc + self.scale;
        }
        let den = 1.0 + self.d - self.c;
        let qc = self.c / den;
        let qd = (2.0 * self.d - self.c) / den;
        let z = if q < qc {
            (q * self.c * den).sqrt()
        } else if q <= qd {
            0.5 * (q * den + self.c)
        } else {
            1.0 - ((1.0 - q) * (1.0 - self.d) * den).sqrt()
        };
        self.loc + self.scale * z
    }

    fn mean(&self) -> f64 {
        self.loc + self.scale * self.standard_moment(1)
    }

    fn var(&self) -> f64 {
        let ex = self.standard_moment(1);
        let ex2 = self.standard_moment(2);
        self.scale * self.scale * (ex2 - ex * ex)
    }

    fn entropy(&self) -> f64 {
        // Standardized form on z ∈ [0, 1] with plateau height
        // h = 2/(1 + d − c). Split E[−ln pdf] over rise [0, c], flat
        // [c, d], fall [d, 1]:
        //   rise contrib: h·c·(1 − 2·ln h)/4
        //   fall contrib: h·(1 − d)·(1 − 2·ln h)/4
        //   flat contrib: −h·(d − c)·ln h
        // Combined: h·[(1 − w)·(1 − 2·ln h)/4 − w·ln h] with w = d − c.
        // Adding the location/scale Jacobian ln(scale):
        let w = self.d - self.c;
        let pdf_h = 2.0 / (1.0 + w);
        let ln_h = pdf_h.ln();
        let std_entropy = pdf_h * ((1.0_f64 - w) * (1.0 - 2.0 * ln_h) / 4.0 - w * ln_h);
        std_entropy + self.scale.ln()
    }

    fn skewness(&self) -> f64 {
        // Standardized moments are loc/scale-invariant — compute in z.
        let m1 = self.standard_moment(1);
        let m2 = self.standard_moment(2);
        let m3 = self.standard_moment(3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.standard_moment(1);
        let m2 = self.standard_moment(2);
        let m3 = self.standard_moment(3);
        let m4 = self.standard_moment(4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }
}

