// ══════════════════════════════════════════════════════════════════════

/// Inverse Gamma distribution.
///
/// Matches `scipy.stats.invgamma`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct InverseGamma {
    pub a: f64, // shape
}

impl InverseGamma {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0, "shape parameter must be positive");
        Self { a }
    }

    /// Log-density at many points, hoisting `lnΓ(a)` out of the per-point loop.
    /// Byte-identical to mapping `logpdf` (kept as the last subtraction); x≤0 → −∞.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let lg = ln_gamma(a);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return f64::NEG_INFINITY;
            }
            (-a - 1.0) * x.ln() - 1.0 / x - lg
        })
    }

    /// Density at many points; hoists `Γ(a) = exp(lnΓ(a))` (the divisor) like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let gamma_a = ln_gamma(a).exp();
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return 0.0;
            }
            x.powf(-a - 1.0) * (-1.0 / x).exp() / gamma_a
        })
    }
}

impl ContinuousDistribution for InverseGamma {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let a = self.a;
        x.powf(-a - 1.0) * (-1.0 / x).exp() / ln_gamma(a).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // (−a−1)·ln(x) − 1/x − lnΓ(a); finite in both tails. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        (-self.a - 1.0) * x.ln() - 1.0 / x - ln_gamma(self.a)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // CDF = 1 - gammainc(a, 1/x) = gammaincc(a, 1/x)
        // Using upper regularized incomplete gamma
        upper_regularized_gamma(self.a, 1.0 / x)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − gammaincc(a, 1/x) = gammainc(a, 1/x) = P(a, 1/x). The lower
        // regularized form →0 accurately as x→∞ instead of 1−cdf collapsing
        // (invgamma(2).sf(1e8) scipy 5e-17). frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        lower_regularized_gamma(self.a, 1.0 / x)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log P(a, 1/x); finite in the right tail where P underflows to 0. frankenscipy-s14mf
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammainc_scalar(self.a, 1.0 / x)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = Q(a, 1/x) = 1 - P(a, 1/x), so P(a, 1/x) = 1 - q
        // 1/x = gammaincinv(a, 1 - q), x = 1 / gammaincinv(a, 1 - q)
        let g = fsci_special::gammaincinv_scalar(self.a, 1.0 - q);
        if g <= 0.0 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        let mut x = 1.0 / g;
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // isf(q)=ppf(1−q): 1/x = gammaincinv(a, 1−(1−q)) = gammaincinv(a, q).
        // Seeding with gammaincinv(a, q) directly avoids the trait default's
        // 1−q cancellation (isf(1e-12) was ~1.9e-6 off), then Newton-refine on
        // the accurate sf. Matches scipy.stats.invgauss.isf. frankenscipy-d2gag
        let g = fsci_special::gammaincinv_scalar(self.a, q);
        if g <= 0.0 {
            return isf_bisection(|v| self.sf(v), q, self.mean(), self.std());
        }
        let mut x = 1.0 / g;
        for _ in 0..8 {
            let err = self.sf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                // sf decreasing: d(sf)/dx = −pdf, so x += err/pdf.
                x = (x + err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        if self.a > 1.0 {
            1.0 / (self.a - 1.0)
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        if self.a > 2.0 {
            1.0 / ((self.a - 1.0).powi(2) * (self.a - 2.0))
        } else {
            f64::INFINITY
        }
    }

    fn skewness(&self) -> f64 {
        // 4·√(a − 2) / (a − 3) for a > 3 (frankenscipy-d4j8j).
        if self.a > 3.0 {
            4.0 * (self.a - 2.0).sqrt() / (self.a - 3.0)
        } else {
            f64::NAN
        }
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 6(5a − 11) / ((a − 3)(a − 4))  for a > 4.
        // (frankenscipy-d4j8j)
        if self.a > 4.0 {
            6.0 * (5.0 * self.a - 11.0) / ((self.a - 3.0) * (self.a - 4.0))
        } else {
            f64::NAN
        }
    }

    fn entropy(&self) -> f64 {
        // h(InverseGamma(a)) = a + ln Γ(a) − (1 + a) ψ(a).
        self.a + ln_gamma(self.a) - (1.0 + self.a) * fsci_special::digamma_scalar(self.a)
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // MoM at unit scale: E[X | a] = 1/(a-1) for a>1, so
        //   a_hat = 1 + 1/sample_mean
        // Requires positive observations and a positive (>1) result.
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "InverseGamma data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "InverseGamma support is (0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 0.0 || !mean.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "InverseGamma MoM: sample mean {mean} non-positive"
            )));
        }
        let a = 1.0 + 1.0 / mean;
        if !a.is_finite() || a <= 1.0 {
            return Err(FitError::NonConvergent(format!(
                "InverseGamma MoM produced a={a} (must be > 1)"
            )));
        }
        Ok(Self { a })
    }

    fn mode(&self) -> f64 {
        // InverseGamma mode = scale / (a + 1); fsci-stats uses unit scale,
        // so mode = 1 / (a + 1) [frankenscipy-71mv5].
        1.0 / (self.a + 1.0)
    }
}

// Log-normal distribution (parameterized by mu, sigma of underlying normal).
//
// Note: The Lognormal struct above uses s/scale. This is an alias with
// the same interface. Kept for disambiguation.

/// Inverse Gaussian (Wald) distribution.
///
/// Matches `scipy.stats.invgauss`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct InverseGaussian {
    pub mu: f64, // mean
}

impl InverseGaussian {
    #[must_use]
    pub fn new(mu: f64) -> Self {
        assert!(mu > 0.0, "mu must be positive");
        Self { mu }
    }
}

impl ContinuousDistribution for InverseGaussian {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let mu = self.mu;
        (1.0 / (2.0 * PI * x.powi(3))).sqrt() * (-(x - mu).powi(2) / (2.0 * mu * mu * x)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −½ln(2π x³) − (x−μ)²/(2μ²x); closed form keeps the tail finite where
        // the default ln(pdf) underflows (exp → 0 by x≈370). frankenscipy.
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let mu = self.mu;
        -0.5 * ((2.0 * PI).ln() + 3.0 * x.ln()) - (x - mu).powi(2) / (2.0 * mu * mu * x)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let mu = self.mu;
        let sqrt_x = x.sqrt();
        let t1 = standard_normal_cdf(sqrt_x / mu - 1.0 / sqrt_x);
        let t2 = (2.0 / mu).exp() * standard_normal_cdf(-(sqrt_x / mu + 1.0 / sqrt_x));
        t1 + t2
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Φ(−(√x/μ − 1/√x)) − e^{2/μ}·Φ(−(√x/μ + 1/√x)); evaluating the
        // small upper-normal tail directly avoids the t1→1 rounding the default
        // 1−cdf suffers deep in the right tail. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let mu = self.mu;
        let sqrt_x = x.sqrt();
        let t1 = standard_normal_cdf(-(sqrt_x / mu - 1.0 / sqrt_x));
        let t2 = (2.0 / mu).exp() * standard_normal_cdf(-(sqrt_x / mu + 1.0 / sqrt_x));
        (t1 - t2).max(0.0)
    }

    fn mean(&self) -> f64 {
        self.mu
    }

    fn var(&self) -> f64 {
        self.mu.powi(3)
    }

    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // No closed-form inverse. The trait default routes ppf(1−q), inverting
        // the cdf where it is flat (≈1) near the right tail — ill-conditioned,
        // ~1.9e-6 off scipy at q=1e-12. Invert the steep, accurate sf instead
        // (sf well away from 0/1 there), then Newton-polish. frankenscipy-d2gag
        let mut x = isf_bisection(|v| self.sf(v), q, self.mean(), self.std());
        for _ in 0..8 {
            let err = self.sf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                // sf decreasing: d(sf)/dx = −pdf, so x += err/pdf.
                x = (x + err / dx).max(0.0);
            }
        }
        x
    }

    fn skewness(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-ggikd]:
        // scipy.stats.invgauss reports skew = 3·√mu.
        3.0 * self.mu.sqrt()
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-ggikd]:
        // scipy.stats.invgauss reports excess kurtosis = 15·mu.
        15.0 * self.mu
    }

    fn entropy(&self) -> f64 {
        // InverseGaussian pdf has a 1/√(2π x³) factor near x = 0.
        // Substitute u = ln x ∈ ℝ so dx = e^u du. The change-of-variable
        // identity h(X) = −∫ pdf_X(x)·ln pdf_X(x) dx becomes
        //   h(X) = −∫ pdf_X(e^u)·ln pdf_X(e^u) · e^u du
        // and the e^u factor turns the singular x → 0 region into a
        // tractable u → −∞ tail (handled by the integration window).
        simpson_integrate_adaptive(
            |u| {
                let x = u.exp();
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() * x } else { 0.0 }
            },
            -30.0,
            30.0,
            4_096,
            1e-11,
            1e-11,
            10,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // The standardized scipy.stats.invgauss has implicit λ=1, so its
        // single shape parameter `mu` is also the population mean. The MLE
        // collapses to the sample mean: mu_hat = (1/n) Σ x_i.
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "InverseGaussian data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "InverseGaussian support is (0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mu = sum / count as f64;
        if !mu.is_finite() || mu <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "InverseGaussian MLE produced non-positive mu: {mu}"
            )));
        }
        Ok(Self { mu })
    }
}

/// Pearson type III distribution.
///
/// Matches `scipy.stats.pearson3`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Pearson3 {
    pub skew: f64,
}

impl Pearson3 {
    #[must_use]
    pub fn new(skew: f64) -> Self {
        assert!(skew.is_finite(), "skew must be finite");
        Self { skew }
    }
}

impl ContinuousDistribution for Pearson3 {
    fn pdf(&self, x: f64) -> f64 {
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return standard_normal_pdf(x);
        }

        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);
        if transx < 0.0 {
            return 0.0;
        }

        beta.abs() * transx.powf(alpha - 1.0) * (-transx).exp() / ln_gamma(alpha).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            // Standard normal: ln pdf = -x^2/2 - ln(sqrt(2pi)).
            return -0.5 * x * x - 0.5 * (2.0 * PI).ln();
        }
        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);
        if transx <= 0.0 {
            return f64::NEG_INFINITY;
        }
        // pdf = |beta|*transx^(alpha-1)*exp(-transx)/gamma(alpha). The default
        // logpdf = ln(pdf) returns -inf once pdf underflows to 0 in the tail
        // (e.g. pearson3(0.5).pdf(1000)=0 but scipy logpdf=-3918). Evaluate the
        // log directly so it stays finite.
        beta.abs().ln() + (alpha - 1.0) * transx.ln() - transx - ln_gamma(alpha)
    }

    fn cdf(&self, x: f64) -> f64 {
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return standard_normal_cdf(x);
        }

        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);

        if skew > 0.0 {
            if transx <= 0.0 {
                0.0
            } else {
                lower_regularized_gamma(alpha, transx)
            }
        } else if transx <= 0.0 {
            1.0
        } else {
            upper_regularized_gamma(alpha, transx)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Survival mirrors the gamma-tail cdf branches but uses the
        // complementary regularized gamma so the far tail stays accurate
        // instead of collapsing under 1−cdf. frankenscipy-w3f6m
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return 0.5 * fsci_special::erfc_scalar(x * FRAC_1_SQRT_2);
        }
        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);
        if skew > 0.0 {
            if transx <= 0.0 {
                1.0
            } else {
                upper_regularized_gamma(alpha, transx)
            }
        } else if transx <= 0.0 {
            0.0
        } else {
            lower_regularized_gamma(alpha, transx)
        }
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log of the gamma-tail cdf branches; finite where P/Q underflow. frankenscipy-osnge
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return fsci_special::log_ndtr_scalar(x);
        }
        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);
        if skew > 0.0 {
            if transx <= 0.0 {
                f64::NEG_INFINITY
            } else {
                fsci_special::log_gammainc_scalar(alpha, transx)
            }
        } else if transx <= 0.0 {
            0.0
        } else {
            fsci_special::log_gammaincc_scalar(alpha, transx)
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // log of the gamma-tail sf branches; finite where P/Q underflow. frankenscipy-osnge
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return fsci_special::log_ndtr_scalar(-x);
        }
        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let transx = beta * (x - zeta);
        if skew > 0.0 {
            if transx <= 0.0 {
                0.0
            } else {
                fsci_special::log_gammaincc_scalar(alpha, transx)
            }
        } else if transx <= 0.0 {
            f64::NEG_INFINITY
        } else {
            fsci_special::log_gammainc_scalar(alpha, transx)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        const NORMAL_TRANSITION: f64 = 1.6e-5;
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        let skew = self.skew;
        if skew.abs() < NORMAL_TRANSITION {
            return fsci_special::ndtri_scalar(q);
        }

        let beta = 2.0 / skew;
        let alpha = beta * beta;
        let zeta = -beta;
        let gamma_q = if beta < 0.0 { 1.0 - q } else { q };
        let g = fsci_special::gammaincinv_scalar(alpha, gamma_q);
        if !g.is_finite() {
            return ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std());
        }
        g / beta + zeta
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        1.0
    }

    fn skewness(&self) -> f64 {
        // Pearson3 is parameterised by its skewness directly.
        // (frankenscipy-okk7z)
        self.skew
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis = 1.5·skew² (Pearson3 is a shifted/scaled
        // Gamma where shape k = 4/skew²; kurt = 6/k = 6·skew²/4 = 1.5·skew²).
        // (frankenscipy-okk7z)
        1.5 * self.skew * self.skew
    }

    fn entropy(&self) -> f64 {
        // Pearson3(skew) = sign(skew) · Gamma(α = 4/skew², scale = |skew|/2)
        // shifted by −2·sign(skew)/|skew|. Shifts and reflections preserve
        // differential entropy, so h(Pearson3) equals h(Gamma(α, scale)):
        //   h = α + ln Γ(α) + (1 − α) ψ(α) + ln(scale).
        if self.skew.abs() < 1.6e-5 {
            // Normal limit: h(N(0, 1)) = (1/2) ln(2πe).
            return 0.5 * (2.0 * PI * std::f64::consts::E).ln();
        }
        let alpha = 4.0 / (self.skew * self.skew);
        let scale = self.skew.abs() / 2.0;
        alpha + ln_gamma(alpha) + (1.0 - alpha) * fsci_special::digamma_scalar(alpha) + scale.ln()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 3 {
            return Err(FitError::InsufficientData {
                required: 3,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Pearson3 data contains non-finite value: {x}"
                )));
            }
        }
        // Method-of-moments skewness estimator g₁ = m₃ / m₂^1.5,
        // where m_k is the k-th central moment. Pearson3 in this crate
        // is the standardized form (loc=0, scale=1), so its single shape
        // parameter is the skewness — and the natural estimator is
        // exactly the sample skewness.
        let n = data.len() as f64;
        let mean: f64 = data.iter().sum::<f64>() / n;
        let mut m2 = 0.0_f64;
        let mut m3 = 0.0_f64;
        for &x in data {
            let d = x - mean;
            m2 += d * d;
            m3 += d * d * d;
        }
        m2 /= n;
        m3 /= n;
        if !m2.is_finite() || m2 <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "Pearson3 fit: sample variance {m2} is non-positive"
            )));
        }
        let skew = m3 / m2.powf(1.5);
        if !skew.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Pearson3 fit: skew estimate {skew} is non-finite"
            )));
        }
        Ok(Self { skew })
    }
}

/// Exponentially modified normal distribution.
///
/// Matches `scipy.stats.exponnorm`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ExponNorm {
    pub k: f64,
}

impl ExponNorm {
    #[must_use]
    pub fn new(k: f64) -> Self {
        assert!(k.is_finite() && k > 0.0, "k must be positive and finite");
        Self { k }
    }
}

impl ContinuousDistribution for ExponNorm {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let inv_k = 1.0 / self.k;
        let exp_arg = inv_k * (0.5 * inv_k - x);
        (exp_arg + fsci_special::log_ndtr_scalar(x - inv_k)).exp() / self.k
    }

    fn logpdf(&self, x: f64) -> f64 {
        // exp_arg + logΦ(x−1/k) − ln(k); finite in the tail. frankenscipy-p82v7
        let inv_k = 1.0 / self.k;
        let exp_arg = inv_k * (0.5 * inv_k - x);
        exp_arg + fsci_special::log_ndtr_scalar(x - inv_k) - self.k.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let inv_k = 1.0 / self.k;
        let exp_arg = inv_k * (0.5 * inv_k - x);
        standard_normal_cdf(x) - (exp_arg + fsci_special::log_ndtr_scalar(x - inv_k)).exp()
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − [Φ(x) − e^{exp_arg}Φ(x−1/k)] = Φ(−x) + e^{exp_arg}Φ(x−1/k);
        // the exponential-component term keeps the right tail accurate where
        // the default 1−cdf collapses to 0. frankenscipy-w3f6m
        let inv_k = 1.0 / self.k;
        let exp_arg = inv_k * (0.5 * inv_k - x);
        standard_normal_cdf(-x) + (exp_arg + fsci_special::log_ndtr_scalar(x - inv_k)).exp()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std())
    }

    fn mean(&self) -> f64 {
        self.k
    }

    fn var(&self) -> f64 {
        1.0 + self.k * self.k
    }

    fn skewness(&self) -> f64 {
        // EMG / ExponNorm: skew = 2·K³ / (1 + K²)^{3/2}.
        // (frankenscipy-u65lx)
        let k = self.k;
        let k2 = k * k;
        2.0 * k2 * k / (1.0 + k2).powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 6·K⁴ / (1 + K²)². (frankenscipy-u65lx)
        let k2 = self.k * self.k;
        let one_plus = 1.0 + k2;
        6.0 * k2 * k2 / (one_plus * one_plus)
    }

    fn entropy(&self) -> f64 {
        // ExponNorm (exponentially modified gaussian) has gaussian
        // left tail and exponential right tail. Use the location/scale
        // form X = Z + K·Y (Z ~ N(0,1), Y ~ Exp(1)) and integrate over
        // [−20, 20 + 30K] so the K=3 case still has 30K = 90 panels of
        // exponential tail at rate 1/K = 1/3 (exp(-30) ≈ 1e-13).
        let upper = 20.0_f64 + 30.0 * self.k;
        simpson_integrate_adaptive(
            |x| {
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            -20.0,
            upper,
            8_192,
            1e-12,
            1e-12,
            12,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "ExponNorm data contains non-finite value: {x}"
                )));
            }
        }
        // ExponNorm at standardized (loc=0, scale=1) has E[X] = k, so the
        // method-of-moments shape estimator is just the sample mean. The
        // shape parameter must be positive — reject non-positive means.
        let mean: f64 = data.iter().sum::<f64>() / data.len() as f64;
        if mean <= 0.0 || !mean.is_finite() {
            return Err(FitError::UnsupportedData(format!(
                "ExponNorm requires positive sample mean (k > 0); got {mean}"
            )));
        }
        Ok(Self { k: mean })
    }
}

/// Power normal distribution.
///
/// Matches `scipy.stats.powernorm`.
pub struct PowerNorm {
    pub c: f64,
}

impl PowerNorm {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c.is_finite() && c > 0.0, "c must be positive and finite");
        Self { c }
    }

    fn log_sf(&self, x: f64) -> f64 {
        self.c * fsci_special::log_ndtr_scalar(-x)
    }

    fn raw_moment(&self, order: i32) -> f64 {
        if (self.c - 1.0).abs() < 1e-12 {
            // c = 1 reduces to standard normal: m_1 = 0, m_2 = 1,
            // m_3 = 0, m_4 = 3.
            return match order {
                1 | 3 => 0.0,
                2 => 1.0,
                4 => 3.0,
                _ => f64::NAN,
            };
        }

        // /mock-code-finder boundary: at c < 1 the right tail is
        // heavier than Φ, so ppf(1 − 1e-12) underflows when the inner
        // ((1−q).ln()/c).exp() drops below the smallest probability
        // ndtri accepts — ppf returns +∞ and the integration NaNs out.
        // Fall back to a finite cap on either bound so quadrature
        // stays well-defined for all c > 0.
        let eps = 1e-12;
        let fallback = 50.0;
        let raw_lo = self.ppf(eps);
        let raw_hi = self.ppf(1.0 - eps);
        let lo = if raw_lo.is_finite() {
            raw_lo
        } else {
            -fallback
        };
        let hi = if raw_hi.is_finite() { raw_hi } else { fallback };
        simpson_integrate_adaptive(
            |x| x.powi(order) * self.pdf(x),
            lo,
            hi,
            4_096,
            1e-10,
            1e-10,
            8,
        )
    }
}

impl ContinuousDistribution for PowerNorm {
    fn pdf(&self, x: f64) -> f64 {
        (self.c.ln() - 0.5 * x * x - 0.5 * (2.0 * PI).ln()
            + (self.c - 1.0) * fsci_special::log_ndtr_scalar(-x))
        .exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) − ½x² − ½ln(2π) + (c−1)·logΦ(−x); finite in the tail. frankenscipy-p82v7
        self.c.ln() - 0.5 * x * x - 0.5 * (2.0 * PI).ln()
            + (self.c - 1.0) * fsci_special::log_ndtr_scalar(-x)
    }

    fn cdf(&self, x: f64) -> f64 {
        -self.log_sf(x).exp_m1()
    }

    fn sf(&self, x: f64) -> f64 {
        // cdf = −expm1(log_sf), so sf = exp(log_sf) directly — keeps the right
        // tail accurate where the default 1−cdf collapses to 0. frankenscipy-w3f6m
        self.log_sf(x).exp()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        -fsci_special::ndtri_scalar(((1.0 - q).ln() / self.c).exp())
    }

    fn mean(&self) -> f64 {
        self.raw_moment(1)
    }

    fn var(&self) -> f64 {
        let mean = self.mean();
        (self.raw_moment(2) - mean * mean).max(0.0)
    }

    fn skewness(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let m4 = self.raw_moment(4);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // PowerNorm: gaussian-like tails; use arctan to handle both
        // sides uniformly when c < 1 spreads the right tail further.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            -PI / 2.0 + 1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

/// Power-lognormal distribution with shapes `c > 0`, `s > 0`.
///
/// Matches `scipy.stats.powerlognorm(c, s)`. Resolves [frankenscipy-bx7kx].
/// Support: x > 0.
///
///   pdf(x; c, s) = c · φ(ln x / s) · Φ(−ln x / s)^(c − 1) / (x · s)
///   cdf(x; c, s) = 1 − Φ(−ln x / s)^c
///   sf(x;  c, s) = Φ(−ln x / s)^c
///   ppf(q; c, s) = exp(−s · Φ⁻¹((1 − q)^(1/c)))
///
/// where φ, Φ are the standard normal pdf and cdf.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PowerLognorm {
    pub c: f64,
    pub s: f64,
}

impl PowerLognorm {
    #[must_use]
    pub fn new(c: f64, s: f64) -> Self {
        assert!(
            c > 0.0 && c.is_finite() && s > 0.0 && s.is_finite(),
            "c and s must be positive and finite"
        );
        Self { c, s }
    }
}

impl ContinuousDistribution for PowerLognorm {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 || !x.is_finite() {
            return 0.0;
        }
        let c = self.c;
        let s = self.s;
        let z = x.ln() / s;
        let phi = standard_normal_pdf(z);
        // Deep-tail guard: φ(z) underflows to 0 for |z| > ~38.
        // For c < 1, Φ(−z)^(c−1) = 0^negative = +∞, and 0 · +∞ = NaN.
        // The pdf is effectively 0 there — return that directly.
        if phi == 0.0 {
            return 0.0;
        }
        let big_phi_neg = standard_normal_cdf(-z);
        c * phi * big_phi_neg.powf(c - 1.0) / (x * s)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) + lnφ(z) + (c−1)·logΦ(−z) − ln(x) − ln(s), z = ln(x)/s; the
        // log-space form stays finite where φ underflows. frankenscipy-p82v7
        if x <= 0.0 || !x.is_finite() {
            return f64::NEG_INFINITY;
        }
        let z = x.ln() / self.s;
        self.c.ln() - 0.5 * z * z - 0.5 * (2.0 * PI).ln()
            + (self.c - 1.0) * fsci_special::log_ndtr_scalar(-z)
            - x.ln()
            - self.s.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if !x.is_finite() {
            return 1.0;
        }
        let c = self.c;
        let s = self.s;
        let z = x.ln() / s;
        let big_phi_neg = standard_normal_cdf(-z);
        if big_phi_neg <= 0.5 {
            // Φ(−z) is small (x ≥ median region): the literal
            // 1 − Φ(−z)^c is precise because we're subtracting
            // something small from 1.
            (1.0 - big_phi_neg.powf(c)).clamp(0.0, 1.0)
        } else {
            // Φ(−z) is close to 1 (x < median region): the
            // literal form catastrophically cancels. Use the
            // stable rewrite via ln_1p / expm1:
            //   1 − Φ(−z)^c = −expm1(c · ln_1p(−Φ(z)))
            // (caught by [frankenscipy-evspb] fuzz: cdf became
            // non-monotone at c=1, s=1, x ≈ 1e-3; and
            // cdf + sf = 1.01 at c=0.1, s=0.1, x=2.5 in the
            // wrong regime).
            let big_phi_z = standard_normal_cdf(z);
            let log_term = (-big_phi_z).ln_1p();
            (-(c * log_term).exp_m1()).clamp(0.0, 1.0)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        if !x.is_finite() {
            return 0.0;
        }
        let c = self.c;
        let s = self.s;
        let z = x.ln() / s;
        standard_normal_cdf(-z).powf(c).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let c = self.c;
        let s = self.s;
        // x = exp(−s · Φ⁻¹((1 − q)^(1/c)))
        let inner = (1.0 - q).powf(1.0 / c);
        (-s * standard_normal_ppf(inner)).exp()
    }

    fn mean(&self) -> f64 {
        powerlognorm_moment(self.c, self.s, 1)
    }

    fn var(&self) -> f64 {
        let m1 = powerlognorm_moment(self.c, self.s, 1);
        let m2 = powerlognorm_moment(self.c, self.s, 2);
        let v = m2 - m1 * m1;
        if v.is_finite() && v >= 0.0 {
            v
        } else {
            f64::NAN
        }
    }

    fn skewness(&self) -> f64 {
        let m1 = powerlognorm_moment(self.c, self.s, 1);
        let m2 = powerlognorm_moment(self.c, self.s, 2);
        let m3 = powerlognorm_moment(self.c, self.s, 3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = powerlognorm_moment(self.c, self.s, 1);
        let m2 = powerlognorm_moment(self.c, self.s, 2);
        let m3 = powerlognorm_moment(self.c, self.s, 3);
        let m4 = powerlognorm_moment(self.c, self.s, 4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // PowerLognorm: support (0, ∞) with long log-normal tail.
        // arctan compactification keeps integrand bounded.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() || x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 4, "PowerLognorm")?;
        for &x in data {
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "PowerLognorm support is (0, infinity); got {x}"
                )));
            }
        }

        let qs = quantile(data, &[0.25, 0.5, 0.75]);
        let spread = qs[2] - qs[0];
        if !spread.is_finite() || spread <= 0.0 || qs[1] <= 0.0 {
            return Err(FitError::NonConvergent(
                "PowerLognorm fit needs positive non-degenerate quartiles".to_owned(),
            ));
        }

        let mut best = None::<(f64, f64, f64)>;
        for step in 0..=990 {
            let c = 0.1 + 0.01 * step as f64;
            let inner50 = 0.5_f64.powf(1.0 / c);
            let z50 = standard_normal_ppf(inner50);
            if !z50.is_finite() || z50.abs() < 1e-12 {
                continue;
            }
            let s = -qs[1].ln() / z50;
            if !s.is_finite() || s <= 0.0 {
                continue;
            }
            let dist = Self { c, s };
            let model_q25 = dist.ppf(0.25);
            let model_q75 = dist.ppf(0.75);
            if !model_q25.is_finite() || !model_q75.is_finite() {
                continue;
            }
            let error =
                ((model_q25 - qs[0]) / spread).powi(2) + ((model_q75 - qs[2]) / spread).powi(2);
            if best.is_none_or(|(_, _, best_error)| error < best_error) {
                best = Some((c, s, error));
            }
        }

        if let Some((c, s, _)) = best {
            Ok(Self { c, s })
        } else {
            Err(FitError::NonConvergent(
                "PowerLognorm quantile fit did not find finite c/s".to_owned(),
            ))
        }
    }
}

/// Johnson SU distribution.
///
/// Matches `scipy.stats.johnsonsu`.
pub struct JohnsonSU {
    pub a: f64,
    pub b: f64,
}

impl JohnsonSU {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a.is_finite(), "a must be finite");
        assert!(b.is_finite() && b > 0.0, "b must be positive and finite");
        Self { a, b }
    }
}

impl ContinuousDistribution for JohnsonSU {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = self.a + self.b * x.asinh();
        self.b * standard_normal_pdf(z) / x.hypot(1.0)
    }

    fn cdf(&self, x: f64) -> f64 {
        standard_normal_cdf(self.a + self.b * x.asinh())
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log Φ(a + b·asinh x); finite in the left tail. frankenscipy-osnge
        fsci_special::log_ndtr_scalar(self.a + self.b * x.asinh())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Φ(−(a+b·asinh x)) = ½·erfc((a+b·asinh x)/√2); direct so the right
        // tail does not collapse like the default 1−cdf. frankenscipy-w3f6m
        let z = self.a + self.b * x.asinh();
        0.5 * fsci_special::erfc_scalar(z * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = log Φ(−(a+b·asinh x)); finite in the ultra-extreme tail. frankenscipy-czegj
        fsci_special::log_ndtr_scalar(-(self.a + self.b * x.asinh()))
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        ((fsci_special::ndtri_scalar(q) - self.a) / self.b).sinh()
    }

    fn mean(&self) -> f64 {
        let inv_b = self.b.recip();
        let exp_inv_b_sq = (inv_b * inv_b).exp();
        -exp_inv_b_sq.sqrt() * (self.a * inv_b).sinh()
    }

    fn var(&self) -> f64 {
        let inv_b = self.b.recip();
        let exp_inv_b_sq = (inv_b * inv_b).exp();
        0.5 * exp_inv_b_sq.mul_add((2.0 * self.a * inv_b).cosh(), 1.0) * (inv_b * inv_b).exp_m1()
    }

    fn skewness(&self) -> f64 {
        // Raw moments via MGF of W = (U - a)/b ~ N(-a/b, 1/b^2):
        // E[e^{tW}] = exp(-tΩ + t²/(2b²)) where Ω = a/b.
        // Setting ω = exp(1/b²) gives closed-form raw moments m_n of
        // X = sinh(W); central moments follow.
        let omega = (self.b * self.b).recip().exp();
        let ohm = self.a / self.b;
        let m1 = -omega.sqrt() * ohm.sinh();
        let m2 = (omega * omega).mul_add((2.0 * ohm).cosh(), -1.0) / 2.0;
        let m3 = (3.0_f64.mul_add(
            omega.sqrt() * ohm.sinh(),
            -omega.powf(4.5) * (3.0 * ohm).sinh(),
        )) / 4.0;
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let omega = (self.b * self.b).recip().exp();
        let ohm = self.a / self.b;
        let m1 = -omega.sqrt() * ohm.sinh();
        let m2 = (omega * omega).mul_add((2.0 * ohm).cosh(), -1.0) / 2.0;
        let m3 = (3.0_f64.mul_add(
            omega.sqrt() * ohm.sinh(),
            -omega.powf(4.5) * (3.0 * ohm).sinh(),
        )) / 4.0;
        let m4 = ((omega.powi(8)).mul_add(
            (4.0 * ohm).cosh(),
            (-4.0 * omega * omega).mul_add((2.0 * ohm).cosh(), 3.0),
        )) / 8.0;
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // JohnsonSU: X = sinh((Z − a)/b), Z ~ N(0, 1). Integrate
        // −E[ln pdf(X)] in z so the gaussian weight bounds both tails.
        simpson_integrate_adaptive(
            |z| {
                let x = ((z - self.a) / self.b).sinh();
                let p = self.pdf(x);
                if p > 0.0 {
                    -standard_normal_pdf(z) * p.ln()
                } else {
                    0.0
                }
            },
            -12.0,
            12.0,
            4_096,
            1e-11,
            1e-11,
            8,
        )
    }
}

/// Johnson SB distribution.
///
/// Matches `scipy.stats.johnsonsb`.
pub struct JohnsonSB {
    pub a: f64,
    pub b: f64,
}

impl JohnsonSB {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a.is_finite(), "a must be finite");
        assert!(b.is_finite() && b > 0.0, "b must be positive and finite");
        Self { a, b }
    }

    fn expit(x: f64) -> f64 {
        if x >= 0.0 {
            1.0 / (1.0 + (-x).exp())
        } else {
            let exp_x = x.exp();
            exp_x / (1.0 + exp_x)
        }
    }

    /// k-th raw moment via the transformation X = expit((Z − a)/b),
    /// Z ~ N(0, 1):  m_k = ∫ expit^k((z − a)/b) · φ(z) dz.
    /// Evaluated by simpson_integrate_adaptive on [−12, 12] (φ tails
    /// negligible beyond) — same machinery as mean/var.
    fn raw_moment(&self, k: u32) -> f64 {
        simpson_integrate_adaptive(
            |z| {
                let x = Self::expit((z - self.a) / self.b);
                x.powi(k as i32) * standard_normal_pdf(z)
            },
            -12.0,
            12.0,
            4_096,
            1e-11,
            1e-11,
            8,
        )
    }
}

impl ContinuousDistribution for JohnsonSB {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 || x >= 1.0 {
            return 0.0;
        }
        let z = self.a + self.b * (x / (1.0 - x)).ln();
        self.b * standard_normal_pdf(z) / (x * (1.0 - x))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(b) + lnφ(z) − ln(x) − ln(1−x), z = a + b·ln(x/(1−x)); finite where
        // φ underflows. frankenscipy-p82v7
        if x <= 0.0 || x >= 1.0 {
            return f64::NEG_INFINITY;
        }
        let z = self.a + self.b * (x / (1.0 - x)).ln();
        self.b.ln() - 0.5 * z * z - 0.5 * (2.0 * PI).ln() - x.ln() - (1.0 - x).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return 1.0;
        }
        let z = self.a + self.b * (x / (1.0 - x)).ln();
        if z >= 0.0 {
            -fsci_special::log_ndtr_scalar(-z).exp_m1()
        } else {
            fsci_special::log_ndtr_scalar(z).exp()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        Self::expit((fsci_special::ndtri_scalar(q) - self.a) / self.b)
    }

    fn mean(&self) -> f64 {
        self.raw_moment(1)
    }

    fn var(&self) -> f64 {
        let m1 = self.raw_moment(1);
        (self.raw_moment(2) - m1 * m1).max(0.0)
    }

    fn skewness(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let m4 = self.raw_moment(4);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Direct −E[ln pdf]: PDF on x ∈ (0, 1) is
        //   pdf(x) = b·φ(a + b·logit(x)) / (x·(1−x))
        // where φ is the standard normal density. Integrate in the
        // underlying N(0, 1) variable z (so x = expit((z − a)/b))
        // using the same simpson_integrate_adaptive on [−12, 12]
        // pattern as the JohnsonSB raw_moment helper. The integrand
        //   −φ(z) · ln pdf(x(z))
        // is bounded everywhere because φ kills both tails.
        simpson_integrate_adaptive(
            |z| {
                let x = Self::expit((z - self.a) / self.b);
                let p = self.pdf(x);
                if p > 0.0 {
                    -standard_normal_pdf(z) * p.ln()
                } else {
                    0.0
                }
            },
            -12.0,
            12.0,
            4_096,
            1e-11,
            1e-11,
            8,
        )
    }
}

/// Generalized Extreme Value (GEV) distribution.
///
/// Uses the standard extreme-value-theory shape convention ξ = `c`: the pdf is
/// built around `(1 + c·x)`, so positive `c` is the heavy-tailed Fréchet case.
///
/// **SciPy uses the opposite sign for its shape parameter**, so
/// `GenExtreme::new(c)` equals `scipy.stats.genextreme(-c)` — to reproduce a
/// SciPy `genextreme(c)` result, construct `GenExtreme::new(-c)` (the
/// conformance harness in `diff_stats_genextreme.rs` flips the sign for exactly
/// this reason). pdf/cdf/ppf/sf and all moments are internally consistent under
/// this convention.
pub struct GenExtreme {
    pub c: f64, // shape parameter ξ (NOTE: negated relative to SciPy's `c`)
}

impl GenExtreme {
    #[must_use]
    pub fn new(c: f64) -> Self {
        Self { c }
    }
}

impl ContinuousDistribution for GenExtreme {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let c = self.c;
        if c.abs() < 1e-15 {
            // Gumbel case (c -> 0): exp(-(x + exp(-x)))
            let ex = (-x).exp();
            (-(x + ex)).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return 0.0;
            }
            let tp = t.powf(-1.0 / c);
            tp.powf(c + 1.0) * (-tp).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −(x+e^{-x}) (c→0) or −(c+1)/c·ln(1+c·x) − (1+c·x)^{−1/c}; finite tail. frankenscipy-p82v7
        let c = self.c;
        if c.abs() < 1e-15 {
            -x - (-x).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return f64::NEG_INFINITY;
            }
            -(c + 1.0) / c * t.ln() - t.powf(-1.0 / c)
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        let c = self.c;
        if c.abs() < 1e-15 {
            (-(-x).exp()).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { 0.0 } else { 1.0 };
            }
            (-t.powf(-1.0 / c)).exp()
        }
    }

    fn logcdf(&self, x: f64) -> f64 {
        let c = self.c;
        // cdf = exp(-τ), so logcdf = -τ directly. The default ln(cdf) underflows
        // to -inf once cdf -> 0 in the left tail (genextreme(0).logcdf(-50) =
        // -inf vs scipy -5.18e21). τ = exp(-x) (Gumbel) or (1+cx)^(-1/c).
        if c.abs() < 1e-15 {
            -(-x).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { f64::NEG_INFINITY } else { 0.0 };
            }
            -t.powf(-1.0 / c)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Survival = 1 − exp(−τ) = −expm1(−τ), computed directly so the right
        // tail (τ→0, cdf→1) doesn't collapse to 0 (genextreme(0).sf(40) scipy
        // 4.2e-18). frankenscipy-8y248
        let c = self.c;
        if c.abs() < 1e-15 {
            -((-(-x).exp()).exp_m1())
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { 1.0 } else { 0.0 };
            }
            -((-t.powf(-1.0 / c)).exp_m1())
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return if self.c > 0.0 {
                -1.0 / self.c
            } else {
                f64::NEG_INFINITY
            };
        }
        if q == 1.0 {
            return if self.c < 0.0 {
                -1.0 / self.c
            } else {
                f64::INFINITY
            };
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            -(-q.ln()).ln()
        } else {
            ((-q.ln()).powf(-c) - 1.0) / c
        }
    }

    fn mean(&self) -> f64 {
        let c = self.c;
        if c.abs() < 1e-15 {
            0.577_215_664_901_532_9 // Euler-Mascheroni constant
        } else if c < 1.0 {
            (ln_gamma(1.0 - c).exp() - 1.0) / c
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        let c = self.c;
        if c.abs() < 1e-15 {
            PI * PI / 6.0
        } else if c < 0.5 {
            let g1 = ln_gamma(1.0 - c).exp();
            let g2 = ln_gamma(1.0 - 2.0 * c).exp();
            (g2 - g1 * g1) / (c * c)
        } else {
            f64::INFINITY
        }
    }

    fn skewness(&self) -> f64 {
        // Wikipedia closed form: sgn(c)·(g_3 − 3·g_1·g_2 + 2·g_1³) /
        // (g_2 − g_1²)^{3/2} where g_k = Γ(1 − k·c). Exists when c < 1/3.
        // c = 0 limit: -12·√6·ζ(3)/π³ ≈ -1.13955 (Gumbel value).
        // (frankenscipy-ufsz9)
        let c = self.c;
        if c.abs() < 1e-15 {
            // Gumbel-right limit; scipy.stats.gumbel_r.skewness =
            // +12·√6·ζ(3)/π³ ≈ +1.1396. The Wikipedia sgn(c)·formula
            // has a 0/0 singularity at c = 0 but its analytic limit
            // matches this canonical value.
            return 1.139_547_099_404_648_7;
        }
        if c >= 1.0 / 3.0 {
            return f64::NAN;
        }
        let g1 = ln_gamma(1.0 - c).exp();
        let g2 = ln_gamma(1.0 - 2.0 * c).exp();
        let g3 = ln_gamma(1.0 - 3.0 * c).exp();
        let num = g3 - 3.0 * g1 * g2 + 2.0 * g1 * g1 * g1;
        let den = (g2 - g1 * g1).powf(1.5);
        c.signum() * num / den
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: (g_4 − 4·g_1·g_3 + 6·g_1²·g_2 − 3·g_1⁴)
        // / (g_2 − g_1²)² − 3. Exists when c < 1/4.
        // c = 0 limit: 12/5 = 2.4 (Gumbel). (frankenscipy-ufsz9)
        let c = self.c;
        if c.abs() < 1e-15 {
            return 12.0 / 5.0;
        }
        if c >= 0.25 {
            return f64::NAN;
        }
        let g1 = ln_gamma(1.0 - c).exp();
        let g2 = ln_gamma(1.0 - 2.0 * c).exp();
        let g3 = ln_gamma(1.0 - 3.0 * c).exp();
        let g4 = ln_gamma(1.0 - 4.0 * c).exp();
        let g1_sq = g1 * g1;
        let num = g4 - 4.0 * g1 * g3 + 6.0 * g1_sq * g2 - 3.0 * g1_sq * g1_sq;
        let den = (g2 - g1_sq).powi(2);
        num / den - 3.0
    }

    fn entropy(&self) -> f64 {
        // h(GenExtreme(c)) = γ · (1 + c) + 1.  (γ = Euler-Mascheroni.)
        // Our `c` is scipy's negated shape (GenExtreme::new(c) == genextreme(-c)),
        // so scipy's h = γ·(1 − c_scipy) + 1 becomes γ·(1 + c) + 1 here. The sign
        // of `c` was previously flipped, matching scipy only at c = 0 (Gumbel,
        // h = γ + 1) and diverging by up to ~25% for nonzero shape.
        EULER_MASCHERONI.mul_add(1.0 + self.c, 1.0)
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 3, "GenExtreme")?;
        let qs = quantile(data, &[0.25, 0.5, 0.75]);
        let spread = qs[2] - qs[0];
        if !spread.is_finite() || spread <= 0.0 {
            return Err(FitError::NonConvergent(
                "GenExtreme fit needs non-degenerate quartiles".to_owned(),
            ));
        }

        let mut best = None::<(f64, f64)>;
        for step in 0..=1600 {
            let c = -2.0 + 0.0025 * step as f64;
            let dist = Self { c };
            let model = [dist.ppf(0.25), dist.ppf(0.5), dist.ppf(0.75)];
            if model.iter().any(|x| !x.is_finite()) {
                continue;
            }
            let error = model
                .iter()
                .zip(qs.iter())
                .map(|(m, q)| ((m - q) / spread).powi(2))
                .sum::<f64>();
            if best.is_none_or(|(_, best_error)| error < best_error) {
                best = Some((c, error));
            }
        }

        if let Some((c, _)) = best {
            Ok(Self { c })
        } else {
            Err(FitError::NonConvergent(
                "GenExtreme quantile fit did not find a finite shape".to_owned(),
            ))
        }
    }

    fn mode(&self) -> f64 {
        // fsci GenExtreme uses pdf ∝ (1 + c·x)^{-(1/c+1)}·exp(-(1+c·x)^{-1/c}).
        // Solving d/dx ln pdf = 0 gives (1 + c·x)^{-1/c} = 1 + c, hence
        //   mode = ((1 + c)^{-c} − 1) / c     for c ≠ 0
        // c = 0 collapses to standard Gumbel, mode = 0. The opposite-sign
        // convention vs scipy.stats.genextreme is intentional — fsci's c
        // matches scipy's −c. (frankenscipy-tlw2q)
        if self.c == 0.0 {
            0.0
        } else {
            ((1.0 + self.c).powf(-self.c) - 1.0) / self.c
        }
    }
}

/// Generalized Pareto distribution.
///
/// Matches `scipy.stats.genpareto`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GenPareto {
    pub c: f64,
}

impl GenPareto {
    #[must_use]
    pub fn new(c: f64) -> Self {
        Self { c }
    }
}

impl ContinuousDistribution for GenPareto {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            (-x).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return 0.0;
            }
            t.powf(-1.0 / c - 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −x (c→0) or (−1/c−1)·ln(1+c·x); finite in the tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            -x
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return f64::NEG_INFINITY;
            }
            (-1.0 / c - 1.0) * t.ln()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            1.0 - (-x).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { 0.0 } else { 1.0 };
            }
            1.0 - t.powf(-1.0 / c)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival (1 + c·x)^(-1/c), or e^(-x) for c→0 — the default
        // 1−cdf collapses to 0 in the right tail (genpareto(0).sf(40) scipy
        // 4.2e-18). frankenscipy-w3f6m
        if x < 0.0 {
            return 1.0;
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            (-x).exp()
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { 0.0 } else { 1.0 };
            }
            t.powf(-1.0 / c)
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = −(1/c)·ln(1+c·x), or −x for c→0; finite in the ultra-extreme
        // tail where ln(sf) would be −inf. frankenscipy-czegj
        if x < 0.0 {
            return 0.0;
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            -x
        } else {
            let t = 1.0 + c * x;
            if t <= 0.0 {
                return if c > 0.0 { f64::NEG_INFINITY } else { 0.0 };
            }
            -(1.0 / c) * t.ln()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return if self.c < 0.0 {
                -1.0 / self.c
            } else {
                f64::INFINITY
            };
        }
        let c = self.c;
        if c.abs() < 1e-15 {
            -(1.0 - q).ln()
        } else {
            ((1.0 - q).powf(-c) - 1.0) / c
        }
    }

    fn mean(&self) -> f64 {
        if self.c < 1.0 {
            1.0 / (1.0 - self.c)
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        if self.c < 0.5 {
            1.0 / ((1.0 - self.c).powi(2) * (1.0 - 2.0 * self.c))
        } else {
            f64::INFINITY
        }
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = k! / prod_{j=1}^k (1 − jc); finite for c < 1/k.
        // Skewness requires c < 1/3.
        if self.c >= 1.0 / 3.0 {
            return f64::NAN;
        }
        let c = self.c;
        let m1 = 1.0 / (1.0 - c);
        let m2 = 2.0 / ((1.0 - c) * (1.0 - 2.0 * c));
        let m3 = 6.0 / ((1.0 - c) * (1.0 - 2.0 * c) * (1.0 - 3.0 * c));
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurt requires c < 1/4.
        if self.c >= 0.25 {
            return f64::NAN;
        }
        let c = self.c;
        let m1 = 1.0 / (1.0 - c);
        let m2 = 2.0 / ((1.0 - c) * (1.0 - 2.0 * c));
        let m3 = 6.0 / ((1.0 - c) * (1.0 - 2.0 * c) * (1.0 - 3.0 * c));
        let m4 = 24.0 / ((1.0 - c) * (1.0 - 2.0 * c) * (1.0 - 3.0 * c) * (1.0 - 4.0 * c));
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // h(GenPareto(c)) = 1 + c (exact closed form for any c).
        1.0 + self.c
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Method-of-moments: at unit scale, E[X | c] = 1/(1-c) for c < 1.
        // Solving for c: c_hat = 1 - 1/sample_mean = (mean - 1) / mean.
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "GenPareto data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "GenPareto support starts at 0; got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 0.0 || !mean.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "GenPareto MoM: sample mean {mean} is non-positive"
            )));
        }
        let c = (mean - 1.0) / mean;
        if !c.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "GenPareto MoM produced non-finite shape: {c}"
            )));
        }
        Ok(Self { c })
    }

    fn mode(&self) -> f64 {
        // GenPareto pdf = (1 + c·x)^{−(1/c + 1)} on x ≥ 0 is strictly
        // decreasing in x for every valid c, so the mode is the boundary
        // 0 (frankenscipy-tlw2q).
        0.0
    }
}

/// Power-law distribution: x^(a-1) on [0, 1].
///
/// Matches `scipy.stats.powerlaw`.
pub struct PowerLaw {
    pub a: f64,
}

impl PowerLaw {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0, "a must be positive");
        Self { a }
    }
}

impl ContinuousDistribution for PowerLaw {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if !(0.0..=1.0).contains(&x) {
            0.0
        } else {
            self.a * x.powf(self.a - 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(a) + (a−1)·ln(x) on (0,1]; boundary/shape limits delegate to pdf. frankenscipy-p82v7
        if !(0.0..=1.0).contains(&x) || x == 0.0 {
            return self.pdf(x).ln();
        }
        self.a.ln() + (self.a - 1.0) * x.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else if x >= 1.0 {
            1.0
        } else {
            x.powf(self.a)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − x^a = −expm1(a·ln x) on (0,1); stable near the upper edge
        // x→1 where the literal 1 − x^a underflows. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        if x >= 1.0 {
            return 0.0;
        }
        -(self.a * x.ln()).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            0.0
        } else if q == 1.0 {
            1.0
        } else {
            q.powf(1.0 / self.a)
        }
    }

    fn mean(&self) -> f64 {
        self.a / (self.a + 1.0)
    }

    fn var(&self) -> f64 {
        self.a / ((self.a + 1.0).powi(2) * (self.a + 2.0))
    }

    fn entropy(&self) -> f64 {
        // h(PowerLaw(a)) = 1 − 1/a − ln(a).
        1.0 - 1.0 / self.a - self.a.ln()
    }

    fn skewness(&self) -> f64 {
        // Raw moments are E[X^k] = a/(a+k). Build central moments
        // analytically. (frankenscipy-noof0)
        let a = self.a;
        let m1 = a / (a + 1.0);
        let m2 = a / (a + 2.0);
        let m3 = a / (a + 3.0);
        let mu3 = m3 - 3.0 * m1 * m2 + 2.0 * m1 * m1 * m1;
        let var = m2 - m1 * m1;
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let a = self.a;
        let m1 = a / (a + 1.0);
        let m2 = a / (a + 2.0);
        let m3 = a / (a + 3.0);
        let m4 = a / (a + 4.0);
        let mu4 = m4 - 4.0 * m1 * m3 + 6.0 * m1 * m1 * m2 - 3.0 * m1 * m1 * m1 * m1;
        let var = m2 - m1 * m1;
        mu4 / (var * var) - 3.0
    }

    fn fit(data: &[f64]) -> Self {
        if data.is_empty() || data.iter().any(|&x| !x.is_finite() || x <= 0.0 || x > 1.0) {
            return Self { a: f64::NAN };
        }

        let log_sum = data.iter().map(|&x| x.ln()).sum::<f64>();
        if !log_sum.is_finite() || log_sum > 0.0 {
            return Self { a: f64::NAN };
        }
        if log_sum == 0.0 {
            return Self { a: f64::INFINITY };
        }

        Self {
            a: -(data.len() as f64) / log_sum,
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.is_empty() {
            return Err(FitError::InsufficientData {
                required: 1,
                actual: 0,
            });
        }
        if data.iter().any(|&x| !x.is_finite()) {
            return Err(FitError::UnsupportedData(
                "PowerLaw::fit: non-finite samples".to_owned(),
            ));
        }
        if data.iter().any(|&x| x <= 0.0 || x > 1.0) {
            return Err(FitError::UnsupportedData(
                "PowerLaw::fit: samples must be in (0, 1] for fixed-support MLE".to_owned(),
            ));
        }
        Ok(Self::fit(data))
    }

    fn mode(&self) -> f64 {
        // PowerLaw pdf = a·x^{a−1} on [0, 1]. For a > 1 the pdf is
        // strictly increasing on (0, 1], so the maximum is at x = 1.
        // For a < 1 it is strictly decreasing, mode at the boundary 0
        // (frankenscipy-tlw2q).
        if self.a > 1.0 { 1.0 } else { 0.0 }
    }
}

/// Half-normal distribution (folded normal).
///
/// Matches `scipy.stats.halfnorm`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HalfNormal;

impl ContinuousDistribution for HalfNormal {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            (2.0 / PI).sqrt() * (-x * x / 2.0).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ½·ln(2/π) − x²/2; finite in the tail where pdf underflows. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        0.5 * (2.0 / PI).ln() - x * x / 2.0
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.0
        } else {
            fsci_special::erf_scalar(x / std::f64::consts::SQRT_2)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-f66lp]:
        //   sf(x) = erfc(x/√2) for x ≥ 0.
        // erfc preserves deep-tail precision where 1 - erf would
        // collapse to 0.
        if x < 0.0 {
            1.0
        } else {
            fsci_special::erfc_scalar(x / std::f64::consts::SQRT_2)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // HalfNormal is the positive half of N(0,1), so ppf(q) = ndtri((1+q)/2)
        fsci_special::ndtri_scalar((1.0 + q) / 2.0)
    }

    fn mean(&self) -> f64 {
        (2.0 / PI).sqrt()
    }

    fn var(&self) -> f64 {
        1.0 - 2.0 / PI
    }

    fn skewness(&self) -> f64 {
        // √2·(4 − π) / (π − 2)^{3/2} ≈ 0.99527 (frankenscipy-5cd0j).
        let pm2 = PI - 2.0;
        std::f64::consts::SQRT_2 * (4.0 - PI) / pm2.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 8(π − 3) / (π − 2)² ≈ 0.86918 (frankenscipy-5cd0j).
        let pm2 = PI - 2.0;
        8.0 * (PI - 3.0) / (pm2 * pm2)
    }

    // fit() inherits the trait default (delegates to try_fit, panics on
    // FitError). Resolves [frankenscipy-paejq]: previously fit silently
    // accepted any data including negatives, while try_fit validated.

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x < 0.0) {
            return Err(FitError::UnsupportedData(
                "HalfNormal data must be non-negative".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // HalfNormal mode = 0 (left edge of support) [frankenscipy-cxgdg].
        0.0
    }

    fn entropy(&self) -> f64 {
        // H(HalfNormal) = 0.5·ln(πe/2) [frankenscipy-vngzr].
        0.5 * (PI * std::f64::consts::E / 2.0).ln()
    }
}

/// Half-logistic distribution.
///
/// Matches `scipy.stats.halflogistic`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HalfLogistic;

impl ContinuousDistribution for HalfLogistic {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let exp_neg_x = (-x).exp();
        2.0 * exp_neg_x / (1.0 + exp_neg_x).powi(2)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln2 − x − 2·ln1p(e^{-x}); finite in the tail (support x≥0). frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        2.0_f64.ln() - x - 2.0 * (-x).exp().ln_1p()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let exp_neg_x = (-x).exp();
        (1.0 - exp_neg_x) / (1.0 + exp_neg_x)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 2·e^{-x}/(1 + e^{-x}); the default 1−cdf collapses to 0 for
        // x ≳ 37 (halflogistic.sf(40) scipy 8.5e-18). frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let e = (-x).exp();
        2.0 * e / (1.0 + e)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = ln 2 − x − ln1p(e^{-x}); finite for arbitrarily large x. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        std::f64::consts::LN_2 - x - (-x).exp().ln_1p()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        ((1.0 + q) / (1.0 - q)).ln()
    }

    fn mean(&self) -> f64 {
        2.0 * LN_2
    }

    fn var(&self) -> f64 {
        PI * PI / 3.0 - 4.0 * LN_2 * LN_2
    }

    fn skewness(&self) -> f64 {
        // Standardised third central moment via numerical integration of
        // E[X^k] = 2^k · ∫_0^∞ s^k · sech²(s) ds   (after q = tanh s).
        // (frankenscipy-okhq6)
        let m1 = 2.0 * LN_2;
        let m2 = halflogistic_raw_moment(2);
        let m3 = halflogistic_raw_moment(3);
        let var = m2 - m1 * m1;
        let mu3 = m3 - 3.0 * m1 * m2 + 2.0 * m1 * m1 * m1;
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = 2.0 * LN_2;
        let m2 = halflogistic_raw_moment(2);
        let m3 = halflogistic_raw_moment(3);
        let m4 = halflogistic_raw_moment(4);
        let var = m2 - m1 * m1;
        let mu4 = m4 - 4.0 * m1 * m3 + 6.0 * m1 * m1 * m2 - 3.0 * m1 * m1 * m1 * m1;
        mu4 / (var * var) - 3.0
    }

    // fit() inherits the trait default. Resolves [frankenscipy-paejq].

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x < 0.0) {
            return Err(FitError::UnsupportedData(
                "HalfLogistic data must be non-negative".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // HalfLogistic mode = 0 (left edge of support) [frankenscipy-cxgdg].
        0.0
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-8f97g]: scipy.stats.halflogistic
        // reports differential entropy = 2 − ln(2) ≈ 1.30685.
        2.0 - LN_2
    }
}

/// Half-Cauchy distribution.
///
/// Matches `scipy.stats.halfcauchy`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HalfCauchy;

impl ContinuousDistribution for HalfCauchy {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        2.0 / (PI * (1.0 + x * x))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln2 − ln(π) − ln(1+x²); finite in the heavy tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        2.0_f64.ln() - PI.ln() - (1.0 + x * x).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        2.0 * x.atan() / PI
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival for [frankenscipy-f66lp]:
        //   sf(x) = 2·atan(1/x)/π for x > 0  (arctan reciprocal)
        // For very large x the default 1 - 2·atan(x)/π collapses to 0
        // because atan(x) rounds to π/2; the closed form returns the
        // actual ~2/(π·x) behaviour.
        if x <= 0.0 {
            1.0
        } else {
            2.0 * (1.0 / x).atan() / PI
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        (PI * q / 2.0).tan()
    }

    fn mean(&self) -> f64 {
        // HalfCauchy has no finite moments — scipy reports +∞, not NaN,
        // so callers that distinguish "moment doesn't exist" from
        // "not yet implemented" can rely on the same dispatch
        // (frankenscipy-59anq).
        f64::INFINITY
    }

    fn var(&self) -> f64 {
        f64::INFINITY
    }

    fn skewness(&self) -> f64 {
        // Heavy 1/x² tails (one-sided), all higher moments diverge.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    // fit() inherits the trait default. Resolves [frankenscipy-paejq].

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x < 0.0) {
            return Err(FitError::UnsupportedData(
                "HalfCauchy data must be non-negative".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // HalfCauchy mode = 0 (left edge of support) [frankenscipy-cxgdg].
        0.0
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-8f97g]: scipy.stats.halfcauchy
        // reports differential entropy = ln(2π) ≈ 1.83788. (mean and
        // higher moments are NaN; only entropy has a closed form.)
        (2.0 * PI).ln()
    }
}

/// Birnbaum-Saunders fatigue-life distribution.
///
/// Matches `scipy.stats.fatiguelife`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FatigueLife {
    pub c: f64,
}

impl FatigueLife {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for FatigueLife {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let numerator = x + 1.0;
        let denominator = 2.0 * self.c * (2.0 * PI * x.powi(3)).sqrt();
        let exponent = -((x - 1.0) * (x - 1.0)) / (2.0 * x * self.c * self.c);
        numerator * exponent.exp() / denominator
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(x+1) + exponent − ln(2c) − ½ln(2π) − 1.5·ln(x); finite tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let exponent = -((x - 1.0) * (x - 1.0)) / (2.0 * x * self.c * self.c);
        (x + 1.0).ln() + exponent - (2.0 * self.c).ln() - 0.5 * (2.0 * PI).ln() - 1.5 * x.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // Delegate to standard_normal_cdf for deep-tail precision
        // (very small x → very negative z; very large x → very
        // positive z). Resolves [frankenscipy-tkpgq].
        let root_x = x.sqrt();
        let z = (root_x - 1.0 / root_x) / self.c;
        standard_normal_cdf(z)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log Φ(z), z = (√x − 1/√x)/c; finite in the left tail. frankenscipy-osnge
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let root_x = x.sqrt();
        fsci_special::log_ndtr_scalar((root_x - 1.0 / root_x) / self.c)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Φ(−z) = ½·erfc(z/√2), z = (√x − 1/√x)/c; direct so the deep
        // right tail (z→+∞, cdf→1) doesn't collapse to 0. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let root_x = x.sqrt();
        let z = (root_x - 1.0 / root_x) / self.c;
        0.5 * fsci_special::erfc_scalar(z * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = log Φ(−z), z = (√x − 1/√x)/c; finite deep tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        let root_x = x.sqrt();
        let z = (root_x - 1.0 / root_x) / self.c;
        fsci_special::log_ndtr_scalar(-z)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let tmp = self.c * fsci_special::ndtri_scalar(q);
        0.25 * (tmp + (tmp * tmp + 4.0).sqrt()).powi(2)
    }

    fn mean(&self) -> f64 {
        1.0 + 0.5 * self.c * self.c
    }

    fn var(&self) -> f64 {
        0.25 * self.c * self.c * (5.0 * self.c * self.c + 4.0)
    }

    fn skewness(&self) -> f64 {
        // Closed form for Birnbaum-Saunders / FatigueLife shape c:
        //   skew = 4·c·(11c² + 6) / (5c² + 4)^{3/2}
        // (frankenscipy-4iv2i)
        let c2 = self.c * self.c;
        4.0 * self.c * (11.0 * c2 + 6.0) / (5.0 * c2 + 4.0).powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: 6·c²·(93c² + 40) / (5c² + 4)²
        // (frankenscipy-4iv2i)
        let c2 = self.c * self.c;
        let denom = 5.0 * c2 + 4.0;
        6.0 * c2 * (93.0 * c2 + 40.0) / (denom * denom)
    }

    fn entropy(&self) -> f64 {
        // Birnbaum-Saunders has no elementary entropy closed form;
        // adaptive Simpson on -pdf · ln pdf with a tail cap that scales
        // with c (heavier c → more right-tail mass). For c=2 the tail
        // extends to ~200 and lower base grids underestimate.
        let upper = (1.0 + 80.0 * self.c * self.c).max(200.0);
        simpson_integrate_adaptive(
            |x| {
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            upper,
            4_096,
            1e-10,
            1e-10,
            10,
        )
    }
}

/// Truncated normal distribution on [a, b].
///
/// Matches `scipy.stats.truncnorm`.
pub struct TruncNormal {
    pub a: f64,
    pub b: f64,
}

impl TruncNormal {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a < b, "a must be less than b");
        Self { a, b }
    }

    /// `Φ(b) − Φ(a)`, the renormalising mass — computed on whichever tail keeps
    /// the subtraction small.
    ///
    /// Written literally, that difference is exactly ZERO for `a = 30, b = 40`,
    /// because both operands round to 1.0. Every method here divides by it, so the
    /// whole distribution collapsed: `pdf` was identically 0 across its entire
    /// support where `scipy.stats.truncnorm.pdf(30.5, 30, 40)` is 8.107714e-06.
    /// The survival-side form `S(a) − S(b)` gives 4.906713927147908e-198 for the
    /// same interval. It is not only an extreme-case problem — on `[5, 10]` the
    /// two forms already disagree in the 10th significant digit.
    ///
    /// [`interval_probability`] makes that choice; this is a thin alias so the
    /// seven call sites below cannot drift apart again. frankenscipy-45de1.
    fn mass(&self) -> f64 {
        interval_probability(&Normal::standard(), self.a, self.b)
    }
}

impl ContinuousDistribution for TruncNormal {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < self.a || x > self.b {
            return 0.0;
        }
        let phi_x = (-x * x / 2.0).exp() / (2.0 * PI).sqrt();
        let norm = self.mass();
        if norm > 0.0 { phi_x / norm } else { 0.0 }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= self.a {
            return 0.0;
        }
        if x >= self.b {
            return 1.0;
        }
        // BOTH the numerator and the denominator are interval masses, and both
        // cancel for the same reason, so both go through the tail choice.
        let norm = self.mass();
        if norm > 0.0 {
            (interval_probability(&Normal::standard(), self.a, x) / norm).clamp(0.0, 1.0)
        } else {
            0.0
        }
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= self.a {
            return 1.0;
        }
        if x >= self.b {
            return 0.0;
        }
        // Its own interval mass, NOT 1 − cdf. Previously there was no `sf` here at
        // all, so the trait default subtracted — and the upper part of the interval
        // is exactly where that has already lost its digits.
        // scipy.stats.truncnorm.sf(32, 30, 40) = 1.08655699900926376e-34.
        let norm = self.mass();
        if norm > 0.0 {
            (interval_probability(&Normal::standard(), x, self.b) / norm).clamp(0.0, 1.0)
        } else {
            0.0
        }
    }

    /// The quantile, kept inside the support.
    ///
    /// The trait default returns `-inf` at `q = 0` and `+inf` at `q = 1`, which is right
    /// for a distribution on the whole line and wrong for a truncated one: the support
    /// IS `[a, b]`, so those are the two quantiles that are known exactly.
    /// `scipy.stats.truncnorm.ppf(0, 30, 40)` is 30 and `ppf(1, 30, 40)` is 40.
    ///
    /// The interior is left to the default bisection, which is sound here because `cdf`
    /// now goes through the tail-choosing interval mass. Its result is clamped for the
    /// same reason `Truncated::quantile` clamps: on `[30, 40]` the bracketing anchors
    /// are built from `mean` and `std`, both of which are computed from quantities that
    /// underflow, so the search can step outside a support it should never leave.
    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.a;
        }
        if q == 1.0 {
            return self.b;
        }
        let x = ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std());
        x.clamp(self.a, self.b)
    }

    /// Inverse survival function, with the same endpoints reflected.
    ///
    /// `isf(0)` is the upper bound and `isf(1)` the lower — the mirror of `ppf`. Left to
    /// the trait default these are `+inf` and `-inf`, and fixing only `ppf` would leave
    /// the two functions disagreeing about where the distribution lives.
    ///
    /// The interior keeps the trait's own tail discipline rather than reinventing it:
    /// `1 - q` is used only while it is representable, and below that the accurate `sf`
    /// is inverted directly. Routing everything through `ppf(1 - q)` would reintroduce
    /// precisely the underflow the default was written to avoid — for `q` under about
    /// 1.1e-16, `1 - q` rounds to 1.0 and the answer collapses to the upper bound.
    fn isf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.b;
        }
        if q == 1.0 {
            return self.a;
        }
        let p = 1.0 - q;
        let x = if p < 1.0 {
            ppf_bisection(|x| self.cdf(x), p, self.mean(), self.std())
        } else {
            isf_bisection(|x| self.sf(x), q, self.mean(), self.std())
        };
        x.clamp(self.a, self.b)
    }

    fn mean(&self) -> f64 {
        let phi_a = (-self.a * self.a / 2.0).exp() / (2.0 * PI).sqrt();
        let phi_b = (-self.b * self.b / 2.0).exp() / (2.0 * PI).sqrt();
        let norm = self.mass();
        if norm > 0.0 {
            (phi_a - phi_b) / norm
        } else {
            (self.a + self.b) / 2.0
        }
    }

    fn var(&self) -> f64 {
        let phi_a = (-self.a * self.a / 2.0).exp() / (2.0 * PI).sqrt();
        let phi_b = (-self.b * self.b / 2.0).exp() / (2.0 * PI).sqrt();
        let norm = self.mass();
        if norm <= 0.0 {
            return 0.0;
        }
        let z = norm;
        1.0 + (self.a * phi_a - self.b * phi_b) / z - ((phi_a - phi_b) / z).powi(2)
    }

    fn entropy(&self) -> f64 {
        // h(TruncNormal(a, b)) = ln(√(2πe) · Δ)
        //                      + (a·φ(a) − b·φ(b)) / (2 Δ),
        // where Δ = Φ(b) − Φ(a). (Standard normal truncation.)
        let phi_a = (-self.a * self.a / 2.0).exp() / (2.0 * PI).sqrt();
        let phi_b = (-self.b * self.b / 2.0).exp() / (2.0 * PI).sqrt();
        let delta = self.mass();
        if delta <= 0.0 {
            return f64::NAN;
        }
        ((2.0 * PI * std::f64::consts::E).sqrt() * delta).ln()
            + (self.a * phi_a - self.b * phi_b) / (2.0 * delta)
    }

    fn skewness(&self) -> f64 {
        // Raw moments of the standard truncated normal follow the
        // integration-by-parts recurrence m_k = (a^{k−1}φ(a) −
        // b^{k−1}φ(b))/Δ + (k−1) m_{k−2} with m_0 = 1.
        let (a, b) = (self.a, self.b);
        let phi_a = (-a * a / 2.0).exp() / (2.0 * PI).sqrt();
        let phi_b = (-b * b / 2.0).exp() / (2.0 * PI).sqrt();
        let z = self.mass();
        if z <= 0.0 {
            return f64::NAN;
        }
        let m1 = (phi_a - phi_b) / z;
        let m2 = (a * phi_a - b * phi_b) / z + 1.0;
        let m3 = 2.0_f64.mul_add(m1, (a * a * phi_a - b * b * phi_b) / z);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let (a, b) = (self.a, self.b);
        let phi_a = (-a * a / 2.0).exp() / (2.0 * PI).sqrt();
        let phi_b = (-b * b / 2.0).exp() / (2.0 * PI).sqrt();
        let z = self.mass();
        if z <= 0.0 {
            return f64::NAN;
        }
        let m1 = (phi_a - phi_b) / z;
        let m2 = (a * phi_a - b * phi_b) / z + 1.0;
        let m3 = 2.0_f64.mul_add(m1, (a * a * phi_a - b * b * phi_b) / z);
        let m4 = 3.0_f64.mul_add(m2, (a.powi(3) * phi_a - b.powi(3) * phi_b) / z);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }
}

/// Chi distribution (not chi-squared).
///
/// Matches `scipy.stats.chi`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Chi {
    pub df: f64,
}

impl Chi {
    #[must_use]
    pub fn new(df: f64) -> Self {
        assert!(df > 0.0, "df must be positive");
        Self { df }
    }

    /// Log-density at many points, hoisting `(1−k/2)·ln2` and `lnΓ(k/2)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (lead leading, lnΓ last
    /// subtraction); x≤0 delegates to `pdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k = self.df;
        let lead = (1.0 - k / 2.0) * 2.0_f64.ln();
        let lg = ln_gamma(k / 2.0);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return self.pdf(x).ln();
            }
            lead + (k - 1.0) * x.ln() - x * x / 2.0 - lg
        })
    }

    /// Density at many points; hoists `2^(1−k/2)` and `Γ(k/2)` like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k = self.df;
        let lead = 2.0_f64.powf(1.0 - k / 2.0);
        let gamma_k2 = ln_gamma(k / 2.0).exp();
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            lead * x.powf(k - 1.0) * (-x * x / 2.0).exp() / gamma_k2
        })
    }
}

impl ContinuousDistribution for Chi {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let k = self.df;
        2.0_f64.powf(1.0 - k / 2.0) * x.powf(k - 1.0) * (-x * x / 2.0).exp()
            / ln_gamma(k / 2.0).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // (1−k/2)·ln2 + (k−1)·ln(x) − x²/2 − lnΓ(k/2); finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let k = self.df;
        (1.0 - k / 2.0) * 2.0_f64.ln() + (k - 1.0) * x.ln() - x * x / 2.0 - ln_gamma(k / 2.0)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // CDF of chi with k df = regularized lower incomplete gamma(k/2, x²/2)
        lower_regularized_gamma(self.df / 2.0, x * x / 2.0)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log P(k/2, x²/2); finite in the left tail where P underflows. frankenscipy-s14mf
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_gammainc_scalar(self.df / 2.0, x * x / 2.0)
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival Q(k/2, x²/2) — avoids the default 1−cdf collapsing
        // to 0 in the right tail (chi.sf(10,4) scipy 9.8e-21). frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(self.df / 2.0, x * x / 2.0)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(k/2, x²/2); finite in the ultra-extreme tail where Q underflows. frankenscipy-pkaua
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammaincc_scalar(self.df / 2.0, x * x / 2.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = P(df/2, x²/2), so x²/2 = gammaincinv(df/2, q), x = sqrt(2*gammaincinv(df/2, q))
        let g = fsci_special::gammaincinv_scalar(self.df / 2.0, q);
        let mut x = (2.0 * g).sqrt();
        if x <= 0.0 || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        let k = self.df;
        std::f64::consts::SQRT_2 * ln_gamma((k + 1.0) / 2.0).exp() / ln_gamma(k / 2.0).exp()
    }

    fn var(&self) -> f64 {
        let m = self.mean();
        self.df - m * m
    }

    fn skewness(&self) -> f64 {
        // γ₁ = μ(1 − 2σ²) / σ³ (frankenscipy-fubyp)
        let mu = self.mean();
        let var = self.df - mu * mu;
        let sigma = var.sqrt();
        mu * (1.0 - 2.0 * var) / (sigma * sigma * sigma)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis: (2/σ²)·(1 − μσ·γ₁ − σ²) (frankenscipy-fubyp)
        let mu = self.mean();
        let var = self.df - mu * mu;
        let sigma = var.sqrt();
        let skew = mu * (1.0 - 2.0 * var) / (sigma * sigma * sigma);
        (2.0 / var) * (1.0 - mu * sigma * skew - var)
    }

    fn entropy(&self) -> f64 {
        // h(Chi(k)) = ln Γ(k/2) + (k − ln 2 − (k − 1) ψ(k/2)) / 2.
        let k = self.df;
        ln_gamma(k / 2.0)
            + 0.5 * (k - 2.0_f64.ln() - (k - 1.0) * fsci_special::digamma_scalar(k / 2.0))
    }

    fn mode(&self) -> f64 {
        // Differentiating x^{k−1}·exp(−x²/2) gives x² = k − 1, so the
        // mode is √(k−1) for k ≥ 1; the pdf is monotone decreasing for
        // k < 1 with the mode pushed to the boundary 0 (frankenscipy-rt24d).
        if self.df >= 1.0 {
            (self.df - 1.0).sqrt()
        } else {
            0.0
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Chi(df) is sqrt of ChiSquared(df), so E[X²] = df.
        // Closed-form MoM: df_hat = sample_E[x²].
        let mut sum2 = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Chi data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Chi support is [0, ∞); got {x}"
                )));
            }
            sum2 += x * x;
            count += 1;
        }
        let df = sum2 / count as f64;
        if df <= 0.0 || !df.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Chi MoM produced non-positive df: {df}"
            )));
        }
        Ok(Self { df })
    }
}

/// Rice distribution.
///
/// Matches `scipy.stats.rice`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rice {
    pub b: f64, // non-centrality parameter
}

impl Rice {
    #[must_use]
    pub fn new(b: f64) -> Self {
        assert!(b >= 0.0, "b must be non-negative");
        Self { b }
    }
}

impl ContinuousDistribution for Rice {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let b = self.b;
        // f(x) = x * exp(-(x² + b²)/2) * I₀(b*x)
        x * (-(x * x + b * b) / 2.0).exp() * modified_bessel_i(0.0, b * x)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(x) − (x²+b²)/2 + ln I₀(b·x), with ln I₀(z) = log_ive(0,z) + z;
        // finite far into the tail where the pdf's I₀(b·x) overflows. frankenscipy-7m3xk
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let b = self.b;
        let bx = b * x;
        x.ln() - (x * x + b * b) / 2.0 + fsci_special::log_ive_scalar(0.0, bx) + bx
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        // Rice² ~ noncentral χ²(2 dof, nc = b²): F_Rice(x) = F_ncx2(x²). This is
        // exact (= 1 − Q₁(b, x), Marcum Q) and replaces the fixed-grid Simpson
        // over the pdf, which carried a ~1e-7 error. frankenscipy-tvfae
        NoncentralChiSquared::new(2.0, self.b * self.b)
            .cdf(x * x)
            .clamp(0.0, 1.0)
    }

    fn mean(&self) -> f64 {
        // Closed form: m_1 = √(π/2) · L_{1/2}(−b²/2) with
        //   L_{1/2}(−w) = e^{−w/2} [(1+w) I_0(w/2) + w I_1(w/2)]
        // and w = b²/2, so w/2 = b²/4. The i0_scalar/i1_scalar helpers
        // return the *unscaled* Bessel I, so absorb the e^{−w/2} factor
        // by computing e^{−b²/4} · I_n(b²/4) directly.
        let w = self.b * self.b / 2.0;
        let z = w / 2.0;
        let damp = (-z).exp();
        let l_half =
            damp * ((1.0 + w) * fsci_special::i0_scalar(z) + w * fsci_special::i1_scalar(z));
        (PI / 2.0).sqrt() * l_half
    }

    fn var(&self) -> f64 {
        // m_2 = 2 + b² (X² is non-central χ²(2, b²) with mean 2 + b²).
        let m1 = self.mean();
        2.0_f64.mul_add(1.0, self.b * self.b) - m1 * m1
    }

    fn skewness(&self) -> f64 {
        // m_3 = 3 √(π/2) · L_{3/2}(−b²/2) with
        //   L_{3/2}(−w) = (2/3) e^{−w/2}
        //               · [(3/2 + 3w + w²) I_0(w/2) + (2+w)w I_1(w/2)].
        let w = self.b * self.b / 2.0;
        let z = w / 2.0;
        let damp = (-z).exp();
        let i0 = fsci_special::i0_scalar(z);
        let i1 = fsci_special::i1_scalar(z);
        let l_half = damp * ((1.0 + w) * i0 + w * i1);
        let l_3half =
            (2.0 / 3.0) * damp * (3.0_f64.mul_add(w, w.mul_add(w, 1.5)) * i0 + (2.0 + w) * w * i1);
        let m1 = (PI / 2.0).sqrt() * l_half;
        let m2 = 2.0 + self.b * self.b;
        let m3 = 3.0 * (PI / 2.0).sqrt() * l_3half;
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // m_4 = 8 + 8 b² + b⁴ (fourth moment of |Z + b|² for 2-vec Z).
        let w = self.b * self.b / 2.0;
        let z = w / 2.0;
        let damp = (-z).exp();
        let i0 = fsci_special::i0_scalar(z);
        let i1 = fsci_special::i1_scalar(z);
        let l_half = damp * ((1.0 + w) * i0 + w * i1);
        let l_3half =
            (2.0 / 3.0) * damp * (3.0_f64.mul_add(w, w.mul_add(w, 1.5)) * i0 + (2.0 + w) * w * i1);
        let m1 = (PI / 2.0).sqrt() * l_half;
        let m2 = 2.0 + self.b * self.b;
        let m3 = 3.0 * (PI / 2.0).sqrt() * l_3half;
        let b2 = self.b * self.b;
        let m4 = 8.0_f64.mul_add(b2, b2.mul_add(b2, 8.0));
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // No elementary closed form: −ln pdf = −ln x + (x² + b²)/2
        //                                      − ln I_0(b·x).
        // E[X²] = 2 + b² is closed; E[ln X] and E[ln I_0(bX)] need
        // quadrature. Integrate directly: h = ∫ −pdf(x)·ln pdf(x) dx.
        // The pdf decays as exp(−x²/2)·(thin polynomial), so [0, b+12]
        // is enough.
        let upper = (self.b + 12.0).max(20.0);
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            upper,
            2_048,
            1e-10,
            1e-10,
            8,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Standardized Rice (σ=1) has E[X²] = 2 + b².
        // Closed-form: b_hat = sqrt(max(0, sample_E[X²] - 2)).
        let mut sum2 = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Rice data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Rice support is [0, ∞); got {x}"
                )));
            }
            sum2 += x * x;
            count += 1;
        }
        let m2 = sum2 / count as f64;
        if m2 < 2.0 {
            return Err(FitError::UnsupportedData(format!(
                "Rice MoM (σ=1) requires sample E[x²] ≥ 2; got {m2}"
            )));
        }
        let b = (m2 - 2.0).sqrt();
        if !b.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Rice MoM produced non-finite b: {b}"
            )));
        }
        Ok(Self { b })
    }
}

/// Nakagami distribution.
///
/// Matches `scipy.stats.nakagami`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Nakagami {
    pub nu: f64, // shape parameter >= 0.5
}

impl Nakagami {
    #[must_use]
    pub fn new(nu: f64) -> Self {
        assert!(nu >= 0.5, "nu must be >= 0.5");
        Self { nu }
    }

    /// Log-density at many points, hoisting the `ln2 + ν·ln(ν) − lnΓ(ν)` lead term
    /// out of the per-point loop. Byte-identical to mapping `logpdf` (lead kept as
    /// the leading addends, same subtraction order); x≤0 delegates to `pdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let nu = self.nu;
        let lead = 2.0_f64.ln() + nu * nu.ln() - ln_gamma(nu);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return self.pdf(x).ln();
            }
            lead + (2.0 * nu - 1.0) * x.ln() - nu * x * x
        })
    }

    /// Density at many points; hoists the `2·ν^ν / Γ(ν)` coefficient like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let nu = self.nu;
        let coeff = 2.0 * nu.powf(nu) / ln_gamma(nu).exp();
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            coeff * x.powf(2.0 * nu - 1.0) * (-nu * x * x).exp()
        })
    }
}

impl ContinuousDistribution for Nakagami {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let nu = self.nu;
        2.0 * nu.powf(nu) / ln_gamma(nu).exp() * x.powf(2.0 * nu - 1.0) * (-nu * x * x).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln2 + ν·ln(ν) − lnΓ(ν) + (2ν−1)·ln(x) − ν·x²; finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let nu = self.nu;
        2.0_f64.ln() + nu * nu.ln() - ln_gamma(nu) + (2.0 * nu - 1.0) * x.ln() - nu * x * x
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        lower_regularized_gamma(self.nu, self.nu * x * x)
    }

    fn ppf(&self, q: f64) -> f64 {
        // x = sqrt(gammaincinv(nu, q)/nu); direct inverse vs bisection. frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        (fsci_special::gammaincinv_scalar(self.nu, q) / self.nu).sqrt()
    }

    fn isf(&self, q: f64) -> f64 {
        // sf(x)=Q(ν, ν·x²)=q ⇒ x=sqrt(gammainccinv(ν,q)/ν). The trait default
        // ppf(1−q)→gammaincinv near 1 is ill-conditioned (isf(1e-12) was ~8.5e-6
        // off scipy); gammainccinv is well-conditioned. frankenscipy-d2gag
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        (fsci_special::gammainccinv_scalar(self.nu, q) / self.nu).sqrt()
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log P(nu, nu·x²); finite in the left tail where P underflows. frankenscipy-s14mf
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_gammainc_scalar(self.nu, self.nu * x * x)
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival Q(nu, nu·x²). frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(self.nu, self.nu * x * x)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(nu, nu·x²); finite in the ultra-extreme tail. frankenscipy-pkaua
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammaincc_scalar(self.nu, self.nu * x * x)
    }

    fn mean(&self) -> f64 {
        ln_gamma(self.nu + 0.5).exp() / (self.nu.sqrt() * ln_gamma(self.nu).exp())
    }

    fn var(&self) -> f64 {
        let m = self.mean();
        1.0 - m * m
    }

    fn entropy(&self) -> f64 {
        // Derivation: Y = ν·X² ~ Gamma(ν, 1) so E[ln X] = (ψ(ν) − ln ν)/2.
        // The PDF gives −ln pdf = −ln 2 − ν ln ν + ln Γ(ν)
        //                        − (2ν − 1) ln x + ν x²; E[X²] = 1.
        // Combining:
        //   h(Nakagami(ν)) = −ln 2 + ln Γ(ν) − (ν − 1/2) ψ(ν)
        //                  − (1/2) ln ν + ν.
        let nu = self.nu;
        -2.0_f64.ln() + ln_gamma(nu) - (nu - 0.5) * fsci_special::digamma_scalar(nu) - 0.5 * nu.ln()
            + nu
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = Γ(ν+k/2)/Γ(ν) · ν^{-k/2}; m_2 = 1.
        // Evaluate in log space to stay stable across ν.
        let nu = self.nu;
        let lg_nu = ln_gamma(nu);
        let m1 = (ln_gamma(nu + 0.5) - lg_nu - 0.5 * nu.ln()).exp();
        let m3 = (ln_gamma(nu + 1.5) - lg_nu - 1.5 * nu.ln()).exp();
        let var = 1.0 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let nu = self.nu;
        let lg_nu = ln_gamma(nu);
        let m1 = (ln_gamma(nu + 0.5) - lg_nu - 0.5 * nu.ln()).exp();
        let m3 = (ln_gamma(nu + 1.5) - lg_nu - 1.5 * nu.ln()).exp();
        // m_4 = Γ(ν+2)/Γ(ν)/ν² = ν(ν+1)/ν² = (ν+1)/ν.
        let m4 = (nu + 1.0) / nu;
        let var = 1.0 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        // Setting d/dx [x^{2ν−1}·exp(−ν x²)] = 0 gives 2ν x² = 2ν − 1,
        // i.e. mode = √((2ν − 1)/(2ν)) = √((ν − 1/2)/ν). Constructor
        // requires ν ≥ 1/2, so the radicand is non-negative
        // (frankenscipy-rt24d).
        ((self.nu - 0.5) / self.nu).sqrt()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum1 = 0.0_f64;
        let mut sum2 = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Nakagami data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Nakagami support is [0, ∞); got {x}"
                )));
            }
            sum1 += x;
            sum2 += x * x;
            count += 1;
        }
        let n = count as f64;
        let mean = sum1 / n;
        let m2 = sum2 / n;
        if m2 <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "Nakagami MoM: sample E[x²]={m2} non-positive"
            )));
        }
        // Ω-invariant moment ratio:
        //   r = (E[X])² / E[X²] = Γ(ν+0.5)² / (Γ(ν)² · ν)
        // monotone-increasing in ν from 2/π at ν=0.5 to 1 as ν→∞.
        let target = (mean * mean) / m2;
        let ratio_of = |nu: f64| {
            let log_num = 2.0 * ln_gamma(nu + 0.5);
            let log_den = 2.0 * ln_gamma(nu) + nu.ln();
            (log_num - log_den).exp()
        };
        let mut lo = 0.5_f64;
        let mut hi = 50.0_f64;
        let r_lo = ratio_of(lo); // ≈ 0.6366
        let r_hi = ratio_of(hi); // ≈ 0.995
        if !(r_lo <= target && target <= r_hi) {
            return Err(FitError::NonConvergent(format!(
                "Nakagami MoM bracket failed: r({lo})={r_lo}, r({hi})={r_hi}, target={target}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let r_mid = ratio_of(mid);
            if (r_mid - target).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { nu: mid });
            }
            if r_mid < target {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self {
            nu: 0.5 * (lo + hi),
        })
    }
}

/// Log-logistic (Fisk) distribution.
///
/// Matches `scipy.stats.fisk`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Fisk {
    pub c: f64, // shape
}

impl Fisk {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for Fisk {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        // /mock-code-finder boundary [frankenscipy-zu96v]: at x=0 the
        // formula c·x^(c-1)/(1+x^c)² has a shape-dependent limit:
        //   c < 1 → +∞   (x^(c-1) diverges)
        //   c = 1 → 1    (constant numerator)
        //   c > 1 → 0    (x^(c-1) vanishes)
        // scipy.stats.fisk reports inf/1/0 in those regimes.
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.c < 1.0 {
                f64::INFINITY
            } else if self.c == 1.0 {
                1.0
            } else {
                0.0
            };
        }
        let c = self.c;
        if weibull_density_reuse() {
            let xc = x.powf(c);
            c * (xc / x) / (1.0 + xc).powi(2)
        } else {
            c * x.powf(c - 1.0) / (1.0 + x.powf(c)).powi(2)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) + (c−1)·ln(x) − 2·ln1p(x^c); finite in the power-law tail. The
        // shape-dependent x=0 limit is delegated to pdf. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let c = self.c;
        if weibull_density_reuse() {
            let lx = x.ln();
            c.ln() + (c - 1.0) * lx - 2.0 * (c * lx).exp().ln_1p()
        } else {
            c.ln() + (c - 1.0) * x.ln() - 2.0 * x.powf(c).ln_1p()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            1.0 / (1.0 + x.powf(-self.c))
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1/(1 + x^c); algebraically equal to 1−cdf but its power-law
        // tail no longer underflows to 0 for large x. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        1.0 / (1.0 + x.powf(self.c))
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = −ln(1 + x^c) = −ln1p(x^c); finite power-law tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        -x.powf(self.c).ln_1p()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        (q / (1.0 - q)).powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        if self.c > 1.0 {
            let b = PI / self.c;
            b / b.sin()
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        if self.c > 2.0 {
            let b = PI / self.c;
            2.0 * b / (2.0 * b).sin() - b * b / (b.sin() * b.sin())
        } else {
            f64::INFINITY
        }
    }

    fn entropy(&self) -> f64 {
        // h(Fisk(c)) = 2 − ln(c). Independent of scale (scale=1).
        2.0 - self.c.ln()
    }

    fn skewness(&self) -> f64 {
        // Raw moments via Euler reflection:
        //   m_k = B(1+k/c, 1−k/c) = (πk/c) / sin(πk/c)
        // Finite for c > k; skew requires c > 3.
        if self.c <= 3.0 {
            return f64::NAN;
        }
        let b = PI / self.c;
        let m1 = b / b.sin();
        let m2 = 2.0 * b / (2.0 * b).sin();
        let m3 = 3.0 * b / (3.0 * b).sin();
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.c <= 4.0 {
            return f64::NAN;
        }
        let b = PI / self.c;
        let m1 = b / b.sin();
        let m2 = 2.0 * b / (2.0 * b).sin();
        let m3 = 3.0 * b / (3.0 * b).sin();
        let m4 = 4.0 * b / (4.0 * b).sin();
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        // Fisk pdf = c·x^{c−1} / (1 + x^c)². d/dx ln pdf gives
        // x^c = (c − 1)/(c + 1), so mode = ((c−1)/(c+1))^{1/c} for c > 1;
        // for c ≤ 1 the pdf is monotone decreasing and the mode collapses
        // to the boundary 0 (frankenscipy-rt24d).
        if self.c > 1.0 {
            ((self.c - 1.0) / (self.c + 1.0)).powf(1.0 / self.c)
        } else {
            0.0
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Fisk data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Fisk support is [0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 1.0 || !mean.is_finite() {
            return Err(FitError::UnsupportedData(format!(
                "Fisk MoM (unit-scale) requires sample mean > 1; got {mean}"
            )));
        }
        // Mean(c) = π/(c · sin(π/c)) for c > 1, monotone-decreasing from
        // ∞ at c→1+ to 1 at c→∞. Bisect on c ∈ (1.001, 1e3).
        let mean_of = |c: f64| {
            let b = PI / c;
            b / b.sin()
        };
        let mut lo = 1.001_f64;
        let mut hi = 1.0e3_f64;
        let m_lo = mean_of(lo);
        let m_hi = mean_of(hi);
        if !(m_hi <= mean && mean <= m_lo) {
            return Err(FitError::NonConvergent(format!(
                "Fisk MoM bracket failed: mean({lo})={m_lo}, mean({hi})={m_hi}, target={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let m_mid = mean_of(mid);
            if (m_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if m_mid > mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }
}

/// Loguniform (reciprocal) distribution on [a, b].
///
/// Matches `scipy.stats.loguniform`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Loguniform {
    pub a: f64,
    pub b: f64,
}

impl Loguniform {
    #[must_use]
    pub fn new(a: f64, b: f64) -> Self {
        assert!(a > 0.0, "a must be positive");
        assert!(b > a, "b must be greater than a");
        Self { a, b }
    }
}

impl ContinuousDistribution for Loguniform {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < self.a || x > self.b {
            0.0
        } else {
            1.0 / (x * (self.b / self.a).ln())
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −ln(x) − ln(ln(b/a)) on [a,b]. frankenscipy-p82v7
        if x < self.a || x > self.b {
            return f64::NEG_INFINITY;
        }
        -x.ln() - (self.b / self.a).ln().ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= self.a {
            0.0
        } else if x >= self.b {
            1.0
        } else {
            (x / self.a).ln() / (self.b / self.a).ln()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.a;
        }
        if q == 1.0 {
            return self.b;
        }
        self.a * (self.b / self.a).powf(q)
    }

    fn mean(&self) -> f64 {
        (self.b - self.a) / (self.b / self.a).ln()
    }

    fn var(&self) -> f64 {
        let log_ratio = (self.b / self.a).ln();
        let m = self.mean();
        (self.b * self.b - self.a * self.a) / (2.0 * log_ratio) - m * m
    }

    fn entropy(&self) -> f64 {
        // h(Loguniform(a, b)) = ln(ln(b/a)) + (ln a + ln b)/2.
        let log_a = self.a.ln();
        let log_b = self.b.ln();
        (log_b - log_a).ln() + 0.5 * (log_a + log_b)
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = (b^k − a^k) / (k · log(b/a)), always finite
        // on the bounded support (a, b).
        let log_ratio = (self.b / self.a).ln();
        let mk = |k: i32| (self.b.powi(k) - self.a.powi(k)) / (f64::from(k) * log_ratio);
        let m1 = mk(1);
        let m2 = mk(2);
        let m3 = mk(3);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let log_ratio = (self.b / self.a).ln();
        let mk = |k: i32| (self.b.powi(k) - self.a.powi(k)) / (f64::from(k) * log_ratio);
        let m1 = mk(1);
        let m2 = mk(2);
        let m3 = mk(3);
        let m4 = mk(4);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn mode(&self) -> f64 {
        // Loguniform pdf 1/(x · ln(b/a)) is strictly decreasing on
        // [a, b], so the mode is the lower endpoint a (frankenscipy-rt24d).
        self.a
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Boundary MLE: a = min(x_i), b = max(x_i). The Loguniform PDF
        // 1/(x · ln(b/a)) is non-zero only on [a, b], so the likelihood is
        // strictly increasing as the support shrinks toward the observed
        // range — the minimum and maximum are the MLEs.
        let mut min_obs = f64::INFINITY;
        let mut max_obs = f64::NEG_INFINITY;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Loguniform data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Loguniform support is (0, ∞); got {x}"
                )));
            }
            if x < min_obs {
                min_obs = x;
            }
            if x > max_obs {
                max_obs = x;
            }
        }
        if min_obs >= max_obs {
            return Err(FitError::NonConvergent(format!(
                "Loguniform MLE: data has zero range (min={min_obs}, max={max_obs})"
            )));
        }
        Ok(Self {
            a: min_obs,
            b: max_obs,
        })
    }
}

// Discrete distributions: Zipf, Boltzmann, etc.

/// Zipf (zeta) distribution.
/// Truncated Zipf (Zipfian) distribution.
///
/// Matches `scipy.stats.zipfian(a, n)`. Resolves [frankenscipy-kv0cb].
/// Two parameters: shape `a > 0` and truncation `n ≥ 1`.
/// Support: k ∈ {1, …, n}. Distinct from `Zipf` (= scipy.stats.zipf,
/// infinite support).
///
///   pmf(k; a, n) = (1 / k^a) / Z
///   cdf(k; a, n) = Σ_{j=1..k} (1 / j^a) / Z
///   where Z = Σ_{j=1..n} 1 / j^a.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Zipfian {
    pub a: f64,
    pub n: u32,
}

impl Zipfian {
    #[must_use]
    pub fn new(a: f64, n: u32) -> Self {
        assert!(a > 0.0 && a.is_finite(), "a must be positive and finite");
        assert!(n >= 1, "n must be at least 1");
        Self { a, n }
    }

    #[inline]
    fn z(&self) -> f64 {
        let mut s = 0.0_f64;
        for j in 1..=self.n {
            s += (j as f64).powf(-self.a);
        }
        s
    }
}

impl DiscreteDistribution for Zipfian {
    fn pmf(&self, k: u64) -> f64 {
        if k == 0 || k > self.n as u64 {
            return 0.0;
        }
        (k as f64).powf(-self.a) / self.z()
    }

    fn logpmf(&self, k: u64) -> f64 {
        // −a·ln(k) − ln(Z); finite where pmf underflows. frankenscipy-7m3xk
        if k == 0 || k > self.n as u64 {
            return f64::NEG_INFINITY;
        }
        -self.a * (k as f64).ln() - self.z().ln()
    }

    fn cdf(&self, k: u64) -> f64 {
        if k == 0 {
            return 0.0;
        }
        let bound = k.min(self.n as u64);
        // Closed form via the Hurwitz-zeta generalized harmonic, matching scipy's
        // zipfian `_gen_harmonic`: H_{m,a} = Σ_{j=1}^m j^{-a} = ζ(a) − ζ(a, m+1), so
        // cdf(k) = H_{bound,a} / H_{n,a}. O(1) vs the O(k) partial sum — scipy's
        // zipfian.cdf is O(1) (Hurwitz zeta), so the sum left fsci O(k)-slower at
        // large k. Gated a>1 where ζ(a) and ζ(a,·) converge by their defining series;
        // a≤1 keeps the exact partial sum. frankenscipy-zipf-cdf-hurwitz
        if self.a > 1.0 {
            let za = riemann_zeta(self.a);
            let h_k = za - fsci_special::hurwitz_zeta(self.a, bound as f64 + 1.0);
            let h_n = za - fsci_special::hurwitz_zeta(self.a, self.n as f64 + 1.0);
            return (h_k / h_n).min(1.0);
        }
        let z = self.z();
        let mut acc = 0.0_f64;
        for j in 1..=bound {
            acc += (j as f64).powf(-self.a);
        }
        (acc / z).min(1.0)
    }

    fn mean(&self) -> f64 {
        // ⟨k⟩ = Σ k · k^(−a) / Z = Σ k^(1−a) / Z
        let z = self.z();
        let mut acc = 0.0_f64;
        for j in 1..=self.n {
            let jf = j as f64;
            acc += jf * jf.powf(-self.a);
        }
        acc / z
    }

    fn var(&self) -> f64 {
        // Var = ⟨k²⟩ − ⟨k⟩²
        let z = self.z();
        let mut e1 = 0.0_f64;
        let mut e2 = 0.0_f64;
        for j in 1..=self.n {
            let jf = j as f64;
            let p = jf.powf(-self.a) / z;
            e1 += jf * p;
            e2 += jf * jf * p;
        }
        (e2 - e1 * e1).max(0.0)
    }

    fn skewness(&self) -> f64 {
        // Bounded support [1, n] → direct E[X^k] sums are exact and
        // O(n) per moment. No elementary closed form for skewness here.
        let z = self.z();
        let (mut m1, mut m2, mut m3) = (0.0_f64, 0.0_f64, 0.0_f64);
        for j in 1..=self.n {
            let jf = j as f64;
            let p = jf.powf(-self.a) / z;
            m1 += jf * p;
            m2 += jf * jf * p;
            m3 += jf * jf * jf * p;
        }
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let z = self.z();
        let (mut m1, mut m2, mut m3, mut m4) = (0.0_f64, 0.0_f64, 0.0_f64, 0.0_f64);
        for j in 1..=self.n {
            let jf = j as f64;
            let p = jf.powf(-self.a) / z;
            m1 += jf * p;
            m2 += jf * jf * p;
            m3 += jf * jf * jf * p;
            m4 += jf * jf * jf * jf * p;
        }
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Zipfian on bounded support [1, n]: h = ln Z + a · ⟨ln k⟩
        //   pmf(k) = k^{-a} / Z, ln pmf = -a ln k - ln Z
        //   h = -Σ pmf · (-a ln k - ln Z) = a · Σ pmf · ln k + ln Z
        let z = self.z();
        let mut sum_ln = 0.0_f64;
        for j in 1..=self.n {
            let jf = j as f64;
            let p = jf.powf(-self.a) / z;
            sum_ln += p * jf.ln();
        }
        self.a * sum_ln + z.ln()
    }

    fn mode(&self) -> f64 {
        // Zipfian pmf ∝ k^{−a} on [1, n] is strictly decreasing in k for
        // every a > 0; mode at k=1 (frankenscipy-ckykz).
        1.0
    }
}

///
/// Matches `scipy.stats.zipf`.
pub struct Zipf {
    pub a: f64,
}

impl Zipf {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 1.0, "a must be > 1");
        Self { a }
    }

    /// PMF: P(X=k) = k^{-a} / zeta(a)
    pub fn pmf(&self, k: usize) -> f64 {
        if k == 0 {
            return 0.0;
        }
        (k as f64).powf(-self.a) / riemann_zeta(self.a)
    }

    /// CDF: sum of PMF from 1 to k.
    pub fn cdf(&self, k: usize) -> f64 {
        let z = riemann_zeta(self.a);
        let mut sum = 0.0;
        for i in 1..=k {
            sum += (i as f64).powf(-self.a);
        }
        (sum / z).min(1.0)
    }

    /// Mean: zeta(a-1)/zeta(a), exists for a > 2.
    pub fn mean(&self) -> f64 {
        if self.a > 2.0 {
            riemann_zeta(self.a - 1.0) / riemann_zeta(self.a)
        } else {
            f64::INFINITY
        }
    }
}

/// Helper: Riemann zeta function for real s > 1.
///
/// Delegates to `fsci_special::zeta_scalar`, which uses Euler-Maclaurin
/// summation. The previous local implementation truncated a direct
/// series at k=10000; for s near 1 the integral tail dominates and
/// truncation gave ~37% error at s=1.1 (frankenscipy-3u8ze).
fn riemann_zeta(s: f64) -> f64 {
    fsci_special::zeta_scalar(s)
}

/// Generic discrete distribution from custom PMF values.
///
/// Matches `scipy.stats.rv_discrete(values=(xk, pk))`.
#[derive(Debug, Clone)]
pub struct RvDiscrete {
    xk: Vec<f64>,
    pk: Vec<f64>,
    cdf_vals: Vec<f64>,
}

impl RvDiscrete {
    /// Create from support points xk and their probabilities pk.
    pub fn new(xk: Vec<f64>, pk: Vec<f64>) -> Self {
        assert_eq!(xk.len(), pk.len(), "xk and pk must have same length");
        assert!(!xk.is_empty(), "must have at least one value");

        let total: f64 = pk.iter().sum();
        let pk: Vec<f64> = pk.iter().map(|&p| p / total).collect();

        let mut indices: Vec<usize> = (0..xk.len()).collect();
        indices.sort_by(|&a, &b| xk[a].total_cmp(&xk[b]));

        let xk_sorted: Vec<f64> = indices.iter().map(|&i| xk[i]).collect();
        let pk_sorted: Vec<f64> = indices.iter().map(|&i| pk[i]).collect();

        let mut cdf_vals = Vec::with_capacity(pk_sorted.len());
        let mut cumsum = 0.0;
        for &p in &pk_sorted {
            cumsum += p;
            cdf_vals.push(cumsum.min(1.0));
        }

        Self {
            xk: xk_sorted,
            pk: pk_sorted,
            cdf_vals,
        }
    }

    /// Probability mass function.
    /// Probability mass at `x`, which must be EXACTLY a support point.
    ///
    /// scipy's `rv_discrete(values=(xk, pk)).pmf` matches exactly: with `xk = [1, 2, 3]`,
    /// `pmf(2.0)` is 0.3 while `pmf(2.0 + 5e-11)` is **0.0**. This used to match within
    /// `1e-10`, so it returned 0.3 for a point that is not in the support — assigning an
    /// atom's entire mass to a neighbour of it.
    ///
    /// Conforming input is unaffected: an exact support point compared with `==` is the same
    /// point the tolerance admitted.
    pub fn pmf(&self, x: f64) -> f64 {
        for (i, &xi) in self.xk.iter().enumerate() {
            if x == xi {
                return self.pk[i];
            }
        }
        0.0
    }

    /// Cumulative distribution function.
    pub fn cdf(&self, x: f64) -> f64 {
        let mut result = 0.0;
        for (i, &xi) in self.xk.iter().enumerate() {
            if xi <= x {
                result = self.cdf_vals[i];
            } else {
                break;
            }
        }
        result
    }

    /// Percent point function (inverse CDF).
    /// Percent-point function (inverse CDF): the smallest support point whose CDF reaches
    /// `q`.
    ///
    /// `q == 0.0` returns `xk[0] - 1.0`, one below the lower support bound. That is scipy's
    /// convention for DISCRETE distributions and it is not arbitrary: `ppf(q)` is
    /// `inf{x : cdf(x) >= q}`, and every point of the support already satisfies
    /// `cdf(x) >= 0`, so the infimum falls below the support entirely. Verified against
    /// scipy 1.17.1 across three supports — `[1,2,3]` gives 0.0, `[5,6,7]` gives 4.0,
    /// `[-2,0,4]` gives -3.0 — and the same rule already appears twice in this file, in
    /// `RandInt::ppf` (`low - 1`) and `LogSeries::ppf` (`0.0`, its support starting at 1).
    ///
    /// Without the special case the loop returned `xk[0]`, because `cdf_vals[0] >= 0.0` is
    /// trivially true — a point INSIDE the support for a quantile no outcome attains.
    ///
    /// `xk` is sorted ascending by the constructor, so `xk[0]` is the lower bound.
    pub fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.xk[0] - 1.0;
        }
        for (i, &cdf_val) in self.cdf_vals.iter().enumerate() {
            if cdf_val >= q {
                return self.xk[i];
            }
        }
        *self.xk.last().unwrap()
    }

    /// Expected value (mean).
    pub fn mean(&self) -> f64 {
        self.xk.iter().zip(&self.pk).map(|(&x, &p)| x * p).sum()
    }

    /// Variance.
    pub fn var(&self) -> f64 {
        let mu = self.mean();
        self.xk
            .iter()
            .zip(&self.pk)
            .map(|(&x, &p)| (x - mu).powi(2) * p)
            .sum()
    }

    /// Standard deviation.
    pub fn std(&self) -> f64 {
        self.var().sqrt()
    }

    /// Support points.
    pub fn support(&self) -> &[f64] {
        &self.xk
    }

    /// Probabilities.
    pub fn probs(&self) -> &[f64] {
        &self.pk
    }
}

/// Double Weibull distribution.
///
/// Matches `scipy.stats.dweibull`.
pub struct DoubleWeibull {
    pub c: f64,
}

impl DoubleWeibull {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for DoubleWeibull {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let c = self.c;
        0.5 * c * x.abs().powf(c - 1.0) * (-x.abs().powf(c)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(½c) + (c−1)·ln|x| − |x|^c; shape-dependent x=0 limit delegates. frankenscipy-p82v7
        if x == 0.0 {
            return self.pdf(x).ln();
        }
        let c = self.c;
        let ax = x.abs();
        (0.5 * c).ln() + (c - 1.0) * ax.ln() - ax.powf(c)
    }

    fn cdf(&self, x: f64) -> f64 {
        let c = self.c;
        if x < 0.0 {
            0.5 * (-(-x).powf(c)).exp()
        } else {
            1.0 - 0.5 * (-x.powf(c)).exp()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // x≥0: sf = ½·exp(−x^c) directly (the default 1−cdf collapses in the
        // right tail); x<0: 1 − ½·exp(−(−x)^c) by symmetry. frankenscipy-w3f6m
        let c = self.c;
        if x < 0.0 {
            1.0 - 0.5 * (-(-x).powf(c)).exp()
        } else {
            0.5 * (-x.powf(c)).exp()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let c = self.c;
        if q < 0.5 {
            // x < 0: CDF = 0.5*exp(-|x|^c), so |x| = (-ln(2q))^(1/c)
            -(-(2.0 * q).ln()).powf(1.0 / c)
        } else if q > 0.5 {
            // x >= 0: CDF = 1 - 0.5*exp(-x^c), so x = (-ln(2*(1-q)))^(1/c)
            (-(2.0 * (1.0 - q)).ln()).powf(1.0 / c)
        } else {
            0.0
        }
    }

    fn mean(&self) -> f64 {
        0.0 // symmetric about 0
    }

    fn var(&self) -> f64 {
        let c = self.c;
        ln_gamma(1.0 + 2.0 / c).exp() // Γ(1 + 2/c) for unit scale
    }

    fn skewness(&self) -> f64 {
        // Symmetric about 0 ⇒ all odd central moments vanish ⇒ skew = 0.
        0.0
    }

    fn entropy(&self) -> f64 {
        // DoubleWeibull is the symmetric reflection of Weibull(c):
        //   h(DoubleWeibull(c)) = h(Weibull(c)) + ln 2
        //                       = γ·(1 − 1/c) − ln(c) + 1 + ln 2.
        EULER_MASCHERONI * (1.0 - 1.0 / self.c) - self.c.ln() + 1.0 + 2.0_f64.ln()
    }

    fn kurtosis(&self) -> f64 {
        // X = ±Y, Y ~ Weibull(c). Even moments: m_2 = Γ(1+2/c),
        // m_4 = Γ(1+4/c); odd moments vanish. Excess kurt = m_4/m_2² − 3.
        let c = self.c;
        let m2 = ln_gamma(1.0 + 2.0 / c).exp();
        let m4 = ln_gamma(1.0 + 4.0 / c).exp();
        m4 / (m2 * m2) - 3.0
    }

    fn mode(&self) -> f64 {
        // For c > 1 the Weibull half has its maximum at ((c−1)/c)^{1/c};
        // for c ≤ 1 the pdf diverges at 0 (the only mode). The dweibull
        // density is the symmetrized version, so the global maxima are
        // at ±mode (returning the right-side root is the scipy convention;
        // we report 0 when both halves peak at the origin).
        if self.c > 1.0 {
            ((self.c - 1.0) / self.c).powf(1.0 / self.c)
        } else {
            0.0
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // DoubleWeibull is symmetric around 0 with PDF (c/2)·|x|^{c−1}·
        // exp(−|x|^c). The likelihood depends only on |x|, and |X|
        // ~ Weibull(c, 1), so the shape MLE is the standard-Weibull
        // shape MLE on the absolute values.
        validate_finite_fit_data(data, 2, "DoubleWeibull")?;
        let mut abs: Vec<f64> = Vec::with_capacity(data.len());
        for &x in data {
            let y = x.abs();
            if y <= 0.0 {
                return Err(FitError::UnsupportedData(
                    "DoubleWeibull fit requires every sample to be nonzero".to_owned(),
                ));
            }
            abs.push(y);
        }
        let c = fit_standard_weibull_shape_mle(&abs, "DoubleWeibull")?;
        Ok(Self { c })
    }
}

/// Double gamma distribution.
///
/// Matches `scipy.stats.dgamma`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DoubleGamma {
    pub a: f64,
}

impl DoubleGamma {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0, "a must be positive");
        Self { a }
    }

    /// Log-density at many points, hoisting `ln(½)` and `lnΓ(a)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (`ln(½)` leading, `lnΓ(a)`
    /// last subtraction); x==0 delegates to `pdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let ln_half = 0.5_f64.ln();
        let lg = ln_gamma(a);
        par_continuous_map_min(xs, 65536, |x| {
            if x == 0.0 {
                return self.pdf(x).ln();
            }
            let ax = x.abs();
            ln_half + (a - 1.0) * ax.ln() - ax - lg
        })
    }

    /// Density at many points; hoists `Γ(a) = exp(lnΓ(a))` (the divisor) like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let a = self.a;
        let gamma_a = ln_gamma(a).exp();
        par_continuous_map_min(xs, 65536, |x| {
            0.5 * x.abs().powf(a - 1.0) * (-x.abs()).exp() / gamma_a
        })
    }
}

impl ContinuousDistribution for DoubleGamma {
    fn pdf(&self, x: f64) -> f64 {
        0.5 * x.abs().powf(self.a - 1.0) * (-x.abs()).exp() / ln_gamma(self.a).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(½) + (a−1)·ln|x| − |x| − lnΓ(a); shape-dependent x=0 limit delegates. frankenscipy-p82v7
        if x == 0.0 {
            return self.pdf(x).ln();
        }
        let ax = x.abs();
        0.5_f64.ln() + (self.a - 1.0) * ax.ln() - ax - ln_gamma(self.a)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            0.5 * upper_regularized_gamma(self.a, -x)
        } else if x > 0.0 {
            0.5 + 0.5 * lower_regularized_gamma(self.a, x)
        } else {
            0.5
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // x>0: sf = ½·Q(a,x) directly (default 1−cdf collapses); x<0:
        // 1 − ½·Q(a,−x) by symmetry. frankenscipy-w3f6m
        if x < 0.0 {
            1.0 - 0.5 * upper_regularized_gamma(self.a, -x)
        } else if x > 0.0 {
            0.5 * upper_regularized_gamma(self.a, x)
        } else {
            0.5
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // x>0: log sf = −ln2 + log Q(a,x), finite where Q underflows; x≤0: sf is
        // O(1), so ln(sf) is well-conditioned. frankenscipy-pkaua
        if x > 0.0 {
            -std::f64::consts::LN_2 + fsci_special::log_gammaincc_scalar(self.a, x)
        } else {
            self.sf(x).ln()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        if q == 0.5 {
            return 0.0;
        }

        let target = if q < 0.5 {
            1.0 - 2.0 * q
        } else {
            2.0 * q - 1.0
        };
        let g = fsci_special::gammaincinv_scalar(self.a, target);
        if g.is_finite() && g >= 0.0 {
            if q < 0.5 { -g } else { g }
        } else {
            ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std())
        }
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        self.a * (self.a + 1.0)
    }

    fn skewness(&self) -> f64 {
        // X = ±Y, Y ~ Gamma(a, 1). Symmetric about 0 ⇒ skew = 0.
        0.0
    }

    fn entropy(&self) -> f64 {
        // DoubleGamma is the symmetric reflection of Gamma(a, 1):
        //   h(DoubleGamma(a)) = h(Gamma(a, 1)) + ln 2
        //                     = a + ln Γ(a) + (1 − a) ψ(a) + ln 2.
        self.a
            + ln_gamma(self.a)
            + (1.0 - self.a) * fsci_special::digamma_scalar(self.a)
            + 2.0_f64.ln()
    }

    fn kurtosis(&self) -> f64 {
        // Even moments: m_2 = a(a+1), m_4 = a(a+1)(a+2)(a+3).
        // Excess kurt = m_4/m_2² − 3 = (a+2)(a+3)/(a(a+1)) − 3.
        let a = self.a;
        (a + 2.0) * (a + 3.0) / (a * (a + 1.0)) - 3.0
    }

    fn mode(&self) -> f64 {
        // Gamma(a, 1) has mode at a − 1 for a ≥ 1; the dgamma symmetric
        // density therefore peaks at ±(a−1) for a > 1 and at the origin
        // for a ≤ 1 (where Gamma's pdf is monotone decreasing).
        if self.a > 1.0 { self.a - 1.0 } else { 0.0 }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "DoubleGamma data contains non-finite value: {x}"
                )));
            }
        }
        // DoubleGamma has mean = 0 and var = a(a+1). MoM: solve
        //   a² + a − sample_var = 0  ⟹  a = (−1 + √(1 + 4·var)) / 2
        // (the positive root, since a > 0). We use sample variance about
        // 0 (the population mean) — not about the sample mean — because
        // that is the moment the distribution actually defines.
        let n = data.len() as f64;
        let m2_about_zero: f64 = data.iter().map(|x| x * x).sum::<f64>() / n;
        if !m2_about_zero.is_finite() || m2_about_zero <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "DoubleGamma MoM: sample E[x²] {m2_about_zero} is non-positive"
            )));
        }
        let a = 0.5 * (-1.0 + (1.0 + 4.0 * m2_about_zero).sqrt());
        if !a.is_finite() || a <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "DoubleGamma MoM produced non-positive a: {a}"
            )));
        }
        Ok(Self { a })
    }
}

/// Skew-normal distribution with skewness parameter `a` (any finite real).
///
/// Matches `scipy.stats.skewnorm(a)`. Resolves [frankenscipy-cquzz].
/// Reduces to the standard normal at `a = 0`.
///
///   pdf(x; a) = 2 · φ(x) · Φ(a · x)
///   cdf(x; a) = Φ(x) − 2 · T(x, a)        (Owen's T)
///
/// Closed-form moments via δ = a / √(1 + a²):
///   mean        = δ · √(2/π)
///   var         = 1 − 2 δ² / π
///   skew        = (4 − π)/2 · (δ √(2/π))³ / (1 − 2δ²/π)^(3/2)
///   ex_kurt     = 2(π − 3) · (δ √(2/π))⁴ / (1 − 2δ²/π)²
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SkewNorm {
    pub a: f64,
}

impl SkewNorm {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a.is_finite(), "a must be finite, got {a}");
        Self { a }
    }

    fn delta(&self) -> f64 {
        self.a / (1.0 + self.a * self.a).sqrt()
    }

    /// Left-tail cdf for a > 0 by direct quadrature of the pdf, avoiding the
    /// catastrophic Φ(x) − 2·T(x,a) cancellation. The integrand
    /// 2·φ(t)·Φ(a·t) ∝ exp(−(1+a²)t²/2) is sharply peaked at the upper limit
    /// t = x, so a window of ~30 e-foldings below x captures the whole mass;
    /// beyond the f64 range the pdf underflows to 0 and the integral is 0 (as
    /// scipy returns). frankenscipy-qg05t
    fn left_tail_cdf_quadrature(&self, x: f64) -> f64 {
        let a = self.a;
        let c = 1.0 + a * a;
        let width = (30.0 / (c * x.abs())).clamp(0.05, 40.0);
        let lo = x - width;
        simpson_integrate_adaptive(
            |t| 2.0 * standard_normal_pdf(t) * standard_normal_cdf(a * t),
            lo,
            x,
            512,
            1.0e-10,
            0.0,
            16,
        )
        .clamp(0.0, 1.0)
    }
}

impl ContinuousDistribution for SkewNorm {
    fn pdf(&self, x: f64) -> f64 {
        // 2 · φ(x) · Φ(a · x). Clamp Φ to [0, 1] before multiplying:
        // standard_normal_cdf can drift slightly outside [0, 1] at
        // extreme arguments due to fp roundoff in the erf path,
        // which would yield a negative pdf. Resolves [frankenscipy-r7dbb].
        let phi = standard_normal_pdf(x);
        let big_phi = standard_normal_cdf(self.a * x).clamp(0.0, 1.0);
        2.0 * phi * big_phi
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln 2 + ln φ(x) + log Φ(a·x); the closed form stays finite in the tail
        // where the default ln(pdf) underflows (φ(x) → 0 by x≈39). log_ndtr keeps
        // the Φ factor accurate even for very negative a·x. frankenscipy.
        std::f64::consts::LN_2 - 0.5 * x * x - 0.5 * (2.0 * PI).ln()
            + fsci_special::log_ndtr_scalar(self.a * x)
    }

    fn cdf(&self, x: f64) -> f64 {
        // Φ(x) − 2 · T(x, a) where T is Owen's T.
        // For large |a|, the 10-pt Gauss-Legendre quadrature in
        // owens_t can lose precision and the result drifts slightly
        // outside [0, 1] — clamp to match scipy's np.clip(cdf, 0, 1).
        // Resolves [frankenscipy-r7dbb] (fuzz finding eb2vm).
        let cdf = (standard_normal_cdf(x) - 2.0 * fsci_special::owens_t_scalar(x, self.a))
            .clamp(0.0, 1.0);
        // In the LEFT tail with a > 0, Φ(x) and 2·T(x,a) are both tiny and nearly
        // equal, so their difference loses every significant digit — cdf(-8)
        // drifted ~200 orders of magnitude (8e-30 vs the true ~4e-241). scipy hits
        // the same wall and falls back to integrating the pdf when
        // `cdf < 1e-6 and a > 0` (skewnorm._cdf). Mirror that: recompute by direct
        // quadrature of 2·φ(t)·Φ(a·t), which has no cancellation. frankenscipy-qg05t
        if self.a > 0.0 && x < 0.0 && cdf < 1.0e-6 {
            return self.left_tail_cdf_quadrature(x);
        }
        cdf
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − [Φ(x) − 2T(x,a)] = Φ(−x) + 2T(x,a); both terms vanish directly
        // in the right tail instead of the default 1−cdf collapsing. frankenscipy-w3f6m
        let raw = standard_normal_cdf(-x) + 2.0 * fsci_special::owens_t_scalar(x, self.a);
        raw.clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // Bisection on the cdf (no clean closed-form inverse).
        ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std())
    }

    fn mean(&self) -> f64 {
        self.delta() * (2.0 / PI).sqrt()
    }

    fn var(&self) -> f64 {
        let d = self.delta();
        1.0 - 2.0 * d * d / PI
    }

    fn skewness(&self) -> f64 {
        let d = self.delta();
        let m = d * (2.0 / PI).sqrt();
        let v = 1.0 - 2.0 * d * d / PI;
        (4.0 - PI) / 2.0 * m.powi(3) / v.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let d = self.delta();
        let m = d * (2.0 / PI).sqrt();
        let v = 1.0 - 2.0 * d * d / PI;
        2.0 * (PI - 3.0) * m.powi(4) / v.powi(2)
    }

    fn entropy(&self) -> f64 {
        // No elementary closed form (the Φ(α·x) factor inside ln pdf
        // resists clean expectation). Direct adaptive Simpson with
        // gaussian-like tail decay on both sides.
        simpson_integrate_adaptive(
            |x| {
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            -20.0,
            20.0,
            2_048,
            1e-10,
            1e-10,
            8,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 3, "SkewNorm")?;
        let sample_skew = sample_standardized_skewness(data);
        if !sample_skew.is_finite() {
            return Err(FitError::NonConvergent(
                "SkewNorm fit needs positive sample variance".to_owned(),
            ));
        }
        if sample_skew.abs() < 1e-14 {
            return Ok(Self { a: 0.0 });
        }

        let max_skew = Self { a: 50.0 }.skewness();
        if sample_skew.abs() >= max_skew {
            return Err(FitError::NonConvergent(format!(
                "SkewNorm sample skew {sample_skew} exceeds standardized family range"
            )));
        }

        let target = sample_skew.abs();
        let mut lo = 0.0_f64;
        let mut hi = 50.0_f64;
        for _ in 0..80 {
            let mid = 0.5 * (lo + hi);
            if (Self { a: mid }).skewness() < target {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        let a = 0.5 * (lo + hi) * sample_skew.signum();
        Ok(Self { a })
    }
}

/// Wrapped Cauchy distribution on [0, 2π).
///
/// Matches `scipy.stats.wrapcauchy(c)` for the standard (loc=0, scale=1)
/// Skewed Cauchy distribution with skewness parameter `a ∈ (−1, 1)`.
///
/// Matches `scipy.stats.skewcauchy(a)`. Resolves [frankenscipy-5co7w].
/// Reduces to the standard Cauchy at `a = 0`. No finite moments
/// (heavy tails like Cauchy), so mean/var/skew/kurt remain NaN.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SkewCauchy {
    pub a: f64,
}

impl SkewCauchy {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a.abs() < 1.0, "a must be in (-1, 1), got {a}");
        Self { a }
    }
}

impl ContinuousDistribution for SkewCauchy {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let a = self.a;
        let scale = a * x.signum() + 1.0;
        1.0 / (PI * (x * x / (scale * scale) + 1.0))
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −ln(π) − ln(1 + x²/scale²), scale = a·sign(x)+1; heavy tail. frankenscipy-p82v7
        let scale = self.a * x.signum() + 1.0;
        -PI.ln() - (1.0 + x * x / (scale * scale)).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let a = self.a;
        if x <= 0.0 {
            (1.0 - a) / 2.0 + (1.0 - a) / PI * (x / (1.0 - a)).atan()
        } else {
            (1.0 - a) / 2.0 + (1.0 + a) / PI * (x / (1.0 + a)).atan()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let a = self.a;
        // Threshold cdf(0) = (1 - a) / 2.
        let half = (1.0 - a) / 2.0;
        if q < half {
            (PI / (1.0 - a) * (q - half)).tan() * (1.0 - a)
        } else {
            (PI / (1.0 + a) * (q - half)).tan() * (1.0 + a)
        }
    }

    fn mean(&self) -> f64 {
        // SkewCauchy has no finite mean — heavy tails like Cauchy.
        f64::NAN
    }

    fn var(&self) -> f64 {
        // No finite variance.
        f64::NAN
    }

    fn skewness(&self) -> f64 {
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // Skew-Cauchy(a) has the same differential entropy as the
        // standard Cauchy regardless of the skew parameter — the two
        // half-PDFs (with weights (1−a)/2 and (1+a)/2) compose to keep
        // the total surface measure invariant under the skew tilt.
        // scipy.stats.skewcauchy.entropy() = ln(4π) for every a ∈ (−1, 1).
        (4.0 * PI).ln()
    }
}

/// parameterization. The shape parameter `c ∈ [0, 1)` controls
/// concentration: c=0 is uniform on the circle, c→1 concentrates near 0.
///
///   pdf(x; c) = (1 − c²) / (2π · (1 + c² − 2c·cos(x)))   for x ∈ [0, 2π)
///   cdf(x; c) = (1/π) · arctan( ((1+c)/(1−c)) · tan(x/2) ) on (0, π);
///               1 − cdf(2π − x; c) on (π, 2π)
///   mean = π (median by symmetry; circular mean is 0)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct WrapCauchy {
    pub c: f64,
}

impl WrapCauchy {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!((0.0..1.0).contains(&c), "c must be in [0, 1), got {c}");
        Self { c }
    }
}

impl ContinuousDistribution for WrapCauchy {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if !(0.0..2.0 * PI).contains(&x) {
            return 0.0;
        }
        let c = self.c;
        let denom = 1.0 + c * c - 2.0 * c * x.cos();
        (1.0 - c * c) / (2.0 * PI * denom)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 2.0 * PI {
            return 1.0;
        }
        let c = self.c;
        let half_x = x / 2.0;
        // For c=0 the kernel reduces to uniform: F(x) = x/(2π).
        if c == 0.0 {
            return x / (2.0 * PI);
        }
        // Standard wrapped-Cauchy CDF on the half-circles, joined at π.
        let ratio = (1.0 + c) / (1.0 - c);
        if x <= PI {
            (1.0 / PI) * (ratio * half_x.tan()).atan()
        } else {
            // Use reflection symmetry around π.
            let y = 2.0 * PI - x;
            1.0 - (1.0 / PI) * (ratio * (y / 2.0).tan()).atan()
        }
    }

    fn mean(&self) -> f64 {
        // Median = π. The circular mean is 0; scipy returns π for the
        // linear mean of the support [0, 2π).
        PI
    }

    fn var(&self) -> f64 {
        // Linear variance over [0, 2π) — closed form depends on c via
        // ∫(x-π)² · pdf(x) dx; we report π²/3 as a fallback (uniform
        // variance) since scipy reports a tabulated value scipy users
        // rarely need. NaN signals "not exactly available" without
        // crashing the trait contract.
        f64::NAN
    }

    fn skewness(&self) -> f64 {
        // Linear higher moments of WrapCauchy aren't routinely
        // tabulated; scipy itself returns NaN. We do the same to
        // preserve trait-contract symmetry with var.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // h(WrapCauchy(c)) = ln(2π · (1 − c²)) for c ∈ [0, 1). c = 0
        // collapses to the uniform-on-[0, 2π) entropy ln(2π).
        (2.0 * PI * (1.0 - self.c * self.c)).ln()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 2, "WrapCauchy")?;
        let upper = 2.0 * PI;
        let mut cos_sum = 0.0_f64;
        for &x in data {
            if !(0.0..upper).contains(&x) {
                return Err(FitError::UnsupportedData(format!(
                    "WrapCauchy support is [0, 2π); got {x}"
                )));
            }
            cos_sum += x.cos();
        }
        let c = (cos_sum / data.len() as f64).clamp(0.0, 1.0 - f64::EPSILON);
        Ok(Self { c })
    }
}

/// Semicircular distribution on [-1, 1].
///
/// Matches `scipy.stats.semicircular`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Semicircular;

impl ContinuousDistribution for Semicircular {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x.abs() > 1.0 {
            0.0
        } else {
            2.0 / PI * (1.0 - x * x).sqrt()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(2/π) + ½·ln(1−x²) on [−1,1]. frankenscipy-p82v7
        if x.abs() > 1.0 {
            return f64::NEG_INFINITY;
        }
        (2.0 / PI).ln() + 0.5 * (1.0 - x * x).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= -1.0 {
            0.0
        } else if x >= 1.0 {
            1.0
        } else {
            0.5 + x * (1.0 - x * x).sqrt() / PI + x.asin() / PI
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return -1.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        // No closed form — use Newton with initial guess from arcsine approximation
        let mut x = (PI * (q - 0.5)).sin(); // rough initial guess
        for _ in 0..12 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).clamp(-1.0, 1.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        0.25 // 1/4
    }

    fn skewness(&self) -> f64 {
        // Semicircular is symmetric around 0.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.semicircular
        // reports excess kurtosis = -1.
        -1.0
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.semicircular
        // reports differential entropy = ln(π) − 1/2 ≈ 0.6447.
        PI.ln() - 0.5
    }

    // fit() inherits the trait default. Resolves [frankenscipy-paejq].

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| !(-1.0..=1.0).contains(&x)) {
            return Err(FitError::UnsupportedData(
                "Semicircular data must lie in [-1, 1]".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // Semicircular pdf = 2/π · √(1 − x²) on [−1, 1] peaks at the
        // centre (frankenscipy-tlw2q).
        0.0
    }
}

/// Cosine distribution on [-π, π].
///
/// Matches `scipy.stats.cosine`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CosineDistribution;

impl ContinuousDistribution for CosineDistribution {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x.abs() > PI {
            0.0
        } else {
            (1.0 + x.cos()) / (2.0 * PI)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(1 + cos x) − ln(2π) on [−π, π]. frankenscipy-p82v7
        if x.abs() > PI {
            return f64::NEG_INFINITY;
        }
        (1.0 + x.cos()).ln() - (2.0 * PI).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= -PI {
            0.0
        } else if x >= PI {
            1.0
        } else {
            (PI + x + x.sin()) / (2.0 * PI)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        // The support is finite ([-π, π]), so the default
        // ContinuousDistribution::ppf returning ±∞ at q=0/1 is wrong
        // here. Use bisection on the closed-form cdf — the derivative
        // 1+cos(x) vanishes at the endpoints so Newton overshoots,
        // but bisection always converges on a monotone cdf.
        // Resolves [frankenscipy-2zdyv].
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return -PI;
        }
        if q == 1.0 {
            return PI;
        }
        // g(x) = π + x + sin(x) − 2πq is increasing (g' = 1 + cos x ≥ 0) on
        // [−π, π] with g(−π) < 0 < g(π); Illinois converges superlinearly and
        // its bracket-preserving midpoint fallback stays robust where g' → 0 at
        // the endpoints (so it is never worse than the former 60-step bisection).
        let target = 2.0 * PI * q;
        let g = |x: f64| PI + x + x.sin() - target;
        illinois_root_increasing(g, -PI, PI, g(-PI), g(PI))
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        PI * PI / 3.0 - 2.0 // π²/3 - 2
    }

    fn skewness(&self) -> f64 {
        // CosineDistribution is symmetric around 0.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.cosine
        // reports excess kurtosis = -6·(π⁴ - 90)/(5·(π² - 6)²).
        let pi2 = PI * PI;
        let pi4 = pi2 * pi2;
        -6.0 * (pi4 - 90.0) / (5.0 * (pi2 - 6.0).powi(2))
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.cosine
        // reports differential entropy = ln(4π) − 1 ≈ 1.531.
        (4.0 * PI).ln() - 1.0
    }

    fn mode(&self) -> f64 {
        // Cosine pdf = (1 + cos x)/(2π) on [−π, π] peaks at x = 0
        // (frankenscipy-tlw2q).
        0.0
    }

    fn fit(_data: &[f64]) -> Self {
        Self
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x.abs() > PI) {
            return Err(FitError::UnsupportedData(
                "CosineDistribution data must lie in [-π, π]".to_owned(),
            ));
        }
        Ok(Self)
    }
}

/// Reciprocal (log-uniform on [a, b]) distribution.
/// Alias for Loguniform kept for compatibility.
///
/// Matches `scipy.stats.reciprocal`.
pub type Reciprocal = Loguniform;

/// Wald distribution (alias for Inverse Gaussian).
///
/// Matches `scipy.stats.wald`.
pub type Wald = InverseGaussian;

/// Erlang distribution: Gamma with integer shape.
///
/// Matches `scipy.stats.erlang`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Erlang {
    pub k: usize,
    pub rate: f64,
}

impl Erlang {
    #[must_use]
    pub fn new(k: usize, rate: f64) -> Self {
        assert!(k > 0, "k must be positive");
        assert!(rate > 0.0, "rate must be positive");
        Self { k, rate }
    }

    /// Log-density at many points, hoisting `k·ln(λ)` and `lnΓ(k)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (lead leading, lnΓ last
    /// subtraction); x≤0 delegates to `pdf`.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k = self.k as f64;
        let lambda = self.rate;
        let k_lnlambda = k * lambda.ln();
        let lg = ln_gamma(k);
        par_continuous_map_min(xs, 65536, |x| {
            if x <= 0.0 {
                return self.pdf(x).ln();
            }
            k_lnlambda + (k - 1.0) * x.ln() - lambda * x - lg
        })
    }

    /// Density at many points; hoists `λ^k` (the lead factor) and `Γ(k)` (the
    /// divisor) like [`logpdf_many`](Self::logpdf_many). Byte-identical to `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let k = self.k as f64;
        let lambda = self.rate;
        let coeff = lambda.powf(k);
        let gamma_k = ln_gamma(k).exp();
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            coeff * x.powf(k - 1.0) * (-lambda * x).exp() / gamma_k
        })
    }
}

impl ContinuousDistribution for Erlang {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let k = self.k as f64;
        let lambda = self.rate;
        lambda.powf(k) * x.powf(k - 1.0) * (-lambda * x).exp() / ln_gamma(k).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // k·ln(λ) + (k−1)·ln(x) − λx − lnΓ(k); finite in the tail; x≤0 delegates. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let k = self.k as f64;
        let lambda = self.rate;
        k * lambda.ln() + (k - 1.0) * x.ln() - lambda * x - ln_gamma(k)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        lower_regularized_gamma(self.k as f64, self.rate * x)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log P(k, rate·x); finite in the left tail where P underflows. frankenscipy-s14mf
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_gammainc_scalar(self.k as f64, self.rate * x)
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival Q(k, rate·x). frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(self.k as f64, self.rate * x)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(k, rate·x); finite in the ultra-extreme tail. frankenscipy-pkaua
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammaincc_scalar(self.k as f64, self.rate * x)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = P(k, rate*x), so rate*x = gammaincinv(k, q), x = gammaincinv(k, q) / rate
        let k = self.k as f64;
        let mut x = fsci_special::gammaincinv_scalar(k, q) / self.rate;
        if x <= 0.0 || (self.cdf(x) - q).abs() > 0.1 {
            return ppf_bisection(|v| self.cdf(v), q, self.mean(), self.std());
        }
        for _ in 0..8 {
            let err = self.cdf(x) - q;
            if err.abs() < 1e-14 {
                break;
            }
            let dx = self.pdf(x);
            if dx > 1e-30 {
                x = (x - err / dx).max(0.0);
            }
        }
        x
    }

    fn mean(&self) -> f64 {
        self.k as f64 / self.rate
    }

    fn var(&self) -> f64 {
        self.k as f64 / (self.rate * self.rate)
    }

    fn skewness(&self) -> f64 {
        // Erlang is Gamma with integer shape k; skew = 2/√k, scale-free.
        // (frankenscipy-6m3we)
        2.0 / (self.k as f64).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis = 6/k. (frankenscipy-6m3we)
        6.0 / (self.k as f64)
    }

    fn entropy(&self) -> f64 {
        // Erlang(k, rate) is Gamma(k, scale=1/rate):
        //   h = k + ln Γ(k) + (1 − k) ψ(k) − ln(rate).
        let k = self.k as f64;
        k + ln_gamma(k) + (1.0 - k) * fsci_special::digamma_scalar(k) - self.rate.ln()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Method-of-moments: m = k/rate, v = k/rate², so rate = m/v and
        // k = m²/v rounded to the nearest positive integer.
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Erlang data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Erlang support is [0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let n = count as f64;
        let mean = sum / n;
        let mut variance = 0.0_f64;
        for &x in data {
            let d = x - mean;
            variance += d * d;
        }
        variance /= n;
        if variance <= 0.0 || !variance.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Erlang MoM: sample variance {variance} is non-positive"
            )));
        }
        let rate = mean / variance;
        if !rate.is_finite() || rate <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "Erlang MoM produced non-positive rate: {rate}"
            )));
        }
        let k_real = mean * mean / variance;
        let k = (k_real.round() as i64).max(1) as usize;
        Ok(Self { k, rate })
    }

    fn mode(&self) -> f64 {
        // Erlang(k, rate) is Gamma(k, 1/rate); pdf ∝ x^{k−1}·e^{−rate·x}
        // peaks at (k − 1)/rate for k ≥ 1, else at the boundary 0
        // (frankenscipy-tlw2q).
        if self.k >= 1 {
            (self.k as f64 - 1.0) / self.rate
        } else {
            0.0
        }
    }
}

/// Anglit distribution on [-π/4, π/4].
///
/// Matches `scipy.stats.anglit`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Anglit;

impl ContinuousDistribution for Anglit {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let quarter_pi = PI / 4.0;
        if x.abs() > quarter_pi {
            0.0
        } else {
            (2.0 * x).cos()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(cos 2x) on [−π/4, π/4]. frankenscipy-p82v7
        if x.abs() > PI / 4.0 {
            return f64::NEG_INFINITY;
        }
        (2.0 * x).cos().ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let quarter_pi = PI / 4.0;
        if x <= -quarter_pi {
            0.0
        } else if x >= quarter_pi {
            1.0
        } else {
            ((2.0 * x).sin() + 1.0) / 2.0
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return -PI / 4.0;
        }
        if q == 1.0 {
            return PI / 4.0;
        }
        // CDF = (sin(2x)+1)/2, so x = asin(2q-1)/2
        (2.0 * q - 1.0).asin() / 2.0
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        PI * PI / 16.0 - 0.5 // π²/16 - 1/2
    }

    fn skewness(&self) -> f64 {
        // Anglit is symmetric around 0 → odd central moments vanish.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-a1kjq]: scipy.stats.anglit
        // reports excess kurtosis = -2(π⁴ - 96)/(π² - 8)².
        let pi2 = PI * PI;
        let pi4 = pi2 * pi2;
        -2.0 * (pi4 - 96.0) / (pi2 - 8.0).powi(2)
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-a1kjq]: scipy.stats.anglit
        // reports differential entropy = 1 − ln(2).
        1.0 - 2.0_f64.ln()
    }

    fn fit(_data: &[f64]) -> Self {
        Self
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        let quarter_pi = PI / 4.0;
        if data.iter().any(|&x| x.abs() > quarter_pi) {
            return Err(FitError::UnsupportedData(
                "Anglit data must lie in [-π/4, π/4]".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // Anglit pdf = sin(2(x + π/4)) on [−π/4, π/4]; peaks at the
        // centre x = 0 (frankenscipy-tlw2q).
        0.0
    }
}

/// Bradford distribution on [0, 1] with shape c.
///
/// Matches `scipy.stats.bradford`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Bradford {
    pub c: f64,
}

impl Bradford {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for Bradford {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if !(0.0..=1.0).contains(&x) {
            0.0
        } else {
            self.c / ((1.0 + self.c * x) * (1.0 + self.c).ln())
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) − ln(1+c·x) − ln(ln(1+c)) on [0,1]. frankenscipy-p82v7
        if !(0.0..=1.0).contains(&x) {
            return f64::NEG_INFINITY;
        }
        self.c.ln() - (1.0 + self.c * x).ln() - (1.0 + self.c).ln().ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else if x >= 1.0 {
            1.0
        } else {
            (1.0 + self.c * x).ln() / (1.0 + self.c).ln()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        ((1.0 + self.c).powf(q) - 1.0) / self.c
    }

    fn mean(&self) -> f64 {
        let k = (1.0 + self.c).ln();
        (self.c - k) / (self.c * k)
    }

    fn var(&self) -> f64 {
        let c = self.c;
        let k = (1.0 + c).ln();
        let m = self.mean();
        // E[X²] = (c² - 2c + 2k) / (2c²k), derived from ∫₀¹ x²·c/((1+cx)·k) dx
        let ex2 = (c * c - 2.0 * c + 2.0 * k) / (2.0 * c * c * k);
        ex2 - m * m
    }

    fn entropy(&self) -> f64 {
        // h(Bradford(c)) = K/2 − ln(c/K) where K = log(1 + c).
        let k = (1.0 + self.c).ln();
        0.5 * k - (self.c / k).ln()
    }

    fn skewness(&self) -> f64 {
        // Raw moments via u = 1 + cx substitution. Closed-form
        // polynomial expressions (derived by expanding (u−1)^k / u and
        // integrating over [1, 1+c]):
        //   c K m_1 = c − K
        //   c² K m_2 = c²/2 − c + K
        //   c³ K m_3 = c³/3 − c²/2 + c − K
        //   c⁴ K m_4 = c⁴/4 − c³/3 + c²/2 − c + K
        // where K = log(1+c).
        let c = self.c;
        let k = (1.0 + c).ln();
        let c2 = c * c;
        let c3 = c2 * c;
        let m1 = (c - k) / (c * k);
        let m2 = (c2 / 2.0 - c + k) / (c2 * k);
        let m3 = (c3 / 3.0 - c2 / 2.0 + c - k) / (c3 * k);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let c = self.c;
        let k = (1.0 + c).ln();
        let c2 = c * c;
        let c3 = c2 * c;
        let c4 = c2 * c2;
        let m1 = (c - k) / (c * k);
        let m2 = (c2 / 2.0 - c + k) / (c2 * k);
        let m3 = (c3 / 3.0 - c2 / 2.0 + c - k) / (c3 * k);
        let m4 = (c4 / 4.0 - c3 / 3.0 + c2 / 2.0 - c + k) / (c4 * k);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Bradford data contains non-finite value: {x}"
                )));
            }
            if !(0.0..=1.0).contains(&x) {
                return Err(FitError::UnsupportedData(format!(
                    "Bradford data outside [0, 1]: {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        // Method-of-moments: E[X | c] = (c - ln(1+c)) / (c · ln(1+c)).
        // The mapping c ↦ E[X] is monotone DECREASING from 1/2 at c=0⁺ to 0 at c=∞.
        // Reject means outside the open interval (0, 0.5); endpoints map to
        // degenerate c (uniform-on-[0,1] for c→0; degenerate point mass at 0 for c→∞).
        if !(0.0..0.5).contains(&mean) {
            return Err(FitError::UnsupportedData(format!(
                "Bradford method-of-moments requires sample mean in (0, 0.5), got {mean}"
            )));
        }
        let mom = |c: f64| {
            // Use the small-c Taylor expansion to avoid catastrophic
            // cancellation in (c - ln(1+c)) when c is tiny. The exact
            // closed form is (c - ln1p(c)) / (c · ln1p(c)).
            if c < 1.0e-4 {
                // f(c) = 1/2 - c/6 + c²/24 - 19c³/720 + ...
                0.5 - c / 6.0 + c * c / 24.0 - 19.0 * c * c * c / 720.0
            } else {
                let k = c.ln_1p();
                (c - k) / (c * k)
            }
        };
        // Bisection on c ∈ (1e-6, 1e6]. f(low) > mean > f(high) by monotonicity.
        let mut lo = 1.0e-6_f64;
        let mut hi = 1.0e6_f64;
        let f_lo = mom(lo);
        let f_hi = mom(hi);
        if !(f_hi <= mean && mean <= f_lo) {
            return Err(FitError::NonConvergent(format!(
                "Bradford bisection bracket failed: f(lo)={f_lo}, f(hi)={f_hi}, mean={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let f_mid = mom(mid);
            if (f_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if f_mid > mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }

    fn mode(&self) -> f64 {
        // Bradford pdf = c / ((1 + c·x) · ln(1 + c)) on [0, 1] is
        // strictly decreasing in x for c > 0, so the mode is the left
        // boundary 0 (frankenscipy-tlw2q).
        0.0
    }
}

/// Gilbrat distribution (log-normal with s=1).
///
/// `scipy.stats.gilbrat` was removed in scipy 1.17 in favour of the
/// canonical one-arg lognormal `scipy.stats.lognorm(s=1, scale=1)`.
/// The struct is kept here for backwards compatibility; the conformance
/// harness in `fsci-conformance/tests/diff_stats_gilbrat.rs` uses the
/// lognorm replacement as its oracle (frankenscipy-t2qia).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Gilbrat;

impl ContinuousDistribution for Gilbrat {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            (-0.5 * x.ln().powi(2)).exp() / (x * (2.0 * PI).sqrt())
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −½·(ln x)² − ln(x) − ½ln(2π); finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let lnx = x.ln();
        -0.5 * lnx * lnx - lnx - 0.5 * (2.0 * PI).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            standard_normal_cdf(x.ln())
        }
    }

    fn logcdf(&self, x: f64) -> f64 {
        // log Φ(ln x); finite in the left tail where Φ underflows to 0. frankenscipy-osnge
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        fsci_special::log_ndtr_scalar(x.ln())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Φ(−ln x) = ½·erfc(ln x/√2); direct so the right tail does not
        // collapse like the default 1−cdf. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        0.5 * fsci_special::erfc_scalar(x.ln() * FRAC_1_SQRT_2)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = log Φ(−ln x); finite in the ultra-extreme tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_ndtr_scalar(-x.ln())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = Φ(ln(x)), so ln(x) = ndtri(q), x = exp(ndtri(q))
        fsci_special::ndtri_scalar(q).exp()
    }

    fn mean(&self) -> f64 {
        std::f64::consts::E.sqrt() // exp(1/2)
    }

    fn var(&self) -> f64 {
        std::f64::consts::E * (std::f64::consts::E - 1.0) // e(e-1)
    }

    fn skewness(&self) -> f64 {
        // Gilbrat ≡ LogNormal(s=1) so ω = e^{s²} = e.
        // skew = (ω + 2)·sqrt(ω − 1) with ω = e.
        let e = std::f64::consts::E;
        (e + 2.0) * (e - 1.0).sqrt()
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis for LogNormal(s=1):
        //   e^{4s²} + 2 e^{3s²} + 3 e^{2s²} − 6
        // with s² = 1 this collapses to e⁴ + 2e³ + 3e² − 6.
        let e = std::f64::consts::E;
        let e2 = e * e;
        let e3 = e2 * e;
        let e4 = e2 * e2;
        2.0_f64.mul_add(e3, 3.0_f64.mul_add(e2, e4)) - 6.0
    }

    fn entropy(&self) -> f64 {
        // Gilbrat ≡ LogNormal(s=1, scale=1).  Closed form
        // h = 0.5 + 0.5·ln(2π·s²) + ln(scale) reduces to 0.5 + 0.5·ln(2π).
        0.5 + 0.5 * (2.0 * PI).ln()
    }

    // fit() inherits the trait default. Resolves [frankenscipy-paejq].

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x <= 0.0) {
            return Err(FitError::UnsupportedData(
                "Gilbrat support is (0, ∞)".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn mode(&self) -> f64 {
        // Gilbrat is LogNormal(μ=0, σ=1); LogNormal(μ, σ).mode = exp(μ − σ²).
        // Here μ = 0, σ = 1 so mode = e^{−1} (frankenscipy-tlw2q).
        (-1.0_f64).exp()
    }
}

/// Levy distribution (one-sided stable with α=1/2, β=1).
///
/// Matches `scipy.stats.levy`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Levy {
    pub loc: f64,
    pub scale: f64,
}

impl Levy {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive");
        Self { loc, scale }
    }
}

impl Default for Levy {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl ContinuousDistribution for Levy {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = x - self.loc;
        if z <= 0.0 {
            return 0.0;
        }
        (self.scale / (2.0 * PI)).sqrt() * (-self.scale / (2.0 * z)).exp() / z.powf(1.5)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ½·ln(scale/2π) − scale/(2z) − 1.5·ln(z), z = x−loc. frankenscipy-p82v7
        let z = x - self.loc;
        if z <= 0.0 {
            return f64::NEG_INFINITY;
        }
        0.5 * (self.scale / (2.0 * PI)).ln() - self.scale / (2.0 * z) - 1.5 * z.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = x - self.loc;
        if z <= 0.0 {
            return 0.0;
        }
        fsci_special::erfc_scalar((self.scale / (2.0 * z)).sqrt())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − erfc(u) = erf(u), u = √(scale/(2(x−loc))); direct erf keeps
        // the slowly-decaying tail from collapsing once 1−erfc rounds to 0. frankenscipy-w3f6m
        let z = x - self.loc;
        if z <= 0.0 {
            return 1.0;
        }
        fsci_special::erf_scalar((self.scale / (2.0 * z)).sqrt())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.loc;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF(x) = erfc(sqrt(scale/(2*(x-loc))))
        // erfcinv(q) = sqrt(scale/(2*z)) where z = x - loc
        // z = scale / (2 * erfcinv(q)²)
        // erfcinv(q) = -ndtri(q/2) / sqrt(2)
        let erfcinv_q = -fsci_special::ndtri_scalar(q / 2.0) * FRAC_1_SQRT_2;
        if erfcinv_q <= 0.0 {
            return f64::INFINITY;
        }
        self.loc + self.scale / (2.0 * erfcinv_q * erfcinv_q)
    }

    fn mean(&self) -> f64 {
        f64::INFINITY
    }

    fn var(&self) -> f64 {
        f64::INFINITY
    }

    fn skewness(&self) -> f64 {
        // Levy is α = 1/2 stable: no finite moments at all.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // h(Levy(loc, scale)) = (1 + 3γ + ln(16π·scale²)) / 2. Mean/var
        // diverge but entropy is finite (well-known for α-stable laws).
        0.5 * (1.0 + 3.0 * EULER_MASCHERONI + (16.0 * PI * self.scale * self.scale).ln())
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Closed-form MLE with floc = 0. The log-likelihood
        //   ln L = (n/2) ln(scale) - (n/2) ln(2π) - (scale/2) Σ 1/x_i - (3/2) Σ ln(x_i)
        // has dL/dscale = n/(2 scale) - (1/2) Σ 1/x_i = 0
        // ⟹ scale = n / Σ 1/x_i (the harmonic mean of the observations).
        let mut reciprocal_sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Levy data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Levy MLE with floc=0 requires positive observations; got {x}"
                )));
            }
            reciprocal_sum += 1.0 / x;
            count += 1;
        }
        if reciprocal_sum <= 0.0 || !reciprocal_sum.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Levy MLE: reciprocal sum {reciprocal_sum} is non-positive or non-finite"
            )));
        }
        let scale = count as f64 / reciprocal_sum;
        if !scale.is_finite() || scale <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "Levy MLE produced non-positive scale: {scale}"
            )));
        }
        Ok(Self { loc: 0.0, scale })
    }

    fn mode(&self) -> f64 {
        // Solve d/dx ln pdf = 0 for Levy(loc, scale):
        //   −3/(2(x − loc)) + scale / (2(x − loc)²) = 0
        //   ⟹ x − loc = scale/3, so mode = loc + scale/3
        // (frankenscipy-tlw2q).
        self.loc + self.scale / 3.0
    }
}

/// Left-skewed Levy distribution.
///
/// Matches `scipy.stats.levy_l`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LevyLeft {
    pub loc: f64,
    pub scale: f64,
}

impl LevyLeft {
    #[must_use]
    pub fn new(loc: f64, scale: f64) -> Self {
        assert!(scale > 0.0, "scale must be positive");
        Self { loc, scale }
    }
}

impl Default for LevyLeft {
    fn default() -> Self {
        Self {
            loc: 0.0,
            scale: 1.0,
        }
    }
}

impl ContinuousDistribution for LevyLeft {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let z = self.loc - x;
        if z <= 0.0 {
            return 0.0;
        }
        (self.scale / (2.0 * PI)).sqrt() * (-self.scale / (2.0 * z)).exp() / z.powf(1.5)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ½·ln(scale/2π) − scale/(2z) − 1.5·ln(z), z = loc−x. frankenscipy-p82v7
        let z = self.loc - x;
        if z <= 0.0 {
            return f64::NEG_INFINITY;
        }
        0.5 * (self.scale / (2.0 * PI)).ln() - self.scale / (2.0 * z) - 1.5 * z.ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        let z = self.loc - x;
        if z <= 0.0 {
            return 1.0;
        }
        fsci_special::erf_scalar((self.scale / (2.0 * z)).sqrt())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − erf(u) = erfc(u), u = √(scale/(2(loc−x))); direct erfc keeps
        // the upper-tail (x→loc⁻) from collapsing when 1−erf rounds to 0. frankenscipy-w3f6m
        let z = self.loc - x;
        if z <= 0.0 {
            return 0.0;
        }
        fsci_special::erfc_scalar((self.scale / (2.0 * z)).sqrt())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return self.loc;
        }
        let z = fsci_special::ndtri_scalar((q + 1.0) / 2.0);
        self.loc - self.scale / (z * z)
    }

    fn mean(&self) -> f64 {
        f64::NEG_INFINITY
    }

    fn var(&self) -> f64 {
        f64::INFINITY
    }

    fn skewness(&self) -> f64 {
        // LevyLeft is α = 1/2 stable on the left tail: no finite moments.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // LevyLeft is the mirror of Levy across the location; entropy is
        // reflection-invariant.
        0.5 * (1.0 + 3.0 * EULER_MASCHERONI + (16.0 * PI * self.scale * self.scale).ln())
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Mirror of Levy::try_fit. With loc = 0 fixed, the support of LevyLeft
        // is x < 0; the MLE for scale is scale = n / Σ 1/(-x_i) (harmonic mean
        // of the negated observations).
        let mut reciprocal_sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "LevyLeft data contains non-finite value: {x}"
                )));
            }
            if x >= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "LevyLeft MLE with floc=0 requires negative observations; got {x}"
                )));
            }
            reciprocal_sum += 1.0 / (-x);
            count += 1;
        }
        if reciprocal_sum <= 0.0 || !reciprocal_sum.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "LevyLeft MLE: reciprocal sum {reciprocal_sum} is non-positive or non-finite"
            )));
        }
        let scale = count as f64 / reciprocal_sum;
        if !scale.is_finite() || scale <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "LevyLeft MLE produced non-positive scale: {scale}"
            )));
        }
        Ok(Self { loc: 0.0, scale })
    }

    fn mode(&self) -> f64 {
        // LevyLeft is the mirror of Levy through `loc`; its mode is
        // therefore loc − scale/3 (frankenscipy-tlw2q).
        self.loc - self.scale / 3.0
    }
}

/// Burr Type III distribution with shapes `c > 0`, `d > 0`.
///
/// Matches `scipy.stats.burr(c, d)`. Resolves [frankenscipy-wllk0].
/// Support: x > 0. (Distinct from `Burr12` / scipy.stats.burr12,
/// which is Type XII; the two families share names in the
/// literature but have inverse-related cdfs.)
///
///   pdf(x; c, d) = c · d · x^(−c − 1) · (1 + x^(−c))^(−d − 1)
///   cdf(x; c, d) = (1 + x^(−c))^(−d)
///   ppf(q; c, d) = (q^(−1/d) − 1)^(−1/c)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Burr3 {
    pub c: f64,
    pub d: f64,
}

impl Burr3 {
    #[must_use]
    pub fn new(c: f64, d: f64) -> Self {
        assert!(
            c > 0.0 && c.is_finite() && d > 0.0 && d.is_finite(),
            "c and d must be positive and finite"
        );
        Self { c, d }
    }
}

impl ContinuousDistribution for Burr3 {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 || !x.is_finite() {
            return 0.0;
        }
        let c = self.c;
        let d = self.d;
        let xnc = x.powf(-c);
        c * d * x.powf(-c - 1.0) * (1.0 + xnc).powf(-d - 1.0)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if !x.is_finite() {
            return 1.0;
        }
        let c = self.c;
        let d = self.d;
        let xnc = x.powf(-c);
        // Clamp: as x → ∞, x^(−c) → 0 and (1 + 0)^(−d) → 1; fp
        // can drift slightly above 1.
        (1.0 + xnc).powf(-d).clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − (1+x^{-c})^{-d} = −expm1(−d·ln1p(x^{-c})); stable as x→∞ where
        // (1+tiny)^{-d}→1 and the default 1−cdf collapses to 0. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        if !x.is_finite() {
            return 0.0;
        }
        -(-self.d * x.powf(-self.c).ln_1p()).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let c = self.c;
        let d = self.d;
        let inner = q.powf(-1.0 / d) - 1.0;
        if inner <= 0.0 {
            // q^(−1/d) → 1 from above as q → 1; underflow gives
            // 0 or negative, ppf diverges.
            return f64::INFINITY;
        }
        inner.powf(-1.0 / c)
    }

    fn mean(&self) -> f64 {
        // Closed form: E[X^k] = d · B(d + k/c, 1 − k/c), valid when k < c.
        // For mean (k=1) the existence condition is c > 1.
        // (frankenscipy-hoazz)
        if self.c <= 1.0 {
            return f64::NAN;
        }
        self.d * ln_beta(self.d + 1.0 / self.c, 1.0 - 1.0 / self.c).exp()
    }

    fn var(&self) -> f64 {
        if self.c <= 2.0 {
            return f64::NAN;
        }
        let m1 = self.d * ln_beta(self.d + 1.0 / self.c, 1.0 - 1.0 / self.c).exp();
        let m2 = self.d * ln_beta(self.d + 2.0 / self.c, 1.0 - 2.0 / self.c).exp();
        let v = m2 - m1 * m1;
        if v.is_finite() && v >= 0.0 {
            v
        } else {
            f64::NAN
        }
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = d · B(d + k/c, 1 − k/c), finite for c > k.
        if self.c <= 3.0 {
            return f64::NAN;
        }
        let (c, d) = (self.c, self.d);
        let mk = |k: f64| d * ln_beta(d + k / c, 1.0 - k / c).exp();
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.c <= 4.0 {
            return f64::NAN;
        }
        let (c, d) = (self.c, self.d);
        let mk = |k: f64| d * ln_beta(d + k / c, 1.0 - k / c).exp();
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let m4 = mk(4.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Compactify via u = arctan(x) ∈ (0, π/2): the 1/x^{cd+1}
        // tail decays slowly, so direct integration over a finite
        // range under-counts. Same trick as FoldedCauchy.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

/// Burr (Type XII) distribution.
///
/// Matches `scipy.stats.burr12`.
pub struct Burr12 {
    pub c: f64,
    pub d: f64,
}

impl Burr12 {
    #[must_use]
    pub fn new(c: f64, d: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        assert!(d > 0.0, "d must be positive");
        Self { c, d }
    }
}

impl ContinuousDistribution for Burr12 {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        // /mock-code-finder boundary [frankenscipy-27u2d]: at x=0 the
        // formula c·d·x^(c-1)/(1+x^c)^(d+1) has a c-dependent limit:
        //   c < 1 → +∞   (x^(c-1) diverges)
        //   c = 1 → d    (x^0 = 1, denom → 1)
        //   c > 1 → 0    (x^(c-1) vanishes)
        // scipy.stats.burr12 reports inf/d/0 in those regimes.
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.c < 1.0 {
                f64::INFINITY
            } else if self.c == 1.0 {
                self.d
            } else {
                0.0
            };
        }
        let c = self.c;
        let d = self.d;
        if weibull_density_reuse() {
            let xc = x.powf(c);
            c * d * (xc / x) / (1.0 + xc).powf(d + 1.0)
        } else {
            c * d * x.powf(c - 1.0) / (1.0 + x.powf(c)).powf(d + 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c)+ln(d)+(c−1)·ln(x) − (d+1)·ln1p(x^c); shape-dependent x=0 limit
        // delegates to pdf. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let c = self.c;
        let d = self.d;
        if weibull_density_reuse() {
            let lx = x.ln();
            c.ln() + d.ln() + (c - 1.0) * lx - (d + 1.0) * (c * lx).exp().ln_1p()
        } else {
            c.ln() + d.ln() + (c - 1.0) * x.ln() - (d + 1.0) * x.powf(c).ln_1p()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        1.0 - (1.0 + x.powf(self.c)).powf(-self.d)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = (1 + x^c)^{-d} directly; the default 1−cdf collapses to 0 once
        // the power-law tail drops below the f64 floor. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        (1.0 + x.powf(self.c)).powf(-self.d)
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = −d·ln1p(x^c); finite power-law tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        -self.d * x.powf(self.c).ln_1p()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = 1 - (1+x^c)^(-d), so x = ((1-q)^(-1/d) - 1)^(1/c)
        ((1.0 - q).powf(-1.0 / self.d) - 1.0).powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        if self.c * self.d > 1.0 {
            let c = self.c;
            let d = self.d;
            d * ln_gamma(d - 1.0 / c).exp() * ln_gamma(1.0 + 1.0 / c).exp()
                / ln_gamma(d + 1.0).exp()
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        let c = self.c;
        let d = self.d;
        if c * d <= 2.0 {
            return f64::NAN;
        }

        let mean = self.mean();
        let second_moment = d * ln_gamma(d - 2.0 / c).exp() * ln_gamma(1.0 + 2.0 / c).exp()
            / ln_gamma(d + 1.0).exp();
        second_moment - mean * mean
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = d · B(d − k/c, 1 + k/c), finite for cd > k.
        // Evaluate in log space via ln_gamma. Skew requires cd > 3.
        if self.c * self.d <= 3.0 {
            return f64::NAN;
        }
        let (c, d) = (self.c, self.d);
        let lg_d1 = ln_gamma(d + 1.0);
        let mk = |k: f64| (ln_gamma(d - k / c) + ln_gamma(1.0 + k / c) - lg_d1).exp() * d;
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.c * self.d <= 4.0 {
            return f64::NAN;
        }
        let (c, d) = (self.c, self.d);
        let lg_d1 = ln_gamma(d + 1.0);
        let mk = |k: f64| (ln_gamma(d - k / c) + ln_gamma(1.0 + k / c) - lg_d1).exp() * d;
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let m4 = mk(4.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Burr12 has 1/x^{cd+1} tail; compactify via u = arctan(x).
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

/// Log-Laplace distribution.
///
/// Matches `scipy.stats.loglaplace`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LogLaplace {
    pub c: f64,
}

impl LogLaplace {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for LogLaplace {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        // /mock-code-finder boundary [frankenscipy-27u2d]: at x=0 the
        // formula (c/2)·x^(c-1) has a c-dependent limit:
        //   c < 1 → +∞   (x^(c-1) diverges)
        //   c = 1 → 1/2  (x^0 = 1)
        //   c > 1 → 0    (x^(c-1) vanishes)
        // scipy.stats.loglaplace reports inf/0.5/0 in those regimes.
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.c < 1.0 {
                f64::INFINITY
            } else if self.c == 1.0 {
                0.5
            } else {
                0.0
            };
        }
        let c = self.c;
        if x < 1.0 {
            c / 2.0 * x.powf(c - 1.0)
        } else {
            c / 2.0 * x.powf(-c - 1.0)
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c/2) + (c−1)·ln(x) for x<1, + (−c−1)·ln(x) for x≥1; shape-dependent
        // x=0 limit delegates to pdf. frankenscipy-p82v7
        if x <= 0.0 {
            return self.pdf(x).ln();
        }
        let c = self.c;
        if x < 1.0 {
            (c / 2.0).ln() + (c - 1.0) * x.ln()
        } else {
            (c / 2.0).ln() + (-c - 1.0) * x.ln()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let c = self.c;
        if x < 1.0 {
            0.5 * x.powf(c)
        } else {
            1.0 - 0.5 * x.powf(-c)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = ½·x^{-c} for x≥1 (direct, so the power-law tail does not collapse
        // once 1−cdf underflows), and 1 − ½·x^c for 0<x<1. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let c = self.c;
        if x < 1.0 {
            1.0 - 0.5 * x.powf(c)
        } else {
            0.5 * x.powf(-c)
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let c = self.c;
        if q < 0.5 {
            // CDF = 0.5*x^c, so x = (2q)^(1/c)
            (2.0 * q).powf(1.0 / c)
        } else {
            // CDF = 1 - 0.5*x^(-c), so x = (2(1-q))^(-1/c)
            (2.0 * (1.0 - q)).powf(-1.0 / c)
        }
    }

    fn mean(&self) -> f64 {
        if self.c > 1.0 {
            self.c * self.c / (self.c * self.c - 1.0)
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        let c = self.c;
        if c > 2.0 {
            let second_moment = c * c / (c * c - 4.0);
            second_moment - self.mean().powi(2)
        } else {
            f64::INFINITY
        }
    }

    fn entropy(&self) -> f64 {
        // h(LogLaplace(c)) = 1 + ln(2/c) = 1 + ln 2 − ln c.
        1.0 + (2.0 / self.c).ln()
    }

    fn skewness(&self) -> f64 {
        // Symbolic ∫ x^k pdf(x) dx split at x = 1 gives
        //   m_k = c² / (c² − k²)
        // (finite when c > k). Skew requires c > 3.
        if self.c <= 3.0 {
            return f64::NAN;
        }
        let c2 = self.c * self.c;
        let m1 = c2 / (c2 - 1.0);
        let m2 = c2 / (c2 - 4.0);
        let m3 = c2 / (c2 - 9.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.c <= 4.0 {
            return f64::NAN;
        }
        let c2 = self.c * self.c;
        let m1 = c2 / (c2 - 1.0);
        let m2 = c2 / (c2 - 4.0);
        let m3 = c2 / (c2 - 9.0);
        let m4 = c2 / (c2 - 16.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut abs_log_sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "LogLaplace data contains non-finite value: {x}"
                )));
            }
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "LogLaplace data contains non-positive value: {x}"
                )));
            }
            // Skip x == 1.0 exactly: ln(1) = 0 contributes no information
            // and would otherwise need to be folded into one branch arbitrarily.
            // SciPy's MLE collapses to the same value because abs(ln(1)) = 0.
            abs_log_sum += x.ln().abs();
            count += 1;
        }
        if abs_log_sum == 0.0 {
            return Err(FitError::NonConvergent(
                "LogLaplace MLE undefined when all observations equal 1.0".to_string(),
            ));
        }
        // MLE: c_hat = n / sum |ln(x_i)|
        let c = count as f64 / abs_log_sum;
        if !c.is_finite() || c <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "LogLaplace MLE produced non-positive shape: {c}"
            )));
        }
        Ok(Self { c })
    }
}

/// Log-logistic distribution (Fisk).
///
/// Matches `scipy.stats.fisk` (sometimes called "log-logistic" or
/// "Fisk distribution"). Closed-form pdf and cdf:
///     pdf(x; c) = c · x^(c-1) / (1 + x^c)²,  x > 0
///     cdf(x; c) = x^c / (1 + x^c)
///     ppf(q; c) = (q / (1 - q))^(1/c)
///     median = 1 (independent of c)
///
/// Resolves [frankenscipy-ryd47].
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Loglogistic {
    pub c: f64,
}

impl Loglogistic {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for Loglogistic {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let c = self.c;
        let xc = x.powf(c);
        if weibull_density_reuse() {
            c * (xc / x) / ((1.0 + xc) * (1.0 + xc))
        } else {
            c * x.powf(c - 1.0) / ((1.0 + xc) * (1.0 + xc))
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) + (c−1)·ln(x) − 2·ln1p(x^c); finite in the power-law tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let c = self.c;
        if weibull_density_reuse() {
            let lx = x.ln();
            c.ln() + (c - 1.0) * lx - 2.0 * (c * lx).exp().ln_1p()
        } else {
            c.ln() + (c - 1.0) * x.ln() - 2.0 * x.powf(c).ln_1p()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let c = self.c;
        let xc = x.powf(c);
        xc / (1.0 + xc)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1/(1 + x^c); direct form avoids the 1−cdf tail collapse. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        1.0 / (1.0 + x.powf(self.c))
    }

    fn logsf(&self, x: f64) -> f64 {
        // log sf = −ln1p(x^c); finite power-law tail. frankenscipy-czegj
        if x <= 0.0 {
            return 0.0;
        }
        -x.powf(self.c).ln_1p()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        (q / (1.0 - q)).powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        // E[X] = π/c · 1/sin(π/c) for c > 1, else infinite.
        let c = self.c;
        if c > 1.0 {
            let theta = std::f64::consts::PI / c;
            theta / theta.sin()
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        // Var[X] = (2π/c)/sin(2π/c) − ((π/c)/sin(π/c))² for c > 2.
        let c = self.c;
        if c > 2.0 {
            let theta = std::f64::consts::PI / c;
            let two_theta = 2.0 * theta;
            let m1 = theta / theta.sin();
            let m2 = two_theta / two_theta.sin();
            m2 - m1 * m1
        } else {
            f64::INFINITY
        }
    }

    fn entropy(&self) -> f64 {
        // Loglogistic ≡ Fisk. Entropy h = 2 − ln(c).
        2.0 - self.c.ln()
    }

    fn skewness(&self) -> f64 {
        // Loglogistic ≡ Fisk: raw moments via Euler reflection,
        //   m_k = B(1 + k/c, 1 − k/c) = (πk/c) / sin(πk/c).
        // Skew finite for c > 3.
        if self.c <= 3.0 {
            return f64::NAN;
        }
        let theta = std::f64::consts::PI / self.c;
        let m1 = theta / theta.sin();
        let m2 = 2.0 * theta / (2.0 * theta).sin();
        let m3 = 3.0 * theta / (3.0 * theta).sin();
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.c <= 4.0 {
            return f64::NAN;
        }
        let theta = std::f64::consts::PI / self.c;
        let m1 = theta / theta.sin();
        let m2 = 2.0 * theta / (2.0 * theta).sin();
        let m3 = 3.0 * theta / (3.0 * theta).sin();
        let m4 = 4.0 * theta / (4.0 * theta).sin();
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() || x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Loglogistic data must be finite and positive: {x}"
                )));
            }
        }
        // Method-of-moments-via-quartiles: scipy's MLE has no closed
        // form, so we use the analytic relation between the log-logistic
        // quartile ratio Q3/Q1 and the shape parameter c. With pinned
        // ppf, Q1/Q3 = (1/3)^(1/c) / 3^(1/c) = (1/9)^(1/c), so
        // c = ln(9) / ln(Q3/Q1). Median is 1 by construction; this
        // matches scipy's default fixed-loc=0 fit signature.
        let mut sorted: Vec<f64> = data.to_vec();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = sorted.len();
        let q1 = sorted[(n / 4).max(1) - 1];
        let q3 = sorted[((3 * n) / 4).min(n - 1)];
        if q3 <= q1 || q1 <= 0.0 {
            return Err(FitError::NonConvergent(
                "Loglogistic quartile ratio is non-positive".to_string(),
            ));
        }
        let c = (9.0_f64).ln() / (q3 / q1).ln();
        if !c.is_finite() || c <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "Loglogistic shape estimate is non-positive: {c}"
            )));
        }
        Ok(Self { c })
    }
}

/// Mielke Beta-Kappa distribution.
///
/// Matches `scipy.stats.mielke`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Mielke {
    pub k: f64,
    pub s: f64,
}

impl Mielke {
    #[must_use]
    pub fn new(k: f64, s: f64) -> Self {
        assert!(k > 0.0 && s > 0.0, "k and s must be positive");
        Self { k, s }
    }
}

impl ContinuousDistribution for Mielke {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        // /mock-code-finder boundary [frankenscipy-zu96v]: at x=0 the
        // formula k·x^(k-1)/(1+x^s)^(1+k/s) has a shape-dependent
        // limit governed by k:
        //   k < 1 → +∞   (x^(k-1) diverges)
        //   k = 1 → 1    (constant numerator)
        //   k > 1 → 0    (x^(k-1) vanishes)
        // scipy.stats.mielke reports inf/1/0 in those regimes.
        if x < 0.0 {
            return 0.0;
        }
        if x == 0.0 {
            return if self.k < 1.0 {
                f64::INFINITY
            } else if self.k == 1.0 {
                1.0
            } else {
                0.0
            };
        }
        let k = self.k;
        let s = self.s;
        k * x.powf(k - 1.0) / (1.0 + x.powf(s)).powf(1.0 + k / s)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let xk = x.powf(self.k);
        xk / (1.0 + x.powf(self.s)).powf(self.k / self.s)
    }

    fn ppf(&self, q: f64) -> f64 {
        // cdf=(1+x^{-s})^{-k/s} ⇒ x=(q^{-s/k}−1)^{-1/s}; closed-form inverse. frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        (q.powf(-self.s / self.k) - 1.0).powf(-1.0 / self.s)
    }

    fn sf(&self, x: f64) -> f64 {
        // cdf = x^k/(1+x^s)^{k/s} ≡ (1+x^{-s})^{-k/s}, so
        // sf = 1 − (1+x^{-s})^{-k/s} = −expm1(−(k/s)·ln1p(x^{-s})) — stable in
        // the right tail where the default 1−cdf collapses. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        -(-(self.k / self.s) * x.powf(-self.s).ln_1p()).exp_m1()
    }

    fn mean(&self) -> f64 {
        if self.s <= 1.0 {
            return f64::INFINITY;
        }
        let log_moment = ln_gamma((self.k + 1.0) / self.s) + ln_gamma(1.0 - 1.0 / self.s)
            - ln_gamma(self.k / self.s);
        log_moment.exp()
    }

    fn var(&self) -> f64 {
        if self.s <= 2.0 {
            return f64::INFINITY;
        }
        let mean = self.mean();
        let log_second_moment = ln_gamma((self.k + 2.0) / self.s) + ln_gamma(1.0 - 2.0 / self.s)
            - ln_gamma(self.k / self.s);
        log_second_moment.exp() - mean * mean
    }

    fn skewness(&self) -> f64 {
        // Raw moments E[X^n] = Γ((k+n)/s) · Γ(1 − n/s) / Γ(k/s),
        // finite for s > n. Skew requires s > 3.
        if self.s <= 3.0 {
            return f64::NAN;
        }
        let (k, s) = (self.k, self.s);
        let lg_ks = ln_gamma(k / s);
        let mom = |n: f64| (ln_gamma((k + n) / s) + ln_gamma(1.0 - n / s) - lg_ks).exp();
        let m1 = mom(1.0);
        let m2 = mom(2.0);
        let m3 = mom(3.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.s <= 4.0 {
            return f64::NAN;
        }
        let (k, s) = (self.k, self.s);
        let lg_ks = ln_gamma(k / s);
        let mom = |n: f64| (ln_gamma((k + n) / s) + ln_gamma(1.0 - n / s) - lg_ks).exp();
        let m1 = mom(1.0);
        let m2 = mom(2.0);
        let m3 = mom(3.0);
        let m4 = mom(4.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Mielke has 1/x^{s+1} tail; compactify via arctan.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 4, "Mielke")?;
        for &x in data {
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Mielke support is (0, infinity); got {x}"
                )));
            }
        }
        let qs = quantile(data, &[0.25, 0.5, 0.75]);
        if qs.iter().any(|&x| x <= 0.0) || qs[0] >= qs[2] {
            return Err(FitError::NonConvergent(
                "Mielke fit needs positive non-degenerate quartiles".to_owned(),
            ));
        }

        let mut best = None::<(f64, f64, f64)>;
        for ki in 0..=195 {
            let k = 0.25 + 0.05 * ki as f64;
            for si in 0..=195 {
                let s = 0.25 + 0.05 * si as f64;
                let dist = Self { k, s };
                let c25 = dist.cdf(qs[0]);
                let c50 = dist.cdf(qs[1]);
                let c75 = dist.cdf(qs[2]);
                if !c25.is_finite() || !c50.is_finite() || !c75.is_finite() {
                    continue;
                }
                let error = (c25 - 0.25).powi(2) + (c50 - 0.5).powi(2) + (c75 - 0.75).powi(2);
                if best.is_none_or(|(_, _, best_error)| error < best_error) {
                    best = Some((k, s, error));
                }
            }
        }

        if let Some((k, s, _)) = best {
            Ok(Self { k, s })
        } else {
            Err(FitError::NonConvergent(
                "Mielke quantile fit did not find finite k/s".to_owned(),
            ))
        }
    }
}

/// Moyal distribution.
///
/// Matches `scipy.stats.moyal`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Moyal;

impl ContinuousDistribution for Moyal {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let inv_sqrt_2pi = 1.0 / (2.0 * PI).sqrt();
        inv_sqrt_2pi * (-0.5 * (x + (-x).exp())).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −½·ln(2π) − ½·(x + e^{−x}); finite in the right tail. frankenscipy-p82v7
        -0.5 * (2.0 * PI).ln() - 0.5 * (x + (-x).exp())
    }

    fn cdf(&self, x: f64) -> f64 {
        // F(x) = erfc(exp(-x/2) / √2) = erfc(√(exp(-x)/2))
        fsci_special::erfc_scalar(((-x).exp() / 2.0).sqrt())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − erfc(u) = erf(u), u = √(e^{-x}/2). The direct erf keeps the
        // right tail from collapsing (1 − erfc rounds to 0 for x ≳ 37,
        // moyal.sf(40) scipy ~1.1e-9). frankenscipy-w3f6m
        fsci_special::erf_scalar(((-x).exp() / 2.0).sqrt())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = erfc(sqrt(exp(-x)/2))
        // erfcinv(q) = sqrt(exp(-x)/2)
        // exp(-x) = 2 * erfcinv(q)^2
        // x = -ln(2 * erfcinv(q)^2)
        // erfcinv(q) = -ndtri(q/2) / sqrt(2)
        let erfcinv_q = -fsci_special::ndtri_scalar(q / 2.0) * FRAC_1_SQRT_2;
        if erfcinv_q <= 0.0 {
            return f64::INFINITY;
        }
        -(2.0 * erfcinv_q * erfcinv_q).ln()
    }

    fn mean(&self) -> f64 {
        0.577_215_664_901_532_9 + (2.0f64).ln() // γ + ln(2)
    }

    fn var(&self) -> f64 {
        PI * PI / 2.0
    }

    fn skewness(&self) -> f64 {
        // μ_3 = 14 · ζ(3), var = π²/2 → skew = 14·ζ(3) · 2^{3/2}/π³
        //                                    = 28√2 · ζ(3) / π³.
        const ZETA3: f64 = 1.202_056_903_159_594_3;
        28.0 * 2.0_f64.sqrt() * ZETA3 / (PI * PI * PI)
    }

    fn kurtosis(&self) -> f64 {
        // Excess kurtosis is exactly 4 for Moyal (well-known constant).
        4.0
    }

    fn entropy(&self) -> f64 {
        // h(Moyal) = E[−ln pdf] = (1/2) · ln(2π) + E[X]/2 + E[e^{−X}]/2.
        // E[X] = γ + ln 2; the substitution u = e^{−x}/2 collapses
        // E[e^{−X}] = 2^{3/2}·Γ(3/2)/√(2π) = 1 exactly. So
        //   h = (γ + 1 + ln(4π)) / 2.
        0.5 * (EULER_MASCHERONI + 1.0 + (4.0 * PI).ln())
    }

    fn fit(_data: &[f64]) -> Self {
        Self
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Moyal has unbounded support; only finite-value validation applies.
        validate_parameterless_fit_data(data)?;
        Ok(Self)
    }
}

/// Gompertz distribution.
///
/// Matches `scipy.stats.gompertz`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Gompertz {
    pub c: f64,
}

impl Gompertz {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }

    /// Raw moments m_1, m_2, m_3, m_4 via the substitution U = c(e^X − 1),
    /// which gives U ~ Exp(1) and X = log(1 + U/c). Then
    /// E[X^n] = ∫_0^∞ (log(1 + u/c))^n e^{−u} du, evaluated by composite
    /// Simpson's on [0, 35] (e^{−35} ≈ 6e-16). Closed forms exist only
    /// for the first moment (involving Ei); higher moments require
    /// special integrals, so we ship the numerical evaluation here.
    fn raw_moments_via_u_substitution(&self) -> [f64; 4] {
        let u_max = 35.0;
        let n_grid: usize = 10_000;
        let h = u_max / n_grid as f64;
        let mut m = [0.0_f64; 4];
        for i in 0..=n_grid {
            let u = i as f64 * h;
            let w = if i == 0 || i == n_grid {
                1.0
            } else if i % 2 == 0 {
                2.0
            } else {
                4.0
            };
            let lg = (1.0 + u / self.c).ln();
            let e_u = (-u).exp();
            let base = w * e_u;
            m[0] += base * lg;
            let lg2 = lg * lg;
            m[1] += base * lg2;
            m[2] += base * lg2 * lg;
            m[3] += base * lg2 * lg2;
        }
        let factor = h / 3.0;
        [m[0] * factor, m[1] * factor, m[2] * factor, m[3] * factor]
    }
}

impl ContinuousDistribution for Gompertz {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        // f(x; c) = c * exp(x) * exp(-c * (exp(x) - 1))
        self.c * x.exp() * (-self.c * (x.exp() - 1.0)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) + x − c·(e^x − 1); finite where pdf underflows. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        self.c.ln() + x - self.c * (x.exp() - 1.0)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        1.0 - (-self.c * (x.exp() - 1.0)).exp()
    }

    fn ppf(&self, q: f64) -> f64 {
        // Closed-form inverse x = ln(1 − ln(1−q)/c). frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        // Let a = -ln(1-q)/c (≥0, small for small q). x = ln(1+a) via ln_1p
        // keeps full precision; the outer (1.0 - ...).ln() cancelled
        // (ppf(1e-12) was 1.3e-4 off scipy). Matches scipy.stats.gompertz.ppf.
        let a = -(-q).ln_1p() / self.c;
        a.ln_1p()
    }

    fn isf(&self, q: f64) -> f64 {
        // sf(x)=exp(−c·(e^x−1))=q ⇒ x=ln(1 − ln q / c)=ln_1p(−ln q / c). The
        // trait default ppf(1−q) cancels 1−q for small q (isf(1e-12) was ~2.6e-7
        // off scipy). Matches scipy.stats.gompertz.isf. frankenscipy-d2gag
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        (-q.ln() / self.c).ln_1p()
    }

    fn sf(&self, x: f64) -> f64 {
        // Closed-form survival exp(−c(eˣ−1)) — the default 1−cdf returned 0 in
        // the tail (gompertz.sf(5,1) scipy 9.5e-65). frankenscipy-8y248
        if x <= 0.0 {
            return 1.0;
        }
        (-self.c * (x.exp() - 1.0)).exp()
    }

    fn mean(&self) -> f64 {
        -(self.c.exp() * fsci_special::expi_scalar(-self.c))
    }

    fn var(&self) -> f64 {
        let [_m1, m2, _m3, _m4] = self.raw_moments_via_u_substitution();
        let mean = self.mean();
        (m2 - mean * mean).max(0.0)
    }

    fn entropy(&self) -> f64 {
        // PDF: c · exp(x − c·(e^x − 1)), so −ln pdf = −ln c − x + c(e^x − 1).
        // Taking expectations under X ~ Gompertz(c) via the substitution
        // U = c(e^X − 1) ~ Exp(1):
        //   E[e^X] = 1 + 1/c   ⇒   c·(E[e^X] − 1) = 1.
        // So h(Gompertz(c)) = −ln c − E[X] + 1. The mean already uses
        // the exponential-integral closed form.
        -self.c.ln() - self.mean() + 1.0
    }

    fn skewness(&self) -> f64 {
        let [m1, m2, m3, _m4] = self.raw_moments_via_u_substitution();
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let [m1, m2, m3, m4] = self.raw_moments_via_u_substitution();
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "Gompertz data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "Gompertz support is [0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 0.0 || !mean.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "Gompertz MoM: sample mean {mean} non-positive"
            )));
        }
        // Mean(c) = -e^c · Ei(-c) is monotone-decreasing in c on (0, ∞).
        // Bisect on c ∈ (1e-6, 50). The upper bound is constrained by
        // numerical overflow: e^c · Ei(-c) blows past f64::MAX around
        // c ≈ 709 even though the product remains O(1/c). For c > 50 we
        // fall back to the asymptotic form mean ≈ 1/c which is accurate
        // to better than 1e-12 there.
        let mean_of = |c: f64| {
            if c > 50.0 {
                1.0 / c
            } else {
                -(c.exp() * fsci_special::expi_scalar(-c))
            }
        };
        let mut lo = 1.0e-6_f64;
        let mut hi = 1.0e6_f64;
        let m_lo = mean_of(lo);
        let m_hi = mean_of(hi);
        if !(m_hi <= mean && mean <= m_lo) {
            return Err(FitError::NonConvergent(format!(
                "Gompertz MoM bracket failed: mean({lo})={m_lo}, mean({hi})={m_hi}, target={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let m_mid = mean_of(mid);
            if (m_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if m_mid > mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }
}

/// Arcsine distribution on [0, 1].
///
/// Matches `scipy.stats.arcsine`. The arcsine distribution has PDF:
/// f(x) = 1 / (π * sqrt(x * (1-x))) for x in (0, 1)
///
/// This is a special case of the Beta distribution with α = β = 0.5.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Arcsine;

impl ContinuousDistribution for Arcsine {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        // /mock-code-finder boundary [frankenscipy-1w4wg]: scipy.stats.arcsine
        // returns +∞ at x=0 and x=1 (the limit of 1/(π·√(x(1-x)))).
        // The previous "x ≤ 0 || x ≥ 1 → 0" short-circuit silently
        // diverged from scipy at exactly those points.
        if !(0.0..=1.0).contains(&x) {
            return 0.0;
        }
        if x == 0.0 || x == 1.0 {
            return f64::INFINITY;
        }
        1.0 / (PI * (x * (1.0 - x)).sqrt())
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return 1.0;
        }
        2.0 / PI * x.sqrt().asin()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        // F(x) = 2/π * arcsin(sqrt(x))
        // q = 2/π * arcsin(sqrt(x))
        // arcsin(sqrt(x)) = q * π / 2
        // sqrt(x) = sin(q * π / 2)
        // x = sin²(q * π / 2)
        let s = (q * PI / 2.0).sin();
        s * s
    }

    fn mean(&self) -> f64 {
        0.5
    }

    fn var(&self) -> f64 {
        0.125 // 1/8
    }

    fn skewness(&self) -> f64 {
        // Arcsine is symmetric around 1/2.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.arcsine
        // reports excess kurtosis = -3/2.
        -1.5
    }

    fn entropy(&self) -> f64 {
        // /mock-code-finder for [frankenscipy-lud8x]: scipy.stats.arcsine
        // reports differential entropy = ln(π/4) ≈ -0.241564.
        (PI / 4.0).ln()
    }

    // fit() inherits the trait default. Resolves [frankenscipy-paejq].

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| !(0.0..=1.0).contains(&x)) {
            return Err(FitError::UnsupportedData(
                "Arcsine data must lie in [0, 1]".to_owned(),
            ));
        }
        Ok(Self)
    }
}

/// Generalized logistic distribution.
///
/// Matches `scipy.stats.genlogistic`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GenLogistic {
    pub c: f64,
}

impl GenLogistic {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for GenLogistic {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let c = self.c;
        c * (-x).exp() / (1.0 + (-x).exp()).powf(c + 1.0)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) − x − (c+1)·softplus(−x); stable softplus keeps both tails
        // finite where pdf underflows. frankenscipy-p82v7
        let c = self.c;
        let softplus_neg_x = if x <= 0.0 {
            -x + x.exp().ln_1p()
        } else {
            (-x).exp().ln_1p()
        };
        c.ln() - x - (c + 1.0) * softplus_neg_x
    }

    fn cdf(&self, x: f64) -> f64 {
        1.0 / (1.0 + (-x).exp()).powf(self.c)
    }

    fn logcdf(&self, x: f64) -> f64 {
        // ln cdf = −c·ln(1+e^{−x}) = −c·softplus(−x). The default ln(cdf)
        // returns −inf once cdf=(1+e^{−x})^{−c} underflows in the deep left
        // tail (genlogistic(2).logcdf(−700) was −inf vs −1400). frankenscipy-zghyi
        let neg_x = -x;
        let softplus = if neg_x > 0.0 {
            neg_x + (-neg_x).exp().ln_1p()
        } else {
            neg_x.exp().ln_1p()
        };
        -self.c * softplus
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − (1+e^{-x})^{-c} = −expm1(−c·ln1p(e^{-x})); stable in the
        // right tail where (1+tiny)^{-c}→1 and 1−cdf collapses. frankenscipy-w3f6m
        let u = (-x).exp();
        -(-self.c * u.ln_1p()).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // x = -ln(q^(-1/c) − 1). The naive q.powf(-1/c) − 1 cancels for q→1
        // (q^(-1/c) ≈ 1), so isf(q)=ppf(1−q) lost precision in the right tail
        // (~3.9e-6 off scipy at q=1e-12). q^(-1/c) − 1 = expm1(−ln(q)/c) is exact;
        // this matches scipy.stats.genlogistic.ppf (and isf via ppf(1−q))
        // bit-for-bit. frankenscipy-d2gag
        -((-q.ln() / self.c).exp_m1()).ln()
    }

    fn mean(&self) -> f64 {
        fsci_special::digamma_scalar(self.c) + EULER_MASCHERONI
    }

    fn var(&self) -> f64 {
        PI * PI / 6.0 + fsci_special::trigamma(self.c)
    }

    fn entropy(&self) -> f64 {
        // PDF = c·exp(−x)/(1+exp(−x))^{c+1}. Then
        //   −ln pdf = −ln c + x + (c+1) ln(1 + exp(−x)).
        // Mean E[X] = ψ(c) + γ; the substitution U = (1+e^{−X})^{−c}
        // gives U ~ Uniform(0,1) and ln(1+e^{−X}) = −ln U / c, so
        //   E[ln(1 + exp(−X))] = 1/c.
        // Therefore h = −ln c + ψ(c) + γ + 1 + 1/c.
        -self.c.ln() + fsci_special::digamma_scalar(self.c) + EULER_MASCHERONI + 1.0 + 1.0 / self.c
    }

    fn skewness(&self) -> f64 {
        // GenLogistic cumulants in terms of polygamma at c and at 1:
        //   κ_2 = ψ'(c) + ψ'(1) = trigamma(c) + π²/6
        //   κ_3 = ψ''(c) − ψ''(1) = tetragamma(c) − tetragamma(1)
        //   κ_4 = ψ'''(c) + ψ'''(1) = pentagamma(c) + pentagamma(1)
        // skew = κ_3 / κ_2^{3/2}.
        let mu2 = self.var();
        let kappa3 = fsci_special::tetragamma(self.c) - fsci_special::tetragamma(1.0);
        kappa3 / mu2.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // excess kurt = κ_4 / κ_2².
        let mu2 = self.var();
        let kappa4 = fsci_special::pentagamma(self.c) + fsci_special::pentagamma(1.0);
        kappa4 / (mu2 * mu2)
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "GenLogistic data contains non-finite value: {x}"
                )));
            }
        }
        // Method-of-moments: standardized mean = ψ(c) + γ. Sample mean
        // m_hat = (1/n) Σ x_i, then solve ψ(c) = m_hat - γ via bisection
        // (digamma is monotone increasing on (0, ∞)).
        let mean: f64 = data.iter().sum::<f64>() / data.len() as f64;
        let target = mean - EULER_MASCHERONI;
        // Bracket: ψ(1e-6) ≈ -1e6, ψ(1e6) ≈ ln(1e6) ≈ 13.8
        let mut lo = 1.0e-6_f64;
        let mut hi = 1.0e6_f64;
        let f_lo = fsci_special::digamma_scalar(lo);
        let f_hi = fsci_special::digamma_scalar(hi);
        if !(f_lo <= target && target <= f_hi) {
            return Err(FitError::NonConvergent(format!(
                "GenLogistic MoM bracket failed: ψ({lo})={f_lo}, ψ({hi})={f_hi}, target={target}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let f_mid = fsci_special::digamma_scalar(mid);
            if (f_mid - target).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if f_mid < target {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }
}

/// Frechet (right) distribution (Weibull maximum).
///
/// Matches `scipy.stats.frechet_r` / `scipy.stats.weibull_max`.
pub struct FrechetR {
    pub c: f64,
}

impl FrechetR {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for FrechetR {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x > 0.0 {
            return 0.0;
        }
        let ax = (-x).abs();
        self.c * weibull_pdf_shape(ax, self.c, weibull_density_reuse())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // Support x≤0; ln(c) + (c−1)·ln|x| − |x|^c. x≥0 (incl. shape-dependent
        // x=0 limit) delegates to pdf. frankenscipy-p82v7
        if x >= 0.0 {
            return self.pdf(x).ln();
        }
        let ax = (-x).abs();
        self.c.ln() + weibull_logpdf_shape(ax, self.c, weibull_density_reuse())
    }

    fn cdf(&self, x: f64) -> f64 {
        if x > 0.0 {
            return 1.0;
        }
        (-(-x).powf(self.c)).exp()
    }

    fn sf(&self, x: f64) -> f64 {
        // Support x≤0; sf = 1 − exp(−(−x)^c) = −expm1(−(−x)^c), stable as x→0⁻
        // where cdf→1 and the default 1−cdf collapses. frankenscipy-w3f6m
        if x >= 0.0 {
            return 0.0;
        }
        -(-((-x).powf(self.c))).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return 0.0;
        }
        // CDF = exp(-(-x)^c), so (-x)^c = -ln(q), x = -(-ln(q))^(1/c)
        -(-q.ln()).powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        -ln_gamma(1.0 + 1.0 / self.c).exp()
    }

    fn var(&self) -> f64 {
        let first = ln_gamma(1.0 + 1.0 / self.c).exp();
        let second = ln_gamma(1.0 + 2.0 / self.c).exp();
        second - first * first
    }

    fn entropy(&self) -> f64 {
        // FrechetR = -Y where Y ~ Weibull(c). Reflection preserves
        // entropy: h(FrechetR(c)) = h(Weibull(c)) = γ(1 - 1/c) - ln(c) + 1.
        EULER_MASCHERONI * (1.0 - 1.0 / self.c) - self.c.ln() + 1.0
    }

    fn skewness(&self) -> f64 {
        // FrechetR = -Y where Y ~ Weibull(c) (i.e. weibull_max). Raw
        // moments of Y are g_k = Γ(1 + k/c), so the negation flips the
        // sign of odd central moments and leaves even ones intact:
        // skew(X) = -skew(Y).
        let c = self.c;
        let g1 = ln_gamma(1.0 + 1.0 / c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / c).exp();
        let var = g2 - g1 * g1;
        let mu3_y = 2.0_f64.mul_add(g1.powi(3), g3 - 3.0 * g1 * g2);
        -mu3_y / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let c = self.c;
        let g1 = ln_gamma(1.0 + 1.0 / c).exp();
        let g2 = ln_gamma(1.0 + 2.0 / c).exp();
        let g3 = ln_gamma(1.0 + 3.0 / c).exp();
        let g4 = ln_gamma(1.0 + 4.0 / c).exp();
        let var = g2 - g1 * g1;
        let mu4 = (-3.0_f64).mul_add(
            g1.powi(4),
            6.0_f64.mul_add(g1 * g1 * g2, 4.0_f64.mul_add(-g1 * g3, g4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // FrechetR matches scipy's deprecated frechet_r alias of
        // weibull_max: support (−∞, 0] with the same standard-Weibull
        // pdf in y = −x. Re-use the shared MLE on negated data.
        validate_finite_fit_data(data, 2, "FrechetR")?;
        if let Some(&bad) = data.iter().find(|&&x| x > 0.0) {
            return Err(FitError::UnsupportedData(format!(
                "FrechetR support is (−∞, 0]; got {bad}"
            )));
        }
        let mut negated: Vec<f64> = Vec::with_capacity(data.len());
        for &x in data {
            let y = -x;
            if y <= 0.0 {
                return Err(FitError::UnsupportedData(
                    "FrechetR fit requires every sample to be strictly negative".to_owned(),
                ));
            }
            negated.push(y);
        }
        let c = fit_standard_weibull_shape_mle(&negated, "FrechetR")?;
        Ok(Self { c })
    }
}

/// Kolmogorov-Smirnov "n large" limiting distribution.
///
/// Matches `scipy.stats.kstwobign`. Resolves [frankenscipy-kfvg1].
/// Parameterless. Support: x ≥ 0.
///
/// Two complementary series, picked by x relative to the
/// Kolmogorov crossover at ≈ 1.18:
///
/// Large x (fast convergence for x ≳ 1.18):
///   pdf(x) = 8x · Σ_{k=1}^∞ (−1)^(k−1) · k² · exp(−2 k² x²)
///   cdf(x) = 1 + 2 · Σ_{k=1}^∞ (−1)^k · exp(−2 k² x²)
///
/// Small x (Jacobi theta dual; fast convergence for x ≲ 1.18):
///   cdf(x) = (√(2π)/x) · Σ_{k=1}^∞ exp(−c_k / x²),   c_k = (2k−1)² π² / 8
///   pdf(x) = (√(2π)/x⁴) · Σ_{k=1}^∞ (2 c_k − x²) · exp(−c_k / x²)
///
/// The dual form is essential for x ≲ 0.05 — the large-x series
/// barely decays in 50 terms there, leaving cdf(x) clamped to 1
/// instead of the correct ≈ 0 (caught by [frankenscipy-p1i9n]
/// fuzz round-trip).
///
/// Closed-form mean: √(π/2) · ln(2) ≈ 0.86873.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KsTwoBign;

const KSTWOBIGN_KMAX: u32 = 50;
const KSTWOBIGN_TOL: f64 = 1.0e-30;
// Kolmogorov-classic crossover. Both series converge to fp
// epsilon within a handful of terms at this x.
const KSTWOBIGN_THRESHOLD: f64 = 1.18;

pub(crate) fn kstwobign_pdf_large(x: f64) -> f64 {
    let mut sum = 0.0_f64;
    for k in 1..=KSTWOBIGN_KMAX {
        let kf = k as f64;
        let term = 8.0 * kf * kf * x * (-2.0 * kf * kf * x * x).exp();
        let signed = if k % 2 == 1 { term } else { -term };
        sum += signed;
        if term.abs() < KSTWOBIGN_TOL {
            break;
        }
    }
    sum.max(0.0)
}

pub(crate) fn kstwobign_cdf_large(x: f64) -> f64 {
    let mut sum = 0.0_f64;
    for k in 1..=KSTWOBIGN_KMAX {
        let kf = k as f64;
        let term = (-2.0 * kf * kf * x * x).exp();
        let signed = if k % 2 == 1 { -term } else { term };
        sum += signed;
        if term < KSTWOBIGN_TOL {
            break;
        }
    }
    (1.0 + 2.0 * sum).clamp(0.0, 1.0)
}

// Dual Jacobi-theta-form series: converges rapidly for small x
// where the large-x alternating series barely decays in 50 terms.
pub(crate) fn kstwobign_cdf_small(x: f64) -> f64 {
    let xsq = x * x;
    let inv_xsq = 1.0 / xsq;
    let mut sum = 0.0_f64;
    for k in 1..=KSTWOBIGN_KMAX {
        let m = (2 * k - 1) as f64;
        let c_k = m * m * PI * PI / 8.0;
        let exponent = -c_k * inv_xsq;
        if exponent < -700.0 {
            // exp will underflow to 0; safe to break.
            break;
        }
        let term = exponent.exp();
        sum += term;
        if term < KSTWOBIGN_TOL {
            break;
        }
    }
    let result = (2.0 * PI).sqrt() * sum / x;
    result.clamp(0.0, 1.0)
}

pub(crate) fn kstwobign_pdf_small(x: f64) -> f64 {
    let xsq = x * x;
    let xq4 = xsq * xsq;
    let inv_xsq = 1.0 / xsq;
    let mut sum = 0.0_f64;
    for k in 1..=KSTWOBIGN_KMAX {
        let m = (2 * k - 1) as f64;
        let c_k = m * m * PI * PI / 8.0;
        let exponent = -c_k * inv_xsq;
        if exponent < -700.0 {
            break;
        }
        let term = (2.0 * c_k - xsq) * exponent.exp();
        sum += term;
        // Sentinel: each successive term shrinks by exp(-Δc_k/x²)
        // which exceeds 1e-30 in magnitude well before the early break.
        if c_k > 80.0 * xsq && term.abs() < KSTWOBIGN_TOL {
            break;
        }
    }
    let result = (2.0 * PI).sqrt() * sum / xq4;
    result.max(0.0)
}

impl KsTwoBign {
    /// k-th raw moment via direct Simpson on [eps, 8]. The pdf has
    /// near-zero mass beyond x ≈ 5; capping at 8 leaves the truncation
    /// error well below 1e-12.
    fn kstwobign_raw_moment(&self, k: u32) -> f64 {
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                x.powi(k as i32) * self.pdf(x)
            },
            1e-12,
            8.0,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

impl ContinuousDistribution for KsTwoBign {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x < KSTWOBIGN_THRESHOLD {
            kstwobign_pdf_small(x)
        } else {
            kstwobign_pdf_large(x)
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x < KSTWOBIGN_THRESHOLD {
            kstwobign_cdf_small(x)
        } else {
            kstwobign_cdf_large(x)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        if x < KSTWOBIGN_THRESHOLD {
            // Small x: cdf is near 0, so 1 - cdf has no cancellation.
            return (1.0 - kstwobign_cdf_small(x)).clamp(0.0, 1.0);
        }
        // Large-x Kolmogorov survival series: sf = 2*sum_{k>=1} (-1)^(k-1)
        // e^{-2k^2 x^2}. The default 1 - cdf RE-cancels (cdf_large = 1 + 2*sum of
        // the same exp terms) and underflowed sf to exactly 0 by x~5
        // (scipy.kstwobign.sf(5)=3.86e-22) — and sf IS the KS-test p-value, so
        // the deep tail matters for significant results. Sum the series directly.
        let mut sum = 0.0_f64;
        for k in 1..=KSTWOBIGN_KMAX {
            let kf = k as f64;
            let term = (-2.0 * kf * kf * x * x).exp();
            sum += if k % 2 == 1 { term } else { -term };
            if term < KSTWOBIGN_TOL {
                break;
            }
        }
        (2.0 * sum).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // Illinois over the strictly-monotone cdf: g(x)=cdf(x)−q, g(0)=−q<0.
        let a = 0.0_f64;
        let mut b = 10.0_f64;
        let mut fb = self.cdf(b) - q;
        while fb < 0.0 && b.is_finite() {
            b *= 2.0;
            fb = self.cdf(b) - q;
        }
        illinois_root_increasing(|x| self.cdf(x) - q, a, b, -q, fb)
    }

    fn mean(&self) -> f64 {
        // √(π/2) · ln(2)
        (PI / 2.0).sqrt() * 2.0_f64.ln()
    }

    fn var(&self) -> f64 {
        // π²/12 − √(π/2)²·ln(2)² = π²/12 − (π/2)·ln²(2).
        //
        // Derivation: E[K²] = ∫_0^∞ 2x · P(K > x) dx
        //                  = ∫_0^∞ 2x · (1 − F(x)) dx
        // and a known identity (e.g. Marsaglia–Tsang–Wang 2003 and
        // Wikipedia) gives E[K²] = π²/12. Subtract mean² to get var.
        PI * PI / 12.0 - 0.5 * PI * 2.0_f64.ln().powi(2)
    }

    fn skewness(&self) -> f64 {
        // No clean elementary closed form; integrate x^k · pdf(x).
        let m1 = self.mean();
        let m2 = self.kstwobign_raw_moment(2);
        let m3 = self.kstwobign_raw_moment(3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.mean();
        let m2 = self.kstwobign_raw_moment(2);
        let m3 = self.kstwobign_raw_moment(3);
        let m4 = self.kstwobign_raw_moment(4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_parameterless_fit_data(data)?;
        if data.iter().any(|&x| x < 0.0) {
            return Err(FitError::UnsupportedData(
                "KsTwoBign data must be non-negative".to_owned(),
            ));
        }
        Ok(Self)
    }

    fn entropy(&self) -> f64 {
        // KsTwoBign pdf has near-zero mass beyond x ≈ 5; integrate
        // −pdf·ln pdf on [eps, 8] (same window as the raw_moment helper).
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            8.0,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

/// Reciprocal inverse Gaussian distribution with shape `mu > 0`.
///
/// Matches `scipy.stats.recipinvgauss(mu)`. Resolves [frankenscipy-k7e3h].
/// If Y ~ InverseGaussian(mu) then 1/Y ~ RecipInvGauss(mu).
///
///   pdf(x; μ) = 1/√(2π x) · exp(−(1 − μx)² / (2 μ² x))   for x ≥ 0
///   cdf(x; μ) = Φ(−(1/μ − x)/√x) − exp(2/μ) · Φ(−(1/μ + x)/√x)
///   sf(x; μ)  = Φ((1/μ − x)/√x) + exp(2/μ) · Φ(−(1/μ + x)/√x)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RecipInvGauss {
    pub mu: f64,
}

impl RecipInvGauss {
    #[must_use]
    pub fn new(mu: f64) -> Self {
        assert!(mu > 0.0 && mu.is_finite(), "mu must be positive and finite");
        Self { mu }
    }

    /// k-th raw moment via adaptive Simpson on a wide x window. The
    /// gaussian-like exp(−(1 − μx)²/(2 x μ²)) decay handles the tail.
    fn recip_inv_gauss_raw_moment(&self, k: u32) -> f64 {
        // Bulk lives around x ≈ 1/μ; the tail decays like x^{−1/2}·e^{−x/2}
        // (independent of μ), so the integrand x^k·pdf has its mass pushed out
        // by ~2k for higher moments. Scale the upper bound with BOTH μ (bulk)
        // and k (tail): the old fixed 40 truncated m3/m4, leaving skew/kurt
        // ~1e-5 short of scipy (k=4 error 8.9e-6 → ~5e-15). frankenscipy-xa0m5
        let upper = (40.0 + 20.0 * f64::from(k)).max(40.0 * self.mu);
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                x.powi(k as i32) * self.pdf(x)
            },
            1e-12,
            upper,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

impl ContinuousDistribution for RecipInvGauss {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let mu = self.mu;
        let log_pdf = -((1.0 - mu * x).powi(2)) / (2.0 * x * mu * mu) - 0.5 * (2.0 * PI * x).ln();
        log_pdf.exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // The pdf already forms this log expression then exp's it; expose it so
        // the tail stays finite where pdf underflows. frankenscipy-7m3xk
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let mu = self.mu;
        -((1.0 - mu * x).powi(2)) / (2.0 * x * mu * mu) - 0.5 * (2.0 * PI * x).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let mu = self.mu;
        let trm1 = 1.0 / mu - x;
        let trm2 = 1.0 / mu + x;
        let isqx = 1.0 / x.sqrt();
        // Clamp to [0, 1]: the difference of two Φ terms can drift
        // slightly outside the valid range for large mu (e.g.
        // RecipInvGauss(50).cdf(40.4) raw ≈ 1.00000000004).
        // Same defect class as SkewNorm.cdf (cc83022). Resolves
        // [frankenscipy-n82pr].
        (standard_normal_cdf(-isqx * trm1) - (2.0 / mu).exp() * standard_normal_cdf(-isqx * trm2))
            .clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 1.0;
        }
        let mu = self.mu;
        let trm1 = 1.0 / mu - x;
        let trm2 = 1.0 / mu + x;
        let isqx = 1.0 / x.sqrt();
        (standard_normal_cdf(isqx * trm1) + (2.0 / mu).exp() * standard_normal_cdf(-isqx * trm2))
            .clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // Illinois over the strictly-monotone cdf: g(x)=cdf(x)−q, g(0)=−q<0.
        // Bracket via mode-ish estimate; expand until cdf(b) ≥ q.
        let a = 0.0_f64;
        let mut b = (10.0 * self.mu).max(10.0);
        let mut fb = self.cdf(b) - q;
        while fb < 0.0 && b.is_finite() {
            b *= 2.0;
            fb = self.cdf(b) - q;
        }
        illinois_root_increasing(|x| self.cdf(x) - q, a, b, -q, fb)
    }

    fn mean(&self) -> f64 {
        // Closed form: E[X] = (1 + μ)/μ = 1/μ + 1 (frankenscipy-7um75).
        (1.0 + self.mu) / self.mu
    }

    fn var(&self) -> f64 {
        // Closed form: Var[X] = (1 + 2μ)/μ = 1/μ + 2 (frankenscipy-7um75).
        (1.0 + 2.0 * self.mu) / self.mu
    }

    fn skewness(&self) -> f64 {
        // RecipInvGauss has no elementary closed form for higher
        // moments. Integrate x^k · pdf(x) on a wide window — the pdf
        // has a Gaussian-like exp(−(1 − μx)²/(2 x μ²)) factor that
        // decays fast enough beyond x ≈ 10 · max(1/μ, 1).
        let m1 = self.mean();
        let m2 = m1 * m1 + self.var();
        let m3 = self.recip_inv_gauss_raw_moment(3);
        let var = self.var();
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.mean();
        let var = self.var();
        let m2 = m1 * m1 + var;
        let m3 = self.recip_inv_gauss_raw_moment(3);
        let m4 = self.recip_inv_gauss_raw_moment(4);
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Pdf has exp(−(1 − μ·x)²/(2 x μ²)) factor; decays fast enough
        // that a wide x window suffices.
        let upper = (40.0_f64).max(40.0 * self.mu);
        simpson_integrate_adaptive(
            |x| {
                if x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            upper,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 2, "RecipInvGauss")?;
        let mut reciprocal_sum = 0.0_f64;
        for &x in data {
            if x <= 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "RecipInvGauss support is (0, infinity); got {x}"
                )));
            }
            reciprocal_sum += 1.0 / x;
        }
        let mu = reciprocal_sum / data.len() as f64;
        if mu.is_finite() && mu > 0.0 {
            Ok(Self { mu })
        } else {
            Err(FitError::NonConvergent(format!(
                "RecipInvGauss reciprocal-mean fit produced invalid mu: {mu}"
            )))
        }
    }
}

/// Doubly-truncated Weibull minimum distribution on (a, b].
///
/// Matches `scipy.stats.truncweibull_min(c, a, b)` with shape
/// `c > 0` and bounds `0 ≤ a < b`. Resolves [frankenscipy-op097].
///
///   pdf(x; c, a, b) = c · x^(c−1) · exp(−x^c) / (exp(−a^c) − exp(−b^c))
///   cdf(x; c, a, b) = (exp(−a^c) − exp(−x^c)) / (exp(−a^c) − exp(−b^c))
///   ppf(q)          = (−ln(exp(−a^c) − q · denom))^(1/c)
///
/// where `denom = exp(−a^c) − exp(−b^c)`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TruncWeibullMin {
    pub c: f64,
    pub a: f64,
    pub b: f64,
}

impl TruncWeibullMin {
    #[must_use]
    pub fn new(c: f64, a: f64, b: f64) -> Self {
        assert!(c > 0.0 && c.is_finite(), "c must be positive and finite");
        assert!(a >= 0.0 && a.is_finite(), "a must be ≥ 0 and finite");
        assert!(b > a && b.is_finite(), "b must be > a and finite");
        Self { c, a, b }
    }
}

impl ContinuousDistribution for TruncWeibullMin {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if !(self.a < x && x <= self.b) {
            return 0.0;
        }
        // Rewrite as c·x^(c-1)·exp(a^c - x^c) / (-expm1(a^c - b^c))
        // to avoid underflow when both exp(-a^c) and exp(-b^c) are
        // tiny (e.g., c=10, a=10 → a^c = 1e10). The naive denom
        // exp(-a^c) - exp(-b^c) becomes 0/0 = NaN there.
        // Resolves [frankenscipy-li9bu] (fuzz finding kin4s).
        let ac = self.a.powf(self.c);
        let xc = x.powf(self.c);
        let bc = self.b.powf(self.c);
        let denom_log = -(ac - bc).exp_m1(); // 1 - exp(a^c - b^c) > 0
        self.c * x.powf(self.c - 1.0) * (ac - xc).exp() / denom_log
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= self.a {
            return 0.0;
        }
        if x >= self.b {
            return 1.0;
        }
        // expm1(a^c - x^c) / expm1(a^c - b^c) — both expm1 args
        // are non-positive so both are in (-1, 0]; the ratio is
        // in [0, 1]. This avoids the same underflow issue as pdf.
        let ac = self.a.powf(self.c);
        let xc = x.powf(self.c);
        let bc = self.b.powf(self.c);
        (ac - xc).exp_m1() / (ac - bc).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return self.a;
        }
        if q == 1.0 {
            return self.b;
        }
        // From the rewritten cdf: q · expm1(a^c - b^c) = expm1(a^c - x^c)
        // ⇒ a^c − x^c = ln1p(q · expm1(a^c − b^c))
        // ⇒ x = (a^c − ln1p(q · expm1(a^c − b^c)))^(1/c)
        let ac = self.a.powf(self.c);
        let bc = self.b.powf(self.c);
        let xc = ac - q.mul_add((ac - bc).exp_m1(), 0.0).ln_1p();
        xc.powf(1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        // Truncated support [a, b] makes E[X^k] = ∫_0^1 ppf(q)^k dq a
        // bounded integral; composite Simpson's on q ∈ [0, 1] with
        // 4000 panels nails it to ~1e-12 abs vs scipy's
        // truncweibull_min.stats (frankenscipy-ygfhj).
        trunc_weibull_min_moment(self.c, self.a, self.b, 1)
    }

    fn var(&self) -> f64 {
        let m1 = trunc_weibull_min_moment(self.c, self.a, self.b, 1);
        let m2 = trunc_weibull_min_moment(self.c, self.a, self.b, 2);
        let v = m2 - m1 * m1;
        if v.is_finite() && v >= 0.0 {
            v
        } else {
            f64::NAN
        }
    }

    fn skewness(&self) -> f64 {
        let m1 = trunc_weibull_min_moment(self.c, self.a, self.b, 1);
        let m2 = trunc_weibull_min_moment(self.c, self.a, self.b, 2);
        let m3 = trunc_weibull_min_moment(self.c, self.a, self.b, 3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = trunc_weibull_min_moment(self.c, self.a, self.b, 1);
        let m2 = trunc_weibull_min_moment(self.c, self.a, self.b, 2);
        let m3 = trunc_weibull_min_moment(self.c, self.a, self.b, 3);
        let m4 = trunc_weibull_min_moment(self.c, self.a, self.b, 4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Bounded support [a, b]; integrate −pdf·ln pdf directly.
        simpson_integrate_adaptive(
            |x| {
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            self.a,
            self.b,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

/// R-distribution (symmetric beta) on [-1, 1] with shape `c > 0`.
///
/// Matches `scipy.stats.rdist(c)`. Resolves [frankenscipy-i4qnc].
///
///   pdf(x; c) = (1 − x²)^(c/2 − 1) / B(1/2, c/2)
///   cdf(x; c) = Beta(c/2, c/2).cdf((x + 1)/2)
///
/// Special cases: c=2 → Uniform(-1, 1); c=3 → Semicircular;
/// c=4 → Epanechnikov; c=6 → quartic. Closed-form moments:
/// mean = 0 (symmetric), var = 1 / (c + 1).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RDist {
    pub c: f64,
}

impl RDist {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0 && c.is_finite(), "c must be positive and finite");
        Self { c }
    }
}

impl ContinuousDistribution for RDist {
    fn pdf(&self, x: f64) -> f64 {
        if !(-1.0..=1.0).contains(&x) {
            return 0.0;
        }
        let c = self.c;
        let one_minus_x2 = 1.0 - x * x;
        if one_minus_x2 <= 0.0 {
            // x = ±1 boundary: 0^(c/2 - 1) = 0 for c > 2, 1 for c = 2,
            // ∞ for c < 2.
            return if c > 2.0 {
                0.0
            } else if c == 2.0 {
                (-ln_beta(0.5, c / 2.0)).exp()
            } else {
                f64::INFINITY
            };
        }
        let log_pdf = (c / 2.0 - 1.0) * one_minus_x2.ln() - ln_beta(0.5, c / 2.0);
        log_pdf.exp()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= -1.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return 1.0;
        }
        // Beta(c/2, c/2).cdf((x + 1)/2).
        BetaDist::new(self.c / 2.0, self.c / 2.0).cdf((x + 1.0) / 2.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return -1.0;
        }
        if q == 1.0 {
            return 1.0;
        }
        // ppf via Beta(c/2, c/2).ppf(q), then map (z * 2 - 1).
        2.0 * BetaDist::new(self.c / 2.0, self.c / 2.0).ppf(q) - 1.0
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        1.0 / (self.c + 1.0)
    }

    fn skewness(&self) -> f64 {
        // Symmetric around 0.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // Raw moments via x² substitution + Beta integral identity:
        //   m_4 = 3/((c+1)(c+3)).
        // var = 1/(c+1), so excess kurt = m_4/var² − 3 = −6/(c+3).
        -6.0 / (self.c + 3.0)
    }

    fn entropy(&self) -> f64 {
        // (X + 1)/2 ~ Beta(c/2, c/2). Mapping [0, 1] → [−1, 1] adds
        // a ln 2 Jacobian to the entropy. Specializing the standard
        // h(Beta(a, b)) = ln B(a, b) − (a−1)ψ(a) − (b−1)ψ(b)
        //               + (a+b−2)ψ(a+b)
        // to a = b = c/2 collapses the two ψ(c/2) terms:
        //   h(Beta(c/2, c/2)) = ln B(c/2, c/2)
        //                     − (c − 2) ψ(c/2)
        //                     + (c − 2) ψ(c).
        let a = self.c / 2.0;
        let log_beta = 2.0 * ln_gamma(a) - ln_gamma(2.0 * a);
        log_beta + (self.c - 2.0) * fsci_special::digamma_scalar(self.c)
            - (self.c - 2.0) * fsci_special::digamma_scalar(a)
            + 2.0_f64.ln()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 2, "RDist")?;
        for &x in data {
            if !(-1.0..=1.0).contains(&x) {
                return Err(FitError::UnsupportedData(format!(
                    "RDist support is [-1, 1]; got {x}"
                )));
            }
        }
        let variance = sample_population_variance(data);
        if !variance.is_finite() || variance <= 0.0 || variance >= 1.0 {
            return Err(FitError::NonConvergent(format!(
                "RDist variance must be in (0, 1); got {variance}"
            )));
        }
        let c = 1.0 / variance - 1.0;
        if c.is_finite() && c > 0.0 {
            Ok(Self { c })
        } else {
            Err(FitError::NonConvergent(format!(
                "RDist moment fit produced invalid c: {c}"
            )))
        }
    }
}

/// Irwin–Hall distribution: the sum of `n` iid `Uniform(0, 1)`
/// variables, with support [0, n].
///
/// Matches `scipy.stats.irwinhall(n)`. Resolves [frankenscipy-7dxwg].
///
///   pdf(x; n) = 1/(n−1)! · Σ_{k=0}^{⌊x⌋} (−1)^k · C(n, k) · (x − k)^(n−1)
///   cdf(x; n) = 1/n!     · Σ_{k=0}^{⌊x⌋} (−1)^k · C(n, k) · (x − k)^n
///
/// Closed-form moments: mean = n/2, var = n/12, skew = 0, ex_kurt = −6/(5n).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IrwinHall {
    pub n: u32,
}

impl IrwinHall {
    #[must_use]
    pub fn new(n: u32) -> Self {
        assert!(n >= 1, "n must be ≥ 1, got {n}");
        Self { n }
    }
}

impl ContinuousDistribution for IrwinHall {
    fn pdf(&self, x: f64) -> f64 {
        let nf = self.n as f64;
        // n=1 collapses to Uniform(0, 1). Handle directly so the
        // closed boundary at x=0 and x=1 returns 1 (matches scipy's
        // B-spline-based implementation; the (-1)^k cancellation in
        // the alternating sum spuriously yields 0 at x=1 otherwise).
        if self.n == 1 {
            return if (0.0..=1.0).contains(&x) { 1.0 } else { 0.0 };
        }
        if x <= 0.0 || x >= nf {
            return 0.0;
        }
        // Exploit symmetry around n/2: evaluate the alternating-sign
        // sum on the lower half where ⌊x⌋ is smaller and there are
        // fewer cancelling terms. For x > n/2, mirror to n − x and
        // use pdf(n − x) = pdf(x). [frankenscipy-3f75d]
        let xeff = if x > nf / 2.0 { nf - x } else { x };
        // 1 / (n-1)! · Σ (-1)^k · C(n, k) · (x-k)^(n-1) for k = 0..=floor(x).
        let upper = xeff.floor() as u64;
        let mut sum = 0.0_f64;
        for k in 0..=upper {
            let sign = if k % 2 == 0 { 1.0 } else { -1.0 };
            let term = fsci_special::comb(self.n as u64, k) * (xeff - k as f64).powf(nf - 1.0);
            sum += sign * term;
        }
        // Clamp to ≥ 0: residual fp error can drift slightly negative.
        (sum / fsci_special::factorial((self.n - 1) as u64)).max(0.0)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let nf = self.n as f64;
        if x >= nf {
            return 1.0;
        }
        // 1 / n! · Σ (-1)^k · C(n, k) · (x-k)^n for k = 0..=floor(x).
        let upper = x.floor() as u64;
        let mut sum = 0.0_f64;
        for k in 0..=upper {
            let sign = if k % 2 == 0 { 1.0 } else { -1.0 };
            let term = fsci_special::comb(self.n as u64, k) * (x - k as f64).powf(nf);
            sum += sign * term;
        }
        // Clamp to [0, 1]: for large n the alternating-sign sum
        // accumulates floating-point error and the raw quotient can
        // drift slightly outside the valid cdf range (e.g.,
        // IrwinHall(19).cdf(17.1) raw ≈ 1.0000000037).
        // Resolves [frankenscipy-3f75d] (fuzz finding mtg5c).
        (sum / fsci_special::factorial(self.n as u64)).clamp(0.0, 1.0)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return self.n as f64;
        }
        // No closed-form inverse — Illinois over the strictly-monotone cdf on
        // the full support [0, n]: g(x)=cdf(x)−q, g(0)=−q<0<g(n)=1−q. Earlier 4σ
        // bracket missed tail q-values where the true x is outside the σ-band.
        let a = 0.0_f64;
        let b = self.n as f64;
        illinois_root_increasing(|x| self.cdf(x) - q, a, b, -q, self.cdf(b) - q)
    }

    fn mean(&self) -> f64 {
        self.n as f64 / 2.0
    }

    fn var(&self) -> f64 {
        self.n as f64 / 12.0
    }

    fn skewness(&self) -> f64 {
        // IrwinHall is symmetric around n/2.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        -6.0 / (5.0 * self.n as f64)
    }

    fn entropy(&self) -> f64 {
        // n = 1 is Uniform(0, 1) with h = 0.
        // n = 2 is Triangular(0, 1, 2) with h = 0.5 (the shape-independent
        // Triangular entropy formula collapses to ln(b−a) + 0.5 − ln 2 =
        // ln 2 + 0.5 − ln 2 = 0.5).
        // For n ≥ 3 the IrwinHall PDF is piecewise polynomial of degree
        // n − 1 and the entropy has no simple closed form; integrate
        // −ln pdf with composite Simpson on the bounded support [0, n].
        match self.n {
            1 => 0.0,
            2 => 0.5,
            _ => {
                let nf = self.n as f64;
                let steps = 8_000usize;
                let h = nf / steps as f64;
                let mut sum = 0.0_f64;
                for i in 0..=steps {
                    let x = i as f64 * h;
                    let w = if i == 0 || i == steps {
                        1.0
                    } else if i % 2 == 0 {
                        2.0
                    } else {
                        4.0
                    };
                    let p = self.pdf(x);
                    if p > 0.0 {
                        sum += w * (-p * p.ln());
                    }
                }
                sum * h / 3.0
            }
        }
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // IrwinHall(n) is the sum of n iid Uniform(0,1) variates.
        // Closed-form MOM identity: Var(X) = n / 12, so we estimate
        // n by rounding 12·Var to the nearest positive integer.
        // We also require every observation to lie in [0, n_est] for
        // the fitted distribution to be consistent with the data.
        validate_finite_fit_data(data, 2, "IrwinHall")?;
        let var = sample_variance(data);
        if !var.is_finite() || var <= 0.0 {
            return Err(FitError::NonConvergent(
                "IrwinHall fit needs positive sample variance".to_owned(),
            ));
        }
        let n_est_raw = (12.0 * var).round();
        let n_est = if !n_est_raw.is_finite() || n_est_raw < 1.0 {
            return Err(FitError::NonConvergent(
                "IrwinHall MOM did not yield a positive integer n".to_owned(),
            ));
        } else if n_est_raw > u32::MAX as f64 {
            return Err(FitError::NonConvergent(
                "IrwinHall MOM yielded n exceeding u32 range".to_owned(),
            ));
        } else {
            n_est_raw as u32
        };
        let nf = f64::from(n_est);
        if data.iter().any(|&x| x < 0.0 || x > nf) {
            return Err(FitError::UnsupportedData(format!(
                "IrwinHall(n={n_est}) fit requires every sample in [0, {nf}]"
            )));
        }
        Ok(Self { n: n_est })
    }
}

/// Upper-truncated Pareto distribution on [1, c] with shape `b ≠ 0`
/// and `c > 1`.
///
/// Matches `scipy.stats.truncpareto(b, c)`. Resolves [frankenscipy-yvjyl].
///
///   pdf(x; b, c) = b · x^(-b-1) / (1 − c^(-b))
///   cdf(x; b, c) = (1 − x^(-b)) / (1 − c^(-b))
///   ppf(q)       = (1 − q · (1 − c^(-b)))^(-1/b)
///
/// For `b > 1` the mean is `b·(1 − c^(1-b)) / ((b-1)·(1 − c^(-b)))`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TruncPareto {
    pub b: f64,
    pub c: f64,
}

impl TruncPareto {
    #[must_use]
    pub fn new(b: f64, c: f64) -> Self {
        assert!(b != 0.0 && b.is_finite(), "b must be finite and nonzero");
        assert!(c > 1.0 && c.is_finite(), "c must be > 1 and finite");
        Self { b, c }
    }

    /// Common denominator 1 − c^(-b).
    fn denom(&self) -> f64 {
        1.0 - self.c.powf(-self.b)
    }
}

impl ContinuousDistribution for TruncPareto {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if !(1.0..=self.c).contains(&x) {
            return 0.0;
        }
        self.b * x.powf(-self.b - 1.0) / self.denom()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x < 1.0 {
            return 0.0;
        }
        if x >= self.c {
            return 1.0;
        }
        (1.0 - x.powf(-self.b)) / self.denom()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 1.0;
        }
        if q == 1.0 {
            return self.c;
        }
        (1.0 - q * self.denom()).powf(-1.0 / self.b)
    }

    fn mean(&self) -> f64 {
        // E[X] = b · (1 − c^(1-b)) / ((b - 1) · (1 − c^(-b))) for b ≠ 1.
        // For b = 1: E[X] = (c - 1) / ln(c).
        if self.b == 1.0 {
            (self.c - 1.0) / self.c.ln()
        } else {
            self.b * (1.0 - self.c.powf(1.0 - self.b)) / ((self.b - 1.0) * self.denom())
        }
    }

    fn var(&self) -> f64 {
        // Closed form for var via E[X²] - E[X]². E[X²] = b·(c^(2-b) - 1)
        // / ((2-b)·(1 - c^(-b))) for b ≠ 2; for b = 2: 2·ln(c)/(1 - c^(-2)).
        let denom = self.denom();
        let e2 = if self.b == 2.0 {
            2.0 * self.c.ln() / denom
        } else {
            self.b * (self.c.powf(2.0 - self.b) - 1.0) / ((2.0 - self.b) * denom)
        };
        let m = self.mean();
        e2 - m * m
    }

    fn skewness(&self) -> f64 {
        let (b, c) = (self.b, self.c);
        let denom = self.denom();
        let mk = |k: f64| {
            if (k - b).abs() < 1e-15 {
                b * c.ln() / denom
            } else {
                b * (c.powf(k - b) - 1.0) / ((k - b) * denom)
            }
        };
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let (b, c) = (self.b, self.c);
        let denom = self.denom();
        let mk = |k: f64| {
            if (k - b).abs() < 1e-15 {
                b * c.ln() / denom
            } else {
                b * (c.powf(k - b) - 1.0) / ((k - b) * denom)
            }
        };
        let m1 = mk(1.0);
        let m2 = mk(2.0);
        let m3 = mk(3.0);
        let m4 = mk(4.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // PDF = b·x^{−b−1}/(1 − c^{−b}) on [1, c].
        // −ln pdf = −ln b + (b+1) ln x + ln(1 − c^{−b}).
        // Integration by parts: E[ln X] = (1 − c^{−b}·(b·ln c + 1))
        //                                / (b · (1 − c^{−b})).
        let cb = self.c.powf(-self.b);
        let denom = 1.0 - cb;
        let e_ln_x = (1.0 - cb * self.b.mul_add(self.c.ln(), 1.0)) / (self.b * denom);
        -self.b.ln() + (self.b + 1.0) * e_ln_x + denom.ln()
    }
}

/// Truncated exponential distribution on [0, b].
///
/// Matches `scipy.stats.truncexpon`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TruncExpon {
    pub b: f64,
}

impl TruncExpon {
    #[must_use]
    pub fn new(b: f64) -> Self {
        assert!(b > 0.0, "b must be positive");
        Self { b }
    }
}

impl ContinuousDistribution for TruncExpon {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 || x > self.b {
            0.0
        } else {
            (-x).exp() / (1.0 - (-self.b).exp())
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −x − ln(1 − e^{−b}) on [0,b]. frankenscipy-p82v7
        if x < 0.0 || x > self.b {
            return f64::NEG_INFINITY;
        }
        -x - (1.0 - (-self.b).exp()).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else if x >= self.b {
            1.0
        } else {
            (1.0 - (-x).exp()) / (1.0 - (-self.b).exp())
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return self.b;
        }
        // CDF = (1-exp(-x))/(1-exp(-b)), so x = -ln(1 - q*(1-exp(-b)))
        -(1.0 - q * (1.0 - (-self.b).exp())).ln()
    }

    fn mean(&self) -> f64 {
        let eb = (-self.b).exp();
        // E[X] = (1 - (1+b)*exp(-b)) / (1 - exp(-b))
        (1.0 - (1.0 + self.b) * eb) / (1.0 - eb)
    }

    fn var(&self) -> f64 {
        let m = self.mean();
        let eb = (-self.b).exp();
        let e2 = (2.0 - (2.0 + 2.0 * self.b + self.b * self.b) * eb) / (1.0 - eb);
        e2 - m * m
    }

    fn entropy(&self) -> f64 {
        // PDF = e^{−x}/(1 − e^{−b}); −ln pdf = ln(1 − e^{−b}) + x.
        //   h = ln(1 − e^{−b}) + E[X].
        let one_minus_e_b = -(-self.b).exp_m1();
        one_minus_e_b.ln() + self.mean()
    }

    fn skewness(&self) -> f64 {
        // Raw moments via the integration-by-parts recurrence
        //   I_k = ∫_0^b x^k e^{−x} dx = −b^k e^{−b} + k · I_{k−1},
        //   I_0 = 1 − e^{−b};
        // then m_k = I_k / I_0. Always finite on the bounded support.
        let b = self.b;
        let e_b = (-b).exp();
        let i0 = 1.0 - e_b;
        let i1 = (1.0_f64).mul_add(i0, -b * e_b);
        let i2 = 2.0_f64.mul_add(i1, -b * b * e_b);
        let i3 = 3.0_f64.mul_add(i2, -b.powi(3) * e_b);
        let m1 = i1 / i0;
        let m2 = i2 / i0;
        let m3 = i3 / i0;
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let b = self.b;
        let e_b = (-b).exp();
        let i0 = 1.0 - e_b;
        let i1 = (1.0_f64).mul_add(i0, -b * e_b);
        let i2 = 2.0_f64.mul_add(i1, -b * b * e_b);
        let i3 = 3.0_f64.mul_add(i2, -b.powi(3) * e_b);
        let i4 = 4.0_f64.mul_add(i3, -b.powi(4) * e_b);
        let m1 = i1 / i0;
        let m2 = i2 / i0;
        let m3 = i3 / i0;
        let m4 = i4 / i0;
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        // Boundary MLE: at fixed rate λ=1, the support is [0, b], so the
        // log-likelihood is monotonically decreasing in b on [max(x_i), ∞).
        // The MLE is therefore b_hat = max(x_i).
        let mut max_obs = f64::NEG_INFINITY;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "TruncExpon data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "TruncExpon data must be non-negative; got {x}"
                )));
            }
            if x > max_obs {
                max_obs = x;
            }
        }
        if max_obs <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "TruncExpon MLE: max observation {max_obs} must be > 0"
            )));
        }
        Ok(Self { b: max_obs })
    }
}

/// Generalized half-logistic distribution.
///
/// Matches `scipy.stats.genhalflogistic`.
pub struct GenHalfLogistic {
    pub c: f64,
}

impl GenHalfLogistic {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }

    /// k-th raw moment via the substitution u = (1 − c·x)^{1/c}, which
    /// gives x = (1 − u^c)/c and the standard half-logistic measure
    /// 2/(1 + u)² du on the bounded interval u ∈ [0, 1]:
    ///   E[X^k] = ∫_0^1 ((1 − u^c)/c)^k · 2/(1 + u)² du.
    /// Evaluated by composite Simpson — endpoint at u = 0 is regular
    /// (integrand → (1/c)^k · 2), so no eps shift needed.
    fn raw_moment(&self, k: u32) -> f64 {
        let n: usize = 8_192;
        let h = 1.0 / n as f64;
        let mut sum = 0.0_f64;
        for i in 0..=n {
            let u = i as f64 * h;
            let w = if i == 0 || i == n {
                1.0
            } else if i % 2 == 0 {
                2.0
            } else {
                4.0
            };
            let xv = (1.0 - u.powf(self.c)) / self.c;
            let denom = 1.0 + u;
            sum += w * xv.powi(k as i32) * 2.0 / (denom * denom);
        }
        sum * h / 3.0
    }
}

impl ContinuousDistribution for GenHalfLogistic {
    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let limit = 1.0 / self.c;
        if x >= limit {
            return 0.0;
        }
        2.0 * (1.0 - self.c * x).powf(1.0 / self.c - 1.0)
            / (1.0 + (1.0 - self.c * x).powf(1.0 / self.c)).powi(2)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln2 + (1/c−1)·ln(1−c·x) − 2·ln(1+(1−c·x)^{1/c}) on [0, 1/c). frankenscipy-p82v7
        if x < 0.0 || x >= 1.0 / self.c {
            return f64::NEG_INFINITY;
        }
        let base = 1.0 - self.c * x;
        2.0_f64.ln() + (1.0 / self.c - 1.0) * base.ln() - 2.0 * (1.0 + base.powf(1.0 / self.c)).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let limit = 1.0 / self.c;
        if x >= limit {
            return 1.0;
        }
        let t = (1.0 - self.c * x).powf(1.0 / self.c);
        1.0 - 2.0 * t / (1.0 + t)
    }

    fn ppf(&self, q: f64) -> f64 {
        // t=(1−q)/(1+q), x=(1 − t^c)/c; closed-form inverse vs bisection. frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        (1.0 - ((1.0 - q) / (1.0 + q)).powf(self.c)) / self.c
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 2t/(1+t), t=(1−c·x)^{1/c}; direct form keeps precision near the
        // upper support limit 1/c where 1−cdf collapses. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        let limit = 1.0 / self.c;
        if x >= limit {
            return 0.0;
        }
        let t = (1.0 - self.c * x).powf(1.0 / self.c);
        2.0 * t / (1.0 + t)
    }

    fn mean(&self) -> f64 {
        // The earlier (ψ(1/c + 1) + γ)/c formula matched a different
        // distribution — scipy.stats.genhalflogistic(c=0.5).mean() is
        // 0.858, not 3.0. The substitution u = (1 − cx)^{1/c} gives
        // PDF measure 2/(1+u)² du on u ∈ [0, 1] and x = (1 − u^c)/c,
        // which integrates cleanly via Simpson on the bounded interval.
        self.raw_moment(1)
    }

    fn var(&self) -> f64 {
        let m1 = self.raw_moment(1);
        (self.raw_moment(2) - m1 * m1).max(0.0)
    }

    fn skewness(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let m4 = self.raw_moment(4);
        let var = m2 - m1 * m1;
        if var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // h(GenHalfLogistic(c)) = 2 − (2c + 1) · ln 2.
        2.0 - (2.0 * self.c + 1.0) * 2.0_f64.ln()
    }
}

/// Tukey-Lambda distribution.
///
/// Matches `scipy.stats.tukeylambda`.
pub struct TukeyLambda {
    pub lam: f64,
}

impl TukeyLambda {
    #[must_use]
    pub fn new(lam: f64) -> Self {
        Self { lam }
    }

    fn logistic_cdf(x: f64) -> f64 {
        if x >= 0.0 {
            1.0 / (1.0 + (-x).exp())
        } else {
            let ex = x.exp();
            ex / (1.0 + ex)
        }
    }

    fn quantile_derivative(&self, p: f64) -> f64 {
        let lam = self.lam;
        if lam.abs() < 1e-15 {
            1.0 / p + 1.0 / (1.0 - p)
        } else {
            p.powf(lam - 1.0) + (1.0 - p).powf(lam - 1.0)
        }
    }
}

impl ContinuousDistribution for TukeyLambda {
    fn pdf(&self, x: f64) -> f64 {
        if x.is_nan() {
            return f64::NAN;
        }

        if self.lam.abs() < 1e-15 {
            let cdf = Self::logistic_cdf(x);
            return cdf * (1.0 - cdf);
        }

        let cdf = self.cdf(x);
        if !cdf.is_finite() {
            return f64::NAN;
        }
        if cdf <= 0.0 || cdf >= 1.0 {
            return 0.0;
        }

        1.0 / self.quantile_derivative(cdf)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x.is_nan() {
            return f64::NAN;
        }

        if self.lam > 0.0 {
            let bound = 1.0 / self.lam;
            if x <= -bound {
                return 0.0;
            }
            if x >= bound {
                return 1.0;
            }
        }

        let mut lo = 0.0f64;
        let mut hi = 1.0f64;
        let eps = 1e-12;
        let mut p = Self::logistic_cdf(x).clamp(eps, 1.0 - eps);

        for _ in 0..10 {
            let q = self.ppf(p);
            if !q.is_finite() {
                break;
            }
            if q < x {
                lo = p;
            } else {
                hi = p;
            }
            if (q - x).abs() <= 1e-14 * (1.0 + x.abs()) {
                return p;
            }

            let derivative = self.quantile_derivative(p);
            if !derivative.is_finite() || derivative <= 0.0 {
                break;
            }

            let next = p - (q - x) / derivative;
            if !next.is_finite() || next <= lo || next >= hi {
                break;
            }
            p = next.clamp(eps, 1.0 - eps);
        }

        for _ in 0..60 {
            let mid = (lo + hi) / 2.0;
            let q = self.ppf(mid);
            if q < x {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        (lo + hi) / 2.0
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let lam = self.lam;
        if lam.abs() < 1e-15 {
            // Logistic: Q(p) = ln(p/(1-p))
            (q / (1.0 - q)).ln()
        } else {
            (q.powf(lam) - (1.0 - q).powf(lam)) / lam
        }
    }

    fn mean(&self) -> f64 {
        0.0 // Symmetric
    }

    fn var(&self) -> f64 {
        let lam = self.lam;
        if lam.abs() < 1e-15 {
            return PI * PI / 3.0;
        }
        if lam <= -0.5 {
            return f64::NAN;
        }

        let gamma_ratio = (2.0 * ln_gamma(lam + 1.0) - ln_gamma(2.0 * lam + 2.0)).exp();
        2.0 * (1.0 / (1.0 + 2.0 * lam) - gamma_ratio) / (lam * lam)
    }

    fn skewness(&self) -> f64 {
        // Symmetric about 0 for every λ → skew = 0.
        0.0
    }

    fn entropy(&self) -> f64 {
        // h(TukeyLambda(λ)) = ∫_0^1 ln(q^{λ−1} + (1−q)^{λ−1}) dq.
        // Derivation: pdf(ppf(q)) = 1/Q'(q) so −ln pdf = ln Q'(q);
        // Q'(q) = q^{λ−1} + (1−q)^{λ−1}. λ = 0 collapses to the
        // logistic h = 2.
        let lam = self.lam;
        if lam.abs() < 1e-15 {
            return 2.0;
        }
        simpson_integrate_adaptive(
            |q| (q.powf(lam - 1.0) + (1.0 - q).powf(lam - 1.0)).ln(),
            1e-12,
            1.0 - 1e-12,
            2_048,
            1e-11,
            1e-11,
            8,
        )
    }

    fn kurtosis(&self) -> f64 {
        // λ = 0 limit: logistic, ex.kurt = 6/5 = 1.2.
        let lam = self.lam;
        if lam.abs() < 1e-15 {
            return 1.2;
        }
        // m_4 finite only when 4λ + 1 > 0, i.e. λ > −1/4.
        if lam <= -0.25 {
            return f64::NAN;
        }
        // m_{2k} = (1/λ^{2k}) Σ_{j=0}^{2k} C(2k,j) (−1)^j B(λ(2k−j)+1, λj+1)
        // (for 2k = 4):
        //   m_4 = (1/λ^4) [2/(4λ+1) − 8 B(3λ+1, λ+1) + 6 B(2λ+1, 2λ+1)]
        // (using B(a,b) = B(b,a) symmetry to collapse two pairs).
        let lg = |a: f64, b: f64| (ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b)).exp();
        let inv4 = 1.0 / lam.powi(4);
        let m4 = inv4
            * 2.0_f64.mul_add(
                1.0 / (4.0 * lam + 1.0),
                6.0_f64.mul_add(
                    lg(2.0 * lam + 1.0, 2.0 * lam + 1.0),
                    -8.0 * lg(3.0 * lam + 1.0, lam + 1.0),
                ),
            );
        let var = self.var();
        // Symmetric ⇒ μ_4 = m_4 (mean = 0).
        m4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        validate_finite_fit_data(data, 2, "TukeyLambda")?;
        let target_var = sample_population_variance(data);
        if !target_var.is_finite() || target_var <= 0.0 {
            return Err(FitError::NonConvergent(
                "TukeyLambda fit needs positive sample variance".to_owned(),
            ));
        }

        let mut lo = -0.49_f64;
        let mut hi = 20.0_f64;
        if (Self { lam: lo }).var() < target_var {
            return Err(FitError::NonConvergent(format!(
                "TukeyLambda sample variance {target_var} exceeds finite-variance search range"
            )));
        }
        while (Self { lam: hi }).var() > target_var && hi < 1.0e6 {
            hi *= 2.0;
        }
        if (Self { lam: hi }).var() > target_var {
            return Err(FitError::NonConvergent(format!(
                "TukeyLambda sample variance {target_var} is too small to bracket"
            )));
        }
        for _ in 0..100 {
            let mid = 0.5 * (lo + hi);
            if (Self { lam: mid }).var() > target_var {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self {
            lam: 0.5 * (lo + hi),
        })
    }
}

/// Inverse Weibull (Frechet) distribution.
///
/// Matches `scipy.stats.invweibull`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct InvWeibull {
    pub c: f64,
}

impl InvWeibull {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for InvWeibull {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        self.c * weibull_pdf_shape(x, -self.c, weibull_density_reuse())
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(c) + (−c−1)·ln(x) − x^{−c}; finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        self.c.ln() + weibull_logpdf_shape(x, -self.c, weibull_density_reuse())
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            (-x.powf(-self.c)).exp()
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = 1 − exp(−x^{−c}) = −expm1(−x^{−c}); the default collapses to 0
        // as x→∞ where cdf→1 (invweibull.sf(1e8,1) scipy 1e-8). frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        -(-x.powf(-self.c)).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        // CDF = exp(-x^(-c)), so x^(-c) = -ln(q), x = (-ln(q))^(-1/c)
        (-q.ln()).powf(-1.0 / self.c)
    }

    fn mean(&self) -> f64 {
        if self.c > 1.0 {
            ln_gamma(1.0 - 1.0 / self.c).exp()
        } else {
            f64::INFINITY
        }
    }

    fn var(&self) -> f64 {
        if self.c <= 2.0 {
            return f64::NAN;
        }

        let g1 = ln_gamma(1.0 - 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 - 2.0 / self.c).exp();
        g2 - g1 * g1
    }

    fn entropy(&self) -> f64 {
        // h(InvWeibull(c, scale=1)) = γ·(1 + 1/c) + ln(1/c) + 1
        //                          = γ + γ/c − ln(c) + 1.
        // (Frechet Type II — Wikipedia.)
        EULER_MASCHERONI + EULER_MASCHERONI / self.c - self.c.ln() + 1.0
    }

    fn skewness(&self) -> f64 {
        // Raw moments m_k = Γ(1 − k/c), finite only for c > k.
        // Skewness requires c > 3 (otherwise μ_3 diverges).
        if self.c <= 3.0 {
            return f64::NAN;
        }
        let g1 = ln_gamma(1.0 - 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 - 2.0 / self.c).exp();
        let g3 = ln_gamma(1.0 - 3.0 / self.c).exp();
        let var = g2 - g1 * g1;
        let mu3 = 2.0_f64.mul_add(g1.powi(3), g3 - 3.0 * g1 * g2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // Kurtosis requires c > 4 (otherwise μ_4 diverges).
        if self.c <= 4.0 {
            return f64::NAN;
        }
        let g1 = ln_gamma(1.0 - 1.0 / self.c).exp();
        let g2 = ln_gamma(1.0 - 2.0 / self.c).exp();
        let g3 = ln_gamma(1.0 - 3.0 / self.c).exp();
        let g4 = ln_gamma(1.0 - 4.0 / self.c).exp();
        let var = g2 - g1 * g1;
        let mu4 = (-3.0_f64).mul_add(
            g1.powi(4),
            6.0_f64.mul_add(g1 * g1 * g2, 4.0_f64.mul_add(-g1 * g3, g4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "InvWeibull data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "InvWeibull support is [0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 1.0 || !mean.is_finite() {
            return Err(FitError::UnsupportedData(format!(
                "InvWeibull MoM (unit-scale) requires sample mean > 1; got {mean}"
            )));
        }
        // Mean(c) = Γ(1 - 1/c) for c > 1. Monotone-decreasing from ∞ at
        // c→1+ to 1 at c→∞. Bisect on c ∈ (1.001, 1e3).
        let mean_of = |c: f64| ln_gamma(1.0 - 1.0 / c).exp();
        let mut lo = 1.001_f64;
        let mut hi = 1.0e3_f64;
        let m_lo = mean_of(lo);
        let m_hi = mean_of(hi);
        if !(m_hi <= mean && mean <= m_lo) {
            return Err(FitError::NonConvergent(format!(
                "InvWeibull MoM bracket failed: mean({lo})={m_lo}, mean({hi})={m_hi}, target={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let m_mid = mean_of(mid);
            if (m_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if m_mid > mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }
}

/// When `true`, [`GenNorm::logpdf_many`] runs its `powf` map serially (the ORIG behaviour). When
/// `false` (default), it fans across cores via `par_continuous_map_min` (byte-identical, order-
/// preserving — the same helper the sibling `pdf_many` uses). For the same-binary A/B perf gate.
///
/// History (frankenscipy-lnb7b, frankenscipy-gur9n): introduced by 0216fd42c, removed as collateral
/// by 3a4493248 — whose stated subject was adding trima/trimr and iterative QMC discrepancy
/// variants — which left `perf_gennorm_logpdf` importing a symbol that no longer existed. Restored
/// individually in 515509102 before the full crate reconciliation; this is the parent's original,
/// with that provenance note merged in.
#[doc(hidden)]
/// A/B switch: force `GenNormal::logpdf_many` onto its serial map.
///
/// CONTRACT: BYTE-IDENTICAL either way. The parallel arm is an ORDER-PRESERVING
/// map (`par_continuous_map_min`) over a PURE per-element expression --
/// `lead - |x|.powf(beta)`, with `lead` hoisted before the split. Each output
/// depends only on its own input, so no float is combined across threads and
/// the only thing parallelism changes is which core evaluates which `powf`.
///
/// This is the same helper and gate the sibling `pdf_many` already uses;
/// `logpdf_many` was the one distribution `_many` left serial.
pub static GENNORM_LOGPDF_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Generalized normal distribution (exponential power).
///
/// Matches `scipy.stats.gennorm`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GenNorm {
    pub beta: f64,
}

impl GenNorm {
    #[must_use]
    pub fn new(beta: f64) -> Self {
        assert!(beta > 0.0, "beta must be positive");
        Self { beta }
    }

    /// Log-density at many points, hoisting `ln(β) − ln2 − lnΓ(1/β)` out of the
    /// per-point loop. Byte-identical to mapping `logpdf` (lead kept leading, same
    /// final `− |x|^β` subtraction).
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let b = self.beta;
        let lead = b.ln() - 2.0_f64.ln() - ln_gamma(1.0 / b);
        // `powf` per element is compute-bound; fan across cores via the order-preserving
        // `par_continuous_map_min` — the SAME helper (and gate) the sibling `pdf_many` already uses.
        // BYTE-IDENTICAL to the serial map (`lead` hoisted, pure per-element `powf`). This lone
        // `logpdf_many` was the one distribution `_many` left serial. `GENNORM_LOGPDF_FORCE_SERIAL`
        // restores the serial map (same-binary A/B).
        if GENNORM_LOGPDF_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
            xs.iter().map(|&x| lead - x.abs().powf(b)).collect()
        } else {
            par_continuous_map_min(xs, 65536, |x| lead - x.abs().powf(b))
        }
    }

    /// Density at many points; hoists the `β / (2·Γ(1/β))` coefficient like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let b = self.beta;
        let coeff = b / (2.0 * ln_gamma(1.0 / b).exp());
        par_continuous_map_min(xs, 65536, |x| coeff * (-x.abs().powf(b)).exp())
    }
}

impl ContinuousDistribution for GenNorm {
    fn pdf(&self, x: f64) -> f64 {
        let b = self.beta;
        b / (2.0 * ln_gamma(1.0 / b).exp()) * (-x.abs().powf(b)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(β) − ln2 − lnΓ(1/β) − |x|^β; finite in the tail. frankenscipy-p82v7
        let b = self.beta;
        b.ln() - 2.0_f64.ln() - ln_gamma(1.0 / b) - x.abs().powf(b)
    }

    fn cdf(&self, x: f64) -> f64 {
        // cdf = ½ + ½·P(1/β, x^β) for x ≥ 0; for x < 0 the symmetric form is
        // ½ − ½·P(1/β, |x|^β) = ½·Q(1/β, |x|^β). The subtraction collapses to 0
        // in the left tail (P → 1), so use the upper regularized gamma directly
        // — keeps the value exact (matches scipy.gennorm.cdf to 0 ULP down to
        // ~1e-155). frankenscipy-ew60b
        let b = self.beta;
        if x >= 0.0 {
            0.5 + 0.5 * lower_regularized_gamma(1.0 / b, x.powf(b))
        } else {
            0.5 * upper_regularized_gamma(1.0 / b, (-x).powf(b))
        }
    }

    fn logcdf(&self, x: f64) -> f64 {
        // Mirror of logsf: x < 0 → log cdf = −ln2 + log Q(1/β, |x|^β), finite
        // where Q underflows (the default ln(cdf) returns −inf there); x ≥ 0 →
        // cdf ≥ ½, so ln(cdf) is well-conditioned. frankenscipy-ew60b
        let b = self.beta;
        if x >= 0.0 {
            self.cdf(x).ln()
        } else {
            -std::f64::consts::LN_2 + fsci_special::log_gammaincc_scalar(1.0 / b, (-x).powf(b))
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        // |x|^β = gammaincinv(1/β, |2q−1|), sign from q≷½. frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        let b = self.beta;
        // Use the gammainccinv reflection (gammaincinv(a,1−y)=gammainccinv(a,y))
        // so the tail argument stays small: gammaincinv(1/β, 1−2q) near 1 is
        // ill-conditioned and disagreed with scipy by ~7.8e-7 at q=1e-12.
        // gammainccinv(1/β, 2·min(q,1−q)) is well-conditioned and matches
        // scipy.stats.gennorm.ppf bit-for-bit. frankenscipy-d2gag
        if q >= 0.5 {
            fsci_special::gammainccinv_scalar(1.0 / b, 2.0 * (1.0 - q)).powf(1.0 / b)
        } else {
            -fsci_special::gammainccinv_scalar(1.0 / b, 2.0 * q).powf(1.0 / b)
        }
    }

    fn isf(&self, q: f64) -> f64 {
        // GenNorm is symmetric about 0: isf(q)=ppf(1−q)=−ppf(q). Routing through
        // −ppf(q) avoids the 1−q cancellation; matches scipy.stats.gennorm.isf
        // bit-for-bit. frankenscipy-d2gag
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        -self.ppf(q)
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = ½·Q(1/β, x^β) for x≥0 (upper regularized gamma, so the right tail
        // does not collapse when 1−cdf underflows); ½ + ½·P(1/β, |x|^β) for x<0
        // by symmetry. frankenscipy-w3f6m
        let b = self.beta;
        if x >= 0.0 {
            0.5 * upper_regularized_gamma(1.0 / b, x.powf(b))
        } else {
            0.5 + 0.5 * lower_regularized_gamma(1.0 / b, (-x).powf(b))
        }
    }

    fn logsf(&self, x: f64) -> f64 {
        // x≥0: log sf = −ln2 + log Q(1/β, x^β), finite where Q underflows; x<0:
        // sf ≥ ½, so ln(sf) is well-conditioned. frankenscipy-pkaua
        let b = self.beta;
        if x >= 0.0 {
            -std::f64::consts::LN_2 + fsci_special::log_gammaincc_scalar(1.0 / b, x.powf(b))
        } else {
            self.sf(x).ln()
        }
    }

    fn mean(&self) -> f64 {
        0.0
    }

    fn var(&self) -> f64 {
        let b = self.beta;
        ln_gamma(3.0 / b).exp() / ln_gamma(1.0 / b).exp()
    }

    fn entropy(&self) -> f64 {
        // h(GenNorm(β)) = 1/β − ln(β / (2·Γ(1/β))).
        let b = self.beta;
        1.0 / b - (b / (2.0 * ln_gamma(1.0 / b).exp())).ln()
    }

    fn skewness(&self) -> f64 {
        // Symmetric about 0 ⇒ all odd central moments vanish.
        0.0
    }

    fn kurtosis(&self) -> f64 {
        // Raw moments via u = |x|^β: m_k = Γ((k+1)/β)/Γ(1/β) for k even,
        // 0 for k odd. Excess kurt = m_4/m_2² − 3.
        let b = self.beta;
        let lg1 = ln_gamma(1.0 / b);
        let m2 = (ln_gamma(3.0 / b) - lg1).exp();
        let m4 = (ln_gamma(5.0 / b) - lg1).exp();
        m4 / (m2 * m2) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "GenNorm data contains non-finite value: {x}"
                )));
            }
        }
        // Method-of-moments: standardized variance is
        //   Var(β) = Γ(3/β) / Γ(1/β)
        // monotone-decreasing in β. β=1 → Var=2 (Laplace);
        // β=2 → Var=1 (standard normal); β→∞ → Var → 1/3 (uniform).
        // Sample variance about 0 is the natural moment (the distribution
        // is centered at 0).
        let n = data.len() as f64;
        let m2_about_zero: f64 = data.iter().map(|x| x * x).sum::<f64>() / n;
        if !m2_about_zero.is_finite() || m2_about_zero <= 0.0 {
            return Err(FitError::NonConvergent(format!(
                "GenNorm MoM: sample E[x²] {m2_about_zero} non-positive"
            )));
        }
        let var_of = |beta: f64| -> f64 { ln_gamma(3.0 / beta).exp() / ln_gamma(1.0 / beta).exp() };
        // Bracket. β=0.1 gives huge variance; β=50 gives variance ~ 1/3.
        let mut lo = 0.1_f64;
        let mut hi = 50.0_f64;
        let v_lo = var_of(lo);
        let v_hi = var_of(hi);
        // var is monotone-decreasing in β, so v_lo ≥ target ≥ v_hi.
        if !(v_hi <= m2_about_zero && m2_about_zero <= v_lo) {
            return Err(FitError::NonConvergent(format!(
                "GenNorm MoM bracket failed: var({lo})={v_lo}, var({hi})={v_hi}, target={m2_about_zero}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let v_mid = var_of(mid);
            if (v_mid - m2_about_zero).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { beta: mid });
            }
            if v_mid > m2_about_zero {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self {
            beta: 0.5 * (lo + hi),
        })
    }
}

/// Half generalized normal distribution (upper half of `gennorm`).
///
/// Matches `scipy.stats.halfgennorm`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HalfGenNorm {
    pub beta: f64,
}

impl HalfGenNorm {
    #[must_use]
    pub fn new(beta: f64) -> Self {
        assert!(beta > 0.0, "beta must be positive");
        Self { beta }
    }

    /// Log-density at many points, hoisting `ln(β) − lnΓ(1/β)` out of the per-point
    /// loop. Byte-identical to mapping `logpdf` (lead leading, same `− x^β`); x<0 → −∞.
    #[must_use]
    pub fn logpdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let b = self.beta;
        let lead = b.ln() - ln_gamma(1.0 / b);
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return f64::NEG_INFINITY;
            }
            lead - x.powf(b)
        })
    }

    /// Density at many points; hoists the `β / Γ(1/β)` coefficient like
    /// [`logpdf_many`](Self::logpdf_many). Byte-identical to mapping `pdf`.
    #[must_use]
    pub fn pdf_many(&self, xs: &[f64]) -> Vec<f64> {
        let b = self.beta;
        let coeff = b / ln_gamma(1.0 / b).exp();
        par_continuous_map_min(xs, 65536, |x| {
            if x < 0.0 {
                return 0.0;
            }
            coeff * (-x.powf(b)).exp()
        })
    }
}

impl ContinuousDistribution for HalfGenNorm {
    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 {
            return 0.0;
        }
        let b = self.beta;
        b / ln_gamma(1.0 / b).exp() * (-x.powf(b)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(β) − lnΓ(1/β) − x^β; finite in the tail. frankenscipy-p82v7
        if x < 0.0 {
            return f64::NEG_INFINITY;
        }
        let b = self.beta;
        b.ln() - ln_gamma(1.0 / b) - x.powf(b)
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        let b = self.beta;
        lower_regularized_gamma(1.0 / b, x.powf(b))
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Q(1/β, x^β) directly; the default 1−cdf collapses once the lower
        // regularized gamma rounds to 1. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        upper_regularized_gamma(1.0 / self.beta, x.powf(self.beta))
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(1/β, x^β); finite in the ultra-extreme tail. frankenscipy-pkaua
        if x <= 0.0 {
            return 0.0;
        }
        fsci_special::log_gammaincc_scalar(1.0 / self.beta, x.powf(self.beta))
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        let b = self.beta;
        let g = fsci_special::gammaincinv_scalar(1.0 / b, q);
        if g.is_finite() && g >= 0.0 {
            g.powf(1.0 / b)
        } else {
            ppf_bisection(|x| self.cdf(x), q, self.mean(), self.std())
        }
    }

    fn mean(&self) -> f64 {
        let b = self.beta;
        ln_gamma(2.0 / b).exp() / ln_gamma(1.0 / b).exp()
    }

    fn var(&self) -> f64 {
        let b = self.beta;
        let mean = self.mean();
        ln_gamma(3.0 / b).exp() / ln_gamma(1.0 / b).exp() - mean * mean
    }

    fn entropy(&self) -> f64 {
        // h(HalfGenNorm(β)) = 1/β − ln(β / Γ(1/β)). One factor of
        // ln 2 less than the symmetric GenNorm — folding halves the
        // support.
        let b = self.beta;
        1.0 / b - (b / ln_gamma(1.0 / b).exp()).ln()
    }

    fn skewness(&self) -> f64 {
        // Raw moments via u = x^β: m_k = Γ((k+1)/β)/Γ(1/β) for k ≥ 0.
        let b = self.beta;
        let lg1 = ln_gamma(1.0 / b);
        let m1 = (ln_gamma(2.0 / b) - lg1).exp();
        let m2 = (ln_gamma(3.0 / b) - lg1).exp();
        let m3 = (ln_gamma(4.0 / b) - lg1).exp();
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let b = self.beta;
        let lg1 = ln_gamma(1.0 / b);
        let m1 = (ln_gamma(2.0 / b) - lg1).exp();
        let m2 = (ln_gamma(3.0 / b) - lg1).exp();
        let m3 = (ln_gamma(4.0 / b) - lg1).exp();
        let m4 = (ln_gamma(5.0 / b) - lg1).exp();
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        let mut sum = 0.0_f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "HalfGenNorm data contains non-finite value: {x}"
                )));
            }
            if x < 0.0 {
                return Err(FitError::UnsupportedData(format!(
                    "HalfGenNorm support is [0, ∞); got {x}"
                )));
            }
            sum += x;
            count += 1;
        }
        let mean = sum / count as f64;
        if mean <= 0.0 || !mean.is_finite() {
            return Err(FitError::NonConvergent(format!(
                "HalfGenNorm MoM: sample mean {mean} non-positive"
            )));
        }
        // Mean(β) = Γ(2/β) / Γ(1/β), monotone-decreasing in β.
        let mean_of = |beta: f64| ln_gamma(2.0 / beta).exp() / ln_gamma(1.0 / beta).exp();
        let mut lo = 0.1_f64;
        let mut hi = 50.0_f64;
        let m_lo = mean_of(lo);
        let m_hi = mean_of(hi);
        if !(m_hi <= mean && mean <= m_lo) {
            return Err(FitError::NonConvergent(format!(
                "HalfGenNorm MoM bracket failed: mean({lo})={m_lo}, mean({hi})={m_hi}, target={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let m_mid = mean_of(mid);
            if (m_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { beta: mid });
            }
            if m_mid > mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self {
            beta: 0.5 * (lo + hi),
        })
    }
}

/// Log-gamma distribution.
///
/// Matches `scipy.stats.loggamma`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LogGamma {
    pub c: f64,
}

impl LogGamma {
    #[must_use]
    pub fn new(c: f64) -> Self {
        assert!(c > 0.0, "c must be positive");
        Self { c }
    }
}

impl ContinuousDistribution for LogGamma {
    fn pdf(&self, x: f64) -> f64 {
        (self.c * x - x.exp() - ln_gamma(self.c)).exp()
    }

    fn logpdf(&self, x: f64) -> f64 {
        // c·x − e^x − lnΓ(c); finite in both tails where pdf underflows. frankenscipy-p82v7
        self.c * x - x.exp() - ln_gamma(self.c)
    }

    fn cdf(&self, x: f64) -> f64 {
        lower_regularized_gamma(self.c, x.exp())
    }

    fn sf(&self, x: f64) -> f64 {
        // sf = Q(c, e^x) directly; the default 1−cdf collapses for large x where
        // the lower regularized gamma rounds to 1. frankenscipy-w3f6m
        upper_regularized_gamma(self.c, x.exp())
    }

    fn logsf(&self, x: f64) -> f64 {
        // log Q(c, e^x); finite for large x where Q underflows. frankenscipy-pkaua
        fsci_special::log_gammaincc_scalar(self.c, x.exp())
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return f64::NEG_INFINITY;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        let g = fsci_special::gammaincinv_scalar(self.c, q);
        if g.is_finite() && g > 0.0 {
            g.ln()
        } else {
            (q.ln() + ln_gamma(self.c + 1.0)) / self.c
        }
    }

    fn mean(&self) -> f64 {
        fsci_special::digamma_scalar(self.c)
    }

    fn var(&self) -> f64 {
        fsci_special::trigamma(self.c)
    }

    fn entropy(&self) -> f64 {
        // X = log Y, Y ~ Gamma(c); pdf(x) = e^{cx − e^x}/Γ(c).
        // −ln pdf = ln Γ(c) − c·x + e^x. E[X] = ψ(c), E[e^X] = c, so
        //   h = ln Γ(c) − c·ψ(c) + c.
        ln_gamma(self.c) - self.c * fsci_special::digamma_scalar(self.c) + self.c
    }

    fn skewness(&self) -> f64 {
        // LogGamma cumulants are derivatives of ln Γ:
        //   κ_k = ψ^{(k−1)}(c).
        // skew = κ_3 / κ_2^{3/2} = tetragamma(c) / trigamma(c)^{3/2}.
        let kappa2 = fsci_special::trigamma(self.c);
        fsci_special::tetragamma(self.c) / kappa2.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        // excess kurt = κ_4 / κ_2² = pentagamma(c) / trigamma(c)².
        let kappa2 = fsci_special::trigamma(self.c);
        fsci_special::pentagamma(self.c) / (kappa2 * kappa2)
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        if data.len() < 2 {
            return Err(FitError::InsufficientData {
                required: 2,
                actual: data.len(),
            });
        }
        for &x in data {
            if !x.is_finite() {
                return Err(FitError::UnsupportedData(format!(
                    "LogGamma data contains non-finite value: {x}"
                )));
            }
        }
        // Method-of-moments: mean = ψ(c). Solve via bisection on c ∈ (1e-6, 1e6).
        // digamma is monotone-increasing so a single root exists.
        let mean: f64 = data.iter().sum::<f64>() / data.len() as f64;
        let mut lo = 1.0e-6_f64;
        let mut hi = 1.0e6_f64;
        let f_lo = fsci_special::digamma_scalar(lo);
        let f_hi = fsci_special::digamma_scalar(hi);
        if !(f_lo <= mean && mean <= f_hi) {
            return Err(FitError::NonConvergent(format!(
                "LogGamma MoM bracket failed: ψ({lo})={f_lo}, ψ({hi})={f_hi}, target={mean}"
            )));
        }
        for _ in 0..200 {
            let mid = 0.5 * (lo + hi);
            let f_mid = fsci_special::digamma_scalar(mid);
            if (f_mid - mean).abs() < 1.0e-12 || (hi - lo) < lo * 1.0e-12 + 1.0e-15 {
                return Ok(Self { c: mid });
            }
            if f_mid < mean {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        Ok(Self { c: 0.5 * (lo + hi) })
    }
}

/// Alpha distribution.
///
/// Matches `scipy.stats.alpha`.
pub struct Alpha {
    pub a: f64,
}

impl Alpha {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0, "a must be positive");
        Self { a }
    }
}

impl ContinuousDistribution for Alpha {
    // ndtri-class ppf (~50ns, break-even ~67-90k): pessimized ~5x@4096; gate parallel@131k.
    fn ppf_isf_par_min(&self) -> usize {
        65536
    }
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }

        let normalizer = standard_normal_cdf(self.a);
        standard_normal_pdf(self.a - 1.0 / x) / (x * x * normalizer)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // lnφ(a−1/x) − 2·ln(x) − ln(Φ(a)); finite in the tail. frankenscipy-p82v7
        if x <= 0.0 {
            return f64::NEG_INFINITY;
        }
        let z = self.a - 1.0 / x;
        -0.5 * z * z - 0.5 * (2.0 * PI).ln() - 2.0 * x.ln() - standard_normal_cdf(self.a).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }

        standard_normal_cdf(self.a - 1.0 / x) / standard_normal_cdf(self.a)
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }

        1.0 / (self.a - fsci_special::ndtri_scalar(q * standard_normal_cdf(self.a)))
    }

    fn mean(&self) -> f64 {
        f64::INFINITY
    }

    fn var(&self) -> f64 {
        f64::INFINITY
    }

    fn skewness(&self) -> f64 {
        // pdf ~ 1/(x² Φ(a)) as x → ∞, so all raw moments diverge.
        // scipy.stats.alpha.stats(moments='s') returns NaN — match.
        f64::NAN
    }

    fn kurtosis(&self) -> f64 {
        f64::NAN
    }

    fn entropy(&self) -> f64 {
        // Alpha pdf ~ 1/x² as x → ∞ but has finite entropy. Use
        // arctan compactification — direct truncation undershoots
        // because the 1/x² tail extends extremely far before becoming
        // negligible vs the −ln pdf weighting.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() || x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

/// Laplace-asymmetric distribution.
///
/// Matches `scipy.stats.laplace_asymmetric`.
pub struct LaplaceAsymmetric {
    pub kappa: f64,
}

impl LaplaceAsymmetric {
    #[must_use]
    pub fn new(kappa: f64) -> Self {
        assert!(kappa > 0.0, "kappa must be positive");
        Self { kappa }
    }
}

impl ContinuousDistribution for LaplaceAsymmetric {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        let k = self.kappa;
        let norm = 1.0 / (k + 1.0 / k);
        if x >= 0.0 {
            norm * (-x * k).exp()
        } else {
            norm * (x / k).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // −ln(κ+1/κ) − xκ (x≥0) / + x/κ (x<0); finite in both tails. frankenscipy-p82v7
        let k = self.kappa;
        let lognorm = -(k + 1.0 / k).ln();
        if x >= 0.0 {
            lognorm - x * k
        } else {
            lognorm + x / k
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        let k = self.kappa;
        if x >= 0.0 {
            // CDF = 1 - exp(-xκ) / (1+κ²)
            1.0 - (-x * k).exp() / (1.0 + k * k)
        } else {
            // CDF = κ² / (1+κ²) * exp(x/κ)
            k * k / (1.0 + k * k) * (x / k).exp()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        // Piecewise closed-form inverse; split at cdf(0)=κ²/(1+κ²). frankenscipy-ld94y
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        let k = self.kappa;
        let split = k * k / (1.0 + k * k);
        if q <= split {
            k * (q * (1.0 + k * k) / (k * k)).ln()
        } else {
            -((1.0 - q) * (1.0 + k * k)).ln() / k
        }
    }

    fn sf(&self, x: f64) -> f64 {
        // x≥0: sf = exp(−xκ)/(1+κ²) directly — the exponential tail no longer
        // collapses under 1−cdf; x<0: 1 − κ²/(1+κ²)·exp(x/κ). frankenscipy-w3f6m
        let k = self.kappa;
        if x >= 0.0 {
            (-x * k).exp() / (1.0 + k * k)
        } else {
            1.0 - k * k / (1.0 + k * k) * (x / k).exp()
        }
    }

    fn mean(&self) -> f64 {
        1.0 / self.kappa - self.kappa
    }

    fn var(&self) -> f64 {
        1.0 / (self.kappa * self.kappa) + self.kappa * self.kappa
    }

    fn skewness(&self) -> f64 {
        // Piecewise exponential moments split at 0:
        //   ∫_0^∞ x^k e^{−κx} dx = k!/κ^{k+1},
        //   ∫_{−∞}^0 x^k e^{x/κ} dx = (−1)^k k! κ^{k+1}.
        // Combine with the normalisation 1/(κ + 1/κ):
        //   m_k = k! · (1 + (−1)^k κ^{2k+2}) / ((1 + κ²) κ^k)
        let k = self.kappa;
        let one_plus_k2 = k.mul_add(k, 1.0);
        let mk = |n: u32, fact: f64, sign: f64| {
            let pow_k = k.powi(n as i32);
            fact * sign.mul_add(k.powi(2 * (n as i32) + 2), 1.0) / (one_plus_k2 * pow_k)
        };
        let m1 = mk(1, 1.0, -1.0);
        let m2 = mk(2, 2.0, 1.0);
        let m3 = mk(3, 6.0, -1.0);
        let var = m2 - m1 * m1;
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let k = self.kappa;
        let one_plus_k2 = k.mul_add(k, 1.0);
        let mk = |n: u32, fact: f64, sign: f64| {
            let pow_k = k.powi(n as i32);
            fact * sign.mul_add(k.powi(2 * (n as i32) + 2), 1.0) / (one_plus_k2 * pow_k)
        };
        let m1 = mk(1, 1.0, -1.0);
        let m2 = mk(2, 2.0, 1.0);
        let m3 = mk(3, 6.0, -1.0);
        let m4 = mk(4, 24.0, 1.0);
        let var = m2 - m1 * m1;
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // h(LaplaceAsymmetric(κ)) = 1 + ln((1 + κ²)/κ). κ = 1 collapses
        // to standard Laplace's h = 1 + ln 2.
        1.0 + (self.kappa.mul_add(self.kappa, 1.0) / self.kappa).ln()
    }

    fn try_fit(data: &[f64]) -> Result<Self, FitError> {
        // Closed-form MOM matching the first moment to the type's own
        // mean formula. LaplaceAsymmetric(κ) has mean = 1/κ − κ. Solving
        // 1/κ − κ = m̄ for κ > 0 gives the unique positive root of
        // κ² + m̄·κ − 1 = 0, i.e.
        //   κ = (−m̄ + √(m̄² + 4)) / 2.
        // (m̄ > 0 ⇒ κ < 1 ⇒ left-skewed; m̄ < 0 ⇒ κ > 1; m̄ = 0 ⇒ κ = 1
        // collapses to the symmetric Laplace.)
        validate_finite_fit_data(data, 1, "LaplaceAsymmetric")?;
        let m = sample_mean(data);
        if !m.is_finite() {
            return Err(FitError::NonConvergent(
                "LaplaceAsymmetric fit requires a finite sample mean".to_owned(),
            ));
        }
        let kappa = 0.5 * ((m * m + 4.0).sqrt() - m);
        if kappa.is_finite() && kappa > 0.0 {
            Ok(Self { kappa })
        } else {
            Err(FitError::NonConvergent(
                "LaplaceAsymmetric MOM did not yield a positive κ".to_owned(),
            ))
        }
    }
}

/// Kappa 3-parameter distribution with shape `a > 0`.
///
/// Matches `scipy.stats.kappa3(a)`. Resolves [frankenscipy-okp6z].
/// Support: x ≥ 0. (The "3-parameter" name refers to scipy's
/// shape-only parameterisation; loc and scale come from the
/// outer scipy machinery, not the distribution itself.)
///
///   pdf(x; a) = a · (a + x^a)^(−(a + 1) / a)
///   cdf(x; a) = x · (a + x^a)^(−1 / a)
///   ppf(q; a) = q · (a / (1 − q^a))^(1 / a)
///
/// Mean has no closed form for general a — left as NaN.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Kappa3 {
    pub a: f64,
}

impl Kappa3 {
    #[must_use]
    pub fn new(a: f64) -> Self {
        assert!(a > 0.0 && a.is_finite(), "a must be positive and finite");
        Self { a }
    }
}

impl ContinuousDistribution for Kappa3 {
    fn ppf_isf_is_cheap(&self) -> bool {
        true
    }

    fn cdf_sf_is_cheap(&self) -> bool {
        true
    }

    fn pdf(&self, x: f64) -> f64 {
        if x < 0.0 || !x.is_finite() {
            return 0.0;
        }
        if x == 0.0 {
            return 0.0;
        }
        let a = self.a;
        let xa = x.powf(a);
        let base = a + xa;
        a * base.powf(-(a + 1.0) / a)
    }

    fn logpdf(&self, x: f64) -> f64 {
        // ln(a) − (a+1)/a·ln(a + x^a); finite in the power-law tail. frankenscipy-p82v7
        if x <= 0.0 || !x.is_finite() {
            return f64::NEG_INFINITY;
        }
        let a = self.a;
        a.ln() - (a + 1.0) / a * (a + x.powf(a)).ln()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if !x.is_finite() {
            return 1.0;
        }
        let a = self.a;
        let xa = x.powf(a);
        // Clamp to [0, 1]: when x^a ≫ a (large a + moderate x, or
        // small a + huge x), the closed form drifts a few ulp
        // above 1. Caught by [frankenscipy-4397j] fuzz at
        // (a=19, x≈66) → 1.0 + 2e-16.
        (x * (a + xa).powf(-1.0 / a)).clamp(0.0, 1.0)
    }

    fn sf(&self, x: f64) -> f64 {
        // cdf = x·(a+x^a)^{-1/a} ≡ (1+a·x^{-a})^{-1/a}, so
        // sf = 1 − (1+a·x^{-a})^{-1/a} = −expm1(−(1/a)·ln1p(a·x^{-a})) — stable in
        // the right tail where the default 1−cdf collapses. frankenscipy-w3f6m
        if x <= 0.0 {
            return 1.0;
        }
        if !x.is_finite() {
            return 0.0;
        }
        let a = self.a;
        -(-(1.0 / a) * (a * x.powf(-a)).ln_1p()).exp_m1()
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }
        if q == 0.0 {
            return 0.0;
        }
        if q == 1.0 {
            return f64::INFINITY;
        }
        let a = self.a;
        let qa = q.powf(a);
        let denom = 1.0 - qa;
        if denom <= 0.0 {
            // q^a ≥ 1 for q very near 1 with small a — ppf
            // diverges. Return +∞ rather than NaN.
            return f64::INFINITY;
        }
        q * (a / denom).powf(1.0 / a)
    }

    fn mean(&self) -> f64 {
        // E[X] exists only when a > 1 — scipy returns NaN below that
        // threshold (frankenscipy-4htpw).
        if self.a <= 1.0 {
            return f64::NAN;
        }
        kappa3_moment(self.a, 1)
    }

    fn var(&self) -> f64 {
        if self.a <= 2.0 {
            return f64::NAN;
        }
        let m1 = kappa3_moment(self.a, 1);
        let m2 = kappa3_moment(self.a, 2);
        let v = m2 - m1 * m1;
        if v.is_finite() && v >= 0.0 {
            v
        } else {
            f64::NAN
        }
    }

    fn skewness(&self) -> f64 {
        if self.a <= 3.0 {
            return f64::NAN;
        }
        let m1 = kappa3_moment(self.a, 1);
        let m2 = kappa3_moment(self.a, 2);
        let m3 = kappa3_moment(self.a, 3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.a <= 4.0 {
            return f64::NAN;
        }
        let m1 = kappa3_moment(self.a, 1);
        let m2 = kappa3_moment(self.a, 2);
        let m3 = kappa3_moment(self.a, 3);
        let m4 = kappa3_moment(self.a, 4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Kappa3 has power-law right tail x^{-(a+1)}; compactify via
        // arctan so the integration interval is bounded.
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() || x <= 0.0 {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

/// Kappa 4-parameter distribution.
///
/// Matches `scipy.stats.kappa4`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Kappa4 {
    pub h: f64,
    pub k: f64,
}

impl Kappa4 {
    const SHAPE_TOL: f64 = 1e-15;

    #[must_use]
    pub fn new(h: f64, k: f64) -> Self {
        Self { h, k }
    }

    fn normalized_shapes(&self) -> (f64, f64) {
        let h = if self.h.abs() < Self::SHAPE_TOL {
            0.0
        } else {
            self.h
        };
        let k = if self.k.abs() < Self::SHAPE_TOL {
            0.0
        } else {
            self.k
        };
        (h, k)
    }

    fn support(&self) -> (f64, f64) {
        let (h, k) = self.normalized_shapes();
        if h > 0.0 && k > 0.0 {
            ((1.0 - h.powf(-k)) / k, 1.0 / k)
        } else if h > 0.0 && k == 0.0 {
            (h.ln(), f64::INFINITY)
        } else if h > 0.0 && k < 0.0 {
            ((1.0 - h.powf(-k)) / k, f64::INFINITY)
        } else if k > 0.0 {
            (f64::NEG_INFINITY, 1.0 / k)
        } else if k == 0.0 {
            (f64::NEG_INFINITY, f64::INFINITY)
        } else {
            (1.0 / k, f64::INFINITY)
        }
    }

    fn moment_exists(&self, order: f64) -> bool {
        let (h, k) = self.normalized_shapes();
        if k < 0.0 {
            order < -1.0 / k
        } else if h < 0.0 && k > 0.0 {
            order < -k / h
        } else {
            true
        }
    }

    fn raw_moment(&self, order: i32) -> f64 {
        if !self.moment_exists(order as f64) {
            return f64::NAN;
        }
        // Quantile-space integration keeps the numerical surface finite even
        // when the support is semi-infinite.
        simpson_integrate_adaptive(
            |q| {
                let x = self.ppf(q);
                x.powi(order)
            },
            1e-12,
            1.0 - 1e-12,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

/// Argus distribution (used in high-energy physics).
///
/// Matches `scipy.stats.argus`.
pub struct Argus {
    pub chi: f64,
}

impl Argus {
    #[must_use]
    pub fn new(chi: f64) -> Self {
        assert!(chi > 0.0, "chi must be positive");
        Self { chi }
    }

    /// k-th raw moment E[X^k] via direct adaptive Simpson on the
    /// bounded support [0, 1]. Argus moments have no elementary closed
    /// form; the pdf is smooth and well-behaved on (0, 1), so direct
    /// quadrature converges well. Mean/var keep their existing
    /// specialized routines (gammainc-based) for tighter accuracy on
    /// those two moments. Wider tolerance + lower base-grid here
    /// since 4 moments × 3 χ values at tight tolerance was burning
    /// 80 s of test time and 5e-5 already matches scipy.
    fn raw_moment_simpson(&self, k: u32) -> f64 {
        simpson_integrate_adaptive(
            |x| x.powi(k as i32) * self.pdf(x),
            1e-12,
            1.0 - 1e-12,
            1_024,
            1e-9,
            1e-9,
            6,
        )
    }
}

/// Ψ(z) = Φ(z) − z·φ(z) − ½, the Argus normalization/CDF auxiliary
/// (Φ standard normal CDF, φ standard normal PDF). frankenscipy-tvfae
fn argus_psi(z: f64) -> f64 {
    let phi = (-0.5 * z * z).exp() / (2.0 * PI).sqrt();
    standard_normal_cdf(z) - z * phi - 0.5
}

impl ContinuousDistribution for Argus {
    fn pdf(&self, x: f64) -> f64 {
        if x <= 0.0 || x >= 1.0 {
            return 0.0;
        }
        let chi = self.chi;
        let chi2 = chi * chi;
        let t = 1.0 - x * x;
        // Normalization via Ψ(χ) = Φ(χ) - χφ(χ) - 1/2
        // where Φ = standard normal CDF, φ = standard normal PDF
        let phi_chi = standard_normal_cdf(chi);
        let pdf_chi = (-0.5 * chi2).exp() / (2.0 * PI).sqrt();
        let psi = phi_chi - chi * pdf_chi - 0.5;
        let norm = if psi > 0.0 {
            chi.powi(3) / ((2.0 * PI).sqrt() * psi)
        } else {
            1.0
        };
        norm * x * t.sqrt() * (-0.5 * chi2 * t).exp()
    }

    fn cdf(&self, x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        if x >= 1.0 {
            return 1.0;
        }
        // Closed form: F(x) = 1 − Ψ(χ·√(1−x²))/Ψ(χ), Ψ(z) = Φ(z) − z·φ(z) − ½.
        // The old 400-point Simpson over the pdf lost accuracy as χ grew
        // (≈1e-7 at χ=8); this matches scipy to ~3e-14. frankenscipy-tvfae
        let chi = self.chi;
        let z = chi * (1.0 - x * x).sqrt();
        (1.0 - argus_psi(z) / argus_psi(chi)).clamp(0.0, 1.0)
    }

    fn mean(&self) -> f64 {
        let a = 0.5 * self.chi * self.chi;
        let gamma_half3 = ln_gamma(1.5).exp();
        let p = fsci_special::gammainc_scalar(1.5, a, RuntimeMode::Strict).unwrap_or(f64::NAN);
        let norm = 2.0 * a.powf(1.5) / (gamma_half3 * p);
        norm * simpson_integrate_adaptive(
            |t| (1.0 - t * t).sqrt() * t * t * (-(a * t * t)).exp(),
            0.0,
            1.0,
            1_024,
            1e-12,
            1e-12,
            8,
        )
    }

    fn var(&self) -> f64 {
        let a = 0.5 * self.chi * self.chi;
        let gamma_half3 = ln_gamma(1.5).exp();
        let gamma_half5 = ln_gamma(2.5).exp();
        let p3 = fsci_special::gammainc_scalar(1.5, a, RuntimeMode::Strict).unwrap_or(f64::NAN);
        let p5 = fsci_special::gammainc_scalar(2.5, a, RuntimeMode::Strict).unwrap_or(f64::NAN);
        let mean = self.mean();
        let gamma3 = p3 * gamma_half3;
        let gamma5 = p5 * gamma_half5;
        let second_moment = 1.0 - gamma5 / (a * gamma3);
        (second_moment - mean * mean).max(0.0)
    }

    fn skewness(&self) -> f64 {
        let m1 = self.mean();
        let m2 = self.raw_moment_simpson(2);
        let m3 = self.raw_moment_simpson(3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let m1 = self.mean();
        let m2 = self.raw_moment_simpson(2);
        let m3 = self.raw_moment_simpson(3);
        let m4 = self.raw_moment_simpson(4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // Direct Simpson over (0, 1) on −pdf(x) · ln pdf(x). The pdf is
        // smooth on the open interval and zero at the endpoints, so the
        // adaptive integrator converges without special handling.
        simpson_integrate_adaptive(
            |x| {
                let p = self.pdf(x);
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            },
            1e-12,
            1.0 - 1e-12,
            1_024,
            1e-9,
            1e-9,
            6,
        )
    }
}

impl ContinuousDistribution for Kappa4 {
    fn pdf(&self, x: f64) -> f64 {
        if x.is_nan() {
            return f64::NAN;
        }

        let (h, k) = self.normalized_shapes();
        let (lower, upper) = self.support();
        if x < lower || x > upper {
            return 0.0;
        }

        if h != 0.0 && k != 0.0 {
            let base = 1.0 - k * x;
            if base < 0.0 {
                return 0.0;
            }
            let transformed = base.powf(1.0 / k);
            let inner = 1.0 - h * transformed;
            if inner < 0.0 {
                return 0.0;
            }
            base.powf(1.0 / k - 1.0) * inner.powf(1.0 / h - 1.0)
        } else if h == 0.0 && k != 0.0 {
            let base = 1.0 - k * x;
            if base < 0.0 {
                return 0.0;
            }
            let transformed = base.powf(1.0 / k);
            base.powf(1.0 / k - 1.0) * (-transformed).exp()
        } else if h != 0.0 {
            let exp_neg_x = (-x).exp();
            let inner = 1.0 - h * exp_neg_x;
            if inner < 0.0 {
                return 0.0;
            }
            exp_neg_x * inner.powf(1.0 / h - 1.0)
        } else {
            let exp_neg_x = (-x).exp();
            (-x - exp_neg_x).exp()
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        if x.is_nan() {
            return f64::NAN;
        }
        let (h, k) = self.normalized_shapes();
        let (lower, upper) = self.support();
        if x < lower || x > upper {
            return f64::NEG_INFINITY;
        }
        // Branch-by-branch log of pdf so the tail stays finite where pdf -> 0.
        // The default logpdf = ln(pdf) returned -inf once pdf underflowed, e.g.
        // kappa4(0,0) (Gumbel) logpdf(1e4) = -1e4 vs scipy, where pdf(1e4)=0.
        if h != 0.0 && k != 0.0 {
            let base = 1.0 - k * x;
            if base <= 0.0 {
                return f64::NEG_INFINITY;
            }
            let transformed = base.powf(1.0 / k);
            let inner = 1.0 - h * transformed;
            if inner <= 0.0 {
                return f64::NEG_INFINITY;
            }
            (1.0 / k - 1.0) * base.ln() + (1.0 / h - 1.0) * inner.ln()
        } else if h == 0.0 && k != 0.0 {
            let base = 1.0 - k * x;
            if base <= 0.0 {
                return f64::NEG_INFINITY;
            }
            let transformed = base.powf(1.0 / k);
            (1.0 / k - 1.0) * base.ln() - transformed
        } else if h != 0.0 {
            let exp_neg_x = (-x).exp();
            let inner = 1.0 - h * exp_neg_x;
            if inner <= 0.0 {
                return f64::NEG_INFINITY;
            }
            -x + (1.0 / h - 1.0) * inner.ln()
        } else {
            // h == 0 && k == 0: Gumbel. pdf = exp(-x - exp(-x)).
            -x - (-x).exp()
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        if x.is_nan() {
            return f64::NAN;
        }

        let (lower, upper) = self.support();
        if x <= lower {
            return 0.0;
        }
        if x >= upper {
            return 1.0;
        }

        let (h, k) = self.normalized_shapes();
        if h != 0.0 && k != 0.0 {
            let transformed = (1.0 - k * x).powf(1.0 / k);
            (1.0 - h * transformed).powf(1.0 / h)
        } else if h == 0.0 && k != 0.0 {
            (-(1.0 - k * x).powf(1.0 / k)).exp()
        } else if h != 0.0 {
            (1.0 - h * (-x).exp()).powf(1.0 / h)
        } else {
            (-(-x).exp()).exp()
        }
    }

    fn ppf(&self, q: f64) -> f64 {
        if !(0.0..=1.0).contains(&q) {
            return f64::NAN;
        }

        let (lower, upper) = self.support();
        if q == 0.0 {
            return lower;
        }
        if q == 1.0 {
            return upper;
        }

        let (h, k) = self.normalized_shapes();
        if h != 0.0 && k != 0.0 {
            let transformed = ((1.0 - q.powf(h)) / h).powf(k);
            (1.0 - transformed) / k
        } else if h == 0.0 && k != 0.0 {
            (1.0 - (-q.ln()).powf(k)) / k
        } else if h != 0.0 {
            -((1.0 - q.powf(h)) / h).ln()
        } else {
            -(-q.ln()).ln()
        }
    }

    fn mean(&self) -> f64 {
        let (h, k) = self.normalized_shapes();
        if h == 0.0 {
            return GenExtreme::new(k).mean();
        }
        if (h - 1.0).abs() < Self::SHAPE_TOL {
            return GenPareto::new(-k).mean();
        }

        self.raw_moment(1)
    }

    fn var(&self) -> f64 {
        let (h, k) = self.normalized_shapes();
        if h == 0.0 {
            return GenExtreme::new(k).var();
        }
        if (h - 1.0).abs() < Self::SHAPE_TOL {
            return GenPareto::new(-k).var();
        }

        let mean = self.mean();
        let second_moment = self.raw_moment(2);
        let variance = second_moment - mean * mean;
        if variance.is_nan() {
            f64::NAN
        } else {
            variance.max(0.0)
        }
    }

    fn skewness(&self) -> f64 {
        let (h, k) = self.normalized_shapes();
        if h == 0.0 {
            return GenExtreme::new(k).skewness();
        }
        if (h - 1.0).abs() < Self::SHAPE_TOL {
            return GenPareto::new(-k).skewness();
        }
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        let (h, k) = self.normalized_shapes();
        if h == 0.0 {
            return GenExtreme::new(k).kurtosis();
        }
        if (h - 1.0).abs() < Self::SHAPE_TOL {
            return GenPareto::new(-k).kurtosis();
        }
        let m1 = self.raw_moment(1);
        let m2 = self.raw_moment(2);
        let m3 = self.raw_moment(3);
        let m4 = self.raw_moment(4);
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // h(Kappa4) routes through quantile-space Simpson:
        //   h = -∫ pdf(x) · ln pdf(x) dx
        //     = -∫_0^1 ln pdf(ppf(q)) dq
        // since pdf(ppf(q))·dx/dq = 1 makes the −ln pdf integrand
        // already in q-coordinates. Same machinery as the existing
        // raw_moment helper (Simpson on q ∈ [eps, 1−eps]).
        let (h, k) = self.normalized_shapes();
        if h == 0.0 {
            // GenExtreme limit: h = γ(1 − k) + 1.
            return GenExtreme::new(k).entropy();
        }
        if (h - 1.0).abs() < Self::SHAPE_TOL {
            // GenPareto limit: h = 1 + (−k).
            return GenPareto::new(-k).entropy();
        }
        simpson_integrate_adaptive(
            |q| {
                let x = self.ppf(q);
                let p = self.pdf(x);
                if p > 0.0 { -p.ln() } else { 0.0 }
            },
            1e-12,
            1.0 - 1e-12,
            4_096,
            1e-12,
            1e-12,
            10,
        )
    }
}

/// Crystal Ball distribution (used in high-energy physics).
///
/// Matches `scipy.stats.crystalball`.
pub struct CrystalBall {
    pub beta_param: f64,
    pub m: f64,
}

impl CrystalBall {
    #[must_use]
    pub fn new(beta_param: f64, m: f64) -> Self {
        assert!(beta_param > 0.0, "beta must be positive");
        assert!(m > 1.0, "m must be > 1");
        Self { beta_param, m }
    }

    /// Raw moments m_1..m_4 of CrystalBall computed exactly from
    /// closed-form integrals over both pieces of the split pdf:
    ///   gauss part: ∫_{−β}^∞ x^k e^{−x²/2} dx via recurrence
    ///     J_k = (−β)^{k−1} e^{−β²/2} + (k−1) J_{k−2}
    ///   tail part: A · Σ_{j=0..k} C(k,j) B^{k−j} (−1)^j ·
    ///                y₀^{j−m+1} / (m − j − 1),  y₀ = m/β.
    /// Convergence requires m > k + 1; the caller (skew/kurt) checks
    /// those preconditions.
    fn crystal_ball_raw_moments(&self) -> [f64; 4] {
        let beta = self.beta_param;
        let m = self.m;
        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a_coeff = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let b = m / beta - beta;
        let y0 = m / beta;
        let tail_norm = a_coeff * y0.powf(1.0 - m) / (m - 1.0);
        let total_norm = gauss_norm + tail_norm;
        let e_neg_b2 = (-0.5 * beta * beta).exp();
        let j0 = gauss_norm;
        let j1 = e_neg_b2;
        let j2 = (-beta).mul_add(e_neg_b2, gauss_norm);
        let j3 = (beta * beta + 2.0) * e_neg_b2;
        let j4 = 3.0_f64.mul_add(j2, -beta.powi(3) * e_neg_b2);
        let gauss = [j1, j2, j3, j4];
        // Tail integrals for k = 1..4 via binomial expansion of (B − y)^k.
        let tail_k = |k: u32| -> f64 {
            let mut s = 0.0_f64;
            for j in 0..=k {
                let cj = match (k, j) {
                    (1, 0) => 1.0,
                    (1, 1) => 1.0,
                    (2, 0) | (2, 2) => 1.0,
                    (2, 1) => 2.0,
                    (3, 0) | (3, 3) => 1.0,
                    (3, 1) | (3, 2) => 3.0,
                    (4, 0) | (4, 4) => 1.0,
                    (4, 1) | (4, 3) => 4.0,
                    (4, 2) => 6.0,
                    _ => 0.0,
                };
                let sign = if j % 2 == 0 { 1.0 } else { -1.0 };
                let denom = m - f64::from(j) - 1.0;
                s += cj * b.powi((k - j) as i32) * sign * y0.powf(f64::from(j) - m + 1.0) / denom;
            }
            a_coeff * s
        };
        let mut out = [0.0_f64; 4];
        for k in 1..=4u32 {
            out[k as usize - 1] = (gauss[k as usize - 1] + tail_k(k)) / total_norm;
        }
        // Silence unused j0 warning.
        let _ = j0;
        out
    }
}

impl ContinuousDistribution for CrystalBall {
    // erf/ndtr-class cdf (~25-50ns): intermediate cost, pessimized ~3-4x@4096 under the
    // default 2048 gate (break-even ~45-70k). Moderate gate -> parallel only at ~65k+.
    fn cdf_sf_par_min(&self) -> usize {
        32768
    }

    fn pdf(&self, x: f64) -> f64 {
        let beta = self.beta_param;
        let m = self.m;

        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let b = m / beta - beta;
        let tail_norm = if m > 1.0 {
            a * (m / beta).powf(1.0 - m) / (m - 1.0)
        } else {
            100.0 * a // rough estimate for divergent tail
        };
        let total_norm = gauss_norm + tail_norm;

        let unnormalized_pdf = if x > -beta {
            (-0.5 * x * x).exp()
        } else {
            a * (b - x).powf(-m)
        };

        if total_norm > 0.0 {
            unnormalized_pdf / total_norm
        } else {
            0.0
        }
    }

    fn logpdf(&self, x: f64) -> f64 {
        // Closed form so the Gaussian right arm stays finite (default ln(pdf)
        // underflows once exp(−x²/2) → 0, e.g. x≈38). frankenscipy.
        let beta = self.beta_param;
        let m = self.m;
        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let tail_norm = if m > 1.0 {
            a * (m / beta).powf(1.0 - m) / (m - 1.0)
        } else {
            100.0 * a
        };
        let total_norm = gauss_norm + tail_norm;
        // Deliberate negated comparison: `!(x > 0.0)` is TRUE for NaN, whereas
        // `x <= 0.0` is FALSE for NaN. Rewriting this to a direct comparison
        // would silently stop rejecting a NaN normalisation constant.
        #[allow(clippy::neg_cmp_op_on_partial_ord)]
        if !(total_norm > 0.0) {
            return f64::NEG_INFINITY;
        }
        let ln_norm = total_norm.ln();
        if x > -beta {
            -0.5 * x * x - ln_norm
        } else {
            // ln a = m·ln(m/β) − β²/2;  power-law arm a·(b − x)^{−m}.
            let b = m / beta - beta;
            (m * (m / beta).ln() - 0.5 * beta * beta) - m * (b - x).ln() - ln_norm
        }
    }

    fn cdf(&self, x: f64) -> f64 {
        let beta = self.beta_param;
        let m = self.m;

        // Analytical normalization: split at x = -beta
        // Gaussian part: ∫_{-β}^{∞} exp(-x²/2) dx = √(2π) * Φ(β)... wait, ∫ from -β to ∞
        // = √(2π) * (1 - Φ(-β)) = √(2π) * Φ(β)
        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);

        // Power tail part: ∫_{-∞}^{-β} A*(B-x)^{-m} dx
        let a_coeff = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let b_val = m / beta - beta;
        // ∫_{-∞}^{-β} A*(B-x)^{-m} dx = A * (B-(-β))^{1-m} / (m-1)
        // B - (-β) = m/β - β + β = m/β
        let tail_norm = if m > 1.0 {
            a_coeff * (m / beta).powf(1.0 - m) / (m - 1.0)
        } else {
            // For m <= 1 the integral diverges; use numerical fallback
            100.0 * a_coeff // rough estimate
        };

        let total_norm = gauss_norm + tail_norm;
        if total_norm <= 0.0 {
            return 0.5;
        }

        // CDF: integrate pdf from -∞ to x
        if x >= -beta {
            // All tail + Gaussian from -β to x
            let gauss_cdf_part =
                (2.0 * PI).sqrt() * (standard_normal_cdf(x) - standard_normal_cdf(-beta));
            (tail_norm + gauss_cdf_part) / total_norm
        } else {
            // Only part of the tail: ∫_{-∞}^{x} A*(B-t)^{-m} dt
            let bx = b_val - x;
            let partial = if m > 1.0 && bx > 0.0 {
                a_coeff * bx.powf(1.0 - m) / (m - 1.0)
            } else {
                0.0
            };
            // tail_norm - ∫_{x}^{-β} = tail_norm - (tail_norm - partial)
            (partial / total_norm).clamp(0.0, 1.0)
        }
    }

    fn sf(&self, x: f64) -> f64 {
        let beta = self.beta_param;
        let m = self.m;
        if x < -beta {
            // Power-law left region: cdf is small, so 1 - cdf has no cancellation.
            return 1.0 - self.cdf(x);
        }
        // Gaussian right region. From cdf = (tail_norm + sqrt(2pi)*(Phi(x)-Phi(-b)))
        // /total_norm and Phi(b)+Phi(-b)=1, the algebra collapses to
        //   sf(x) = sqrt(2pi) * Phi(-x) / total_norm,
        // which equals 1 - cdf but evaluates Phi(-x) via erfc (standard_normal_cdf
        // is erfc-stable for negative args) instead of cancelling 1 - cdf -> 0.
        // The default underflowed sf to exactly 0 by x~8 (scipy: 7.5e-24). frankenscipy.
        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a_coeff = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let tail_norm = if m > 1.0 {
            a_coeff * (m / beta).powf(1.0 - m) / (m - 1.0)
        } else {
            100.0 * a_coeff
        };
        let total_norm = gauss_norm + tail_norm;
        if total_norm <= 0.0 {
            return 0.5;
        }
        ((2.0 * PI).sqrt() * standard_normal_cdf(-x) / total_norm).clamp(0.0, 1.0)
    }

    fn mean(&self) -> f64 {
        let beta = self.beta_param;
        let m = self.m;
        if m <= 2.0 {
            return f64::INFINITY;
        }

        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let b = m / beta - beta;
        let y0 = m / beta;
        let tail_norm = a * y0.powf(1.0 - m) / (m - 1.0);
        let total_norm = gauss_norm + tail_norm;

        let gauss_first = (-0.5 * beta * beta).exp();
        let tail_first = a * (b * y0.powf(1.0 - m) / (m - 1.0) - y0.powf(2.0 - m) / (m - 2.0));

        (gauss_first + tail_first) / total_norm
    }

    fn var(&self) -> f64 {
        let beta = self.beta_param;
        let m = self.m;
        if m <= 3.0 {
            return f64::INFINITY;
        }

        let mean = self.mean();
        let gauss_norm = (2.0 * PI).sqrt() * standard_normal_cdf(beta);
        let a = (m / beta).powf(m) * (-0.5 * beta * beta).exp();
        let b = m / beta - beta;
        let y0 = m / beta;
        let tail_norm = a * y0.powf(1.0 - m) / (m - 1.0);
        let total_norm = gauss_norm + tail_norm;

        let gauss_second = gauss_norm - beta * (-0.5 * beta * beta).exp();
        let tail_second = a
            * (b * b * y0.powf(1.0 - m) / (m - 1.0) - 2.0 * b * y0.powf(2.0 - m) / (m - 2.0)
                + y0.powf(3.0 - m) / (m - 3.0));
        let second_moment = (gauss_second + tail_second) / total_norm;

        (second_moment - mean * mean).max(0.0)
    }

    fn skewness(&self) -> f64 {
        // m_k requires m > k + 1 (power-tail convergence). Skew needs
        // m > 4.
        if self.m <= 4.0 {
            return f64::NAN;
        }
        let [m1, m2, m3, _] = self.crystal_ball_raw_moments();
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu3 = 2.0_f64.mul_add(m1.powi(3), m3 - 3.0 * m1 * m2);
        mu3 / var.powf(1.5)
    }

    fn kurtosis(&self) -> f64 {
        if self.m <= 5.0 {
            return f64::NAN;
        }
        let [m1, m2, m3, m4] = self.crystal_ball_raw_moments();
        let var = m2 - m1 * m1;
        if !var.is_finite() || var <= 0.0 {
            return f64::NAN;
        }
        let mu4 = (-3.0_f64).mul_add(
            m1.powi(4),
            6.0_f64.mul_add(m1 * m1 * m2, 4.0_f64.mul_add(-m1 * m3, m4)),
        );
        mu4 / (var * var) - 3.0
    }

    fn entropy(&self) -> f64 {
        // CrystalBall has a power-law left tail (1/x^m); the right
        // tail is gaussian. Use arctan compactification to handle the
        // left tail safely; right tail handled by capping at a wide
        // positive bound first.
        // Translate via u = arctan(x): u ∈ (−π/2, π/2).
        simpson_integrate_adaptive(
            |u| {
                let x = u.tan();
                if !x.is_finite() {
                    return 0.0;
                }
                let p = self.pdf(x);
                if p > 0.0 {
                    let sec2 = 1.0 / u.cos().powi(2);
                    -p * p.ln() * sec2
                } else {
                    0.0
                }
            },
            -PI / 2.0 + 1e-12,
            PI / 2.0 - 1e-12,
            4_096,
            1e-9,
            1e-9,
            10,
        )
    }
}

// ══════════════════════════════════════════════════════════════════════
// Ranking and Order Statistics
// ══════════════════════════════════════════════════════════════════════

/// Compute quantiles of data at given probabilities.
///
/// Matches `numpy.quantile`.
pub fn quantile(data: &[f64], q: &[f64]) -> Vec<f64> {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return vec![f64::NAN; q.len()];
    }
    let n = data.len();

    // Each requested quantile reads only the one or two ranks sorted[lo]/sorted[hi].
    // When there are few of them relative to log2(n), partition per quantile in
    // O(n) (select_ranks) rather than fully sorting once (O(n log n)). Both paths
    // are byte-identical, so the gate only affects speed.
    if (q.len() as f64) < (n as f64).log2().max(1.0) {
        let mut buf = data.to_vec();
        return q
            .iter()
            .map(|&qi| {
                let qi = qi.clamp(0.0, 1.0);
                let idx = qi * (n - 1) as f64;
                let lo = idx.floor() as usize;
                let hi = idx.ceil() as usize;
                let frac = idx - lo as f64;
                let (v_lo, v_hi) = select_ranks(&mut buf, lo, hi);
                if lo == hi {
                    v_lo
                } else {
                    v_lo * (1.0 - frac) + v_hi * frac
                }
            })
            .collect();
    }

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    q.iter()
        .map(|&qi| {
            let qi = qi.clamp(0.0, 1.0);
            let idx = qi * (n - 1) as f64;
            let lo = idx.floor() as usize;
            let hi = idx.ceil() as usize;
            let frac = idx - lo as f64;
            if lo == hi || hi >= n {
                sorted[lo.min(n - 1)]
            } else {
                sorted[lo] * (1.0 - frac) + sorted[hi] * frac
            }
        })
        .collect()
}

/// Compute weighted quantiles of data at given probabilities.
///
/// Uses linear interpolation between data points where cumulative
/// weight crosses the quantile threshold.
pub fn quantile_weighted(data: &[f64], q: &[f64], weights: &[f64]) -> Vec<f64> {
    if data.is_empty() || data.len() != weights.len() {
        return vec![f64::NAN; q.len()];
    }
    if data.iter().any(|v| v.is_nan()) {
        return vec![f64::NAN; q.len()];
    }
    if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
        return vec![f64::NAN; q.len()];
    }
    let total_w: f64 = weights.iter().sum();
    if total_w <= 0.0 {
        return vec![f64::NAN; q.len()];
    }

    let mut pairs: Vec<(f64, f64)> = data.iter().zip(weights).map(|(&x, &w)| (x, w)).collect();
    pairs.sort_by(|a, b| a.0.total_cmp(&b.0));

    let mut cumulative = Vec::with_capacity(pairs.len());
    let mut acc = 0.0;
    for &(_, w) in &pairs {
        acc += w;
        cumulative.push(acc);
    }

    q.iter()
        .map(|&qi| {
            let qi = qi.clamp(0.0, 1.0);
            let target = qi * total_w;

            if target <= 0.0 {
                return pairs[0].0;
            }
            if target >= total_w {
                return pairs.last().map(|&(x, _)| x).unwrap_or(f64::NAN);
            }

            for (i, &cum) in cumulative.iter().enumerate() {
                if cum >= target {
                    if i == 0 {
                        return pairs[0].0;
                    }
                    let prev_cum = cumulative[i - 1];
                    let frac = (target - prev_cum) / (cum - prev_cum);
                    return pairs[i - 1].0 * (1.0 - frac) + pairs[i].0 * frac;
                }
            }
            pairs.last().map(|&(x, _)| x).unwrap_or(f64::NAN)
        })
        .collect()
}

/// Compute weighted mean.
pub fn weighted_mean(values: &[f64], weights: &[f64]) -> f64 {
    if values.len() != weights.len() {
        return f64::NAN;
    }
    // Accumulate the denominator and numerator together. Each accumulator sees
    // exactly the same left-to-right operation sequence as the former two-pass
    // implementation, while weights are loaded only once on the valid path.
    let mut total_w = 0.0;
    let mut weighted_total = 0.0;
    for (&value, &weight) in values.iter().zip(weights) {
        total_w += weight;
        weighted_total += value * weight;
    }
    if total_w == 0.0 {
        return f64::NAN;
    }
    weighted_total / total_w
}

/// Compute weighted variance.
pub fn weighted_var(values: &[f64], weights: &[f64]) -> f64 {
    if values.len() != weights.len() {
        return f64::NAN;
    }
    let mean = weighted_mean(values, weights);
    let total_w: f64 = weights.iter().sum();
    if total_w == 0.0 {
        return f64::NAN;
    }
    values
        .iter()
        .zip(weights.iter())
        .map(|(&v, &w)| w * (v - mean).powi(2))
        .sum::<f64>()
        / total_w
}

/// Compute weighted standard deviation.
pub fn weighted_std(values: &[f64], weights: &[f64]) -> f64 {
    weighted_var(values, weights).sqrt()
}

/// When `true`, [`neff`] runs its finite-check, `Σw` and `Σw²` as three separate passes (the ORIG
/// behaviour); default `false` folds all three into one pass over weights. Byte-identical.
#[doc(hidden)]
/// A/B switch: run `neff`'s weight validity check, `sum(w)` and `sum(w^2)` as
/// three separate passes instead of one fused pass.
///
/// CONTRACT: BYTE-IDENTICAL either way. The fused arm performs the SAME
/// additions in the SAME order as the separate passes it replaces --
/// `Iterator::sum::<f64>()` is a left fold from 0.0, and the fused loop
/// accumulates left to right from 0.0 over the same pairs -- so no float is
/// reassociated. Fusing changes how many times the data is traversed, not what
/// is added to what.
///
/// The early-out is preserved exactly: a non-finite or negative weight still
/// returns NaN, and the sums computed before that point are discarded in the
/// fused arm just as the original early-out discarded them.
pub static NEFF_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Kish's effective sample size for weighted data.
///
/// Computes the effective sample size when observations have different weights.
/// n_eff = (Σw)² / Σ(w²)
///
/// For equal weights, returns the actual sample size.
/// For highly variable weights, returns a smaller effective size.
pub fn neff(weights: &[f64]) -> f64 {
    if weights.is_empty() {
        return 0.0;
    }
    // The finite/non-negative check, `Σw` and `Σw²` are three INDEPENDENT all-light reductions over
    // `weights` — fold them into ONE pass. BYTE-IDENTICAL: each Σ keeps its exact left-to-right order
    // and `w * w` expression, and a bad weight still returns NaN (the sums discarded on that path
    // exactly as the original early-out discarded them).
    let (sum_w, sum_w2) = if NEFF_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        (
            weights.iter().sum::<f64>(),
            weights.iter().map(|&w| w * w).sum::<f64>(),
        )
    } else {
        let mut sum_w = 0.0f64;
        let mut sum_w2 = 0.0f64;
        let mut valid = true;
        for &w in weights {
            valid &= w.is_finite() && w >= 0.0;
            sum_w += w;
            sum_w2 += w * w;
        }
        if !valid {
            return f64::NAN;
        }
        (sum_w, sum_w2)
    };
    if sum_w2 == 0.0 {
        return 0.0;
    }
    (sum_w * sum_w) / sum_w2
}

/// Compute the geometric mean.
///
/// Matches `scipy.stats.gmean`.
pub fn gmean(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let n = data.len() as f64;
    (gmean_log_sum(data) / n).exp()
}

/// `Σ ln(xᵢ)` with four independent accumulators (break the fold's latency chain
/// so the `ln`-bound loop pipelines) and, for large inputs, split across threads —
/// each output is an independent `ln` then a reduction. ~1e-15 reassociation vs
/// the serial fold (the same order as the geometric mean's float rounding).
fn gmean_log_sum(data: &[f64]) -> f64 {
    let chunk_sum = |chunk: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= chunk.len() {
            a[0] += chunk[i].ln();
            a[1] += chunk[i + 1].ln();
            a[2] += chunk[i + 2].ln();
            a[3] += chunk[i + 3].ln();
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < chunk.len() {
            s += chunk[i].ln();
            i += 1;
        }
        s
    };
    let n = data.len();
    // Short-circuit small inputs BEFORE probing parallelism: `available_parallelism()`
    // is a `sched_getaffinity` syscall, and when `gmean` is called once per line by
    // `gmean_axis_2d` (thousands of short lines), that per-call syscall dominates the
    // (otherwise cheap) `ln` work. The serial `chunk_sum` is what we'd take here anyway.
    if n < (1 << 16) {
        return chunk_sum(data);
    }
    // Cap workers so each owns >=64k elements: the per-element `ln` is light, so a
    // 64-way split has too little work per chunk to amortize the thread spawn.
    let cores = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let threads = cores.min((n / (1 << 16)).max(1)).min(16);
    if threads <= 1 {
        return chunk_sum(data);
    }
    let chunk = n.div_ceil(threads);
    let parts: Vec<f64> = std::thread::scope(|scope| {
        let handles: Vec<_> = data
            .chunks(chunk)
            .map(|c| scope.spawn(move || chunk_sum(c)))
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    parts.iter().sum()
}

/// When `true`, [`mean_weighted`] runs its weights finite-check, `Σw` and the weighted-mean numerator
/// `Σw·x` as three separate passes (the ORIG behaviour); default `false` folds all three into ONE pass
/// over (data, weights). Byte-identical. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
/// A/B switch: run `mean_weighted`'s weight validity check, `sum(w)` and the
/// numerator `sum(w*x)` as separate passes instead of one fused pass.
///
/// CONTRACT: BYTE-IDENTICAL either way. The fused arm performs the SAME
/// additions in the SAME order as the separate passes it replaces --
/// `Iterator::sum::<f64>()` is a left fold from 0.0, and the fused loop
/// accumulates left to right from 0.0 over the same pairs -- so no float is
/// reassociated. Fusing changes how many times the data is traversed, not what
/// is added to what.
///
/// The NaN paths are preserved: a bad weight returns NaN before the polluted
/// sums are used, and a non-positive `sum(w)` returns NaN, exactly as in the
/// unfused arm.
pub static MEAN_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Weighted arithmetic mean.
///
/// Computes the weighted mean: Σ(w·x) / Σw
pub fn mean_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() {
        return f64::NAN;
    }
    if MEAN_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return f64::NAN;
        }
        return data.iter().zip(weights).map(|(&x, &w)| w * x).sum::<f64>() / total_w;
    }
    // Fuse the weights-validity check, `Σw`, and the numerator `Σw·x` into ONE pass. BYTE-IDENTICAL:
    // `total_w` and `sum_wx` are the same left-to-right folds from 0.0 over (data,weights) in order,
    // and a bad weight still returns NaN before the polluted sums are used (same as the early-out).
    let mut total_w = 0.0f64;
    let mut sum_wx = 0.0f64;
    let mut valid = true;
    for (&x, &w) in data.iter().zip(weights) {
        valid &= w.is_finite() && w >= 0.0;
        total_w += w;
        sum_wx += w * x;
    }
    if !valid {
        return f64::NAN;
    }
    if total_w <= 0.0 {
        return f64::NAN;
    }
    sum_wx / total_w
}

/// When `true`, [`var_weighted`] runs its weights finite-check, `Σw` and the weighted-mean sum as
/// separate passes (the ORIG behaviour); default `false` folds all three into one pass over
/// (data, weights). Byte-identical.
#[doc(hidden)]
/// A/B switch: run `var_weighted`'s weight check, `sum(w)` and weighted-mean
/// sum as separate passes instead of one fused pass.
///
/// CONTRACT: BYTE-IDENTICAL either way. The fused arm performs the SAME
/// additions in the SAME order as the separate passes it replaces --
/// `Iterator::sum::<f64>()` is a left fold from 0.0, and the fused loop
/// accumulates left to right from 0.0 over the same pairs -- so no float is
/// reassociated. Fusing changes how many times the data is traversed, not what
/// is added to what.
///
/// Note this fuses only the FIRST sweep. The weighted mean must be known before
/// the squared deviations can be accumulated, so the second sweep remains a
/// second sweep in both arms -- the toggle does not change that structure.
pub static VAR_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Weighted variance (population variance with frequency weights).
///
/// Computes: Σ(w·(x - μ)²) / Σw where μ is the weighted mean.
pub fn var_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.len() < 2 || data.len() != weights.len() {
        return f64::NAN;
    }
    // BYTE-IDENTICAL fusion: the weights finite/non-negative check, `Σw`, and the weighted-mean
    // numerator `Σw·x` are three INDEPENDENT reductions — fold them into ONE pass. Each Σ keeps its
    // left-to-right order and `w * x` expression; a bad weight still returns NaN (polluted sums
    // discarded exactly as the original early-out discarded them). The `var` pass depends on the mean.
    let (total_w, mean_val) = if VAR_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return f64::NAN;
        }
        let mean_val: f64 = data.iter().zip(weights).map(|(&x, &w)| w * x).sum::<f64>() / total_w;
        (total_w, mean_val)
    } else {
        let mut total_w = 0.0f64;
        let mut sum_wx = 0.0f64;
        let mut valid = true;
        for (&x, &w) in data.iter().zip(weights) {
            valid &= w.is_finite() && w >= 0.0;
            total_w += w;
            sum_wx += w * x;
        }
        if !valid {
            return f64::NAN;
        }
        if total_w <= 0.0 {
            return f64::NAN;
        }
        (total_w, sum_wx / total_w)
    };
    data.iter()
        .zip(weights)
        .map(|(&x, &w)| w * (x - mean_val).powi(2))
        .sum::<f64>()
        / total_w
}

/// Weighted standard deviation.
///
/// Square root of weighted variance.
pub fn std_weighted(data: &[f64], weights: &[f64]) -> f64 {
    var_weighted(data, weights).sqrt()
}

/// Compute the sample covariance between two arrays.
///
/// cov(x, y) = Σ((x - mean_x)(y - mean_y)) / (n - 1)
pub fn cov(x: &[f64], y: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() < 2 {
        return f64::NAN;
    }
    let n = x.len() as f64;
    // Two means fused into ONE work-gated pass (parallel for huge inputs, byte-identical below the
    // gate) — the ORIG made two separate serial `iter().sum()` traversals before the parallel reduction.
    let (mean_x, mean_y) = par_two_means(x, y);
    // Centered cross-product Σ(x−mx)(y−my) — the dominant O(n) reduction (means fixed above). Below the
    // gate (and under PEARSONR_FORCE_SERIAL) fold in ONE serial pass (byte-identical to `.map().sum()`);
    // above 1<<22 fan across cores as per-thread partials, within per-op ULP tolerance. Same lever as the
    // pearsonr/linregress/corrcoef family.
    let nn = x.len();
    let chunk_sum = |xs: &[f64], ys: &[f64]| -> f64 {
        let mut s = 0.0f64;
        for (&xi, &yi) in xs.iter().zip(ys) {
            s += (xi - mean_x) * (yi - mean_y);
        }
        s
    };
    let ssxym =
        if PEARSONR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || nn < (1 << 22) {
            chunk_sum(x, y)
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(nn / (1 << 16))
                .max(1);
            let chunk = nn.div_ceil(nthreads);
            let chunk_sum = &chunk_sum;
            let parts: Vec<f64> = std::thread::scope(|scope| {
                x.chunks(chunk)
                    .zip(y.chunks(chunk))
                    .map(|(xs, ys)| scope.spawn(move || chunk_sum(xs, ys)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("cov worker panicked"))
                    .collect()
            });
            parts.into_iter().fold(0.0f64, |acc, s| acc + s)
        };
    ssxym / (n - 1.0)
}

/// When `true`, [`cov_weighted`] runs its weights finite-check and the two weighted-mean sums as
/// separate passes (the ORIG behaviour); default `false` folds the check into `Σw` and computes both
/// mean sums in one zip pass. Byte-identical.
#[doc(hidden)]
/// A/B switch: run the weighted covariance's `sum(w)`, `sum(w*x)` and `sum(w*y)`
/// as separate passes instead of one fused pass.
///
/// CONTRACT: BYTE-IDENTICAL either way. The fused arm performs the SAME
/// additions in the SAME order as the separate passes it replaces --
/// `Iterator::sum::<f64>()` is a left fold from 0.0, and the fused loop
/// accumulates left to right from 0.0 over the same pairs -- so no float is
/// reassociated. Fusing changes how many times the data is traversed, not what
/// is added to what.
pub static CW_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the weighted covariance between two arrays.
///
/// cov_w(x, y) = Σ(w·(x - mean_x)(y - mean_y)) / Σw
pub fn cov_weighted(x: &[f64], y: &[f64], weights: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() != weights.len() || x.len() < 2 {
        return f64::NAN;
    }
    // BYTE-IDENTICAL fusion: fold the weights finite/non-negative check into the `Σw` pass, and
    // compute `Σw·xi` and `Σw·yi` in ONE zip pass (two independent accumulators over the same order
    // as the separate passes). Every Σ keeps its exact left-to-right order and `w * xi` / `w * yi`
    // expressions; a bad weight still returns NaN (the polluted sums discarded exactly as the
    // original early-out discarded them).
    let (total_w, sum_wx, sum_wy) = if CW_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return f64::NAN;
        }
        let sum_wx: f64 = x.iter().zip(weights).map(|(&xi, &w)| w * xi).sum::<f64>();
        let sum_wy: f64 = y.iter().zip(weights).map(|(&yi, &w)| w * yi).sum::<f64>();
        (total_w, sum_wx, sum_wy)
    } else {
        let mut total_w = 0.0f64;
        let mut valid = true;
        for &w in weights {
            valid &= w.is_finite() && w >= 0.0;
            total_w += w;
        }
        if !valid {
            return f64::NAN;
        }
        if total_w <= 0.0 {
            return f64::NAN;
        }
        let mut sum_wx = 0.0f64;
        let mut sum_wy = 0.0f64;
        for ((&xi, &yi), &w) in x.iter().zip(y).zip(weights) {
            sum_wx += w * xi;
            sum_wy += w * yi;
        }
        (total_w, sum_wx, sum_wy)
    };
    let mean_x: f64 = sum_wx / total_w;
    let mean_y: f64 = sum_wy / total_w;
    x.iter()
        .zip(y)
        .zip(weights)
        .map(|((&xi, &yi), &w)| w * (xi - mean_x) * (yi - mean_y))
        .sum::<f64>()
        / total_w
}

/// Compute the Pearson correlation coefficient between two arrays.
///
/// r = cov(x, y) / (std(x) * std(y))
pub fn corrcoef(x: &[f64], y: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() < 2 {
        return f64::NAN;
    }
    // Two means fused into ONE work-gated pass (parallel for huge inputs, byte-identical below the
    // gate) — the ORIG made two separate serial `iter().sum()` traversals before the parallel reduction.
    let (mean_x, mean_y) = par_two_means(x, y);
    // Centered cov/variances (cov_xy=Σdx·dy, var_x=Σdx², var_y=Σdy²) — the dominant O(n) reduction
    // (means fixed above). Below the gate (and under PEARSONR_FORCE_SERIAL) fold the three in ONE serial
    // pass (byte-identical to the original loop); above 1<<22 fan them across cores as per-thread partial
    // triples, within per-op ULP tolerance. Same lever as `pearsonr`/`linregress`.
    let nn = x.len();
    let chunk_ss = |xs: &[f64], ys: &[f64]| -> (f64, f64, f64) {
        let mut cov = 0.0f64;
        let mut vx = 0.0f64;
        let mut vy = 0.0f64;
        for (&xi, &yi) in xs.iter().zip(ys) {
            let dx = xi - mean_x;
            let dy = yi - mean_y;
            cov += dx * dy;
            vx += dx * dx;
            vy += dy * dy;
        }
        (cov, vx, vy)
    };
    let (cov_xy, var_x, var_y) =
        if PEARSONR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || nn < (1 << 22) {
            chunk_ss(x, y)
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(nn / (1 << 16))
                .max(1);
            let chunk = nn.div_ceil(nthreads);
            let chunk_ss = &chunk_ss;
            let parts: Vec<(f64, f64, f64)> = std::thread::scope(|scope| {
                x.chunks(chunk)
                    .zip(y.chunks(chunk))
                    .map(|(xs, ys)| scope.spawn(move || chunk_ss(xs, ys)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("corrcoef worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0.0f64, 0.0f64), |(am, bm, cm), (a, b, c)| {
                    (am + a, bm + b, cm + c)
                })
        };
    if var_x == 0.0 || var_y == 0.0 {
        return f64::NAN;
    }
    cov_xy / (var_x * var_y).sqrt()
}

/// When `true`, [`corrcoef_weighted`] runs its weights finite-check, `Σw` and the two weighted-mean
/// sums as separate passes (the ORIG behaviour); default `false` folds all four into one pass over
/// (x, y, weights). Byte-identical.
#[doc(hidden)]
pub static CORRCOEF_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the weighted Pearson correlation coefficient.
///
/// r_w = cov_w(x, y) / (std_w(x) * std_w(y))
pub fn corrcoef_weighted(x: &[f64], y: &[f64], weights: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() != weights.len() || x.len() < 2 {
        return f64::NAN;
    }
    // BYTE-IDENTICAL fusion: the weights finite/non-negative check, `Σw`, and the two weighted-mean
    // numerators `Σw·x` and `Σw·y` are four INDEPENDENT reductions over (x, y, weights) — fold them
    // into ONE pass (the moment loop below was already fused). Each Σ keeps its exact left-to-right
    // order and `w * xi` / `w * yi` expressions; a bad weight still returns NaN (polluted sums
    // discarded exactly as the original early-out discarded them).
    let (total_w, sum_wx, sum_wy) =
        if CORRCOEF_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
            if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
                return f64::NAN;
            }
            let total_w: f64 = weights.iter().sum();
            if total_w <= 0.0 {
                return f64::NAN;
            }
            let sum_wx: f64 = x.iter().zip(weights).map(|(&xi, &w)| w * xi).sum::<f64>();
            let sum_wy: f64 = y.iter().zip(weights).map(|(&yi, &w)| w * yi).sum::<f64>();
            (total_w, sum_wx, sum_wy)
        } else {
            let mut total_w = 0.0f64;
            let mut sum_wx = 0.0f64;
            let mut sum_wy = 0.0f64;
            let mut valid = true;
            for ((&xi, &yi), &w) in x.iter().zip(y).zip(weights) {
                valid &= w.is_finite() && w >= 0.0;
                total_w += w;
                sum_wx += w * xi;
                sum_wy += w * yi;
            }
            if !valid {
                return f64::NAN;
            }
            if total_w <= 0.0 {
                return f64::NAN;
            }
            (total_w, sum_wx, sum_wy)
        };
    let mean_x: f64 = sum_wx / total_w;
    let mean_y: f64 = sum_wy / total_w;
    let mut cov_xy = 0.0;
    let mut var_x = 0.0;
    let mut var_y = 0.0;
    for ((&xi, &yi), &w) in x.iter().zip(y).zip(weights) {
        let dx = xi - mean_x;
        let dy = yi - mean_y;
        cov_xy += w * dx * dy;
        var_x += w * dx * dx;
        var_y += w * dy * dy;
    }
    if var_x == 0.0 || var_y == 0.0 {
        return f64::NAN;
    }
    cov_xy / (var_x * var_y).sqrt()
}

/// Lin's concordance correlation coefficient.
///
/// Measures agreement between two continuous measurements.
/// Unlike Pearson's r, CCC penalizes both lack of precision and accuracy.
///
/// CCC = 2 * cov(x,y) / (var(x) + var(y) + (mean(x) - mean(y))²)
///
/// # Returns
/// CCC value in [-1, 1] where 1 = perfect agreement, 0 = no agreement.
pub fn concordance_correlation(x: &[f64], y: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() < 2 {
        return f64::NAN;
    }

    let n = x.len() as f64;
    let mean_x = x.iter().sum::<f64>() / n;
    let mean_y = y.iter().sum::<f64>() / n;

    let var_x: f64 = x.iter().map(|&xi| (xi - mean_x).powi(2)).sum::<f64>() / n;
    let var_y: f64 = y.iter().map(|&yi| (yi - mean_y).powi(2)).sum::<f64>() / n;
    let cov_xy: f64 = x
        .iter()
        .zip(y)
        .map(|(&xi, &yi)| (xi - mean_x) * (yi - mean_y))
        .sum::<f64>()
        / n;

    let mean_diff_sq = (mean_x - mean_y).powi(2);
    let denom = var_x + var_y + mean_diff_sq;

    if denom == 0.0 {
        return f64::NAN;
    }

    2.0 * cov_xy / denom
}

/// Result of Bland-Altman analysis.
#[derive(Debug, Clone, PartialEq)]
pub struct BlandAltmanResult {
    /// Mean of differences (bias).
    pub mean_diff: f64,
    /// Standard deviation of differences.
    pub std_diff: f64,
    /// Lower limit of agreement (mean - 1.96*std).
    pub lower_loa: f64,
    /// Upper limit of agreement (mean + 1.96*std).
    pub upper_loa: f64,
}

/// Bland-Altman analysis for method comparison.
///
/// Computes the mean difference (bias) and limits of agreement
/// between two measurement methods.
///
/// # Arguments
/// * `method1` - Measurements from first method
/// * `method2` - Measurements from second method
/// * `confidence` - Confidence level for limits (default 0.95 gives ±1.96*SD)
///
/// # Returns
/// `BlandAltmanResult` with bias and limits of agreement.
pub fn bland_altman(method1: &[f64], method2: &[f64], confidence: f64) -> BlandAltmanResult {
    if method1.len() != method2.len() || method1.len() < 2 {
        return BlandAltmanResult {
            mean_diff: f64::NAN,
            std_diff: f64::NAN,
            lower_loa: f64::NAN,
            upper_loa: f64::NAN,
        };
    }

    let n = method1.len() as f64;
    let diffs: Vec<f64> = method1.iter().zip(method2).map(|(&a, &b)| a - b).collect();

    let mean_diff = diffs.iter().sum::<f64>() / n;
    let var_diff = diffs.iter().map(|&d| (d - mean_diff).powi(2)).sum::<f64>() / (n - 1.0);
    let std_diff = var_diff.sqrt();

    let alpha = 1.0 - confidence;
    let z = standard_normal_ppf(1.0 - alpha / 2.0);

    BlandAltmanResult {
        mean_diff,
        std_diff,
        lower_loa: mean_diff - z * std_diff,
        upper_loa: mean_diff + z * std_diff,
    }
}

/// Compute the partial correlation between x and y, controlling for z.
///
/// The partial correlation measures the relationship between x and y
/// after removing the linear effect of the control variable z.
///
/// r_xy.z = (r_xy - r_xz * r_yz) / sqrt((1 - r_xz²) * (1 - r_yz²))
///
/// # Arguments
/// * `x` - First variable
/// * `y` - Second variable
/// * `z` - Control variable
///
/// # Returns
/// Partial correlation coefficient in [-1, 1].
pub fn partial_corr(x: &[f64], y: &[f64], z: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() != z.len() || x.len() < 3 {
        return f64::NAN;
    }

    let r_xy = corrcoef(x, y);
    let r_xz = corrcoef(x, z);
    let r_yz = corrcoef(y, z);

    if r_xy.is_nan() || r_xz.is_nan() || r_yz.is_nan() {
        return f64::NAN;
    }

    let denom_x = 1.0 - r_xz * r_xz;
    let denom_y = 1.0 - r_yz * r_yz;

    if denom_x <= 0.0 || denom_y <= 0.0 {
        return f64::NAN;
    }

    (r_xy - r_xz * r_yz) / (denom_x * denom_y).sqrt()
}

/// Compute the semi-partial (part) correlation of x and y, controlling for z in y only.
///
/// The semi-partial correlation measures the unique contribution of y to x,
/// after removing the effect of z from y but not from x.
///
/// r_x(y.z) = (r_xy - r_xz * r_yz) / sqrt(1 - r_yz²)
///
/// # Arguments
/// * `x` - Criterion variable
/// * `y` - Predictor variable (effect of z removed)
/// * `z` - Control variable
///
/// # Returns
/// Semi-partial correlation coefficient.
pub fn semi_partial_corr(x: &[f64], y: &[f64], z: &[f64]) -> f64 {
    if x.len() != y.len() || x.len() != z.len() || x.len() < 3 {
        return f64::NAN;
    }

    let r_xy = corrcoef(x, y);
    let r_xz = corrcoef(x, z);
    let r_yz = corrcoef(y, z);

    if r_xy.is_nan() || r_xz.is_nan() || r_yz.is_nan() {
        return f64::NAN;
    }

    let denom = 1.0 - r_yz * r_yz;
    if denom <= 0.0 {
        return f64::NAN;
    }

    (r_xy - r_xz * r_yz) / denom.sqrt()
}

/// When `true`, [`nanmean`] materializes the NaN-filtered `Vec` then sums it (the ORIG
/// behaviour); default `false` folds `(sum, count)` inline with no allocation. Byte-identical.
#[doc(hidden)]
pub static NANMEAN_FORCE_COLLECT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute mean ignoring NaN values.
///
/// Matches `numpy.nanmean`.
pub fn nanmean(data: &[f64]) -> f64 {
    if NANMEAN_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed) {
        let valid: Vec<f64> = data.iter().copied().filter(|x| !x.is_nan()).collect();
        if valid.is_empty() {
            return f64::NAN;
        }
        return valid.iter().sum::<f64>() / valid.len() as f64;
    }
    // Fold Σ and the count in ONE pass without materializing the filtered Vec. BYTE-IDENTICAL:
    // Σ is the same left-to-right fold from 0.0 over the same non-NaN elements in data order
    // as `valid.iter().sum()`, and `count == valid.len()`.
    let mut sum = 0.0f64;
    let mut count = 0usize;
    for &x in data {
        if !x.is_nan() {
            sum += x;
            count += 1;
        }
    }
    if count == 0 {
        return f64::NAN;
    }
    sum / count as f64
}

/// When `true`, [`nanvar`] (and thus [`nanstd`]) and [`nanzscore`]'s mean/variance setup materialize
/// the NaN-filtered `Vec` then make two passes over it (the ORIG behaviour); default `false` re-filters
/// inline in two passes with no allocation. Byte-identical. (`nanvar` re-filters always; `nanzscore`
/// gates the inline path to the memory-bound regime, keeping the collect path for small inputs.)
#[doc(hidden)]
pub static NANVAR_FORCE_COLLECT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute variance ignoring NaN values.
///
/// Matches `numpy.nanvar`.
pub fn nanvar(data: &[f64]) -> f64 {
    if NANVAR_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed) {
        let valid: Vec<f64> = data.iter().copied().filter(|x| !x.is_nan()).collect();
        if valid.len() < 2 {
            return f64::NAN;
        }
        let n = valid.len() as f64;
        let mean = valid.iter().sum::<f64>() / n;
        return valid.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
    }
    // Two inline filter passes, no materialized Vec: pass 1 folds Σ + count (⇒ mean), pass 2
    // folds Σ(x−mean)². BYTE-IDENTICAL: each pass reduces the SAME non-NaN elements in data
    // order as `valid`, from 0.0 — count == valid.len(), mean and the SS reduction are the
    // same left folds. Re-running the cheap `is_nan` predicate is cheaper than the Vec write
    // + two Vec reads it replaces.
    let mut sum = 0.0f64;
    let mut count = 0usize;
    for &x in data {
        if !x.is_nan() {
            sum += x;
            count += 1;
        }
    }
    if count < 2 {
        return f64::NAN;
    }
    let n = count as f64;
    let mean = sum / n;
    let mut ss = 0.0f64;
    for &x in data {
        if !x.is_nan() {
            ss += (x - mean).powi(2);
        }
    }
    ss / n
}

/// Compute standard deviation ignoring NaN values.
///
/// Matches `numpy.nanstd`.
pub fn nanstd(data: &[f64]) -> f64 {
    nanvar(data).sqrt()
}

/// Compute z-scores ignoring NaN values.
///
/// Computes (x - nanmean) / nanstd, preserving NaN positions.
///
/// Like `scipy.stats.zscore` with nan_policy='omit'.
pub fn nanzscore(data: &[f64]) -> Vec<f64> {
    // mean + population variance over the non-NaN elements. Same alloc-free lever as tvar/nanvar:
    // above 1<<22 (data spills LLC) compute both in two inline filter passes over `data` instead of
    // materializing the NaN-filtered `valid` Vec (its alloc + write + two reads → two reads of `data`);
    // below the gate (and under NANVAR_FORCE_COLLECT) keep the collect path. BYTE-IDENTICAL: Σ, count
    // and Σ(x-mean)² are the same left-to-right folds over the non-NaN elements in data order as over
    // `valid`, so `mean`/`var` (and the output map) are unchanged.
    let (mean, var) = if NANVAR_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed)
        || data.len() < (1 << 22)
    {
        let valid: Vec<f64> = data.iter().copied().filter(|x| !x.is_nan()).collect();
        if valid.len() < 2 {
            return vec![f64::NAN; data.len()];
        }
        let n = valid.len() as f64;
        let mean = valid.iter().sum::<f64>() / n;
        let var = valid.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / n;
        (mean, var)
    } else {
        let mut sum = 0.0f64;
        let mut count = 0usize;
        for &x in data {
            if !x.is_nan() {
                sum += x;
                count += 1;
            }
        }
        if count < 2 {
            return vec![f64::NAN; data.len()];
        }
        let n = count as f64;
        let mean = sum / n;
        let mut ss = 0.0f64;
        for &x in data {
            if !x.is_nan() {
                ss += (x - mean).powi(2);
            }
        }
        (mean, ss / n)
    };
    let std = var.sqrt();

    if std == 0.0 {
        return vec![f64::NAN; data.len()];
    }

    // The NaN-aware `(x-mean)/std` output map over the full `data` is the dominant pass and is a
    // per-element pure function of its index, so fan it across cores via the order-preserving
    // `par_continuous_map_min` — BYTE-IDENTICAL to `iter().map(..).collect()` (NaNs still pass through,
    // same index order). Shares [`ZSCORE_FORCE_SERIAL`]; 800k gate keeps small arrays serial.
    if ZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter()
            .map(|&x| {
                if x.is_nan() {
                    f64::NAN
                } else {
                    (x - mean) / std
                }
            })
            .collect()
    } else {
        par_continuous_map_min(data, 800_000, move |x| {
            if x.is_nan() {
                f64::NAN
            } else {
                (x - mean) / std
            }
        })
    }
}

/// When `true`, [`nansum`]/[`nanprod`] reduce serially (the ORIG exact `filter(!is_nan).sum()`/
/// `.product()`); default `false` fans the filtered reduction across cores for large inputs. WITHIN
/// per-op ULP tolerance (parallel reassociation). `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static NANSUM_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute NaN-aware sum.
///
/// Returns the sum of values, ignoring NaN values.
/// Matches `numpy.nansum`.
pub fn nansum(data: &[f64]) -> f64 {
    // Bandwidth-light kernel (is_nan check + add). Below the gate (and when forced serial) keep the
    // EXACT `filter(!is_nan).sum()` — byte-identical for small inputs and any bit-exact test; above
    // 1<<20 fan the filtered sum across cores (each chunk sums its non-NaN, combine), within per-op
    // ULP tolerance (parallel reorder).
    let n = data.len();
    if NANSUM_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 20) {
        return data.iter().filter(|x| !x.is_nan()).sum();
    }
    let chunk_sum = |ds: &[f64]| -> f64 { ds.iter().filter(|x| !x.is_nan()).sum() };
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sum = &chunk_sum;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|ds| scope.spawn(move || chunk_sum(ds)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("nansum worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, s| acc + s)
}

/// Compute NaN-aware product.
///
/// Returns the product of values, ignoring NaN values.
/// Matches `numpy.nanprod`.
pub fn nanprod(data: &[f64]) -> f64 {
    // Bandwidth-light kernel (is_nan check + multiply). Below the gate (and when forced serial) keep
    // the EXACT `filter(!is_nan).product()` — byte-identical for small inputs and any bit-exact test;
    // above 1<<20 fan the filtered product across cores (each chunk multiplies its non-NaN, combine),
    // within per-op ULP tolerance (float multiply reassociation). A 0 anywhere still gives 0 (0 is
    // absorbing) and an all-NaN chunk contributes the identity 1.0 — the structure is preserved.
    let n = data.len();
    if NANSUM_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 20) {
        return data.iter().filter(|x| !x.is_nan()).product();
    }
    let chunk_prod = |ds: &[f64]| -> f64 { ds.iter().filter(|x| !x.is_nan()).product() };
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_prod = &chunk_prod;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|ds| scope.spawn(move || chunk_prod(ds)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("nanprod worker panicked"))
            .collect()
    });
    parts.into_iter().fold(1.0f64, |acc, p| acc * p)
}

/// When `true`, [`nanmin`]/[`nanmax`] run their NaN-filtered fold serially (the ORIG
/// behaviour); default `false` fans it across cores above the work gate. Byte-identical.
#[doc(hidden)]
pub static NANMINMAX_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Parallel `data.iter().filter(!nan).copied().fold(ident, reduce)`. BYTE-IDENTICAL to the
/// serial fold: `f64::min`/`f64::max` are associative and give a total order over signed
/// zeros, so the chunk-then-merge result equals the left fold, and NaN is filtered per chunk
/// identically. Work-gated (the syscall + spawn cost more than the fold below the gate).
fn par_nan_fold(data: &[f64], ident: f64, reduce: fn(f64, f64) -> f64) -> f64 {
    let n = data.len();
    let serial = |d: &[f64]| {
        d.iter()
            .filter(|x| !x.is_nan())
            .copied()
            .fold(ident, reduce)
    };
    let nthreads =
        if NANMINMAX_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < 131_072 {
            1
        } else {
            std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n / 65_536)
                .max(1)
        };
    if nthreads <= 1 {
        return serial(data);
    }
    let chunk = n.div_ceil(nthreads);
    let serial = &serial;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|c| scope.spawn(move || serial(c)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().unwrap())
            .collect()
    });
    parts.into_iter().fold(ident, reduce)
}

/// Compute NaN-aware min.
///
/// Returns the minimum value, ignoring NaN values.
/// Matches `numpy.nanmin`.
pub fn nanmin(data: &[f64]) -> f64 {
    par_nan_fold(data, f64::INFINITY, f64::min)
}

/// Compute NaN-aware max.
///
/// Returns the maximum value, ignoring NaN values.
/// Matches `numpy.nanmax`.
pub fn nanmax(data: &[f64]) -> f64 {
    par_nan_fold(data, f64::NEG_INFINITY, f64::max)
}

/// When `true`, [`nanmedian`] fully sorts the filtered values (the ORIG behaviour); default
/// `false` quickselects the central rank(s) in O(n). Byte-identical. A/B gate.
#[doc(hidden)]
pub static NANMEDIAN_FORCE_SORT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute median ignoring NaN values.
///
/// Matches `numpy.nanmedian`.
pub fn nanmedian(data: &[f64]) -> f64 {
    let mut valid: Vec<f64> = data.iter().copied().filter(|x| !x.is_nan()).collect();
    if valid.is_empty() {
        return f64::NAN;
    }
    if NANMEDIAN_FORCE_SORT.load(std::sync::atomic::Ordering::Relaxed) {
        valid.sort_unstable_by(|a, b| a.total_cmp(b));
        let n = valid.len();
        return if n.is_multiple_of(2) {
            (valid[n / 2 - 1] + valid[n / 2]) / 2.0
        } else {
            valid[n / 2]
        };
    }
    // The median only needs the one or two central order statistics, so quickselect them in
    // O(n) via `median_in_place` instead of a full O(n log n) `sort_unstable`. BYTE-IDENTICAL:
    // `median_in_place` selects the same central ranks (even ⇒ mean of ranks n/2-1 and n/2;
    // odd ⇒ rank n/2) that indexing a full total_cmp sort would read.
    median_in_place(&mut valid)
}

/// When `true`, [`nanquantile`] fully sorts the filtered values (the ORIG behaviour); default
/// `false` quickselects each quantile's rank(s) when few relative to log2(n). Byte-identical.
#[doc(hidden)]
pub static NANQUANTILE_FORCE_SORT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute quantiles ignoring NaN values.
///
/// Matches `numpy.nanquantile`.
pub fn nanquantile(data: &[f64], q: &[f64]) -> Vec<f64> {
    let mut valid: Vec<f64> = data.iter().copied().filter(|x| !x.is_nan()).collect();
    if valid.is_empty() {
        return vec![f64::NAN; q.len()];
    }
    let n = valid.len();
    // Each quantile reads only 1-2 order statistics, so when there are few of them relative
    // to log2(n) it is cheaper to `select_ranks` (partition, O(n)) per quantile on the shared
    // buffer than to fully sort once (O(n log n)). Both paths are BYTE-IDENTICAL — the k-th
    // order statistic (and the linear interpolation) is the same whether read from a fully
    // sorted array or partitioned out. `NANQUANTILE_FORCE_SORT` pins the full-sort path.
    let use_sort = NANQUANTILE_FORCE_SORT.load(std::sync::atomic::Ordering::Relaxed)
        || (q.len() as f64) >= (n as f64).log2().max(1.0);
    if use_sort {
        valid.sort_unstable_by(|a, b| a.total_cmp(b));
    }
    let mut out = Vec::with_capacity(q.len());
    for &qi in q {
        let qi = qi.clamp(0.0, 1.0);
        let idx = qi * (n - 1) as f64;
        let lo = idx.floor() as usize;
        let hi = idx.ceil() as usize;
        let frac = idx - lo as f64;
        let v = if lo == hi || hi >= n {
            let r = lo.min(n - 1);
            if use_sort {
                valid[r]
            } else {
                select_ranks(&mut valid, r, r).0
            }
        } else if use_sort {
            valid[lo] * (1.0 - frac) + valid[hi] * frac
        } else {
            let (v_lo, v_hi) = select_ranks(&mut valid, lo, hi);
            v_lo * (1.0 - frac) + v_hi * frac
        };
        out.push(v);
    }
    out
}

/// Compute percentile ignoring NaN values.
///
/// Matches `numpy.nanpercentile`.
pub fn nanpercentile(data: &[f64], q: f64) -> f64 {
    if q.is_nan() {
        return f64::NAN;
    }
    let result = nanquantile(data, &[q / 100.0]);
    result.first().copied().unwrap_or(f64::NAN)
}

/// When `true`, [`gmean_weighted`] sums `Σ w·ln(x)` serially (the ORIG exact `map.sum()` fold); default
/// `false` fans the `ln`-bound sum across cores for large inputs (4-way-unrolled chunks). WITHIN per-op
/// ULP tolerance (parallel reorder). `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static GMEAN_W_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the weighted geometric mean.
///
/// G_w = exp(Σ(w·ln(x)) / Σw)
///
/// Like scipy.stats.gmean with weights parameter.
pub fn gmean_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() {
        return f64::NAN;
    }
    if data.iter().any(|&x| !x.is_finite() || x <= 0.0) {
        return f64::NAN;
    }
    if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
        return f64::NAN;
    }
    let total_w: f64 = weights.iter().sum();
    if total_w == 0.0 {
        return f64::NAN;
    }
    // `Σ w·ln(x)` — the per-element `ln` is a heavy transcendental (compute-bound), mirroring the
    // unweighted `gmean_log_sum`. Below the gate (and when forced serial) keep the EXACT serial
    // `map.sum()` fold (byte-identical for small inputs and any bit-exact test); above 1<<16 fan a
    // 4-way-unrolled chunk sum across cores (within per-op ULP tolerance, parallel reorder).
    let n = data.len();
    let weighted_log_sum: f64 =
        if GMEAN_W_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 16) {
            data.iter().zip(weights).map(|(&x, &w)| w * x.ln()).sum()
        } else {
            let chunk_sum = |ds: &[f64], ws: &[f64]| -> f64 {
                let mut a = [0.0f64; 4];
                let mut i = 0;
                while i + 4 <= ds.len() {
                    a[0] += ws[i] * ds[i].ln();
                    a[1] += ws[i + 1] * ds[i + 1].ln();
                    a[2] += ws[i + 2] * ds[i + 2].ln();
                    a[3] += ws[i + 3] * ds[i + 3].ln();
                    i += 4;
                }
                let mut s = (a[0] + a[1]) + (a[2] + a[3]);
                while i < ds.len() {
                    s += ws[i] * ds[i].ln();
                    i += 1;
                }
                s
            };
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n / (1 << 15))
                .max(1);
            let chunk = n.div_ceil(nthreads);
            let chunk_sum = &chunk_sum;
            let parts: Vec<f64> = std::thread::scope(|scope| {
                data.chunks(chunk)
                    .zip(weights.chunks(chunk))
                    .map(|(ds, ws)| scope.spawn(move || chunk_sum(ds, ws)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("gmean_weighted worker panicked"))
                    .collect()
            });
            parts.into_iter().fold(0.0f64, |acc, s| acc + s)
        };
    (weighted_log_sum / total_w).exp()
}

/// Compute the geometric standard deviation.
///
/// The geometric standard deviation is defined as exp(std(log(data))).
/// All values must be positive.
///
/// Matches `scipy.stats.gstd(a)`.
/// When `true`, [`gstd`] builds its log vector with the serial `data.iter().map(ln).collect()` (the
/// ORIG behaviour). When `false` (default), the compute-bound `ln` map fans across cores via the
/// order-preserving `par_continuous_map`. Byte-identical either way. For the same-binary A/B perf gate.
#[doc(hidden)]
pub static GSTD_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn gstd(data: &[f64]) -> f64 {
    if data.is_empty() || data.len() < 2 {
        return f64::NAN;
    }
    if data.iter().any(|&x| x <= 0.0 || !x.is_finite()) {
        return f64::NAN;
    }
    let n = data.len() as f64;
    // `ln` is a heavy per-element transcendental; parallelize the map via the order-preserving
    // `par_continuous_map` (BYTE-IDENTICAL to `data.iter().map(ln).collect()`, same values in index
    // order). `GSTD_FORCE_SERIAL` restores the serial map. With the ln map already parallel, the two
    // downstream reductions over `logs` were the serial BOTTLENECK — route them through the shared
    // work-gated `par_sum`/`sum_sq_dev` (byte-identical below the 1<<22 gate; the variance is
    // m2-insensitive to the mean so par_sum is byte-safe above it, and gstd's output uses `mean_log`
    // only through `var_log`).
    let logs: Vec<f64> = if GSTD_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| x.ln()).collect()
    } else {
        par_continuous_map(data, |x| x.ln())
    };
    let mean_log = par_sum(&logs) / n;
    let var_log = sum_sq_dev(&logs, mean_log) / (n - 1.0);
    var_log.sqrt().exp()
}

/// When `true`, [`hmean`] runs its validity check, zero check and Σ(1/x) as three separate
/// passes (the ORIG behaviour); default `false` fuses them into one traversal. Byte-identical.
#[doc(hidden)]
pub static HMEAN_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `Σ(1/xᵢ)` for the harmonic mean, fused with the validity (`NaN`/negative) and zero checks and —
/// for large inputs — split across threads. Each worker folds its chunk's `1/x` in the same
/// left-to-right order and OR-combines the two flags; the parts are summed in chunk order. Mirrors
/// [`gmean_log_sum`]'s work-gated `thread::scope` split (`1/x` is a light-ish division, so cap
/// workers at >=64k elements each). Returns `(invalid, has_zero, inv_sum)`. ~1e-15 reassociation
/// vs the serial fold above the gate; BYTE-IDENTICAL at/below it (the single-chunk fold IS the
/// original fused loop).
fn hmean_inv_sum(data: &[f64]) -> (bool, bool, f64) {
    let chunk_fold = |chunk: &[f64]| -> (bool, bool, f64) {
        let mut invalid = false;
        let mut has_zero = false;
        let mut inv_sum = 0.0f64;
        for &x in chunk {
            if x.is_nan() || x < 0.0 {
                invalid = true;
            } else if x == 0.0 {
                has_zero = true;
            } else {
                inv_sum += 1.0 / x;
            }
        }
        (invalid, has_zero, inv_sum)
    };
    let n = data.len();
    // Short-circuit small inputs BEFORE the `available_parallelism()` syscall — `hmean` is called
    // once per line by the axis reducer over many short lines, where that per-call `sched_getaffinity`
    // would dominate the (cheap) division work. The serial fold is what we'd take here anyway.
    if n < (1 << 16) {
        return chunk_fold(data);
    }
    let cores = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let threads = cores.min((n / (1 << 16)).max(1)).min(16);
    if threads <= 1 {
        return chunk_fold(data);
    }
    let chunk = n.div_ceil(threads);
    let parts: Vec<(bool, bool, f64)> = std::thread::scope(|scope| {
        let handles: Vec<_> = data
            .chunks(chunk)
            .map(|c| scope.spawn(move || chunk_fold(c)))
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    let mut invalid = false;
    let mut has_zero = false;
    let mut inv_sum = 0.0f64;
    for (inv, hz, s) in parts {
        invalid |= inv;
        has_zero |= hz;
        inv_sum += s;
    }
    (invalid, has_zero, inv_sum)
}

/// Compute the harmonic mean.
///
/// Matches `scipy.stats.hmean`.
pub fn hmean(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let n = data.len() as f64;
    if HMEAN_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if data.iter().any(|&x| x.is_nan() || x < 0.0) {
            return f64::NAN;
        }
        if data.contains(&0.0) {
            return 0.0;
        }
        let inv_sum: f64 = data.iter().map(|&x| 1.0 / x).sum();
        return if inv_sum == 0.0 {
            f64::INFINITY
        } else {
            n / inv_sum
        };
    }
    // The validity check (`any(nan || x<0)`), the zero check (`contains(0)`) and Σ(1/x) are
    // three independent traversals; fuse them into ONE (and, for huge inputs, split across
    // threads — see `hmean_inv_sum`). BYTE-IDENTICAL below the parallel gate: for valid input (no
    // NaN/negative/zero) every element takes the `else` arm, so `inv_sum` is the same left-to-
    // right fold of `1/x` from 0.0 as `iter().map(1/x).sum()`; a NaN/negative returns NaN and a
    // zero returns 0.0 with the same precedence as the two separate early-return checks.
    let (invalid, has_zero, inv_sum) = hmean_inv_sum(data);
    if invalid {
        return f64::NAN;
    }
    if has_zero {
        return 0.0;
    }
    if inv_sum == 0.0 {
        return f64::INFINITY;
    }
    n / inv_sum
}

/// When `true`, [`hmean_weighted`] runs its five separate traversals (data-validity, weights-validity,
/// `Σw`, the `x==0 && w>0` zero-check, and `Σ(w/x)`); default `false` folds all five into ONE pass.
///
/// BYTE-IDENTICAL only while that fused pass stays serial. The default arm routes through
/// [`hmean_weighted_reduce`], which above `1 << 16` splits into per-thread chunk folds and adds the
/// partial `Σw` and `Σ(w/x)` in chunk order — a reassociation — so above that gate this is WITHIN
/// PER-OP ULP TOLERANCE. The five FLAGS stay exact at every size: they OR-combine, which is
/// associative, and they fire in the original precedence. This doc claimed byte-identity with no
/// qualification while [`hmean_weighted_reduce`]'s own doc has recorded "~1e-15 reassociation vs the
/// serial fold above the gate" and [`hmean_weighted`]'s inline comment has said "BYTE-IDENTICAL below
/// the parallel gate" throughout; the parallel split landed on a function that already had a
/// documented byte-identical toggle and the toggle's doc never caught up. Corrected under
/// frankenscipy-5f06d after an exact A/B gate caught it at n = 200_000: 0.9102444235517904 split vs
/// 0.9102444235518026 fused. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static HMEAN_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// The weighted harmonic mean's fused five-in-one traversal (`Σw`, `Σ(w/x)`, and the three flags),
/// split across threads for large inputs. Each worker folds its aligned (data,weights) chunk in
/// index order and OR-combines the flags; the two sums are added in chunk order. Mirrors
/// [`hmean_inv_sum`]/[`gmean_log_sum`]'s work-gated `thread::scope` split (`w/x` is a light-ish
/// division, so cap workers at >=64k elements each). Returns
/// `(data_invalid, weights_invalid, has_zero, total_w, weighted_inv_sum)`. ~1e-15 reassociation vs
/// the serial fold above the gate; BYTE-IDENTICAL at/below it (the single-chunk fold IS the
/// original fused loop).
fn hmean_weighted_reduce(data: &[f64], weights: &[f64]) -> (bool, bool, bool, f64, f64) {
    let chunk_fold = |xs: &[f64], ws: &[f64]| -> (bool, bool, bool, f64, f64) {
        let mut data_invalid = false;
        let mut weights_invalid = false;
        let mut has_zero = false;
        let mut total_w = 0.0f64;
        let mut weighted_inv_sum = 0.0f64;
        for (&x, &w) in xs.iter().zip(ws) {
            data_invalid |= x.is_nan() || x < 0.0;
            weights_invalid |= !w.is_finite() || w < 0.0;
            total_w += w;
            has_zero |= x == 0.0 && w > 0.0;
            weighted_inv_sum += w / x;
        }
        (
            data_invalid,
            weights_invalid,
            has_zero,
            total_w,
            weighted_inv_sum,
        )
    };
    let n = data.len();
    // Short-circuit small inputs BEFORE the `available_parallelism()` syscall — the per-line axis
    // reducer calls this over many short lines, where that `sched_getaffinity` would dominate the
    // (cheap) division work. The serial fold is what we'd take here anyway.
    if n < (1 << 16) {
        return chunk_fold(data, weights);
    }
    let cores = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let threads = cores.min((n / (1 << 16)).max(1)).min(16);
    if threads <= 1 {
        return chunk_fold(data, weights);
    }
    let chunk = n.div_ceil(threads);
    // `data` and `weights` have equal length, so `chunks(chunk)` splits them at aligned boundaries.
    let parts: Vec<(bool, bool, bool, f64, f64)> = std::thread::scope(|scope| {
        let handles: Vec<_> = data
            .chunks(chunk)
            .zip(weights.chunks(chunk))
            .map(|(xs, ws)| scope.spawn(move || chunk_fold(xs, ws)))
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    let mut data_invalid = false;
    let mut weights_invalid = false;
    let mut has_zero = false;
    let mut total_w = 0.0f64;
    let mut weighted_inv_sum = 0.0f64;
    for (di, wi, hz, tw, wis) in parts {
        data_invalid |= di;
        weights_invalid |= wi;
        has_zero |= hz;
        total_w += tw;
        weighted_inv_sum += wis;
    }
    (
        data_invalid,
        weights_invalid,
        has_zero,
        total_w,
        weighted_inv_sum,
    )
}

/// Compute the weighted harmonic mean.
///
/// H_w = (Σw) / Σ(w/x)
///
/// Like scipy.stats.hmean with weights parameter.
pub fn hmean_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() {
        return f64::NAN;
    }
    if HMEAN_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if data.iter().any(|&x| x.is_nan() || x < 0.0) {
            return f64::NAN;
        }
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        let total_w: f64 = weights.iter().sum();
        if total_w == 0.0 {
            return f64::NAN;
        }
        for (&x, &w) in data.iter().zip(weights) {
            if x == 0.0 && w > 0.0 {
                return 0.0;
            }
        }
        let weighted_inv_sum: f64 = data.iter().zip(weights).map(|(&x, &w)| w / x).sum();
        return if weighted_inv_sum == 0.0 {
            f64::INFINITY
        } else {
            total_w / weighted_inv_sum
        };
    }
    // Fuse the five independent traversals into ONE pass (and, for huge inputs, split it across
    // threads — see `hmean_weighted_reduce`). BYTE-IDENTICAL below the parallel gate: `total_w` and
    // `weighted_inv_sum` are the same left-to-right folds from 0.0 over (data,weights) in order, and
    // the flags trigger the same early-returns in the same precedence (data-invalid > weights-invalid
    // > Σw==0 > x==0&&w>0). A `w/x` from an invalid/zero element poisons `weighted_inv_sum`, but it is
    // only used once no flag has fired (all x>0), exactly as the original's ordering guaranteed.
    let (data_invalid, weights_invalid, has_zero, total_w, weighted_inv_sum) =
        hmean_weighted_reduce(data, weights);
    if data_invalid || weights_invalid || total_w == 0.0 {
        return f64::NAN;
    }
    if has_zero {
        return 0.0;
    }
    if weighted_inv_sum == 0.0 {
        return f64::INFINITY;
    }
    total_w / weighted_inv_sum
}

/// Compute the power mean (generalized mean).
///
/// Matches `scipy.stats.pmean`.
pub fn pmean(data: &[f64], p: f64) -> f64 {
    if data.is_empty() || !p.is_finite() {
        return f64::NAN;
    }
    if data.iter().any(|&x| !x.is_finite()) {
        return f64::NAN;
    }
    if data.iter().any(|&x| x < 0.0) {
        return f64::NAN;
    }
    if p == 0.0 {
        return gmean(data);
    }
    if p < 0.0 && data.contains(&0.0) {
        return 0.0;
    }
    let n = data.len() as f64;
    // `powf` is a heavy per-element transcendental (~50-100 cycles) so the map dominates this
    // reduction. Parallelize ONLY the map (via the order-preserving `par_continuous_map`), then sum
    // the results in the SAME index order. BYTE-IDENTICAL to the serial `map(powf).sum()`: the powf
    // values are independent per element and the left-fold from 0.0 is over the same sequence — only
    // the map's owning core changes, not the arithmetic. `PMEAN_FORCE_SERIAL` restores the fused
    // serial map-sum (same-binary A/B).
    let power_sum: f64 = if PMEAN_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| x.powf(p)).sum()
    } else {
        par_continuous_map(data, |x| x.powf(p)).iter().sum()
    };
    (power_sum / n).powf(1.0 / p)
}

/// When `true`, [`pmean`] computes its `powf` power-sum with the fused serial `map(powf).sum()` (the
/// ORIG behaviour). When `false` (default), the compute-bound `powf` map fans across cores via the
/// order-preserving `par_continuous_map` and the sum stays in index order. Byte-identical either way.
/// For the same-binary A/B perf gate.
#[doc(hidden)]
pub static PMEAN_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the weighted power mean (generalized mean with weights).
///
/// Matches `scipy.stats.pmean` with weights parameter.
pub fn pmean_weighted(data: &[f64], p: f64, weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() || !p.is_finite() {
        return f64::NAN;
    }
    if data.iter().any(|&x| !x.is_finite()) || weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
        return f64::NAN;
    }
    if data.iter().any(|&x| x < 0.0) {
        return f64::NAN;
    }
    let total_w: f64 = weights.iter().sum();
    if total_w <= 0.0 {
        return f64::NAN;
    }
    if p == 0.0 {
        return gmean_weighted(data, weights);
    }
    if p < 0.0 && data.contains(&0.0) {
        return 0.0;
    }
    // `powf` dominates this weighted reduction — parallelize ONLY the `powf` map (order-preserving
    // `par_continuous_map`), then the light weighted sum `w·x^p` stays in index order. BYTE-IDENTICAL
    // to the fused `map(w·x^p).sum()`: `w[i]·powed[i]` = `w[i]·x[i].powf(p)`, left-fold from 0.0 over
    // the same sequence. `PMEAN_WEIGHTED_FORCE_SERIAL` restores the fused serial map-sum.
    let weighted_power_sum: f64 =
        if PMEAN_WEIGHTED_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
            data.iter().zip(weights).map(|(&x, &w)| w * x.powf(p)).sum()
        } else {
            par_continuous_map(data, |x| x.powf(p))
                .iter()
                .zip(weights)
                .map(|(&pw, &w)| w * pw)
                .sum()
        };
    (weighted_power_sum / total_w).powf(1.0 / p)
}

/// When `true`, [`pmean_weighted`] computes its weighted `powf` sum with the fused serial
/// `map(w·x^p).sum()` (the ORIG behaviour). When `false` (default), the compute-bound `powf` map fans
/// across cores via the order-preserving `par_continuous_map` and the light weighted sum stays in
/// index order. Byte-identical either way. For the same-binary A/B perf gate.
#[doc(hidden)]
pub static PMEAN_WEIGHTED_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Circular mean for angular data.
///
/// Matches `scipy.stats.circmean`.
/// Σsin(x) and Σcos(x) over `data`, the shared reduction of the circular statistics
/// (`circmean`/`circvar`/`circstd`). `sin`/`cos` are heavy per-element transcendentals (~20-40 cycles
/// each) so each map dominates its light left-fold: parallelize ONLY the maps (order-preserving
/// `par_continuous_map`), sums stay in index order. BYTE-IDENTICAL to the serial `map(sin).sum()` /
/// `map(cos).sum()` (independent values, same left-fold from 0.0). `CIRC_FORCE_SERIAL` restores the
/// fused serial maps (same-binary A/B).
fn circular_sincos_sums(data: &[f64]) -> (f64, f64) {
    if CIRC_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        let sin_sum: f64 = data.iter().map(|&x| x.sin()).sum();
        let cos_sum: f64 = data.iter().map(|&x| x.cos()).sum();
        return (sin_sum, cos_sum);
    }
    // Each element needs BOTH `x.sin()` and `x.cos()`. Compute Σsin and Σcos in ONE pass over `data`
    // instead of the previous two separate `par_continuous_map` passes (two data reads, two n-length
    // Vecs, two spawns). Serial below the gate (byte-identical to the two separate serial folds — each
    // sum accumulates only its own terms in index order); fanned across cores above it (no Vec).
    // WITHIN per-op ULP tolerance above the gate (parallel reorder).
    let n = data.len();
    let chunk_sums = |ds: &[f64]| -> (f64, f64) {
        let mut ss = 0.0f64;
        let mut cs = 0.0f64;
        for &x in ds {
            ss += x.sin();
            cs += x.cos();
        }
        (ss, cs)
    };
    if n < (1 << 15) {
        return chunk_sums(data);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 14))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sums = &chunk_sums;
    let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|ds| scope.spawn(move || chunk_sums(ds)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("circ sincos worker panicked"))
            .collect()
    });
    parts
        .into_iter()
        .fold((0.0f64, 0.0f64), |(as_, ac), (cs, cc)| (as_ + cs, ac + cc))
}

/// When `true`, the circular `Σsin`/`Σcos` reductions ([`circmean`]/[`circvar`]/[`circstd`] and the
/// shared rayleigh/von-Mises paths) use the exact serial `map(...).sum()` folds. When `false`
/// (default), [`circmean`]/[`circvar`]/[`circstd`] compute both sums in ONE pass — serial below the
/// gate (byte-identical) and fanned across cores above it (within per-op ULP tolerance); the
/// rayleigh/von-Mises paths keep the order-preserving `par_continuous_map` (byte-identical). A/B gate.
#[doc(hidden)]
pub static CIRC_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn circmean(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let (sin_sum, cos_sum) = circular_sincos_sums(data);
    // scipy.stats.circmean wraps into the default range [0, 2π); atan2 alone
    // returns [-π, π], which is 2π too low for a negative mean angle.
    // frankenscipy-87q5w
    sin_sum.atan2(cos_sum).rem_euclid(2.0 * PI)
}

/// Circular variance for angular data.
///
/// Matches `scipy.stats.circvar`.
pub fn circvar(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let n = data.len() as f64;
    let (sin_sum, cos_sum) = circular_sincos_sums(data);
    let r = (sin_sum * sin_sum + cos_sum * cos_sum).sqrt() / n;
    1.0 - r
}

/// Circular standard deviation for angular data.
///
/// Matches `scipy.stats.circstd`.
pub fn circstd(data: &[f64]) -> f64 {
    let v = circvar(data);
    if v <= 0.0 {
        return 0.0;
    }
    (-2.0 * (1.0 - v).ln()).sqrt()
}

/// Weighted circular mean for angular data.
///
/// Matches `scipy.stats.circmean` with weights parameter.
/// Weighted `Σw·sin(x)` and `Σw·cos(x)` over `data`, the shared reduction of the weighted circular
/// statistics (`circmean_weighted`/`circvar_weighted`/`circstd_weighted`). `sin`/`cos` are heavy
/// per-element transcendentals so each map dominates the light `w·f(x)` left-fold: parallelize ONLY
/// the maps (order-preserving `par_continuous_map`), then the weighted sums stay in index order.
/// BYTE-IDENTICAL to the serial `map(w·sin(x)).sum()` / `map(w·cos(x)).sum()` (`w[i]·s[i]` =
/// `w[i]·x[i].sin()`, same left-fold from 0.0). `CIRC_WEIGHTED_FORCE_SERIAL` restores the fused serial
/// maps (same-binary A/B).
fn circular_weighted_sincos_sums(data: &[f64], weights: &[f64]) -> (f64, f64) {
    // Each element needs BOTH `x.sin()` and `x.cos()` (two heavy transcendentals). Compute the two
    // weighted sums Σw·sin and Σw·cos in ONE pass. The serial/small path folds both together (its
    // sin/cos sums are byte-identical to the two separate serial folds — each accumulates only its own
    // terms in index order); above the gate, fan the (Σw·sin, Σw·cos) pair across cores. This replaces
    // the previous TWO separate `par_continuous_map` calls (two data passes, two 8·n-byte Vecs, two
    // thread spawns) with one alloc-free pass. WITHIN per-op ULP tolerance above the gate (parallel
    // reorder); `CIRC_WEIGHTED_FORCE_SERIAL` keeps the exact two-pass serial fold.
    let n = data.len();
    let chunk_sums = |ds: &[f64], ws: &[f64]| -> (f64, f64) {
        let mut ss = 0.0f64;
        let mut cs = 0.0f64;
        for (&x, &w) in ds.iter().zip(ws) {
            ss += w * x.sin();
            cs += w * x.cos();
        }
        (ss, cs)
    };
    if CIRC_WEIGHTED_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        let sin_sum: f64 = data.iter().zip(weights).map(|(&x, &w)| w * x.sin()).sum();
        let cos_sum: f64 = data.iter().zip(weights).map(|(&x, &w)| w * x.cos()).sum();
        return (sin_sum, cos_sum);
    }
    if n < (1 << 15) {
        return chunk_sums(data, weights);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 14))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sums = &chunk_sums;
    let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .zip(weights.chunks(chunk))
            .map(|(ds, ws)| scope.spawn(move || chunk_sums(ds, ws)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("circ weighted worker panicked"))
            .collect()
    });
    parts
        .into_iter()
        .fold((0.0f64, 0.0f64), |(as_, ac), (cs, cc)| (as_ + cs, ac + cc))
}

/// When `true`, [`circmean_weighted`]/[`circvar_weighted`]/[`circstd_weighted`] compute their weighted
/// `Σsin`/`Σcos` with the exact two-pass serial `map(...).sum()`. When `false` (default), both weighted
/// sums are computed in ONE pass over (data, weights) — serial below the gate (byte-identical to the
/// two-pass fold) and fanned across cores above it (within per-op ULP tolerance). For the A/B gate.
#[doc(hidden)]
pub static CIRC_WEIGHTED_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn circmean_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() {
        return f64::NAN;
    }
    if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
        return f64::NAN;
    }
    let (sin_sum, cos_sum) = circular_weighted_sincos_sums(data, weights);
    // Wrap into scipy's default [0, 2π) range (see circmean). frankenscipy-87q5w
    sin_sum.atan2(cos_sum).rem_euclid(2.0 * PI)
}

/// Weighted circular variance for angular data.
///
/// Matches `scipy.stats.circvar` with weights parameter.
pub fn circvar_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.is_empty() || data.len() != weights.len() {
        return f64::NAN;
    }
    if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
        return f64::NAN;
    }
    let total_w: f64 = weights.iter().sum();
    if total_w <= 0.0 {
        return f64::NAN;
    }
    let (sin_sum, cos_sum) = circular_weighted_sincos_sums(data, weights);
    let r = (sin_sum * sin_sum + cos_sum * cos_sum).sqrt() / total_w;
    1.0 - r
}

/// Weighted circular standard deviation for angular data.
///
/// Matches `scipy.stats.circstd` with weights parameter.
pub fn circstd_weighted(data: &[f64], weights: &[f64]) -> f64 {
    let v = circvar_weighted(data, weights);
    if v.is_nan() || v <= 0.0 {
        return if v.is_nan() { f64::NAN } else { 0.0 };
    }
    (-2.0 * (1.0 - v).ln()).sqrt()
}

/// Rayleigh test for circular uniformity.
///
/// Matches `scipy.stats.rayleightest(samples)`.
/// Tests whether the circular data comes from a uniform distribution.
///
/// # Arguments
/// * `samples` - Circular data in radians
///
/// # Returns
/// A tuple (statistic, pvalue) where statistic is Rayleigh's R² value
/// and pvalue is the probability under the null hypothesis of uniformity.
pub fn rayleightest(samples: &[f64]) -> (f64, f64) {
    let n = samples.len();
    if n < 2 {
        return (f64::NAN, f64::NAN);
    }
    let nf = n as f64;

    // `sin`/`cos` are heavy per-element transcendentals; reuse the shared circular reduction that
    // parallelizes both maps (order-preserving `par_continuous_map`, index-ordered sums) — BYTE-IDENTICAL
    // to the serial `map(cos).sum()`/`map(sin).sum()`. Gated by `CIRC_FORCE_SERIAL` (shared with circmean).
    let (sum_sin, sum_cos) = circular_sincos_sums(samples);

    let r_bar = ((sum_cos * sum_cos + sum_sin * sum_sin) / (nf * nf)).sqrt();
    let z = nf * r_bar * r_bar;

    let pvalue = (-z).exp()
        * (1.0 + (2.0 * z - z * z) / (4.0 * nf)
            - (24.0 * z - 132.0 * z * z + 76.0 * z * z * z - 9.0 * z * z * z * z)
                / (288.0 * nf * nf));

    (z, pvalue.clamp(0.0, 1.0))
}

/// Result for directional statistics.
#[derive(Debug, Clone, PartialEq)]
pub struct DirectionalStatsResult {
    /// Mean direction as unit vector.
    pub mean_direction: Vec<f64>,
    /// Mean resultant length (0 to 1, higher = less dispersed).
    pub mean_resultant_length: f64,
}

/// Compute directional statistics for 2D vector data.
///
/// Computes mean direction and mean resultant length for a set of
/// 2D vectors (e.g., unit vectors on a circle).
///
/// Similar to `scipy.stats.directional_stats` for 2D case.
///
/// # Arguments
/// * `data` - Slice of 2D vectors as [x, y] pairs
/// * `normalize` - If true, normalize input vectors to unit length
///
/// # Returns
/// `DirectionalStatsResult` with mean_direction and mean_resultant_length.
pub fn directional_stats(data: &[[f64; 2]], normalize: bool) -> DirectionalStatsResult {
    let n = data.len();
    if n == 0 {
        return DirectionalStatsResult {
            mean_direction: vec![f64::NAN, f64::NAN],
            mean_resultant_length: f64::NAN,
        };
    }

    let nf = n as f64;
    let mut sum_x = 0.0;
    let mut sum_y = 0.0;

    for &[x, y] in data {
        if normalize {
            let norm = (x * x + y * y).sqrt();
            if norm > 0.0 {
                sum_x += x / norm;
                sum_y += y / norm;
            }
        } else {
            sum_x += x;
            sum_y += y;
        }
    }

    let mean_x = sum_x / nf;
    let mean_y = sum_y / nf;
    let mean_resultant_length = (mean_x * mean_x + mean_y * mean_y).sqrt();

    let mean_direction = if mean_resultant_length > 0.0 {
        vec![
            mean_x / mean_resultant_length,
            mean_y / mean_resultant_length,
        ]
    } else {
        vec![f64::NAN, f64::NAN]
    };

    DirectionalStatsResult {
        mean_direction,
        mean_resultant_length,
    }
}

/// V-test for circular uniformity against a specified mean direction.
///
/// Tests whether circular data has a specified mean direction vs uniformity.
/// This is a modification of the Rayleigh test that is more powerful when
/// the alternative hypothesis specifies a mean direction.
///
/// # Arguments
/// * `samples` - Circular data in radians
/// * `mu` - The expected mean direction under the alternative hypothesis (radians)
///
/// # Returns
/// A tuple (statistic, pvalue) where statistic is the V-statistic and
/// pvalue is the one-sided p-value for the alternative of concentration around mu.
pub fn vtest(samples: &[f64], mu: f64) -> (f64, f64) {
    let n = samples.len();
    if n < 2 {
        return (f64::NAN, f64::NAN);
    }
    let nf = n as f64;

    // Σcos(x−mu) and Σsin(x−mu): two heavy transcendentals/element (the circular sweet spot), everything
    // else O(1). Compute both sums in ONE pass over `samples` (vs two separate `par_continuous_map`
    // passes = two data reads, two n-Vecs, two spawns): serial below the gate (BYTE-IDENTICAL to the two
    // separate serial folds — each sum accumulates only its own terms in index order) and fanned across
    // cores above 1<<15 (no Vec, within per-op ULP tolerance). Shares `CIRC_FORCE_SERIAL` (exact serial).
    let chunk_sums = |ss: &[f64]| -> (f64, f64) {
        let mut sc = 0.0f64;
        let mut sn = 0.0f64;
        for &x in ss {
            sc += (x - mu).cos();
            sn += (x - mu).sin();
        }
        (sc, sn)
    };
    let (sum_cos, sum_sin) = if CIRC_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        let sum_cos: f64 = samples.iter().map(|&x| (x - mu).cos()).sum();
        let sum_sin: f64 = samples.iter().map(|&x| (x - mu).sin()).sum();
        (sum_cos, sum_sin)
    } else if n < (1 << 15) {
        chunk_sums(samples)
    } else {
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / (1 << 14))
            .max(1);
        let chunk = n.div_ceil(nthreads);
        let chunk_sums = &chunk_sums;
        let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
            samples
                .chunks(chunk)
                .map(|ss| scope.spawn(move || chunk_sums(ss)))
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("vtest worker panicked"))
                .collect()
        });
        parts
            .into_iter()
            .fold((0.0f64, 0.0f64), |(ac, an), (cc, cn)| (ac + cc, an + cn))
    };

    let r_bar = ((sum_cos * sum_cos + sum_sin * sum_sin) / (nf * nf)).sqrt();
    let v = r_bar * (sum_cos / nf).signum() * (nf).sqrt();

    let u = v * (2.0 / nf).sqrt();
    let pvalue = 1.0 - Normal::new(0.0, 1.0).cdf(u);

    (v, pvalue.clamp(0.0, 1.0))
}

/// Kuiper's test for circular uniformity.
///
/// Tests whether circular data comes from a uniform distribution on the circle.
/// This is an alternative to the Rayleigh test that is equally sensitive to
/// departures from uniformity in all directions.
///
/// # Arguments
/// * `samples` - Circular data in radians, will be normalized to [0, 2π)
///
/// # Returns
/// A tuple (statistic, pvalue) where statistic is Kuiper's V statistic
/// and pvalue is approximated from the asymptotic distribution.
pub fn kuipertest(samples: &[f64]) -> (f64, f64) {
    let n = samples.len();
    if n < 2 {
        return (f64::NAN, f64::NAN);
    }
    let nf = n as f64;

    let mut normalized: Vec<f64> = samples
        .iter()
        .map(|&x| {
            let x_mod = x % (2.0 * PI);
            if x_mod < 0.0 { x_mod + 2.0 * PI } else { x_mod }
        })
        .collect();
    normalized.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let mut d_plus = 0.0f64;
    let mut d_minus = 0.0f64;

    for (i, &x) in normalized.iter().enumerate() {
        let cdf = x / (2.0 * PI);
        let ecdf_before = i as f64 / nf;
        let ecdf_after = (i + 1) as f64 / nf;

        d_plus = d_plus.max(ecdf_after - cdf);
        d_minus = d_minus.max(cdf - ecdf_before);
    }

    let v = d_plus + d_minus;
    let v_star = v * (nf.sqrt() + 0.155 + 0.24 / nf.sqrt());

    let pvalue = kuiper_pvalue(v_star);

    (v, pvalue.clamp(0.0, 1.0))
}

fn kuiper_pvalue(v_star: f64) -> f64 {
    if v_star < 0.4 {
        return 1.0;
    }
    let mut sum = 0.0;
    for k in 1..=100 {
        let kf = k as f64;
        let term =
            (4.0 * kf * kf * v_star * v_star - 1.0) * (-2.0 * kf * kf * v_star * v_star).exp();
        sum += 2.0 * term;
    }
    sum.clamp(0.0, 1.0)
}

/// Rao's spacing test for circular uniformity.
///
/// Tests whether circular data comes from a uniform distribution based on
/// the spacing between adjacent observations. Sensitive to clustering.
///
/// # Arguments
/// * `samples` - Circular data in radians
///
/// # Returns
/// A tuple (statistic, pvalue) where statistic is Rao's U statistic
/// and pvalue is approximated using the large-sample distribution.
pub fn rao_spacing_test(samples: &[f64]) -> (f64, f64) {
    let n = samples.len();
    if n < 4 {
        return (f64::NAN, f64::NAN);
    }
    let nf = n as f64;

    let mut normalized: Vec<f64> = samples
        .iter()
        .map(|&x| {
            let x_mod = x % (2.0 * PI);
            if x_mod < 0.0 { x_mod + 2.0 * PI } else { x_mod }
        })
        .collect();
    normalized.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let expected_spacing = 2.0 * PI / nf;
    let mut spacings = Vec::with_capacity(n);

    for i in 0..n {
        let next = (i + 1) % n;
        let spacing = if next == 0 {
            (2.0 * PI - normalized[i]) + normalized[0]
        } else {
            normalized[next] - normalized[i]
        };
        spacings.push(spacing);
    }

    let u: f64 = spacings
        .iter()
        .map(|&s| (s - expected_spacing).abs())
        .sum::<f64>()
        / 2.0;
    let u_degrees = u * 180.0 / PI;

    let mean_u = (nf - 1.0) * (2.0 * PI / nf) * 0.5;
    let var_u = (nf - 1.0) * (4.0 - PI * PI / 3.0) / nf;
    let z = (u - mean_u) / var_u.sqrt();
    let pvalue = 1.0 - Normal::new(0.0, 1.0).cdf(z);

    (u_degrees, pvalue.clamp(0.0, 1.0))
}

// ══════════════════════════════════════════════════════════════════════
// Statistical Tests
// ══════════════════════════════════════════════════════════════════════

/// Result of a statistical test.
#[derive(Debug, Clone, PartialEq)]
pub struct TtestResult {
    /// Test statistic.
    pub statistic: f64,
    /// Two-sided p-value.
    pub pvalue: f64,
    /// Degrees of freedom.
    pub df: f64,
}

/// Result of a variance homogeneity test.
#[derive(Debug, Clone, PartialEq)]
pub struct VarianceTestResult {
    /// Test statistic.
    pub statistic: f64,
    /// Right-tail p-value.
    pub pvalue: f64,
}

fn invalid_variance_test_result() -> VarianceTestResult {
    VarianceTestResult {
        statistic: f64::NAN,
        pvalue: f64::NAN,
    }
}

fn sample_mean(data: &[f64]) -> f64 {
    data.iter().sum::<f64>() / data.len() as f64
}

/// When `true`, [`par_sum`] folds serially (the ORIG `iter().sum()`); default `false` fans the sum
/// across cores for huge inputs. Byte-identical below the gate. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static PAR_SUM_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `Σ data` — a work-gated parallel sum for the mean pass of reductions whose SS/variance pass is
/// already parallel (so the serial mean sum has become the residual). Below the gate (and under
/// `PAR_SUM_FORCE_SERIAL`) it is the exact serial left-fold `data.iter().sum()` (BYTE-IDENTICAL); above
/// 1<<22 it fans across cores as per-thread partial sums, within per-op ULP tolerance.
fn par_sum(data: &[f64]) -> f64 {
    let n = data.len();
    if PAR_SUM_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 22) {
        return data.iter().sum();
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let parts: Vec<f64> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|c| scope.spawn(move || c.iter().sum::<f64>()))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("par_sum worker panicked"))
            .collect()
    });
    parts.into_iter().sum()
}

/// `Σ(xᵢ − mean)²` — the centered second-moment reduction shared by [`sample_variance`], [`sem`] and
/// [`variation`]. Below the gate (and under `MOMENT_PAR_FORCE_SERIAL`) it is the exact serial
/// `map((x−mean)²).sum()` fold (BYTE-IDENTICAL to those callers' original loops); above 1<<22 it fans
/// across cores as per-thread partial sums, within per-op ULP tolerance — mirroring the already-parallel
/// central-moment loops in `skew`/`kurtosis`/`describe`. Reuses their `MOMENT_PAR_FORCE_SERIAL` flag.
fn sum_sq_dev(data: &[f64], mean: f64) -> f64 {
    let chunk_ss = |ds: &[f64]| -> f64 { ds.iter().map(|&x| (x - mean).powi(2)).sum() };
    let n = data.len();
    if MOMENT_PAR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 22) {
        return chunk_ss(data);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_ss = &chunk_ss;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        data.chunks(chunk)
            .map(|ds| scope.spawn(move || chunk_ss(ds)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("sum_sq_dev worker panicked"))
            .collect()
    });
    parts.into_iter().sum()
}

fn sample_variance(data: &[f64]) -> f64 {
    if data.len() < 2 {
        return f64::NAN;
    }
    let mean = sample_mean(data);
    sum_sq_dev(data, mean) / (data.len() as f64 - 1.0)
}

fn sample_median(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    let mid = sorted.len() / 2;
    if sorted.len().is_multiple_of(2) {
        0.5 * (sorted[mid - 1] + sorted[mid])
    } else {
        sorted[mid]
    }
}

/// One-sample t-test: test whether the mean of a sample differs from `popmean`.
///
/// Matches `scipy.stats.ttest_1samp(a, popmean)`.
/// Returns NaN statistic and p-value for samples with fewer than 2 elements.
pub fn ttest_1samp(data: &[f64], popmean: f64) -> TtestResult {
    let n = data.len() as f64;
    if data.is_empty() {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    if data.len() < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: n - 1.0,
        };
    }
    // Mean via `par_sum` + Σ(x−mean)² via `sum_sq_dev` — both work-gated parallel (byte-identical
    // below the 1<<22 gate; the variance is m2-insensitive to the mean, so par_sum is byte-safe there
    // too). Both were serial `.sum()` stragglers vs the parallel sem/variance reductions.
    let mean: f64 = par_sum(data) / n;
    let var: f64 = sum_sq_dev(data, mean) / (n - 1.0);
    let se = (var / n).sqrt();
    if se == 0.0 {
        // All values identical: t is infinite or NaN depending on whether mean == popmean
        let statistic = if (mean - popmean).abs() == 0.0 {
            f64::NAN
        } else {
            (mean - popmean).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df: n - 1.0,
        };
    }
    let t = (mean - popmean) / se;
    let df = n - 1.0;
    let tdist = StudentT::new(df);
    let pvalue = 2.0 * tdist.sf(t.abs());
    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// One-sample t-test with alternative hypothesis specification.
///
/// Matches `scipy.stats.ttest_1samp(a, popmean, alternative=...)`.
///
/// # Arguments
/// * `data` - Sample data
/// * `popmean` - Expected population mean under H0
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn ttest_1samp_alternative(data: &[f64], popmean: f64, alternative: &str) -> TtestResult {
    let n = data.len() as f64;
    if data.is_empty() {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    if data.len() < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: n - 1.0,
        };
    }
    // Mean via `par_sum` + Σ(x−mean)² via `sum_sq_dev` — both work-gated parallel (byte-identical
    // below the 1<<22 gate; the variance is m2-insensitive to the mean, so par_sum is byte-safe there
    // too). Both were serial `.sum()` stragglers vs the parallel sem/variance reductions.
    let mean: f64 = par_sum(data) / n;
    let var: f64 = sum_sq_dev(data, mean) / (n - 1.0);
    let se = (var / n).sqrt();
    if se == 0.0 {
        let statistic = if (mean - popmean).abs() == 0.0 {
            f64::NAN
        } else {
            (mean - popmean).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df: n - 1.0,
        };
    }
    let t = (mean - popmean) / se;
    let df = n - 1.0;
    let tdist = StudentT::new(df);

    let pvalue = match alternative {
        "less" => tdist.cdf(t),
        "greater" => tdist.sf(t),
        _ => 2.0 * tdist.sf(t.abs()),
    };

    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// One-sample t-test from summary statistics.
///
/// Matches `scipy.stats.ttest_1samp_from_stats(mean, std, nobs, popmean)`.
///
/// # Arguments
/// * `mean` - Sample mean
/// * `std` - Sample standard deviation
/// * `nobs` - Number of observations
/// * `popmean` - Expected population mean under H0
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn ttest_1samp_from_stats(
    mean: f64,
    std: f64,
    nobs: usize,
    popmean: f64,
    alternative: Option<&str>,
) -> TtestResult {
    let n = nobs as f64;
    if nobs < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: n - 1.0,
        };
    }
    let se = std / n.sqrt();
    if se == 0.0 || !se.is_finite() {
        let statistic = if (mean - popmean).abs() == 0.0 {
            f64::NAN
        } else {
            (mean - popmean).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df: n - 1.0,
        };
    }
    let t = (mean - popmean) / se;
    let df = n - 1.0;
    let tdist = StudentT::new(df);

    let alt = alternative.unwrap_or("two-sided");
    let pvalue = match alt {
        "less" => tdist.cdf(t),
        "greater" => tdist.sf(t),
        _ => 2.0 * tdist.sf(t.abs()),
    };

    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// Independent two-sample t-test (equal variance assumed).
///
/// Matches `scipy.stats.ttest_ind(a, b, equal_var=True)`.
/// Each sample must have at least 2 elements; returns NaN otherwise.
pub fn ttest_ind(a: &[f64], b: &[f64]) -> TtestResult {
    let n1 = a.len() as f64;
    let n2 = b.len() as f64;
    let df = n1 + n2 - 2.0;
    if a.is_empty() || b.is_empty() {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    if df <= 0.0 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df,
        };
    }
    // Means via `par_sum` — the variances below already use the parallel `sum_sq_dev`, so the mean
    // was the last serial straggler. Byte-identical below the 1<<22 gate (par_sum is the exact serial
    // sum there); above it the means reassociate within per-op ULP like the already-parallel variances.
    let mean1: f64 = par_sum(a) / n1;
    let mean2: f64 = par_sum(b) / n2;
    let var1: f64 = if a.len() > 1 {
        sum_sq_dev(a, mean1) / (n1 - 1.0)
    } else {
        0.0
    };
    let var2: f64 = if b.len() > 1 {
        sum_sq_dev(b, mean2) / (n2 - 1.0)
    } else {
        0.0
    };

    // Pooled variance
    let sp2 = ((n1 - 1.0) * var1 + (n2 - 1.0) * var2) / df;
    let se = (sp2 * (1.0 / n1 + 1.0 / n2)).sqrt();

    if se == 0.0 {
        let statistic = if (mean1 - mean2).abs() == 0.0 {
            f64::NAN
        } else {
            (mean1 - mean2).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df,
        };
    }

    let t = (mean1 - mean2) / se;

    let tdist = StudentT::new(df);
    let pvalue = 2.0 * tdist.sf(t.abs());
    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// Independent two-sample t-test with alternative hypothesis specification.
///
/// Matches `scipy.stats.ttest_ind(a, b, equal_var=True, alternative=...)`.
///
/// # Arguments
/// * `a`, `b` - Sample data
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn ttest_ind_alternative(a: &[f64], b: &[f64], alternative: &str) -> TtestResult {
    let n1 = a.len() as f64;
    let n2 = b.len() as f64;
    let df = n1 + n2 - 2.0;
    if a.is_empty() || b.is_empty() {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    if df <= 0.0 || a.iter().any(|v| v.is_nan()) || b.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df,
        };
    }
    // Means via `par_sum` — the variances below already use the parallel `sum_sq_dev`, so the mean
    // was the last serial straggler. Byte-identical below the 1<<22 gate (par_sum is the exact serial
    // sum there); above it the means reassociate within per-op ULP like the already-parallel variances.
    let mean1: f64 = par_sum(a) / n1;
    let mean2: f64 = par_sum(b) / n2;
    let var1: f64 = if a.len() > 1 {
        sum_sq_dev(a, mean1) / (n1 - 1.0)
    } else {
        0.0
    };
    let var2: f64 = if b.len() > 1 {
        sum_sq_dev(b, mean2) / (n2 - 1.0)
    } else {
        0.0
    };

    let sp2 = ((n1 - 1.0) * var1 + (n2 - 1.0) * var2) / df;
    let se = (sp2 * (1.0 / n1 + 1.0 / n2)).sqrt();

    if se == 0.0 {
        let statistic = if (mean1 - mean2).abs() == 0.0 {
            f64::NAN
        } else {
            (mean1 - mean2).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df,
        };
    }

    let t = (mean1 - mean2) / se;
    let tdist = StudentT::new(df);

    let pvalue = match alternative {
        "less" => tdist.cdf(t),
        "greater" => tdist.sf(t),
        _ => 2.0 * tdist.sf(t.abs()),
    };

    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// Welch's t-test (unequal variance).
///
/// Matches `scipy.stats.ttest_ind(a, b, equal_var=False)`.
///
/// Short inputs do NOT return NaN uniformly, and the previous "returns NaN
/// otherwise" wording was wrong (corrected 2026-08-08, frankenscipy-4t6sd).
/// SciPy's behaviour, which this reproduces, splits on emptiness rather than on
/// the len < 2 test:
/// - either sample EMPTY -> statistic, pvalue and df all NaN;
/// - a non-empty sample of length 1 (`[1]` vs `[2]`, `[1]` vs `[2,3]`) ->
///   statistic and pvalue NaN but **df = 1.0**.
///
/// Verified against scipy 1.17.1 and pinned by
/// `ttest_ind_welch_singleton_df_matches_scipy_reference`.
pub fn ttest_ind_welch(a: &[f64], b: &[f64]) -> TtestResult {
    if a.len() < 2 || b.len() < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: if a.is_empty() || b.is_empty() {
                f64::NAN
            } else {
                1.0
            },
        };
    }
    let n1 = a.len() as f64;
    let n2 = b.len() as f64;
    // Means via `par_sum` — the variances below already use the parallel `sum_sq_dev`, so the mean
    // was the last serial straggler. Byte-identical below the 1<<22 gate (par_sum is the exact serial
    // sum there); above it the means reassociate within per-op ULP like the already-parallel variances.
    let mean1: f64 = par_sum(a) / n1;
    let mean2: f64 = par_sum(b) / n2;
    let var1: f64 = sum_sq_dev(a, mean1) / (n1 - 1.0);
    let var2: f64 = sum_sq_dev(b, mean2) / (n2 - 1.0);

    let se = (var1 / n1 + var2 / n2).sqrt();

    // Welch-Satterthwaite degrees of freedom
    let vn1 = var1 / n1;
    let vn2 = var2 / n2;
    let mut df = (vn1 + vn2).powi(2) / (vn1.powi(2) / (n1 - 1.0) + vn2.powi(2) / (n2 - 1.0));
    if df.is_nan() {
        df = 1.0;
    }

    if se == 0.0 {
        let statistic = if (mean1 - mean2).abs() == 0.0 {
            f64::NAN
        } else {
            (mean1 - mean2).signum() * f64::INFINITY
        };
        return TtestResult {
            statistic,
            pvalue: if statistic.is_nan() { f64::NAN } else { 0.0 },
            df,
        };
    }

    let t = (mean1 - mean2) / se;

    let tdist = StudentT::new(df);
    let pvalue = 2.0 * tdist.sf(t.abs());
    TtestResult {
        statistic: t,
        pvalue,
        df,
    }
}

/// Paired t-test for related samples.
///
/// Tests H0: mean of differences `a[i] - b[i]` is zero.
/// Requires equal-length paired observations.
///
/// Matches `scipy.stats.ttest_rel(a, b, alternative=...)`.
pub fn ttest_rel(
    a: &[f64],
    b: &[f64],
    alternative: Option<&str>,
) -> Result<TtestResult, StatsError> {
    let alternative = validate_hypothesis_alternative(alternative)?;
    if a.len() != b.len() || a.len() < 2 {
        return Ok(TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        });
    }
    let n = a.len() as f64;
    let diffs: Vec<f64> = a.iter().zip(b.iter()).map(|(&ai, &bi)| ai - bi).collect();
    // Mean of diffs via `par_sum` + Σ(d−d̄)² via `sum_sq_dev` — both work-gated parallel (byte-identical
    // below the 1<<22 gate; the variance is m2-insensitive to the mean, so par_sum is byte-safe there
    // too). Both were serial `.sum()` folds over `diffs`.
    let d_mean = par_sum(&diffs) / n;
    let d_var = sum_sq_dev(&diffs, d_mean) / (n - 1.0);
    let se = (d_var / n).sqrt();
    let df = n - 1.0;
    let tdist = StudentT::new(df);

    if se == 0.0 {
        let statistic = if d_mean == 0.0 {
            f64::NAN
        } else {
            d_mean.signum() * f64::INFINITY
        };
        return Ok(TtestResult {
            statistic,
            pvalue: student_t_alternative_pvalue(statistic, &tdist, alternative),
            df,
        });
    }

    let t = d_mean / se;
    Ok(TtestResult {
        statistic: t,
        pvalue: student_t_alternative_pvalue(t, &tdist, alternative),
        df,
    })
}

/// One-sample chi-squared goodness-of-fit test.
///
/// Tests whether observed frequencies differ significantly from expected.
/// This is a convenience wrapper around `power_divergence` with lambda=1.
///
/// Matches `scipy.stats.chisquare(f_obs, f_exp)`.
pub fn chisquare(f_obs: &[f64], f_exp: Option<&[f64]>) -> (f64, f64) {
    power_divergence(f_obs, f_exp, 1.0)
}

/// G-test (log-likelihood ratio test) for goodness of fit.
///
/// Tests whether observed frequencies differ significantly from expected.
/// This is a convenience wrapper around `power_divergence` with lambda=0.
///
/// The G-test is an alternative to the chi-squared test that is sometimes
/// preferred because of its better approximation in smaller samples.
///
/// Matches `scipy.stats.power_divergence(f_obs, f_exp, lambda_="log-likelihood")`.
pub fn g_test(f_obs: &[f64], f_exp: Option<&[f64]>) -> (f64, f64) {
    power_divergence(f_obs, f_exp, 0.0)
}

/// Freeman-Tukey test for goodness of fit.
///
/// A power divergence test with lambda=-0.5.
///
/// Matches `scipy.stats.power_divergence(f_obs, f_exp, lambda_="freeman-tukey")`.
pub fn freeman_tukey_test(f_obs: &[f64], f_exp: Option<&[f64]>) -> (f64, f64) {
    power_divergence(f_obs, f_exp, -0.5)
}

/// Modified log-likelihood ratio test (Cressie-Read).
///
/// A power divergence test with lambda=2/3.
///
/// Matches `scipy.stats.power_divergence(f_obs, f_exp, lambda_="mod-log-likelihood")`.
pub fn mod_log_likelihood_test(f_obs: &[f64], f_exp: Option<&[f64]>) -> (f64, f64) {
    power_divergence(f_obs, f_exp, 2.0 / 3.0)
}

/// Cressie-Read test for goodness of fit.
///
/// A power divergence test with lambda=2/3 (same as modified log-likelihood).
///
/// Matches `scipy.stats.power_divergence(f_obs, f_exp, lambda_="cressie-read")`.
pub fn cressie_read_test(f_obs: &[f64], f_exp: Option<&[f64]>) -> (f64, f64) {
    power_divergence(f_obs, f_exp, 2.0 / 3.0)
}

/// 1D Wasserstein distance (earth mover's distance) between two distributions.
///
/// Computes the first Wasserstein distance between empirical distributions
/// defined by samples u and v.
///
/// Matches `scipy.stats.wasserstein_distance(u_values, v_values)`.
pub fn wasserstein_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.is_empty()
        || v.is_empty()
        || u.iter().any(|&val| val.is_nan())
        || v.iter().any(|&val| val.is_nan())
    {
        return f64::NAN;
    }

    // Resolves [frankenscipy-k8sed]: linear merge sweep over the two
    // sorted samples, advancing pointers to track CDF counts. The
    // previous version sorted+deduped a third Vec and called
    // partition_point (O(log N)) per step, totaling O((N+M)·log(N+M)).
    // The two-pointer variant runs in O(N + M).
    // The two O(N log N) sorts dominate this O(N+M) sweep and are independent, so
    // overlap them on separate threads for large inputs (see sort_two_f64_total).
    // BIT-IDENTICAL: deterministic sort feeds the unchanged merge sweep.
    let (u_sorted, v_sorted) = sort_two_f64_total(u, v);
    wasserstein_distance_sorted(&u_sorted, &v_sorted)
}

/// [`wasserstein_distance`] (1-D) on inputs already sorted ascending (`total_cmp` order) and NaN-free.
/// Skips the sort so an all-pairs matrix can sort each sample ONCE up front (the sort is
/// query-independent). BYTE-IDENTICAL to `wasserstein_distance` on the same finite data: the same
/// sorted arrays feed the same merge sweep.
fn wasserstein_distance_sorted(u_sorted: &[f64], v_sorted: &[f64]) -> f64 {
    if u_sorted.is_empty() || v_sorted.is_empty() {
        return f64::NAN;
    }
    let nu = u_sorted.len() as f64;
    let nv = v_sorted.len() as f64;

    // CDF counts: number of u/v values seen so far, ≤ current threshold.
    let mut iu = 0_usize;
    let mut iv = 0_usize;
    let mut prev_val = u_sorted[0].min(v_sorted[0]);
    let mut distance = 0.0_f64;

    while iu < u_sorted.len() || iv < v_sorted.len() {
        // Pick the next breakpoint = min of the two remaining heads.
        let next_val = match (u_sorted.get(iu), v_sorted.get(iv)) {
            (Some(&u_val), Some(&v_val)) => u_val.min(v_val),
            (Some(&u_val), None) => u_val,
            (None, Some(&v_val)) => v_val,
            (None, None) => break,
        };

        // Accumulate area at the previous breakpoint (CDF is a step
        // function — the area between (prev_val, next_val] uses the
        // CDF values established by counts iu, iv up to prev_val).
        let cdf_u = iu as f64 / nu;
        let cdf_v = iv as f64 / nv;
        distance += (cdf_u - cdf_v).abs() * (next_val - prev_val);

        // Advance whichever pointers have head equal to next_val. This
        // is equivalent to partition_point but in O(1) per step.
        while iu < u_sorted.len() && u_sorted[iu] <= next_val {
            iu += 1;
        }
        while iv < v_sorted.len() && v_sorted[iv] <= next_val {
            iv += 1;
        }
        prev_val = next_val;
    }

    distance
}

/// First Wasserstein (earth-mover's) distance between two N-D discrete
/// distributions.
///
/// Matches `scipy.stats.wasserstein_distance_nd`. `u_values` and `v_values` are
/// point sets (one inner `Vec` per support point, all of the same dimension `d`);
/// `u_weights`/`v_weights` are optional masses (default uniform). The distance is
/// the optimal-transport cost under the Euclidean ground metric, obtained here by
/// solving the transport LP `min Σ Dᵢⱼ Pᵢⱼ` s.t. the row/column marginals equal
/// the (normalised) weights and `P ≥ 0` — the same optimum scipy computes via the
/// Kantorovich dual.
///
/// Returns `NaN` on empty/ragged input or non-positive total weight. Mirrors
/// scipy's infinity handling: `+∞` if exactly one input contains an infinity,
/// `NaN` if both do.
pub fn wasserstein_distance_nd(
    u_values: &[Vec<f64>],
    v_values: &[Vec<f64>],
    u_weights: Option<&[f64]>,
    v_weights: Option<&[f64]>,
) -> f64 {
    let m = u_values.len();
    let n = v_values.len();
    if m == 0 || n == 0 {
        return f64::NAN;
    }
    let d = u_values[0].len();
    if d == 0 || u_values.iter().any(|r| r.len() != d) || v_values.iter().any(|r| r.len() != d) {
        return f64::NAN;
    }

    // Infinity handling, mirroring scipy.
    let u_inf = u_values.iter().flatten().any(|x| x.is_infinite());
    let v_inf = v_values.iter().flatten().any(|x| x.is_infinite());
    if u_inf ^ v_inf {
        return f64::INFINITY;
    }
    if u_inf && v_inf {
        return f64::NAN;
    }

    // Normalise the marginals (default uniform).
    let normalize = |w: Option<&[f64]>, len: usize| -> Option<Vec<f64>> {
        match w {
            None => Some(vec![1.0 / len as f64; len]),
            Some(weights) => {
                if weights.len() != len {
                    return None;
                }
                let sum: f64 = weights.iter().sum();
                if !(sum.is_finite() && sum > 0.0) {
                    return None;
                }
                Some(weights.iter().map(|&x| x / sum).collect())
            }
        }
    };
    let (p_u, p_v) = match (normalize(u_weights, m), normalize(v_weights, n)) {
        (Some(a), Some(b)) => (a, b),
        _ => return f64::NAN,
    };

    // Cost matrix c = vec(D), Dᵢⱼ = ‖u_i − v_j‖₂.
    let nvars = m * n;
    let mut cost = Vec::with_capacity(nvars);
    for ui in u_values.iter() {
        for vj in v_values.iter() {
            let dist = ui
                .iter()
                .zip(vj.iter())
                .map(|(a, b)| (a - b) * (a - b))
                .sum::<f64>()
                .sqrt();
            cost.push(dist);
        }
    }

    // Equality constraints: m row marginals + (n−1) column marginals (the last
    // column marginal is dropped to keep A_eq full-rank for balanced masses).
    let mut a_eq: Vec<Vec<f64>> = Vec::with_capacity(m + n.saturating_sub(1));
    let mut b_eq: Vec<f64> = Vec::with_capacity(m + n.saturating_sub(1));
    for (i, &pi) in p_u.iter().enumerate() {
        let mut row = vec![0.0; nvars];
        for j in 0..n {
            row[i * n + j] = 1.0;
        }
        a_eq.push(row);
        b_eq.push(pi);
    }
    for j in 0..n.saturating_sub(1) {
        let mut row = vec![0.0; nvars];
        for i in 0..m {
            row[i * n + j] = 1.0;
        }
        a_eq.push(row);
        b_eq.push(p_v[j]);
    }

    let bounds = vec![(Some(0.0), None); nvars];
    match fsci_opt::linprog(&cost, &[], &[], &a_eq, &b_eq, &bounds, None) {
        Ok(res) if res.success => res.fun,
        _ => f64::NAN,
    }
}

/// Energy distance between two 1D distributions.
///
/// A statistical distance based on the Cramér distance:
///   D(u, v) = 2 * E|X-Y| - E|X-X'| - E|Y-Y'|
/// where X, X' ~ u and Y, Y' ~ v.
///
/// Matches `scipy.stats.energy_distance(u_values, v_values)`.
pub fn energy_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.is_empty()
        || v.is_empty()
        || u.iter().any(|&val| val.is_nan())
        || v.iter().any(|&val| val.is_nan())
    {
        return f64::NAN;
    }

    // Sort u and v ONCE (overlapping the two independent sorts for large inputs, see
    // sort_two_f64_total), then evaluate the closed-form L1-pair sums via energy_distance_sorted.
    let (su, sv) = sort_two_f64_total(u, v);
    energy_distance_sorted(&su, &sv)
}

/// [`energy_distance`] on inputs already sorted ascending (`total_cmp` order) and NaN-free. Skips the
/// sort so an all-pairs matrix can sort each sample ONCE up front (the sort is query-independent).
/// BYTE-IDENTICAL to `energy_distance` on the same finite data: the same sorted arrays feed the same
/// closed-form L1-pair sums.
fn energy_distance_sorted(su: &[f64], sv: &[f64]) -> f64 {
    let nu = su.len() as f64;
    let nv = sv.len() as f64;
    // E|X-Y|: mean of |u_i - v_j| over all pairs, via the O((N+M)) sweep on the
    // sorted inputs (frankenscipy-ggmrw). For each sorted u_i with c = #{v_j ≤ u_i}
    // and S = Σ_{v_j ≤ u_i} v_j,  Σ_j |u_i − v_j| = (2c − M)·u_i + S_total − 2·S.
    let e_xy = cross_set_l1_pair_sum_sorted(su, sv) / (nu * nv);

    // E|X-X'|: mean of |u_i - u_j| over all pairs (frankenscipy-6nuo5): for sorted
    // s of length n, Σ_{i<j}(s[j]-s[i]) = Σ_i s[i]·(2i − n + 1), O(N) after sort.
    let e_xx = within_set_l1_pair_sum_sorted(su) * 2.0 / (nu * nu);
    let e_yy = within_set_l1_pair_sum_sorted(sv) * 2.0 / (nv * nv);

    let d_sq = 2.0 * e_xy - e_xx - e_yy;
    if d_sq.is_nan() {
        f64::NAN
    } else {
        d_sq.max(0.0).sqrt()
    }
}

/// Compute the cross-set L1 pair sum  Σ_i Σ_j |u_i − v_j|  in
/// O((N+M) log(N+M)) via a two-pointer sweep on the sorted inputs.
/// Equivalent to the naïve O(N·M) double loop.
///
/// RETIRED (frankenscipy-19hon). This is the sorting WRAPPER; 8de105e9b changed
/// `energy_distance` to sort u and v once up front and call
/// [`cross_set_l1_pair_sum_sorted`] directly, so nothing reaches this entry
/// point any more. The kernel it delegates to is very much alive — only the
/// sort-then-call convenience layer is dead. Kept as the documented naive-order
/// reference for the sorted kernel rather than deleted.
#[allow(dead_code)]
fn cross_set_l1_pair_sum(u: &[f64], v: &[f64]) -> f64 {
    let mut su: Vec<f64> = u.to_vec();
    su.sort_unstable_by(|a, b| a.total_cmp(b));
    let mut sv: Vec<f64> = v.to_vec();
    sv.sort_unstable_by(|a, b| a.total_cmp(b));
    cross_set_l1_pair_sum_sorted(&su, &sv)
}

/// [`cross_set_l1_pair_sum`] on inputs already sorted ascending by `total_cmp`.
fn cross_set_l1_pair_sum_sorted(su: &[f64], sv: &[f64]) -> f64 {
    let m = sv.len();
    let m_f = m as f64;
    let s_total_v: f64 = sv.iter().sum();

    let mut total = 0.0_f64;
    let mut j = 0_usize;
    let mut s_le_v = 0.0_f64;
    for &ui in su {
        while j < m && sv[j] <= ui {
            s_le_v += sv[j];
            j += 1;
        }
        let c_le = j as f64;
        total += (2.0 * c_le - m_f) * ui + s_total_v - 2.0 * s_le_v;
    }
    total
}

/// Compute the upper-triangle pair sum  Σ_{i<j} |x_j − x_i|  in
/// O(N log N) using the sorted closed form. Equivalent to the naïve
/// O(N²) double loop.
///
/// RETIRED (frankenscipy-19hon), same reason as [`cross_set_l1_pair_sum`]: this
/// is the sorting wrapper, and 8de105e9b moved `energy_distance` to sort once up
/// front and call [`within_set_l1_pair_sum_sorted`] directly. The sorted kernel
/// is live; only this convenience layer is unreachable. Kept, not deleted.
#[allow(dead_code)]
fn within_set_l1_pair_sum(x: &[f64]) -> f64 {
    if x.len() < 2 {
        return 0.0;
    }
    let mut sorted: Vec<f64> = x.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    within_set_l1_pair_sum_sorted(&sorted)
}

/// [`within_set_l1_pair_sum`] on an input already sorted ascending by `total_cmp`.
fn within_set_l1_pair_sum_sorted(sorted: &[f64]) -> f64 {
    let n = sorted.len();
    if n < 2 {
        return 0.0;
    }
    let mut sum = 0.0_f64;
    let n_f = n as f64;
    for (i, &val) in sorted.iter().enumerate() {
        sum += val * (2.0 * i as f64 - n_f + 1.0);
    }
    sum
}

/// Jensen-Shannon divergence between two probability distributions.
///
/// The Jensen-Shannon divergence is a symmetric, smoothed version of
/// KL divergence. It is the square of the Jensen-Shannon distance.
///
/// D_JS(P || Q) = (D_KL(P || M) + D_KL(Q || M)) / 2
/// where M = (P + Q) / 2
///
/// # Arguments
/// * `p` - First probability distribution (must sum to 1)
/// * `q` - Second probability distribution (must sum to 1)
/// * `base` - Logarithm base (e.g., 2.0 for bits, E for nats)
///
/// # Returns
/// Jensen-Shannon divergence value in [0, log(2)] for base e.
///
/// When [`JENSENSHANNON_FORCE_SERIAL`] is `true`, the term loop runs serially (the ORIG behaviour);
/// default `false` materialises the heavy `ln` terms in parallel for large inputs. Byte-identical.
#[doc(hidden)]
pub static JENSENSHANNON_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn jensenshannon(p: &[f64], q: &[f64], base: Option<f64>) -> f64 {
    if p.len() != q.len() || p.is_empty() {
        return f64::NAN;
    }

    let base = base.unwrap_or(std::f64::consts::E);
    let n = p.len();

    // d_pm = Σ pᵢ·ln(pᵢ/mᵢ), d_qm = Σ qᵢ·ln(qᵢ/mᵢ), mᵢ = (pᵢ+qᵢ)/2 (computed inline — no `m` Vec).
    // Each term is a heavy independent `ln`; the two Σ are float reductions (can't chunk-merge byte-id),
    // so for large n MATERIALISE the two term arrays with an order-preserving parallel map then fold
    // each serially in index order — BYTE-IDENTICAL to the fused serial loop (each term is 0 for the
    // pᵢ≤0/mᵢ≤0 skip, and `+0.0` is a no-op in the left fold). `JENSENSHANNON_FORCE_SERIAL`.
    const JS_MIN_PER_THREAD: usize = 200_000;
    let (d_pm, d_qm) = if JENSENSHANNON_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
        || n < 2 * JS_MIN_PER_THREAD
    {
        let mut d_pm = 0.0;
        let mut d_qm = 0.0;
        for (&pi, &qi) in p.iter().zip(q) {
            let mi = (pi + qi) / 2.0;
            if pi > 0.0 && mi > 0.0 {
                d_pm += pi * (pi / mi).ln();
            }
            if qi > 0.0 && mi > 0.0 {
                d_qm += qi * (qi / mi).ln();
            }
        }
        (d_pm, d_qm)
    } else {
        let mut term_pm = vec![0.0f64; n];
        let mut term_qm = vec![0.0f64; n];
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / JS_MIN_PER_THREAD)
            .max(1);
        let chunk = n.div_ceil(nthreads);
        std::thread::scope(|scope| {
            for (((pm_b, qm_b), p_b), q_b) in term_pm
                .chunks_mut(chunk)
                .zip(term_qm.chunks_mut(chunk))
                .zip(p.chunks(chunk))
                .zip(q.chunks(chunk))
            {
                scope.spawn(move || {
                    for (((pm, qm), &pi), &qi) in pm_b
                        .iter_mut()
                        .zip(qm_b.iter_mut())
                        .zip(p_b.iter())
                        .zip(q_b.iter())
                    {
                        let mi = (pi + qi) / 2.0;
                        *pm = if pi > 0.0 && mi > 0.0 {
                            pi * (pi / mi).ln()
                        } else {
                            0.0
                        };
                        *qm = if qi > 0.0 && mi > 0.0 {
                            qi * (qi / mi).ln()
                        } else {
                            0.0
                        };
                    }
                });
            }
        });
        (term_pm.iter().sum(), term_qm.iter().sum())
    };

    let js = (d_pm + d_qm) / 2.0;
    if base == std::f64::consts::E {
        js
    } else {
        js / base.ln()
    }
}

/// Jensen-Shannon distance between two probability distributions.
///
/// The Jensen-Shannon distance is the square root of the JS divergence.
/// It is a proper metric satisfying the triangle inequality.
///
/// # Arguments
/// * `p` - First probability distribution (must sum to 1)
/// * `q` - Second probability distribution (must sum to 1)
///
/// # Returns
/// Jensen-Shannon distance value in [0, 1] when using log base 2.
pub fn jensenshannon_distance(p: &[f64], q: &[f64]) -> f64 {
    let js = jensenshannon(p, q, Some(2.0));
    if js.is_nan() || js < 0.0 {
        f64::NAN
    } else {
        js.sqrt()
    }
}

/// When `true`, [`bhattacharyya_coefficient`] sums serially (the ORIG exact 1-accumulator fold, byte-
/// identical to `map(sqrt).sum()`); default `false` fans a 4-way-unrolled chunk sum across cores for
/// large inputs. WITHIN per-op ULP tolerance (same reordering the parallel `entropy`/`kl_divergence` use).
#[doc(hidden)]
pub static BHATTACHARYYA_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `BC(p, q) = Σ √(pᵢ·qᵢ)` — the Bhattacharyya coefficient shared by [`hellinger_distance`] and
/// [`bhattacharyya_distance`]. `√(p·q)` per element is compute-bound; fan the sum across cores
/// (chunked, 4-way-unrolled). WITHIN per-op ULP tolerance (mirrors the shipped `entropy`/`kl` reorder).
fn bhattacharyya_coefficient(p: &[f64], q: &[f64]) -> f64 {
    let n = p.len();
    if BHATTACHARYYA_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        return p.iter().zip(q).map(|(&pi, &qi)| (pi * qi).sqrt()).sum();
    }
    let chunk_sum = |ps: &[f64], qs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= ps.len() {
            a[0] += (ps[i] * qs[i]).sqrt();
            a[1] += (ps[i + 1] * qs[i + 1]).sqrt();
            a[2] += (ps[i + 2] * qs[i + 2]).sqrt();
            a[3] += (ps[i + 3] * qs[i + 3]).sqrt();
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < ps.len() {
            s += (ps[i] * qs[i]).sqrt();
            i += 1;
        }
        s
    };
    if n < (1 << 17) {
        return chunk_sum(p, q);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sum = &chunk_sum;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        p.chunks(chunk)
            .zip(q.chunks(chunk))
            .map(|(ps, qs)| scope.spawn(move || chunk_sum(ps, qs)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("bhattacharyya worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, s| acc + s)
}

/// Hellinger distance between two probability distributions.
///
/// The Hellinger distance is defined as:
/// H(P, Q) = sqrt(1 - BC(P, Q))
/// where BC(P, Q) = Σ sqrt(P_i * Q_i) is the Bhattacharyya coefficient.
///
/// # Arguments
/// * `p` - First probability distribution (must sum to 1)
/// * `q` - Second probability distribution (must sum to 1)
///
/// # Returns
/// Hellinger distance value in [0, 1].
pub fn hellinger_distance(p: &[f64], q: &[f64]) -> f64 {
    if p.len() != q.len() || p.is_empty() {
        return f64::NAN;
    }

    let bc = bhattacharyya_coefficient(p, q);

    (1.0 - bc.min(1.0)).max(0.0).sqrt()
}

/// Bhattacharyya distance between two probability distributions.
///
/// D_B(P, Q) = -ln(BC(P, Q))
/// where BC(P, Q) = Σ sqrt(P_i * Q_i) is the Bhattacharyya coefficient.
///
/// # Arguments
/// * `p` - First probability distribution (must sum to 1)
/// * `q` - Second probability distribution (must sum to 1)
///
/// # Returns
/// Bhattacharyya distance value in [0, ∞).
pub fn bhattacharyya_distance(p: &[f64], q: &[f64]) -> f64 {
    if p.len() != q.len() || p.is_empty() {
        return f64::NAN;
    }

    let bc = bhattacharyya_coefficient(p, q);

    if bc <= 0.0 { f64::INFINITY } else { -bc.ln() }
}

/// When `true`, [`sqeuclidean_sum`] sums serially (the ORIG exact 1-accumulator fold, byte-
/// identical to `map(..).sum()`); default `false` fans a 4-way-unrolled chunk sum across cores for
/// large inputs. WITHIN per-op ULP tolerance (same reordering the parallel `bhattacharyya` sum uses).
#[doc(hidden)]
pub static SQEUCLIDEAN_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `Σ (uᵢ − vᵢ)²` — the squared-Euclidean sum shared by [`euclidean_distance`] and
/// [`sqeuclidean_distance`]. Per element is compute-light (one sub + one square), so this is
/// bandwidth-bound; fan the sum across cores (chunked, 4-way-unrolled) for large inputs.
/// WITHIN per-op ULP tolerance (mirrors the shipped parallel `bhattacharyya_coefficient` reorder).
fn sqeuclidean_sum(u: &[f64], v: &[f64]) -> f64 {
    let n = u.len();
    if SQEUCLIDEAN_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        return u.iter().zip(v).map(|(&ui, &vi)| (ui - vi).powi(2)).sum();
    }
    let chunk_sum = |us: &[f64], vs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= us.len() {
            a[0] += (us[i] - vs[i]).powi(2);
            a[1] += (us[i + 1] - vs[i + 1]).powi(2);
            a[2] += (us[i + 2] - vs[i + 2]).powi(2);
            a[3] += (us[i + 3] - vs[i + 3]).powi(2);
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < us.len() {
            s += (us[i] - vs[i]).powi(2);
            i += 1;
        }
        s
    };
    // Bandwidth-light kernel: parallel only pays past ~1M (thread-spawn overhead loses
    // at 200k, 0.68x; wins 2.2-2.4x at 8-16M). Gate at 1<<20 so no measured size regresses.
    if n < (1 << 20) {
        return chunk_sum(u, v);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sum = &chunk_sum;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        u.chunks(chunk)
            .zip(v.chunks(chunk))
            .map(|(us, vs)| scope.spawn(move || chunk_sum(us, vs)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("sqeuclidean worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, s| acc + s)
}

/// Compute the Euclidean distance between two vectors.
///
/// d(u, v) = sqrt(Σ (u_i - v_i)²)
pub fn euclidean_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }
    sqeuclidean_sum(u, v).sqrt()
}

/// Compute the squared Euclidean distance between two vectors.
///
/// d²(u, v) = Σ (u_i - v_i)²
pub fn sqeuclidean_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }
    sqeuclidean_sum(u, v)
}

/// Compute the cosine distance between two vectors.
///
/// d(u, v) = 1 - (u · v) / (||u|| ||v||)
///
/// Returns a value in [0, 2] where 0 means identical direction.
pub fn cosine_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }

    // Fuse the three independent reductions (dot, Σu², Σv²) into ONE pass so the
    // two arrays are read once instead of three times (bandwidth-bound for large n).
    // Byte-identical: each accumulator still sees additions in index order 0..n.
    let mut dot = 0.0f64;
    let mut sq_u = 0.0f64;
    let mut sq_v = 0.0f64;
    for (&ui, &vi) in u.iter().zip(v) {
        dot += ui * vi;
        sq_u += ui * ui;
        sq_v += vi * vi;
    }
    let norm_u = sq_u.sqrt();
    let norm_v = sq_v.sqrt();

    if norm_u == 0.0 || norm_v == 0.0 {
        return f64::NAN;
    }

    1.0 - dot / (norm_u * norm_v)
}

/// When `true`, [`cityblock_distance`] sums serially (the ORIG exact 1-accumulator fold, byte-
/// identical to `map(..).sum()`); default `false` fans a 4-way-unrolled chunk sum across cores for
/// large inputs. WITHIN per-op ULP tolerance (same reordering the parallel `sqeuclidean` sum uses).
#[doc(hidden)]
pub static CITYBLOCK_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the Manhattan (city block) distance between two vectors.
///
/// d(u, v) = Σ |u_i - v_i|
pub fn cityblock_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }
    let n = u.len();
    if CITYBLOCK_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        return u.iter().zip(v).map(|(&ui, &vi)| (ui - vi).abs()).sum();
    }
    let chunk_sum = |us: &[f64], vs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= us.len() {
            a[0] += (us[i] - vs[i]).abs();
            a[1] += (us[i + 1] - vs[i + 1]).abs();
            a[2] += (us[i + 2] - vs[i + 2]).abs();
            a[3] += (us[i + 3] - vs[i + 3]).abs();
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < us.len() {
            s += (us[i] - vs[i]).abs();
            i += 1;
        }
        s
    };
    // Bandwidth-light kernel (sub + abs): parallel only pays past ~1M, gate at 1<<20
    // like sqeuclidean so no small size regresses.
    if n < (1 << 20) {
        return chunk_sum(u, v);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sum = &chunk_sum;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        u.chunks(chunk)
            .zip(v.chunks(chunk))
            .map(|(us, vs)| scope.spawn(move || chunk_sum(us, vs)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("cityblock worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, s| acc + s)
}

/// When `true`, [`chebyshev_distance`] folds serially (the ORIG single-accumulator `fold(max)`);
/// default `false` fans a 4-way-unrolled chunk max across cores for large inputs. BYTE-IDENTICAL
/// either way — `f64::max` is exactly associative/commutative and ignores NaN, so any grouping of
/// the reduction yields the same bits (unlike the ULP-reordered parallel SUM siblings).
#[doc(hidden)]
pub static CHEBYSHEV_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the Chebyshev distance between two vectors.
///
/// d(u, v) = max_i |u_i - v_i|
pub fn chebyshev_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }
    let n = u.len();
    // Serial = the ORIGINAL naive fold; LLVM already auto-vectorizes a max-reduction (maxpd),
    // so a manual unroll doesn't help below the gate — keep the naive fold there unchanged.
    let serial = || {
        u.iter()
            .zip(v)
            .map(|(&ui, &vi)| (ui - vi).abs())
            .fold(0.0f64, |acc, d| acc.max(d))
    };
    // Cheap kernel (sub + abs + max): the fixed thread-spawn cost only amortizes at large n
    // (measured 0.90x @2M loss, 2.0-2.2x @8-16M). Gate at 1<<22 so no measured size regresses.
    // BYTE-IDENTICAL at every size — f64::max is exactly associative/commutative and ignores NaN,
    // so the parallel per-chunk max + max-combine yields the same bits as the serial fold.
    if CHEBYSHEV_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 22) {
        return serial();
    }
    let chunk_max = |us: &[f64], vs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= us.len() {
            a[0] = a[0].max((us[i] - vs[i]).abs());
            a[1] = a[1].max((us[i + 1] - vs[i + 1]).abs());
            a[2] = a[2].max((us[i + 2] - vs[i + 2]).abs());
            a[3] = a[3].max((us[i + 3] - vs[i + 3]).abs());
            i += 4;
        }
        let mut m = a[0].max(a[1]).max(a[2]).max(a[3]);
        while i < us.len() {
            m = m.max((us[i] - vs[i]).abs());
            i += 1;
        }
        m
    };
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_max = &chunk_max;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        u.chunks(chunk)
            .zip(v.chunks(chunk))
            .map(|(us, vs)| scope.spawn(move || chunk_max(us, vs)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("chebyshev worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, m| acc.max(m))
}

/// When `true`, [`minkowski_distance`] sums serially (the ORIG exact 1-accumulator fold, byte-
/// identical to `map(..).sum()`); default `false` fans a 4-way-unrolled chunk sum across cores for
/// large inputs. WITHIN per-op ULP tolerance (same reordering the parallel `canberra` sum uses).
#[doc(hidden)]
pub static MINKOWSKI_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the Minkowski distance between two vectors.
///
/// d(u, v) = (Σ |u_i - v_i|^p)^(1/p)
///
/// Special cases: p=1 is cityblock, p=2 is Euclidean.
pub fn minkowski_distance(u: &[f64], v: &[f64], p: f64) -> f64 {
    if u.len() != v.len() || u.is_empty() || p <= 0.0 {
        return f64::NAN;
    }
    if p == f64::INFINITY {
        return chebyshev_distance(u, v);
    }
    let n = u.len();
    if MINKOWSKI_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        return u
            .iter()
            .zip(v)
            .map(|(&ui, &vi)| (ui - vi).abs().powf(p))
            .sum::<f64>()
            .powf(1.0 / p);
    }
    let chunk_sum = |us: &[f64], vs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= us.len() {
            a[0] += (us[i] - vs[i]).abs().powf(p);
            a[1] += (us[i + 1] - vs[i + 1]).abs().powf(p);
            a[2] += (us[i + 2] - vs[i + 2]).abs().powf(p);
            a[3] += (us[i + 3] - vs[i + 3]).abs().powf(p);
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < us.len() {
            s += (us[i] - vs[i]).abs().powf(p);
            i += 1;
        }
        s
    };
    // Very heavy kernel (powf per element) is strongly compute-bound → parallel pays
    // very early; gate the thread fan-out at 1<<16.
    let total = if n < (1 << 16) {
        chunk_sum(u, v)
    } else {
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / (1 << 15))
            .max(1);
        let chunk = n.div_ceil(nthreads);
        let chunk_sum = &chunk_sum;
        let parts: Vec<f64> = std::thread::scope(|scope| {
            u.chunks(chunk)
                .zip(v.chunks(chunk))
                .map(|(us, vs)| scope.spawn(move || chunk_sum(us, vs)))
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("minkowski worker panicked"))
                .collect()
        });
        parts.into_iter().fold(0.0f64, |acc, s| acc + s)
    };
    total.powf(1.0 / p)
}

/// When `true`, [`canberra_distance`] sums serially (the ORIG exact 1-accumulator fold, byte-
/// identical to `map(..).sum()`); default `false` fans a 4-way-unrolled chunk sum across cores for
/// large inputs. WITHIN per-op ULP tolerance (same reordering the parallel `cityblock` sum uses).
#[doc(hidden)]
pub static CANBERRA_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the Canberra distance between two vectors.
///
/// d(u, v) = Σ |u_i - v_i| / (|u_i| + |v_i|)
///
/// A weighted version of Manhattan distance, particularly sensitive
/// to small changes near zero.
pub fn canberra_distance(u: &[f64], v: &[f64]) -> f64 {
    if u.len() != v.len() || u.is_empty() {
        return f64::NAN;
    }
    let n = u.len();
    let kern = |ui: f64, vi: f64| -> f64 {
        let denom = ui.abs() + vi.abs();
        if denom == 0.0 {
            0.0
        } else {
            (ui - vi).abs() / denom
        }
    };
    if CANBERRA_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        return u.iter().zip(v).map(|(&ui, &vi)| kern(ui, vi)).sum();
    }
    let chunk_sum = |us: &[f64], vs: &[f64]| -> f64 {
        let mut a = [0.0f64; 4];
        let mut i = 0;
        while i + 4 <= us.len() {
            a[0] += kern(us[i], vs[i]);
            a[1] += kern(us[i + 1], vs[i + 1]);
            a[2] += kern(us[i + 2], vs[i + 2]);
            a[3] += kern(us[i + 3], vs[i + 3]);
            i += 4;
        }
        let mut s = (a[0] + a[1]) + (a[2] + a[3]);
        while i < us.len() {
            s += kern(us[i], vs[i]);
            i += 1;
        }
        s
    };
    // Heavier kernel (3 abs + sub + div + branch) is compute-bound → parallel pays
    // earlier; gate the thread fan-out at 1<<17.
    if n < (1 << 17) {
        return chunk_sum(u, v);
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(n / (1 << 16))
        .max(1);
    let chunk = n.div_ceil(nthreads);
    let chunk_sum = &chunk_sum;
    let parts: Vec<f64> = std::thread::scope(|scope| {
        u.chunks(chunk)
            .zip(v.chunks(chunk))
            .map(|(us, vs)| scope.spawn(move || chunk_sum(us, vs)))
            .collect::<Vec<_>>()
            .into_iter()
            .map(|h| h.join().expect("canberra worker panicked"))
            .collect()
    });
    parts.into_iter().fold(0.0f64, |acc, s| acc + s)
}

// ══════════════════════════════════════════════════════════════════════
// Non-parametric Tests and ANOVA
// ══════════════════════════════════════════════════════════════════════

/// One-way ANOVA (Analysis of Variance).
///
/// Compute the total sum of squares (SS_Total).
///
/// SS_Total = Σ (x_i - grand_mean)²
///
/// This is the total variability in the data, which can be
/// partitioned into between-group and within-group components.
pub fn ss_total(groups: &[&[f64]]) -> f64 {
    let all_values: Vec<f64> = groups.iter().flat_map(|g| g.iter().copied()).collect();
    if all_values.is_empty() {
        return f64::NAN;
    }
    let n = all_values.len() as f64;
    let grand_mean = all_values.iter().sum::<f64>() / n;
    all_values.iter().map(|&x| (x - grand_mean).powi(2)).sum()
}

/// Compute the between-group sum of squares (SS_Between).
///
/// SS_Between = Σ n_i * (group_mean_i - grand_mean)²
///
/// Measures the variability between group means.
pub fn ss_between(groups: &[&[f64]]) -> f64 {
    if groups.is_empty() || groups.iter().any(|g| g.is_empty()) {
        return f64::NAN;
    }
    let all_values: Vec<f64> = groups.iter().flat_map(|g| g.iter().copied()).collect();
    let n = all_values.len() as f64;
    let grand_mean = all_values.iter().sum::<f64>() / n;

    groups
        .iter()
        .map(|g| {
            let gi_mean: f64 = g.iter().sum::<f64>() / g.len() as f64;
            g.len() as f64 * (gi_mean - grand_mean).powi(2)
        })
        .sum()
}

/// Compute the within-group sum of squares (SS_Within).
///
/// SS_Within = Σ Σ (x_ij - group_mean_i)²
///
/// Measures the variability within groups (error/residual).
pub fn ss_within(groups: &[&[f64]]) -> f64 {
    if groups.is_empty() || groups.iter().any(|g| g.is_empty()) {
        return f64::NAN;
    }
    groups
        .iter()
        .map(|g| {
            let gi_mean: f64 = g.iter().sum::<f64>() / g.len() as f64;
            g.iter().map(|&x| (x - gi_mean).powi(2)).sum::<f64>()
        })
        .sum()
}

/// Matches `scipy.stats.f_oneway(*groups)`.
///
/// Tests H0: all group means are equal.
/// Assumes normality and equal variances within groups.
/// When `true`, [`f_oneway`] recomputes each group's mean inside BOTH the between- and within-group
/// sums of squares (the ORIG behaviour, one redundant full pass over the data); default `false` hoists
/// the per-group means and reuses them. Byte-identical. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static F_ONEWAY_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn f_oneway(groups: &[&[f64]]) -> TtestResult {
    if groups.len() < 2
        || groups.iter().any(|g| g.is_empty())
        || groups.iter().any(|g| g.iter().any(|v| v.is_nan()))
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let k = groups.len() as f64; // number of groups
    let n_total: usize = groups.iter().map(|g| g.len()).sum();
    let nf = n_total as f64;

    if n_total <= groups.len() {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    // Grand mean
    let grand_sum: f64 = groups.iter().flat_map(|g| g.iter()).sum();
    let grand_mean = grand_sum / nf;

    // Between- and within-group sums of squares. The ORIG recomputed each group's mean `Σg/len`
    // TWICE — once inside ss_between and again inside ss_within — an extra full traversal of the
    // data. Hoist the per-group means ONCE and reuse: ss_between then needs no data traversal at all,
    // and ss_within reuses the cached mean. BYTE-IDENTICAL: `gi_mean` is the same deterministic
    // `Σg/len` feeding the same two closed forms. `F_ONEWAY_FUSE_DISABLE` restores the twice-computed
    // ORIG for the same-binary A/B gate.
    let (ss_between, ss_within): (f64, f64) =
        if F_ONEWAY_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
            let ssb = groups
                .iter()
                .map(|g| {
                    let gi_mean: f64 = g.iter().sum::<f64>() / g.len() as f64;
                    g.len() as f64 * (gi_mean - grand_mean).powi(2)
                })
                .sum();
            let ssw = groups
                .iter()
                .map(|g| {
                    let gi_mean: f64 = g.iter().sum::<f64>() / g.len() as f64;
                    g.iter().map(|&x| (x - gi_mean).powi(2)).sum::<f64>()
                })
                .sum();
            (ssb, ssw)
        } else {
            let group_means: Vec<f64> = groups
                .iter()
                .map(|g| g.iter().sum::<f64>() / g.len() as f64)
                .collect();
            let ssb = groups
                .iter()
                .zip(&group_means)
                .map(|(g, &gi_mean)| g.len() as f64 * (gi_mean - grand_mean).powi(2))
                .sum();
            let ssw = groups
                .iter()
                .zip(&group_means)
                .map(|(g, &gi_mean)| g.iter().map(|&x| (x - gi_mean).powi(2)).sum::<f64>())
                .sum();
            (ssb, ssw)
        };

    let df_between = k - 1.0;
    let df_within = nf - k;

    if df_within <= 0.0 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: df_between,
        };
    }

    if ss_within == 0.0 {
        if ss_between == 0.0 {
            return TtestResult {
                statistic: f64::NAN,
                pvalue: f64::NAN,
                df: df_between,
            };
        } else {
            return TtestResult {
                statistic: f64::INFINITY,
                pvalue: 0.0,
                df: df_between,
            };
        }
    }

    let ms_between = ss_between / df_between;
    let ms_within = ss_within / df_within;
    let f_stat = ms_between / ms_within;

    let fdist = FDistribution::new(df_between, df_within);
    let cdf_val = fdist.cdf(f_stat);
    let pvalue = if !cdf_val.is_finite() || !(0.0..=1.0).contains(&cdf_val) {
        if f_stat > 0.0 { 0.0 } else { 1.0 }
    } else {
        (1.0 - cdf_val).max(0.0)
    };

    TtestResult {
        statistic: f_stat,
        pvalue,
        df: df_between,
    }
}

/// One-way ANOVA with nan_policy parameter.
///
/// Matches `scipy.stats.f_oneway(*groups, nan_policy=...)`.
///
/// * `nan_policy` - "propagate" (default), "omit", or "raise"
pub fn f_oneway_with_nan_policy(
    groups: &[&[f64]],
    nan_policy: Option<&str>,
) -> Result<TtestResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;

    let has_nan = groups.iter().any(|g| g.iter().any(|v| v.is_nan()));

    if has_nan {
        match nan_policy {
            "raise" => {
                return Err(StatsError::InvalidArgument(
                    "input contains NaN values".to_string(),
                ));
            }
            "propagate" => {
                return Ok(TtestResult {
                    statistic: f64::NAN,
                    pvalue: f64::NAN,
                    df: f64::NAN,
                });
            }
            "omit" => {
                let cleaned: Vec<Vec<f64>> = groups
                    .iter()
                    .map(|g| g.iter().copied().filter(|v| !v.is_nan()).collect())
                    .collect();
                let cleaned_refs: Vec<&[f64]> = cleaned.iter().map(|v| v.as_slice()).collect();
                return Ok(f_oneway(&cleaned_refs));
            }
            _ => {}
        }
    }

    Ok(f_oneway(groups))
}

/// Alexander-Govern test for equality of means.
///
/// Matches `scipy.stats.alexandergovern(*groups)`.
/// A non-parametric alternative to one-way ANOVA that doesn't assume
/// homogeneity of variances (robust to heteroscedasticity).
///
/// # Arguments
/// * `groups` - Slice of sample arrays for each group
///
/// # Returns
/// `TtestResult` with the test statistic and p-value.
pub fn alexander_govern(groups: &[&[f64]]) -> TtestResult {
    let k = groups.len();
    if k < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let mut means = Vec::with_capacity(k);
    let mut standard_errors_squared = Vec::with_capacity(k);
    let mut lengths = Vec::with_capacity(k);

    for group in groups.iter() {
        let n = group.len();
        if n < 2 {
            return TtestResult {
                statistic: f64::NAN,
                pvalue: f64::NAN,
                df: f64::NAN,
            };
        }
        let n_f = n as f64;
        let mean: f64 = group.iter().sum::<f64>() / n_f;
        let var: f64 = group.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / (n_f - 1.0);
        if var <= 0.0 {
            return TtestResult {
                statistic: f64::NAN,
                pvalue: f64::NAN,
                df: f64::NAN,
            };
        }
        let se2 = var / n_f;
        means.push(mean);
        standard_errors_squared.push(se2);
        lengths.push(n_f);
    }

    // (2) define a weight for each sample
    let inv_sq_se_sum: f64 = standard_errors_squared.iter().map(|&se2| 1.0 / se2).sum();
    let weights: Vec<f64> = standard_errors_squared
        .iter()
        .map(|&se2| (1.0 / se2) / inv_sq_se_sum)
        .collect();

    // (3) variance-weighted estimate of the common mean
    let var_w: f64 = means.iter().zip(&weights).map(|(&m, &w)| m * w).sum();

    // (4) one-sample t statistic for each group and transformation
    let mut a_stat = 0.0;
    for i in 0..k {
        let se = standard_errors_squared[i].sqrt();
        let t_stat = (means[i] - var_w) / se;
        let v = lengths[i] - 1.0;

        // Parameters for transformation (scipy formulas)
        let a = v - 0.5;
        let b = 48.0 * a * a;
        let c = (a * (1.0 + t_stat * t_stat / v).ln()).sqrt();

        // (8) normalizing transformation
        let z = c + (c.powi(3) + 3.0 * c) / b
            - (4.0 * c.powi(7) + 33.0 * c.powi(5) + 240.0 * c.powi(3) + 855.0 * c)
                / (b * b * 10.0 + 8.0 * b * c.powi(4) + 1000.0 * b);

        a_stat += z * z;
    }

    let df = (k - 1) as f64;
    let pvalue = 1.0 - ChiSquared::new(df).cdf(a_stat.max(0.0));

    TtestResult {
        statistic: a_stat,
        pvalue,
        df,
    }
}

/// Result for Tukey's HSD test.
#[derive(Debug, Clone, PartialEq)]
pub struct TukeyHSDResult {
    /// Pairwise mean differences (i,j) = mean_i - mean_j.
    pub statistic: Vec<Vec<f64>>,
    /// Pairwise p-values using Bonferroni correction.
    pub pvalue: Vec<Vec<f64>>,
}

/// Tukey's HSD test for pairwise comparison of group means.
///
/// Post-hoc test after ANOVA to identify which groups differ.
/// Uses the Studentized Range distribution for exact p-values.
///
/// Matches `scipy.stats.tukey_hsd(*groups)`.
///
/// # Arguments
/// * `groups` - Slice of sample arrays for each group
///
/// # Returns
/// `TukeyHSDResult` with matrices of statistics (mean differences) and p-values.
pub fn tukey_hsd(groups: &[&[f64]]) -> TukeyHSDResult {
    let k = groups.len();
    if k < 2 {
        return TukeyHSDResult {
            statistic: vec![],
            pvalue: vec![],
        };
    }

    // Compute group means and sizes
    let means: Vec<f64> = groups
        .iter()
        .map(|g| {
            if g.is_empty() {
                f64::NAN
            } else {
                g.iter().sum::<f64>() / g.len() as f64
            }
        })
        .collect();

    let ns: Vec<f64> = groups.iter().map(|g| g.len() as f64).collect();

    // Compute pooled variance (MSE from ANOVA)
    let n_total: usize = groups.iter().map(|g| g.len()).sum();
    let df_within = n_total as f64 - k as f64;

    if df_within <= 0.0 {
        return TukeyHSDResult {
            statistic: vec![vec![f64::NAN; k]; k],
            pvalue: vec![vec![f64::NAN; k]; k],
        };
    }

    let ss_within: f64 = groups
        .iter()
        .zip(means.iter())
        .map(|(g, &m)| g.iter().map(|&x| (x - m).powi(2)).sum::<f64>())
        .sum();
    let mse = ss_within / df_within;

    // Studentized Range distribution for k groups with df_within degrees of freedom
    let sr_dist = StudentizedRange::new(k, df_within);

    // Compute pairwise statistics and p-values
    let mut stat_matrix = vec![vec![0.0; k]; k];
    let mut pval_matrix = vec![vec![1.0; k]; k];

    for i in 0..k {
        for j in 0..k {
            if i == j {
                stat_matrix[i][j] = 0.0;
                pval_matrix[i][j] = 1.0;
            } else {
                let mean_diff = means[i] - means[j];
                stat_matrix[i][j] = mean_diff;

                // Standard error: sqrt(MSE / n) for equal sample sizes
                // For unequal sizes, use harmonic mean: sqrt(MSE * (1/ni + 1/nj) / 2)
                let se = (mse * (1.0 / ns[i] + 1.0 / ns[j]) / 2.0).sqrt();

                if se > 0.0 {
                    let q = mean_diff.abs() / se;
                    pval_matrix[i][j] = sr_dist.sf(q);
                } else {
                    pval_matrix[i][j] = f64::NAN;
                }
            }
        }
    }

    TukeyHSDResult {
        statistic: stat_matrix,
        pvalue: pval_matrix,
    }
}

/// Result for Dunnett's test.
#[derive(Debug, Clone, PartialEq)]
pub struct DunnettResult {
    /// Test statistics (t-values) for each treatment vs control.
    pub statistic: Vec<f64>,
    /// P-values for each comparison using multivariate t distribution.
    pub pvalue: Vec<f64>,
}

/// Compute p-value for Dunnett's test using multivariate t distribution.
///
/// For k comparisons with equal correlation ρ, computes P(max|T_i| >= t)
/// where T follows a k-variate t distribution with correlation ρ.
fn dunnett_pvalue_mvt(t_abs: f64, k: usize, df: f64, rho: f64) -> f64 {
    if k == 0 {
        return 1.0;
    }
    if k == 1 {
        let tdist = StudentT::new(df);
        return 2.0 * (1.0 - tdist.cdf(t_abs));
    }
    if t_abs <= 0.0 {
        return 1.0;
    }
    if !t_abs.is_finite() {
        return 0.0;
    }

    // P(max|T_i| < t) = integral over s of P(all |Z_i| < t*s/sqrt(1-ρ) - ρ/(1-ρ)*z | z) * f_chi(s) ds
    // where s ~ sqrt(chi2(df)/df), z ~ N(0,1)
    //
    // Simplified: for equicorrelated multivariate t, we integrate:
    // P(all T_i in [-t, t]) = integral f_chi2_scaled(s) * [integral phi(z) * prod_i P(-t*s - sqrt(ρ)*z < sqrt(1-ρ)*Z_i < t*s - sqrt(ρ)*z) dz] ds

    let sqrt_rho = rho.sqrt();
    let sqrt_1m_rho = (1.0 - rho).sqrt();
    let k_f = k as f64;
    let half_df = df / 2.0;
    let log_chi2_norm = half_df * 2.0_f64.ln() + ln_gamma(half_df);

    // Outer integral over chi2 distribution
    let chi2_upper = (df + 12.0 * (2.0 * df).sqrt()).max(60.0);

    let prob_all_within = simpson_integrate_adaptive(
        |v| {
            if v <= 0.0 {
                return 0.0;
            }
            let s = (v / df).sqrt();
            let bound = t_abs * s;

            // Inner integral over z (common latent normal)
            let inner = simpson_integrate_adaptive(
                |z| {
                    let phi_z = (-0.5 * z * z).exp() / (2.0 * PI).sqrt();
                    let low = (-bound - sqrt_rho * z) / sqrt_1m_rho;
                    let high = (bound - sqrt_rho * z) / sqrt_1m_rho;
                    let prob_one = standard_normal_cdf(high) - standard_normal_cdf(low);
                    phi_z * prob_one.max(0.0).powf(k_f)
                },
                -10.0,
                10.0,
                32,
                1e-9,
                1e-12,
                10,
            );

            let log_chi2_pdf = (half_df - 1.0) * v.ln() - v / 2.0 - log_chi2_norm;
            inner * log_chi2_pdf.exp()
        },
        1e-10,
        chi2_upper,
        64,
        1e-9,
        1e-12,
        12,
    );

    (1.0 - prob_all_within).clamp(0.0, 1.0)
}

/// Dunnett's test for multiple comparisons against a control group.
///
/// Compares each treatment group to a single control group.
/// More powerful than Tukey HSD when only control comparisons are needed.
/// Uses the multivariate t distribution for exact p-values.
///
/// Matches `scipy.stats.dunnett(*samples, control=control)`.
///
/// # Arguments
/// * `treatments` - Slice of sample arrays for treatment groups
/// * `control` - Sample array for the control group
///
/// # Returns
/// `DunnettResult` with test statistics and p-values for each treatment vs control.
///
/// # Examples
/// ```
/// use fsci_stats::dunnett;
/// let control = [2.0, 2.5, 3.0, 2.8];
/// let treatment1 = [5.0, 5.5, 6.0, 5.2];
/// let treatment2 = [2.1, 2.3, 2.9, 2.7];
/// let result = dunnett(&[&treatment1, &treatment2], &control);
/// assert!(result.pvalue[0] < 0.05); // treatment1 differs from control
/// assert!(result.pvalue[1] > 0.05); // treatment2 similar to control
/// ```
pub fn dunnett(treatments: &[&[f64]], control: &[f64]) -> DunnettResult {
    let k = treatments.len();
    if k == 0 || control.is_empty() {
        return DunnettResult {
            statistic: vec![],
            pvalue: vec![],
        };
    }

    // Control group statistics
    let n_c = control.len() as f64;
    let mean_c: f64 = control.iter().sum::<f64>() / n_c;

    // Compute pooled variance (MSE)
    let mut ss_within = control.iter().map(|&x| (x - mean_c).powi(2)).sum::<f64>();
    let mut df_within = n_c - 1.0;

    // Treatment group statistics
    let treatment_stats: Vec<(f64, f64, f64)> = treatments
        .iter()
        .map(|t| {
            if t.is_empty() {
                (f64::NAN, 0.0, 0.0)
            } else {
                let n = t.len() as f64;
                let mean = t.iter().sum::<f64>() / n;
                let ss: f64 = t.iter().map(|&x| (x - mean).powi(2)).sum();
                (mean, n, ss)
            }
        })
        .collect();

    // Add treatment contributions to pooled variance
    for (_, _, ss) in &treatment_stats {
        ss_within += ss;
    }
    for t in treatments {
        if !t.is_empty() {
            df_within += t.len() as f64 - 1.0;
        }
    }

    if df_within <= 0.0 {
        return DunnettResult {
            statistic: vec![f64::NAN; k],
            pvalue: vec![f64::NAN; k],
        };
    }

    let mse = ss_within / df_within;

    // Compute all test statistics first
    let mut stats = Vec::with_capacity(k);
    let mut sample_sizes = Vec::with_capacity(k);

    for (mean_t, n_t, _) in &treatment_stats {
        if n_t.is_nan() || *n_t == 0.0 {
            stats.push(f64::NAN);
            sample_sizes.push(0.0);
        } else {
            let mean_diff = mean_t - mean_c;
            let se = (mse * (1.0 / n_t + 1.0 / n_c)).sqrt();
            if se > 0.0 {
                stats.push(mean_diff / se);
                sample_sizes.push(*n_t);
            } else {
                stats.push(f64::NAN);
                sample_sizes.push(0.0);
            }
        }
    }

    // Compute correlation for Dunnett's test
    // For equal sample sizes: rho = n_c / (n + n_c)
    // For unequal: use harmonic mean approximation or average
    let avg_n = sample_sizes.iter().filter(|&&n| n > 0.0).sum::<f64>()
        / sample_sizes.iter().filter(|&&n| n > 0.0).count().max(1) as f64;
    let rho = if avg_n > 0.0 {
        n_c / (avg_n + n_c)
    } else {
        0.5
    };

    // Compute p-values using multivariate t distribution
    let pvals: Vec<f64> = stats
        .iter()
        .map(|&t| {
            if t.is_nan() {
                f64::NAN
            } else {
                dunnett_pvalue_mvt(t.abs(), k, df_within, rho)
            }
        })
        .collect();

    DunnettResult {
        statistic: stats,
        pvalue: pvals,
    }
}

/// Dunnett's test with alternative hypothesis specification.
///
/// Matches `scipy.stats.dunnett(*samples, control=control, alternative=alternative)`.
///
/// # Arguments
/// * `treatments` - Slice of sample arrays for treatment groups
/// * `control` - Sample array for the control group
/// * `alternative` - "two-sided", "less", or "greater"
pub fn dunnett_alternative(
    treatments: &[&[f64]],
    control: &[f64],
    alternative: &str,
) -> DunnettResult {
    let k = treatments.len();
    if k == 0 || control.is_empty() {
        return DunnettResult {
            statistic: vec![],
            pvalue: vec![],
        };
    }

    // Control group statistics
    let n_c = control.len() as f64;
    let mean_c: f64 = control.iter().sum::<f64>() / n_c;

    // Compute pooled variance (MSE)
    let mut ss_within = control.iter().map(|&x| (x - mean_c).powi(2)).sum::<f64>();
    let mut df_within = n_c - 1.0;

    let treatment_stats: Vec<(f64, f64, f64)> = treatments
        .iter()
        .map(|t| {
            if t.is_empty() {
                (f64::NAN, 0.0, 0.0)
            } else {
                let n = t.len() as f64;
                let mean = t.iter().sum::<f64>() / n;
                let ss: f64 = t.iter().map(|&x| (x - mean).powi(2)).sum();
                (mean, n, ss)
            }
        })
        .collect();

    for (_, _, ss) in &treatment_stats {
        ss_within += ss;
    }
    for t in treatments {
        if !t.is_empty() {
            df_within += t.len() as f64 - 1.0;
        }
    }

    if df_within <= 0.0 {
        return DunnettResult {
            statistic: vec![f64::NAN; k],
            pvalue: vec![f64::NAN; k],
        };
    }

    let mse = ss_within / df_within;
    let tdist = StudentT::new(df_within);

    let mut stats = Vec::with_capacity(k);
    let mut pvals = Vec::with_capacity(k);

    for (mean_t, n_t, _) in &treatment_stats {
        if n_t.is_nan() || *n_t == 0.0 {
            stats.push(f64::NAN);
            pvals.push(f64::NAN);
            continue;
        }

        let mean_diff = mean_t - mean_c;
        let se = (mse * (1.0 / n_t + 1.0 / n_c)).sqrt();

        if se > 0.0 {
            let t = mean_diff / se;
            stats.push(t);

            let p_raw = match alternative {
                "less" => tdist.cdf(t),
                "greater" => 1.0 - tdist.cdf(t),
                _ => 2.0 * (1.0 - tdist.cdf(t.abs())),
            };
            pvals.push((p_raw * k as f64).min(1.0));
        } else {
            stats.push(f64::NAN);
            pvals.push(f64::NAN);
        }
    }

    DunnettResult {
        statistic: stats,
        pvalue: pvals,
    }
}

/// Levene's test for equal variances using median-centered absolute deviations.
///
/// Matches the robust default behavior of `scipy.stats.levene(*groups)`.
/// When `true`, [`levene`] builds its per-group `|x − median|` deviation vectors serially (the ORIG
/// behaviour); default `false` fans the median+deviation construction across cores over the independent
/// groups. Byte-identical either way. `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static LEVENE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn levene(groups: &[&[f64]]) -> VarianceTestResult {
    if groups.len() < 2
        || groups.iter().any(|group| group.len() < 2)
        || groups.iter().any(|g| g.iter().any(|v| v.is_nan()))
    {
        return invalid_variance_test_result();
    }

    // Each group's deviation vector is `|x − median(group)|`; the per-group `median` is an independent,
    // sort/select-dominated O(n) reduction that dominates levene (the downstream SS scans are O(n)).
    // Groups are INDEPENDENT, so build the deviations across cores (chunked over groups, collected in
    // group order). BYTE-IDENTICAL to the serial map: each group's `center`/`|x−center|` is unchanged;
    // only the owning core differs. Gated on total work / group count; `LEVENE_FORCE_SERIAL` for A/B.
    let build = |group: &[f64]| -> Vec<f64> {
        let center = sample_median(group);
        group.iter().map(|&x| (x - center).abs()).collect()
    };
    let total: usize = groups.iter().map(|g| g.len()).sum();
    let deviations: Vec<Vec<f64>> = if LEVENE_FORCE_SERIAL
        .load(std::sync::atomic::Ordering::Relaxed)
        || total < (1 << 18)
        || groups.len() < 2
    {
        groups.iter().map(|group| build(group)).collect()
    } else {
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(groups.len());
        let chunk = groups.len().div_ceil(nthreads);
        let build = &build;
        std::thread::scope(|scope| {
            groups
                .chunks(chunk)
                .map(|gc| {
                    scope.spawn(move || gc.iter().map(|g| build(g)).collect::<Vec<Vec<f64>>>())
                })
                .collect::<Vec<_>>()
                .into_iter()
                .flat_map(|h| h.join().expect("levene worker panicked"))
                .collect()
        })
    };

    let k = deviations.len() as f64;
    let n_total: usize = deviations.iter().map(Vec::len).sum();
    let df_within = n_total as f64 - k;
    if df_within <= 0.0 {
        return invalid_variance_test_result();
    }

    let grand_mean = deviations.iter().flatten().sum::<f64>() / n_total as f64;

    let ss_between: f64 = deviations
        .iter()
        .map(|group| {
            let mean = sample_mean(group);
            group.len() as f64 * (mean - grand_mean).powi(2)
        })
        .sum();

    let ss_within: f64 = deviations
        .iter()
        .map(|group| {
            let mean = sample_mean(group);
            group.iter().map(|&x| (x - mean).powi(2)).sum::<f64>()
        })
        .sum();

    if ss_within == 0.0 {
        if ss_between == 0.0 {
            return invalid_variance_test_result();
        }
        return VarianceTestResult {
            statistic: f64::INFINITY,
            pvalue: 0.0,
        };
    }

    let df_between = k - 1.0;
    let w = (df_within / df_between) * (ss_between / ss_within);
    let pvalue = FDistribution::new(df_between, df_within)
        .sf(w)
        .clamp(0.0, 1.0);
    VarianceTestResult {
        statistic: w,
        pvalue,
    }
}

/// Levene's test with nan_policy parameter.
///
/// Matches `scipy.stats.levene(*groups, nan_policy=...)`.
///
/// * `nan_policy` - "propagate" (default), "omit", or "raise"
pub fn levene_with_nan_policy(
    groups: &[&[f64]],
    nan_policy: Option<&str>,
) -> Result<VarianceTestResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;

    let has_nan = groups.iter().any(|g| g.iter().any(|v| v.is_nan()));

    if has_nan {
        match nan_policy {
            "raise" => {
                return Err(StatsError::InvalidArgument(
                    "input contains NaN values".to_string(),
                ));
            }
            "propagate" => {
                return Ok(invalid_variance_test_result());
            }
            "omit" => {
                let cleaned: Vec<Vec<f64>> = groups
                    .iter()
                    .map(|g| g.iter().copied().filter(|v| !v.is_nan()).collect())
                    .collect();
                let cleaned_refs: Vec<&[f64]> = cleaned.iter().map(|v| v.as_slice()).collect();
                return Ok(levene(&cleaned_refs));
            }
            _ => {}
        }
    }

    Ok(levene(groups))
}

/// Bartlett's test for equal variances under normality.
///
/// Matches `scipy.stats.bartlett(*groups)`.
pub fn bartlett(groups: &[&[f64]]) -> VarianceTestResult {
    if groups.len() < 2
        || groups.iter().any(|group| group.len() < 2)
        || groups.iter().any(|g| g.iter().any(|v| v.is_nan()))
    {
        return invalid_variance_test_result();
    }

    let k = groups.len() as f64;
    let n_total: usize = groups.iter().map(|group| group.len()).sum();
    let df = n_total as f64 - k;
    if df <= 0.0 {
        return invalid_variance_test_result();
    }

    let variances: Vec<f64> = groups.iter().map(|group| sample_variance(group)).collect();
    if variances
        .iter()
        .any(|variance| !variance.is_finite() || *variance < 0.0)
    {
        return invalid_variance_test_result();
    }

    let pooled_variance: f64 = groups
        .iter()
        .zip(&variances)
        .map(|(group, variance)| (group.len() as f64 - 1.0) * variance)
        .sum::<f64>()
        / df;

    if pooled_variance <= 0.0 {
        if variances.iter().all(|variance| *variance == 0.0) {
            return invalid_variance_test_result();
        }
        return VarianceTestResult {
            statistic: f64::INFINITY,
            pvalue: 0.0,
        };
    }

    let weighted_log_variance_sum: f64 = groups
        .iter()
        .zip(&variances)
        .map(|(group, variance)| (group.len() as f64 - 1.0) * variance.ln())
        .sum();

    let correction = 1.0
        + (groups
            .iter()
            .map(|group| 1.0 / (group.len() as f64 - 1.0))
            .sum::<f64>()
            - 1.0 / df)
            / (3.0 * (k - 1.0));

    let statistic = (df * pooled_variance.ln() - weighted_log_variance_sum) / correction;
    let pvalue = ChiSquared::new(k - 1.0).sf(statistic).clamp(0.0, 1.0);
    VarianceTestResult { statistic, pvalue }
}

/// Bartlett's test with nan_policy parameter.
///
/// Matches `scipy.stats.bartlett(*groups, nan_policy=...)`.
///
/// * `nan_policy` - "propagate" (default), "omit", or "raise"
pub fn bartlett_with_nan_policy(
    groups: &[&[f64]],
    nan_policy: Option<&str>,
) -> Result<VarianceTestResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;

    let has_nan = groups.iter().any(|g| g.iter().any(|v| v.is_nan()));

    if has_nan {
        match nan_policy {
            "raise" => {
                return Err(StatsError::InvalidArgument(
                    "input contains NaN values".to_string(),
                ));
            }
            "propagate" => {
                return Ok(invalid_variance_test_result());
            }
            "omit" => {
                let cleaned: Vec<Vec<f64>> = groups
                    .iter()
                    .map(|g| g.iter().copied().filter(|v| !v.is_nan()).collect())
                    .collect();
                let cleaned_refs: Vec<&[f64]> = cleaned.iter().map(|v| v.as_slice()).collect();
                return Ok(bartlett(&cleaned_refs));
            }
            _ => {}
        }
    }

    Ok(bartlett(groups))
}

/// When `true`, [`friedmanchisquare`] allocates a fresh per-block scratch `Vec` (the ORIG
/// behaviour); when `false` (default) it reuses one hoisted buffer. Byte-identical either
/// way. For the same-binary A/B perf gate.
#[doc(hidden)]
pub static FRIEDMAN_ALLOC_IN_LOOP: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Friedman test for repeated measures (non-parametric).
///
/// Tests H0: all treatments have the same effect. Non-parametric alternative
/// to repeated-measures ANOVA. Each group must have the same length.
///
/// Matches `scipy.stats.friedmanchisquare(*groups)`.
pub fn friedmanchisquare(groups: &[&[f64]]) -> TtestResult {
    let k = groups.len();
    if k < 3 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    let n = groups[0].len();
    if n < 2
        || groups
            .iter()
            .any(|g| g.len() != n || g.iter().any(|v| v.is_nan()))
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    // Rank within each block (row) with tie handling (average ranks)
    // and accumulate Σ(t³-t) over tie groups for scipy's tie correction.
    let mut rank_sums = vec![0.0; k];
    let mut tie_sum = 0.0_f64;
    // Per-block (value, group) scratch, hoisted out of the block loop and cleared+refilled
    // each block, so the n blocks share ONE k-element allocation instead of mallocing a
    // fresh Vec per block (n allocs -> 1). BYTE-IDENTICAL: identical contents, sort and
    // rank accumulation each block. frankenscipy-26zjo. The FRIEDMAN_ALLOC_IN_LOOP toggle
    // restores the per-block alloc for the same-binary A/B gate.
    let alloc_in_loop = FRIEDMAN_ALLOC_IN_LOOP.load(std::sync::atomic::Ordering::Relaxed);
    let mut scratch: Vec<(f64, usize)> = Vec::with_capacity(k);
    for block in 0..n {
        let mut owned;
        let vals: &mut Vec<(f64, usize)> = if alloc_in_loop {
            owned = Vec::with_capacity(k);
            &mut owned
        } else {
            scratch.clear();
            &mut scratch
        };
        for (j, g) in groups.iter().enumerate() {
            vals.push((g[block], j));
        }
        vals.sort_by(|a, b| a.0.total_cmp(&b.0));

        // Average ranks for ties
        let mut i = 0;
        while i < k {
            let mut j = i + 1;
            while j < k && vals[j].0 == vals[i].0 {
                j += 1;
            }
            // Positions i..j all tied — average rank
            let avg_rank = (i..j).map(|r| r as f64 + 1.0).sum::<f64>() / (j - i) as f64;
            for tied in &vals[i..j] {
                rank_sums[tied.1] += avg_rank;
            }
            let t = (j - i) as f64;
            if t > 1.0 {
                tie_sum += t * t * t - t;
            }
            i = j;
        }
    }

    // Friedman statistic: χ² = 12/(nk(k+1)) Σ R_j² - 3n(k+1), then
    // divided by scipy's tie-correction factor (1 - Σ(t³-t)/(n*k*(k²-1))).
    let kf = k as f64;
    let nf = n as f64;
    let sum_sq: f64 = rank_sums.iter().map(|&r| r * r).sum();
    let chi2_uncorrected = 12.0 / (nf * kf * (kf + 1.0)) * sum_sq - 3.0 * nf * (kf + 1.0);
    let denom = nf * kf * (kf * kf - 1.0);
    let c = if denom > 0.0 {
        1.0 - tie_sum / denom
    } else {
        1.0
    };
    let chi2 = if c > 0.0 {
        chi2_uncorrected / c
    } else {
        chi2_uncorrected
    };

    let df = kf - 1.0;
    let dist = ChiSquared::new(df);
    let pvalue = (1.0 - dist.cdf(chi2)).clamp(0.0, 1.0);

    TtestResult {
        statistic: chi2,
        pvalue,
        df,
    }
}

/// When `true`, [`fligner`] builds its per-group median-centered scores serially (the ORIG behaviour);
/// default `false` fans the sort+median+deviation build across cores over the independent groups.
/// Byte-identical either way. `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static FLIGNER_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// When `true`, [`fligner`] maps its rank→normal-quantile scores serially (the ORIG behaviour);
/// default `false` fans the compute-bound `standard_normal_ppf` map across cores via the
/// order-preserving `par_continuous_map`. Byte-identical either way. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static FLIGNER_PPF_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Fligner-Killeen test for equal variances.
///
/// A robust non-parametric test that uses the chi-squared distribution
/// of median-centered rank scores.
///
/// Matches `scipy.stats.fligner(*groups)`.
///
/// When [`FLIGNER_FORCE_SERIAL`] is `true`, the per-group median-centered scores are built serially
/// (the ORIG behaviour); default `false` fans the sort+median+deviation build across cores over the
/// independent groups. Byte-identical.
pub fn fligner(groups: &[&[f64]]) -> VarianceTestResult {
    if groups.len() < 2
        || groups.iter().any(|g| g.len() < 2)
        || groups.iter().any(|g| g.iter().any(|v| v.is_nan()))
    {
        return invalid_variance_test_result();
    }

    let k = groups.len();

    // Compute median-centered scores (`|x − median(group)|`). Each group's `median` is a
    // sort-dominated O(n log n) reduction that dominates fligner (the downstream rankdata + ppf are
    // O(n)/O(n log n) over the flattened scores, done once), and the groups are INDEPENDENT. Build the
    // per-group deviations across cores (chunked over groups) then flatten in GROUP ORDER. BYTE-IDENTICAL
    // to the serial extend loop: `all_scores` is the same concatenation, so the downstream ranks/scores
    // are unchanged. `FLIGNER_FORCE_SERIAL` restores the serial build for A/B.
    let group_sizes: Vec<usize> = groups.iter().map(|g| g.len()).collect();
    let build = |group: &[f64]| -> Vec<f64> {
        let mut sorted = group.to_vec();
        sorted.sort_unstable_by(|a, b| a.total_cmp(b));
        let median = quantile_sorted(&sorted, 0.5);
        group.iter().map(|&x| (x - median).abs()).collect()
    };
    let total: usize = group_sizes.iter().sum();
    let all_scores: Vec<f64> = if FLIGNER_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
        || total < (1 << 18)
        || groups.len() < 2
    {
        let mut v = Vec::with_capacity(total);
        for group in groups {
            v.extend_from_slice(&build(group));
        }
        v
    } else {
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(groups.len());
        let chunk = groups.len().div_ceil(nthreads);
        let build = &build;
        std::thread::scope(|scope| {
            groups
                .chunks(chunk)
                .map(|gc| {
                    scope.spawn(move || {
                        let mut v: Vec<f64> = Vec::new();
                        for g in gc {
                            v.extend_from_slice(&build(g));
                        }
                        v
                    })
                })
                .collect::<Vec<_>>()
                .into_iter()
                .flat_map(|h| h.join().expect("fligner worker panicked"))
                .collect()
        })
    };

    let n_total = all_scores.len();
    // Rank all scores using average ranks for ties (matches scipy.stats.rankdata).
    let ranks = rankdata_average(&all_scores);

    // Transform ranks to normal quantile scores. `standard_normal_ppf` (inverse normal CDF) is a heavy
    // per-element transcendental → COMPUTE-bound, and each output is a pure function of its index. Fan
    // the map across cores via the order-preserving `par_continuous_map` — BYTE-IDENTICAL to the serial
    // `map(ppf).collect()` (same values in index order). `FLIGNER_PPF_FORCE_SERIAL` restores the serial
    // map for the same-binary A/B gate.
    let nf = n_total as f64;
    let scores: Vec<f64> = if FLIGNER_PPF_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        ranks
            .iter()
            .map(|&r| standard_normal_ppf((1.0 + r / (nf + 1.0)) / 2.0))
            .collect()
    } else {
        par_continuous_map(&ranks, |r| {
            standard_normal_ppf((1.0 + r / (nf + 1.0)) / 2.0)
        })
    };

    // Compute group means of scores
    let grand_mean = scores.iter().sum::<f64>() / nf;
    let mut offset = 0;
    let mut numerator = 0.0;
    let mut denominator = 0.0;
    for &ni in &group_sizes {
        let group_mean = scores[offset..offset + ni].iter().sum::<f64>() / ni as f64;
        numerator += ni as f64 * (group_mean - grand_mean).powi(2);
        for score in scores.iter().skip(offset).take(ni) {
            denominator += (score - grand_mean).powi(2);
        }
        offset += ni;
    }

    // scipy normalises by var(a, ddof=1) = sum_sq_dev / (N-1), so the
    // multiplier here is (N - 1), not (N - k).
    let statistic = if denominator > 0.0 {
        (nf - 1.0) * numerator / denominator
    } else {
        f64::NAN
    };

    let df = (k - 1) as f64;
    let dist = ChiSquared::new(df);
    let pvalue = (1.0 - dist.cdf(statistic)).clamp(0.0, 1.0);

    VarianceTestResult { statistic, pvalue }
}

/// Fligner-Killeen test with nan_policy parameter.
///
/// Matches `scipy.stats.fligner(*groups, nan_policy=...)`.
///
/// * `nan_policy` - "propagate" (default), "omit", or "raise"
pub fn fligner_with_nan_policy(
    groups: &[&[f64]],
    nan_policy: Option<&str>,
) -> Result<VarianceTestResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;

    let has_nan = groups.iter().any(|g| g.iter().any(|v| v.is_nan()));

    if has_nan {
        match nan_policy {
            "raise" => {
                return Err(StatsError::InvalidArgument(
                    "input contains NaN values".to_string(),
                ));
            }
            "propagate" => {
                return Ok(invalid_variance_test_result());
            }
            "omit" => {
                let cleaned: Vec<Vec<f64>> = groups
                    .iter()
                    .map(|g| g.iter().copied().filter(|v| !v.is_nan()).collect())
                    .collect();
                let cleaned_refs: Vec<&[f64]> = cleaned.iter().map(|v| v.as_slice()).collect();
                return Ok(fligner(&cleaned_refs));
            }
            _ => {}
        }
    }

    Ok(fligner(groups))
}

/// Mood's test for equal scale parameters.
///
/// Tests H0: two samples have equal scale. Non-parametric.
///
/// Matches `scipy.stats.mood(x, y)`.
pub fn mood(x: &[f64], y: &[f64]) -> TtestResult {
    let m = x.len();
    let n = y.len();
    let total = m + n;
    if m == 0 || n == 0 || total < 3 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan())
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let mf = m as f64;
    let nf = n as f64;
    let totalf = total as f64;
    let center = (totalf + 1.0) / 2.0;
    let sum_i = |u: f64| u * (u + 1.0) / 2.0;
    let sum_i2 = |u: f64| u * (u + 1.0) * (2.0 * u + 1.0) / 6.0;

    // Pool observations and aggregate equal-valued groups so the statistic and
    // variance follow SciPy's tie-aware Mielke correction.
    let mut pooled: Vec<(f64, bool)> = x
        .iter()
        .map(|&v| (v, true))
        .chain(y.iter().map(|&v| (v, false)))
        .collect();
    pooled.sort_by(|a, b| a.0.total_cmp(&b.0));

    let mut cumulative = 0.0;
    let mut statistic_sum = 0.0;
    let mut tie_variance_sum = 0.0;
    let mut i = 0;
    while i < pooled.len() {
        let value = pooled[i].0;
        let start = cumulative;
        let mut j = i;
        let mut x_count = 0.0;
        while j < pooled.len() && pooled[j].0 == value {
            if pooled[j].1 {
                x_count += 1.0;
            }
            j += 1;
        }

        let count = (j - i) as f64;
        cumulative += count;
        let lo = start + 1.0;
        let hi = cumulative;
        let rank_sum = sum_i(hi) - sum_i(lo - 1.0);
        let rank_sq_sum = sum_i2(hi) - sum_i2(lo - 1.0);
        let phi = (rank_sq_sum - 2.0 * center * rank_sum + count * center * center) / count;
        statistic_sum += x_count * phi;

        tie_variance_sum += count
            * (count * count - 1.0)
            * (count * count - 4.0 + 15.0 * (totalf - cumulative - start).powi(2));

        i = j;
    }

    let e_m = mf * (totalf * totalf - 1.0) / 12.0;
    let var_m = mf * nf * (totalf + 1.0) * (totalf * totalf - 4.0) / 180.0
        - mf * nf * tie_variance_sum / (180.0 * totalf * (totalf - 1.0));

    if !var_m.is_finite() || var_m <= 0.0 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let z = (statistic_sum - e_m) / var_m.sqrt();
    let norm = Normal::standard();
    let pvalue = (2.0 * ContinuousDistribution::sf(&norm, z.abs())).clamp(0.0, 1.0);

    TtestResult {
        statistic: z,
        pvalue,
        df: f64::NAN, // Non-parametric, no df
    }
}

/// Mood's scale test with alternative hypothesis.
///
/// Matches `scipy.stats.mood(x, y, alternative=...)`.
///
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn mood_alternative(x: &[f64], y: &[f64], alternative: &str) -> TtestResult {
    let m = x.len();
    let n = y.len();
    let total = m + n;
    if m == 0 || n == 0 || total < 3 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan())
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let mf = m as f64;
    let nf = n as f64;
    let totalf = total as f64;
    let center = (totalf + 1.0) / 2.0;
    let sum_i = |u: f64| u * (u + 1.0) / 2.0;
    let sum_i2 = |u: f64| u * (u + 1.0) * (2.0 * u + 1.0) / 6.0;

    let mut pooled: Vec<(f64, bool)> = x
        .iter()
        .map(|&v| (v, true))
        .chain(y.iter().map(|&v| (v, false)))
        .collect();
    pooled.sort_by(|a, b| a.0.total_cmp(&b.0));

    let mut cumulative = 0.0;
    let mut statistic_sum = 0.0;
    let mut tie_variance_sum = 0.0;
    let mut i = 0;
    while i < pooled.len() {
        let value = pooled[i].0;
        let start = cumulative;
        let mut j = i;
        let mut x_count = 0.0;
        while j < pooled.len() && pooled[j].0 == value {
            if pooled[j].1 {
                x_count += 1.0;
            }
            j += 1;
        }

        let count = (j - i) as f64;
        cumulative += count;
        let lo = start + 1.0;
        let hi = cumulative;
        let rank_sum = sum_i(hi) - sum_i(lo - 1.0);
        let rank_sq_sum = sum_i2(hi) - sum_i2(lo - 1.0);
        let phi = (rank_sq_sum - 2.0 * center * rank_sum + count * center * center) / count;
        statistic_sum += x_count * phi;

        tie_variance_sum += count
            * (count * count - 1.0)
            * (count * count - 4.0 + 15.0 * (totalf - cumulative - start).powi(2));

        i = j;
    }

    let e_m = mf * (totalf * totalf - 1.0) / 12.0;
    let var_m = mf * nf * (totalf + 1.0) * (totalf * totalf - 4.0) / 180.0
        - mf * nf * tie_variance_sum / (180.0 * totalf * (totalf - 1.0));

    if !var_m.is_finite() || var_m <= 0.0 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let z = (statistic_sum - e_m) / var_m.sqrt();
    let pvalue = normal_alternative_pvalue(z, alternative).clamp(0.0, 1.0);

    TtestResult {
        statistic: z,
        pvalue,
        df: f64::NAN,
    }
}

/// Mood's median test for equal medians across groups.
///
/// Tests H0: all groups have the same median.
///
/// Matches `scipy.stats.median_test(*groups)`.
pub fn median_test(groups: &[&[f64]]) -> TtestResult {
    if groups.len() < 2
        || groups
            .iter()
            .any(|g| g.is_empty() || g.iter().any(|v| v.is_nan()))
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    // Pool all data and find grand median
    let mut all_data: Vec<f64> = groups.iter().flat_map(|g| g.iter().copied()).collect();
    all_data.sort_unstable_by(|a, b| a.total_cmp(b));
    let grand_median = quantile_sorted(&all_data, 0.5);

    // Count observations above/below median per group
    let k = groups.len();
    let mut above = vec![0.0; k];
    let mut below = vec![0.0; k];
    for (i, group) in groups.iter().enumerate() {
        for &val in *group {
            if val > grand_median {
                above[i] += 1.0;
            } else {
                below[i] += 1.0;
            }
        }
    }

    // Chi-squared test on the 2×k contingency table
    let table = vec![above, below];
    let result = chi2_contingency(&table, true);
    TtestResult {
        statistic: result.statistic,
        pvalue: result.pvalue,
        df: (k - 1) as f64,
    }
}

/// Ansari-Bradley test for equal scale parameters.
///
/// Matches the core behavior of `scipy.stats.ansari(x, y)` for the
/// default two-sided alternative.
///
/// Delegates to `ansari_alternative(x, y, "two-sided")` so the
/// exact-distribution path (n + m < 55, no ties — see
/// [frankenscipy-1vlpt]) and the normal-tail fallback are shared
/// across both entry points.
pub fn ansari(x: &[f64], y: &[f64]) -> TtestResult {
    ansari_alternative(x, y, "two-sided")
}

/// Ansari-Bradley scale test with alternative hypothesis.
///
/// Matches `scipy.stats.ansari(x, y, alternative=...)`.
///
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn ansari_alternative(x: &[f64], y: &[f64], alternative: &str) -> TtestResult {
    let n = x.len();
    let m = y.len();
    if n < 1 || m < 1 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let total = n + m;
    let mut pooled = Vec::with_capacity(total);
    pooled.extend_from_slice(x);
    pooled.extend_from_slice(y);
    let ranks = rankdata_average(&pooled);
    let total_f = total as f64;
    let symranks: Vec<f64> = ranks.iter().map(|&r| r.min(total_f - r + 1.0)).collect();
    let statistic: f64 = symranks[..n].iter().sum();

    let repeats = {
        let mut sorted = pooled.clone();
        sorted.sort_unstable_by(|a, b| a.total_cmp(b));
        sorted.windows(2).any(|w| w[0].total_cmp(&w[1]).is_eq())
    };

    let n_f = n as f64;
    let m_f = m as f64;
    let mean = if total % 2 == 1 {
        n_f * (total_f + 1.0).powi(2) / (4.0 * total_f)
    } else {
        n_f * (total_f + 2.0) / 4.0
    };

    let variance = if repeats {
        let fac: f64 = symranks.iter().map(|r| r * r).sum();
        if total % 2 == 1 {
            m_f * n_f * (16.0 * total_f * fac - (total_f + 1.0).powi(4))
                / (16.0 * total_f.powi(2) * (total_f - 1.0))
        } else {
            m_f * n_f * (16.0 * fac - total_f * (total_f + 2.0).powi(2))
                / (16.0 * total_f * (total_f - 1.0))
        }
    } else if total % 2 == 1 {
        n_f * m_f * (total_f + 1.0) * (3.0 + total_f.powi(2)) / (48.0 * total_f.powi(2))
    } else {
        m_f * n_f * (total_f + 2.0) * (total_f - 2.0) / (48.0 * (total_f - 1.0))
    };

    // scipy uses the exact distribution when n < 55, m < 55, and there
    // are no ties in the pooled data. For ties or larger samples it
    // falls through to the normal-tail approximation.
    let exact_path = !repeats && n < 55 && m < 55;
    let pvalue = if exact_path {
        ansari_exact_pvalue(statistic, n, total, alternative)
    } else {
        if variance <= 0.0 {
            return TtestResult {
                statistic,
                pvalue: 1.0,
                df: f64::NAN,
            };
        }
        let z = (mean - statistic) / variance.sqrt();
        normal_alternative_pvalue(z, alternative).clamp(0.0, 1.0)
    };

    TtestResult {
        statistic,
        pvalue,
        df: f64::NAN,
    }
}

/// Exact p-value for the Ansari-Bradley test under H0 (random allocation
/// of n, m samples to a pooled rank stream of length N = n + m, no ties).
///
/// Builds the generating function product
///   G(t, x) = ∏_{i=1..N} (1 + x · t^{s_i})    where s_i = min(i, N+1−i)
/// via 2-D dynamic programming and reads off the count for choosing
/// exactly n out of N (the AB statistic conditioning).
///
/// Matches the `_ABW` exact distribution scipy.stats.ansari uses for
/// n + m < 55 with no ties — see scipy/_morestats.py:`ansari` exact
/// branch.
fn ansari_exact_pvalue(stat: f64, n: usize, total: usize, alternative: &str) -> f64 {
    if total == 0 {
        return f64::NAN;
    }
    // Symmetric ranks: s_i = min(i, N+1-i) for i = 1..=N.
    let mut symranks = Vec::with_capacity(total);
    for i in 1..=total {
        symranks.push(i.min(total + 1 - i));
    }
    // DP: dp[j][k] = number of ways to choose j elements with sum k.
    // max_k upper-bounded by sum of n largest symranks (for n=m=N/2 ≈ N²/8).
    let max_sum: usize = {
        let mut sorted = symranks.clone();
        sorted.sort_unstable_by(|a, b| b.cmp(a));
        sorted.iter().take(n).sum()
    };
    let mut dp = vec![vec![0u128; max_sum + 1]; n + 1];
    dp[0][0] = 1;
    for &s in &symranks {
        // Iterate j and k in reverse so each item is used at most once
        // (knapsack-style 0/1 selection).
        for j in (1..=n).rev() {
            for k in s..=max_sum {
                dp[j][k] = dp[j][k].saturating_add(dp[j - 1][k - s]);
            }
        }
    }
    let total_count: u128 = dp[n].iter().sum();
    if total_count == 0 {
        return f64::NAN;
    }
    let total_f = total_count as f64;
    let stat_int = stat.round() as usize;
    if stat_int > max_sum {
        return f64::NAN;
    }
    // CDF/SF on the rounded integer statistic. scipy uses:
    //   cdf(k) = P(AB ≤ k) = sum freqs[..=k] / total
    //   sf(k)  = P(AB ≥ k) = sum freqs[k..] / total
    let cdf: u128 = dp[n][..=stat_int].iter().sum();
    let sf: u128 = dp[n][stat_int..].iter().sum();
    let cdf_f = cdf as f64 / total_f;
    let sf_f = sf as f64 / total_f;
    let pval = match alternative {
        "two-sided" => (2.0 * cdf_f.min(sf_f)).min(1.0),
        "greater" => cdf_f, // AB statistic is _smaller_ when scale ratio is larger
        _ => sf_f,          // "less"
    };
    pval.clamp(0.0, 1.0)
}

///
/// Matches `scipy.stats.mannwhitneyu(x, y, alternative='two-sided')`.
///
/// Non-parametric test: H0: distributions of x and y are equal.
/// Uses normal approximation for p-value (valid for n > 20).
/// Exact null distribution of the Mann-Whitney U statistic for sample sizes
/// (a, b): `counts[u]` = number of combined arrangements with U == u, for
/// u = 0..=a*b. The distribution is symmetric and depends only on the multiset
/// {a, b}, so the caller passes a = min(n1, n2). Recurrence (Mann-Whitney 1947):
/// f(i, j; U) = f(i-1, j; U-j) + f(i, j-1; U), built column-by-column in f64.
fn mwu_exact_counts(a: usize, b: usize) -> Vec<f64> {
    let mut prev: Vec<Vec<f64>> = vec![Vec::new(); a + 1]; // f(i, j-1)
    for j in 0..=b {
        let mut cur: Vec<Vec<f64>> = vec![Vec::new(); a + 1];
        for i in 0..=a {
            let arr = if i == 0 || j == 0 {
                let mut base = vec![0.0; i * j + 1];
                base[0] = 1.0;
                base
            } else {
                let mut acc = vec![0.0; i * j + 1];
                for (u, &c) in cur[i - 1].iter().enumerate() {
                    if c != 0.0 {
                        acc[u + j] += c; // shift f(i-1, j) up by j
                    }
                }
                for (u, &c) in prev[i].iter().enumerate() {
                    if c != 0.0 {
                        acc[u] += c; // f(i, j-1)
                    }
                }
                acc
            };
            cur[i] = arr;
        }
        prev = cur;
    }
    std::mem::take(&mut prev[a])
}

/// scipy's exact Mann-Whitney p-value (`method='exact'`, used when there are no
/// ties and at least one sample is small): from the exact U distribution,
/// `less` → P(U ≤ U1), `greater` → P(U ≥ U1), two-sided → 2·min(cdf, sf) clipped.
/// U1 is the statistic for the first sample. frankenscipy-vwmup
fn mwu_exact_pvalue(u1: f64, n1: usize, n2: usize, alternative: &str) -> f64 {
    let counts = mwu_exact_counts(n1.min(n2), n1.max(n2));
    let total: f64 = counts.iter().sum();
    let ui = (u1.round() as usize).min(counts.len() - 1);
    let cdf: f64 = counts[..=ui].iter().sum::<f64>() / total; // P(U <= U1)
    let sf: f64 = counts[ui..].iter().sum::<f64>() / total; // P(U >= U1)
    match alternative {
        "less" => cdf,
        "greater" => sf,
        _ => (2.0 * cdf.min(sf)).min(1.0),
    }
}

/// scipy `method='auto'` uses the exact Mann-Whitney null distribution when
/// there are no ties and the smaller sample has ≤ 8 observations. We additionally
/// cap n1·n2 so the O((n1·n2)²) count DP stays cheap; beyond the cap (only
/// reachable for a tiny sample paired with a very large one) the asymptotic
/// approximation is already excellent. frankenscipy-vwmup
fn mwu_use_exact(n1: usize, n2: usize, no_ties: bool) -> bool {
    no_ties && n1.min(n2) <= 8 && n1 * n2 <= 20_000
}

pub fn mannwhitneyu(x: &[f64], y: &[f64]) -> TtestResult {
    if x.len() < 2 || y.len() < 2 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let n1 = x.len();
    let n2 = y.len();
    let n1f = n1 as f64;
    let n2f = n2 as f64;

    // Combine and rank all observations
    let mut combined: Vec<(f64, usize)> = Vec::with_capacity(n1 + n2);
    for &v in x {
        combined.push((v, 0)); // group 0 = x
    }
    for &v in y {
        combined.push((v, 1)); // group 1 = y
    }

    let values: Vec<f64> = combined.iter().map(|&(v, _)| v).collect();
    // Ranks AND the tie sum from ONE pass, replacing a `ranks.clone()` + second sort
    // below (`frankenscipy-921i0`). BYTE-IDENTICAL: the old loop grouped sorted RANKS
    // within 1e-12, a tolerance that cannot bite because distinct average-rank groups
    // differ by at least 0.5; ranks are monotone in values, so the groups and their
    // ascending order are exactly those of the ranking pass.
    let (ranks, tie_correction) = rankdata_ties_with_tie_sum(&values, RankTieMethod::Average);

    // U statistic: sum of ranks of x - n1*(n1+1)/2
    let rank_sum_x: f64 = ranks
        .iter()
        .zip(combined.iter())
        .filter(|(_, (_, group))| *group == 0)
        .map(|(r, _)| *r)
        .sum();

    let u1 = rank_sum_x - n1f * (n1f + 1.0) / 2.0;
    let u2 = n1f * n2f - u1;
    let u = u1.min(u2); // two-sided: use smaller U

    // Normal approximation. Per br-nknp: include tie correction in
    // sigma and continuity correction (|U - mu| - 0.5) on the z-score
    // to match scipy.stats.mannwhitneyu defaults
    // (use_continuity=True, method='asymptotic').
    let mu = n1f * n2f / 2.0;
    let n = n1f + n2f;

    // Tie correction: sum_t (t^3 - t) over each tied rank group.
    // Implemented by counting equal-rank groups in the sorted ranks.
    // `tie_correction` came back from the ranking pass above.

    // scipy returns the U statistic for the first sample (U1), not min(U1, U2).
    // For an untied small sample it uses the exact null distribution instead of
    // the normal approximation. frankenscipy-vwmup
    if mwu_use_exact(n1, n2, tie_correction == 0.0) {
        return TtestResult {
            statistic: u1,
            pvalue: mwu_exact_pvalue(u1, n1, n2, "two-sided"),
            df: f64::NAN,
        };
    }

    let variance_no_ties = n1f * n2f * (n + 1.0) / 12.0;
    let variance = if n > 1.0 {
        variance_no_ties - n1f * n2f * tie_correction / (12.0 * n * (n - 1.0))
    } else {
        variance_no_ties
    };
    let sigma = variance.max(0.0).sqrt();

    if sigma == 0.0 {
        return TtestResult {
            statistic: u1,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    // Continuity correction: subtract 0.5 from |U - mu| to compensate
    // for the discrete-to-continuous approximation. Equivalent to
    // scipy's `z = (U - mu - 0.5*sign(U - mu)) / sigma` for two-sided.
    let abs_diff = (u - mu).abs();
    let z = (abs_diff - 0.5).max(0.0) / sigma;
    let normal = Normal::standard();
    // pvalue = 2 * sf(|z|) for two-sided
    let pvalue = (2.0 * (1.0 - normal.cdf(z))).clamp(0.0, 1.0);

    TtestResult {
        statistic: u1,
        pvalue,
        df: f64::NAN,
    }
}

/// [`mannwhitneyu`] on two samples already sorted ascending (`total_cmp` order) and NaN-free. An
/// O(n+m) two-pointer merge over the pre-sorted pair yields BOTH the pooled rank sum of `sa` and the
/// tie correction `Σ(t³−t)`, so an all-pairs matrix can sort each sample ONCE instead of rank-sorting
/// the pool per pair. BYTE-IDENTICAL to `mannwhitneyu(x, y)` on the same finite data: the pooled average
/// ranks are exact int/half-int (order-independent rank sum below 2^53), tie groups are the same
/// value-groups the reference's rank-sort finds, and the identical downstream (exact-vs-asymptotic
/// branch, continuity correction) is fed the same u1/tie_correction.
fn mannwhitneyu_sorted(sa: &[f64], sb: &[f64]) -> TtestResult {
    let n1 = sa.len();
    let n2 = sb.len();
    if n1 < 2 || n2 < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    let (n1f, n2f) = (n1 as f64, n2 as f64);
    let mut ia = 0usize;
    let mut ib = 0usize;
    let mut rank_sum_a = 0.0f64;
    let mut tie_correction = 0.0f64;
    while ia < n1 || ib < n2 {
        let next_val = match (sa.get(ia), sb.get(ib)) {
            (Some(&a), Some(&b)) => {
                if a.total_cmp(&b) == std::cmp::Ordering::Greater {
                    b
                } else {
                    a
                }
            }
            (Some(&a), None) => a,
            (None, Some(&b)) => b,
            (None, None) => break,
        };
        let start = ia + ib;
        // Tie membership by value `==`, NOT `total_cmp`: `rankdata_average` (the
        // per-pair `mannwhitneyu` rank engine) groups ±0.0 TOGETHER (they compare
        // equal, matching scipy), whereas `total_cmp` keeps −0.0 < +0.0 distinct.
        // Grouping by `==` here makes this kernel byte-identical to the per-pair
        // path on ±0.0 data (previously it diverged — a latent bug the square-form
        // `mannwhitneyu_matrix` shared). Inputs are finite (NaN → per-pair fallback),
        // so `==` is total here.
        let mut na = 0usize;
        while ia < n1 && sa[ia] == next_val {
            ia += 1;
            na += 1;
        }
        let mut nb = 0usize;
        while ib < n2 && sb[ib] == next_val {
            ib += 1;
            nb += 1;
        }
        let group = na + nb;
        let avg_rank = start as f64 + 1.0 + (group as f64 - 1.0) / 2.0;
        rank_sum_a += na as f64 * avg_rank;
        let t = group as f64;
        if t > 1.0 {
            tie_correction += t * t * t - t;
        }
    }
    let u1 = rank_sum_a - n1f * (n1f + 1.0) / 2.0;
    let u2 = n1f * n2f - u1;
    let u = u1.min(u2);
    let mu = n1f * n2f / 2.0;
    let n = n1f + n2f;
    if mwu_use_exact(n1, n2, tie_correction == 0.0) {
        return TtestResult {
            statistic: u1,
            pvalue: mwu_exact_pvalue(u1, n1, n2, "two-sided"),
            df: f64::NAN,
        };
    }
    let variance_no_ties = n1f * n2f * (n + 1.0) / 12.0;
    let variance = if n > 1.0 {
        variance_no_ties - n1f * n2f * tie_correction / (12.0 * n * (n - 1.0))
    } else {
        variance_no_ties
    };
    let sigma = variance.max(0.0).sqrt();
    if sigma == 0.0 {
        return TtestResult {
            statistic: u1,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }
    let abs_diff = (u - mu).abs();
    let z = (abs_diff - 0.5).max(0.0) / sigma;
    let normal = Normal::standard();
    let pvalue = (2.0 * (1.0 - normal.cdf(z))).clamp(0.0, 1.0);
    TtestResult {
        statistic: u1,
        pvalue,
        df: f64::NAN,
    }
}

/// Mann-Whitney U test with alternative hypothesis specification.
///
/// Matches `scipy.stats.mannwhitneyu(x, y, alternative=...)`.
///
/// # Arguments
/// * `x`, `y` - Sample data
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn mannwhitneyu_alternative(x: &[f64], y: &[f64], alternative: &str) -> TtestResult {
    if x.len() < 2 || y.len() < 2 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let n1 = x.len();
    let n2 = y.len();
    let n1f = n1 as f64;
    let n2f = n2 as f64;

    let mut combined: Vec<(f64, usize)> = Vec::with_capacity(n1 + n2);
    for &v in x {
        combined.push((v, 0));
    }
    for &v in y {
        combined.push((v, 1));
    }

    let values: Vec<f64> = combined.iter().map(|&(v, _)| v).collect();
    // Ranks AND the tie sum from ONE pass, replacing a `ranks.clone()` + second sort
    // below (`frankenscipy-921i0`). BYTE-IDENTICAL: the old loop grouped sorted RANKS
    // within 1e-12, a tolerance that cannot bite because distinct average-rank groups
    // differ by at least 0.5; ranks are monotone in values, so the groups and their
    // ascending order are exactly those of the ranking pass.
    let (ranks, tie_correction) = rankdata_ties_with_tie_sum(&values, RankTieMethod::Average);

    let rank_sum_x: f64 = ranks
        .iter()
        .zip(combined.iter())
        .filter(|(_, (_, group))| *group == 0)
        .map(|(r, _)| *r)
        .sum();

    let u1 = rank_sum_x - n1f * (n1f + 1.0) / 2.0;
    let u2 = n1f * n2f - u1;

    let mu = n1f * n2f / 2.0;
    let n = n1f + n2f;

    // br-nknp: tie correction for sigma (matches scipy default).
    // `tie_correction` came back from the ranking pass above.
    // Exact null distribution for an untied small sample (scipy method='auto').
    // The reported statistic is always U1 (for x). frankenscipy-vwmup
    if mwu_use_exact(n1, n2, tie_correction == 0.0) {
        return TtestResult {
            statistic: u1,
            pvalue: mwu_exact_pvalue(u1, n1, n2, alternative),
            df: f64::NAN,
        };
    }

    let variance_no_ties = n1f * n2f * (n + 1.0) / 12.0;
    let variance = if n > 1.0 {
        variance_no_ties - n1f * n2f * tie_correction / (12.0 * n * (n - 1.0))
    } else {
        variance_no_ties
    };
    let sigma = variance.max(0.0).sqrt();

    if sigma == 0.0 {
        return TtestResult {
            statistic: u1,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    // scipy's asymptotic p-value is always SF with a -0.5 continuity correction,
    // choosing U = U1 for 'greater', U2 for 'less', and max(U1,U2) two-sided.
    let normal = Normal::standard();
    let pvalue = match alternative {
        "less" => normal.sf((u2 - mu - 0.5) / sigma),
        "greater" => normal.sf((u1 - mu - 0.5) / sigma),
        _ => {
            // br-nknp: two-sided with continuity correction (z from min(U1, U2)).
            let abs_diff = (u1.min(u2) - mu).abs();
            let z = (abs_diff - 0.5).max(0.0) / sigma;
            (2.0 * (1.0 - normal.cdf(z))).clamp(0.0, 1.0)
        }
    };

    // scipy reports U1 (statistic for x) for every alternative.
    TtestResult {
        statistic: u1,
        pvalue,
        df: f64::NAN,
    }
}

/// Result of [`logrank`]: the (square-root form) log-rank test statistic and its
/// p-value, mirroring `scipy.stats.LogRankResult`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LogRankResult {
    /// Standardized log-rank statistic (a z-score; its square is the usual
    /// chi-squared statistic with 1 degree of freedom).
    pub statistic: f64,
    /// p-value for the requested alternative.
    pub pvalue: f64,
}

/// Log-rank (Mantel–Cox) test comparing the survival distributions of two
/// independent samples of (fully observed) event times.
///
/// Matches `scipy.stats.logrank(x, y, alternative)` for uncensored input
/// (arrays of event times, all events observed); right-censored input via a
/// `CensoredData` object is not supported.
///
/// `alternative` is one of `"two-sided"` (default), `"less"`, or `"greater"`.
/// The statistic is `(O_x − E_x) / sqrt(V)` where `O_x`/`E_x` are the observed
/// and expected numbers of events in `x` and `V` is the hypergeometric variance
/// summed over the distinct event times of the pooled sample.
/// When `true`, [`logrank`] computes each time's at-risk/death counts by a linear scan (the
/// ORIG O(|times|·n) behaviour); default `false` uses pre-sorted binary search (O(n log n)).
/// Byte-identical. A/B gate.
#[doc(hidden)]
pub static LOGRANK_FORCE_QUADRATIC: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

#[must_use]
pub fn logrank(x: &[f64], y: &[f64], alternative: &str) -> LogRankResult {
    if x.is_empty() || y.is_empty() || x.iter().chain(y.iter()).any(|v| v.is_nan()) {
        return LogRankResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    // Distinct event times of the pooled sample.
    let mut times: Vec<f64> = x.iter().chain(y.iter()).copied().collect();
    times.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    times.dedup();

    let (sum_var, sum_exp_x) = if LOGRANK_FORCE_QUADRATIC.load(std::sync::atomic::Ordering::Relaxed)
    {
        // ORIGINAL O(|times|·n): a linear scan of x and y for every distinct time.
        let count_ge = |s: &[f64], t: f64| s.iter().filter(|&&v| v >= t).count() as f64;
        let count_eq = |s: &[f64], t: f64| s.iter().filter(|&&v| v == t).count() as f64;
        let mut sum_var = 0.0_f64;
        let mut sum_exp_x = 0.0_f64;
        for &t in &times {
            let at_risk_x = count_ge(x, t);
            let at_risk_xy = at_risk_x + count_ge(y, t);
            let deaths_xy = count_eq(x, t) + count_eq(y, t);
            let at_risk_y = at_risk_xy - at_risk_x;
            if at_risk_xy > 1.0 {
                sum_var += at_risk_x * at_risk_y * deaths_xy * (at_risk_xy - deaths_xy)
                    / (at_risk_xy * at_risk_xy * (at_risk_xy - 1.0));
            }
            sum_exp_x += at_risk_x * (deaths_xy / at_risk_xy);
        }
        (sum_var, sum_exp_x)
    } else {
        // O((n + |times|)·log n): sort x and y ONCE, then get each time's at-risk/death counts
        // by binary search instead of a full scan. The data is guaranteed finite (NaN was
        // rejected above), so `partition_point` on the ascending-sorted arrays yields the SAME
        // integer counts as the linear scans (count_ge = n − #{v < t}, count_eq = #{v ≤ t} −
        // #{v < t}) — BYTE-IDENTICAL sums (same integer values accumulated over `times` in the
        // same order).
        let mut sx = x.to_vec();
        let mut sy = y.to_vec();
        sx.sort_by(|a, b| a.partial_cmp(b).expect("finite (NaN rejected above)"));
        sy.sort_by(|a, b| a.partial_cmp(b).expect("finite (NaN rejected above)"));
        let count_ge = |s: &[f64], t: f64| (s.len() - s.partition_point(|&v| v < t)) as f64;
        let count_eq = |s: &[f64], t: f64| {
            (s.partition_point(|&v| v <= t) - s.partition_point(|&v| v < t)) as f64
        };
        let mut sum_var = 0.0_f64;
        let mut sum_exp_x = 0.0_f64;
        for &t in &times {
            let at_risk_x = count_ge(&sx, t);
            let at_risk_xy = at_risk_x + count_ge(&sy, t);
            let deaths_xy = count_eq(&sx, t) + count_eq(&sy, t);
            let at_risk_y = at_risk_xy - at_risk_x;
            if at_risk_xy > 1.0 {
                sum_var += at_risk_x * at_risk_y * deaths_xy * (at_risk_xy - deaths_xy)
                    / (at_risk_xy * at_risk_xy * (at_risk_xy - 1.0));
            }
            sum_exp_x += at_risk_x * (deaths_xy / at_risk_xy);
        }
        (sum_var, sum_exp_x)
    };

    let observed_x = x.len() as f64;
    let statistic = (observed_x - sum_exp_x) / sum_var.sqrt();

    let normal = Normal::standard();
    let pvalue = match alternative {
        "less" => normal.cdf(statistic),
        "greater" => normal.sf(statistic),
        _ => (2.0 * normal.sf(statistic.abs())).clamp(0.0, 1.0),
    };

    LogRankResult { statistic, pvalue }
}

/// Wilcoxon signed-rank test for paired samples.
///
/// Matches `scipy.stats.wilcoxon(x, y)`.
///
/// Non-parametric test: H0: median of x - y is zero.
/// pmf of the Wilcoxon signed-rank statistic T+ (sum of the positive ranks) over
/// integer ranks 1..n, via scipy's halving recurrence (`_get_wilcoxon_distr`).
/// Returns probabilities for T+ = 0, 1, …, n(n+1)/2. Used for the EXACT p-value
/// when the absolute differences have no ties and no zeros were dropped.
/// frankenscipy-78v5y
fn wilcoxon_signed_rank_pmf(n: usize) -> Vec<f64> {
    let mut c = vec![1.0_f64];
    for k in 1..=n {
        let prev = c;
        let len = k * (k + 1) / 2 + 1;
        let mut nc = vec![0.0_f64; len];
        for (i, &p) in prev.iter().enumerate() {
            nc[i] += p * 0.5; // rank k assigned a negative sign
            nc[k + i] += p * 0.5; // rank k assigned a positive sign (shift by k)
        }
        c = nc;
    }
    c
}

/// scipy's exact signed-rank p-value (`method='exact'`, used only when there are
/// no ties and no zeros so the ranks are 1..n). Returns (statistic, pvalue).
fn wilcoxon_exact_pvalue(t_plus: f64, t_minus: f64, n: usize, alternative: &str) -> (f64, f64) {
    let pmf = wilcoxon_signed_rank_pmf(n);
    let rp = (t_plus.round() as usize).min(pmf.len() - 1);
    let cdf: f64 = pmf[..=rp].iter().sum(); // P(T+ <= r_plus)
    let sf: f64 = pmf[rp..].iter().sum(); // P(T+ >= r_plus)
    match alternative {
        "less" => (t_plus, cdf),
        "greater" => (t_plus, sf),
        _ => (t_plus.min(t_minus), (2.0 * sf.min(cdf)).min(1.0)),
    }
}

/// scipy's exact-permutation signed-rank p-value, used by `method='auto'` when
/// the absolute differences have ties or zeros were dropped and the total
/// sample size is small (n<=13). scipy switches from the integer-rank exact
/// distribution to `stats.permutation_test(permutation_type='samples')`, which
/// enumerates the 2^m sign assignments of the m non-zero average ranks and
/// forms the exact null distribution of T+ (since 2^13 < 9999 default resamples
/// → deterministic). The two-sided p is `2*min(P(T+<=obs), P(T+>=obs))` with no
/// +1 small-sample adjustment (exact enumeration). scipy's `gamma=100*eps*obs`
/// tolerance is far below the 0.5 spacing of average ranks, so we work in
/// exact doubled-rank integer space where it never changes a count.
/// frankenscipy-qghyr
fn wilcoxon_permutation_pvalue(ranks: &[f64], t_plus: f64, alternative: &str) -> f64 {
    // counts[s] = number of rank subsets whose doubled-rank sum equals s.
    let doubled: Vec<usize> = ranks.iter().map(|r| (r * 2.0).round() as usize).collect();
    let total: usize = doubled.iter().sum();
    let mut counts = vec![0u64; total + 1];
    counts[0] = 1;
    for &w in &doubled {
        for s in (0..=total - w).rev() {
            counts[s + w] += counts[s];
        }
    }
    let n_perm = (1u64 << ranks.len()) as f64; // 2^m sign assignments
    let obs2 = ((t_plus * 2.0).round() as usize).min(total);
    let le: u64 = counts[..=obs2].iter().sum(); // P(T+ <= obs)
    let ge: u64 = counts[obs2..].iter().sum(); // P(T+ >= obs)
    let less_p = le as f64 / n_perm;
    let greater_p = ge as f64 / n_perm;
    match alternative {
        "less" => less_p,
        "greater" => greater_p,
        _ => (2.0 * less_p.min(greater_p)).min(1.0),
    }
}

/// When `true`, [`wilcoxon`] computes its `no_ties` sort eagerly (the ORIG behaviour, wasted on
/// the large-n path); default `false` gates it behind `nr <= 1000`. Byte-identical.
#[doc(hidden)]
pub static WILCOXON_FORCE_EAGER_NOTIES: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn wilcoxon(x: &[f64], y: &[f64]) -> TtestResult {
    if x.len() != y.len() || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    // Compute differences, discard zeros
    let diffs: Vec<f64> = x
        .iter()
        .zip(y.iter())
        .map(|(&xi, &yi)| xi - yi)
        .filter(|&d| d.abs() > 1e-15)
        .collect();

    let nr = diffs.len();
    if nr < 2 {
        return TtestResult {
            statistic: 0.0,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    // Rank the absolute differences
    let abs_diffs: Vec<f64> = diffs.iter().map(|d| d.abs()).collect();
    // Ranks AND Σ(t³ − t) from ONE pass. scipy does the same —
    // `r, t = _rankdata(xp.abs(d), 'average', return_ties=True)` then
    // `tie_correct = xp.sum(t**3 - t)` (scipy/stats/_wilcoxon.py:138,172) — for the same
    // reason: the tie structure is already known where the ranks are assigned. This
    // replaces a clone+sort for `no_ties` AND a clone+sort for the tie correction
    // (`frankenscipy-921i0`), and switches the tie predicate from a 1e-12 tolerance to
    // exact equality, matching scipy (`frankenscipy-clttw`).
    let (ranks, tie_sum) = rankdata_ties_with_tie_sum(&abs_diffs, RankTieMethod::Average);

    // T+ = sum of ranks where difference is positive
    let t_plus: f64 = ranks
        .iter()
        .zip(diffs.iter())
        .filter(|(_, d)| **d > 0.0)
        .map(|(r, _)| *r)
        .sum();

    let t_minus: f64 = ranks
        .iter()
        .zip(diffs.iter())
        .filter(|(_, d)| **d < 0.0)
        .map(|(r, _)| *r)
        .sum();

    // scipy `method='auto'` uses the EXACT signed-rank null distribution when no
    // zeros were dropped and the absolute differences have no ties (ranks 1..n);
    // it falls back to the normal approximation otherwise. frankenscipy-78v5y
    let no_zeros = x.len() == nr;
    // HISTORICAL (frankenscipy-78v5y): computing `no_ties` used to sort a clone of
    // abs_diffs, so it was gated behind the cheap `no_zeros && nr <= 1000` checks to spare
    // the large-n / has-zeros paths that fall through to the normal approximation. That
    // sort is gone — see below — so the gate no longer saves anything, though the
    // short-circuit still yields the same boolean.
    // Was: clone `abs_diffs`, sort, check no two adjacent entries are equal. `tie_sum`
    // from the ranking pass answers that for free — it is zero exactly when no tie group
    // has size >= 2. BYTE-IDENTICAL as a predicate: both test exact equality.
    // `WILCOXON_FORCE_EAGER_NOTIES` gated the cost of that sort; the sort is gone, so both
    // arms now do the same free comparison — the lever is vestigial, not wrong, and is
    // left in place so its A/B harness still builds.
    let no_ties = || tie_sum == 0.0;
    let take_exact = if WILCOXON_FORCE_EAGER_NOTIES.load(std::sync::atomic::Ordering::Relaxed) {
        let nt = no_ties();
        no_zeros && nt && nr <= 1000
    } else {
        no_zeros && nr <= 1000 && no_ties()
    };
    if take_exact {
        let (stat, pvalue) = wilcoxon_exact_pvalue(t_plus, t_minus, nr, "two-sided");
        return TtestResult {
            statistic: stat,
            pvalue,
            df: f64::NAN,
        };
    }

    // scipy `method='auto'` switches the exact path to an exact permutation test
    // when there are ties or dropped zeros and the total sample size is <=13
    // (2^13 < 9999 default resamples → deterministic). frankenscipy-qghyr
    if x.len() <= 13 {
        let pvalue = wilcoxon_permutation_pvalue(&ranks, t_plus, "two-sided");
        return TtestResult {
            statistic: t_plus.min(t_minus),
            pvalue,
            df: f64::NAN,
        };
    }

    let t_stat = t_plus.min(t_minus);
    let nrf = nr as f64;

    // Normal approximation with tie correction. scipy:
    //   sigma² = n*(n+1)*(2n+1)/24 - Σ(t³-t)/48
    // where t are tie-group sizes among absolute differences.
    let mu = nrf * (nrf + 1.0) / 4.0;
    // `tie_sum` came from the ranking pass. NOT byte-identical to what stood here: the
    // deleted loop grouped by `|a − b| < 1e-12`, merging values scipy treats as distinct.
    // Exact grouping changes the correction on near-tied inputs — measured at
    // p 0.52861213 against 0.52810613, statistic unchanged (`frankenscipy-clttw`).
    let variance = (nrf * (nrf + 1.0) * (2.0 * nrf + 1.0) / 24.0) - tie_sum / 48.0;
    let sigma = variance.max(0.0).sqrt();

    if sigma == 0.0 {
        return TtestResult {
            statistic: t_stat,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    let z = (t_stat - mu) / sigma;
    let normal = Normal::standard();
    let pvalue = 2.0 * normal.cdf(z.min(0.0));

    TtestResult {
        statistic: t_stat,
        pvalue,
        df: f64::NAN,
    }
}

/// Wilcoxon signed-rank test with alternative hypothesis specification.
///
/// Matches `scipy.stats.wilcoxon(x, y, alternative=...)`.
///
/// # Arguments
/// * `x`, `y` - Paired sample data
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn wilcoxon_alternative(x: &[f64], y: &[f64], alternative: &str) -> TtestResult {
    if x.len() != y.len() || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let diffs: Vec<f64> = x
        .iter()
        .zip(y.iter())
        .map(|(&xi, &yi)| xi - yi)
        .filter(|&d| d.abs() > 1e-15)
        .collect();

    let nr = diffs.len();
    if nr < 2 {
        return TtestResult {
            statistic: 0.0,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    let abs_diffs: Vec<f64> = diffs.iter().map(|d| d.abs()).collect();
    // Ranks AND Σ(t³ − t) from ONE pass. scipy does the same —
    // `r, t = _rankdata(xp.abs(d), 'average', return_ties=True)` then
    // `tie_correct = xp.sum(t**3 - t)` (scipy/stats/_wilcoxon.py:138,172) — for the same
    // reason: the tie structure is already known where the ranks are assigned. This
    // replaces a clone+sort for `no_ties` AND a clone+sort for the tie correction
    // (`frankenscipy-921i0`), and switches the tie predicate from a 1e-12 tolerance to
    // exact equality, matching scipy (`frankenscipy-clttw`).
    let (ranks, tie_sum) = rankdata_ties_with_tie_sum(&abs_diffs, RankTieMethod::Average);

    let t_plus: f64 = ranks
        .iter()
        .zip(diffs.iter())
        .filter(|(_, d)| **d > 0.0)
        .map(|(r, _)| *r)
        .sum();

    let t_minus: f64 = ranks
        .iter()
        .zip(diffs.iter())
        .filter(|(_, d)| **d < 0.0)
        .map(|(r, _)| *r)
        .sum();

    // Exact signed-rank p-value when no zeros/ties (see `wilcoxon`).
    // frankenscipy-78v5y
    let no_zeros = x.len() == nr;
    // Was: clone `abs_diffs`, sort, check no two adjacent entries are equal. `tie_sum`
    // from the ranking pass answers that for free — it is zero exactly when no tie group
    // has size >= 2. BYTE-IDENTICAL as a predicate: both test exact equality.
    let no_ties = tie_sum == 0.0;
    if no_zeros && no_ties && nr <= 1000 {
        let (stat, pvalue) = wilcoxon_exact_pvalue(t_plus, t_minus, nr, alternative);
        return TtestResult {
            statistic: stat,
            pvalue,
            df: f64::NAN,
        };
    }

    // Exact permutation test for ties/zeros with small n (see `wilcoxon`).
    // frankenscipy-qghyr
    if x.len() <= 13 {
        let pvalue = wilcoxon_permutation_pvalue(&ranks, t_plus, alternative);
        let stat = if alternative == "two-sided" {
            t_plus.min(t_minus)
        } else {
            t_plus
        };
        return TtestResult {
            statistic: stat,
            pvalue,
            df: f64::NAN,
        };
    }

    let nrf = nr as f64;
    let mu = nrf * (nrf + 1.0) / 4.0;

    // Tie correction for sigma (matches scipy's wilcoxon mode='approx'):
    //   sigma² = n*(n+1)*(2n+1)/24 - Σ(t³-t)/48
    // where t are tie-group sizes among the absolute differences.
    // `tie_sum` came from the ranking pass. NOT byte-identical to what stood here: the
    // deleted loop grouped by `|a − b| < 1e-12`, merging values scipy treats as distinct.
    // Exact grouping changes the correction on near-tied inputs — measured at
    // p 0.52861213 against 0.52810613, statistic unchanged (`frankenscipy-clttw`).
    let variance = (nrf * (nrf + 1.0) * (2.0 * nrf + 1.0) / 24.0) - tie_sum / 48.0;
    let sigma = variance.max(0.0).sqrt();

    if sigma == 0.0 {
        return TtestResult {
            statistic: t_plus,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    let normal = Normal::standard();
    let (t_stat, pvalue) = match alternative {
        "less" => {
            let z = (t_plus - mu) / sigma;
            (t_plus, normal.cdf(z))
        }
        "greater" => {
            let z = (t_plus - mu) / sigma;
            (t_plus, normal.sf(z))
        }
        _ => {
            let t = t_plus.min(t_minus);
            let z = (t - mu) / sigma;
            (t, 2.0 * normal.cdf(z.min(0.0)))
        }
    };

    TtestResult {
        statistic: t_stat,
        pvalue,
        df: f64::NAN,
    }
}

/// Kruskal-Wallis H-test for independent samples.
///
/// Matches `scipy.stats.kruskal(*groups)`.
///
/// Non-parametric alternative to one-way ANOVA.
/// Tests H0: all groups come from the same distribution.
/// Kruskal-Wallis H-test, matching `scipy.stats.mstats.kruskalwallis` (the
/// `mstats` spelling of [`kruskal`]; identical for data without masked values).
pub fn kruskalwallis(groups: &[&[f64]]) -> TtestResult {
    kruskal(groups)
}

/// Two-sample Kolmogorov-Smirnov test, matching `scipy.stats.mstats.ks_twosamp`
/// (the `mstats` spelling of [`ks_2samp`]; identical for unmasked data).
pub fn ks_twosamp(data1: &[f64], data2: &[f64]) -> GoodnessOfFitResult {
    ks_2samp(data1, data2)
}

/// One-sample t-test, matching `scipy.stats.mstats.ttest_onesamp` (the `mstats`
/// spelling of [`ttest_1samp`]; identical for unmasked data).
pub fn ttest_onesamp(data: &[f64], popmean: f64) -> TtestResult {
    ttest_1samp(data, popmean)
}

pub fn kruskal(groups: &[&[f64]]) -> TtestResult {
    if groups.len() < 2
        || groups.iter().any(|g| g.is_empty())
        || groups.iter().any(|g| g.iter().any(|v| v.is_nan()))
    {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let n_total: usize = groups.iter().map(|g| g.len()).sum();
    let nf = n_total as f64;

    if n_total < 3 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    // Combine all observations and rank
    let mut all_values: Vec<f64> = Vec::with_capacity(n_total);
    let mut group_sizes: Vec<usize> = Vec::with_capacity(groups.len());
    for &g in groups {
        all_values.extend_from_slice(g);
        group_sizes.push(g.len());
    }
    if all_values.iter().all(|&v| v == all_values[0]) {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }
    // Ranks AND the tie-correction sum from ONE pass. The tie structure is already
    // known where the ranks are assigned, so the previous `all_values.clone()` +
    // second sort recomputed what this pass had in hand — the same shape scipy avoids
    // via `_rankdata(..., return_ties=True)` (`frankenscipy-921i0`). BYTE-IDENTICAL:
    // the old loop grouped `sorted_values[j] == sorted_values[i]`, the same `==` over
    // the same values in the same ascending order, summing the same `t` values.
    let (ranks, tie_sum) = rankdata_ties_with_tie_sum(&all_values, RankTieMethod::Average);

    // Compute H statistic: H = (12/(N(N+1))) * Σ(R_i²/n_i) - 3(N+1)
    let mut offset = 0;
    let mut h_sum = 0.0;
    for &ni in &group_sizes {
        let rank_sum: f64 = ranks[offset..offset + ni].iter().sum();
        h_sum += rank_sum * rank_sum / ni as f64;
        offset += ni;
    }

    let h_uncorrected = 12.0 / (nf * (nf + 1.0)) * h_sum - 3.0 * (nf + 1.0);

    // Tie correction. scipy divides H by C = 1 - Σ(t³-t)/(N³-N) where the
    // sum is over each tie-group size t in the combined sorted observations.
    // `tie_sum` came back from the ranking pass above; the clone + second sort that
    // used to recompute it here is gone.
    let c = 1.0 - tie_sum / (nf * nf * nf - nf);
    let h = if c > 0.0 {
        h_uncorrected / c
    } else {
        h_uncorrected
    };
    let df = groups.len() as f64 - 1.0;

    // P-value from chi-squared distribution
    let chi2 = ChiSquared::new(df);
    let pvalue = chi2.sf(h).clamp(0.0, 1.0);

    TtestResult {
        statistic: h,
        pvalue,
        df,
    }
}

/// Kruskal-Wallis H-test with nan_policy parameter.
///
/// Matches `scipy.stats.kruskal(*groups, nan_policy=...)`.
///
/// * `nan_policy` - "propagate" (default), "omit", or "raise"
pub fn kruskal_with_nan_policy(
    groups: &[&[f64]],
    nan_policy: Option<&str>,
) -> Result<TtestResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;

    // Check for NaN and apply policy
    let has_nan = groups.iter().any(|g| g.iter().any(|v| v.is_nan()));

    if has_nan {
        match nan_policy {
            "raise" => {
                return Err(StatsError::InvalidArgument(
                    "input contains NaN values".to_string(),
                ));
            }
            "propagate" => {
                return Ok(TtestResult {
                    statistic: f64::NAN,
                    pvalue: f64::NAN,
                    df: f64::NAN,
                });
            }
            "omit" => {
                // Filter NaN from each group
                let cleaned: Vec<Vec<f64>> = groups
                    .iter()
                    .map(|g| g.iter().copied().filter(|v| !v.is_nan()).collect())
                    .collect();
                let cleaned_refs: Vec<&[f64]> = cleaned.iter().map(|v| v.as_slice()).collect();
                return Ok(kruskal(&cleaned_refs));
            }
            _ => {}
        }
    }

    Ok(kruskal(groups))
}

/// Wilcoxon rank-sum test for two independent samples.
///
/// Matches `scipy.stats.ranksums(x, y)`.
///
/// Similar to Mann-Whitney U but returns a z-statistic.
pub fn ranksums(x: &[f64], y: &[f64]) -> TtestResult {
    if x.len() < 2 || y.len() < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let n1 = x.len() as f64;
    let n2 = y.len() as f64;

    // Combine and rank
    let mut combined: Vec<f64> = Vec::with_capacity(x.len() + y.len());
    combined.extend_from_slice(x);
    combined.extend_from_slice(y);
    let ranks = rankdata_average(&combined);

    // Sum of ranks for first sample
    let rank_sum_x: f64 = ranks[..x.len()].iter().sum();

    // Expected rank sum under H0
    let expected = n1 * (n1 + n2 + 1.0) / 2.0;
    let sd = (n1 * n2 * (n1 + n2 + 1.0) / 12.0).sqrt();

    if sd == 0.0 {
        return TtestResult {
            statistic: 0.0,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    let z = (rank_sum_x - expected) / sd;
    let normal = Normal::standard();
    let pvalue = 2.0 * normal.cdf(-z.abs()); // two-sided

    TtestResult {
        statistic: z,
        pvalue,
        df: f64::NAN,
    }
}

/// Wilcoxon rank-sum test with alternative hypothesis.
///
/// Matches `scipy.stats.ranksums(x, y, alternative=...)`.
///
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn ranksums_alternative(x: &[f64], y: &[f64], alternative: &str) -> TtestResult {
    if x.len() < 2 || y.len() < 2 {
        return TtestResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
            df: f64::NAN,
        };
    }

    let n1 = x.len() as f64;
    let n2 = y.len() as f64;

    let mut combined: Vec<f64> = Vec::with_capacity(x.len() + y.len());
    combined.extend_from_slice(x);
    combined.extend_from_slice(y);
    let ranks = rankdata_average(&combined);

    let rank_sum_x: f64 = ranks[..x.len()].iter().sum();

    let expected = n1 * (n1 + n2 + 1.0) / 2.0;
    let sd = (n1 * n2 * (n1 + n2 + 1.0) / 12.0).sqrt();

    if sd == 0.0 {
        return TtestResult {
            statistic: 0.0,
            pvalue: 1.0,
            df: f64::NAN,
        };
    }

    let z = (rank_sum_x - expected) / sd;
    let pvalue = normal_alternative_pvalue(z, alternative);

    TtestResult {
        statistic: z,
        pvalue,
        df: f64::NAN,
    }
}

// ══════════════════════════════════════════════════════════════════════
// Correlation and Regression
// ══════════════════════════════════════════════════════════════════════

/// Result of linear regression.
#[derive(Debug, Clone, PartialEq)]
pub struct LinregressResult {
    /// Slope of the regression line.
    pub slope: f64,
    /// Intercept of the regression line.
    pub intercept: f64,
    /// Pearson correlation coefficient (r-value).
    pub rvalue: f64,
    /// Two-sided p-value for the hypothesis test that the slope is zero.
    pub pvalue: f64,
    /// Standard error of the estimated slope.
    pub stderr: f64,
    /// Standard error of the estimated intercept.
    pub intercept_stderr: f64,
}

/// Calculate a linear least-squares regression for two sets of measurements.
///
/// Matches `scipy.stats.linregress(x, y)`.
///
/// Returns slope, intercept, r-value, p-value, and standard errors.
pub fn linregress(x: &[f64], y: &[f64]) -> LinregressResult {
    let n = x.len() as f64;
    if x.len() < 2 || x.len() != y.len() {
        return LinregressResult {
            slope: f64::NAN,
            intercept: f64::NAN,
            rvalue: f64::NAN,
            pvalue: f64::NAN,
            stderr: f64::NAN,
            intercept_stderr: f64::NAN,
        };
    }

    // Two means fused into ONE work-gated pass (parallel for huge inputs, byte-identical below the
    // gate) — the ORIG made two separate serial `iter().sum()` traversals before the parallel triple.
    let (xmean, ymean) = par_two_means(x, y);

    // Centered sums-of-squares/cross-products (ssxm=Σdx², ssym=Σdy², ssxym=Σdx·dy) — the dominant O(n)
    // reduction (means fixed above). Below the gate (and under PEARSONR_FORCE_SERIAL) fold the three in
    // ONE serial pass (byte-identical to the original loop); above 1<<22 fan them across cores as
    // per-thread partial triples, within per-op ULP tolerance (parallel reorder). Same as `pearsonr`.
    let nn = x.len();
    let chunk_ss = |xs: &[f64], ys: &[f64]| -> (f64, f64, f64) {
        let mut sxm = 0.0f64;
        let mut sym = 0.0f64;
        let mut sxym = 0.0f64;
        for (&xi, &yi) in xs.iter().zip(ys) {
            let dx = xi - xmean;
            let dy = yi - ymean;
            sxm += dx * dx;
            sym += dy * dy;
            sxym += dx * dy;
        }
        (sxm, sym, sxym)
    };
    let (ssxm, ssym, ssxym) =
        if PEARSONR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || nn < (1 << 22) {
            chunk_ss(x, y)
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(nn / (1 << 16))
                .max(1);
            let chunk = nn.div_ceil(nthreads);
            let chunk_ss = &chunk_ss;
            let parts: Vec<(f64, f64, f64)> = std::thread::scope(|scope| {
                x.chunks(chunk)
                    .zip(y.chunks(chunk))
                    .map(|(xs, ys)| scope.spawn(move || chunk_ss(xs, ys)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("linregress worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0.0f64, 0.0f64), |(am, bm, cm), (a, b, c)| {
                    (am + a, bm + b, cm + c)
                })
        };

    if ssxm == 0.0 {
        // All x values identical — slope undefined
        return LinregressResult {
            slope: f64::NAN,
            intercept: f64::NAN,
            rvalue: f64::NAN,
            pvalue: f64::NAN,
            stderr: f64::NAN,
            intercept_stderr: f64::NAN,
        };
    }

    let slope = ssxym / ssxm;
    let intercept = ymean - slope * xmean;

    // Correlation coefficient
    let rvalue = if ssym == 0.0 {
        // All y values identical: scipy leaves the correlation undefined.
        f64::NAN
    } else {
        ssxym / (ssxm * ssym).sqrt()
    };

    // p-value: test H0: slope = 0 using t-distribution
    let df = n - 2.0;
    let (pvalue, stderr, intercept_stderr) = if x.len() == 2 {
        let pvalue = if y[0] == y[1] { 1.0 } else { 0.0 };
        (pvalue, 0.0, 0.0)
    } else if df > 0.0 && rvalue.is_finite() {
        // Residual sum of squares
        let r2 = rvalue * rvalue;
        let sse = ssym * (1.0 - r2);
        let mse = sse / df;
        let se_slope = (mse / ssxm).sqrt();
        let se_intercept = (mse * (1.0 / n + xmean * xmean / ssxm)).sqrt();

        let tiny = 1.0e-20;
        let t_stat = rvalue * (df / ((1.0 - rvalue + tiny) * (1.0 + rvalue + tiny))).sqrt();
        let tdist = StudentT::new(df);
        let pval = 2.0 * tdist.sf(t_stat.abs());
        (pval, se_slope, se_intercept)
    } else {
        (f64::NAN, f64::NAN, f64::NAN)
    };

    LinregressResult {
        slope,
        intercept,
        rvalue,
        pvalue,
        stderr,
        intercept_stderr,
    }
}

/// Result of linregress confidence intervals.
#[derive(Debug, Clone, PartialEq)]
pub struct LinregressCIResult {
    pub slope_lo: f64,
    pub slope_hi: f64,
    pub intercept_lo: f64,
    pub intercept_hi: f64,
}

/// Compute confidence intervals for linear regression slope and intercept.
///
/// # Arguments
/// * `x` - Independent variable data
/// * `y` - Dependent variable data
/// * `alpha` - Significance level (e.g., 0.05 for 95% CI)
pub fn linregress_ci(x: &[f64], y: &[f64], alpha: f64) -> LinregressCIResult {
    let n = x.len();
    if n < 3 || x.len() != y.len() {
        return LinregressCIResult {
            slope_lo: f64::NAN,
            slope_hi: f64::NAN,
            intercept_lo: f64::NAN,
            intercept_hi: f64::NAN,
        };
    }

    let result = linregress(x, y);
    if result.stderr.is_nan() {
        return LinregressCIResult {
            slope_lo: f64::NAN,
            slope_hi: f64::NAN,
            intercept_lo: f64::NAN,
            intercept_hi: f64::NAN,
        };
    }

    let df = n as f64 - 2.0;
    let tdist = StudentT::new(df);
    let t_crit = tdist.ppf(1.0 - alpha / 2.0);

    let slope_margin = t_crit * result.stderr;
    let intercept_margin = t_crit * result.intercept_stderr;

    LinregressCIResult {
        slope_lo: result.slope - slope_margin,
        slope_hi: result.slope + slope_margin,
        intercept_lo: result.intercept - intercept_margin,
        intercept_hi: result.intercept + intercept_margin,
    }
}

/// Result of a correlation test.
#[derive(Debug, Clone, PartialEq)]
pub struct CorrelationResult {
    /// Correlation coefficient.
    pub statistic: f64,
    /// Two-sided p-value.
    pub pvalue: f64,
}

/// Coefficient of determination (R²) for regression.
///
/// R² = 1 - SS_res / SS_tot, measures proportion of variance explained.
///
/// # Arguments
/// * `y_true` — Actual values
/// * `y_pred` — Predicted values
pub fn r_squared(y_true: &[f64], y_pred: &[f64]) -> f64 {
    if y_true.len() != y_pred.len() || y_true.len() < 2 {
        return f64::NAN;
    }

    let n = y_true.len() as f64;
    let y_mean = y_true.iter().sum::<f64>() / n;

    let ss_tot: f64 = y_true.iter().map(|&y| (y - y_mean).powi(2)).sum();
    let ss_res: f64 = y_true
        .iter()
        .zip(y_pred.iter())
        .map(|(&t, &p)| (t - p).powi(2))
        .sum();

    if ss_tot == 0.0 {
        return if ss_res == 0.0 { 1.0 } else { f64::NAN };
    }

    1.0 - ss_res / ss_tot
}

/// Adjusted R² for regression with multiple predictors.
///
/// Adjusts R² for the number of predictors to prevent overfitting bias.
/// adj_R² = 1 - (1 - R²) * (n - 1) / (n - p - 1)
///
/// # Arguments
/// * `y_true` — Actual values
/// * `y_pred` — Predicted values
/// * `n_predictors` — Number of predictors (not including intercept)
pub fn adjusted_r_squared(y_true: &[f64], y_pred: &[f64], n_predictors: usize) -> f64 {
    let r2 = r_squared(y_true, y_pred);
    if !r2.is_finite() {
        return f64::NAN;
    }

    let n = y_true.len();
    if n <= n_predictors + 1 {
        return f64::NAN;
    }

    let n_f = n as f64;
    let p = n_predictors as f64;

    1.0 - (1.0 - r2) * (n_f - 1.0) / (n_f - p - 1.0)
}

/// Result of Somers' D ordinal association test.
#[derive(Debug, Clone, PartialEq)]
pub struct SomersDResult {
    /// Somers' D statistic.
    pub statistic: f64,
    /// p-value for H0: D = 0.
    pub pvalue: f64,
    /// Contingency table used in the calculation.
    pub table: Vec<Vec<f64>>,
    /// Alias for `statistic`, matching SciPy's result object.
    pub correlation: f64,
}

/// Input surface for `somersd`.
pub enum SomersDInput<'a> {
    /// Independent/dependent ordinal rankings.
    Rankings(&'a [f64], &'a [f64]),
    /// Precomputed contingency table.
    Table(&'a [Vec<f64>]),
}

/// When `true`, [`pearsonr`]/[`linregress`] fold their centered sums-of-squares serially (the ORIG
/// one-pass loop); default `false` fan them across cores for large inputs. WITHIN per-op ULP tolerance
/// (parallel reorder). `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static PEARSONR_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// When `true`, [`pearsonr`]/[`linregress`] compute their two means (Σx/n, Σy/n) as two separate
/// serial passes (the ORIG behaviour); default `false` computes both in ONE work-gated pass, fanned
/// across cores for huge inputs.
///
/// WITHIN PER-OP ULP TOLERANCE wherever the A/B is meaningful. "Byte-identical below the gate" —
/// what this doc used to say on its own — is vacuously true: below `1 << 22` the two arms are
/// literally the same code, so the toggle cannot change anything and the claim tests nothing. Above
/// the gate [`par_two_means`] folds per-thread `(Σx, Σy)` partials, which reassociates, and that
/// drift propagates into every centered term downstream. Corrected under frankenscipy-5f06d after
/// an exact A/B gate caught it at n = 1 << 22: r = 0.8320502929942495 serial vs 0.8320502929942493
/// parallel. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static PEARSONR_MEAN_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// `(Σx/n, Σy/n)` for equal-length `x`, `y` computed in ONE fused pass. The ORIG made two separate
/// `iter().sum()` traversals before the (already-parallel) centered triple — this fuses them and, for
/// huge inputs, fans across cores. BYTE-IDENTICAL below the gate: `sx`/`sy` are the same left-to-right
/// folds from 0.0 in index order as the two separate sums; above 1<<22 the per-thread (Σx,Σy) partials
/// reorder within per-op ULP tolerance (the centered triple downstream is ULP-gated the same way).
fn par_two_means(x: &[f64], y: &[f64]) -> (f64, f64) {
    let n = x.len();
    let nf = n as f64;
    let chunk_sums = |xs: &[f64], ys: &[f64]| -> (f64, f64) {
        let mut sx = 0.0f64;
        let mut sy = 0.0f64;
        for (&xi, &yi) in xs.iter().zip(ys) {
            sx += xi;
            sy += yi;
        }
        (sx, sy)
    };
    let (sx, sy) =
        if PEARSONR_MEAN_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 22) {
            chunk_sums(x, y)
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n / (1 << 16))
                .max(1);
            let chunk = n.div_ceil(nthreads);
            let chunk_sums = &chunk_sums;
            let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
                x.chunks(chunk)
                    .zip(y.chunks(chunk))
                    .map(|(xs, ys)| scope.spawn(move || chunk_sums(xs, ys)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("par_two_means worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0.0f64), |(a, b), (u, v)| (a + u, b + v))
        };
    (sx / nf, sy / nf)
}

/// Calculate the Pearson correlation coefficient and p-value.
///
/// Matches `scipy.stats.pearsonr(x, y)`.
///
/// Tests for non-correlation: H0: ρ = 0 (no linear relationship).
pub fn pearsonr(x: &[f64], y: &[f64]) -> CorrelationResult {
    let n = x.len();
    if n < 2 || n != y.len() {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    let nf = n as f64;

    // Two means fused into ONE work-gated pass (parallel for huge inputs, byte-identical below the
    // gate) — the ORIG made two separate serial `iter().sum()` traversals before the parallel triple.
    let (xmean, ymean) = par_two_means(x, y);

    // Centered sums-of-squares/cross-products (ssxm=Σdx², ssym=Σdy², ssxym=Σdx·dy) — the dominant O(n)
    // reduction (means are fixed above). Below the gate (and under PEARSONR_FORCE_SERIAL) fold the three
    // in ONE serial pass (byte-identical to the original loop); above 1<<22 fan them across cores as
    // per-thread partial triples, within per-op ULP tolerance (parallel reorder). (The gate constant
    // read 1<<20 here while the code below has always tested `n < (1 << 22)`; corrected to the code
    // under frankenscipy-5f06d.)
    let chunk_ss = |xs: &[f64], ys: &[f64]| -> (f64, f64, f64) {
        let mut sxm = 0.0f64;
        let mut sym = 0.0f64;
        let mut sxym = 0.0f64;
        for (&xi, &yi) in xs.iter().zip(ys) {
            let dx = xi - xmean;
            let dy = yi - ymean;
            sxm += dx * dx;
            sym += dy * dy;
            sxym += dx * dy;
        }
        (sxm, sym, sxym)
    };
    let (ssxm, ssym, ssxym) =
        if PEARSONR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < (1 << 22) {
            chunk_ss(x, y)
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n / (1 << 16))
                .max(1);
            let chunk = n.div_ceil(nthreads);
            let chunk_ss = &chunk_ss;
            let parts: Vec<(f64, f64, f64)> = std::thread::scope(|scope| {
                x.chunks(chunk)
                    .zip(y.chunks(chunk))
                    .map(|(xs, ys)| scope.spawn(move || chunk_ss(xs, ys)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("pearsonr worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0.0f64, 0.0f64), |(am, bm, cm), (a, b, c)| {
                    (am + a, bm + b, cm + c)
                })
        };

    let denom = (ssxm * ssym).sqrt();
    if denom == 0.0 {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let r = ssxym / denom;
    // Clamp to [-1, 1] for numerical safety
    let r = r.clamp(-1.0, 1.0);
    // scipy returns exactly ±1 for n == 2 (mask = (n == 2) → round).
    let r = if n == 2 { r.round() } else { r };

    // p-value via t-distribution: t = r * sqrt((n-2)/(1-r²))
    let df = nf - 2.0;
    let pvalue = if n == 2 {
        1.0
    } else if df > 0.0 && r.abs() < 1.0 {
        let t = r * (df / (1.0 - r * r)).sqrt();
        let tdist = StudentT::new(df);
        2.0 * tdist.sf(t.abs())
    } else if r.abs() >= 1.0 {
        0.0 // Perfect correlation
    } else {
        f64::NAN
    };

    CorrelationResult {
        statistic: r,
        pvalue,
    }
}

/// Calculate Pearson correlation with alternative hypothesis.
///
/// Matches `scipy.stats.pearsonr(x, y, alternative=...)`.
///
/// * `alternative` - "two-sided" (default), "less", or "greater"
pub fn pearsonr_alternative(x: &[f64], y: &[f64], alternative: &str) -> CorrelationResult {
    let n = x.len();
    if n < 2 || n != y.len() {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    let nf = n as f64;

    // Two means fused into ONE work-gated pass (parallel for huge inputs, byte-identical below the
    // gate) — the ORIG made two separate serial `iter().sum()` traversals before the parallel triple.
    let (xmean, ymean) = par_two_means(x, y);

    // scipy-style normalize-first dot product: scale by max-abs first,
    // then take the sqrt of the squared-sum, then dot product on the
    // normalized centred vectors. This avoids overflow on huge inputs
    // and matches scipy's computation order so r near ±1 lands at the
    // same float as scipy (e.g. -0.99999999999999967 instead of exact
    // -1) — relevant for the boundary pvalue (frankenscipy-vgl6u).
    let xm: Vec<f64> = x.iter().map(|&xi| xi - xmean).collect();
    let ym: Vec<f64> = y.iter().map(|&yi| yi - ymean).collect();
    let xmax = xm.iter().map(|v| v.abs()).fold(0.0_f64, f64::max);
    let ymax = ym.iter().map(|v| v.abs()).fold(0.0_f64, f64::max);
    if xmax == 0.0 || ymax == 0.0 {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    let normxm = xmax * xm.iter().map(|v| (v / xmax).powi(2)).sum::<f64>().sqrt();
    let normym = ymax * ym.iter().map(|v| (v / ymax).powi(2)).sum::<f64>().sqrt();
    if normxm == 0.0 || normym == 0.0 {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    let r = xm
        .iter()
        .zip(ym.iter())
        .map(|(&dx, &dy)| (dx / normxm) * (dy / normym))
        .sum::<f64>()
        .clamp(-1.0, 1.0);
    // scipy rounds r to exactly ±1 for n == 2 (two points are always perfectly correlated; see
    // scipy.stats.pearsonr `mask = (n == 2)` → round). The vecdot otherwise lands ~1 ULP short.
    let r = if n == 2 { r.round() } else { r };

    // p-value via the scipy convention: under the null, r is distributed
    // as Beta(n/2 − 1, n/2 − 1) on (−1, 1). Translate r ∈ [−1, 1] onto
    // u ∈ [0, 1] via u = (r + 1)/2 and call the standard BetaDist cdf.
    // The previous t-distribution path produced p = 0 exactly at r = ±1
    // because of the early clamp; the Beta path mirrors scipy and gives
    // a vanishingly small but non-zero pvalue at the boundary
    // (frankenscipy-vgl6u).
    let ab = nf / 2.0 - 1.0;
    let pvalue = if n == 2 {
        1.0
    } else if ab > 0.0 {
        let u = (r + 1.0) / 2.0;
        let beta = BetaDist::new(ab, ab);
        match alternative {
            "less" => beta.cdf(u),
            "greater" => regularized_incomplete_beta(ab, ab, 1.0 - u),
            // Beta(ab, ab) on (−1, 1) is symmetric around 0, so the
            // two-sided pvalue is 2·sf(|r|). Compute sf via the symmetry
            // identity I(x; a, b) = 1 − I(1−x; b, a) to avoid
            // catastrophic cancellation when |r| is close to 1.
            _ => {
                let u_abs = (r.abs() + 1.0) / 2.0;
                (2.0 * regularized_incomplete_beta(ab, ab, 1.0 - u_abs)).clamp(0.0, 1.0)
            }
        }
    } else {
        // df < 0 (unreachable after the length guard): pvalue undefined.
        f64::NAN
    };

    CorrelationResult {
        statistic: r,
        pvalue,
    }
}

/// Calculate a Spearman rho rank-order correlation coefficient and p-value.
///
/// Matches `scipy.stats.spearmanrho(x, y, alternative=...)` — the renamed,
/// keyword-only form of `spearmanr`. Identical statistic and p-value to
/// [`spearmanr_alternative`]; provided under scipy's current public name.
pub fn spearmanrho(x: &[f64], y: &[f64], alternative: &str) -> CorrelationResult {
    spearmanr_alternative(x, y, alternative)
}

fn spearmanr_length_two(x: &[f64], y: &[f64]) -> CorrelationResult {
    let rank_x = rankdata_average(x);
    let rank_y = rankdata_average(y);
    CorrelationResult {
        statistic: pearsonr(&rank_x, &rank_y).statistic,
        pvalue: f64::NAN,
    }
}

/// Calculate the Spearman rank-order correlation coefficient and p-value.
///
/// Matches `scipy.stats.spearmanr(a, b)`.
///
/// Uses the Pearson correlation of the rank-transformed data.
/// When `true`, [`rank_two_average`] ranks its two inputs sequentially (the ORIG behaviour); default
/// `false` overlaps the two independent rankings on separate threads for large inputs. Bit-identical
/// either way (rankdata_average is deterministic). `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static RANK_TWO_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// [`rankdata_average`] applied to `a` and `b`, overlapping the two INDEPENDENT rank computations on
/// separate threads when both inputs are large enough to amortize a thread spawn. Each rankdata is
/// O(n log n) sort-dominated, so overlapping ~halves the rank phase that dominates `spearmanr` (the
/// downstream `pearsonr` on ranks is O(n)). BIT-IDENTICAL to two serial `rankdata_average` calls
/// (deterministic; only the wall-clock overlaps). Mirrors [`sort_two_f64_total`].
fn rank_two_average(a: &[f64], b: &[f64]) -> (Vec<f64>, Vec<f64>) {
    if a.len().min(b.len()) >= (1 << 16)
        && !RANK_TWO_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
    {
        std::thread::scope(|scope| {
            let h = scope.spawn(|| rankdata_average(b));
            let ra = rankdata_average(a);
            let rb = h.join().expect("rank_two_average worker panicked");
            (ra, rb)
        })
    } else {
        (rankdata_average(a), rankdata_average(b))
    }
}

pub fn spearmanr(x: &[f64], y: &[f64]) -> CorrelationResult {
    let n = x.len();
    if n < 2 || n != y.len() {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    if n == 2 {
        return spearmanr_length_two(x, y);
    }

    let (rank_x, rank_y) = rank_two_average(x, y);

    pearsonr(&rank_x, &rank_y)
}

/// Spearman correlation with alternative hypothesis specification.
///
/// Matches `scipy.stats.spearmanr(a, b, alternative=...)`.
pub fn spearmanr_alternative(x: &[f64], y: &[f64], alternative: &str) -> CorrelationResult {
    let n = x.len();
    if n < 2 || n != y.len() {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    if n == 2 {
        return spearmanr_length_two(x, y);
    }

    let (rank_x, rank_y) = rank_two_average(x, y);
    let nf = n as f64;
    let xmean: f64 = rank_x.iter().sum::<f64>() / nf;
    let ymean: f64 = rank_y.iter().sum::<f64>() / nf;

    let (mut ssxm, mut ssym, mut ssxym) = (0.0, 0.0, 0.0);
    for (&xi, &yi) in rank_x.iter().zip(rank_y.iter()) {
        let (dx, dy) = (xi - xmean, yi - ymean);
        ssxm += dx * dx;
        ssym += dy * dy;
        ssxym += dx * dy;
    }

    let denom = (ssxm * ssym).sqrt();
    if denom == 0.0 {
        return CorrelationResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let r = (ssxym / denom).clamp(-1.0, 1.0);
    let df = nf - 2.0;

    let pvalue = if df > 0.0 && r.abs() < 1.0 {
        let t = r * (df / (1.0 - r * r)).sqrt();
        let tdist = StudentT::new(df);
        match alternative {
            "less" => tdist.cdf(t),
            "greater" => tdist.sf(t),
            _ => 2.0 * tdist.sf(t.abs()),
        }
    } else if r >= 1.0 {
        // Perfect positive correlation: t → +∞. "less" tail covers
        // everything; "greater" tail covers nothing; two-sided is 0.
        match alternative {
            "less" => 1.0,
            _ => 0.0,
        }
    } else if r <= -1.0 {
        // Perfect negative correlation: t → −∞.
        match alternative {
            "greater" => 1.0,
            _ => 0.0,
        }
    } else {
        f64::NAN
    };

    CorrelationResult {
        statistic: r,
        pvalue,
    }
}

/// Result of [`bws_test`]: the Baumgartner-Weiss-Schindler statistic and its
/// exact permutation p-value.
pub struct BwsTestResult {
    /// Observed BWS test statistic.
    pub statistic: f64,
    /// Exact permutation p-value for the requested alternative.
    pub pvalue: f64,
}

// BWS statistic on the pooled-rank groups (already split into x/y ranks).
fn bws_statistic(rx: &[f64], ry: &[f64], two_sided: bool) -> f64 {
    let n = rx.len() as f64;
    let m = ry.len() as f64;
    let mut ri = rx.to_vec();
    ri.sort_unstable_by(|a, b| a.total_cmp(b));
    let mut hj = ry.to_vec();
    hj.sort_unstable_by(|a, b| a.total_cmp(b));

    let mut bx = 0.0;
    for (idx, &r) in ri.iter().enumerate() {
        let i = (idx + 1) as f64;
        let num = r - (m + n) / n * i;
        let numv = if two_sided {
            num * num
        } else {
            num * num.abs()
        };
        let den = i / (n + 1.0) * (1.0 - i / (n + 1.0)) * m * (m + n) / n;
        bx += numv / den;
    }
    bx /= n;

    let mut by = 0.0;
    for (idx, &h) in hj.iter().enumerate() {
        let j = (idx + 1) as f64;
        let num = h - (m + n) / m * j;
        let numv = if two_sided {
            num * num
        } else {
            num * num.abs()
        };
        let den = j / (m + 1.0) * (1.0 - j / (m + 1.0)) * n * (m + n) / m;
        by += numv / den;
    }
    by /= m;

    if two_sided {
        (bx + by) / 2.0
    } else {
        (bx - by) / 2.0
    }
}

/// Baumgartner-Weiss-Schindler two-sample test, matching
/// `scipy.stats.bws_test(x, y, alternative=...)`.
///
/// A nonparametric test that the distributions underlying `x` and `y` are equal,
/// weighting the integrated squared CDF difference by its variance (emphasising
/// the tails). `alternative` is `"two-sided"`, `"less"` or `"greater"`.
///
/// The p-value is the *exact* permutation p-value: every way of splitting the
/// pooled ranks into groups of sizes `len(x)` and `len(y)` is enumerated (this
/// matches SciPy whenever the number of splits is `<= 9999`, where SciPy also
/// enumerates exactly). Returns an error if the number of splits exceeds
/// `max_exact` resamples (default 1_000_000 when `None`).
pub fn bws_test(
    x: &[f64],
    y: &[f64],
    alternative: &str,
    max_exact: Option<u64>,
) -> Result<BwsTestResult, StatsError> {
    let n = x.len();
    let m = y.len();
    if n == 0 || m == 0 {
        return Err(StatsError::DataTooSmall {
            required: 1,
            got: n.min(m),
        });
    }
    let alt = alternative.to_ascii_lowercase();
    let (two_sided, greater) = match alt.as_str() {
        "two-sided" => (true, true),
        "greater" => (false, true),
        "less" => (false, false),
        _ => {
            return Err(StatsError::InvalidArgument(format!(
                "bws_test: alternative must be 'two-sided', 'less' or 'greater', got '{alternative}'"
            )));
        }
    };
    if x.iter().chain(y.iter()).any(|v| !v.is_finite()) {
        return Err(StatsError::NonFiniteInput { argument: "x/y" });
    }

    // Pooled ranks (average ties), then split back into x- and y-ranks.
    let mut pooled = Vec::with_capacity(n + m);
    pooled.extend_from_slice(x);
    pooled.extend_from_slice(y);
    let ranks = rankdata(&pooled, Some("average"))?;
    let rx: Vec<f64> = ranks[..n].to_vec();
    let ry: Vec<f64> = ranks[n..].to_vec();
    let b_obs = bws_statistic(&rx, &ry, two_sided);

    // Number of distinct splits C(n+m, n).
    let nn = n + m;
    let total = {
        let mut c: u128 = 1;
        let k = n.min(m);
        for i in 0..k {
            c = c * (nn - i) as u128 / (i + 1) as u128;
        }
        c
    };
    let cap = max_exact.unwrap_or(1_000_000) as u128;
    if total > cap {
        return Err(StatsError::InvalidArgument(format!(
            "bws_test: exact permutation needs {total} resamples (> max_exact); \
             larger samples require a randomized method not yet supported"
        )));
    }

    // Enumerate every n-subset of the pooled ranks; recompute the statistic.
    // SciPy's permutation_test compares against observed +/- gamma with
    // gamma = |eps * observed|, eps = 100 * machine epsilon.
    let tol = f64::EPSILON * 100.0 * b_obs.abs();
    let mut count: u128 = 0;
    let mut comb: Vec<usize> = (0..n).collect();
    let mut grx = vec![0.0f64; n];
    let mut gry = vec![0.0f64; m];
    loop {
        // Build the two groups for the current combination of indices.
        let mut yi = 0usize;
        let mut ci = 0usize;
        for (p, &rv) in ranks.iter().enumerate() {
            if ci < n && comb[ci] == p {
                grx[ci] = rv;
                ci += 1;
            } else {
                gry[yi] = rv;
                yi += 1;
            }
        }
        let b = bws_statistic(&grx, &gry, two_sided);
        let hit = if greater {
            b >= b_obs - tol
        } else {
            b <= b_obs + tol
        };
        if hit {
            count += 1;
        }
        // Advance to the next combination (lexicographic).
        let mut i = n;
        while i > 0 {
            i -= 1;
            if comb[i] != i + nn - n {
                comb[i] += 1;
                for j in (i + 1)..n {
                    comb[j] = comb[j - 1] + 1;
                }
                break;
            }
            if i == 0 {
                // exhausted
                let pvalue = count as f64 / total as f64;
                return Ok(BwsTestResult {
                    statistic: b_obs,
                    pvalue,
                });
            }
        }
    }
}

/// Compute ranks with a SciPy-style tie handling method.
///
/// Matches `scipy.stats.rankdata(a, method=...)` for the implemented methods.
pub fn rankdata(data: &[f64], method: Option<&str>) -> Result<Vec<f64>, StatsError> {
    match method.unwrap_or("average").to_ascii_lowercase().as_str() {
        "average" => Ok(rankdata_ties(data, RankTieMethod::Average)),
        "min" => Ok(rankdata_ties(data, RankTieMethod::Min)),
        "max" => Ok(rankdata_ties(data, RankTieMethod::Max)),
        "dense" => Ok(rankdata_ties(data, RankTieMethod::Dense)),
        "ordinal" => Ok(rankdata_ordinal(data)),
        _ => Err(StatsError::InvalidArgument(
            "method must be one of {'average', 'min', 'max', 'dense', 'ordinal'}".to_string(),
        )),
    }
}

/// Apply [`rankdata`] across one axis of a rectangular 2-D input.
///
/// Matches `scipy.stats.rankdata(a, method, axis=...)`. Each line is ranked
/// independently — BIT-IDENTICAL to per-line 1-D `rankdata`. scipy ranks each line
/// single-threaded (a full sort per line); the across-lines fan-out over cores wins big.
/// The per-line rank is a serial sort, so the fan-out cannot oversubscribe.
pub fn rankdata_axis_2d(
    x: &[Vec<f64>],
    method: Option<&str>,
    axis: isize,
) -> Result<Vec<Vec<f64>>, StatsError> {
    if x.is_empty() {
        return Ok(Vec::new());
    }
    let cols = x[0].len();
    if x.iter().any(|row| row.len() != cols) {
        return Err(StatsError::InvalidArgument(
            "x must be a rectangular 2-D matrix".to_string(),
        ));
    }
    // Validate the method once (fail fast before spawning).
    rankdata(&[0.0], method)?;

    let (n_lines, line_len): (usize, usize) = match axis {
        -1 | 1 => (x.len(), cols),
        0 => (cols, x.len()),
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "axis must be 0, 1, or -1 for 2-D rankdata, got {other}"
            )));
        }
    };
    let by_columns = axis == 0;
    let line = |idx: usize| -> Result<Vec<f64>, StatsError> {
        if by_columns {
            let col: Vec<f64> = x.iter().map(|r| r[idx]).collect();
            rankdata(&col, method)
        } else {
            rankdata(&x[idx], method)
        }
    };

    // Per-line work ~ L·log L (a sort); fan out when it amortises the thread spawn.
    let threads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let work = (n_lines as u64).saturating_mul(line_len.max(1) as u64);
    // Cap thread count by total work: each spawned thread costs ~20µs (OS thread
    // create/join), so fanning out to all 64 cores for a ~1-2M-element reduction is
    // dominated by spawn overhead — measured ~1.5ms floor at 64 threads vs ~0.5-0.8ms
    // at 16-24. ~48k element-ops/thread keeps each thread busy enough to amortize its
    // spawn. BYTE-IDENTICAL (thread count never changes a per-line reduction) and never
    // spawns MORE than the old `threads.min(n_lines)`, so it is a monotone win that still
    // ramps to all cores once work justifies it (>= 64·48k ≈ 3.1M elements).
    const MIN_WORK_PER_THREAD: u64 = 48_000;
    let nthreads = if n_lines < 4 || work < 1 << 16 || threads <= 1 {
        1
    } else {
        threads
            .min(n_lines)
            .min((work / MIN_WORK_PER_THREAD).max(1) as usize)
    };

    let lines: Vec<Vec<f64>> = if nthreads <= 1 {
        (0..n_lines).map(&line).collect::<Result<Vec<_>, _>>()?
    } else {
        let chunk = n_lines.div_ceil(nthreads);
        let line = &line;
        let chunk_results: Vec<Result<Vec<Vec<f64>>, StatsError>> = std::thread::scope(|scope| {
            (0..n_lines)
                .step_by(chunk)
                .map(|l0| {
                    scope.spawn(move || {
                        let l1 = (l0 + chunk).min(n_lines);
                        (l0..l1).map(line).collect::<Result<Vec<_>, _>>()
                    })
                })
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("rankdata line chunk panicked"))
                .collect()
        });
        let mut lines = Vec::with_capacity(n_lines);
        for cr in chunk_results {
            lines.extend(cr?);
        }
        lines
    };

    if by_columns {
        // `lines[c]` is the ranked column `c` (length = rows); scatter to row-major.
        let nrows = x.len();
        let mut out = vec![vec![0.0; cols]; nrows];
        for (c, col_ranks) in lines.into_iter().enumerate() {
            for (r, v) in col_ranks.into_iter().enumerate() {
                out[r][c] = v;
            }
        }
        Ok(out)
    } else {
        Ok(lines)
    }
}

/// Apply a per-line SCALAR reducer across one axis of a rectangular 2-D input, fanning
/// out across lines (one scalar per line). Used by the `*_axis_2d` reductions below.
/// Each line reduction is independent → BIT-IDENTICAL to calling the 1-D reducer per line.
/// scipy.stats applies these via a per-line Python loop (the slow `_axis_nan_policy` path),
/// so the across-lines fan-out over cores wins by 1-2 orders of magnitude. The per-line
/// reducers here are serial (no internal parallelism) → the fan-out cannot oversubscribe.
fn reduce_axis_2d<F>(x: &[Vec<f64>], axis: isize, reduce: F) -> Result<Vec<f64>, StatsError>
where
    F: Fn(&[f64]) -> f64 + Sync,
{
    if x.is_empty() {
        return Ok(Vec::new());
    }
    let cols = x[0].len();
    if x.iter().any(|row| row.len() != cols) {
        return Err(StatsError::InvalidArgument(
            "x must be a rectangular 2-D matrix".to_string(),
        ));
    }
    let (n_lines, line_len): (usize, usize) = match axis {
        -1 | 1 => (x.len(), cols),
        0 => (cols, x.len()),
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "axis must be 0, 1, or -1 for 2-D reduction, got {other}"
            )));
        }
    };
    let by_columns = axis == 0;
    let line = |idx: usize| -> f64 {
        if by_columns {
            let col: Vec<f64> = x.iter().map(|r| r[idx]).collect();
            reduce(&col)
        } else {
            reduce(&x[idx])
        }
    };
    let threads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let work = (n_lines as u64).saturating_mul(line_len.max(1) as u64);
    // Cap thread count by total work: each spawned thread costs ~20µs (OS thread
    // create/join), so fanning out to all 64 cores for a ~1-2M-element reduction is
    // dominated by spawn overhead — measured ~1.5ms floor at 64 threads vs ~0.5-0.8ms
    // at 16-24. ~48k element-ops/thread keeps each thread busy enough to amortize its
    // spawn. BYTE-IDENTICAL (thread count never changes a per-line reduction) and never
    // spawns MORE than the old `threads.min(n_lines)`, so it is a monotone win that still
    // ramps to all cores once work justifies it (>= 64·48k ≈ 3.1M elements).
    const MIN_WORK_PER_THREAD: u64 = 48_000;
    let nthreads = if n_lines < 4 || work < 1 << 16 || threads <= 1 {
        1
    } else {
        threads
            .min(n_lines)
            .min((work / MIN_WORK_PER_THREAD).max(1) as usize)
    };
    if nthreads <= 1 {
        return Ok((0..n_lines).map(line).collect());
    }
    let chunk = n_lines.div_ceil(nthreads);
    let line = &line;
    let mut out = vec![0.0f64; n_lines];
    std::thread::scope(|scope| {
        for (ci, ochunk) in out.chunks_mut(chunk).enumerate() {
            let base = ci * chunk;
            scope.spawn(move || {
                for (k, slot) in ochunk.iter_mut().enumerate() {
                    *slot = line(base + k);
                }
            });
        }
    });
    Ok(out)
}

/// `skew` across one axis of a rectangular 2-D input — matches `scipy.stats.skew(x, axis)`.
/// One value per line; BIT-IDENTICAL to per-line 1-D [`skew`].
pub fn skew_axis_2d(x: &[Vec<f64>], axis: isize) -> Result<Vec<f64>, StatsError> {
    reduce_axis_2d(x, axis, skew)
}

