fn par_continuous_map<F>(xs: &[f64], f: F) -> Vec<f64>
where
    F: Fn(f64) -> f64 + Sync,
{
    // Parallel map for an array of costly per-point special functions (gammainc/betainc). Threads
    // are gated on WORK: at least ~2048 elements per thread, so small arrays stay serial (avoids the
    // spawn-overhead regression seen over-threading a cheap/small array).
    par_continuous_map_min(xs, 2048, f)
}

/// `par_continuous_map` with an explicit minimum elements-per-thread gate.
///
/// The default `par_continuous_map` (2048/thread) is tuned for COSTLY kernels
/// (gammainc/betainc in cdf/sf/ppf). A CHEAP kernel — e.g. a pdf that is one
/// `ln` + one `exp` — does too little work per element to amortise the thread
/// spawn at 2048/thread (measured: gamma `pdf_many` at n=4096 spawned 2 threads
/// and ran 1.9x SLOWER than the serial map, ~275µs vs ~144µs, also losing to
/// scipy's ~148µs). Such callers pass a much larger `min_per_thread` so small/
/// medium arrays stay serial (keeping the hoisted-normalizer win) and only
/// genuinely large arrays parallelise. Order-preserving ⇒ byte-identical.
fn par_continuous_map_min<F>(xs: &[f64], min_per_thread: usize, f: F) -> Vec<f64>
where
    F: Fn(f64) -> f64 + Sync,
{
    let n = xs.len();
    // Fast serial path: if the array can't even fill two threads at the gate, go
    // serial WITHOUT the `available_parallelism()` syscall (which is surprisingly
    // costly — ~tens of µs — relative to a cheap per-element kernel, and was paid
    // on every small/medium call). Byte-identical to the old `nthreads<=1` branch.
    if n < 2 * min_per_thread.max(1) {
        return xs.iter().map(|&x| f(x)).collect();
    }
    let avail = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let nthreads = (n / min_per_thread.max(1)).clamp(1, avail);
    if nthreads <= 1 {
        return xs.iter().map(|&x| f(x)).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let mut out = vec![0.0f64; n];
    let fref = &f;
    std::thread::scope(|scope| {
        for (block, xblock) in out.chunks_mut(chunk).zip(xs.chunks(chunk)) {
            scope.spawn(move || {
                for (slot, &x) in block.iter_mut().zip(xblock.iter()) {
                    *slot = fref(x);
                }
            });
        }
    });
    out
}

/// Discrete-index sibling of `par_continuous_map` for `pmf_many(&[u64])`: same WORK-gated chunked
/// parallel map (>=2048 elems/thread; small arrays stay serial) for costly per-point pmf kernels
/// (ln_gamma/ln_beta). Order-preserving -> byte-identical to `ks.iter().map(f).collect()`.
/// When `true`, [`par_discrete_map`] runs serially (the same-binary A/B knob for its discrete
/// pmf/logpmf callers); default `false` keeps the work-gated parallel map. Byte-identical.
#[doc(hidden)]
pub static PAR_DISCRETE_MAP_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

fn par_discrete_map<F>(ks: &[u64], f: F) -> Vec<f64>
where
    F: Fn(u64) -> f64 + Sync,
{
    let n = ks.len();
    // Gate at 8192 elts/thread: every caller is a MODERATE ln_gamma/ln_beta pmf/logpmf
    // (Poisson/Binomial/NegBinomial/BetaBinomial/Hypergeometric, ~50-90ns/elt). At the old
    // 2048 gate, n=4096 spawned 2 threads and ran ~2.1x SLOWER than serial (measured,
    // Binomial); break-even is ~16k — so stay serial below that (also skips the
    // ~tens-of-µs available_parallelism() syscall). Byte-identical (order-preserving).
    if PAR_DISCRETE_MAP_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < 2 * 8192 {
        return ks.iter().map(|&k| f(k)).collect();
    }
    let avail = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1);
    let nthreads = (n / 8192).clamp(1, avail);
    if nthreads <= 1 {
        return ks.iter().map(|&k| f(k)).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let mut out = vec![0.0f64; n];
    let fref = &f;
    std::thread::scope(|scope| {
        for (block, kblock) in out.chunks_mut(chunk).zip(ks.chunks(chunk)) {
            scope.spawn(move || {
                for (slot, &k) in block.iter_mut().zip(kblock.iter()) {
                    *slot = fref(k);
                }
            });
        }
    });
    out
}

fn par_beta_cdf(beta: &BetaDist, xs: &[f64]) -> Vec<f64> {
    let m = xs.len();
    // The incomplete beta is far costlier than a single transcendental, so even a
    // few thousand evaluations amortise thread spawn.
    let nthreads = if m < 2048 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(m)
            .max(1)
    };
    if nthreads <= 1 {
        return xs.iter().map(|&v| beta.cdf(v)).collect();
    }
    let chunk = m.div_ceil(nthreads);
    let mut out = vec![0.0f64; m];
    std::thread::scope(|scope| {
        for (block, xblock) in out.chunks_mut(chunk).zip(xs.chunks(chunk)) {
            scope.spawn(move || {
                for (slot, &x) in block.iter_mut().zip(xblock.iter()) {
                    *slot = beta.cdf(x);
                }
            });
        }
    });
    out
}

pub fn hdquantiles(data: &[f64], prob: &[f64]) -> Vec<f64> {
    let mut sorted: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    let n = sorted.len();
    if n < 2 {
        return prob.iter().map(|_| f64::NAN).collect();
    }
    let nf = n as f64;
    prob.iter()
        .map(|&p| {
            if p <= 0.0 {
                return sorted[0];
            }
            if p >= 1.0 {
                return sorted[n - 1];
            }
            let a = (nf + 1.0) * p;
            let b = (nf + 1.0) * (1.0 - p);
            let beta = BetaDist::new(a, b);
            // The k-loop reads beta.cdf at (k+1)/n and k/n, so consecutive k share
            // a breakpoint; evaluate each of the n+1 distinct breakpoints' CDF once
            // (halving the incomplete-beta calls), in parallel for large n. The cdf
            // values and the left-to-right weighted sum are unchanged -> identical.
            let breakpoints: Vec<f64> = (0..=n).map(|j| j as f64 / nf).collect();
            let cdfs = par_beta_cdf(&beta, &breakpoints);
            let mut hd_sum = 0.0;
            for (k, &val) in sorted.iter().enumerate() {
                let w = cdfs[k + 1] - cdfs[k];
                hd_sum += w * val;
            }
            hd_sum
        })
        .collect()
}

/// Computes the Harrell-Davis median estimate.
///
/// Matches `scipy.stats.mstats.hdmedian(data)`.
pub fn hdmedian(data: &[f64]) -> f64 {
    let result = hdquantiles(data, &[0.5]);
    result[0]
}

/// Computes standard error of Harrell-Davis quantile estimates by jackknife.
///
/// Matches `scipy.stats.mstats.hdquantiles_sd(data, prob)`.
pub fn hdquantiles_sd(data: &[f64], prob: &[f64]) -> Vec<f64> {
    let mut sorted: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    let n = sorted.len();
    if n < 2 {
        return prob.iter().map(|_| f64::NAN).collect();
    }
    let nf = n as f64;
    let nm1 = n - 1;
    let nm1f = nm1 as f64;

    prob.iter()
        .map(|&p| {
            if p <= 0.0 || p >= 1.0 {
                return f64::NAN;
            }
            let a = nf * p;
            let b = nf * (1.0 - p);
            let beta = BetaDist::new(a, b);

            let vv: Vec<f64> = (0..n).map(|i| i as f64 / nm1f).collect();
            let beta_cdf = par_beta_cdf(&beta, &vv);
            let w: Vec<f64> = (0..nm1).map(|i| beta_cdf[i + 1] - beta_cdf[i]).collect();

            let mut mx = vec![0.0; n];
            let mut cumsum = 0.0;
            for i in 1..n {
                cumsum += w[i - 1] * sorted[i - 1];
                mx[i] = cumsum;
            }
            let mut right_cumsum: Vec<f64> = vec![0.0; nm1];
            cumsum = 0.0;
            for i in (0..nm1).rev() {
                cumsum += w[i] * sorted[i + 1];
                right_cumsum[i] = cumsum;
            }
            for i in 0..nm1 {
                mx[i] += right_cumsum[i];
            }

            let mean_mx = mx.iter().sum::<f64>() / nf;
            let var_mx = mx.iter().map(|&x| (x - mean_mx).powi(2)).sum::<f64>() / nf;
            (var_mx * nm1f).sqrt()
        })
        .collect()
}

/// Computes empirical quantiles using configurable plotting positions.
///
/// Maritz-Jarrett estimates of the standard error of sample quantiles,
/// matching `scipy.stats.mstats.mjci(data, prob)` for 1-D unmasked input.
///
/// For each quantile `p`, with `m = int(p*n + 0.5)` and the order statistics
/// `x_(1..n)` (sorted), the weights are
/// `W_j = I_{j/n}(m-1, n-m) - I_{(j-1)/n}(m-1, n-m)` (`I` the regularized
/// incomplete beta), and the SE is `sqrt(Σ W_j x_j² − (Σ W_j x_j)²)`. Degenerate
/// beta parameters (`m == 1` or `m == n`) yield `NaN`, as in scipy.
///
/// Toggle forcing [`mjci`]'s per-breakpoint incomplete-beta map onto the serial
/// path, for A/B measurement. Default `false` = the breakpoints fan across cores.
pub static MJCI_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

#[must_use]
pub fn mjci(data: &[f64], prob: &[f64]) -> Vec<f64> {
    let mut sorted: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = sorted.len();
    let nf = n as f64;
    prob.iter()
        .map(|&p| {
            let m = (p * nf + 0.5) as i64; // int() truncation (p*n+0.5 >= 0)
            let a = (m - 1) as f64;
            let b = (n as i64 - m) as f64;
            if a <= 0.0 || b <= 0.0 {
                return f64::NAN;
            }
            // The weights are consecutive differences of I_{j/n}(a,b) for j=0..=n, so
            // each of the n+1 breakpoints' incomplete beta is INDEPENDENT — precompute
            // them across cores (work-gated), then take the ordered weighted sum. The
            // betainc values and the left-to-right c1/c2 accumulation are unchanged, so
            // this is BYTE-IDENTICAL to the serial `prev`/`cur` loop; betainc is a costly
            // continued fraction, so the parallel map is the dominant win (mirrors the
            // hdquantiles/hdquantiles_sd breakpoint precompute).
            let breakpoints: Vec<f64> = (0..=n).map(|j| j as f64 / nf).collect();
            let cdfs = if MJCI_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
                breakpoints
                    .iter()
                    .map(|&x| regularized_incomplete_beta(a, b, x))
                    .collect::<Vec<f64>>()
            } else {
                par_continuous_map(&breakpoints, |x| regularized_incomplete_beta(a, b, x))
            };
            let mut c1 = 0.0_f64;
            let mut c2 = 0.0_f64;
            for j in 1..=n {
                let w = cdfs[j] - cdfs[j - 1];
                let d = sorted[j - 1];
                c1 += w * d;
                c2 += w * d * d;
            }
            (c2 - c1 * c1).max(0.0).sqrt()
        })
        .collect()
}

/// Matches `scipy.stats.mstats.mquantiles_cimj(data, prob, alpha)`.
///
/// Computes the `1 - alpha` confidence interval for the selected quantiles,
/// using the Maritz-Jarrett estimators of the quantile standard errors
/// ([`mjci`]). The point estimates use `mquantiles` with `alphap = betap = 0`
/// (R type 6). Returns `(ci_lower, ci_upper)`, each of length `prob.len()`:
/// `xq ∓ z · smj` with `z = Φ⁻¹(1 − alpha/2)`. `alpha` is folded to
/// `min(alpha, 1 − alpha)` as in scipy.
#[must_use]
pub fn mquantiles_cimj(data: &[f64], prob: &[f64], alpha: f64) -> (Vec<f64>, Vec<f64>) {
    let alpha = alpha.min(1.0 - alpha);
    let z = Normal::standard().ppf(1.0 - alpha / 2.0);
    let xq = mquantiles(data, prob, 0.0, 0.0);
    let smj = mjci(data, prob);
    let lo = xq.iter().zip(&smj).map(|(&q, &s)| q - z * s).collect();
    let hi = xq.iter().zip(&smj).map(|(&q, &s)| q + z * s).collect();
    (lo, hi)
}

/// Matches `scipy.stats.mstats.mquantiles(a, prob, alphap, betap)`.
/// Returns quantiles at the specified probabilities using the formula:
/// `Q(p) = (1-g)*x[j] + g*x[j+1]`, where `j = floor(n*p + m)`, `m = alphap + p*(1 - alphap - betap)`.
///
/// Common (alphap, betap) values:
/// - (0.4, 0.4): Cunnane (default) - approximately quantile unbiased
/// - (0.5, 0.5): R type 5 - piecewise linear
/// - (1.0, 1.0): R type 7 - R default
/// - (0.0, 0.0): R type 6
/// - (1/3, 1/3): R type 8 - approximately median-unbiased
pub fn mquantiles(data: &[f64], prob: &[f64], alphap: f64, betap: f64) -> Vec<f64> {
    let mut sorted: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    let n = sorted.len();
    if n == 0 {
        return prob.iter().map(|_| f64::NAN).collect();
    }
    let nf = n as f64;
    prob.iter()
        .map(|&p| {
            if !(0.0..=1.0).contains(&p) {
                return f64::NAN;
            }
            let m = alphap + p * (1.0 - alphap - betap);
            // scipy.stats.mstats.mquantiles formula:
            //   aleph = n*p + m
            //   k     = clip(floor(aleph), 1, n-1)        — clip applied to FLOOR
            //   gamma = (aleph - k).clip(0, 1)            — gamma uses unclipped aleph
            //   Q(p)  = (1 - gamma)*data[k-1] + gamma*data[k]
            // fsci's previous code used `saturating_sub(1)` on the floor
            // without clipping (silent k=0/gamma=aleph for sub-1 alephs).
            // See [frankenscipy-13w1q].
            let aleph = nf * p + m;
            let k_unclipped = aleph.floor();
            let k = if n >= 2 {
                k_unclipped.clamp(1.0, nf - 1.0) as usize
            } else {
                1
            };
            let gamma = (aleph - k as f64).clamp(0.0, 1.0);
            let lo = k - 1;
            let hi = k.min(n - 1);
            (1.0 - gamma) * sorted[lo] + gamma * sorted[hi]
        })
        .collect()
}

/// Coefficient of variation (std / mean).
///
/// Matches `scipy.stats.variation(a)`.
pub fn variation(data: &[f64]) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let n = data.len() as f64;
    // Mean via `par_sum` + Σ(x−mean)² via `sum_sq_dev` — both work-gated parallel (byte-identical below
    // the gate). variation was a serial straggler vs the parallel skew/kurtosis/describe moment loops.
    let mean_val = par_sum(data) / n;
    let var: f64 = sum_sq_dev(data, mean_val) / n;
    var.sqrt() / mean_val
}

/// When `true`, [`variation_weighted`] runs its weights finite-check, `Σw` and the weighted-mean sum
/// as separate passes (the ORIG behaviour); default `false` folds all three into one pass over
/// (data, weights). Byte-identical.
#[doc(hidden)]
pub static VARIATION_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Weighted coefficient of variation (weighted std / weighted mean).
///
/// Matches `scipy.stats.variation` with weights parameter.
pub fn variation_weighted(data: &[f64], weights: &[f64]) -> f64 {
    if data.len() < 2 || data.len() != weights.len() {
        return f64::NAN;
    }
    // BYTE-IDENTICAL fusion: the weights finite/non-negative check, `Σw`, and the weighted-mean
    // numerator `Σw·x` are three INDEPENDENT reductions — fold them into ONE pass. Each Σ keeps its
    // left-to-right order and `w * x` expression; a bad weight still returns NaN (polluted sums
    // discarded exactly as the original early-out did). The `var` pass depends on the mean.
    let (total_w, mean_val) = if VARIATION_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed)
    {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return f64::NAN;
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return f64::NAN;
        }
        let mean_val: f64 = data.iter().zip(weights).map(|(&x, &w)| w * x).sum::<f64>() / total_w;
        (total_w, mean_val)
    } else {
        let mut total_w = 0.0f64;
        let mut sum_wx = 0.0f64;
        let mut valid = true;
        for (&x, &w) in data.iter().zip(weights) {
            valid &= w.is_finite() && w >= 0.0;
            total_w += w;
            sum_wx += w * x;
        }
        if !valid {
            return f64::NAN;
        }
        if total_w <= 0.0 {
            return f64::NAN;
        }
        (total_w, sum_wx / total_w)
    };
    if mean_val == 0.0 {
        return f64::NAN;
    }
    let var: f64 = data
        .iter()
        .zip(weights)
        .map(|(&x, &w)| w * (x - mean_val).powi(2))
        .sum::<f64>()
        / total_w;
    var.sqrt() / mean_val
}

fn mean_std_ddof(data: &[f64], ddof: usize) -> Option<(f64, f64)> {
    let n = data.len();
    if n == 0 || n <= ddof {
        return None;
    }
    // Mean via `par_sum` and Σ(x−mean)² via `sum_sq_dev` — both work-gated parallel (byte-identical
    // below the gate). This primitive feeds the whole zscore family (zscore/zscore_ddof/gzscore); with
    // the SS reduction and the `(x−mean)/std` output map already parallel, the serial mean sum was the
    // remaining residual pass — now parallel too.
    let mean = par_sum(data) / n as f64;
    let var = sum_sq_dev(data, mean) / (n - ddof) as f64;
    Some((mean, var.sqrt()))
}

/// When `true`, [`zscore`] runs its `(x - mean)/std` output map serially (the ORIG behaviour);
/// default `false` fans it across threads. Byte-identical.
#[doc(hidden)]
pub static ZSCORE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute z-scores: (x - mean) / std.
///
/// Matches `scipy.stats.zscore(a)`.
pub fn zscore(data: &[f64]) -> Vec<f64> {
    let Some((mean_val, std_val)) = mean_std_ddof(data, 0) else {
        return vec![f64::NAN; data.len()];
    };
    if std_val == 0.0 {
        return vec![f64::NAN; data.len()];
    }
    // `mean_std_ddof` is float Σ (serial), but the `(x - mean)/std` output map is a per-element pure
    // function of its index — fan it across threads via the order-preserving `par_continuous_map_min`
    // (BYTE-IDENTICAL to `data.iter().map(..).collect()`). `ZSCORE_FORCE_SERIAL` restores the serial map.
    // 800k/thread gate (was 4096): the map is LIGHT (a subtract + divide), so the old eager gate
    // OVER-SUBSCRIBED medium arrays — measured 0.25x@200k, 0.43x@500k, 0.59x@1M (10 threads on a
    // sub-10ms op). 800k keeps arrays below ~1.6M serial while n≥8M still saturates the cores.
    if ZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| (x - mean_val) / std_val).collect()
    } else {
        par_continuous_map_min(data, 800_000, move |x| (x - mean_val) / std_val)
    }
}

/// When `true`, [`zscore_weighted`] runs its weights finite-check, `Σw` and the weighted-mean sum as
/// separate passes (the ORIG behaviour); default `false` folds all three into one pass over
/// (data, weights). Byte-identical.
#[doc(hidden)]
pub static ZSCORE_W_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute weighted z-scores: (x - weighted_mean) / weighted_std.
///
/// Matches `scipy.stats.zscore` with weights parameter.
pub fn zscore_weighted(data: &[f64], weights: &[f64]) -> Vec<f64> {
    if data.is_empty() || data.len() != weights.len() {
        return vec![f64::NAN; data.len()];
    }
    // BYTE-IDENTICAL fusion: the finite/non-negative check, `Σw`, and the weighted-mean numerator
    // `Σw·x` are three INDEPENDENT reductions over the input — compute them in ONE pass. Each Σ keeps
    // its exact left-to-right order and `w * x` expression; a bad weight still returns the NaN vector
    // (the polluted sums discarded exactly as the original early-out discarded them). The `var` pass
    // stays separate — it depends on the mean.
    let (total_w, sum_wx) = if ZSCORE_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return vec![f64::NAN; data.len()];
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return vec![f64::NAN; data.len()];
        }
        let sum_wx: f64 = data.iter().zip(weights).map(|(&x, &w)| w * x).sum::<f64>();
        (total_w, sum_wx)
    } else {
        let mut total_w = 0.0f64;
        let mut sum_wx = 0.0f64;
        let mut valid = true;
        for (&x, &w) in data.iter().zip(weights) {
            valid &= w.is_finite() && w >= 0.0;
            total_w += w;
            sum_wx += w * x;
        }
        if !valid {
            return vec![f64::NAN; data.len()];
        }
        if total_w <= 0.0 {
            return vec![f64::NAN; data.len()];
        }
        (total_w, sum_wx)
    };
    let mean_val: f64 = sum_wx / total_w;
    let var: f64 = data
        .iter()
        .zip(weights)
        .map(|(&x, &w)| w * (x - mean_val).powi(2))
        .sum::<f64>()
        / total_w;
    let std_val = var.sqrt();
    if std_val == 0.0 {
        return vec![f64::NAN; data.len()];
    }
    // Output map straggler: the weighted mean/var preambles are done, but `(x-mean)/std` stayed serial.
    // It is a per-element pure function of its index, so fan it across cores via the order-preserving
    // `par_continuous_map_min` — BYTE-IDENTICAL to `iter().map(..).collect()`. Shares [`ZSCORE_FORCE_SERIAL`].
    // 800k/thread gate: light map, keep <1.6M serial (avoids small-array thread over-subscription).
    if ZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| (x - mean_val) / std_val).collect()
    } else {
        par_continuous_map_min(data, 800_000, move |x| (x - mean_val) / std_val)
    }
}

/// Compute robust z-scores using median and IQR.
///
/// robust_zscore = (x - median) / (IQR * scale)
///
/// Uses the IQR (interquartile range) scaled to match the normal distribution
/// standard deviation (IQR / 1.349).
///
/// This is more resistant to outliers than standard z-scores.
///
/// # Arguments
/// * `data` - Input data
/// * `scale` - If true (default), scale IQR by 1.349 to match normal std
/// When `true`, [`robust_zscore`] computes its median and IQR via separate `median(data)` and
/// `iqr(data)` calls (the ORIG behaviour — 3 buffer copies + 3 independent quickselects); default
/// `false` hoists them onto ONE buffer copy with cascaded selects. Byte-identical. A/B knob.
#[doc(hidden)]
pub static ROBUST_ZSCORE_HOIST_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn robust_zscore(data: &[f64], scale: bool) -> Vec<f64> {
    if data.len() < 4 {
        return vec![f64::NAN; data.len()];
    }
    let n = data.len();

    // median(data) and iqr(data) each COPY data and quickselect independently (3 copies, 3 selects,
    // ~90% of the runtime). Hoist onto ONE copy: select Q3, then the median rank from the Q3 prefix,
    // then Q1 from the median prefix (each `select_ranks` leaves buf[..=hi] as the hi+1 smallest, so
    // the ranks cascade). BYTE-IDENTICAL: each order statistic is unique, and each value uses its own
    // fn's exact formula — median's even-case `(lo+hi)/2.0`, iqr's frac-weighted linear interpolation.
    let (med, iqr_val) = if ROBUST_ZSCORE_HOIST_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        (median(data), iqr(data))
    } else {
        let qidx = |q: f64| {
            let pos = q * (n - 1) as f64;
            let lo = pos.floor() as usize;
            let hi = pos.ceil() as usize;
            (lo, hi, pos - lo as f64)
        };
        let (lo3, hi3, f3) = qidx(0.75);
        let (lo1, hi1, f1) = qidx(0.25);
        // Median ranks exactly as `median_in_place`: even → (n/2-1, n/2) averaged; odd → (n/2, n/2).
        let (med_lo, med_hi) = if n.is_multiple_of(2) {
            (n / 2 - 1, n / 2)
        } else {
            (n / 2, n / 2)
        };
        let mut buf = data.to_vec();
        let (v_lo3, v_hi3) = select_ranks(&mut buf, lo3, hi3);
        let q3 = if lo3 == hi3 {
            v_lo3
        } else {
            v_lo3 * (1.0 - f3) + v_hi3 * f3
        };
        let (v_ml, v_mh) = select_ranks(&mut buf[..=hi3], med_lo, med_hi);
        let med = if n.is_multiple_of(2) {
            (v_ml + v_mh) / 2.0
        } else {
            v_ml
        };
        let (v_lo1, v_hi1) = select_ranks(&mut buf[..=med_hi], lo1, hi1);
        let q1 = if lo1 == hi1 {
            v_lo1
        } else {
            v_lo1 * (1.0 - f1) + v_hi1 * f1
        };
        (med, q3 - q1)
    };

    if iqr_val == 0.0 {
        return vec![f64::NAN; data.len()];
    }

    let scale_factor = if scale {
        iqr_val / 1.3489795003921634
    } else {
        iqr_val
    };

    data.iter().map(|&x| (x - med) / scale_factor).collect()
}

/// When `true`, [`mad_zscore`] computes its MAD via `mad(data, 1.0)`, which recomputes
/// `median(data)` internally (the ORIG double median). Default `false` feeds the already-computed
/// median to `mad_from_median`, halving the median selects from 2 to 1. Byte-identical. A/B perf gate.
#[doc(hidden)]
pub static MAD_ZSCORE_HOIST_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute robust z-scores using median and MAD.
///
/// mad_zscore = (x - median) / MAD
///
/// Uses the median absolute deviation scaled to match the normal distribution
/// standard deviation (MAD * 1.4826).
///
/// Even more resistant to outliers than IQR-based robust z-scores.
///
/// # Arguments
/// * `data` - Input data
/// * `scale` - If true (default), scale MAD by 1.4826 to match normal std
pub fn mad_zscore(data: &[f64], scale: bool) -> Vec<f64> {
    if data.len() < 2 {
        return vec![f64::NAN; data.len()];
    }

    // `mad(data, 1.0)` recomputes `median(data)` internally; reuse the `med` we already have via
    // `mad_from_median` (byte-identical when the fed median equals `median(data)`), dropping a
    // redundant O(n) median select + allocation.
    let med = median(data);
    let scale_factor = if scale { 1.4826022185056018 } else { 1.0 };
    let mad_raw = if MAD_ZSCORE_HOIST_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        mad(data, 1.0)
    } else {
        mad_from_median(data, med, 1.0)
    };
    let mad_val = mad_raw * scale_factor;

    if mad_val == 0.0 {
        return vec![f64::NAN; data.len()];
    }

    data.iter().map(|&x| (x - med) / mad_val).collect()
}

/// When `true`, [`min_max_scale`] runs its min/max folds and scale map serially (the ORIG behaviour);
/// default `false` chunks the min/max reduce and fans the output map across threads. Byte-identical.
#[doc(hidden)]
pub static MIN_MAX_SCALE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Min-max scale data to a given range.
///
/// Scales data linearly to [feature_min, feature_max].
/// Default range is [0, 1].
///
/// scaled = (x - min) / (max - min) * (feature_max - feature_min) + feature_min
pub fn min_max_scale(data: &[f64], feature_range: Option<(f64, f64)>) -> Vec<f64> {
    if data.is_empty() {
        return vec![];
    }

    let (feature_min, feature_max) = feature_range.unwrap_or((0.0, 1.0));

    // The min/max reduce and the `(x-min)*scale+feature_min` output map are both parallelizable
    // byte-identically: `f64::min`/`f64::max` are associative + commutative (NaN-ignoring identically
    // in any chunk, signed-zero order-independent), and the map is a per-element pure function of its
    // index. FUSING the min/max preamble was IN-FLOOR (the output map dominates); PARALLELIZING the
    // map (order-preserving `par_continuous_map_min`) is the win. `MIN_MAX_SCALE_FORCE_SERIAL` A/B.
    let n = data.len();
    let (min_val, max_val) =
        if MIN_MAX_SCALE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
            (
                data.iter().copied().fold(f64::INFINITY, f64::min),
                data.iter().copied().fold(f64::NEG_INFINITY, f64::max),
            )
        } else {
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n / 4096)
                .max(1);
            if nthreads <= 1 {
                (
                    data.iter().copied().fold(f64::INFINITY, f64::min),
                    data.iter().copied().fold(f64::NEG_INFINITY, f64::max),
                )
            } else {
                let chunk = n.div_ceil(nthreads);
                let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
                    data.chunks(chunk)
                        .map(|c| {
                            scope.spawn(move || {
                                (
                                    c.iter().copied().fold(f64::INFINITY, f64::min),
                                    c.iter().copied().fold(f64::NEG_INFINITY, f64::max),
                                )
                            })
                        })
                        .collect::<Vec<_>>()
                        .into_iter()
                        .map(|h| h.join().expect("min_max_scale chunk panicked"))
                        .collect()
                });
                parts.into_iter().fold(
                    (f64::INFINITY, f64::NEG_INFINITY),
                    |(amn, amx), (bmn, bmx)| (f64::min(amn, bmn), f64::max(amx, bmx)),
                )
            }
        };

    if !min_val.is_finite() || !max_val.is_finite() {
        return vec![f64::NAN; n];
    }

    let range = max_val - min_val;
    if range == 0.0 {
        return vec![(feature_min + feature_max) / 2.0; n];
    }

    let scale = (feature_max - feature_min) / range;
    if MIN_MAX_SCALE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter()
            .map(|&x| (x - min_val) * scale + feature_min)
            .collect()
    } else {
        par_continuous_map_min(data, 4096, move |x| (x - min_val) * scale + feature_min)
    }
}

/// When `true`, [`center`] runs its `x - mean` output map serially (the ORIG behaviour); default
/// `false` fans it across threads. Byte-identical.
#[doc(hidden)]
pub static CENTER_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Center data by subtracting the mean.
///
/// Returns data with zero mean.
pub fn center(data: &[f64]) -> Vec<f64> {
    if data.is_empty() {
        return vec![];
    }
    // `mean` is a float Σ (reassociates ⇒ stays serial for byte-exactness), but the `x - mean`
    // output map is a per-element pure function of its index — fan it across threads via the
    // order-preserving `par_continuous_map_min` (BYTE-IDENTICAL to `data.iter().map(..).collect()`).
    let mean_val = data.iter().sum::<f64>() / data.len() as f64;
    if CENTER_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| x - mean_val).collect()
    } else {
        par_continuous_map_min(data, 4096, move |x| x - mean_val)
    }
}

/// When `true`, [`scale`] runs its `x / std` output map serially (the ORIG behaviour); default
/// `false` fans it across threads. Byte-identical.
#[doc(hidden)]
pub static SCALE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Scale data by dividing by the standard deviation.
///
/// Returns data with unit variance (if ddof=0) or unit sample variance (if ddof=1).
pub fn scale(data: &[f64], ddof: usize) -> Vec<f64> {
    if data.is_empty() || data.len() <= ddof {
        return vec![f64::NAN; data.len()];
    }

    let n = data.len() as f64;
    // `mean` and `var` are float Σ (reassociate ⇒ stay serial), but the `x / std` output map is a
    // per-element pure function of its index — fan it across threads via the order-preserving
    // `par_continuous_map_min` (BYTE-IDENTICAL to `data.iter().map(..).collect()`).
    let mean_val = data.iter().sum::<f64>() / n;
    let var: f64 = data.iter().map(|&x| (x - mean_val).powi(2)).sum::<f64>() / (n - ddof as f64);
    let std_val = var.sqrt();

    if std_val == 0.0 {
        return vec![f64::NAN; data.len()];
    }

    if SCALE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| x / std_val).collect()
    } else {
        par_continuous_map_min(data, 4096, move |x| x / std_val)
    }
}

/// Compute relative z-scores using the mean and variance of `compare`.
///
/// Matches the core 1D behavior of `scipy.stats.zmap(scores, compare)`.
pub fn zmap(scores: &[f64], compare: &[f64]) -> Vec<f64> {
    zmap_ddof(scores, compare, 0)
}

/// Compute relative z-scores with an explicit degrees-of-freedom correction.
///
/// Matches the core 1D behavior of `scipy.stats.zmap(scores, compare, ddof=...)`.
pub fn zmap_ddof(scores: &[f64], compare: &[f64], ddof: usize) -> Vec<f64> {
    let Some((mean, std)) = mean_std_ddof(compare, ddof) else {
        return vec![f64::NAN; scores.len()];
    };

    // `mean_std_ddof(compare)` is float Σ (serial), but the `(score - mean)/std` map over `scores`
    // is a per-element pure function of its index — fan it across threads via the order-preserving
    // `par_continuous_map_min` (BYTE-IDENTICAL to `scores.iter().map(..).collect()`). The same-slice
    // NaN-fill special case runs AFTER the map, unchanged. `ZSCORE_FORCE_SERIAL` (shared knob).
    let mut out: Vec<f64> = if ZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        scores.iter().map(|&score| (score - mean) / std).collect()
    } else {
        par_continuous_map_min(scores, 4096, move |score| (score - mean) / std)
    };

    // SciPy's zscore special-cases the exact same array object by replacing
    // constant slices with NaN rather than leaving mixed NaN/inf outputs.
    let same_slice =
        core::ptr::eq(scores.as_ptr(), compare.as_ptr()) && scores.len() == compare.len();
    if same_slice && std <= (f64::EPSILON * mean).abs() {
        out.fill(f64::NAN);
    }

    out
}

/// Compute weighted relative z-scores using the weighted mean and variance of `compare`.
///
/// Matches `scipy.stats.zmap` with weights parameter.
pub fn zmap_weighted(scores: &[f64], compare: &[f64], weights: &[f64]) -> Vec<f64> {
    if compare.is_empty() || compare.len() != weights.len() {
        return vec![f64::NAN; scores.len()];
    }
    // BYTE-IDENTICAL fusion (same shape as `zscore_weighted`): the weights finite/non-negative
    // check, `Σw`, and the weighted-mean numerator `Σw·x` are three INDEPENDENT reductions over
    // `compare`/`weights` — fold them into ONE pass. Each Σ keeps its left-to-right order and
    // `w * x` expression; a bad weight still returns the NaN vector (polluted sums discarded exactly
    // as the original early-out discarded them). The `var` pass depends on the mean and stays separate.
    let (total_w, sum_wx) = if ZSCORE_W_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        if weights.iter().any(|&w| !w.is_finite() || w < 0.0) {
            return vec![f64::NAN; scores.len()];
        }
        let total_w: f64 = weights.iter().sum();
        if total_w <= 0.0 {
            return vec![f64::NAN; scores.len()];
        }
        let sum_wx: f64 = compare
            .iter()
            .zip(weights)
            .map(|(&x, &w)| w * x)
            .sum::<f64>();
        (total_w, sum_wx)
    } else {
        let mut total_w = 0.0f64;
        let mut sum_wx = 0.0f64;
        let mut valid = true;
        for (&x, &w) in compare.iter().zip(weights) {
            valid &= w.is_finite() && w >= 0.0;
            total_w += w;
            sum_wx += w * x;
        }
        if !valid {
            return vec![f64::NAN; scores.len()];
        }
        if total_w <= 0.0 {
            return vec![f64::NAN; scores.len()];
        }
        (total_w, sum_wx)
    };
    let mean: f64 = sum_wx / total_w;
    let var: f64 = compare
        .iter()
        .zip(weights)
        .map(|(&x, &w)| w * (x - mean).powi(2))
        .sum::<f64>()
        / total_w;
    let std = var.sqrt();
    if std == 0.0 {
        return vec![f64::NAN; scores.len()];
    }
    // Output map straggler (like `zscore_weighted`): the weighted mean/var of `compare` are fused, but
    // the `(s-mean)/std` map over `scores` stayed serial. It is a per-element pure function of its index,
    // so fan it across cores via the order-preserving `par_continuous_map_min` — BYTE-IDENTICAL to
    // `iter().map(..).collect()`. Shares [`ZSCORE_FORCE_SERIAL`]; 800k gate (light map) keeps <1.6M serial.
    if ZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        scores.iter().map(|&s| (s - mean) / std).collect()
    } else {
        par_continuous_map_min(scores, 800_000, move |s| (s - mean) / std)
    }
}

/// Compute the geometric z-score for strictly positive data.
///
/// Matches the core 1D behavior of `scipy.stats.gzscore(a)`.
pub fn gzscore(data: &[f64]) -> Vec<f64> {
    gzscore_ddof(data, 0)
}

/// Compute the geometric z-score with an explicit degrees-of-freedom correction.
///
/// Matches the core 1D behavior of `scipy.stats.gzscore(a, ddof=...)`.
/// `ln(data)` as a vector, the shared materialized heavy map of the geometric z-scores
/// (`gzscore`/`gzscore_ddof`/`gzscore_weighted`), whose downstream `zscore` reads the values across
/// several passes (mean, std, per-element output). Parallelize ONLY the `ln` map via the
/// order-preserving `par_continuous_map` → BYTE-IDENTICAL to `data.iter().map(ln).collect()` (same
/// values, index order). `GZSCORE_FORCE_SERIAL` restores the serial map (same-binary A/B).
fn gzscore_ln_vec(data: &[f64]) -> Vec<f64> {
    if GZSCORE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        data.iter().map(|&x| x.ln()).collect()
    } else {
        par_continuous_map(data, |x| x.ln())
    }
}

/// See [`gzscore_ln_vec`]. When `true`, the geometric z-scores build `ln(data)` serially (ORIG); when
/// `false` (default), the `ln` map fans across cores. Byte-identical either way. For the A/B perf gate.
#[doc(hidden)]
pub static GZSCORE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn gzscore_ddof(data: &[f64], ddof: usize) -> Vec<f64> {
    let logged = gzscore_ln_vec(data);
    zscore_ddof(&logged, ddof)
}

/// Compute the weighted geometric z-score for strictly positive data.
///
/// Matches `scipy.stats.gzscore` with weights parameter.
pub fn gzscore_weighted(data: &[f64], weights: &[f64]) -> Vec<f64> {
    if data.is_empty() || data.len() != weights.len() {
        return vec![f64::NAN; data.len()];
    }
    if data.iter().any(|&x| x <= 0.0 || !x.is_finite()) {
        return vec![f64::NAN; data.len()];
    }
    // Constant data has no log-variation; the geometric z-scores are all 0 by convention (the
    // shared zscore_weighted would return 0/0 = NaN). circular_and_gzscore_weighted_match_analytic.
    if data.windows(2).all(|w| w[0] == w[1]) {
        return vec![0.0; data.len()];
    }
    let logged = gzscore_ln_vec(data);
    zscore_weighted(&logged, weights)
}

/// Compute the q-th percentile of data.
///
/// Uses linear interpolation between data points.
/// `q` should be in [0, 100].
///
/// Matches `numpy.percentile(data, q)`.
pub fn percentile(data: &[f64], q: f64) -> f64 {
    if data.is_empty() || q.is_nan() || data.iter().any(|v| v.is_nan()) {
        return f64::NAN;
    }
    let q_frac = (q / 100.0).clamp(0.0, 1.0);
    quantile_select(data, q_frac)
}

/// Compute the weighted percentile of data.
///
/// Uses linear interpolation between weighted data points.
/// `q` should be in [0, 100].
pub fn percentile_weighted(data: &[f64], q: f64, weights: &[f64]) -> f64 {
    if q.is_nan() {
        return f64::NAN;
    }
    let q_frac = (q / 100.0).clamp(0.0, 1.0);
    let result = quantile_weighted(data, &[q_frac], weights);
    result.first().copied().unwrap_or(f64::NAN)
}

/// Compute the percentile rank of a score relative to a list of scores.
///
/// Returns the percentage of values in `data` that are less than or equal to
/// the given `score`, depending on the `kind` parameter.
///
/// # Arguments
/// * `data` - Input data array
/// * `score` - Score to compute percentile rank for
/// * `kind` - Method of calculation:
///   - `"rank"` (default): Average percentage ranking of score
///   - `"weak"`: Percentage of values < score
///   - `"strict"`: Percentage of values <= score
///   - `"mean"`: Average of weak and strict
///
/// When `true`, [`percentileofscore`] counts `< score` and `<= score` in two separate passes
/// (the ORIG behaviour); default `false` counts both in one pass. Byte-identical. A/B gate.
#[doc(hidden)]
pub static PERCENTILEOFSCORE_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Matches `scipy.stats.percentileofscore(a, score, kind)`.
///
/// When [`PERCENTILEOFSCORE_FUSE_DISABLE`] is `true`, the `<`/`<=` counts run as two separate
/// passes (the ORIG behaviour); default `false` counts both in one pass. Byte-identical.
pub fn percentileofscore(data: &[f64], score: f64, kind: Option<&str>) -> f64 {
    if data.is_empty() {
        return f64::NAN;
    }
    let kind = kind.unwrap_or("rank");
    let n = data.len() as f64;

    // scipy uses exact comparisons; equality is implied by right - left.
    // A tolerance-based equality check double-counts near-but-unequal values
    // (e.g. 0.3 vs 0.1+0.2), which can push `right` above n.
    //   left  = count(< score)
    //   right = count(<= score)
    //   plus1 = 1 if score is in data (left < right) else 0
    //   rank  = (left + right + plus1) * 50 / n
    //   weak  = right * 100 / n            (% values <= score)
    //   strict= left * 100 / n             (% values < score)
    //   mean  = (left + right) * 50 / n    (avg of weak and strict)
    // `left = count(< score)` and `right = count(<= score)` are two independent traversals;
    // count both in ONE pass. BYTE-IDENTICAL: the counts are exact integers, independent of
    // order, and every `x < score` also satisfies `x <= score`.
    let (left, right) = if PERCENTILEOFSCORE_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed)
    {
        (
            data.iter().filter(|&&x| x < score).count() as f64,
            data.iter().filter(|&&x| x <= score).count() as f64,
        )
    } else {
        // The fused (left, right) count is a byte-identical integer reduction — the counts are
        // order-independent and partials sum exactly — so fan it across cores for large inputs (each
        // chunk counts its own (l, r)). The nested-branch count is very cheap and only becomes
        // memory-bandwidth-bound (i.e. worth spreading across cores) at huge n: measured 0.65x @4M
        // (thread overhead dominates a cache-resident count) vs 2.64x @16M → gate 1<<23. The serial
        // nested-branch path (its short-circuit does ~1.5 compares/element) is kept below the gate.
        let count_chunk = |ds: &[f64]| -> (usize, usize) {
            let mut l = 0usize;
            let mut r = 0usize;
            for &x in ds {
                if x <= score {
                    r += 1;
                    if x < score {
                        l += 1;
                    }
                }
            }
            (l, r)
        };
        let (l, r) = if data.len() < (1 << 23) {
            count_chunk(data)
        } else {
            let n_len = data.len();
            let nthreads = std::thread::available_parallelism()
                .map(std::num::NonZero::get)
                .unwrap_or(1)
                .min(n_len / (1 << 16))
                .max(1);
            let chunk = n_len.div_ceil(nthreads);
            let count_chunk = &count_chunk;
            let parts: Vec<(usize, usize)> = std::thread::scope(|scope| {
                data.chunks(chunk)
                    .map(|ds| scope.spawn(move || count_chunk(ds)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("percentileofscore worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0usize, 0usize), |(al, ar), (cl, cr)| (al + cl, ar + cr))
        };
        (l as f64, r as f64)
    };
    let plus1: f64 = if left < right { 1.0 } else { 0.0 };
    match kind {
        "rank" => (left + right + plus1) * 50.0 / n,
        "weak" => right * 100.0 / n,
        "strict" => left * 100.0 / n,
        "mean" => (left + right) * 50.0 / n,
        _ => f64::NAN,
    }
}

/// Compute scores at one or more percentiles of the input sequence.
///
/// Matches the implemented SciPy `scoreatpercentile(a, per, limit=..., interpolation_method=...)`
/// behavior for 1-D inputs.
pub fn scoreatpercentile(
    data: &[f64],
    per: &[f64],
    limit: Option<(f64, f64)>,
    interpolation_method: Option<&str>,
) -> Result<Vec<f64>, StatsError> {
    let method = interpolation_method
        .unwrap_or("fraction")
        .to_ascii_lowercase();
    if !matches!(method.as_str(), "fraction" | "lower" | "higher") {
        return Err(StatsError::InvalidArgument(
            "interpolation_method must be one of {'fraction', 'lower', 'higher'}".to_string(),
        ));
    }

    if data.is_empty() {
        return Ok(vec![f64::NAN; per.len()]);
    }

    let mut filtered = if let Some((lower, upper)) = limit {
        data.iter()
            .copied()
            .filter(|value| lower <= *value && *value <= upper)
            .collect::<Vec<_>>()
    } else {
        data.to_vec()
    };

    if filtered.is_empty() || filtered.iter().any(|value| value.is_nan()) {
        return Ok(vec![f64::NAN; per.len()]);
    }

    // Each percentile reads only 1-2 ranks, so when there are few of them
    // relative to log2(n) it is cheaper to partition per percentile (O(n) each)
    // than to fully sort once (O(n log n)). Both paths are byte-identical, so the
    // gate never changes results.
    if (per.len() as f64) < (filtered.len() as f64).log2().max(1.0) {
        let mut buf = filtered;
        let mut out = Vec::with_capacity(per.len());
        for &percentile in per {
            out.push(scoreatpercentile_single_select(
                &mut buf, percentile, &method,
            )?);
        }
        Ok(out)
    } else {
        filtered.sort_unstable_by(|a, b| a.total_cmp(b));
        per.iter()
            .copied()
            .map(|percentile| scoreatpercentile_single(&filtered, percentile, &method))
            .collect()
    }
}

/// Same result as `scoreatpercentile_single` on a fully `total_cmp`-sorted copy,
/// but reads the one or two needed ranks via partial selection on `buf` (O(n))
/// instead of requiring a pre-sorted slice. `buf` may be left partitioned; each
/// call re-selects from scratch, so repeated calls on the same buffer are fine.
fn scoreatpercentile_single_select(
    buf: &mut [f64],
    per: f64,
    interpolation_method: &str,
) -> Result<f64, StatsError> {
    if !(0.0..=100.0).contains(&per) || per.is_nan() {
        return Err(StatsError::InvalidArgument(
            "percentile must be in the range [0, 100]".to_string(),
        ));
    }
    let n = buf.len();
    if n == 0 {
        return Ok(f64::NAN);
    }
    if n == 1 {
        return Ok(buf[0]);
    }

    let idx = per / 100.0 * (n - 1) as f64;
    let lower = idx.floor() as usize;
    let upper = idx.ceil() as usize;

    if lower == upper {
        buf.select_nth_unstable_by(lower, |a, b| a.total_cmp(b));
        return Ok(buf[lower]);
    }

    let (v_lower, v_upper) = select_ranks(buf, lower, upper);
    let value = match interpolation_method {
        "fraction" => {
            let frac = idx - lower as f64;
            v_lower * (1.0 - frac) + v_upper * frac
        }
        "lower" => v_lower,
        "higher" => v_upper,
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "interpolation_method must be one of {{'fraction', 'lower', 'higher'}}, got {other}"
            )));
        }
    };
    Ok(value)
}

/// Compute the mean after trimming a proportion from each tail.
///
/// Matches `scipy.stats.trim_mean(a, proportiontocut)`.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
pub fn trim_mean(data: &[f64], proportiontocut: f64) -> Result<f64, StatsError> {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return Ok(f64::NAN);
    }
    // A NEGATIVE proportion is clamped to "trim nothing", deliberately. scipy
    // errors there, but with numpy's `kth out of bounds` leaking out of an
    // unguarded partition -- incidental, not a validated contract, so it is not
    // mirrored (see docs/NEGATIVE_EVIDENCE.md).
    let prop = proportiontocut.max(0.0);
    let n = data.len();

    // scipy REJECTS rather than clamping, and its predicate is on the CUT
    // INDICES, not on the proportion (scipy/stats/_stats_py.py):
    //     lowercut = int(proportiontocut * nobs)
    //     uppercut = nobs - lowercut
    //     trim_mean raises iff lowercut is strictly greater than uppercut
    //     trimboth  raises iff lowercut is greater than OR EQUAL to uppercut
    // Testing `proportiontocut` against one half instead is WRONG, and was my
    // first attempt: at n = 5 with prop = 0.51, lowercut = int(2.55) = 2 and
    // uppercut = 3, so scipy happily returns 3.0. Rejecting there would refuse
    // input the incumbent answers. Measured grid on frankenscipy-tb5es.
    //
    // Computed in f64 so a huge proportion cannot overflow the cast; for a
    // non-negative prop the truncation matches Python's int().
    let lowercut = (prop * n as f64).trunc();
    let uppercut = n as f64 - lowercut;
    if lowercut > uppercut {
        return Err(StatsError::InvalidArgument("Proportion too big.".to_string()));
    }

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    let ncut = lowercut as usize;
    let trimmed = &sorted[ncut..n - ncut];
    if trimmed.is_empty() {
        return Ok(f64::NAN);
    }
    Ok(trimmed.iter().sum::<f64>() / trimmed.len() as f64)
}

/// Confidence interval for trimmed mean using bootstrap.
///
/// Computes a confidence interval for the trimmed mean using the
/// percentile bootstrap method.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
/// * `confidence` — Confidence level (e.g., 0.95 for 95%)
/// * `n_bootstrap` — Number of bootstrap samples (default: 1000)
/// * `seed` — Random seed for reproducibility
///
/// # Returns
/// (lower, upper) confidence interval bounds
pub fn trimmed_mean_ci(
    data: &[f64],
    proportiontocut: f64,
    confidence: f64,
    n_bootstrap: usize,
    seed: u64,
) -> (f64, f64) {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return (f64::NAN, f64::NAN);
    }
    if !(0.0..1.0).contains(&confidence) {
        return (f64::NAN, f64::NAN);
    }

    let n = data.len();
    let mut rng = StdRng::seed_from_u64(seed);
    let mut bootstrap_means = Vec::with_capacity(n_bootstrap);

    for _ in 0..n_bootstrap {
        // Resample with replacement
        let sample: Vec<f64> = (0..n).map(|_| data[rng.random_range(0..n)]).collect();
        let tm = trim_mean(&sample, proportiontocut).unwrap_or(f64::NAN);
        if tm.is_finite() {
            bootstrap_means.push(tm);
        }
    }

    if bootstrap_means.is_empty() {
        return (f64::NAN, f64::NAN);
    }

    bootstrap_means.sort_unstable_by(|a, b| a.total_cmp(b));

    let alpha = 1.0 - confidence;
    let lower_idx = ((alpha / 2.0) * bootstrap_means.len() as f64).floor() as usize;
    let upper_idx = ((1.0 - alpha / 2.0) * bootstrap_means.len() as f64).ceil() as usize;

    let lower = bootstrap_means[lower_idx.min(bootstrap_means.len() - 1)];
    let upper = bootstrap_means[(upper_idx - 1).min(bootstrap_means.len() - 1)];

    (lower, upper)
}

/// Standard deviation of trimmed data.
///
/// Computes the standard deviation after trimming a proportion of elements
/// from each end of the sorted data.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
/// * `ddof` — Delta degrees of freedom (default: 1 for sample std)
///
/// # Returns
/// Standard deviation of the trimmed data
pub fn trimmed_std(data: &[f64], proportiontocut: f64, ddof: usize) -> f64 {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return f64::NAN;
    }

    // These wrappers have no error channel of their own, so a rejected
    // proportion becomes their existing NaN signal (frankenscipy-tb5es).
    let Ok(trimmed) = trimboth(data, proportiontocut) else {
        return f64::NAN;
    };
    if trimmed.len() <= ddof {
        return f64::NAN;
    }

    let mean = trimmed.iter().sum::<f64>() / trimmed.len() as f64;
    let variance: f64 =
        trimmed.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (trimmed.len() - ddof) as f64;

    variance.sqrt()
}

/// Variance of trimmed data.
///
/// Computes the variance after trimming a proportion of elements
/// from each end of the sorted data.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
/// * `ddof` — Delta degrees of freedom (default: 1 for sample variance)
///
/// # Returns
/// Variance of the trimmed data
pub fn trimmed_var(data: &[f64], proportiontocut: f64, ddof: usize) -> f64 {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return f64::NAN;
    }

    // These wrappers have no error channel of their own, so a rejected
    // proportion becomes their existing NaN signal (frankenscipy-tb5es).
    let Ok(trimmed) = trimboth(data, proportiontocut) else {
        return f64::NAN;
    };
    if trimmed.len() <= ddof {
        return f64::NAN;
    }

    let mean = trimmed.iter().sum::<f64>() / trimmed.len() as f64;
    trimmed.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (trimmed.len() - ddof) as f64
}

/// Standard error of trimmed mean.
///
/// Computes the standard error of the mean after trimming a proportion
/// of elements from each end of the sorted data.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
/// * `ddof` — Delta degrees of freedom (default: 1)
///
/// # Returns
/// Standard error of the trimmed mean: std / sqrt(n)
pub fn trimmed_sem(data: &[f64], proportiontocut: f64, ddof: usize) -> f64 {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return f64::NAN;
    }

    // These wrappers have no error channel of their own, so a rejected
    // proportion becomes their existing NaN signal (frankenscipy-tb5es).
    let Ok(trimmed) = trimboth(data, proportiontocut) else {
        return f64::NAN;
    };
    if trimmed.len() <= ddof {
        return f64::NAN;
    }

    let std = trimmed_std(data, proportiontocut, ddof);
    std / (trimmed.len() as f64).sqrt()
}

/// Standard error of the trimmed mean, matching `scipy.stats.mstats.trimmed_stde`.
///
/// `limits = (lower, upper)` are the proportions cut from each end (relative to
/// `n`). The tail values are *winsorized* to the boundary order statistics, the
/// sample standard deviation (ddof = 1) is taken over the full winsorized array,
/// and the result is `winstd / ((1 − lower − upper)·√n)`. Tail counts use
/// `int(limit·n)` truncation (the `inclusive` rounding path is broken in scipy
/// itself). Returns NaN for empty input or any NaN.
#[must_use]
pub fn trimmed_stde(data: &[f64], limits: (f64, f64)) -> f64 {
    if data.is_empty() || data.iter().any(|v| v.is_nan()) {
        return f64::NAN;
    }
    let (lo, up) = limits;
    let n = data.len();
    let nf = n as f64;
    // indices sorted by value (argsort).
    let mut idx: Vec<usize> = (0..n).collect();
    idx.sort_by(|&a, &b| data[a].total_cmp(&data[b]));
    let lowidx = (lo * nf) as usize; // int() truncation
    let upidx = n - (nf * up) as usize;
    if lowidx >= upidx {
        return f64::NAN;
    }
    // Winsorize: tail values replaced by the boundary order statistics.
    let low_val = data[idx[lowidx]];
    let up_val = data[idx[upidx - 1]];
    let mut w = data.to_vec();
    for &i in &idx[..lowidx] {
        w[i] = low_val;
    }
    for &i in &idx[upidx..] {
        w[i] = up_val;
    }
    let mean = w.iter().sum::<f64>() / nf;
    let winvar = w.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (nf - 1.0);
    winvar.sqrt() / ((1.0 - lo - up) * nf.sqrt())
}

/// Trims an array by masking values outside given absolute limits.
///
/// Matches `scipy.stats.mstats.trima(a, limits, inclusive)`. `limits =
/// (lower, upper)` are absolute value thresholds (`None` = open end); with
/// `inclusive = (lo_in, up_in)`, a value is masked when `x < lower` (or `<=` if
/// `lo_in` is false) or `x > upper` (or `>=` if `up_in` is false). Returns a
/// same-length, same-order `Vec<f64>` with masked entries set to NaN.
#[must_use]
pub fn trima(
    data: &[f64],
    limits: (Option<f64>, Option<f64>),
    inclusive: (bool, bool),
) -> Vec<f64> {
    let (lo, up) = limits;
    let (loin, upin) = inclusive;
    data.iter()
        .map(|&x| {
            if x.is_nan() {
                return f64::NAN;
            }
            let mut masked = false;
            if let Some(l) = lo {
                masked |= if loin { x < l } else { x <= l };
            }
            if let Some(u) = up {
                masked |= if upin { x > u } else { x >= u };
            }
            if masked { f64::NAN } else { x }
        })
        .collect()
}

/// Trims an array by masking a proportion of the lowest/highest *ranked* values.
///
/// Matches `scipy.stats.mstats.trimr(a, limits, inclusive)`. `limits =
/// (lower, upper)` are proportions of `n` (the non-NaN count) to mask from each
/// rank end. When the corresponding `inclusive` flag is true the tail count is
/// `int(limit·n)` (truncated), otherwise `round(limit·n)` (round-half-even). A
/// lower limit of `0`/`None` masks nothing on that side. Returns a same-length,
/// same-order `Vec<f64>` with masked entries set to NaN.
#[must_use]
pub fn trimr(
    data: &[f64],
    limits: (Option<f64>, Option<f64>),
    inclusive: (bool, bool),
) -> Vec<f64> {
    let (lo, up) = limits;
    let (loin, upin) = inclusive;
    let mut idx: Vec<usize> = (0..data.len()).filter(|&i| !data[i].is_nan()).collect();
    let n = idx.len();
    idx.sort_by(|&a, &b| data[a].total_cmp(&data[b]));
    let nf = n as f64;
    let mut out = data.to_vec();
    if let Some(l) = lo
        && l != 0.0
    {
        let lowidx = if loin {
            (l * nf) as usize
        } else {
            round_half_even(l * nf) as usize
        }
        .min(n);
        for &i in &idx[..lowidx] {
            out[i] = f64::NAN;
        }
    }
    if let Some(u) = up {
        let cut = if upin {
            (nf * u) as usize
        } else {
            round_half_even(nf * u) as usize
        };
        let upidx = n.saturating_sub(cut);
        for &i in &idx[upidx..] {
            out[i] = f64::NAN;
        }
    }
    out
}

/// Trims a proportion of values from one tail of an array.
///
/// Matches `scipy.stats.mstats.trimtail(data, proportiontocut, tail, inclusive)`.
/// `tail` selects the side: `"left"`/`"l"` masks the lowest `proportiontocut`
/// fraction by rank, `"right"`/`"r"` masks the highest. Returns a same-length,
/// same-order `Vec<f64>` with masked entries set to NaN.
#[must_use]
pub fn trimtail(
    data: &[f64],
    proportiontocut: f64,
    tail: &str,
    inclusive: (bool, bool),
) -> Vec<f64> {
    let right = tail.chars().next().map(|c| c.to_ascii_lowercase()) == Some('r');
    let limits = if right {
        (None, Some(proportiontocut))
    } else {
        (Some(proportiontocut), None)
    };
    trimr(data, limits, inclusive)
}

/// Trim a proportion of elements from both ends of a sorted array.
///
/// Slices off the given proportion from **each** end of the sorted input array,
/// returning the middle portion.
///
/// Matches `scipy.stats.trimboth(a, proportiontocut)`.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim from each end (0.0 to 0.5)
///
/// # Returns
/// A new vector containing the trimmed middle portion of the sorted data.
pub fn trimboth(data: &[f64], proportiontocut: f64) -> Result<Vec<f64>, StatsError> {
    // Empty input short-circuits BEFORE the predicate, matching scipy:
    // stats.trimboth([], 0.1) returns an empty array rather than raising.
    if data.is_empty() {
        return Ok(vec![]);
    }
    let prop = proportiontocut.max(0.0);
    let n = data.len();

    // See `trim_mean` for the full explanation. trimboth compares with
    // greater-or-equal where trim_mean uses strictly-greater, so the two
    // genuinely disagree when lowercut equals uppercut:
    // stats.trim_mean([1..=10], 0.5) is nan but stats.trimboth([1..=10], 0.5)
    // RAISES (frankenscipy-tb5es).
    let lowercut = (prop * n as f64).trunc();
    let uppercut = n as f64 - lowercut;
    if lowercut >= uppercut {
        return Err(StatsError::InvalidArgument("Proportion too big.".to_string()));
    }

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    let ncut = lowercut as usize;
    Ok(sorted[ncut..n - ncut].to_vec())
}

/// Trim a proportion of elements from one tail of a sorted array.
///
/// Slices off the given proportion from the specified tail of the sorted input,
/// returning the remaining portion.
///
/// Matches `scipy.stats.trim1(a, proportiontocut, tail)`.
///
/// # Arguments
/// * `data` — Input array
/// * `proportiontocut` — Fraction to trim (0.0 to 1.0)
/// * `tail` — Which tail to trim: `"right"` (high values), `"left"` (low values),
///   or `"both"` (equivalent to `trimboth`)
///
/// # Returns
/// A new vector containing the trimmed sorted data.
pub fn trim1(data: &[f64], proportiontocut: f64, tail: &str) -> Vec<f64> {
    if data.is_empty() {
        return vec![];
    }
    let prop = proportiontocut.clamp(0.0, 1.0);
    let n = data.len();
    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    let ncut = (n as f64 * prop).floor() as usize;

    match tail {
        "left" => {
            if ncut >= n {
                vec![]
            } else {
                sorted[ncut..].to_vec()
            }
        }
        "right" => {
            if ncut >= n {
                vec![]
            } else {
                sorted[..n - ncut].to_vec()
            }
        }
        "both" => {
            let ncut_both = (n as f64 * prop.min(0.5)).floor() as usize;
            if 2 * ncut_both >= n {
                vec![]
            } else {
                sorted[ncut_both..n - ncut_both].to_vec()
            }
        }
        _ => sorted, // unknown tail, return sorted data unchanged
    }
}

/// When `true`, [`tvar`]/[`tsem`] materialize the in-limit `Vec` then read it for mean and sum-of-
/// squares (the ORIG behaviour); default `false` computes both passes over `data` behind the in-limit
/// predicate with NO allocation. A/B gate (shared by [`tstd`], [`tsem`]).
///
/// CONTRACT: byte-identical ONLY WITH [`TVAR_PAR_FORCE_SERIAL`] ALSO SET. This doc read a bare
/// "Byte-identical" until frankenscipy-5f06d put a driver on it, and that is false as a reader would
/// run it: at `len >= 1<<22` the no-alloc path is PARALLEL by default, so flipping this toggle alone
/// swaps a serial collect for a parallel inline reduction and moves two levers at once. Measured on
/// rch worker vmi1152480 at `len == 1<<22`: pinned, the two paths agree bit for bit; unpinned, they
/// DRIFT. The bit-exact claim is about allocation, not about threading -- `Sigma x` and
/// `Sigma (x-mean)^2` are the same left-to-right folds from 0.0 over the same in-limit elements in
/// data order whether or not the `Vec` is materialized.
#[doc(hidden)]
pub static TVAR_FORCE_COLLECT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// When `true`, [`tvar`]'s alloc-free inline path folds its two in-limit passes serially (byte-identical
/// to the collect path); default `false` fans each conditional reduction across cores for huge inputs
/// (within per-op ULP tolerance above the gate). `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static TVAR_PAR_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the trimmed variance of an array.
///
/// Values outside the specified limits are excluded before computing variance.
///
/// Matches `scipy.stats.tvar(a, limits, inclusive, ddof)`.
///
/// # Arguments
/// * `data` — Input array
/// * `limits` — Tuple of (lower, upper) limits. Values outside are excluded.
/// * `inclusive` — Tuple of bools: whether limits are inclusive (lower, upper)
/// * `ddof` — Delta degrees of freedom (default 1 for sample variance)
///
/// # Returns
/// The trimmed variance, or NaN if fewer than ddof+1 values remain.
pub fn tvar(data: &[f64], limits: (f64, f64), inclusive: (bool, bool), ddof: usize) -> f64 {
    let within = |x: f64| -> bool {
        let above_lower = if inclusive.0 {
            x >= limits.0
        } else {
            x > limits.0
        };
        let below_upper = if inclusive.1 {
            x <= limits.1
        } else {
            x < limits.1
        };
        above_lower && below_upper
    };
    // The alloc-free two-pass form (below) wins ONLY in the memory-bound regime: at n≥~4M `data`
    // spills LLC, so dropping the Vec's alloc+write+two-reads for two reads of `data` is 1.53x. When
    // cache-resident (≤2M) the Vec stays hot and the doubled in-limit predicate eval costs more
    // (measured 0.88x). Gate at 1<<22 so no size regresses; keep the ORIG collect path below (and
    // when `TVAR_FORCE_COLLECT`). Both paths are byte-identical WITH `TVAR_PAR_FORCE_SERIAL` set --
    // see that toggle's doc; unpinned, this comparison also picks up the parallel arm and drifts.
    if TVAR_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed) || data.len() < (1 << 22) {
        let filtered: Vec<f64> = data.iter().copied().filter(|&x| within(x)).collect();
        if filtered.len() <= ddof {
            return f64::NAN;
        }
        let n = filtered.len() as f64;
        let mean = filtered.iter().sum::<f64>() / n;
        let sum_sq: f64 = filtered.iter().map(|&x| (x - mean).powi(2)).sum();
        return sum_sq / (n - ddof as f64);
    }
    // Two-pass variance needs the mean before the squared deviations, but neither pass needs the
    // in-limit values materialized: apply the predicate inline instead. BYTE-IDENTICAL — `Σx` and
    // `Σ(x-mean)²` are the same left-to-right folds from 0.0 over the in-limit elements in data
    // order as over `filtered`, and `count == filtered.len()`. Eliminates the intermediate Vec
    // (its alloc + write + two reads → two reads of `data` behind a cheap comparison).
    // Two INDEPENDENT conditional reductions (`Σx`+count, then `Σ(x-mean)²`) over the in-limit elements.
    // Fan each across cores for huge `data`: below the gate / when forced serial, the single-chunk fold
    // IS the serial loop (byte-identical to the collect path); above it the per-thread partials
    // reassociate within per-op ULP tolerance, and the count is an exact integer sum (order-independent).
    let par_serial = TVAR_PAR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed);
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(data.len() / (1 << 16))
        .max(1);
    let chunk = data.len().div_ceil(nthreads);

    let sum_count = |ds: &[f64]| -> (f64, usize) {
        let mut s = 0.0f64;
        let mut c = 0usize;
        for &x in ds {
            if within(x) {
                s += x;
                c += 1;
            }
        }
        (s, c)
    };
    let (sum, count) = if par_serial || nthreads <= 1 {
        sum_count(data)
    } else {
        let sum_count = &sum_count;
        let parts: Vec<(f64, usize)> = std::thread::scope(|scope| {
            data.chunks(chunk)
                .map(|ds| scope.spawn(move || sum_count(ds)))
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("tvar sum worker panicked"))
                .collect()
        });
        parts
            .into_iter()
            .fold((0.0f64, 0usize), |(a, b), (s, c)| (a + s, b + c))
    };
    if count <= ddof {
        return f64::NAN;
    }
    let n = count as f64;
    let mean = sum / n;

    let ss = |ds: &[f64]| -> f64 {
        let mut s = 0.0f64;
        for &x in ds {
            if within(x) {
                s += (x - mean).powi(2);
            }
        }
        s
    };
    let sum_sq = if par_serial || nthreads <= 1 {
        ss(data)
    } else {
        let ss = &ss;
        let parts: Vec<f64> = std::thread::scope(|scope| {
            data.chunks(chunk)
                .map(|ds| scope.spawn(move || ss(ds)))
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("tvar ss worker panicked"))
                .collect()
        });
        parts.into_iter().sum()
    };
    sum_sq / (n - ddof as f64)
}

/// Compute the trimmed standard deviation of an array.
///
/// Values outside the specified limits are excluded before computing std dev.
///
/// Matches `scipy.stats.tstd(a, limits, inclusive, ddof)`.
///
/// # Arguments
/// * `data` — Input array
/// * `limits` — Tuple of (lower, upper) limits. Values outside are excluded.
/// * `inclusive` — Tuple of bools: whether limits are inclusive (lower, upper)
/// * `ddof` — Delta degrees of freedom (default 1 for sample std dev)
///
/// # Returns
/// The trimmed standard deviation, or NaN if fewer than ddof+1 values remain.
pub fn tstd(data: &[f64], limits: (f64, f64), inclusive: (bool, bool), ddof: usize) -> f64 {
    tvar(data, limits, inclusive, ddof).sqrt()
}

/// When `true`, [`tmean`] materializes the in-limit `Vec` then sums it (the ORIG behaviour);
/// default `false` folds `(sum, count)` inline with no allocation. Byte-identical. A/B gate.
#[doc(hidden)]
pub static TMEAN_FORCE_COLLECT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Compute the trimmed mean of an array.
///
/// Values outside the specified limits are excluded before computing mean.
///
/// Matches `scipy.stats.tmean(a, limits, inclusive)`.
///
/// # Arguments
/// * `data` — Input array
/// * `limits` — Tuple of (lower, upper) limits. Values outside are excluded.
/// * `inclusive` — Tuple of bools: whether limits are inclusive (lower, upper)
///
/// # Returns
/// The trimmed mean, or NaN if no values remain after filtering.
pub fn tmean(data: &[f64], limits: (f64, f64), inclusive: (bool, bool)) -> f64 {
    let within = |x: f64| -> bool {
        let above_lower = if inclusive.0 {
            x >= limits.0
        } else {
            x > limits.0
        };
        let below_upper = if inclusive.1 {
            x <= limits.1
        } else {
            x < limits.1
        };
        above_lower && below_upper
    };
    if !TMEAN_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed) {
        // Fold Σ + count over the in-limit elements in ONE pass, no materialized Vec.
        // BYTE-IDENTICAL: Σ is the same left-to-right fold from 0.0 over the same in-limit
        // elements in data order as `filtered.iter().sum()`, and `count == filtered.len()`.
        let mut sum = 0.0f64;
        let mut count = 0usize;
        for &x in data {
            if within(x) {
                sum += x;
                count += 1;
            }
        }
        return if count == 0 {
            f64::NAN
        } else {
            sum / count as f64
        };
    }
    let filtered: Vec<f64> = data.iter().copied().filter(|&x| within(x)).collect();

    if filtered.is_empty() {
        return f64::NAN;
    }

    filtered.iter().sum::<f64>() / filtered.len() as f64
}

/// Compute the trimmed standard error of the mean.
///
/// Values outside the specified limits are excluded before computing SEM.
///
/// Matches `scipy.stats.tsem(a, limits, inclusive, ddof)`.
///
/// # Arguments
/// * `data` — Input array
/// * `limits` — Tuple of (lower, upper) limits. Values outside are excluded.
/// * `inclusive` — Tuple of bools: whether limits are inclusive (lower, upper)
/// * `ddof` — Delta degrees of freedom (default 1)
///
/// # Returns
/// The trimmed SEM, or NaN if fewer than ddof+1 values remain.
pub fn tsem(data: &[f64], limits: (f64, f64), inclusive: (bool, bool), ddof: usize) -> f64 {
    let within = |x: f64| -> bool {
        let above_lower = if inclusive.0 {
            x >= limits.0
        } else {
            x > limits.0
        };
        let below_upper = if inclusive.1 {
            x <= limits.1
        } else {
            x < limits.1
        };
        above_lower && below_upper
    };
    // Same alloc-free lever as [`tvar`]: the intermediate in-limit Vec only pays for itself when
    // cache-resident, so above 1<<22 (data spills LLC) skip it and apply the predicate inline over
    // `data` for the mean and Σ(x-mean)² passes. Byte-identical; keep the collect path below and when
    // TVAR_FORCE_COLLECT. The trailing `(var/n).sqrt()` is unchanged.
    let (n, sum_sq) = if TVAR_FORCE_COLLECT.load(std::sync::atomic::Ordering::Relaxed)
        || data.len() < (1 << 22)
    {
        let filtered: Vec<f64> = data.iter().copied().filter(|&x| within(x)).collect();
        if filtered.len() <= ddof {
            return f64::NAN;
        }
        let n = filtered.len() as f64;
        let mean = filtered.iter().sum::<f64>() / n;
        let sum_sq: f64 = filtered.iter().map(|&x| (x - mean).powi(2)).sum();
        (n, sum_sq)
    } else {
        // Two INDEPENDENT conditional reductions fanned across cores (same lever as tvar): byte-identical
        // below the gate / when forced serial (single-chunk fold IS the serial loop; exact integer count),
        // ULP above. Shares TVAR_PAR_FORCE_SERIAL.
        let par_serial = TVAR_PAR_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed);
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(data.len() / (1 << 16))
            .max(1);
        let chunk = data.len().div_ceil(nthreads);
        let sum_count = |ds: &[f64]| -> (f64, usize) {
            let mut s = 0.0f64;
            let mut c = 0usize;
            for &x in ds {
                if within(x) {
                    s += x;
                    c += 1;
                }
            }
            (s, c)
        };
        let (sum, count) = if par_serial || nthreads <= 1 {
            sum_count(data)
        } else {
            let sum_count = &sum_count;
            let parts: Vec<(f64, usize)> = std::thread::scope(|scope| {
                data.chunks(chunk)
                    .map(|ds| scope.spawn(move || sum_count(ds)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("tsem sum worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0usize), |(a, b), (s, c)| (a + s, b + c))
        };
        if count <= ddof {
            return f64::NAN;
        }
        let n = count as f64;
        let mean = sum / n;
        let ss = |ds: &[f64]| -> f64 {
            let mut s = 0.0f64;
            for &x in ds {
                if within(x) {
                    s += (x - mean).powi(2);
                }
            }
            s
        };
        let sum_sq = if par_serial || nthreads <= 1 {
            ss(data)
        } else {
            let ss = &ss;
            let parts: Vec<f64> = std::thread::scope(|scope| {
                data.chunks(chunk)
                    .map(|ds| scope.spawn(move || ss(ds)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("tsem ss worker panicked"))
                    .collect()
            });
            parts.into_iter().sum()
        };
        (n, sum_sq)
    };
    let var = sum_sq / (n - ddof as f64);
    (var / n).sqrt()
}

/// Compute the trimmed minimum.
///
/// Returns the minimum value greater than (or equal to) the lower limit.
///
/// Matches `scipy.stats.tmin(a, lowerlimit, inclusive=True)`.
///
/// # Arguments
/// * `data` - Input array
/// * `lowerlimit` - Values below this are ignored
/// * `inclusive` - If true, values equal to limit are included
///
/// # Returns
/// When `true`, [`tmin`]/[`tmax`] materialize the filtered `Vec` then fold serially (the
/// ORIG behaviour); default `false` folds inline (no alloc) and fans across cores above the
/// work gate. Byte-identical.
#[doc(hidden)]
pub static TMINMAX_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Fold `reduce` over the elements of `data` that satisfy `keep`, WITHOUT materializing a
/// filtered `Vec`, fanning across cores above the work gate. Returns `None` if nothing is
/// kept. BYTE-IDENTICAL to `data.iter().copied().filter(keep).fold(ident, reduce)`: the kept
/// set and its data order are unchanged, and `f64::min`/`f64::max` are associative with a
/// total order over signed zeros, so the chunk-then-merge equals the serial left fold.
fn par_filter_fold<F>(data: &[f64], ident: f64, keep: F, reduce: fn(f64, f64) -> f64) -> Option<f64>
where
    F: Fn(f64) -> bool + Sync,
{
    let n = data.len();
    let scan = |d: &[f64]| -> (f64, bool) {
        let mut acc = ident;
        let mut any = false;
        for &x in d {
            if keep(x) {
                acc = reduce(acc, x);
                any = true;
            }
        }
        (acc, any)
    };
    let nthreads = if TMINMAX_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < 131_072
    {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / 65_536)
            .max(1)
    };
    let (acc, any) = if nthreads <= 1 {
        scan(data)
    } else {
        let chunk = n.div_ceil(nthreads);
        let scan = &scan;
        let parts: Vec<(f64, bool)> = std::thread::scope(|scope| {
            data.chunks(chunk)
                .map(|c| scope.spawn(move || scan(c)))
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().unwrap())
                .collect()
        });
        parts
            .into_iter()
            .fold((ident, false), |(a, aa), (b, ab)| (reduce(a, b), aa || ab))
    };
    if any { Some(acc) } else { None }
}

/// The trimmed minimum, or NaN if no values remain.
pub fn tmin(data: &[f64], lowerlimit: f64, inclusive: bool) -> f64 {
    let keep = |x: f64| {
        x.is_finite()
            && if inclusive {
                x >= lowerlimit
            } else {
                x > lowerlimit
            }
    };
    if TMINMAX_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        let filtered: Vec<f64> = data.iter().copied().filter(|&x| keep(x)).collect();
        if filtered.is_empty() {
            return f64::NAN;
        }
        return filtered.iter().copied().fold(f64::INFINITY, f64::min);
    }
    par_filter_fold(data, f64::INFINITY, keep, f64::min).unwrap_or(f64::NAN)
}

/// Compute the trimmed maximum.
///
/// Returns the maximum value less than (or equal to) the upper limit.
///
/// Matches `scipy.stats.tmax(a, upperlimit, inclusive=True)`.
///
/// # Arguments
/// * `data` - Input array
/// * `upperlimit` - Values above this are ignored
/// * `inclusive` - If true, values equal to limit are included
///
/// # Returns
/// The trimmed maximum, or NaN if no values remain.
pub fn tmax(data: &[f64], upperlimit: f64, inclusive: bool) -> f64 {
    let keep = |x: f64| {
        x.is_finite()
            && if inclusive {
                x <= upperlimit
            } else {
                x < upperlimit
            }
    };
    if TMINMAX_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) {
        let filtered: Vec<f64> = data.iter().copied().filter(|&x| keep(x)).collect();
        if filtered.is_empty() {
            return f64::NAN;
        }
        return filtered.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    }
    par_filter_fold(data, f64::NEG_INFINITY, keep, f64::max).unwrap_or(f64::NAN)
}

/// Compute the expectile at a given alpha level.
///
/// Expectiles are a generalization of the mean (alpha=0.5). They solve the
/// asymmetric least squares problem where observations above the expectile
/// are weighted by alpha and observations below are weighted by (1-alpha).
///
/// Matches `scipy.stats.expectile(a, alpha)`.
///
/// # Arguments
/// * `data` — Input array
/// * `alpha` — Expectile level in (0, 1). Default 0.5 gives the mean.
///
/// # Returns
/// The expectile value, or NaN for empty input or invalid alpha.
/// When `true`, [`expectile`] folds each iteration's weighted `Σw`/`Σw·x` serially (the ORIG
/// behaviour); default `false` fans it across cores for huge inputs. Byte-identical below the gate;
/// above it within the estimator's 1e-12 convergence tolerance. `#[doc(hidden)]` — internal A/B gate.
#[doc(hidden)]
pub static EXPECTILE_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn expectile(data: &[f64], alpha: f64) -> f64 {
    if data.is_empty() || alpha <= 0.0 || alpha >= 1.0 {
        return f64::NAN;
    }

    let filtered: Vec<f64> = data.iter().copied().filter(|x| x.is_finite()).collect();
    if filtered.is_empty() {
        return f64::NAN;
    }

    // Start with the mean as initial guess
    let mut mu = filtered.iter().sum::<f64>() / filtered.len() as f64;

    // The per-iteration pass folds `Σw` and `Σw·x` (w = alpha if x≥mu else 1-alpha) — the dominant O(n)
    // work; iterations are sequential (mu depends on the previous). Fan each iteration's reduction across
    // cores for huge inputs. BYTE-IDENTICAL below the gate / when forced serial (single-chunk fold IS the
    // serial loop); above it the partials reassociate (~ULP per iteration), and since the fixed point is
    // only resolved to the 1e-12 convergence tolerance the returned expectile stays within that tolerance.
    let n = filtered.len();
    let par = !EXPECTILE_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) && n >= (1 << 22);
    let nthreads = if par {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / (1 << 16))
            .max(1)
    } else {
        1
    };
    let chunk = n.div_ceil(nthreads);

    // Iteratively solve for the expectile using weighted least squares
    for _ in 0..100 {
        let reduce = |ds: &[f64]| -> (f64, f64) {
            let mut sw = 0.0f64;
            let mut swx = 0.0f64;
            for &x in ds {
                let w = if x >= mu { alpha } else { 1.0 - alpha };
                sw += w;
                swx += w * x;
            }
            (sw, swx)
        };
        let (sum_w, sum_wx) = if nthreads <= 1 {
            reduce(&filtered)
        } else {
            let reduce = &reduce;
            let parts: Vec<(f64, f64)> = std::thread::scope(|scope| {
                filtered
                    .chunks(chunk)
                    .map(|ds| scope.spawn(move || reduce(ds)))
                    .collect::<Vec<_>>()
                    .into_iter()
                    .map(|h| h.join().expect("expectile worker panicked"))
                    .collect()
            });
            parts
                .into_iter()
                .fold((0.0f64, 0.0f64), |(a, b), (s, t)| (a + s, b + t))
        };

        let new_mu = sum_wx / sum_w;
        if (new_mu - mu).abs() < 1e-12 {
            return new_mu;
        }
        mu = new_mu;
    }

    mu
}

/// Estimate the differential entropy of a continuous distribution from samples.
///
/// Uses the Vasicek spacing estimator with window length m. The entropy is
/// estimated as: H = (1/n) * sum(ln(n/(2m) * (X_{i+m} - X_{i-m})))
///
/// Matches `scipy.stats.differential_entropy(values, window_length, base)`.
///
/// # Arguments
/// * `values` — Sample data
/// * `window_length` — Window length for spacing estimator. If None, uses floor(sqrt(n))
/// * `base` — Logarithm base. If None, uses natural log (e)
///
/// # Returns
/// Estimated differential entropy, or NaN for insufficient data.
/// When `true`, [`differential_entropy`] folds its Vasicek spacing-log sum serially (the ORIG
/// behaviour); default `false` fans the compute-bound `ln` reduction across cores for large inputs.
///
/// WITHIN PER-OP ULP TOLERANCE, not byte-identical. Above the `1 << 16` gate the parallel arm folds
/// per-thread partial sums with no intermediate Vec, so the additions reassociate. The doc
/// previously said only "byte-identical below the gate" — vacuously true, since below the gate both
/// arms ARE the same code, and therefore silent about the contract governing every comparison that
/// is not vacuous. [`differential_entropy`]'s own inline comment has stated the tolerance correctly
/// all along. Corrected under frankenscipy-5f06d after an exact A/B gate caught it at n = 70_000
/// (count = 69_472): 0.0000033054864609157917 serial vs 0.0000033054864609220334 parallel.
/// The `spacing <= 0` → `-inf` case stays order-independent (any −∞ ⇒ −∞ total).
/// `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static DIFFERENTIAL_ENTROPY_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn differential_entropy(
    values: &[f64],
    window_length: Option<usize>,
    base: Option<f64>,
) -> f64 {
    let filtered: Vec<f64> = values.iter().copied().filter(|x| x.is_finite()).collect();
    let n = filtered.len();

    if n < 2 {
        return f64::NAN;
    }

    // Default window length: floor(sqrt(n))
    let m = window_length
        .unwrap_or_else(|| (n as f64).sqrt().floor() as usize)
        .max(1);

    if 2 * m >= n {
        return f64::NAN;
    }

    // Sort the data
    let mut sorted = filtered;
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    // Vasicek spacing estimator: Σ ln(scale·(sorted[i+m] − sorted[i−m])). Each term is an INDEPENDENT
    // heavy `ln` (a transcendental) over the already-sorted array, so the loop is compute-bound —
    // fan the sum across cores (chunked over i, partials merged). BYTE-IDENTICAL below the gate (the
    // single-chunk fold IS the original loop); above it the finite terms reassociate within per-op ULP
    // tolerance, and the `spacing<=0` → NEG_INFINITY case is order-independent (any −∞ ⇒ −∞ total).
    // `DIFFERENTIAL_ENTROPY_FORCE_SERIAL` restores the serial fold for A/B.
    let scale = n as f64 / (2.0 * m as f64);
    let (lo, hi) = (m, n - m);
    let count = hi - lo;
    let vasicek_chunk = |i0: usize, i1: usize| -> f64 {
        let mut s = 0.0f64;
        for i in i0..i1 {
            let spacing = sorted[i + m] - sorted[i - m];
            if spacing > 0.0 {
                s += (scale * spacing).ln();
            } else {
                s += f64::NEG_INFINITY;
            }
        }
        s
    };
    let sum_log = if DIFFERENTIAL_ENTROPY_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
        || count < (1 << 16)
    {
        vasicek_chunk(lo, hi)
    } else {
        let nthreads = std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(count / (1 << 14))
            .max(1);
        let chunk = count.div_ceil(nthreads);
        let vasicek_chunk = &vasicek_chunk;
        let parts: Vec<f64> = std::thread::scope(|scope| {
            (0..nthreads)
                .filter_map(|t| {
                    let i0 = lo + t * chunk;
                    if i0 >= hi {
                        return None;
                    }
                    let i1 = (i0 + chunk).min(hi);
                    Some(scope.spawn(move || vasicek_chunk(i0, i1)))
                })
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("differential_entropy worker panicked"))
                .collect()
        });
        parts.into_iter().sum()
    };

    let h = sum_log / (n - 2 * m) as f64;

    // Convert to requested base
    if let Some(b) = base
        && b > 0.0
        && b != 1.0
    {
        return h / b.ln();
    }

    h
}

/// When `true`, [`obrientransform`] runs its per-group transform serially (the ORIG behaviour);
/// default `false` fans it across cores over the independent groups. Byte-identical either way.
/// `#[doc(hidden)]` — internal A/B perf gate.
#[doc(hidden)]
pub static OBRIENTRANSFORM_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Apply O'Brien's transform to test for homogeneity of variance.
///
/// The O'Brien transform converts data for use in a one-way ANOVA to test
/// whether the variances of multiple groups are equal. Each value x_ij is
/// transformed to:
///
/// r_ij = ((n-1.5)*n*(x_ij - mean)^2 - 0.5*var*(n-1)) / ((n-1)*(n-2))
///
/// Matches `scipy.stats.obrientransform(*args)`.
///
/// # Arguments
/// * `groups` — Slice of data groups to transform
///
/// # Returns
/// Vector of transformed groups, or empty if any group has fewer than 3 elements.
///
/// When [`OBRIENTRANSFORM_FORCE_SERIAL`] is `true`, the per-group transform runs serially (the ORIG
/// behaviour); default `false` fans it across cores over the independent groups. Byte-identical.
pub fn obrientransform(groups: &[&[f64]]) -> Vec<Vec<f64>> {
    // scipy returns empty if ANY group has < 3 elements; check up front so the
    // per-group transform below is unconditional (the ORIG returned mid-loop).
    if groups.iter().any(|g| g.len() < 3) {
        return vec![];
    }

    // Each group is transformed independently: `r = ((n-1.5)·n·(x-mean)² − 0.5·var·(n-1)) / denom`,
    // three O(n) arithmetic passes (mean, var, transform). Groups are INDEPENDENT, so build the
    // transformed groups across cores (chunked over groups, collected in group order). BYTE-IDENTICAL to
    // the serial loop: each group's mean/var/transform is unchanged and the outer order is preserved —
    // only the owning core differs. `OBRIENTRANSFORM_FORCE_SERIAL` restores the serial build for A/B.
    let transform_group = |group: &[f64]| -> Vec<f64> {
        let n_f = group.len() as f64;
        let mean = group.iter().sum::<f64>() / n_f;
        let var = group.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / (n_f - 1.0);
        let denom = (n_f - 1.0) * (n_f - 2.0);
        group
            .iter()
            .map(|&x| {
                let diff_sq = (x - mean).powi(2);
                ((n_f - 1.5) * n_f * diff_sq - 0.5 * var * (n_f - 1.0)) / denom
            })
            .collect()
    };
    let total: usize = groups.iter().map(|g| g.len()).sum();
    if OBRIENTRANSFORM_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
        || total < (1 << 18)
        || groups.len() < 2
    {
        return groups.iter().map(|g| transform_group(g)).collect();
    }
    let nthreads = std::thread::available_parallelism()
        .map(std::num::NonZero::get)
        .unwrap_or(1)
        .min(groups.len());
    let chunk = groups.len().div_ceil(nthreads);
    let transform_group = &transform_group;
    std::thread::scope(|scope| {
        groups
            .chunks(chunk)
            .map(|gc| {
                scope.spawn(move || {
                    gc.iter()
                        .map(|g| transform_group(g))
                        .collect::<Vec<Vec<f64>>>()
                })
            })
            .collect::<Vec<_>>()
            .into_iter()
            .flat_map(|h| h.join().expect("obrientransform worker panicked"))
            .collect()
    })
}

/// Result of Page's trend test.
#[derive(Debug, Clone, PartialEq)]
pub struct PageTrendResult {
    /// Page's L statistic.
    pub statistic: f64,
    /// Approximate p-value (one-sided, for increasing trend).
    pub pvalue: f64,
}

/// Perform Page's L test for a monotonic trend in ranked data.
///
/// Tests whether there is a monotonic trend across ordered conditions.
/// Data should be organized as rows (subjects/blocks) by columns (conditions).
///
/// Matches `scipy.stats.page_trend_test(data)`.
///
/// # Arguments
/// * `data` — 2D data where each inner slice is a row (subject), columns are conditions
///
/// # Returns
/// `PageTrendResult` with L statistic and approximate p-value.
pub fn page_trend_test(data: &[&[f64]]) -> PageTrendResult {
    let n = data.len(); // number of subjects/blocks
    if n == 0 {
        return PageTrendResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let k = data[0].len(); // number of conditions
    if k < 2 || data.iter().any(|row| row.len() != k) {
        return PageTrendResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    // Rank within each row
    let mut rank_sums = vec![0.0; k];
    // Per-row scratch hoisted out of the loop: indexed is cleared+rebuilt each row,
    // ranks is fully overwritten (the while loop assigns every column) -> byte-
    // identical, saving 2×n_rows allocations. frankenscipy-26zjo.
    let mut indexed: Vec<(usize, f64)> = Vec::with_capacity(k);
    let mut ranks = vec![0.0; k];

    for row in data {
        // Get ranks for this row
        indexed.clear();
        indexed.extend(row.iter().copied().enumerate());
        indexed.sort_by(|a, b| a.1.total_cmp(&b.1));

        let mut i = 0;
        while i < k {
            let mut j = i + 1;
            while j < k && indexed[j].1 == indexed[i].1 {
                j += 1;
            }
            let avg_rank = (i + 1 + j) as f64 / 2.0;
            for idx in i..j {
                ranks[indexed[idx].0] = avg_rank;
            }
            i = j;
        }

        for (col, &rank) in ranks.iter().enumerate() {
            rank_sums[col] += rank;
        }
    }

    // Compute L statistic: sum of (condition_index + 1) * rank_sum
    let l: f64 = rank_sums
        .iter()
        .enumerate()
        .map(|(i, &r)| (i + 1) as f64 * r)
        .sum();

    // Expected value and variance under null hypothesis
    let n_f = n as f64;
    let k_f = k as f64;
    let expected_l = n_f * k_f * (k_f + 1.0).powi(2) / 4.0;
    let var_l = n_f * k_f.powi(2) * (k_f + 1.0).powi(2) * (k_f - 1.0) / 144.0;

    // Z-score approximation
    let z = (l - expected_l) / var_l.sqrt();

    // One-sided p-value (testing for increasing trend)
    let pvalue = 1.0 - standard_normal_cdf(z);

    PageTrendResult {
        statistic: l,
        pvalue,
    }
}

/// Compute a weighted Kendall's tau correlation.
///
/// Weighted tau gives more importance to elements with higher ranks.
/// Uses the default hyperbolic weigher: w(i, j) = 1/(i+1) + 1/(j+1).
///
/// Matches `scipy.stats.weightedtau(x, y)` with default parameters.
///
/// # Arguments
/// * `x` — First ranking
/// * `y` — Second ranking
///
/// # Returns
/// Weighted tau correlation coefficient, or NaN for insufficient data.
pub fn weightedtau(x: &[f64], y: &[f64]) -> f64 {
    let n = x.len();
    if n != y.len() || n < 2 {
        return f64::NAN;
    }

    // scipy.stats.weightedtau defaults to rank=True which averages two τ
    // computations using the *decreasing* lexicographical rank by (x, y)
    // and by (y, x). fsci's rank_values returns ascending ranks (lowest=0),
    // so we flip to descending: highest value gets the most-important rank 0.
    let n_minus_one = (n - 1) as f64;
    let asc_x = rank_values(x);
    let asc_y = rank_values(y);
    let desc_x: Vec<f64> = asc_x.iter().map(|r| n_minus_one - r).collect();
    let desc_y: Vec<f64> = asc_y.iter().map(|r| n_minus_one - r).collect();

    let tau_x = weightedtau_one_side(x, y, &desc_x);
    let tau_y = weightedtau_one_side(x, y, &desc_y);
    if !tau_x.is_finite() || !tau_y.is_finite() {
        return f64::NAN;
    }
    (tau_x + tau_y) / 2.0
}

/// O(n log n) weighted Kendall tau for one hyperbolic ranking. The numerator
/// `sum_{i<j} (wi+wj)·sign((xi-xj)(yi-yj))` and denominator `sum_{i<j} (wi+wj)`
/// (with `wi = 1/(rank_i+1)`) are computed without the O(n^2) all-pairs loop.
/// Denominator: each element lies in `n-1` pairs, so D = (n-1)·sum(wi). Numerator:
/// sort by x (grouping x-ties, which contribute 0); process points in x order, and for
/// each point query two Fenwick trees over the y-rank (one of weights, one of counts)
/// to get, among already-inserted points (strictly smaller x), the weighted concordant
/// minus discordant contribution `(sum_w + wb·cnt)_{y_a<y_b} - (sum_w + wb·cnt)_{y_a>y_b}`.
/// y-ties (y_a==y_b) fall in neither side and contribute 0, matching `sign(...)==0`.
/// Tolerance-parity with the O(n^2) reference (the weighted sums accumulate in a
/// different order); validated bit-close by `weightedtau_one_side_matches_reference`.
fn weightedtau_one_side(x: &[f64], y: &[f64], ranks: &[f64]) -> f64 {
    let n = x.len();
    if n < 2 {
        return f64::NAN;
    }
    let w: Vec<f64> = ranks.iter().map(|&r| 1.0 / (r + 1.0)).collect();
    let denom = (n as f64 - 1.0) * w.iter().sum::<f64>();
    if denom == 0.0 {
        return f64::NAN;
    }

    // Dense 1-based y-ranks (equal y -> equal rank) for Fenwick indexing.
    let mut order_y: Vec<usize> = (0..n).collect();
    order_y.sort_by(|&a, &b| y[a].total_cmp(&y[b]));
    let mut yrank = vec![0usize; n];
    let mut dense = 0usize;
    for k in 0..n {
        if k == 0 || y[order_y[k]].total_cmp(&y[order_y[k - 1]]) != std::cmp::Ordering::Equal {
            dense += 1;
        }
        yrank[order_y[k]] = dense;
    }
    let max_rank = dense;

    let mut order_x: Vec<usize> = (0..n).collect();
    order_x.sort_by(|&a, &b| x[a].total_cmp(&x[b]));

    // Two Fenwick (BIT) trees over y-rank: prefix weight sum and prefix count.
    let mut bit_w = vec![0.0_f64; max_rank + 1];
    let mut bit_c = vec![0.0_f64; max_rank + 1];
    let prefix = |bit: &[f64], mut r: usize| -> f64 {
        let mut s = 0.0;
        while r > 0 {
            s += bit[r];
            r -= r.isolate_lowest_one();
        }
        s
    };
    let mut total_w = 0.0_f64;
    let mut total_c = 0.0_f64;
    let mut numer = 0.0_f64;

    let mut k = 0;
    while k < n {
        let mut g = k + 1;
        while g < n && x[order_x[g]].total_cmp(&x[order_x[k]]) == std::cmp::Ordering::Equal {
            g += 1;
        }
        for &b in &order_x[k..g] {
            let rb = yrank[b];
            let wb = w[b];
            let sum_w_lt = prefix(&bit_w, rb - 1);
            let cnt_lt = prefix(&bit_c, rb - 1);
            let sum_w_le = prefix(&bit_w, rb);
            let cnt_le = prefix(&bit_c, rb);
            let sum_w_gt = total_w - sum_w_le;
            let cnt_gt = total_c - cnt_le;
            numer += (sum_w_lt + wb * cnt_lt) - (sum_w_gt + wb * cnt_gt);
        }
        for &b in &order_x[k..g] {
            let mut r = yrank[b];
            while r <= max_rank {
                bit_w[r] += w[b];
                bit_c[r] += 1.0;
                r += r.isolate_lowest_one();
            }
            total_w += w[b];
            total_c += 1.0;
        }
        k = g;
    }

    numer / denom
}

/// Verbatim O(n²) weighted-tau one-side, retained as the isomorphism oracle for the
/// O(n log n) implementation.
#[cfg(test)]
fn weightedtau_one_side_reference(x: &[f64], y: &[f64], ranks: &[f64]) -> f64 {
    let n = x.len();
    let mut weighted_concordant = 0.0;
    let mut weighted_discordant = 0.0;
    let mut total_weight = 0.0;

    for i in 0..n {
        for j in (i + 1)..n {
            let w = 1.0 / (ranks[i] + 1.0) + 1.0 / (ranks[j] + 1.0);
            let sign = (x[i] - x[j]) * (y[i] - y[j]);
            if sign > 0.0 {
                weighted_concordant += w;
            } else if sign < 0.0 {
                weighted_discordant += w;
            }
            total_weight += w;
        }
    }

    if total_weight == 0.0 {
        return f64::NAN;
    }
    (weighted_concordant - weighted_discordant) / total_weight
}

/// Helper to get ranks (0-indexed) for weighted tau
fn rank_values(data: &[f64]) -> Vec<f64> {
    let n = data.len();
    let mut indexed: Vec<(usize, f64)> = data.iter().copied().enumerate().collect();
    indexed.sort_by(|a, b| a.1.total_cmp(&b.1));

    let mut ranks = vec![0.0; n];
    let mut i = 0;
    while i < n {
        let mut j = i + 1;
        while j < n && indexed[j].1 == indexed[i].1 {
            j += 1;
        }
        let avg_rank = (i + j - 1) as f64 / 2.0;
        for k in i..j {
            ranks[indexed[k].0] = avg_rank;
        }
        i = j;
    }
    ranks
}

/// Result for Chatterjee's Xi correlation.
#[derive(Debug, Clone, PartialEq)]
pub struct ChatterjeeXiResult {
    /// Xi correlation statistic.
    pub statistic: f64,
    /// p-value for independence test.
    pub pvalue: f64,
}

/// Result for multiscale graph correlation.
///
/// Stores the selected MGC statistic, permutation p-value, full local
/// correlation map, and the one-based optimal local scale.
#[derive(Debug, Clone, PartialEq)]
pub struct MultiscaleGraphcorrResult {
    /// Selected multiscale graph correlation statistic in `[0, 1]`.
    pub statistic: f64,
    /// Permutation p-value. Matches SciPy's `1.0` sentinel when `reps == 0`.
    pub pvalue: f64,
    /// Local correlation map across all tested scale pairs.
    pub mgc_map: Vec<Vec<f64>>,
    /// One-based optimal scale in the local correlation map.
    pub opt_scale: (usize, usize),
}

/// Compute Chatterjee's Xi correlation coefficient and independence test.
///
/// Measures association between two variables. Effective even when the
/// association is not monotonic. Returns ~0 for independent variables
/// and ~1 when Y is a measurable function of X.
///
/// Matches `scipy.stats.chatterjeexi(x, y, y_continuous=True)`.
///
/// # Arguments
/// * `x` - Observations of the independent variable
/// * `y` - Corresponding observations of the dependent variable
///
/// # Returns
/// `ChatterjeeXiResult` with statistic and p-value.
///
/// # References
/// Chatterjee, S. (2021). A new coefficient of correlation.
/// Journal of the American Statistical Association.
pub fn chatterjeexi(x: &[f64], y: &[f64]) -> ChatterjeeXiResult {
    let n = x.len();
    if n != y.len() || n < 2 {
        return ChatterjeeXiResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    // Sort indices by x values
    let mut indices: Vec<usize> = (0..n).collect();
    indices.sort_by(|&a, &b| x[a].total_cmp(&x[b]));

    // Reorder y by sorted x
    let y_sorted: Vec<f64> = indices.iter().map(|&i| y[i]).collect();

    // Compute ranks of y_sorted using max method
    let r = rank_max(&y_sorted);

    // Compute sum of |r_{i+1} - r_i|
    let mut num = 0.0;
    for i in 0..(n - 1) {
        num += (r[i + 1] - r[i]).abs();
    }

    // Using y_continuous=True formula: xi = 1 - 3 * num / (n^2 - 1)
    let n_f = n as f64;
    let statistic = 1.0 - 3.0 * num / (n_f * n_f - 1.0);

    // Asymptotic standard deviation for continuous Y: sqrt(2/5) / sqrt(n)
    let std = (2.0_f64 / 5.0).sqrt() / n_f.sqrt();

    // p-value from standard normal (one-tailed, greater)
    let z = statistic / std;
    let pvalue = 1.0 - standard_normal_cdf(z);

    ChatterjeeXiResult { statistic, pvalue }
}

/// Compute the multiscale graph correlation (MGC) statistic.
///
/// MGC is a dependence measure that adapts to the complexity of the relationship
/// between X and Y by computing local correlations at different scales and
/// selecting the optimal scale. This implementation follows Vogelstein et al.
/// (2019) "Discovering and deciphering relationships across disparate data
/// modalities".
///
/// The algorithm:
/// 1. Computes pairwise distance matrices for X and Y
/// 2. Ranks distances within each row to identify k-nearest neighbors
/// 3. Computes local correlations at each scale (k, l) using k-NN for X, l-NN for Y
/// 4. Builds an n×n mgc_map of local correlations
/// 5. Finds optimal scale by smoothing and centering the map
///
/// When `reps > 0`, a permutation test estimates the p-value.
///
/// Matches `scipy.stats.multiscale_graphcorr(x, y, reps=reps, random_state=...)`.
pub fn multiscale_graphcorr(
    x: &[Vec<f64>],
    y: &[Vec<f64>],
    reps: usize,
    random_state: Option<u64>,
) -> Result<MultiscaleGraphcorrResult, StatsError> {
    if x.len() != y.len() {
        return Err(StatsError::InvalidArgument(
            "x and y must have same number of observations".to_string(),
        ));
    }
    validate_graphcorr_observations("x", x)?;
    validate_graphcorr_observations("y", y)?;

    let n = x.len();

    // Compute distance matrices
    let dist_x = pairwise_euclidean_distance_matrix(x);
    let dist_y = pairwise_euclidean_distance_matrix(y);

    // Compute rank matrices (for each row, rank of each distance)
    let rank_x = compute_row_ranks(&dist_x);
    let rank_y = compute_row_ranks(&dist_y);

    // Center the distance matrices
    let centered_x = double_center_distance_matrix(&dist_x);
    let centered_y = double_center_distance_matrix(&dist_y);

    // Build the full n×n mgc_map of local correlations
    let mgc_map = compute_mgc_map(&centered_x, &centered_y, &rank_x, &rank_y, n);

    // Find optimal scale using the smoothed/centered approach
    let (opt_k, opt_l, statistic) = find_optimal_scale(&mgc_map, n);

    // Compute p-value via permutation if requested
    let pvalue = if reps == 0 {
        1.0
    } else {
        mgc_permutation_pvalue(
            &centered_x,
            &centered_y,
            &rank_x,
            &rank_y,
            n,
            statistic,
            reps,
            random_state,
        )
    };

    Ok(MultiscaleGraphcorrResult {
        statistic,
        pvalue,
        mgc_map,
        opt_scale: (opt_k, opt_l),
    })
}

/// Compute row-wise ranks of a distance matrix.
/// For each row, assigns rank 1 to smallest distance, 2 to next, etc.
/// Diagonal (self-distance = 0) gets rank 0.
fn compute_row_ranks(distances: &[Vec<f64>]) -> Vec<Vec<usize>> {
    let n = distances.len();
    if n == 0 {
        return Vec::new();
    }
    // Row i's ranks depend only on distances[i], and the sort key
    // (total_cmp on distance, then ascending index) is a total order, so each row's
    // output is deterministic. Rows are independent, so producing them in parallel is
    // byte-identical to the sequential loop. The self entry (i,i) stays rank 0.
    let row = |i: usize| -> Vec<usize> {
        let mut indexed: Vec<(usize, f64)> = distances[i]
            .iter()
            .enumerate()
            .filter(|(j, _)| *j != i)
            .map(|(j, &d)| (j, d))
            .collect();
        // Total order (distance, then unique ascending index) → an unstable sort
        // yields the identical permutation as a stable one, ~faster. Byte-identical.
        indexed.sort_unstable_by(|a, b| a.1.total_cmp(&b.1).then_with(|| a.0.cmp(&b.0)));
        let mut row_ranks = vec![0usize; n];
        for (rank, (j, _)) in indexed.iter().enumerate() {
            row_ranks[*j] = rank + 1;
        }
        row_ranks
    };

    // Sorting is O(n log n) per row, O(n^2 log n) total; split rows across threads when
    // the matrix is large enough to amortize spawn overhead.
    let work = (n as u64).saturating_mul(n as u64);
    let nthreads = if work < 1 << 18 || n < 8 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / 2)
            .max(1)
    };
    if nthreads <= 1 {
        return (0..n).map(row).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let row = &row;
    std::thread::scope(|scope| {
        let handles: Vec<_> = (0..nthreads)
            .filter_map(|t| {
                let i0 = t * chunk;
                if i0 >= n {
                    return None;
                }
                let i1 = (i0 + chunk).min(n);
                Some(scope.spawn(move || (i0..i1).map(row).collect::<Vec<Vec<usize>>>()))
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("row-ranks worker panicked"))
            .collect()
    })
}

/// Compute the MGC map of local correlations at each scale (k, l).
/// mgc_map[k][l] is the local correlation using k-NN for X and l-NN for Y.
fn compute_mgc_map(
    centered_x: &[Vec<f64>],
    centered_y: &[Vec<f64>],
    rank_x: &[Vec<usize>],
    rank_y: &[Vec<usize>],
    n: usize,
) -> Vec<Vec<f64>> {
    // O(n^2) via 2D prefix sums instead of O(n^4).
    //
    // `local_correlation(k, l)` sums, over every off-diagonal pair (i, j) with
    // rank_x[i][j] < k AND rank_y[i][j] < l, the products cx*cy, cx*cx, cy*cy and a
    // count. A pair with ranks (a, b) is therefore included in EVERY scale (k, l)
    // with k > a and l > b. Scatter each pair's contribution into bucket (a, b) of
    // four accumulator grids, then take a 2D inclusive prefix sum: the prefix value
    // at (k-1, l-1) is exactly the sum over all a <= k-1, b <= l-1, i.e. a < k, b < l.
    //
    // Float note: within a bucket the products are summed in the original (i, j)
    // row-major order, so each bucket equals the original code's partial sum exactly;
    // only the cross-bucket recombination order differs, giving tolerance-parity
    // (no inclusion-exclusion subtraction — two cumulative passes keep it stable).
    // Flat contiguous n*n accumulators (one allocation each, row-major `a*n + b`)
    // instead of four Vec<Vec<f64>> grids: the prefix sums and map build become
    // cache-friendly contiguous sweeps with no per-row heap indirection. The
    // arithmetic and its order are unchanged, so the result is bit-identical to the
    // Vec<Vec> formulation.
    // Co-accessed accumulators packed AoS into one contiguous `n*n` array of
    // [sum_xy, sum_xx, sum_yy, count]. Each pair touches a single cache line for all
    // four sums (instead of four separate 50MB arrays -> 4x the cache misses on the
    // random scatter), and the prefix sum is a single componentwise pass instead of
    // four. Arithmetic and order are unchanged -> bit-identical to the SoA formulation.
    let mut acc = vec![[0.0_f64; 4]; n * n];

    for i in 0..n {
        let rx = &rank_x[i];
        let ry = &rank_y[i];
        let cx_row = &centered_x[i];
        let cy_row = &centered_y[i];
        for j in 0..n {
            if i == j {
                continue;
            }
            let idx = rx[j] * n + ry[j];
            let cx = cx_row[j];
            let cy = cy_row[j];
            let cell = &mut acc[idx];
            cell[0] += cx * cy;
            cell[1] += cx * cx;
            cell[2] += cy * cy;
            cell[3] += 1.0;
        }
    }

    finish_mgc_map_acc(acc, n)
}

/// Compute an MGC map where Y is observed through a permutation vector.
///
/// This is row-isomorphic to building `permute_matrix(centered_y, y_perm)` and
/// `permute_matrix_usize(rank_y, y_perm)` first, then calling `compute_mgc_map`,
/// but avoids two dense n*n materializations per permutation score.
fn compute_mgc_map_permuted_y(
    centered_x: &[Vec<f64>],
    centered_y: &[Vec<f64>],
    rank_x: &[Vec<usize>],
    rank_y: &[Vec<usize>],
    y_perm: &[usize],
    n: usize,
) -> Vec<Vec<f64>> {
    debug_assert_eq!(y_perm.len(), n);
    let mut acc = vec![[0.0_f64; 4]; n * n];

    for i in 0..n {
        let rx = &rank_x[i];
        let cx_row = &centered_x[i];
        let py_i = y_perm[i];
        let cy_row = &centered_y[py_i];
        let ry_row = &rank_y[py_i];
        for j in 0..n {
            if i == j {
                continue;
            }
            let py_j = y_perm[j];
            let idx = rx[j] * n + ry_row[py_j];
            let cx = cx_row[j];
            let cy = cy_row[py_j];
            let cell = &mut acc[idx];
            cell[0] += cx * cy;
            cell[1] += cx * cx;
            cell[2] += cy * cy;
            cell[3] += 1.0;
        }
    }

    finish_mgc_map_acc(acc, n)
}

fn finish_mgc_map_acc(mut acc: Vec<[f64; 4]>, n: usize) -> Vec<Vec<f64>> {
    prefix_sum_2d_inclusive_aos(&mut acc, n);

    // Map cell (k-1, l-1) = corr from the prefix value at (k-1, l-1). Every cell is
    // independent (two sqrt + a divide), so build rows in parallel for large n —
    // bit-identical to the sequential build.
    let build_row = |k: usize| -> Vec<f64> {
        let base = k * n;
        (0..n)
            .map(|l| {
                let [s_xy, s_xx, s_yy, cnt] = acc[base + l];
                if cnt < 1.0 || s_xx <= f64::EPSILON || s_yy <= f64::EPSILON {
                    0.0
                } else {
                    let corr = s_xy / (s_xx.sqrt() * s_yy.sqrt());
                    corr.clamp(-1.0, 1.0).max(0.0)
                }
            })
            .collect()
    };

    let work = (n as u64).saturating_mul(n as u64);
    let nthreads = if work < 1 << 18 || n < 8 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / 2)
            .max(1)
    };
    if nthreads <= 1 {
        return (0..n).map(build_row).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let build_row = &build_row;
    std::thread::scope(|scope| {
        let handles: Vec<_> = (0..nthreads)
            .filter_map(|t| {
                let k0 = t * chunk;
                if k0 >= n {
                    return None;
                }
                let k1 = (k0 + chunk).min(n);
                Some(scope.spawn(move || (k0..k1).map(build_row).collect::<Vec<Vec<f64>>>()))
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("mgc-map build worker panicked"))
            .collect()
    })
}

/// In-place 2D inclusive prefix sum over a flat row-major `n*n` grid of 4-vectors:
/// on return `grid[k*n + l]` holds the componentwise sum of the original cells over
/// all `a <= k`, `b <= l`. Two cumulative passes (along each row, then down the rows),
/// componentwise — no subtraction, so it is numerically stable.
fn prefix_sum_2d_inclusive_aos(grid: &mut [[f64; 4]], n: usize) {
    for k in 0..n {
        let base = k * n;
        for l in 1..n {
            let prev = grid[base + l - 1];
            let cur = &mut grid[base + l];
            for c in 0..4 {
                cur[c] += prev[c];
            }
        }
    }
    for k in 1..n {
        let (head, tail) = grid.split_at_mut(k * n);
        let prev = &head[(k - 1) * n..k * n];
        let cur = &mut tail[0..n];
        for (c, p) in cur.iter_mut().zip(prev.iter()) {
            for t in 0..4 {
                c[t] += p[t];
            }
        }
    }
}

/// Reference O(n^2)-per-scale local correlation at scale (k, l), kept as the
/// isomorphism oracle for the O(n^2) prefix-sum `compute_mgc_map`. Test-only.
/// Uses only pairs (i, j) where j is within k-nearest neighbors of i in X
/// AND i is within l-nearest neighbors of j in Y (or vice versa for symmetry).
#[cfg(test)]
fn local_correlation(
    centered_x: &[Vec<f64>],
    centered_y: &[Vec<f64>],
    rank_x: &[Vec<usize>],
    rank_y: &[Vec<usize>],
    k: usize,
    l: usize,
    n: usize,
) -> f64 {
    // Build indicator matrix: A[i][j] = 1 if rank_x[i][j] <= k AND rank_y[i][j] <= l
    // Using the symmetric formulation from MGC paper
    let mut sum_xy = 0.0;
    let mut sum_xx = 0.0;
    let mut sum_yy = 0.0;
    let mut count = 0.0;

    for i in 0..n {
        for j in 0..n {
            if i == j {
                continue;
            }
            // Include (i,j) if within k-NN for X and l-NN for Y
            if rank_x[i][j] < k && rank_y[i][j] < l {
                sum_xy += centered_x[i][j] * centered_y[i][j];
                sum_xx += centered_x[i][j] * centered_x[i][j];
                sum_yy += centered_y[i][j] * centered_y[i][j];
                count += 1.0;
            }
        }
    }

    if count < 1.0 || sum_xx <= f64::EPSILON || sum_yy <= f64::EPSILON {
        return 0.0;
    }

    let corr = sum_xy / (sum_xx.sqrt() * sum_yy.sqrt());
    corr.clamp(-1.0, 1.0).max(0.0) // MGC uses non-negative correlations
}

/// Find optimal scale in the MGC map.
/// Returns (opt_k, opt_l, statistic) using SciPy's thresholded connected region.
fn find_optimal_scale(mgc_map: &[Vec<f64>], n: usize) -> (usize, usize, f64) {
    if n == 0 {
        return (1, 1, 0.0);
    }

    let mut statistic = mgc_map[n - 1][n - 1];
    let mut best_k = n;
    let mut best_l = n;
    let significant_region = threshold_mgc_map(mgc_map, n);
    let significant_area = significant_region
        .iter()
        .flatten()
        .filter(|&&is_significant| is_significant)
        .count();
    let required_area = (0.02 * n as f64).ceil() as usize * n;

    if significant_area >= required_area {
        for k in 0..n {
            for l in 0..n {
                if significant_region[k][l] && mgc_map[k][l] > statistic + 1.0e-12 {
                    statistic = mgc_map[k][l];
                    best_k = k + 1;
                    best_l = l + 1;
                }
            }
        }
    }

    (best_k, best_l, statistic)
}

fn threshold_mgc_map(mgc_map: &[Vec<f64>], n: usize) -> Vec<Vec<bool>> {
    if n <= 1 {
        return vec![vec![false; n]; n];
    }

    let sample_size = (n - 1) as f64;
    let percentile = 1.0 - (0.02 / sample_size);
    let beta_shape = sample_size * (sample_size - 3.0) / 4.0 - 0.5;
    let beta_quantile = fsci_special::betaincinv_scalar(beta_shape, beta_shape, percentile);
    let mut threshold = beta_quantile.mul_add(2.0, -1.0);
    threshold = threshold.max(mgc_map[n - 1][n - 1]);

    let significant: Vec<Vec<bool>> = mgc_map
        .iter()
        .map(|row| row.iter().map(|&value| value > threshold).collect())
        .collect();
    largest_connected_component(&significant, n)
}

fn largest_connected_component(significant: &[Vec<bool>], n: usize) -> Vec<Vec<bool>> {
    let mut seen = vec![vec![false; n]; n];
    let mut best_component = Vec::new();

    for row in 0..n {
        for col in 0..n {
            if !significant[row][col] || seen[row][col] {
                continue;
            }

            let mut component = Vec::new();
            let mut stack = vec![(row, col)];
            seen[row][col] = true;
            while let Some((cur_row, cur_col)) = stack.pop() {
                component.push((cur_row, cur_col));

                for (next_row, next_col) in mgc_neighbors(cur_row, cur_col, n) {
                    if significant[next_row][next_col] && !seen[next_row][next_col] {
                        seen[next_row][next_col] = true;
                        stack.push((next_row, next_col));
                    }
                }
            }

            if component.len() > best_component.len() {
                best_component = component;
            }
        }
    }

    let mut largest = vec![vec![false; n]; n];
    for (row, col) in best_component {
        largest[row][col] = true;
    }
    largest
}

fn mgc_neighbors(row: usize, col: usize, n: usize) -> impl Iterator<Item = (usize, usize)> {
    [
        row.checked_sub(1).map(|next| (next, col)),
        col.checked_sub(1).map(|next| (row, next)),
        (row + 1 < n).then_some((row + 1, col)),
        (col + 1 < n).then_some((row, col + 1)),
    ]
    .into_iter()
    .flatten()
}

/// Compute p-value for MGC via permutation test.
#[allow(clippy::too_many_arguments)]
fn mgc_permutation_pvalue(
    centered_x: &[Vec<f64>],
    centered_y: &[Vec<f64>],
    rank_x: &[Vec<usize>],
    rank_y: &[Vec<usize>],
    n: usize,
    observed: f64,
    reps: usize,
    random_state: Option<u64>,
) -> f64 {
    // Pre-generate every permutation SEQUENTIALLY from the RNG, so the exact shuffle
    // sequence (hence each permutation) is identical to the old serial loop; only the
    // independent, side-effect-free scoring of each permutation is parallelized below.
    let mut rng = StdRng::seed_from_u64(random_state.unwrap_or(0));
    let mut permutation: Vec<usize> = (0..n).collect();
    let permutations: Vec<Vec<usize>> = (0..reps)
        .map(|_| {
            permutation.shuffle(&mut rng);
            permutation.clone()
        })
        .collect();

    // Each rep is independent: permute Y, build the MGC map, take the optimal-scale
    // statistic, and test it against the observed value. The exceedance tally is a sum of
    // booleans, which is order-independent, so distributing reps across threads is
    // byte-identical to the serial accumulation (same permutations, same per-rep stat,
    // same count).
    let score = |perm: &[usize]| -> bool {
        let perm_map = compute_mgc_map_permuted_y(centered_x, centered_y, rank_x, rank_y, perm, n);
        let (_, _, perm_stat) = find_optimal_scale(&perm_map, n);
        perm_stat >= observed - 1e-12
    };

    // Each permutation scores in O(n²); gate parallelism on total work (reps · n²).
    let work = (reps as u64).saturating_mul((n as u64).saturating_mul(n as u64));
    let nthreads = if work < 1 << 20 || reps < 4 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(reps)
            .max(1)
    };

    let exceed = if nthreads <= 1 {
        permutations.iter().filter(|p| score(p)).count()
    } else {
        let chunk = reps.div_ceil(nthreads);
        let score = &score;
        let permutations = &permutations;
        std::thread::scope(|scope| {
            let handles: Vec<_> =
                (0..nthreads)
                    .filter_map(|t| {
                        let i0 = t * chunk;
                        if i0 >= reps {
                            return None;
                        }
                        let i1 = (i0 + chunk).min(reps);
                        Some(scope.spawn(move || {
                            permutations[i0..i1].iter().filter(|p| score(p)).count()
                        }))
                    })
                    .collect();
            handles
                .into_iter()
                .map(|h| h.join().expect("mgc permutation worker panicked"))
                .sum::<usize>()
        })
    };

    // Matches the serial seed of `exceedances = 1` (the observed statistic counts itself).
    let exceedances = 1 + exceed;
    exceedances as f64 / (reps + 1) as f64
}

/// Permute rows and columns of a matrix according to a permutation.
#[cfg(test)]
fn permute_matrix(matrix: &[Vec<f64>], perm: &[usize]) -> Vec<Vec<f64>> {
    let n = matrix.len();
    let mut result = vec![vec![0.0; n]; n];
    for i in 0..n {
        for j in 0..n {
            result[i][j] = matrix[perm[i]][perm[j]];
        }
    }
    result
}

/// Permute rows and columns of a usize matrix according to a permutation.
#[cfg(test)]
fn permute_matrix_usize(matrix: &[Vec<usize>], perm: &[usize]) -> Vec<Vec<usize>> {
    let n = matrix.len();
    let mut result = vec![vec![0usize; n]; n];
    for i in 0..n {
        for j in 0..n {
            result[i][j] = matrix[perm[i]][perm[j]];
        }
    }
    result
}

fn validate_graphcorr_observations(name: &str, data: &[Vec<f64>]) -> Result<(), StatsError> {
    if data.len() < 2 {
        return Err(StatsError::InvalidArgument(format!(
            "{name} must contain at least two observations"
        )));
    }

    let width = data.first().map_or(0, Vec::len);
    if width == 0 {
        return Err(StatsError::InvalidArgument(format!(
            "{name} observations must be non-empty"
        )));
    }

    for row in data {
        if row.len() != width {
            return Err(StatsError::InvalidArgument(format!(
                "{name} must be rectangular with constant row width"
            )));
        }
        if row.iter().any(|value| !value.is_finite()) {
            return Err(StatsError::InvalidArgument(format!(
                "{name} must contain only finite values"
            )));
        }
    }

    Ok(())
}

fn pairwise_euclidean_distance_matrix(data: &[Vec<f64>]) -> Vec<Vec<f64>> {
    let n = data.len();
    if n == 0 {
        return Vec::new();
    }
    // Each output row i is `[dist(i, 0), .., dist(i, n-1)]`, an independent reduction.
    // dist(i, j) == dist(j, i) bit-for-bit ((a-b)^2 == (b-a)^2 in IEEE754 and the
    // diagonal is sqrt(0)=0), so computing the full matrix row-by-row is byte-identical
    // to the upper-triangle-and-mirror version while making every row disjoint. For
    // large n*n*d the rows are split across threads.
    let d = data[0].len();
    let row = |i: usize| -> Vec<f64> {
        (0..n)
            .map(|j| {
                if i == j {
                    0.0
                } else {
                    data[i]
                        .iter()
                        .zip(data[j].iter())
                        .map(|(left, right)| {
                            let delta = left - right;
                            delta * delta
                        })
                        .sum::<f64>()
                        .sqrt()
                }
            })
            .collect()
    };

    let work = (n as u64)
        .saturating_mul(n as u64)
        .saturating_mul(d.max(1) as u64);
    let nthreads = if work < 1 << 18 || n < 8 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / 2)
            .max(1)
    };
    if nthreads <= 1 {
        return (0..n).map(row).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let row = &row;
    std::thread::scope(|scope| {
        let handles: Vec<_> = (0..nthreads)
            .filter_map(|t| {
                let i0 = t * chunk;
                if i0 >= n {
                    return None;
                }
                let i1 = (i0 + chunk).min(n);
                Some(scope.spawn(move || (i0..i1).map(row).collect::<Vec<Vec<f64>>>()))
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("distance-matrix worker panicked"))
            .collect()
    })
}

fn double_center_distance_matrix(distances: &[Vec<f64>]) -> Vec<Vec<f64>> {
    let n = distances.len();
    if n == 0 {
        return Vec::new();
    }

    let row_means: Vec<f64> = distances
        .iter()
        .map(|row| row.iter().sum::<f64>() / n as f64)
        .collect();
    let mut column_means = vec![0.0; n];
    for row in distances {
        for (j, value) in row.iter().enumerate() {
            column_means[j] += value;
        }
    }
    for mean in &mut column_means {
        *mean /= n as f64;
    }
    let total_mean = row_means.iter().sum::<f64>() / n as f64;

    // Means are kept sequential (column_means is an order-sensitive reduction). The
    // centering write `centered[i][j] = d[i][j] - row_mean[i] - col_mean[j] + total` is
    // per-row independent, so build rows in parallel for large n — byte-identical.
    let row = |i: usize| -> Vec<f64> {
        let di = &distances[i];
        let ri = row_means[i];
        (0..n)
            .map(|j| di[j] - ri - column_means[j] + total_mean)
            .collect()
    };
    let work = (n as u64).saturating_mul(n as u64);
    let nthreads = if work < 1 << 18 || n < 8 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / 2)
            .max(1)
    };
    if nthreads <= 1 {
        return (0..n).map(row).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let row = &row;
    std::thread::scope(|scope| {
        let handles: Vec<_> = (0..nthreads)
            .filter_map(|t| {
                let i0 = t * chunk;
                if i0 >= n {
                    return None;
                }
                let i1 = (i0 + chunk).min(n);
                Some(scope.spawn(move || (i0..i1).map(row).collect::<Vec<Vec<f64>>>()))
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("double-center worker panicked"))
            .collect()
    })
}

/// Compute ranks using max method (number of values <= this value)
fn rank_max(data: &[f64]) -> Vec<f64> {
    // rank_max[i] = #{ j : data[j] <= data[i] }. `<=` on f64 is false whenever either
    // operand is NaN, so NaN entries never count and a NaN query gets 0. Sort the
    // non-NaN values once; for a non-NaN query v the count is the number of sorted
    // values <= v, which is a monotone predicate over the ascending array, so a single
    // partition_point gives it. O(n log n) instead of O(n^2), and because the counts
    // are exact integers the result is bit-identical to the double loop.
    let mut sorted: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
    sorted.sort_by(|a, b| a.partial_cmp(b).expect("non-NaN values compare"));
    data.iter()
        .map(|&v| {
            if v.is_nan() {
                0.0
            } else {
                sorted.partition_point(|&x| x <= v) as f64
            }
        })
        .collect()
}

/// Result of sigma clipping operation.
#[derive(Debug, Clone, PartialEq)]
pub struct SigmaClipResult {
    /// Clipped data array (values within bounds).
    pub clipped: Vec<f64>,
    /// Lower bound used for clipping.
    pub lower: f64,
    /// Upper bound used for clipping.
    pub upper: f64,
}

/// Iteratively sigma-clip data to remove outliers.
///
/// Performs iterative sigma-clipping of array elements. Starting from the full
/// array, elements outside the range [mean - low*std, mean + high*std] are
/// removed. The clipping is repeated until no more elements are removed.
///
/// Matches `scipy.stats.sigmaclip(a, low=low, high=high)`.
///
/// # Arguments
/// * `data` - Input data array
/// * `low` - Number of standard deviations below mean for lower clipping bound
/// * `high` - Number of standard deviations above mean for upper clipping bound
///
/// # Returns
/// `SigmaClipResult` containing clipped array and final bounds.
pub fn sigmaclip(data: &[f64], low: f64, high: f64) -> SigmaClipResult {
    if data.is_empty() {
        return SigmaClipResult {
            clipped: vec![],
            lower: f64::NAN,
            upper: f64::NAN,
        };
    }

    let mut clipped: Vec<f64> = data.iter().copied().filter(|x| x.is_finite()).collect();

    if clipped.is_empty() {
        return SigmaClipResult {
            clipped: vec![],
            lower: f64::NAN,
            upper: f64::NAN,
        };
    }

    loop {
        let n = clipped.len() as f64;
        let mean_val = clipped.iter().sum::<f64>() / n;
        let variance = clipped.iter().map(|&x| (x - mean_val).powi(2)).sum::<f64>() / n;
        let std_val = variance.sqrt();

        let lower = mean_val - low * std_val;
        let upper = mean_val + high * std_val;

        // Clip in place rather than allocating a fresh Vec each iteration. retain
        // keeps the same elements in the same order as filter().collect(), so the
        // result is byte-identical; the length delta drives the convergence check.
        let before = clipped.len();
        clipped.retain(|&x| x >= lower && x <= upper);

        if clipped.len() == before {
            return SigmaClipResult {
                clipped,
                lower,
                upper,
            };
        }

        if clipped.is_empty() {
            return SigmaClipResult {
                clipped: vec![],
                lower: f64::NAN,
                upper: f64::NAN,
            };
        }
    }
}

/// Result for quantile test.
#[derive(Debug, Clone, PartialEq)]
pub struct QuantileTestResult {
    /// Test statistic (T1 or T2 count).
    pub statistic: usize,
    /// Which statistic was used (1 or 2).
    pub statistic_type: u8,
    /// p-value for the test.
    pub pvalue: f64,
}

/// Nonparametric test for a population quantile.
///
/// Tests H0: the p-th population quantile equals q.
/// Uses binomial distribution for the test.
///
/// Matches `scipy.stats.quantile_test(x, q=q, p=p)`.
///
/// # Arguments
/// * `x` - Sample data
/// * `q` - Hypothesized quantile value
/// * `p` - Probability level (0 < p < 1), default 0.5 for median
///
/// When `true`, [`quantile_test`] counts `<= q` and `< q` in two separate passes (the ORIG
/// behaviour); default `false` counts both in one pass. Byte-identical. A/B gate.
#[doc(hidden)]
pub static QUANTILE_TEST_FUSE_DISABLE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// # Returns
/// `QuantileTestResult` with statistic, statistic_type, and pvalue.
///
/// When [`QUANTILE_TEST_FUSE_DISABLE`] is `true`, the `<=`/`<` counts run as two separate
/// passes (the ORIG behaviour); default `false` counts both in one pass. Byte-identical.
pub fn quantile_test(x: &[f64], q: f64, p: f64) -> QuantileTestResult {
    let n = x.len();
    if n == 0 || !(0.0..1.0).contains(&p) || p == 0.0 {
        return QuantileTestResult {
            statistic: 0,
            statistic_type: 0,
            pvalue: f64::NAN,
        };
    }

    // T1 = count of x <= q, T2 = count of x < q — two independent traversals; count both in
    // ONE pass. BYTE-IDENTICAL: the counts are exact integers, order-independent, and every
    // `xi < q` also satisfies `xi <= q`.
    let (t1, t2) = if QUANTILE_TEST_FUSE_DISABLE.load(std::sync::atomic::Ordering::Relaxed) {
        (
            x.iter().filter(|&&xi| xi <= q).count(),
            x.iter().filter(|&&xi| xi < q).count(),
        )
    } else {
        let mut t1 = 0usize;
        let mut t2 = 0usize;
        for &xi in x {
            if xi <= q {
                t1 += 1;
                if xi < q {
                    t2 += 1;
                }
            }
        }
        (t1, t2)
    };

    let binom = Binomial::new(n as u64, p);

    // For two-sided: use the statistic that gives smaller p-value
    // p_greater: P(Y <= t1) for alternative='greater'
    // p_less: P(Y >= t2) = 1 - P(Y < t2) = 1 - P(Y <= t2-1) for alternative='less'

    let p_greater = DiscreteDistribution::cdf(&binom, t1 as u64);
    let p_less = if t2 > 0 {
        1.0 - DiscreteDistribution::cdf(&binom, (t2 - 1) as u64)
    } else {
        1.0
    };

    // Two-sided: min of doubled p-values, clipped to [0, 1]
    let (statistic, statistic_type, pvalue) = if p_greater <= p_less {
        (t1, 1, (2.0 * p_greater).min(1.0))
    } else {
        (t2, 2, (2.0 * p_less).min(1.0))
    };

    QuantileTestResult {
        statistic,
        statistic_type,
        pvalue,
    }
}

/// Exact binomial test.
///
/// Tests H0: probability of success = p, given k successes in n trials.
/// Returns the two-sided p-value.
///
/// Matches `scipy.stats.binomtest(k, n, p)`, INCLUDING its rejections. scipy
/// validates all three arguments and raises rather than returning a value:
///
/// ```text
/// binomtest(k=5, n=3)        ValueError: k (5) must not be greater than n (3).
/// binomtest(k=0, n=0)        ValueError: n must be an integer not less than 1
/// binomtest(k=1, n=3, p=nan) ValueError: p (nan) must be in range [0,1]
/// ```
///
/// This used to collapse all three into a bare `f64::NAN`, so a caller ported
/// from scipy got a number where the incumbent had stopped them
/// (frankenscipy-xb7so). Each is a DELIBERATE validation -- scipy formats the
/// message itself and names the offending value -- which is what distinguishes
/// them from the incidental numpy exceptions catalogued as REJECTED in
/// docs/NEGATIVE_EVIDENCE.md and deliberately not mirrored.
///
/// `p == 0.0` and `p == 1.0` are IN range and have real answers; only NaN and
/// values outside `[0, 1]` are rejected.
pub fn binomtest(k: u64, n: u64, p: f64) -> Result<f64, StatsError> {
    if n == 0 {
        return Err(StatsError::InvalidArgument(
            "n must be an integer not less than 1".to_string(),
        ));
    }
    if k > n {
        return Err(StatsError::InvalidArgument(format!(
            "k ({k}) must not be greater than n ({n})"
        )));
    }
    if p.is_nan() || !(0.0..=1.0).contains(&p) {
        return Err(StatsError::InvalidArgument(format!(
            "p ({p}) must be in range [0,1]"
        )));
    }
    if p == 0.0 {
        return Ok(if k == 0 { 1.0 } else { 0.0 });
    }
    if p == 1.0 {
        return Ok(if k == n { 1.0 } else { 0.0 });
    }

    let binom = Binomial::new(n, p);

    // Two-sided p-value: sum P(X=j) for all j where P(X=j) <= P(X=k)
    let p_observed = DiscreteDistribution::pmf(&binom, k);
    let mut pvalue = 0.0;
    for j in 0..=n {
        let p_j = DiscreteDistribution::pmf(&binom, j);
        if p_j <= p_observed + 1e-14 {
            pvalue += p_j;
        }
    }
    Ok(pvalue.min(1.0))
}

// Internal helpers for skewness and kurtosis
fn skew_from_moments(n: f64, m2: f64, m3: f64) -> f64 {
    if m2 == 0.0 {
        return f64::NAN;
    }
    let m2_n = m2 / n;
    let m3_n = m3 / n;
    m3_n / m2_n.powf(1.5)
}

fn kurtosis_from_moments(n: f64, m2: f64, m4: f64) -> f64 {
    if m2 == 0.0 {
        return f64::NAN; // Degenerate: all values identical
    }
    let m2_n = m2 / n;
    let m4_n = m4 / n;
    m4_n / (m2_n * m2_n) - 3.0
}

/// Return `(rank_lo, rank_hi)` — the `total_cmp`-ordered elements at ranks `lo`
/// and `hi` of `buf` — using partial selection (O(n)) instead of a full
/// O(n log n) sort. Requires `lo <= hi`, `hi - lo <= 1`, `hi < buf.len()`.
///
/// Byte-identical to indexing a fully `total_cmp`-sorted copy: `select_nth_unstable_by`
/// places rank `hi` at position `hi` with every smaller element before it, so the
/// `total_cmp`-max of that lower partition is exactly rank `hi - 1 = lo`.
fn select_ranks(buf: &mut [f64], lo: usize, hi: usize) -> (f64, f64) {
    if lo == hi {
        buf.select_nth_unstable_by(lo, |a, b| a.total_cmp(b));
        let v = buf[lo];
        (v, v)
    } else {
        buf.select_nth_unstable_by(hi, |a, b| a.total_cmp(b));
        let v_hi = buf[hi];
        let v_lo = buf[..hi]
            .iter()
            .copied()
            .reduce(|a, b| if a.total_cmp(&b).is_lt() { b } else { a })
            .unwrap();
        (v_lo, v_hi)
    }
}

/// Linear-interpolation quantile (numpy default), computed in O(n) via
/// [`select_ranks`] instead of sorting. Byte-identical to
/// `quantile_sorted(&total_cmp_sorted_copy, q)`.
fn quantile_select(data: &[f64], q: f64) -> f64 {
    let n = data.len();
    if n == 0 {
        return f64::NAN;
    }
    if n == 1 {
        return data[0];
    }
    let pos = q * (n - 1) as f64;
    let lo = pos.floor() as usize;
    let hi = pos.ceil() as usize;
    let frac = pos - lo as f64;
    let mut buf = data.to_vec();
    let (v_lo, v_hi) = select_ranks(&mut buf, lo, hi);
    if lo == hi {
        v_lo
    } else {
        v_lo * (1.0 - frac) + v_hi * frac
    }
}

fn quantile_sorted(sorted: &[f64], q: f64) -> f64 {
    let n = sorted.len();
    if n == 0 {
        return f64::NAN;
    }
    if n == 1 {
        return sorted[0];
    }
    let pos = q * (n - 1) as f64;
    let lo = pos.floor() as usize;
    let hi = pos.ceil() as usize;
    let frac = pos - lo as f64;
    if lo == hi {
        sorted[lo]
    } else {
        sorted[lo] * (1.0 - frac) + sorted[hi] * frac
    }
}

fn scoreatpercentile_single(
    sorted: &[f64],
    per: f64,
    interpolation_method: &str,
) -> Result<f64, StatsError> {
    if !(0.0..=100.0).contains(&per) || per.is_nan() {
        return Err(StatsError::InvalidArgument(
            "percentile must be in the range [0, 100]".to_string(),
        ));
    }
    if sorted.is_empty() {
        return Ok(f64::NAN);
    }
    if sorted.len() == 1 {
        return Ok(sorted[0]);
    }

    let idx = per / 100.0 * (sorted.len() - 1) as f64;
    let lower = idx.floor() as usize;
    let upper = idx.ceil() as usize;

    if lower == upper {
        return Ok(sorted[lower]);
    }

    let value = match interpolation_method {
        "fraction" => {
            let frac = idx - lower as f64;
            sorted[lower] * (1.0 - frac) + sorted[upper] * frac
        }
        "lower" => sorted[lower],
        "higher" => sorted[upper],
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "interpolation_method must be one of {{'fraction', 'lower', 'higher'}}, got {other}"
            )));
        }
    };
    Ok(value)
}

// ══════════════════════════════════════════════════════════════════════
// Goodness-of-Fit Tests
// ══════════════════════════════════════════════════════════════════════

/// Result of a goodness-of-fit test.
#[derive(Debug, Clone, PartialEq)]
pub struct GoodnessOfFitResult {
    /// Test statistic.
    pub statistic: f64,
    /// p-value.
    pub pvalue: f64,
}

/// Result of the Anderson-Darling test.
#[derive(Debug, Clone, PartialEq)]
pub struct AndersonResult {
    /// Test statistic.
    pub statistic: f64,
    /// Critical values at significance levels [15%, 10%, 5%, 2.5%, 1%].
    pub critical_values: [f64; 5],
    /// Significance levels corresponding to critical values.
    pub significance_level: [f64; 5],
}

/// Result of the k-sample Anderson-Darling test.
#[derive(Debug, Clone, PartialEq)]
pub struct AndersonKSampleResult {
    /// Normalized k-sample Anderson-Darling statistic.
    pub statistic: f64,
    /// Critical values at significance levels [25%, 10%, 5%, 2.5%, 1%, 0.5%, 0.1%].
    pub critical_values: [f64; 7],
    /// Approximate p-value, capped to [0.001, 0.25] without permutation mode.
    pub pvalue: f64,
}

/// Variant of the k-sample Anderson-Darling test.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AndersonKSampleVariant {
    Midrank,
    Right,
    Continuous,
}

/// Target distribution or reference sample for `kstest`.
#[derive(Clone, Copy)]
pub enum KstestTarget<'a> {
    /// One-sample KS against a reference CDF.
    Cdf(fn(f64) -> f64),
    /// Two-sample KS against another sample.
    Sample(&'a [f64]),
}

/// P-value method for the two-sample Cramer-von Mises test.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cvm2SampleMethod {
    Auto,
    Exact,
    Asymptotic,
}

fn anderson_ksamp_statistic_midrank(
    samples: &[Vec<f64>],
    pooled: &[f64],
    unique: &[f64],
    n: &[usize],
    total: usize,
) -> f64 {
    let mut statistic = 0.0;
    let z_left: Vec<usize> = unique
        .iter()
        .map(|&value| pooled.partition_point(|x| *x < value))
        .collect();
    let lj: Vec<f64> = if total == unique.len() {
        vec![1.0; unique.len()]
    } else {
        unique
            .iter()
            .zip(z_left.iter())
            .map(|(&value, &left)| (pooled.partition_point(|x| *x <= value) - left) as f64)
            .collect()
    };
    let bj: Vec<f64> = z_left
        .iter()
        .zip(lj.iter())
        .map(|(&left, &count)| left as f64 + count / 2.0)
        .collect();

    for (sample, &sample_n) in samples.iter().zip(n.iter()) {
        let mut sorted = sample.clone();
        sorted.sort_unstable_by(f64::total_cmp);
        let right_counts: Vec<usize> = unique
            .iter()
            .map(|&value| sorted.partition_point(|x| *x <= value))
            .collect();
        let left_counts: Vec<usize> = unique
            .iter()
            .map(|&value| sorted.partition_point(|x| *x < value))
            .collect();
        let mij: Vec<f64> = right_counts
            .iter()
            .zip(left_counts.iter())
            .map(|(&right, &left)| right as f64 - (right - left) as f64 / 2.0)
            .collect();

        let mut inner_sum = 0.0;
        for ((&l_j, &b_j), &m_ij) in lj.iter().zip(bj.iter()).zip(mij.iter()) {
            let denominator = b_j * (total as f64 - b_j) - total as f64 * l_j / 4.0;
            if denominator > 0.0 {
                let term = l_j / total as f64
                    * (total as f64 * m_ij - b_j * sample_n as f64).powi(2)
                    / denominator;
                inner_sum += term;
            }
        }
        statistic += inner_sum / sample_n as f64;
    }

    statistic * (total as f64 - 1.0) / total as f64
}

fn anderson_ksamp_statistic_right(
    samples: &[Vec<f64>],
    pooled: &[f64],
    unique: &[f64],
    n: &[usize],
    total: usize,
) -> f64 {
    let unique_prefix = &unique[..unique.len().saturating_sub(1)];
    let lj: Vec<f64> = unique_prefix
        .iter()
        .map(|&value| {
            let left = pooled.partition_point(|x| *x < value);
            let right = pooled.partition_point(|x| *x <= value);
            (right - left) as f64
        })
        .collect();
    let mut bj = Vec::with_capacity(lj.len());
    let mut running = 0.0;
    for &count in &lj {
        running += count;
        bj.push(running);
    }

    let mut statistic = 0.0;
    for (sample, &sample_n) in samples.iter().zip(n.iter()) {
        let mut sorted = sample.clone();
        sorted.sort_unstable_by(f64::total_cmp);
        let mij: Vec<f64> = unique_prefix
            .iter()
            .map(|&value| sorted.partition_point(|x| *x <= value) as f64)
            .collect();
        let mut inner_sum = 0.0;
        for ((&l_j, &b_j), &m_ij) in lj.iter().zip(bj.iter()).zip(mij.iter()) {
            let denominator = b_j * (total as f64 - b_j);
            if denominator > 0.0 {
                inner_sum += l_j / total as f64
                    * (total as f64 * m_ij - b_j * sample_n as f64).powi(2)
                    / denominator;
            }
        }
        statistic += inner_sum / sample_n as f64;
    }
    statistic
}

fn anderson_ksamp_statistic_continuous(
    samples: &[Vec<f64>],
    pooled: &[f64],
    n: &[usize],
    total: usize,
) -> f64 {
    let mut statistic = 0.0;
    let js: Vec<f64> = (1..total).map(|j| j as f64).collect();

    for (sample, &sample_n) in samples.iter().zip(n.iter()) {
        let mut sorted = sample.clone();
        sorted.sort_unstable_by(f64::total_cmp);
        let mij: Vec<f64> = pooled[..pooled.len().saturating_sub(1)]
            .iter()
            .map(|&value| sorted.partition_point(|x| *x <= value) as f64)
            .collect();
        let mut inner_sum = 0.0;
        for (&j, &m_ij) in js.iter().zip(mij.iter()) {
            inner_sum +=
                (total as f64 * m_ij - j * sample_n as f64).powi(2) / (j * (total as f64 - j));
        }
        statistic += inner_sum / sample_n as f64;
    }

    statistic / total as f64
}

fn quadratic_least_squares_eval(xs: &[f64], ys: &[f64], x: f64) -> f64 {
    let n = xs.len() as f64;
    let sum_x = xs.iter().sum::<f64>();
    let sum_x2 = xs.iter().map(|value| value * value).sum::<f64>();
    let sum_x3 = xs.iter().map(|value| value * value * value).sum::<f64>();
    let sum_x4 = xs
        .iter()
        .map(|value| value * value * value * value)
        .sum::<f64>();
    let sum_y = ys.iter().sum::<f64>();
    let sum_xy = xs
        .iter()
        .zip(ys.iter())
        .map(|(xv, yv)| xv * yv)
        .sum::<f64>();
    let sum_x2y = xs
        .iter()
        .zip(ys.iter())
        .map(|(xv, yv)| xv * xv * yv)
        .sum::<f64>();

    let mut augmented = [
        [sum_x4, sum_x3, sum_x2, sum_x2y],
        [sum_x3, sum_x2, sum_x, sum_xy],
        [sum_x2, sum_x, n, sum_y],
    ];

    for pivot in 0..3 {
        let (best_row, best_value) = augmented
            .iter()
            .enumerate()
            .skip(pivot)
            .map(|(row_idx, row)| (row_idx, row[pivot].abs()))
            .max_by(|left, right| left.1.total_cmp(&right.1))
            .unwrap_or((pivot, 0.0));
        if best_value <= f64::EPSILON {
            return f64::NAN;
        }
        if best_row != pivot {
            augmented.swap(pivot, best_row);
        }

        let pivot_value = augmented[pivot][pivot];
        for value in augmented[pivot].iter_mut().skip(pivot) {
            *value /= pivot_value;
        }

        for row in 0..3 {
            if row == pivot {
                continue;
            }
            let factor = augmented[row][pivot];
            let pivot_slice: Vec<f64> = augmented[pivot].iter().copied().skip(pivot).collect();
            for (value, pivot_value) in augmented[row]
                .iter_mut()
                .skip(pivot)
                .zip(pivot_slice.iter())
            {
                *value -= factor * pivot_value;
            }
        }
    }

    let a = augmented[0][3];
    let b = augmented[1][3];
    let c = augmented[2][3];
    a * x * x + b * x + c
}

/// K-sample Anderson-Darling test.
///
/// Matches the core non-permutation behavior of `scipy.stats.anderson_ksamp`.
pub fn anderson_ksamp(
    samples: &[Vec<f64>],
    variant: Option<AndersonKSampleVariant>,
) -> Result<AndersonKSampleResult, StatsError> {
    if samples.len() < 2 {
        return Err(StatsError::InvalidArgument(
            "anderson_ksamp needs at least two samples".to_string(),
        ));
    }
    if samples.iter().any(Vec::is_empty) {
        return Err(StatsError::InvalidArgument(
            "anderson_ksamp encountered sample without observations".to_string(),
        ));
    }

    let mut pooled: Vec<f64> = samples
        .iter()
        .flat_map(|sample| sample.iter().copied())
        .collect();
    pooled.sort_unstable_by(f64::total_cmp);
    let mut unique = pooled.clone();
    unique.dedup_by(|a, b| a.total_cmp(b).is_eq());
    if unique.len() < 2 {
        return Err(StatsError::InvalidArgument(
            "anderson_ksamp needs more than one distinct observation".to_string(),
        ));
    }

    let n: Vec<usize> = samples.iter().map(Vec::len).collect();
    let total = pooled.len();
    let k = samples.len();
    let statistic_raw = match variant.unwrap_or(AndersonKSampleVariant::Midrank) {
        AndersonKSampleVariant::Midrank => {
            anderson_ksamp_statistic_midrank(samples, &pooled, &unique, &n, total)
        }
        AndersonKSampleVariant::Right => {
            anderson_ksamp_statistic_right(samples, &pooled, &unique, &n, total)
        }
        AndersonKSampleVariant::Continuous => {
            anderson_ksamp_statistic_continuous(samples, &pooled, &n, total)
        }
    };

    let harmonic_sum: f64 = n.iter().map(|&count| 1.0 / count as f64).sum();
    let hs_cs: Vec<f64> = (2..=(total - 1))
        .rev()
        .scan(0.0, |acc, value| {
            *acc += 1.0 / value as f64;
            Some(*acc)
        })
        .collect();
    let h = hs_cs.last().copied().unwrap_or(0.0) + 1.0;
    let g: f64 = hs_cs
        .iter()
        .zip(2..total)
        .map(|(&value, denom)| value / denom as f64)
        .sum();

    let m = (k - 1) as f64;
    let a = (4.0 * g - 6.0) * m + (10.0 - 6.0 * g) * harmonic_sum;
    let b = (2.0 * g - 4.0) * (k * k) as f64
        + 8.0 * h * k as f64
        + (2.0 * g - 14.0 * h - 4.0) * harmonic_sum
        - 8.0 * h
        + 4.0 * g
        - 6.0;
    let c = (6.0 * h + 2.0 * g - 2.0) * (k * k) as f64
        + (4.0 * h - 4.0 * g + 6.0) * k as f64
        + (2.0 * h - 6.0) * harmonic_sum
        + 4.0 * h;
    let d = (2.0 * h + 6.0) * (k * k) as f64 - 4.0 * h * k as f64;
    let total_f = total as f64;
    let sigma_sq = (a * total_f.powi(3) + b * total_f.powi(2) + c * total_f + d)
        / ((total_f - 1.0) * (total_f - 2.0) * (total_f - 3.0));
    let normalized = (statistic_raw - m) / sigma_sq.sqrt();

    let b0 = [0.675, 1.281, 1.645, 1.96, 2.326, 2.573, 3.085];
    let b1 = [-0.245, 0.25, 0.678, 1.149, 1.822, 2.364, 3.615];
    let b2 = [-0.105, -0.305, -0.362, -0.391, -0.396, -0.345, -0.154];
    let critical_values = std::array::from_fn(|i| b0[i] + b1[i] / m.sqrt() + b2[i] / m);
    let significance: [f64; 7] = [0.25, 0.1, 0.05, 0.025, 0.01, 0.005, 0.001];
    let pvalue = if normalized < critical_values[0] {
        significance[0]
    } else if normalized > critical_values[critical_values.len() - 1] {
        significance[significance.len() - 1]
    } else {
        let ys: Vec<f64> = significance.iter().map(|value| (*value).ln()).collect();
        let xs: Vec<f64> = critical_values.to_vec();
        quadratic_least_squares_eval(&xs, &ys, normalized).exp()
    };

    Ok(AndersonKSampleResult {
        statistic: normalized,
        critical_values,
        pvalue: pvalue.clamp(0.001, 0.25),
    })
}

/// One-sample Kolmogorov-Smirnov test.
///
/// Tests H0: data comes from the distribution specified by `cdf_func`.
/// The CDF function maps x -> P(X <= x) for the reference distribution.
///
/// Matches `scipy.stats.ks_1samp(data, cdf_func)`.
// Scaling constants for the exact KS distribution (powers of two are exact in
// f64): _EP128 = 2^128, _EM128 = 2^-128. frankenscipy-ksk1u
const KS_EP128: f64 = 3.402823669209385e38; // 2^128
const KS_EM128: f64 = 2.938735877055719e-39; // 2^-128

/// x · 2^exp without intermediate overflow (matches numpy.ldexp).
fn ks_ldexp(mut x: f64, mut exp: i32) -> f64 {
    while exp > 1000 {
        x *= 2f64.powi(1000);
        exp -= 1000;
    }
    while exp < -1000 {
        x *= 2f64.powi(-1000);
        exp += 1000;
    }
    x * 2f64.powi(exp)
}

fn ks_matmul(a: &[Vec<f64>], b: &[Vec<f64>], m: usize) -> Vec<Vec<f64>> {
    let mut c = vec![vec![0.0f64; m]; m];
    for i in 0..m {
        for l in 0..m {
            let ail = a[i][l];
            if ail == 0.0 {
                continue;
            }
            let bl = &b[l];
            let ci = &mut c[i];
            for j in 0..m {
                ci[j] += ail * bl[j];
            }
        }
    }
    c
}

/// Exact CDF P(D_n ≤ d) via the Durbin matrix (Marsaglia-Tsang-Wang). Port of
/// scipy.stats `_kolmogn_DMTW`. frankenscipy-ksk1u
fn kolmogn_dmtw(n: usize, d: f64) -> f64 {
    if d >= 1.0 {
        return 1.0;
    }
    let nf = n as f64;
    let nd = nf * d;
    if nd <= 0.5 {
        return 0.0;
    }
    let k = nd.ceil() as usize;
    let h = k as f64 - nd;
    let m = 2 * k - 1;

    let mut v = vec![0.0f64; m];
    let mut w = vec![0.0f64; m];
    for jj in 1..=m {
        v[jj - 1] = 1.0 - h.powi(jj as i32);
    }
    let mut fac = 1.0f64;
    for jj in 1..=m {
        w[jj - 1] = fac;
        fac /= jj as f64;
        v[jj - 1] *= fac;
    }
    let tt = (2.0 * h - 1.0).max(0.0).powi(m as i32) - 2.0 * h.powi(m as i32);
    v[m - 1] = (1.0 + tt) * fac;

    let mut hmat = vec![vec![0.0f64; m]; m];
    for i in 1..m {
        for t in 0..(m - i + 1) {
            hmat[i - 1 + t][i] = w[t];
        }
    }
    for i in 0..m {
        hmat[i][0] = v[i];
    }
    for j in 0..m {
        hmat[m - 1][j] = v[m - 1 - j];
    }

    let mut hpwr = vec![vec![0.0f64; m]; m];
    for (i, row) in hpwr.iter_mut().enumerate() {
        row[i] = 1.0;
    }
    let mut hh = hmat;
    let mut nn = n;
    let mut expnt: i32 = 0;
    let mut hexpnt: i32 = 0;
    while nn > 0 {
        if nn % 2 == 1 {
            hpwr = ks_matmul(&hpwr, &hh, m);
            expnt += hexpnt;
        }
        hh = ks_matmul(&hh, &hh, m);
        hexpnt *= 2;
        if hh[k - 1][k - 1].abs() > KS_EP128 {
            for row in hh.iter_mut() {
                for x in row.iter_mut() {
                    *x /= KS_EP128;
                }
            }
            hexpnt += 128;
        }
        nn /= 2;
    }
    let mut p = hpwr[k - 1][k - 1];
    for i in 1..=n {
        p = i as f64 * p / nf;
        if p.abs() < KS_EM128 {
            p *= KS_EP128;
            expnt -= 128;
        }
    }
    if expnt != 0 {
        p = ks_ldexp(p, expnt);
    }
    p.clamp(0.0, 1.0)
}

fn pomeranz_j1j2(i: usize, n: usize, ll: i64, ceilf: i64, roundf: i64) -> (i64, i64) {
    let (j1, j2): (i64, i64);
    let n = n as i64;
    if i == 0 {
        j1 = -ll - ceilf - 1;
        j2 = ll + ceilf - 1;
    } else {
        let ip1 = (i + 1) as i64;
        let ip1div2 = ip1 / 2;
        let ip1mod2 = ip1 % 2;
        if ip1mod2 == 0 {
            if ip1div2 == n + 1 {
                j1 = n - ll - ceilf - 1;
                j2 = n + ll + ceilf - 1;
            } else {
                j1 = ip1div2 - 1 - ll - roundf - 1;
                j2 = ip1div2 + ll - 1 + ceilf - 1;
            }
        } else {
            j1 = ip1div2 - 1 - ll - 1;
            j2 = ip1div2 + ll + roundf - 1;
        }
    }
    ((j1 + 2).max(0), j2.min(n))
}

/// Exact CDF P(D_n ≤ x) via the Pomeranz recursion. Port of scipy.stats
/// `_kolmogn_Pomeranz`. frankenscipy-ksk1u
fn kolmogn_pomeranz(n: usize, x: f64) -> f64 {
    let nf = n as f64;
    let t = nf * x;
    let ll = t.floor() as i64;
    let f = t - ll as f64;
    let g = f.min(1.0 - f);
    let ceilf = if f > 0.0 { 1i64 } else { 0 };
    let roundf = if f > 0.5 { 1i64 } else { 0 };
    let npwrs = (2 * (ll + 1)) as usize;
    let mut gpower = vec![0.0f64; npwrs];
    let mut twogpower = vec![0.0f64; npwrs];
    let mut onem2gpower = vec![0.0f64; npwrs];
    gpower[0] = 1.0;
    twogpower[0] = 1.0;
    onem2gpower[0] = 1.0;
    let g_over_n = g / nf;
    let two_g_over_n = 2.0 * g / nf;
    let one_minus_two_g_over_n = (1.0 - 2.0 * g) / nf;
    for mm in 1..npwrs {
        gpower[mm] = gpower[mm - 1] * g_over_n / mm as f64;
        twogpower[mm] = twogpower[mm - 1] * two_g_over_n / mm as f64;
        onem2gpower[mm] = onem2gpower[mm - 1] * one_minus_two_g_over_n / mm as f64;
    }
    let mut v0 = vec![0.0f64; npwrs];
    let mut v1 = vec![0.0f64; npwrs];
    v1[0] = 1.0;
    let mut v0s: i64 = 0;
    let mut v1s: i64 = 0;
    let mut expnt: i32 = 0;
    let (mut j1, _) = pomeranz_j1j2(0, n, ll, ceilf, roundf);
    for i in 1..(2 * n + 2) {
        let k1 = j1;
        std::mem::swap(&mut v0, &mut v1);
        std::mem::swap(&mut v0s, &mut v1s);
        for val in v1.iter_mut() {
            *val = 0.0;
        }
        let (nj1, nj2) = pomeranz_j1j2(i, n, ll, ceilf, roundf);
        j1 = nj1;
        let pwrs: &[f64] = if i == 1 || i == 2 * n + 1 {
            &gpower
        } else if i % 2 == 1 {
            &twogpower
        } else {
            &onem2gpower
        };
        let ln2 = nj2 - k1 + 1;
        if ln2 > 0 {
            let start = (k1 - v0s) as usize;
            let a = &v0[start..start + ln2 as usize];
            let b = &pwrs[..ln2 as usize];
            let conv_start = (nj1 - k1) as usize;
            let conv_len = (nj2 - nj1 + 1) as usize;
            // Left indexed on purpose. `idx` both indexes v1 AND drives the
            // convolution offset (cpos = conv_start + idx). Converting to
            // v1.iter_mut().enumerate().take(conv_len) requires conv_len <=
            // v1.len(), and that bound is NOT locally evident — v1 is sized
            // `npwrs` while conv_len comes from the nj1/nj2 window. If the bound
            // can ever fail, the current form panics whereas take() would
            // silently compute a short convolution and return a wrong
            // distribution. Not rewriting until someone traces the nj1/nj2
            // bounds; a wrong answer is worse than a lint.
            #[allow(clippy::needless_range_loop)]
            for idx in 0..conv_len {
                let cpos = conv_start + idx;
                let lo = if cpos >= b.len() {
                    cpos - (b.len() - 1)
                } else {
                    0
                };
                let hi = cpos.min(a.len() - 1);
                let mut s = 0.0;
                let mut p = lo;
                while p <= hi {
                    s += a[p] * b[cpos - p];
                    p += 1;
                }
                v1[idx] = s;
            }
            let mx = v1.iter().cloned().fold(0.0f64, f64::max);
            if mx > 0.0 && mx < KS_EM128 {
                for val in v1.iter_mut() {
                    *val *= KS_EP128;
                }
                expnt -= 128;
            }
            v1s = v0s + nj1 - k1;
        }
    }
    let mut ans = v1[(n as i64 - v1s) as usize];
    for mm in 1..=n {
        if ans.abs() > KS_EP128 {
            ans *= KS_EM128;
            expnt += 128;
        }
        ans *= mm as f64;
    }
    if expnt != 0 {
        ans = ks_ldexp(ans, expnt);
    }
    ans.clamp(0.0, 1.0)
}

/// Exact SF P(D_n ≥ x) for the two-sided one-sample KS statistic, matching
/// scipy.stats `_kolmogn(n, x, cdf=False)` (kstwo.sf). Returns `None` only for
/// the n>140 Pelz-Good body, where the caller uses the asymptotic series.
/// frankenscipy-ksk1u
fn kolmogn_sf(n: usize, x: f64) -> Option<f64> {
    if x >= 1.0 {
        return Some(0.0);
    }
    if x <= 0.0 {
        return Some(1.0);
    }
    let nf = n as f64;
    let t = nf * x;
    if t <= 1.0 {
        // Ruben-Gambino, 1/2n ≤ x ≤ 1/n.
        if t <= 0.5 {
            return Some(1.0);
        }
        let cdf = if n <= 140 {
            let mut p = 1.0;
            for i in 1..=n {
                p *= (i as f64 / nf) * (2.0 * t - 1.0);
            }
            p
        } else {
            let rn = 1.0 / nf;
            let log_nfac = nf.ln() / 2.0 - nf
                + (2.0 * std::f64::consts::PI).ln() / 2.0
                + rn * ks_stirling_poly(rn / nf);
            (log_nfac + nf * (2.0 * t - 1.0).ln()).exp()
        };
        return Some((1.0 - cdf).clamp(0.0, 1.0));
    }
    if t >= nf - 1.0 {
        return Some((2.0 * (1.0 - x).powi(n as i32)).clamp(0.0, 1.0));
    }
    if x >= 0.5 {
        return Some((2.0 * fsci_special::smirnov(n as i32, x)).clamp(0.0, 1.0));
    }
    let nxsq = t * x;
    if n <= 140 {
        if nxsq <= 0.754693 {
            return Some((1.0 - kolmogn_dmtw(n, x)).clamp(0.0, 1.0));
        }
        if nxsq <= 4.0 {
            return Some((1.0 - kolmogn_pomeranz(n, x)).clamp(0.0, 1.0));
        }
        return Some((2.0 * fsci_special::smirnov(n as i32, x)).clamp(0.0, 1.0));
    }
    // n > 140.
    if nxsq >= 2.2 {
        return Some((2.0 * fsci_special::smirnov(n as i32, x)).clamp(0.0, 1.0));
    }
    if n <= 100_000 && nf * x.powf(1.5) <= 1.4 {
        return Some((1.0 - kolmogn_dmtw(n, x)).clamp(0.0, 1.0));
    }
    Some((1.0 - kolmogn_pelzgood_cdf(n, x)).clamp(0.0, 1.0))
}

/// Pelz-Good theta-function approximation to the CDF P(D_n ≤ x). Port of
/// scipy.stats `_kolmogn_PelzGood(n, x, cdf=True)`. frankenscipy-ksk1u
fn kolmogn_pelzgood_cdf(n: usize, x: f64) -> f64 {
    if x <= 0.0 {
        return 0.0;
    }
    if x >= 1.0 {
        return 1.0;
    }
    let nf = n as f64;
    let pi = std::f64::consts::PI;
    let pi2 = pi * pi;
    let pi4 = pi2 * pi2;
    let pi6 = pi4 * pi2;
    let z = nf.sqrt() * x;
    let zsq = z * z;
    let z3 = z * zsq;
    let z4 = zsq * zsq;
    let z6 = z4 * zsq;

    let qlog = -pi2 / 8.0 / zsq;
    if qlog < -708.0 {
        return 0.0;
    }
    let q0 = qlog.exp();

    let k1a = -zsq;
    let k1b = pi2 / 4.0;
    let k2a = 6.0 * z6 + 2.0 * z4;
    let k2b = (2.0 * z4 - 5.0 * zsq) * pi2 / 4.0;
    let k2c = pi4 * (1.0 - 2.0 * zsq) / 16.0;
    let k3d = pi6 * (5.0 - 30.0 * zsq) / 64.0;
    let k3c = pi4 * (-60.0 * zsq + 212.0 * z4) / 16.0;
    let k3b = pi2 * (135.0 * z4 - 96.0 * z6) / 4.0;
    let k3a = -30.0 * z6 - 90.0 * z.powi(8);

    let maxk = (16.0 * z / pi).ceil() as i64;
    let mut k = [0.0f64; 4];
    let mut kk = maxk;
    while kk >= 1 {
        let m = (2 * kk - 1) as f64;
        let msq = m * m;
        let m4 = msq * msq;
        let m6 = m4 * msq;
        let qpower = q0.powi((8 * kk) as i32);
        let coeffs = [
            1.0,
            k1a + k1b * msq,
            k2a + k2b * msq + k2c * m4,
            k3a + k3b * msq + k3c * m4 + k3d * m6,
        ];
        for i in 0..4 {
            k[i] = k[i] * qpower + coeffs[i];
        }
        kk -= 1;
    }
    let sqrt2pi = (2.0 * pi).sqrt();
    let denom = [z, 6.0 * z4, 72.0 * z.powi(7), 6480.0 * z.powi(10)];
    for i in 0..4 {
        k[i] = k[i] * q0 * sqrt2pi / denom[i];
    }

    let q = (-pi2 / 2.0 / zsq).exp();
    let sqrt3z = 3.0f64.sqrt() * z;
    let mut k2extra = 0.0;
    let mut k3extra = 0.0;
    let mut kk = maxk;
    while kk >= 1 {
        let ks = kk as f64;
        let ksq = ks * ks;
        let qpw = q.powi((kk * kk) as i32);
        k2extra += ksq * qpw;
        let kspi = pi * ks;
        k3extra += (sqrt3z + kspi) * (sqrt3z - kspi) * ksq * qpw;
        kk -= 1;
    }
    k[2] += k2extra * pi2 * sqrt2pi / (-36.0 * z3);
    k[3] += k3extra * pi2 * sqrt2pi / (216.0 * z6);

    for (i, ki) in k.iter_mut().enumerate() {
        *ki /= nf.powf(i as f64 / 2.0);
    }
    k[0] + k[1] + k[2] + k[3]
}

/// Stirling-series correction polynomial for log(n!/n^n) (scipy coeffs).
fn ks_stirling_poly(z: f64) -> f64 {
    // Transcribed VERBATIM from scipy's coefficient table. Every literal parses
    // to exactly the same f64 as its shortest round-trip form (verified), so the
    // extra digits cost nothing at runtime — they exist so this block can be
    // diffed character-for-character against upstream. Shortening them would
    // make the table look like a different set of coefficients than scipy's.
    #[allow(clippy::excessive_precision)]
    const C: [f64; 8] = [
        -2.955065359477124183e-2,
        6.4102564102564102564e-3,
        -1.9175269175269175269e-3,
        8.4175084175084175084e-4,
        -5.952380952380952381e-4,
        7.9365079365079365079e-4,
        -2.7777777777777777778e-3,
        8.3333333333333333333e-2,
    ];
    let mut acc = 0.0;
    for &c in &C {
        acc = acc * z + c;
    }
    acc
}

/// When `true`, [`ks_1samp`] computes its KS statistic serially (the ORIG behaviour); default `false`
/// fans the independent per-point CDF evaluations + max reduction across cores for large inputs.
/// Byte-identical. A/B knob.
#[doc(hidden)]
pub static KS_1SAMP_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn ks_1samp(data: &[f64], cdf_func: impl Fn(f64) -> f64 + Sync) -> GoodnessOfFitResult {
    let n = data.len();
    if n == 0 || data.iter().any(|v| v.is_nan()) {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }
    let nf = n as f64;

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    // D = max_i { max(|i/n - F(x_i)|, |(i-1)/n - F(x_i)|) }. Each point's `F(x_i)` (a potentially heavy
    // reference CDF, e.g. erf/gammainc) is INDEPENDENT, and the outer `max` is associative/commutative
    // incl NaN (any-NaN ⇒ NaN, matching the serial guard) with no signed-zero issue (|·| ≥ +0.0), so a
    // chunk-max-then-merge is BYTE-IDENTICAL to the sequential fold. Fan across cores for large n.
    let nan_max = |a: f64, b: f64| {
        if a.is_nan() || b.is_nan() {
            f64::NAN
        } else {
            a.max(b)
        }
    };
    let point_max = |i: usize, x: f64| -> f64 {
        let f_x = cdf_func(x);
        let d_plus = ((i + 1) as f64 / nf - f_x).abs();
        let d_minus = (f_x - i as f64 / nf).abs();
        nan_max(d_plus, d_minus)
    };
    const KS_MIN_PER_THREAD: usize = 400_000;
    let nthreads = if KS_1SAMP_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed)
        || n < 2 * KS_MIN_PER_THREAD
    {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n / KS_MIN_PER_THREAD)
            .max(1)
    };
    let d_stat = if nthreads <= 1 {
        sorted
            .iter()
            .enumerate()
            .fold(0.0_f64, |d, (i, &x)| nan_max(d, point_max(i, x)))
    } else {
        let chunk = n.div_ceil(nthreads);
        let point_max = &point_max;
        let nan_max = &nan_max;
        let parts: Vec<f64> = std::thread::scope(|scope| {
            sorted
                .chunks(chunk)
                .enumerate()
                .map(|(c, block)| {
                    let base = c * chunk;
                    scope.spawn(move || {
                        block
                            .iter()
                            .enumerate()
                            .fold(0.0_f64, |d, (li, &x)| nan_max(d, point_max(base + li, x)))
                    })
                })
                .collect::<Vec<_>>()
                .into_iter()
                .map(|h| h.join().expect("ks_1samp worker panicked"))
                .collect()
        });
        parts.into_iter().fold(0.0_f64, nan_max)
    };

    // scipy's two-sided ks_1samp uses the EXACT KS distribution for n ≤ 10000
    // (method='auto'); only the n>140 Pelz-Good body falls back to the
    // asymptotic Kolmogorov series. frankenscipy-ksk1u
    let pvalue = if !d_stat.is_nan() && n <= 10_000 {
        kolmogn_sf(n, d_stat).unwrap_or_else(|| kolmogorov_pvalue(d_stat, nf))
    } else {
        kolmogorov_pvalue(d_stat, nf)
    };

    GoodnessOfFitResult {
        statistic: d_stat,
        pvalue,
    }
}

/// Kolmogorov-Smirnov test wrapper.
///
/// Dispatches to one-sample or two-sample KS based on `target`.
///
/// Matches the core SciPy surface of `scipy.stats.kstest`.
pub fn kstest(data: &[f64], target: KstestTarget<'_>) -> GoodnessOfFitResult {
    match target {
        KstestTarget::Cdf(cdf) => ks_1samp(data, cdf),
        KstestTarget::Sample(reference) => ks_2samp(data, reference),
    }
}

/// Epps-Singleton two-sample test with SciPy's default support points.
pub fn epps_singleton_2samp(x: &[f64], y: &[f64]) -> GoodnessOfFitResult {
    match epps_singleton_2samp_with_t(x, y, &[0.4, 0.8]) {
        Ok(result) => result,
        Err(_) => GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        },
    }
}

/// Epps-Singleton two-sample test with explicit positive support points `t`.
pub fn epps_singleton_2samp_with_t(
    x: &[f64],
    y: &[f64],
    t: &[f64],
) -> Result<GoodnessOfFitResult, StatsError> {
    if x.len() < 5 || y.len() < 5 {
        return Ok(GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        });
    }
    if t.is_empty() {
        return Err(StatsError::InvalidArgument(
            "t must not be empty".to_string(),
        ));
    }
    if t.iter().any(|&value| value <= 0.0 || !value.is_finite()) {
        return Err(StatsError::InvalidArgument(
            "t must contain positive finite elements only".to_string(),
        ));
    }
    for (i, &value) in t.iter().enumerate() {
        if t.iter().skip(i + 1).any(|&other| other == value) {
            return Err(StatsError::InvalidArgument(
                "t must contain distinct elements".to_string(),
            ));
        }
    }
    if x.iter().any(|v| !v.is_finite()) || y.iter().any(|v| !v.is_finite()) {
        return Ok(GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        });
    }

    let mut pooled = x.to_vec();
    pooled.extend_from_slice(y);
    let sigma = iqr(&pooled) / 2.0;
    if !sigma.is_finite() || sigma == 0.0 {
        return Ok(GoodnessOfFitResult {
            statistic: 0.0,
            pvalue: f64::NAN,
        });
    }

    let scaled_t: Vec<f64> = t.iter().map(|&value| value / sigma).collect();
    let feature_dim = 2 * scaled_t.len();
    let feature_row = |sample: f64| -> Vec<f64> {
        let mut row = Vec::with_capacity(feature_dim);
        for &t_value in &scaled_t {
            row.push((t_value * sample).cos());
        }
        for &t_value in &scaled_t {
            row.push((t_value * sample).sin());
        }
        row
    };

    let gx: Vec<Vec<f64>> = x.iter().copied().map(feature_row).collect();
    let gy: Vec<Vec<f64>> = y.iter().copied().map(feature_row).collect();
    let cov_x = covariance_biased(&gx);
    let cov_y = covariance_biased(&gy);

    let nx = x.len() as f64;
    let ny = y.len() as f64;
    let n_total = nx + ny;
    let mut est_cov = vec![vec![0.0; feature_dim]; feature_dim];
    for (i, row) in est_cov.iter_mut().enumerate() {
        for (j, value) in row.iter_mut().enumerate() {
            *value = (n_total / nx) * cov_x[i][j] + (n_total / ny) * cov_y[i][j];
        }
    }

    let (pinv, rank) = symmetric_pseudoinverse_and_rank(&est_cov);
    if rank == 0 {
        return Ok(GoodnessOfFitResult {
            statistic: 0.0,
            pvalue: f64::NAN,
        });
    }

    let mut mean_x = vec![0.0; feature_dim];
    let mut mean_y = vec![0.0; feature_dim];
    for row in &gx {
        for (j, value) in row.iter().enumerate() {
            mean_x[j] += value;
        }
    }
    for row in &gy {
        for (j, value) in row.iter().enumerate() {
            mean_y[j] += value;
        }
    }
    for value in &mut mean_x {
        *value /= nx;
    }
    for value in &mut mean_y {
        *value /= ny;
    }
    let g_diff: Vec<f64> = mean_x
        .iter()
        .zip(mean_y.iter())
        .map(|(&a, &b)| a - b)
        .collect();
    let pinv_times_diff = matvec_mul(&pinv, &g_diff);
    let mut statistic = n_total * dot(&g_diff, &pinv_times_diff);

    if x.len().max(y.len()) < 25 {
        let correction = 1.0 / (1.0 + n_total.powf(-0.45) + 10.1 * (nx.powf(-1.7) + ny.powf(-1.7)));
        statistic *= correction;
    }

    let pvalue = ChiSquared::new(rank as f64).sf(statistic).clamp(0.0, 1.0);
    Ok(GoodnessOfFitResult { statistic, pvalue })
}

fn cvm_cdf_inf(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }
    if x <= 0.0 {
        return 0.0;
    }

    let mut total = 0.0;
    for k in 0..256 {
        let kf = k as f64;
        let y = 4.0 * kf + 1.0;
        let q = y * y / (16.0 * x);
        let coeff = (ln_gamma(kf + 0.5) - ln_gamma(kf + 1.0)).exp() / (PI.powf(1.5) * x.sqrt());
        let term = coeff * y.sqrt() * (-q).exp() * modified_bessel_k(0.25, q);
        if !term.is_finite() {
            break;
        }
        total += term;
        if term.abs() < 1e-10 {
            break;
        }
    }
    total.clamp(0.0, 1.0)
}

/// Csörgő-Faraway (1996) finite-sample correction term ψ₁_mod for the
/// Cramér-von Mises cdf. Defined in equation 1.10 of the paper, with
/// the V(x)/12 term factored out (added back at the call site as the
/// (1 + 1/(12n)) factor on cvm_cdf_inf(x)).
///
/// This port mirrors `scipy.stats._hypotests._psi1_mod` line-for-line
/// (frankenscipy-4cv67); it is itself a port of Faraway's MAPLE code
/// and the goftest R package.
fn cvm_psi1_mod(x: f64) -> f64 {
    if x <= 0.0 || !x.is_finite() {
        return 0.0;
    }
    let sx = 2.0 * x.sqrt();
    let y1 = x.powf(0.75);
    let y2 = x.powf(1.25);
    let sqrt_pi = PI.sqrt();

    let ed2 = |y: f64| -> f64 {
        let z = y * y / 4.0;
        let b = modified_bessel_k(0.25, z) + modified_bessel_k(0.75, z);
        (-z).exp() * (y / 2.0).powf(1.5) * b / sqrt_pi
    };
    let ed3 = |y: f64| -> f64 {
        let z = y * y / 4.0;
        let k14 = modified_bessel_k(0.25, z);
        let k34 = modified_bessel_k(0.75, z);
        // fsci_special::kv(1.25, z) returns NaN today (negative-order
        // iv sign bug), so we obtain K_{5/4}(z) via the upward
        // recurrence K_{ν+1}(z) = K_{ν-1}(z) + (2ν/z) K_ν(z) with
        // ν = 1/4, giving K_{5/4}(z) = K_{3/4}(z) + K_{1/4}(z) / (2z).
        let k54 = k34 + k14 / (2.0 * z);
        let kv_terms = 2.0 * k14 + 3.0 * k34 - k54;
        ((-z).exp() / sqrt_pi) * (y / 2.0).powf(2.5) * kv_terms
    };

    let mut tot = 0.0_f64;
    for k in 0..256usize {
        let kf = k as f64;
        let m = 2.0 * kf + 1.0;
        let g1 = ln_gamma(kf + 0.5).exp();
        let g3 = ln_gamma(kf + 1.5).exp();
        let e1 = m * g1 * ed2((4.0 * kf + 3.0) / sx) / (9.0 * y1);
        let e2 = g1 * ed3((4.0 * kf + 1.0) / sx) / (72.0 * y2);
        let e3 = 2.0 * (m + 2.0) * g3 * ed3((4.0 * kf + 5.0) / sx) / (12.0 * y2);
        let e4 = 7.0 * m * g1 * ed2((4.0 * kf + 1.0) / sx) / (144.0 * y1);
        let e5 = 7.0 * m * g1 * ed2((4.0 * kf + 5.0) / sx) / (144.0 * y1);
        let a_k = e1 + e2 + e3 + e4 + e5;
        let gamma_kp1 = ln_gamma(kf + 1.0).exp();
        let z = -a_k / (PI * gamma_kp1);
        if !z.is_finite() {
            break;
        }
        tot += z;
        if z.abs() < 1.0e-7 && k > 0 {
            break;
        }
    }
    tot
}

fn cvm_cdf(x: f64, n: Option<usize>) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }
    match n {
        None => cvm_cdf_inf(x),
        Some(sample_size) => {
            let nf = sample_size as f64;
            if x <= 1.0 / (12.0 * nf) {
                0.0
            } else if x >= nf / 3.0 {
                1.0
            } else {
                // Csörgő-Faraway 1996 finite-n correction
                // (frankenscipy-4cv67):
                //   F_n(x) ≈ F_∞(x) · (1 + 1/(12n)) + ψ₁_mod(x) / n
                // where ψ₁_mod is given by `cvm_psi1_mod` and the (1 +
                // 1/(12n)) factor absorbs the V(x)/12 term factored
                // out of ψ₁ for the second-call-saving of F_∞.
                let inf = cvm_cdf_inf(x);
                (inf * (1.0 + 1.0 / (12.0 * nf)) + cvm_psi1_mod(x) / nf).clamp(0.0, 1.0)
            }
        }
    }
}

/// One-sample Cramer-von Mises goodness-of-fit test.
///
/// Matches `scipy.stats.cramervonmises(data, cdf)`.
/// When `true`, [`cramervonmises`] evaluates its CDF terms serially (the ORIG behaviour); default
/// `false` materialises the per-point CDF via a parallel map for large inputs, then folds the W²
/// sum serially in index order. Byte-identical. A/B knob.
#[doc(hidden)]
pub static CVM_FORCE_SERIAL: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

pub fn cramervonmises(data: &[f64], cdf_func: impl Fn(f64) -> f64 + Sync) -> GoodnessOfFitResult {
    let n = data.len();
    if n <= 1 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    let nf = n as f64;
    let base = 1.0 / (12.0 * nf);
    // W² = base + Σ_i (uᵢ - F(x_i))². `F(x_i)` is a heavy independent per-point CDF (erf/gammainc) but
    // the Σ is a float reduction (can't chunk-merge byte-id), so MATERIALISE the CDF values with a
    // parallel order-preserving map then fold serially in index order from `base` — BYTE-IDENTICAL to
    // the fused serial `map(cdf).fold`. Only for n≥4M: the extra cdf_vals Vec adds an alloc + a second
    // pass that a 2-thread parallel map doesn't offset (measured 0.97x@1M), and the serial `total_cmp`
    // sort caps the ceiling ~1.3x; below 4M keep the no-alloc fused serial fold. `CVM_FORCE_SERIAL`.
    const CVM_MIN_PER_THREAD: usize = 400_000;
    let statistic = if CVM_FORCE_SERIAL.load(std::sync::atomic::Ordering::Relaxed) || n < 4_000_000
    {
        sorted.iter().enumerate().fold(base, |acc, (i, &x)| {
            let ui = (2.0 * (i + 1) as f64 - 1.0) / (2.0 * nf);
            let cdf = cdf_func(x);
            acc + (ui - cdf) * (ui - cdf)
        })
    } else {
        let cdf_vals = par_continuous_map_min(&sorted, CVM_MIN_PER_THREAD, &cdf_func);
        cdf_vals.iter().enumerate().fold(base, |acc, (i, &cdf)| {
            let ui = (2.0 * (i + 1) as f64 - 1.0) / (2.0 * nf);
            acc + (ui - cdf) * (ui - cdf)
        })
    };
    let pvalue = (1.0 - cvm_cdf(statistic, Some(n))).clamp(0.0, 1.0);

    GoodnessOfFitResult { statistic, pvalue }
}

fn lcm_u64(a: u64, b: u64) -> u64 {
    a / gcd_u64(a, b) * b
}

fn gcd_u64(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn binomial_u128(n: u64, k: u64) -> u128 {
    let k = k.min(n - k);
    let mut result = 1u128;
    for i in 0..k {
        result = result * (n - i) as u128 / (i + 1) as u128;
    }
    result
}

fn cvm_2samp_exact_pvalue(u_stat: u64, nx: usize, ny: usize) -> f64 {
    use std::collections::BTreeMap;

    let m = nx as u64;
    let n = ny as u64;
    let lcm = lcm_u64(m, n);
    let a = lcm / m;
    let b = lcm / n;
    let mn = m * n;
    let zeta = (lcm as i128
        * lcm as i128
        * (m + n) as i128
        * (6 * u_stat as i128 - (mn * (4 * mn - 1)) as i128))
        / (6 * mn as i128 * mn as i128);

    let mut gs: Vec<BTreeMap<i128, u128>> = std::iter::once({
        let mut seed = BTreeMap::new();
        seed.insert(0, 1);
        seed
    })
    .chain((0..m).map(|_| BTreeMap::new()))
    .collect();

    for u in 0..=n {
        let mut next_gs = Vec::with_capacity((m + 1) as usize);
        let mut tmp: BTreeMap<i128, u128> = BTreeMap::new();
        for v in 0..=m {
            for (&value, &freq) in &gs[v as usize] {
                *tmp.entry(value).or_insert(0) += freq;
            }
            let shift = (a as i128 * v as i128 - b as i128 * u as i128).pow(2);
            let shifted = tmp
                .iter()
                .map(|(&value, &freq)| (value + shift, freq))
                .collect::<BTreeMap<_, _>>();
            next_gs.push(shifted.clone());
            tmp = shifted;
        }
        gs = next_gs;
    }

    let combinations = binomial_u128(m + n, m) as f64;
    let tail = gs[m as usize]
        .iter()
        .filter(|(value, _)| **value >= zeta)
        .map(|(_, &freq)| freq as f64)
        .sum::<f64>();
    (tail / combinations).clamp(0.0, 1.0)
}

fn cvm_2samp_asymptotic_pvalue(statistic: f64, nx: usize, ny: usize) -> f64 {
    let nxf = nx as f64;
    let nyf = ny as f64;
    let n_total = nxf + nyf;
    let k = nxf * nyf;
    let expected_t = (1.0 + 1.0 / n_total) / 6.0;
    let variance_t = (n_total + 1.0)
        * (4.0 * k * n_total - 3.0 * (nxf * nxf + nyf * nyf) - 2.0 * k)
        / (45.0 * n_total * n_total * 4.0 * k);
    let normalized = 1.0 / 6.0 + (statistic - expected_t) / (45.0 * variance_t).sqrt();
    if normalized < 0.003 {
        1.0
    } else {
        (1.0 - cvm_cdf_inf(normalized)).clamp(0.0, 1.0)
    }
}

/// Two-sample Cramer-von Mises test with SciPy's default auto method.
///
/// Matches `scipy.stats.cramervonmises_2samp(x, y)`.
pub fn cramervonmises_2samp(x: &[f64], y: &[f64]) -> GoodnessOfFitResult {
    cramervonmises_2samp_with_method(x, y, Cvm2SampleMethod::Auto)
}

/// Two-sample Cramer-von Mises test with explicit p-value method selection.
pub fn cramervonmises_2samp_with_method(
    x: &[f64],
    y: &[f64],
    method: Cvm2SampleMethod,
) -> GoodnessOfFitResult {
    let nx = x.len();
    let ny = y.len();
    if nx <= 1 || ny <= 1 || x.iter().any(|v| v.is_nan()) || y.iter().any(|v| v.is_nan()) {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let mut xa = x.to_vec();
    let mut ya = y.to_vec();
    sort_f64_total(&mut xa);
    sort_f64_total(&mut ya);

    let mut pooled = xa.clone();
    pooled.extend_from_slice(&ya);
    let ranks = rankdata_average(&pooled);
    let rx = &ranks[..nx];
    let ry = &ranks[nx..];

    let u_stat_x = rx
        .iter()
        .enumerate()
        .map(|(i, &rank)| (rank - (i + 1) as f64).powi(2))
        .sum::<f64>();
    let u_stat_y = ry
        .iter()
        .enumerate()
        .map(|(i, &rank)| (rank - (i + 1) as f64).powi(2))
        .sum::<f64>();
    let u_stat = nx as f64 * u_stat_x + ny as f64 * u_stat_y;
    let k = (nx * ny) as f64;
    let n_total = (nx + ny) as f64;
    let statistic = u_stat / (k * n_total) - (4.0 * k - 1.0) / (6.0 * n_total);

    let pvalue = match method {
        Cvm2SampleMethod::Exact => cvm_2samp_exact_pvalue(u_stat.round() as u64, nx, ny),
        Cvm2SampleMethod::Asymptotic => cvm_2samp_asymptotic_pvalue(statistic, nx, ny),
        Cvm2SampleMethod::Auto => {
            if nx.max(ny) > 20 {
                cvm_2samp_asymptotic_pvalue(statistic, nx, ny)
            } else {
                cvm_2samp_exact_pvalue(u_stat.round() as u64, nx, ny)
            }
        }
    };

    GoodnessOfFitResult { statistic, pvalue }
}

/// Two-sample Kolmogorov-Smirnov test.
///
/// Tests H0: two samples come from the same continuous distribution.
///
/// Matches `scipy.stats.ks_2samp(data1, data2)`.
pub fn ks_2samp(data1: &[f64], data2: &[f64]) -> GoodnessOfFitResult {
    let n1 = data1.len();
    let n2 = data2.len();
    if n1 == 0 || n2 == 0 || data1.iter().any(|v| v.is_nan()) || data2.iter().any(|v| v.is_nan()) {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let mut sorted1 = data1.to_vec();
    let mut sorted2 = data2.to_vec();
    sort_f64_total(&mut sorted1);
    sort_f64_total(&mut sorted2);
    ks_2samp_sorted(&sorted1, &sorted2)
}

/// [`ks_2samp`] on inputs already sorted ascending (`total_cmp` order) and NaN-free. Skips the
/// per-call NaN check + sort so an all-pairs matrix can sort each sample ONCE up front (the sort is
/// query-independent). BYTE-IDENTICAL to `ks_2samp` on the same finite data: same sorted arrays feed
/// the same merge sweep and p-value.
fn ks_2samp_sorted(sorted1: &[f64], sorted2: &[f64]) -> GoodnessOfFitResult {
    let (n1, n2) = (sorted1.len(), sorted2.len());
    if n1 == 0 || n2 == 0 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    // Walk both sorted arrays, computing max |F1(x) - F2(x)|
    let n1f = n1 as f64;
    let n2f = n2 as f64;
    let mut i = 0;
    let mut j = 0;
    let mut d_stat = 0.0_f64;

    while i < n1 || j < n2 {
        let val1 = if i < n1 { sorted1[i] } else { f64::INFINITY };
        let val2 = if j < n2 { sorted2[j] } else { f64::INFINITY };
        let current_val = val1.min(val2);

        // Advance both indices past all elements <= current_val to handle ties
        while i < n1 && sorted1[i] <= current_val {
            i += 1;
        }
        while j < n2 && sorted2[j] <= current_val {
            j += 1;
        }

        let diff = (i as f64 / n1f - j as f64 / n2f).abs();
        d_stat = d_stat.max(diff);
    }

    let (statistic, pvalue) =
        if let Some((exact_d, exact_pvalue)) = ks_2samp_exact_pvalue(d_stat, n1, n2) {
            (exact_d, exact_pvalue)
        } else {
            let en = (n1f * n2f / (n1f + n2f)).sqrt();
            (d_stat, kolmogorov_pvalue(d_stat, en * en))
        };

    GoodnessOfFitResult { statistic, pvalue }
}

/// Two-sample Kolmogorov-Smirnov test with alternative hypothesis.
///
/// Matches `scipy.stats.ks_2samp(data1, data2, alternative=...)`.
///
/// * `alternative` - "two-sided" (default), "less", or "greater"
///   - "two-sided": max|F1(x) - F2(x)|
///   - "greater": max(F1(x) - F2(x)) - tests if F1 > F2
///   - "less": max(F2(x) - F1(x)) - tests if F1 < F2
pub fn ks_2samp_alternative(
    data1: &[f64],
    data2: &[f64],
    alternative: &str,
) -> GoodnessOfFitResult {
    let n1 = data1.len();
    let n2 = data2.len();
    if n1 == 0 || n2 == 0 || data1.iter().any(|v| v.is_nan()) || data2.iter().any(|v| v.is_nan()) {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let mut sorted1 = data1.to_vec();
    let mut sorted2 = data2.to_vec();
    sort_f64_total(&mut sorted1);
    sort_f64_total(&mut sorted2);

    let n1f = n1 as f64;
    let n2f = n2 as f64;
    let mut i = 0;
    let mut j = 0;
    let mut d_plus = 0.0_f64; // max(F1 - F2)
    let mut d_minus = 0.0_f64; // max(F2 - F1)

    while i < n1 || j < n2 {
        let val1 = if i < n1 { sorted1[i] } else { f64::INFINITY };
        let val2 = if j < n2 { sorted2[j] } else { f64::INFINITY };
        let current_val = val1.min(val2);

        while i < n1 && sorted1[i] <= current_val {
            i += 1;
        }
        while j < n2 && sorted2[j] <= current_val {
            j += 1;
        }

        let diff = i as f64 / n1f - j as f64 / n2f;
        d_plus = d_plus.max(diff);
        d_minus = d_minus.max(-diff);
    }

    let (d_stat, mode) = match alternative {
        "greater" => (d_plus, "greater"),
        "less" => (d_minus, "less"),
        _ => (d_plus.max(d_minus), "two-sided"),
    };

    let en = (n1f * n2f / (n1f + n2f)).sqrt();
    let pvalue = if mode == "two-sided" {
        kolmogorov_pvalue(d_stat, en * en)
    } else {
        // One-sided asymptotic: Hodges' Eqn 5.3 correction (matches
        // scipy.stats.ks_2samp asymp branch). scipy uses
        //   z = sqrt(m*n/(m+n)) * d_stat
        // where m = max(n1, n2), n = min(n1, n2). fsci's `en` above is
        // ALREADY sqrt(n1*n2/(n1+n2)) (the inner ratio is already taken
        // sqrt of), so z = en * d_stat directly — DON'T sqrt again.
        //   expt = -2 z² - 2 z (m + 2n) / [3 sqrt(m n (m+n))]
        // (See Hodges 1958, "The significance probability of the
        // Smirnov two-sample test", Eqn 5.3.)
        let z = en * d_stat;
        let m = n1f.max(n2f);
        let n_min = n1f.min(n2f);
        let denom = (m * n_min * (m + n_min)).sqrt();
        let correction = if denom > 0.0 {
            2.0 * z * (m + 2.0 * n_min) / denom / 3.0
        } else {
            0.0
        };
        let expt = -2.0 * z * z - correction;
        expt.exp()
    };

    GoodnessOfFitResult {
        statistic: d_stat,
        pvalue: pvalue.clamp(0.0, 1.0),
    }
}

fn ks_2samp_exact_pvalue(d: f64, n1: usize, n2: usize) -> Option<(f64, f64)> {
    if n1 == 0 || n2 == 0 || n1.max(n2) > KS_2SAMP_EXACT_MAX_N {
        return None;
    }

    let n1u = n1 as u64;
    let n2u = n2 as u64;
    let g = gcd_u64(n1u, n2u);
    let lcm = (n1u / g).checked_mul(n2u)?;
    let h = (d * lcm as f64).round() as u64;
    let snapped_d = h as f64 / lcm as f64;

    if h == 0 {
        return Some((snapped_d, 1.0));
    }

    let a = (n2u / g) as i128;
    let b = (n1u / g) as i128;
    let mut inside_prob = vec![0.0_f64; n2 + 1];

    for i in 0..=n1 {
        let mut left_prob = 0.0_f64;
        for (j, cell) in inside_prob.iter_mut().enumerate().take(n2 + 1) {
            let top_prob = *cell;
            let current = if i == 0 && j == 0 {
                1.0
            } else {
                let delta = ((i as i128 * a) - (j as i128 * b)).unsigned_abs();
                if delta >= h as u128 {
                    0.0
                } else if i == 0 {
                    left_prob
                } else if j == 0 {
                    top_prob
                } else {
                    let denom = (i + j) as f64;
                    top_prob * (i as f64 / denom) + left_prob * (j as f64 / denom)
                }
            };
            *cell = current;
            left_prob = current;
        }
    }

    Some((snapped_d, (1.0 - inside_prob[n2]).clamp(0.0, 1.0)))
}

fn shapiro_poly(coeffs: &[f64], x: f64) -> f64 {
    let nord = coeffs.len();
    let mut result = coeffs[0];
    if nord == 1 {
        return result;
    }

    let mut p = x * coeffs[nord - 1];
    if nord == 2 {
        return result + p;
    }

    for ind in (1..=(nord - 2)).rev() {
        p = (p + coeffs[ind]) * x;
    }
    result += p;
    result
}

fn shapiro_ppnd(p: f64) -> f64 {
    const SPLIT: f64 = 0.42;
    const A0: f64 = 2.50662823884;
    const A1: f64 = -18.61500062529;
    const A2: f64 = 41.39119773534;
    const A3: f64 = -25.44106049637;
    const B1: f64 = -8.47351093090;
    const B2: f64 = 23.08336743743;
    const B3: f64 = -21.06224101826;
    const B4: f64 = 3.13082909833;
    const C0: f64 = -2.78718931138;
    const C1: f64 = -2.29796479134;
    const C2: f64 = 4.85014127135;
    const C3: f64 = 2.32121276858;
    const D1: f64 = 3.54388924762;
    const D2: f64 = 1.63706781897;

    let q = p - 0.5;
    if q.abs() <= SPLIT {
        let r = q * q;
        let mut temp = q * (((A3 * r + A2) * r + A1) * r + A0);
        temp /= ((((B4 * r + B3) * r + B2) * r + B1) * r) + 1.0;
        return temp;
    }

    let mut r = if q > 0.0 { 1.0 - p } else { p };
    if r <= 0.0 {
        return 0.0;
    }

    r = (-r.ln()).sqrt();
    let mut temp = (((C3 * r + C2) * r + C1) * r) + C0;
    temp /= ((D2 * r + D1) * r) + 1.0;
    if q < 0.0 { -temp } else { temp }
}

fn shapiro_alnorm(x: f64, upper: bool) -> f64 {
    const LTONE: f64 = 7.0;
    const UTZERO: f64 = 38.0;
    const CON: f64 = 1.28;
    const A1: f64 = 0.398_942_280_444;
    const A2: f64 = 0.399_903_438_504;
    const A3: f64 = 5.758_854_804_58;
    const A4: f64 = 29.821_355_780_8;
    const A5: f64 = 2.624_331_216_79;
    const A6: f64 = 48.695_993_069_2;
    const A7: f64 = 5.928_857_244_38;
    const B1: f64 = 0.398_942_280_385;
    const B2: f64 = 3.8052e-8;
    const B3: f64 = 1.000_006_153_02;
    const B4: f64 = 3.980_647_94e-4;
    const B5: f64 = 1.986_153_813_64;
    const B6: f64 = 0.151_679_116_635;
    const B7: f64 = 5.293_303_249_26;
    const B8: f64 = 4.838_591_280_8;
    const B9: f64 = 15.150_897_245_1;
    const B10: f64 = 0.742_380_924_027;
    const B11: f64 = 30.789_933_034;
    const B12: f64 = 3.990_194_170_11;

    let mut z = x;
    let mut upper_tail = upper;
    if !matches!(z.partial_cmp(&0.0), Some(std::cmp::Ordering::Greater)) {
        upper_tail = false;
        z = -z;
    }

    if !((z <= LTONE) || (upper_tail && z <= UTZERO)) {
        return if upper_tail { 0.0 } else { 1.0 };
    }

    let y = 0.5 * z * z;
    let temp = if z <= CON {
        0.5 - z * (A1 - A2 * y / (y + A3 - A4 / (y + A5 + A6 / (y + A7))))
    } else {
        B1 * (-y).exp()
            / (z - B2
                + B3 / (z + B4 + B5 / (z - B6 + B7 / (z + B8 - B9 / (z + B10 + B11 / (z + B12))))))
    };
    if upper_tail { temp } else { 1.0 - temp }
}

fn shapiro_swilk(sorted: &[f64]) -> GoodnessOfFitResult {
    const C1: [f64; 6] = [0.0, 0.221157, -0.147981, -2.07119, 4.434685, -2.706056];
    const C2: [f64; 6] = [0.0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633];
    const C3: [f64; 4] = [0.5440, -0.39978, 0.025054, -0.0006714];
    const C4: [f64; 4] = [1.3822, -0.77857, 0.062767, -0.0020322];
    const C5: [f64; 4] = [-1.5861, -0.31082, -0.083751, 0.0038915];
    const C6: [f64; 3] = [-0.4803, -0.082676, 0.0030302];
    const G: [f64; 2] = [-2.273, 0.459];
    const SMALL: f64 = 1e-19;
    const SQRTH: f64 = std::f64::consts::FRAC_1_SQRT_2;
    const PI6: f64 = 6.0 / std::f64::consts::PI;

    let n = sorted.len();
    let n2 = n / 2;
    let an = n as f64;
    let mut a = vec![0.0; n2];

    if n == 3 {
        a[0] = SQRTH;
    } else {
        let an25 = an + 0.25;
        let mut summ2 = 0.0;
        for (index, coeff) in a.iter_mut().enumerate() {
            let temp = shapiro_ppnd((index as f64 + 1.0 - 0.375) / an25);
            *coeff = temp;
            summ2 += temp * temp;
        }
        summ2 *= 2.0;

        let ssumm2 = summ2.sqrt();
        let rsn = 1.0 / an.sqrt();
        let a1 = shapiro_poly(&C1, rsn) - (a[0] / ssumm2);

        let (start, fac) = if n > 5 {
            let a2 = -(a[1] / ssumm2) + shapiro_poly(&C2, rsn);
            let numerator = summ2 - (2.0 * a[0] * a[0]) - (2.0 * a[1] * a[1]);
            let denominator = 1.0 - (2.0 * a1 * a1) - (2.0 * a2 * a2);
            a[1] = a2;
            (2, (numerator / denominator).sqrt())
        } else {
            let numerator = summ2 - (2.0 * a[0] * a[0]);
            let denominator = 1.0 - (2.0 * a1 * a1);
            (1, (numerator / denominator).sqrt())
        };

        a[0] = a1;
        for coeff in a.iter_mut().skip(start) {
            *coeff *= -1.0 / fac;
        }
    }

    let range = sorted[n - 1] - sorted[0];
    if range < SMALL {
        return GoodnessOfFitResult {
            statistic: 1.0,
            pvalue: 1.0,
        };
    }

    let mut sx = sorted[0] / range;
    let mut sa = -a[0];
    let mut mirrored = n - 2;
    for index in 1..n {
        let xi = sorted[index] / range;
        sx += xi;
        if index != mirrored {
            let sign = if index < mirrored { -1.0 } else { 1.0 };
            sa += sign * a[index.min(mirrored)];
        }
        mirrored = mirrored.saturating_sub(1);
    }

    sa /= an;
    sx /= an;

    let mut ssa = 0.0;
    let mut ssx = 0.0;
    let mut sax = 0.0;
    mirrored = n - 1;
    for (index, &value) in sorted.iter().enumerate() {
        let asa = if index != mirrored {
            let sign = if index < mirrored { -1.0 } else { 1.0 };
            sign * a[index.min(mirrored)] - sa
        } else {
            -sa
        };
        let xsx = value / range - sx;
        ssa += asa * asa;
        ssx += xsx * xsx;
        sax += asa * xsx;
        mirrored = mirrored.saturating_sub(1);
    }

    let ssassx = (ssa * ssx).sqrt();
    let w1 = (ssassx - sax) * (ssassx + sax) / (ssa * ssx);
    let w = 1.0 - w1;

    let pvalue = if n == 3 {
        if w < 0.75 {
            return GoodnessOfFitResult {
                statistic: 0.75,
                pvalue: 0.0,
            };
        }
        1.0 - PI6 * w.sqrt().acos()
    } else {
        let mut y = w1.ln();
        let xx = an.ln();
        let (m, s) = if n <= 11 {
            let gamma = shapiro_poly(&G, an);
            if y >= gamma {
                return GoodnessOfFitResult {
                    statistic: w,
                    pvalue: SMALL,
                };
            }
            y = -(gamma - y).ln();
            (shapiro_poly(&C3, an), shapiro_poly(&C4, an).exp())
        } else {
            (shapiro_poly(&C5, xx), shapiro_poly(&C6, xx).exp())
        };
        shapiro_alnorm((y - m) / s, true)
    };

    GoodnessOfFitResult {
        statistic: w,
        pvalue: pvalue.clamp(0.0, 1.0),
    }
}

/// Shapiro-Wilk test for normality.
///
/// Tests H0: data was drawn from a normal distribution.
/// Most powerful normality test for small to moderate sample sizes.
///
/// Matches `scipy.stats.shapiro(data)`.
///
/// Uses the Royston (1995) `swilk` algorithm that SciPy wraps.
pub fn shapiro(data: &[f64]) -> GoodnessOfFitResult {
    if data.len() < 3 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));
    shapiro_swilk(&sorted)
}

/// D'Agostino's skewness test for normality.
///
/// Tests H0: the population skewness matches the normal distribution's skewness.
///
/// Matches `scipy.stats.skewtest(data, nan_policy=..., alternative=...)`.
pub fn skewtest(
    data: &[f64],
    nan_policy: Option<&str>,
    alternative: Option<&str>,
) -> Result<GoodnessOfFitResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;
    let alternative = validate_hypothesis_alternative(alternative)?;

    let filtered;
    let working = match nan_policy {
        "propagate" => {
            if data.iter().any(|value| value.is_nan()) {
                return Ok(GoodnessOfFitResult {
                    statistic: f64::NAN,
                    pvalue: f64::NAN,
                });
            }
            data
        }
        "raise" => {
            if data.iter().any(|value| value.is_nan()) {
                return Err(StatsError::InvalidArgument(
                    "The input contains nan values".to_string(),
                ));
            }
            data
        }
        "omit" => {
            filtered = data
                .iter()
                .copied()
                .filter(|value| !value.is_nan())
                .collect::<Vec<_>>();
            filtered.as_slice()
        }
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "nan_policy must be one of {{'propagate', 'raise', 'omit'}}, got {other}"
            )));
        }
    };

    if working.len() < 8 {
        return Ok(GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        });
    }

    let z = dagostino_skewtest_z(skew(working), working.len() as f64);
    Ok(GoodnessOfFitResult {
        statistic: z,
        pvalue: normal_alternative_pvalue(z, alternative),
    })
}

/// Test whether the kurtosis of a sample differs from a normal distribution.
///
/// Tests H0: the sample was drawn from a population with normal kurtosis.
/// Uses the Anscombe-Glynn transformation (1983) to convert excess kurtosis
/// to a z-score that is approximately standard normal.
///
/// Requires n >= 20 for valid asymptotic approximation.
///
/// Matches `scipy.stats.kurtosistest(data, nan_policy=..., alternative=...)`.
pub fn kurtosistest(
    data: &[f64],
    nan_policy: Option<&str>,
    alternative: Option<&str>,
) -> Result<GoodnessOfFitResult, StatsError> {
    let nan_policy = validate_nan_policy(nan_policy)?;
    let alternative = validate_hypothesis_alternative(alternative)?;

    let filtered;
    let working = match nan_policy {
        "propagate" => {
            if data.iter().any(|value| value.is_nan()) {
                return Ok(GoodnessOfFitResult {
                    statistic: f64::NAN,
                    pvalue: f64::NAN,
                });
            }
            data
        }
        "raise" => {
            if data.iter().any(|value| value.is_nan()) {
                return Err(StatsError::InvalidArgument(
                    "The input contains nan values".to_string(),
                ));
            }
            data
        }
        "omit" => {
            filtered = data
                .iter()
                .copied()
                .filter(|value| !value.is_nan())
                .collect::<Vec<_>>();
            filtered.as_slice()
        }
        other => {
            return Err(StatsError::InvalidArgument(format!(
                "nan_policy must be one of {{'propagate', 'raise', 'omit'}}, got {other}"
            )));
        }
    };

    if working.len() < 20 {
        return Ok(GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        });
    }

    let n = working.len() as f64;
    let mean_val = working.iter().sum::<f64>() / n;
    let mut m2 = 0.0;
    let mut m4 = 0.0;
    for &x in working {
        let d = x - mean_val;
        let d2 = d * d;
        m2 += d2;
        m4 += d2 * d2;
    }
    let m2_n = m2 / n;
    let m4_n = m4 / n;
    let g2 = m4_n / (m2_n * m2_n) - 3.0;

    let z = dagostino_kurttest_z(g2, n);
    Ok(GoodnessOfFitResult {
        statistic: z,
        pvalue: normal_alternative_pvalue(z, alternative),
    })
}

/// D'Agostino-Pearson omnibus test for normality.
///
/// Tests H0: data was drawn from a normal distribution by combining
/// the skewness test and kurtosis test into an omnibus chi-squared test.
///
/// Matches `scipy.stats.normaltest(data)`.
pub fn normaltest(data: &[f64]) -> GoodnessOfFitResult {
    let n = data.len();
    if n < 8 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let nf = n as f64;
    let mean_val = data.iter().sum::<f64>() / nf;

    // Compute central moments
    let mut m2 = 0.0;
    let mut m3 = 0.0;
    let mut m4 = 0.0;
    for &x in data {
        let d = x - mean_val;
        let d2 = d * d;
        m2 += d2;
        m3 += d2 * d;
        m4 += d2 * d2;
    }
    let m2_n = m2 / nf;
    let m3_n = m3 / nf;
    let m4_n = m4 / nf;

    // Skewness test (D'Agostino 1990)
    let g1 = m3_n / m2_n.powf(1.5); // sample skewness
    let z_skew = dagostino_skewtest_z(g1, nf);

    // Kurtosis test (Anscombe & Glynn 1983)
    let g2 = m4_n / (m2_n * m2_n) - 3.0; // excess kurtosis
    let z_kurt = dagostino_kurttest_z(g2, nf);

    // Omnibus: K² = z_skew² + z_kurt² ~ chi²(2)
    let k2 = z_skew * z_skew + z_kurt * z_kurt;

    // p-value from chi-squared(2) survival function
    // For chi²(2): P(X > x) = exp(-x/2)
    let pvalue = (-k2 / 2.0).exp();

    GoodnessOfFitResult {
        statistic: k2,
        pvalue,
    }
}

/// Jarque-Bera test for normality.
///
/// Tests H0: data was drawn from a normal distribution using the sample
/// skewness and excess kurtosis.
///
/// Matches `scipy.stats.jarque_bera(data)`.
pub fn jarque_bera(data: &[f64]) -> GoodnessOfFitResult {
    let n = data.len();
    if n < 2 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let nf = n as f64;
    let mean_val = data.iter().sum::<f64>() / nf;
    let mut m2 = 0.0;
    let mut m3 = 0.0;
    let mut m4 = 0.0;
    for &x in data {
        let d = x - mean_val;
        let d2 = d * d;
        m2 += d2;
        m3 += d2 * d;
        m4 += d2 * d2;
    }

    if m2 == 0.0 {
        return GoodnessOfFitResult {
            statistic: f64::NAN,
            pvalue: f64::NAN,
        };
    }

    let skewness = skew_from_moments(nf, m2, m3);
    let excess_kurtosis = kurtosis_from_moments(nf, m2, m4);
    let statistic = nf / 6.0 * (skewness * skewness + 0.25 * excess_kurtosis * excess_kurtosis);
    let pvalue = ChiSquared::new(2.0).sf(statistic).clamp(0.0, 1.0);

    GoodnessOfFitResult { statistic, pvalue }
}

/// Anderson-Darling test for a specified distribution.
///
/// Tests H0: data comes from the given distribution family.
/// Currently supports `"norm"` (normal distribution).
///
/// Returns the test statistic and critical values at significance levels
/// [15%, 10%, 5%, 2.5%, 1%].
///
/// Matches `scipy.stats.anderson(data, dist='norm')`.
pub fn anderson(data: &[f64], dist: &str) -> AndersonResult {
    let n = data.len();
    if n < 3 || dist != "norm" {
        return AndersonResult {
            statistic: f64::NAN,
            critical_values: [f64::NAN; 5],
            significance_level: [15.0, 10.0, 5.0, 2.5, 1.0],
        };
    }

    let nf = n as f64;

    // Fit normal parameters from data
    let mean_val = data.iter().sum::<f64>() / nf;
    let var_val: f64 = data.iter().map(|&x| (x - mean_val).powi(2)).sum::<f64>() / (nf - 1.0);
    let std_val = var_val.sqrt();

    if std_val == 0.0 {
        return AndersonResult {
            statistic: f64::INFINITY,
            critical_values: anderson_critical_values_norm(nf),
            significance_level: [15.0, 10.0, 5.0, 2.5, 1.0],
        };
    }

    // Sort and standardize
    let mut sorted = data.to_vec();
    sorted.sort_unstable_by(|a, b| a.total_cmp(b));

    let norm = Normal::standard();

    // A² = -n - (1/n) * sum_{i=1}^{n} (2i-1) * [ln(F(Y_i)) + ln(1 - F(Y_{n+1-i}))]
    //
    // The serial form evaluates the (erf-based) normal CDF twice per i — once at
    // Y_i and once at Y_{n+1-i} — so over the whole loop it computes the CDF at
    // every sorted point TWICE. Evaluate each point's clamped CDF logs once
    // (ln F and ln(1-F)) into a per-point table, in parallel for large n, then do
    // the weighted sum serially in i order, reading the forward log of i and the
    // upper-tail log of n-1-i. The per-point values and the left-to-right
    // summation order are unchanged => the statistic is bit-identical (the
    // duplicate CDF evaluations are the only work removed).
    let table = anderson_norm_cdf_log_table(&sorted, mean_val, std_val, &norm);
    let mut s = 0.0;
    for i in 0..n {
        let (ln_f, _) = table[i];
        let (_, ln_1m_rev) = table[n - 1 - i];
        s += (2.0 * (i + 1) as f64 - 1.0) * (ln_f + ln_1m_rev);
    }
    let a2 = -nf - s / nf;

    AndersonResult {
        statistic: a2,
        critical_values: anderson_critical_values_norm(nf),
        significance_level: [15.0, 10.0, 5.0, 2.5, 1.0],
    }
}

/// Per-point clamped-CDF log table for the Anderson-Darling A² sum against the
/// standard normal. Entry `k` is `(ln F(Y_k), ln(1 - F(Y_k)))` where `F` is the
/// erf-based standard-normal CDF clamped to `[1e-15, 1-1e-15]`. The serial A²
/// loop reads `F(Y_i)` and `F(Y_{n+1-i})` per `i`, so over the whole loop it
/// evaluates the CDF at every sorted point TWICE; computing the table once
/// halves the (expensive transcendental) CDF/`ln` work. Each entry is an
/// independent compute written to its own slot in input order, so the table is
/// bit-identical to the serial per-point evaluation — the caller then sums in
/// the exact original `i` order.
fn anderson_norm_cdf_log_table(
    sorted: &[f64],
    mean_val: f64,
    std_val: f64,
    norm: &Normal,
) -> Vec<(f64, f64)> {
    let n = sorted.len();
    let entry = |&y: &f64| -> (f64, f64) {
        let z = (y - mean_val) / std_val;
        let f = ContinuousDistribution::cdf(norm, z).clamp(1e-15, 1.0 - 1e-15);
        (f.ln(), (1.0 - f).ln())
    };
    let nthreads = if n < 2048 {
        1
    } else {
        std::thread::available_parallelism()
            .map(std::num::NonZero::get)
            .unwrap_or(1)
            .min(n)
            .max(1)
    };
    if nthreads <= 1 {
        return sorted.iter().map(entry).collect();
    }
    let chunk = n.div_ceil(nthreads);
    let mut table = vec![(0.0f64, 0.0f64); n];
    std::thread::scope(|scope| {
        for (block, yblock) in table.chunks_mut(chunk).zip(sorted.chunks(chunk)) {
            scope.spawn(move || {
                for (slot, y) in block.iter_mut().zip(yblock.iter()) {
                    *slot = entry(y);
                }
            });
        }
    });
    table
}

/// Critical values for Anderson-Darling test with normal distribution at
/// significance levels [15%, 10%, 5%, 2.5%, 1%]. Matches scipy 1.17.1's
/// formula in `scipy/stats/_morestats.py::anderson` for `dist='norm'`:
///   `around(_Avals_norm / (1.0 + 0.75/N + 2.25/N**2), 3)`
/// scipy 1.17 updated `_Avals_norm` from the historical Stephens 1974 table
/// `[0.576, 0.656, 0.787, 0.918, 1.092]` to the refined values below
/// `[0.561, 0.631, 0.752, 0.873, 1.035]`.
fn anderson_critical_values_norm(n: f64) -> [f64; 5] {
    let avals = [0.561, 0.631, 0.752, 0.873, 1.035];
    let scale = 1.0 + 0.75 / n + 2.25 / (n * n);
    let round3 = |v: f64| (v * 1000.0).round() / 1000.0;
    [
        round3(avals[0] / scale),
        round3(avals[1] / scale),
        round3(avals[2] / scale),
        round3(avals[3] / scale),
        round3(avals[4] / scale),
    ]
}

/// Kolmogorov distribution p-value: P(D_n >= d).
/// Uses the Kolmogorov-Smirnov limiting distribution approximation.
fn kolmogorov_pvalue(d: f64, n: f64) -> f64 {
    if d <= 0.0 {
        return 1.0;
    }
    if d >= 1.0 {
        return 0.0;
    }

    // Effective value: sqrt(n) * d
    let s = n.sqrt() * d;

    // For large s, use asymptotic series (Kolmogorov's formula):
    // P(sqrt(n)*D_n > s) ≈ 2 * sum_{k=1}^{inf} (-1)^{k+1} * exp(-2*k²*s²)
    let mut pval = 0.0;
    for k in 1..=100 {
        let kf = k as f64;
        let term = (-2.0 * kf * kf * s * s).exp();
        if term < 1e-20 {
            break;
        }
        if k % 2 == 1 {
            pval += term;
        } else {
            pval -= term;
        }
    }
    (2.0 * pval).clamp(0.0, 1.0)
}

/// D'Agostino's skewness test z-score.
fn dagostino_skewtest_z(g1: f64, n: f64) -> f64 {
    if !g1.is_finite() || n < 8.0 {
        return f64::NAN;
    }

    // D'Agostino (1990) transformation of sample skewness to z-score
    let y = g1 * ((n + 1.0) * (n + 3.0) / (6.0 * (n - 2.0))).sqrt();
    let beta2 = 3.0 * (n * n + 27.0 * n - 70.0) * (n + 1.0) * (n + 3.0)
        / ((n - 2.0) * (n + 5.0) * (n + 7.0) * (n + 9.0));
    let w2 = -1.0 + (2.0 * (beta2 - 1.0)).sqrt();
    if !(w2.is_finite() && w2 > 1.0) {
        return f64::NAN;
    }

    let delta = 1.0 / (0.5 * w2.ln()).sqrt();
    let alpha = (2.0 / (w2 - 1.0)).sqrt();
    let y = if y == 0.0 { 1.0 } else { y };
    let transformed = y / alpha + ((y / alpha).powi(2) + 1.0).sqrt();
    if transformed <= 0.0 || !transformed.is_finite() {
        return f64::NAN;
    }
    delta * transformed.ln()
}

/// Anscombe & Glynn kurtosis test z-score.
fn dagostino_kurttest_z(g2: f64, n: f64) -> f64 {
    // Expected value and variance of excess kurtosis under normality
    let e_g2 = -6.0 / (n + 1.0);
    let var_g2 = 24.0 * n * (n - 2.0) * (n - 3.0) / ((n + 1.0) * (n + 1.0) * (n + 3.0) * (n + 5.0));
    let std_g2 = var_g2.sqrt();

    if std_g2 == 0.0 {
        return 0.0;
    }

    // Standardize
    let x = (g2 - e_g2) / std_g2;

    // Apply cube-root transformation (Anscombe & Glynn)
    let beta1 = 6.0 * (n * n - 5.0 * n + 2.0) / ((n + 7.0) * (n + 9.0))
        * (6.0 * (n + 3.0) * (n + 5.0) / (n * (n - 2.0) * (n - 3.0))).sqrt();

    let a = 6.0 + 8.0 / beta1 * (2.0 / beta1 + (1.0 + 4.0 / (beta1 * beta1)).sqrt());
    let z_term = ((1.0 - 2.0 / a) / (1.0 + x * (2.0 / (a - 4.0)).sqrt())).abs();
    if z_term <= 0.0 {
        return 0.0;
    }
    (1.0 - 2.0 / (9.0 * a) - z_term.powf(1.0 / 3.0)) / (2.0 / (9.0 * a)).sqrt()
}

