    /// Anchor values from scipy.stats.nct (frankenscipy-evcuc).
    ///
    /// Pre-fix the cdf was off by up to 0.78 for moderate |nc|, with the
    /// noisy cdf making ppf walk to the bracket edge (returning ~30-50
    /// when scipy reports values near 1-2). The chi-scaled Simpson
    /// quadrature now matches scipy to better than 1e-10 absolute.
    #[test]
    fn noncentralt_matches_scipy_anchor_values() {
        // (df, nc, x, expected_cdf, expected_pdf) from scipy.stats.nct.
        let cases = [
            (5.0, 0.5, 0.5, 0.49036270180675584, 0.37504023489231403),
            (5.0, 0.5, 1.5, 0.7997685641492409, 0.21549131606796273),
            (10.0, 1.0, 1.0257209228280022, 0.5, 0.3790279287538437),
            (15.0, -2.5, 1.5, 0.9999395205428545, 0.00019519322914816),
            (15.0, -2.5, 3.0, 0.9999994362738605, 1.6570469892035188e-06),
            (20.0, 2.0, 2.025952753998231, 0.5, 0.37501048228416767),
        ];
        for (df, nc, x, e_cdf, e_pdf) in cases {
            let dist = NoncentralT::new(df, nc);
            let cdf = dist.cdf(x);
            let pdf = dist.pdf(x);
            assert!(
                (cdf - e_cdf).abs() < 1e-9,
                "nct({df}, {nc}).cdf({x}) = {cdf}, expected {e_cdf}, diff = {}",
                (cdf - e_cdf).abs()
            );
            assert!(
                (pdf - e_pdf).abs() < 1e-9,
                "nct({df}, {nc}).pdf({x}) = {pdf}, expected {e_pdf}, diff = {}",
                (pdf - e_pdf).abs()
            );
        }
    }

    #[test]
    fn noncentralt_ppf_matches_scipy_anchor_values() {
        // ppf bisection over the new accurate cdf must converge to the
        // scipy quantile with ~1e-9 relative precision (frankenscipy-evcuc).
        let cases: [(f64, f64, f64, f64); 4] = [
            (10.0, 1.0, 0.5, 1.0257209228280022),
            (20.0, 2.0, 0.5, 2.025952753998231),
            (5.0, 0.5, 0.25, -0.18452418567692463),
            (5.0, 0.5, 0.75, 1.2898472692139387),
        ];
        for (df, nc, q, expected) in cases {
            let dist = NoncentralT::new(df, nc);
            let got = dist.ppf(q);
            let scale = expected.abs().max(1.0);
            assert!(
                (got - expected).abs() < 1e-7 * scale,
                "nct({df}, {nc}).ppf({q}) = {got}, expected {expected}, diff = {}",
                (got - expected).abs()
            );
        }
    }

    #[test]
    fn noncentralt_cdf_at_zero_equals_phi_minus_nc() {
        // F_nct(0; ν, μ) = Φ(-μ).
        let nct = NoncentralT::new(7.0, 1.5);
        let phi = Normal::standard().cdf(-1.5);
        assert!((nct.cdf(0.0) - phi).abs() < 1e-12);
    }

    #[test]
    fn noncentralt_sf_consistent_with_cdf_midrange() {
        // Where cdf is not near 1, the direct sf integral must agree with
        // 1 - cdf to quadrature precision (frankenscipy-8y248).
        let cases = [
            (5.0, 0.5, 0.5),
            (5.0, 0.5, 1.5),
            (10.0, 1.0, 1.0),
            (15.0, -2.5, 1.5),
            (20.0, 2.0, 2.0),
        ];
        for (df, nc, x) in cases {
            let d = NoncentralT::new(df, nc);
            assert!(
                (d.sf(x) - (1.0 - d.cdf(x))).abs() < 1e-9,
                "nct({df},{nc}).sf({x})={} vs 1-cdf={}",
                d.sf(x),
                1.0 - d.cdf(x)
            );
        }
    }

    #[test]
    fn noncentralt_sf_tail_does_not_collapse() {
        // The default 1-cdf returned exactly 0 here; the direct erfc-based
        // integral must keep a positive, finite tail value (frankenscipy-8y248).
        // nc=0 routes to the closed-form central-t sf; scipy nct(10,0).sf(150)
        // = 2.13e-18.
        let central = NoncentralT::new(10.0, 0.0);
        let s = central.sf(150.0);
        assert!(s > 0.0 && s < 1e-15, "central tail sf collapsed: {s}");
        assert!(
            (s - StudentT::new(10.0).sf(150.0)).abs() < 1e-30,
            "nc=0 sf must match central StudentT sf"
        );
        // Noncentral tail stays positive and below the 1-cdf machine floor.
        let nc = NoncentralT::new(10.0, 2.0);
        let s2 = nc.sf(150.0);
        assert!(s2 > 0.0 && s2 < 1e-12, "noncentral tail sf collapsed: {s2}");
        // Monotone decreasing into the tail.
        assert!(nc.sf(20.0) > nc.sf(50.0) && nc.sf(50.0) > s2);
    }

    #[test]
    fn sf_overrides_consistent_with_one_minus_cdf() {
        // Each new sf() must equal 1 − cdf() wherever cdf is not pinned at 1,
        // i.e. it is an exact algebraic rearrangement (frankenscipy-w3f6m).
        macro_rules! chk {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let s = d.sf(x);
                    let oc = 1.0 - d.cdf(x);
                    assert!(
                        (s - oc).abs() <= 1e-12 * oc.abs().max(1e-12) + 1e-15,
                        "{}: sf({x})={s} vs 1-cdf={oc}",
                        stringify!($d)
                    );
                }
            }};
        }
        chk!(GenPareto::new(0.25), &[0.5, 1.0, 2.5]);
        chk!(GenPareto::new(0.0), &[0.5, 2.0, 5.0]);
        chk!(HalfLogistic, &[0.5, 1.0, 3.0]);
        chk!(GenHalfLogistic::new(0.5), &[0.2, 0.8, 1.5]);
        chk!(Fisk::new(3.0), &[0.5, 1.0, 2.0]);
        chk!(Loglogistic::new(3.0), &[0.5, 1.0, 2.0]);
        chk!(InvWeibull::new(2.0), &[0.5, 1.0, 3.0]);
        chk!(Moyal, &[-1.0, 0.5, 2.0]);
        chk!(ExponWeibull::new(1.5, 2.0), &[0.5, 1.0, 2.0]);
        chk!(FatigueLife::new(0.5), &[0.5, 1.0, 2.0]);
        chk!(InverseGamma::new(2.0), &[0.5, 1.0, 3.0]);
    }

    #[test]
    fn sf_overrides_tail_does_not_collapse() {
        // Deep in the right tail the default 1 − cdf returns exactly 0; the
        // closed-form sf must stay positive and decreasing (frankenscipy-w3f6m).
        macro_rules! tail {
            ($d:expr, $x:expr, $upper:expr) => {{
                let d = $d;
                let s = d.sf($x);
                // sf stays positive (no collapse) and at the right magnitude.
                assert!(
                    s > 0.0 && s < $upper,
                    "{}: tail sf({})={s} (collapsed or too large)",
                    stringify!($d),
                    $x
                );
            }};
        }
        tail!(GenPareto::new(0.0), 45.0, 1e-18); // e^-45 ≈ 2.9e-20
        tail!(HalfLogistic, 42.0, 1e-17); // 2e^-42 ≈ 1.1e-18
        tail!(InvWeibull::new(1.0), 1e9, 1e-8); // ≈ 1e-9
        tail!(Moyal, 90.0, 1e-15); // erf(√(e^-90/2)) ≈ 2.3e-20; cdf rounds to 1
        tail!(FatigueLife::new(0.5), 50.0, 1e-30); // ½erfc(13.9/√2) ≈ 5e-44
        tail!(InverseGamma::new(2.0), 1e8, 1e-14); // P(2,1e-8) ≈ 5e-17
        tail!(ExponWeibull::new(1.0, 1.0), 45.0, 1e-18); // ≈ e^-45
    }

