    #[test]
    fn sf_overrides_batch6_consistent_and_tail() {
        // Gilbrat (Gibrat alias) and InverseGaussian: sf == 1 − cdf mid-range,
        // and a positive tail value where 1 − cdf collapses (frankenscipy-w3f6m).
        for &x in &[0.3, 1.0, 3.0] {
            let g = Gilbrat;
            assert!((g.sf(x) - (1.0 - g.cdf(x))).abs() <= 1e-12);
        }
        for &x in &[0.5, 1.0, 2.5] {
            let d = InverseGaussian::new(1.0);
            let oc = 1.0 - d.cdf(x);
            assert!(
                (d.sf(x) - oc).abs() <= 1e-11 * oc.abs().max(1e-11) + 1e-13,
                "invgauss sf({x})={} vs 1-cdf={oc}",
                d.sf(x)
            );
        }
        // Tail: default 1 − cdf returns 0; closed forms stay positive.
        let gt = Gilbrat.sf(1e8); // Φ(−ln 1e8)=Φ(−18.4)
        assert!(gt > 0.0 && gt < 1e-30, "gilbrat tail {gt}");
        let it = InverseGaussian::new(1.0).sf(80.0); // ≈ 3e-20
        assert!(it > 0.0 && it < 1e-17, "invgauss tail {it}");
    }

    #[test]
    fn logsf_overrides_consistent_and_finite_in_extreme_tail() {
        // logsf == ln(sf) where sf is representable; and stays finite & negative
        // deep in the tail where sf underflows to 0 (frankenscipy-czegj).
        macro_rules! mid {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let ls = d.logsf(x);
                    let ref_ = d.sf(x).ln();
                    assert!(
                        (ls - ref_).abs() <= 1e-9 * ref_.abs().max(1.0),
                        "{}: logsf({x})={ls} vs ln(sf)={ref_}",
                        stringify!($d)
                    );
                }
            }};
        }
        mid!(GenPareto::new(0.25), &[0.5, 2.0, 8.0]);
        mid!(HalfLogistic, &[0.5, 2.0, 8.0]);
        mid!(Fisk::new(3.0), &[0.5, 2.0, 8.0]);
        mid!(Loglogistic::new(3.0), &[0.5, 2.0, 8.0]);
        mid!(Burr12::new(2.0, 1.5), &[0.5, 2.0, 8.0]);
        mid!(Lognormal::new(1.0, 1.0), &[0.5, 2.0, 8.0]);
        mid!(Gibrat, &[0.5, 2.0, 8.0]);
        mid!(Gilbrat, &[0.5, 2.0, 8.0]);
        mid!(JohnsonSU::new(0.5, 1.5), &[-1.0, 0.5, 4.0]);
        mid!(FatigueLife::new(0.5), &[0.5, 2.0, 8.0]);

        // Extreme tail: ln(sf) would be -inf (sf underflowed); logsf must be finite.
        macro_rules! ext {
            ($d:expr, $x:expr) => {{
                let d = $d;
                assert_eq!(d.sf($x), 0.0, "precondition: sf underflowed at {}", $x);
                let ls = d.logsf($x);
                assert!(
                    ls.is_finite() && ls < -300.0,
                    "{}: logsf({})={ls} not finite/large-negative",
                    stringify!($d),
                    $x
                );
            }};
        }
        ext!(GenPareto::new(0.0), 1000.0); // -x = -1000
        ext!(HalfLogistic, 1000.0); // ≈ -1000
        ext!(Gibrat, 1e120); // logΦ(-ln 1e120)
        ext!(Lognormal::new(1.0, 1.0), 1e150);
        ext!(JohnsonSU::new(0.5, 1.5), 1e260);
    }

    #[test]
    fn gamma_tail_logsf_consistent_and_finite() {
        // logsf == ln(sf) where sf is representable, and finite/large-negative
        // deep in the tail where sf underflows to 0 (frankenscipy-pkaua).
        macro_rules! mid {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let ls = d.logsf(x);
                    let r = d.sf(x).ln();
                    assert!(
                        (ls - r).abs() <= 1e-9 * r.abs().max(1.0),
                        "{}: logsf({x})={ls} vs ln(sf)={r}",
                        stringify!($d)
                    );
                }
            }};
        }
        mid!(Chi::new(4.0), &[1.0, 3.0, 6.0]);
        mid!(Nakagami::new(2.0), &[0.5, 1.5, 3.0]);
        mid!(Erlang::new(3, 1.0), &[2.0, 6.0, 15.0]);
        mid!(Maxwell::new(1.0), &[1.0, 3.0, 6.0]);
        mid!(HalfGenNorm::new(1.5), &[0.5, 2.0, 5.0]);
        mid!(LogGamma::new(2.0), &[-1.0, 0.5, 3.0]);
        mid!(DoubleGamma::new(1.5), &[-2.0, 0.5, 3.0]);
        mid!(GenNorm::new(1.5), &[-1.0, 0.5, 3.0]);

        // Ultra-extreme tail: ln(sf) would be -inf (sf underflowed); logsf finite.
        macro_rules! ext {
            ($d:expr, $x:expr) => {{
                let d = $d;
                assert_eq!(d.sf($x), 0.0, "precondition: sf underflowed at {}", $x);
                let ls = d.logsf($x);
                assert!(
                    ls.is_finite() && ls < -700.0,
                    "{}: logsf({})={ls} not finite/large-negative",
                    stringify!($d),
                    $x
                );
            }};
        }
        ext!(Chi::new(4.0), 45.0); // Q(2, ~1012)
        ext!(Maxwell::new(1.0), 45.0); // Q(1.5, ~1012)
        ext!(LogGamma::new(2.0), 7.0); // Q(2, e^7≈1097)
        ext!(HalfGenNorm::new(1.0), 800.0); // Q(1, 800)
    }

    #[test]
    fn gamma_family_logcdf_logsf_consistent_and_finite() {
        // logcdf == ln(cdf) and logsf == ln(sf) where representable; finite where
        // the lower-gamma P underflows to 0 (frankenscipy-s14mf).
        macro_rules! mid_cdf {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let lc = d.logcdf(x);
                    let r = d.cdf(x).ln();
                    assert!(
                        (lc - r).abs() <= 1e-9 * r.abs().max(1.0),
                        "{}: logcdf({x})={lc} vs ln(cdf)={r}",
                        stringify!($d)
                    );
                }
            }};
        }
        mid_cdf!(GammaDist::new(2.0, 1.0), &[0.5, 2.0, 6.0]);
        mid_cdf!(ChiSquared::new(4.0), &[1.0, 4.0, 12.0]);
        mid_cdf!(Chi::new(4.0), &[0.5, 2.0, 5.0]);
        mid_cdf!(Nakagami::new(2.0), &[0.3, 1.0, 2.5]);
        mid_cdf!(Erlang::new(3, 1.0), &[1.0, 4.0, 10.0]);
        // InverseGamma logsf == ln(sf).
        let ig = InverseGamma::new(2.0);
        for &x in &[0.5, 1.0, 3.0] {
            assert!((ig.logsf(x) - ig.sf(x).ln()).abs() <= 1e-9);
        }

        // Underflowed left tail: cdf == 0 but logcdf finite.
        macro_rules! ext_cdf {
            ($d:expr, $x:expr) => {{
                let d = $d;
                assert_eq!(d.cdf($x), 0.0, "precondition: cdf underflowed at {}", $x);
                let lc = d.logcdf($x);
                assert!(
                    lc.is_finite() && lc < -300.0,
                    "{}: logcdf={lc}",
                    stringify!($d)
                );
            }};
        }
        ext_cdf!(GammaDist::new(50.0, 1.0), 1e-15); // P(50, 1e-15) → 0
        ext_cdf!(ChiSquared::new(40.0), 1e-30); // P(20, 5e-31) → 0
        // InverseGamma right tail: sf == 0 but logsf finite.
        let ig2 = InverseGamma::new(50.0);
        assert_eq!(ig2.sf(1e15), 0.0);
        assert!(ig2.logsf(1e15).is_finite() && ig2.logsf(1e15) < -300.0);
    }

    #[test]
    fn beta_family_logcdf_logsf_consistent_and_finite() {
        // logcdf/logsf == ln(cdf)/ln(sf) where representable, finite where the
        // incomplete beta underflows (frankenscipy-r4933).
        macro_rules! cc {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let lc = d.logcdf(x);
                    let rc = d.cdf(x).ln();
                    assert!(
                        (lc - rc).abs() <= 1e-9 * rc.abs().max(1.0),
                        "{}: logcdf({x})={lc} vs {rc}",
                        stringify!($d)
                    );
                    let ls = d.logsf(x);
                    let rs = d.sf(x).ln();
                    assert!(
                        (ls - rs).abs() <= 1e-9 * rs.abs().max(1.0),
                        "{}: logsf({x})={ls} vs {rs}",
                        stringify!($d)
                    );
                }
            }};
        }
        cc!(BetaDist::new(2.0, 8.0), &[0.1, 0.4, 0.8]);
        cc!(StudentT::new(5.0), &[-3.0, -0.5, 0.5, 3.0]);
        cc!(FDistribution::new(5.0, 10.0), &[0.2, 1.0, 4.0]);
        cc!(BetaPrime::new(2.0, 3.0), &[0.3, 1.0, 4.0]);

        // Underflowed tails: ln(cdf/sf) would be -inf; the log forms stay finite.
        let bt = BetaDist::new(2.0, 8.0);
        assert_eq!(bt.cdf(1e-200), 0.0);
        assert!(bt.logcdf(1e-200).is_finite() && bt.logcdf(1e-200) < -300.0);
        // StudentT right-tail log p-value (sf underflows for huge t).
        let st = StudentT::new(4.0);
        assert_eq!(st.sf(1e90), 0.0);
        assert!(st.logsf(1e90).is_finite() && st.logsf(1e90) < -300.0);
        // F right-tail (ANOVA) log p-value.
        let fd = FDistribution::new(5.0, 10.0);
        assert_eq!(fd.sf(1e80), 0.0);
        assert!(fd.logsf(1e80).is_finite() && fd.logsf(1e80) < -300.0);
    }

    #[test]
    fn discrete_closed_form_sf_logcdf_logsf_consistent_and_finite() {
        // Closed-form sf/logcdf/logsf for Poisson (gamma) and Binomial/NegBinomial
        // (beta) must agree with the pmf-sum cdf in the bulk and stay finite in
        // the underflowed tail (frankenscipy-r4933).
        macro_rules! cc {
            ($d:expr, $ks:expr) => {{
                let d = $d;
                for &k in $ks {
                    // sf == 1 - cdf (cdf is the scipy-validated pmf-sum).
                    assert!(
                        (d.sf(k) - (1.0 - d.cdf(k))).abs() <= 1e-9,
                        "{}: sf({k})={} vs 1-cdf={}",
                        stringify!($d),
                        d.sf(k),
                        1.0 - d.cdf(k)
                    );
                    // logcdf == ln(cdf), logsf == ln(sf) where representable.
                    let c = d.cdf(k);
                    if c > 0.0 {
                        assert!(
                            (d.logcdf(k) - c.ln()).abs() <= 1e-8 * c.ln().abs().max(1.0),
                            "{}: logcdf({k})={} vs ln(cdf)={}",
                            stringify!($d),
                            d.logcdf(k),
                            c.ln()
                        );
                    }
                    let s = d.sf(k);
                    if s > 0.0 {
                        assert!(
                            (d.logsf(k) - s.ln()).abs() <= 1e-8 * s.ln().abs().max(1.0),
                            "{}: logsf({k})={} vs ln(sf)={}",
                            stringify!($d),
                            d.logsf(k),
                            s.ln()
                        );
                    }
                }
            }};
        }
        cc!(Poisson::new(10.0), &[2, 8, 10, 15, 25]);
        cc!(Binomial::new(20, 0.3), &[1, 5, 10, 15]);
        cc!(NegBinomial::new(5.0, 0.5), &[1, 5, 10, 20]);

        // Closed-form cdf must match an independent pmf-sum reference in the bulk
        // (the O(k)→O(1) swap is faithful). frankenscipy-7kq9d
        let pmf_sum_cdf =
            |pmf: &dyn Fn(u64) -> f64, k: u64| -> f64 { (0..=k).map(pmf).sum::<f64>().min(1.0) };
        {
            let d = Poisson::new(10.0);
            for k in [0u64, 3, 8, 12, 20] {
                let r = pmf_sum_cdf(&|i| d.pmf(i), k);
                assert!(
                    (d.cdf(k) - r).abs() <= 1e-9,
                    "poisson cdf({k})={} vs {r}",
                    d.cdf(k)
                );
            }
        }
        {
            let d = Binomial::new(20, 0.3);
            for k in [0u64, 3, 6, 10, 19, 20] {
                let r = pmf_sum_cdf(&|i| d.pmf(i), k);
                assert!(
                    (d.cdf(k) - r).abs() <= 1e-9,
                    "binom cdf({k})={} vs {r}",
                    d.cdf(k)
                );
            }
        }
        {
            let d = NegBinomial::new(5.0, 0.5);
            for k in [0u64, 3, 8, 15, 30] {
                let r = pmf_sum_cdf(&|i| d.pmf(i), k);
                assert!(
                    (d.cdf(k) - r).abs() <= 1e-9,
                    "nbinom cdf({k})={} vs {r}",
                    d.cdf(k)
                );
            }
        }

        // Deep right tail: the closed-form sf stays accurate (≈3e-181) where the
        // default 1-cdf has lost all precision (cdf rounds to ~1), and logsf is
        // finite and large-negative.
        let p = Poisson::new(10.0);
        let s = p.sf(200);
        assert!(
            s > 0.0 && s < 1e-100,
            "closed sf accurate in deep tail: {s}"
        );
        assert!(p.logsf(200).is_finite() && p.logsf(200) < -300.0);
        assert!(1.0 - p.cdf(200) < 1e-15, "default 1-cdf collapsed");
    }

    #[test]
    fn logcdf_overrides_consistent_and_finite() {
        // logcdf == ln(cdf) where representable; finite in the left tail where
        // cdf underflows to 0 (frankenscipy-osnge).
        macro_rules! mid {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let lc = d.logcdf(x);
                    let r = d.cdf(x).ln();
                    assert!(
                        (lc - r).abs() <= 1e-9 * r.abs().max(1.0),
                        "{}: logcdf({x})={lc} vs ln(cdf)={r}",
                        stringify!($d)
                    );
                }
            }};
        }
        mid!(Gibrat, &[0.5, 1.0, 3.0]);
        mid!(Gilbrat, &[0.5, 1.0, 3.0]);
        mid!(Lognormal::new(1.0, 1.0), &[0.3, 1.0, 4.0]);
        mid!(JohnsonSU::new(0.5, 1.5), &[-2.0, 0.5, 3.0]);
        mid!(FatigueLife::new(0.5), &[0.5, 1.0, 3.0]);
        mid!(Pearson3::new(0.8), &[-1.0, 0.5, 2.0]);
        mid!(Pearson3::new(-0.8), &[-2.0, -0.5, 1.0]);
        // Pearson3 logsf too.
        for &x in &[-1.0, 0.5, 2.0] {
            let d = Pearson3::new(0.8);
            assert!((d.logsf(x) - d.sf(x).ln()).abs() <= 1e-9 * d.sf(x).ln().abs().max(1.0));
        }

        // Left-tail underflow: cdf == 0 but logcdf finite.
        let ln = Lognormal::new(1.0, 1.0);
        assert_eq!(ln.cdf(1e-150), 0.0);
        assert!(ln.logcdf(1e-150).is_finite() && ln.logcdf(1e-150) < -300.0);
        let gb = Gibrat;
        assert_eq!(gb.cdf(1e-120), 0.0);
        assert!(gb.logcdf(1e-120).is_finite() && gb.logcdf(1e-120) < -300.0);
    }

    #[test]
    fn logpdf_overrides_consistent_and_finite() {
        // logpdf == ln(pdf) where pdf is representable; finite in the tail where
        // pdf underflows to 0 (frankenscipy-p82v7).
        macro_rules! mid {
            ($d:expr, $xs:expr) => {{
                let d = $d;
                for &x in $xs {
                    let lp = d.logpdf(x);
                    let r = d.pdf(x).ln();
                    assert!(
                        (lp - r).abs() <= 1e-9 * r.abs().max(1.0),
                        "{}: logpdf({x})={lp} vs ln(pdf)={r}",
                        stringify!($d)
                    );
                }
            }};
        }
        mid!(Exponential::new(1.5), &[0.0, 1.0, 5.0]);
        mid!(GammaDist::new(2.0, 1.5), &[0.5, 2.0, 8.0]);
        mid!(ChiSquared::new(4.0), &[1.0, 4.0, 12.0]);
        mid!(StudentT::new(5.0), &[-3.0, 0.0, 3.0]);
        mid!(Lognormal::new(1.0, 1.0), &[0.3, 1.0, 5.0]);
        mid!(Weibull::new(2.0, 1.0), &[0.3, 1.0, 3.0]);
        mid!(Rayleigh::new(1.0), &[0.5, 2.0, 4.0]);
        mid!(Laplace::new(0.0, 1.0), &[-3.0, 0.5, 3.0]);
        mid!(Logistic::new(0.0, 1.0), &[-5.0, 0.5, 5.0]);
        mid!(Gumbel::new(0.0, 1.0), &[-1.0, 0.5, 4.0]);

        // Deep tail: pdf underflows to 0; logpdf stays finite & large-negative.
        macro_rules! tail {
            ($d:expr, $x:expr) => {{
                let d = $d;
                assert_eq!(d.pdf($x), 0.0, "precondition: pdf underflowed at {}", $x);
                let lp = d.logpdf($x);
                assert!(
                    lp.is_finite() && lp < -300.0,
                    "{}: logpdf={lp}",
                    stringify!($d)
                );
            }};
        }
        tail!(Exponential::new(1.5), 1000.0); // −1.5·1000
        tail!(Lognormal::new(1.0, 1.0), 1e30); // z=ln(1e30)≈69 → −z²/2
        tail!(Laplace::new(0.0, 1.0), 800.0); // −|z|
        tail!(Logistic::new(0.0, 1.0), 800.0); // ≈ −z
        tail!(Gumbel::new(0.0, 1.0), 800.0); // ≈ −z
        tail!(ChiSquared::new(4.0), 2000.0); // −x/2
        tail!(StudentT::new(2.0), 1e110); // power-law: −1.5·ln(1+x²/2), x² stays finite
    }

