    #[test]
    fn gumbel_logcdf_logsf_finite_in_far_tail_match_scipy() {
        // Regression (frankenscipy-uvzzl): the default logcdf/logsf are
        // log_probability(cdf/sf), which collapse to -inf once the linear value
        // underflows. The Gumbel family has exact closed forms:
        //   gumbel_r.logcdf(x) = -e^{-(x-loc)/scale}
        //   gumbel_l.logsf(x)  = -e^{ (x-loc)/scale}
        // Reference values from scipy.stats 1.17.1.
        let cases_r: &[(f64, f64, f64, f64)] = &[
            (0.0, 1.0, -40.0, -2.353_852_668_370_2e17),
            (0.0, 1.0, -3.0, -20.085_536_923_187_668),
            (2.0, 3.0, -40.0, -1_202_604.284_164_776_8),
        ];
        for &(loc, scale, x, want) in cases_r {
            let got = Gumbel::new(loc, scale).logcdf(x);
            assert!(got.is_finite(), "gumbel_r.logcdf({x}) not finite");
            assert!(
                (got - want).abs() <= 1e-9 * want.abs().max(1.0),
                "gumbel_r({loc},{scale}).logcdf({x}) = {got}, want {want}"
            );
        }
        let cases_l: &[(f64, f64, f64, f64)] = &[
            (0.0, 1.0, 40.0, -2.353_852_668_370_2e17),
            (0.0, 1.0, 3.0, -20.085_536_923_187_668),
            (2.0, 3.0, 40.0, -317_003.047_591_547_2),
        ];
        for &(loc, scale, x, want) in cases_l {
            let got = GumbelLeft::new(loc, scale).logsf(x);
            assert!(got.is_finite(), "gumbel_l.logsf({x}) not finite");
            assert!(
                (got - want).abs() <= 1e-9 * want.abs().max(1.0),
                "gumbel_l({loc},{scale}).logsf({x}) = {got}, want {want}"
            );
        }
    }

    #[test]
    fn gennorm_left_tail_cdf_logcdf_match_scipy() {
        // Regression (frankenscipy-ew60b): cdf(x<0) used ½ − ½·P(1/β,|x|^β),
        // which cancels to 0 in the left tail (P → 1); e.g. cdf(-30) returned 0
        // vs scipy 2.92e-73 and cdf(-10) was ~1.2% off. The symmetric upper-gamma
        // form ½·Q(1/β,|x|^β) is exact, and logcdf now stays finite. Reference
        // values from scipy.stats.gennorm 1.17.1.
        let cases: &[(f64, f64, f64, f64)] = &[
            (
                1.5,
                -30.0,
                2.924_238_171_735_146_7e-73,
                -167.015_677_795_913_2,
            ),
            (
                1.5,
                -10.0,
                2.134_498_974_764_425_3e-15,
                -33.780_544_448_011_426,
            ),
            (
                2.5,
                -10.0,
                3.282_333_937_652_431_5e-140,
                -321.173_358_283_456_2,
            ),
            (
                1.0,
                -50.0,
                9.643_749_239_819_591e-23,
                -50.693_147_180_559_95,
            ),
        ];
        for &(beta, x, want_cdf, want_logcdf) in cases {
            let d = GenNorm::new(beta);
            let cdf = d.cdf(x);
            assert!(
                (cdf - want_cdf).abs() <= 1e-12 * want_cdf.abs().max(f64::MIN_POSITIVE),
                "GenNorm({beta}).cdf({x}) = {cdf:e}, want {want_cdf:e}"
            );
            let lc = d.logcdf(x);
            assert!(lc.is_finite(), "GenNorm({beta}).logcdf({x}) not finite");
            assert!(
                (lc - want_logcdf).abs() <= 1e-9 * want_logcdf.abs().max(1.0),
                "GenNorm({beta}).logcdf({x}) = {lc}, want {want_logcdf}"
            );
        }
    }

