    #[test]
    fn f_dist_pdf_cdf_match_scipy() {
        // Exact scipy.stats.f(5,10). The other f_dist tests cover positivity,
        // moments, sf-tail, and entropy, but no exact pdf/cdf value at a regular
        // interior point.
        let f = FDistribution::new(5.0, 10.0);
        assert!(
            (f.pdf(1.0) - 0.495_479_783_486_639_5).abs() < 1e-12,
            "pdf(1)"
        );
        assert!(
            (f.pdf(2.0) - 0.162_005_742_180_115_15).abs() < 1e-12,
            "pdf(2)"
        );
        assert!(
            (f.cdf(1.0) - 0.534_880_573_462_199_6).abs() < 1e-10,
            "cdf(1)"
        );
    }

    #[test]
    fn f_dist_pdf_positive_only() {
        let f = FDistribution::new(5.0, 10.0);
        assert_eq!(f.pdf(-1.0), 0.0);
        assert_eq!(f.pdf(0.0), 0.0);
        assert!(f.pdf(1.0) > 0.0);
    }

    #[test]
    fn f_dist_pdf_many_matches_pdf() {
        // Batch pdf_many/logpdf_many (ln_beta + lead term hoisted) must be
        // byte-identical to per-point pdf/logpdf, including x<=0.
        let f = FDistribution::new(5.0, 10.0);
        let xs = [-1.0, 0.0, 0.5, 1.0, 2.5, 9.0];
        let pm = f.pdf_many(&xs);
        let lpm = f.logpdf_many(&xs);
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(pm[i], f.pdf(x), "pdf_many != pdf at {x}");
            assert_eq!(lpm[i], f.logpdf(x), "logpdf_many != logpdf at {x}");
        }
    }

    #[test]
    fn f_dist_cdf_at_zero() {
        let f = FDistribution::new(5.0, 10.0);
        assert_eq!(f.cdf(0.0), 0.0);
    }

    #[test]
    fn f_dist_cdf_monotone() {
        let f = FDistribution::new(3.0, 7.0);
        let c1 = f.cdf(0.5);
        let c2 = f.cdf(1.0);
        let c3 = f.cdf(2.0);
        assert!(c1 < c2, "CDF should be monotone");
        assert!(c2 < c3, "CDF should be monotone");
        assert!(c3 < 1.0, "CDF < 1 for finite x");
    }

    #[test]
    fn f_dist_mean() {
        let f = FDistribution::new(5.0, 10.0);
        // mean = dfd/(dfd-2) = 10/8 = 1.25
        assert_close(f.mean(), 1.25, 1e-10, "F(5,10) mean");
    }

    /// F-distribution skew/kurt closed forms — frankenscipy-zhiof.
    #[test]
    fn f_dist_skew_kurt_match_scipy() {
        // scipy.stats.f.stats anchors at (dfn, dfd):
        //   (5, 10): skew 3.8670, kurt 50.8615
        //   (10, 20): skew 1.8352, kurt 6.8939
        let cases: [(f64, f64, f64, f64); 2] = [
            (5.0, 10.0, 3.867020319812938, 50.86153846153847),
            (10.0, 20.0, 1.8351920959819217, 6.893877551020408),
        ];
        for (d1, d2, ws, wk) in cases {
            let f = FDistribution::new(d1, d2);
            assert!(
                (f.skewness() - ws).abs() < 1e-10,
                "F({d1},{d2}).skew = {}, scipy {ws}",
                f.skewness()
            );
            assert!(
                (f.kurtosis() - wk).abs() < 1e-10,
                "F({d1},{d2}).kurt = {}, scipy {wk}",
                f.kurtosis()
            );
        }
        // Below thresholds: NaN.
        let f1 = FDistribution::new(3.0, 6.0); // dfd = 6, need >6 for skew
        assert!(f1.skewness().is_nan());
        let f2 = FDistribution::new(3.0, 7.0); // dfd = 7, need >8 for kurt
        assert!(!f2.skewness().is_nan());
        assert!(f2.kurtosis().is_nan());
    }

    #[test]
    fn invgamma_pdf_cdf_match_scipy() {
        // Exact scipy.stats.invgamma(a=3). The InverseGamma suite covers skew/kurt
        // and entropy but no exact pdf/cdf at a point.
        let d = InverseGamma::new(3.0);
        assert!(
            (d.pdf(0.3) - 2.202_098_354_768_667).abs() < 1e-11,
            "pdf(0.3)"
        );
        assert!(
            (d.pdf(0.5) - 1.082_682_265_892_901_4).abs() < 1e-12,
            "pdf(0.5)"
        );
        assert!(
            (d.cdf(0.5) - 0.676_676_416_183_063_4).abs() < 1e-12,
            "cdf(0.5)"
        );
        // Batch pdf_many/logpdf_many (Gamma(a) hoisted) byte-identical to per-point.
        let xs = [-1.0, 0.0, 0.3, 0.5, 1.0, 3.0];
        let pm = d.pdf_many(&xs);
        let lpm = d.logpdf_many(&xs);
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(pm[i], d.pdf(x), "pdf_many != pdf at {x}");
            assert_eq!(lpm[i], d.logpdf(x), "logpdf_many != logpdf at {x}");
        }
    }

    /// InverseGamma skew/kurt closed forms — frankenscipy-d4j8j.
    #[test]
    fn invgamma_skew_kurt_match_scipy() {
        // skew = 4√(a−2)/(a−3), kurt = 6(5a−11)/((a−3)(a−4))
        let cases: [(f64, f64, f64); 3] = [
            (4.0, 5.656854249492381, f64::NAN),
            (5.0, 3.4641016151377544, 42.0),
            (10.0, 1.6162440712835373, 5.571_428_571_428_572),
        ];
        for (a, ws, wk) in cases {
            let g = InverseGamma::new(a);
            assert!(
                (g.skewness() - ws).abs() < 1e-10,
                "InverseGamma({a}).skew = {}, scipy {ws}",
                g.skewness()
            );
            if wk.is_nan() {
                assert!(
                    g.kurtosis().is_nan(),
                    "InverseGamma({a}).kurt should be NaN"
                );
            } else {
                assert!(
                    (g.kurtosis() - wk).abs() < 1e-9,
                    "InverseGamma({a}).kurt = {}, scipy {wk}",
                    g.kurtosis()
                );
            }
        }
        // a≤3 → skew NaN.
        assert!(InverseGamma::new(2.5).skewness().is_nan());
    }

    #[test]
    fn invgamma_entropy_matches_scipy_reference_values() {
        // scipy.stats.invgamma(a).entropy() = a + ln Γ(a) − (1 + a) ψ(a).
        let cases = [
            (2.0_f64, 0.731_646_994_7),
            (3.0, 0.002_009_840_2),
            (5.0, -0.858_652_180_2),
        ];
        for &(a, h) in &cases {
            let g = InverseGamma::new(a);
            assert_close(g.entropy(), h, 1e-8, &format!("InverseGamma({a}) entropy"));
        }
    }

    #[test]
    fn studentt_entropy_matches_scipy_reference_values() {
        // scipy.stats.t(df).entropy() = (df+1)/2·(ψ((df+1)/2) − ψ(df/2))
        //                              + 0.5·ln(df) + ln Γ(df/2) + 0.5·ln(π)
        //                              − ln Γ((df+1)/2).
        let cases = [
            (3.0_f64, 1.773_477_571_9),
            (5.0, 1.627_502_672_4),
            (10.0, 1.521_262_493_0),
        ];
        for &(df, h) in &cases {
            let t = StudentT::new(df);
            assert_close(t.entropy(), h, 1e-8, &format!("StudentT({df}) entropy"));
        }
    }

    #[test]
    fn f_dist_sf_plus_cdf() {
        let f = FDistribution::new(4.0, 8.0);
        for x in [0.5, 1.0, 2.0, 5.0] {
            assert_close(f.sf(x) + f.cdf(x), 1.0, 1e-6, &format!("F sf+cdf at {x}"));
        }
    }

    #[test]
    fn f_dist_sf_tail_matches_scipy() {
        // frankenscipy-…: F.sf inherited the lossy 1−cdf default and returned 0
        // in the right tail (scipy.stats.f.sf(155,20,20) = 1.03e-17). Closed-form
        // survival via the complementary regularized incomplete beta. scipy 1.17.1.
        let cases = [
            (20.0, 20.0, 155.0, 1.0267926396420116e-17),
            (3.0, 30.0, 150.0, 3.768865624162301e-18),
            (5.0, 10.0, 200.0, 1.1023299105708095e-09),
            (10.0, 10.0, 100.0, 1.1597816316815971e-08),
            (2.0, 5.0, 300.0, 6.209213230591552e-06),
        ];
        for (dfn, dfd, x, expected) in cases {
            let got = FDistribution::new(dfn, dfd).sf(x);
            let rel = ((got - expected) / expected).abs();
            assert!(
                rel < 1e-6,
                "F({dfn},{dfd}).sf({x}) = {got:e}, scipy {expected:e}, rel={rel:e}"
            );
        }
    }

    // ── Beta distribution ───────────────────────────────────────────

    #[test]
    fn beta_dist_pdf_support() {
        let b = BetaDist::new(2.0, 3.0);
        assert_eq!(b.pdf(-0.1), 0.0);
        assert_eq!(b.pdf(1.1), 0.0);
        assert!(b.pdf(0.5) > 0.0);
    }

    #[test]
    fn beta_dist_pdf_many_matches_pdf() {
        // Batch pdf_many/logpdf_many (ln_beta hoisted) must be byte-identical to
        // per-point pdf/logpdf, including out-of-support and x∈{0,1} boundaries.
        let b = BetaDist::new(2.5, 3.5);
        let xs = [-0.1, 0.0, 0.25, 0.5, 0.9, 1.0, 1.1];
        let pm = b.pdf_many(&xs);
        let lpm = b.logpdf_many(&xs);
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(pm[i], b.pdf(x), "pdf_many != pdf at {x}");
            assert_eq!(lpm[i], b.logpdf(x), "logpdf_many != logpdf at {x}");
        }
    }

    #[test]
    fn beta_dist_cdf_bounds() {
        let b = BetaDist::new(2.0, 5.0);
        assert_eq!(b.cdf(0.0), 0.0);
        assert_eq!(b.cdf(1.0), 1.0);
    }

    #[test]
    fn beta_dist_sf_tail_matches_scipy() {
        // frankenscipy-…: BetaDist.sf inherited the lossy 1−cdf default and
        // returned 0 as x→1 (beta(2,8).sf(0.9999) scipy 9e-32). Closed-form
        // sf = I_{1−x}(b,a). scipy.stats.beta.sf 1.17.1.
        let cases = [
            (2.0, 8.0, 0.999, 8.992000000000064e-24),
            (2.0, 8.0, 0.9999, 8.999199999992071e-32),
            (5.0, 2.0, 0.99, 0.0014604476050000025),
        ];
        for (a, b, x, expected) in cases {
            let got = BetaDist::new(a, b).sf(x);
            let rel = ((got - expected) / expected).abs();
            assert!(
                rel < 1e-12,
                "Beta({a},{b}).sf({x}) = {got:e}, scipy {expected:e}, rel={rel:e}"
            );
        }
    }

    #[test]
    fn gengamma_pdf_many_matches_pdf() {
        // Batch pdf_many/logpdf_many (ln|c|/lnΓ(a) hoisted) must be byte-identical
        // to per-point pdf/logpdf, including x<=0.
        let g = GenGamma::new(1.9839, 1.542);
        let xs = [-1.0, 0.0, 0.4, 1.0, 2.5, 7.0];
        let pm = g.pdf_many(&xs);
        let lpm = g.logpdf_many(&xs);
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(pm[i], g.pdf(x), "pdf_many != pdf at {x}");
            assert_eq!(lpm[i], g.logpdf(x), "logpdf_many != logpdf at {x}");
        }
    }

    #[test]
    fn gengamma_sf_tail_matches_scipy() {
        // frankenscipy-…: GenGamma.sf returned 0 in the right tail (gengamma(2,1)
        // .sf(80) scipy 1.46e-33). Closed-form survival via the complementary
        // regularized gamma. scipy.stats.gengamma.sf 1.17.1.
        let cases = [
            (2.0, 1.0, 40.0, 1.7418252446695558e-16),
            (2.0, 1.0, 80.0, 1.4619296241547749e-33),
            (3.0, 2.0, 20.0, 1.5398155074540412e-169),
        ];
        for (a, c, x, expected) in cases {
            let got = GenGamma::new(a, c).sf(x);
            let rel = ((got - expected) / expected).abs();
            assert!(
                rel < 1e-12,
                "GenGamma({a},{c}).sf({x}) = {got:e}, scipy {expected:e}, rel={rel:e}"
            );
        }
    }

    #[test]
    fn beta_dist_uniform_special_case() {
        // Beta(1,1) = Uniform(0,1)
        let b = BetaDist::new(1.0, 1.0);
        assert_close(b.mean(), 0.5, 1e-10, "Beta(1,1) mean");
        assert_close(b.var(), 1.0 / 12.0, 1e-10, "Beta(1,1) var");
        assert_close(b.cdf(0.5), 0.5, 1e-4, "Beta(1,1) cdf(0.5)");
    }

    #[test]
    fn beta_dist_mean_var() {
        let b = BetaDist::new(2.0, 5.0);
        // mean = a/(a+b) = 2/7
        assert_close(b.mean(), 2.0 / 7.0, 1e-10, "Beta(2,5) mean");
        // var = ab/((a+b)^2*(a+b+1)) = 10/(49*8) = 10/392
        assert_close(b.var(), 10.0 / 392.0, 1e-10, "Beta(2,5) var");
    }

    #[test]
    fn beta_dist_symmetry() {
        // Beta(a,b) at x has same pdf as Beta(b,a) at 1-x
        let b1 = BetaDist::new(2.0, 5.0);
        let b2 = BetaDist::new(5.0, 2.0);
        assert_close(b1.pdf(0.3), b2.pdf(0.7), 1e-10, "Beta symmetry");
    }

