    #[test]
    fn multivariate_normal_pdf_matches_scipy_reference() {
        let rv = MultivariateNormal::new(&[0.0, 0.0], &[vec![1.0, 0.2], vec![0.2, 2.0]])
            .expect("multivariate normal");
        let pdf = rv.pdf(&[0.0, 0.0]).expect("pdf");
        assert_close(pdf, 0.11368210220849669, 1e-12, "multivariate_normal pdf");
    }

    #[test]
    fn multivariate_normal_logpdf_many_matches_logpdf() {
        // Batch logpdf_many/pdf_many must be byte-identical to per-point logpdf/pdf.
        let rv = MultivariateNormal::new(&[0.5, -1.0], &[vec![1.0, 0.2], vec![0.2, 2.0]])
            .expect("multivariate normal");
        let pts = vec![vec![0.0, 0.0], vec![1.5, -0.5], vec![-2.0, 3.0]];
        let batch_lp = rv.logpdf_many(&pts).expect("logpdf_many");
        let batch_p = rv.pdf_many(&pts).expect("pdf_many");
        for (i, x) in pts.iter().enumerate() {
            assert_eq!(batch_lp[i], rv.logpdf(x).unwrap(), "logpdf_many != logpdf");
            assert_eq!(batch_p[i], rv.pdf(x).unwrap(), "pdf_many != pdf");
        }
    }

    #[test]
    fn multivariate_normal_logpdf_many_parallel_is_bit_identical() {
        // 6-D, large input (n>=5 + work ≥ 2^18) to exercise the threaded path; it
        // must be bit-identical to mapping the scalar logpdf.
        let d = 6usize;
        let mean: Vec<f64> = (0..d).map(|i| 0.1 * i as f64 - 0.3).collect();
        let mut cov = vec![vec![0.0f64; d]; d];
        for (i, cov_i) in cov.iter_mut().enumerate().take(d) {
            for (j, slot) in cov_i.iter_mut().enumerate().take(d) {
                *slot = if i == j { 1.5 + i as f64 * 0.3 } else { 0.15 };
            }
        }
        let rv = MultivariateNormal::new(&mean, &cov).expect("mvn");
        let mut state = 0x9E37_79B9_u64;
        let mut nx = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            (state >> 11) as f64 / (1u64 << 53) as f64
        };
        let pts: Vec<Vec<f64>> = (0..60_000)
            .map(|_| (0..d).map(|_| nx() * 6.0 - 3.0).collect())
            .collect();
        let batch = rv.logpdf_many(&pts).expect("logpdf_many");
        assert_eq!(batch.len(), pts.len());
        for (x, &b) in pts.iter().zip(&batch) {
            assert_eq!(
                b.to_bits(),
                rv.logpdf(x).unwrap().to_bits(),
                "parallel != serial"
            );
        }
    }

