    #[test]
    fn dirichlet_mean_sums_to_one() {
        let d = Dirichlet::new(&[1.0, 2.0, 3.0]);
        let mean = d.mean();
        let sum: f64 = mean.iter().sum();
        assert!((sum - 1.0).abs() < 1e-10, "mean should sum to 1");
    }

