    #[test]
    fn trim_family_matches_scipy() {
        let d = [2.0, 4.0, 1.0, 7.0, 3.0, 9.0, 5.0, 6.0, 8.0, 10.0, 2.5, 0.3];
        let nan = f64::NAN;
        let eq = |got: &[f64], want: &[f64], msg: &str| {
            assert_eq!(got.len(), want.len(), "{msg} len");
            for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
                if w.is_nan() {
                    assert!(g.is_nan(), "{msg}[{i}]: {g} expected NaN");
                } else {
                    assert!((g - w).abs() <= 1e-12, "{msg}[{i}]: {g} vs {w}");
                }
            }
        };
        eq(
            &trima(&d, (Some(3.0), Some(8.0)), (true, true)),
            &[nan, 4.0, nan, 7.0, 3.0, nan, 5.0, 6.0, 8.0, nan, nan, nan],
            "trima",
        );
        eq(
            &trima(&d, (Some(3.0), Some(8.0)), (false, false)),
            &[nan, 4.0, nan, 7.0, nan, nan, 5.0, 6.0, nan, nan, nan, nan],
            "trima_excl",
        );
        eq(
            &trimr(&d, (Some(0.2), Some(0.2)), (true, true)),
            &[2.0, 4.0, nan, 7.0, 3.0, nan, 5.0, 6.0, 8.0, nan, 2.5, nan],
            "trimr",
        );
        eq(
            &trimtail(&d, 0.25, "left", (true, true)),
            &[nan, 4.0, nan, 7.0, 3.0, 9.0, 5.0, 6.0, 8.0, 10.0, 2.5, nan],
            "trimtail_l",
        );
        eq(
            &trimtail(&d, 0.25, "right", (true, true)),
            &[2.0, 4.0, 1.0, 7.0, 3.0, nan, 5.0, 6.0, nan, nan, 2.5, 0.3],
            "trimtail_r",
        );
    }

    #[test]
    fn discrete_ppf_isf_match_scipy() {
        // Generic DiscreteDistribution::ppf/isf (cdf/sf binary search).
        let p = Poisson::new(3.0);
        // scipy.stats.poisson(3).ppf / .isf
        assert_eq!(p.ppf(0.01), 0.0);
        assert_eq!(p.ppf(0.5), 3.0);
        assert_eq!(p.ppf(0.95), 6.0);
        assert_eq!(p.ppf(0.999), 10.0);
        assert_eq!(p.ppf(0.0), -1.0);
        assert!(p.ppf(1.0).is_infinite() && p.ppf(1.0) > 0.0);
        assert!(p.ppf(-0.1).is_nan());
        assert_eq!(p.isf(0.001), 10.0);
        assert_eq!(p.isf(0.05), 6.0);
        assert_eq!(p.isf(0.5), 3.0);
        assert_eq!(p.isf(0.99), 0.0);
        assert_eq!(p.isf(1.0), -1.0);
        assert!(p.isf(0.0).is_infinite() && p.isf(0.0) > 0.0);

        // Signed-support distributions are unsupported via the u64 ppf/isf.
        assert!(Skellam::new(2.0, 1.0).ppf(0.5).is_nan());
        assert!(DiscreteLaplace::new(0.5).isf(0.5).is_nan());
    }

