    #[test]
    fn cosine_higher_moments_match_scipy() {
        // /mock-code-finder for [frankenscipy-lud8x]: pin closed-form
        // skew/kurt/entropy. scipy.stats.cosine values:
        //   skew = 0
        //   ex_kurt = -6(π⁴ - 90)/(5(π² - 6)²) ≈ -0.5937628755982794
        //   entropy = ln(4π) − 1 ≈ 1.5310242469692907
        let dist = CosineDistribution;
        assert_close(dist.skewness(), 0.0, 1e-15, "Cosine.skewness");
        let pi2 = PI * PI;
        let pi4 = pi2 * pi2;
        let ex_kurt = -6.0 * (pi4 - 90.0) / (5.0 * (pi2 - 6.0).powi(2));
        assert_close(dist.kurtosis(), ex_kurt, 1e-15, "Cosine.kurtosis");
        assert!((dist.kurtosis() - (-0.593_762_875_598_279_4)).abs() < 1e-13);
        assert_close(
            dist.entropy(),
            (4.0 * PI).ln() - 1.0,
            1e-15,
            "Cosine.entropy",
        );
        assert!((dist.entropy() - 1.531_024_246_969_290_7).abs() < 1e-13);
    }

    #[test]
    fn f_one_v_cdf_is_studentt_squared() {
        // /testing-metamorphic for [frankenscipy-gfeto]: textbook
        // identity If T ~ StudentT(ν), then T² ~ F(1, ν). At the
        // CDF level, for t > 0 and x = t²:
        //
        //   F(1, ν).cdf(t²) = P(|T| ≤ t) = 2·StudentT(ν).cdf(t) − 1
        //
        // Independent verification: F.cdf invokes
        // regularized_incomplete_beta(0.5, 0.5ν, t²/(t²+ν)) directly,
        // while StudentT.cdf invokes the symmetric form
        // regularized_incomplete_beta(0.5ν, 0.5, ν/(t²+ν)) and folds
        // via I_x(a,b) + I_{1-x}(b,a) = 1. A bug in either parameter
        // swap surfaces as a mismatch.
        for &v in &[1.0_f64, 2.0, 5.0, 30.0, 100.0] {
            let f = FDistribution::new(1.0, v);
            let t = StudentT { df: v };
            for &t_val in &[0.1_f64, 0.5, 1.0, 2.0, 5.0] {
                let x = t_val * t_val;
                let lhs = f.cdf(x);
                let rhs = 2.0 * t.cdf(t_val) - 1.0;
                assert_close(
                    lhs,
                    rhs,
                    1e-10,
                    &format!("F(1, {v}).cdf({x}) vs 2·T({v}).cdf({t_val}) − 1"),
                );
                // sf = 1 - cdf, equivalent through the same identity
                // routed via two different code paths.
                let lhs_sf = f.sf(x);
                let rhs_sf = 2.0 * t.sf(t_val);
                assert_close(
                    lhs_sf,
                    rhs_sf,
                    1e-10,
                    &format!("F(1, {v}).sf({x}) vs 2·T({v}).sf({t_val})"),
                );
            }
        }
    }

    #[test]
    fn halflogistic_is_folded_logistic() {
        // /testing-metamorphic for [frankenscipy-z6ssa]: textbook
        // identity HalfLogistic ≡ |Logistic(0, 1)|. For x ≥ 0:
        //   HalfLogistic.pdf(x) = 2 · Logistic.pdf(x)
        //   HalfLogistic.cdf(x) = 2 · Logistic.cdf(x) − 1
        //   HalfLogistic.sf(x)  = 2 · Logistic.sf(x)
        // Independent verification across two distinct code paths:
        // Logistic uses exp/(1+exp)² with translation/scale logic;
        // HalfLogistic uses 2·exp(-x)/(1+exp(-x))² directly. The
        // algebraic equivalence at x ≥ 0 holds only if both
        // implementations are correct.
        let hl = HalfLogistic;
        let lg = Logistic::new(0.0, 1.0);
        for &x in &[0.0_f64, 0.05, 0.5, 1.0, 2.5, 5.0, 10.0] {
            assert_close(
                hl.pdf(x),
                2.0 * lg.pdf(x),
                1e-12,
                &format!("HalfLogistic.pdf({x}) vs 2·Logistic.pdf({x})"),
            );
            assert_close(
                hl.cdf(x),
                2.0 * lg.cdf(x) - 1.0,
                1e-12,
                &format!("HalfLogistic.cdf({x}) vs 2·Logistic.cdf({x}) − 1"),
            );
            assert_close(
                hl.sf(x),
                2.0 * lg.sf(x),
                1e-12,
                &format!("HalfLogistic.sf({x}) vs 2·Logistic.sf({x})"),
            );
        }
    }

    #[test]
    fn betaprime_is_beta_under_x_over_one_plus_x() {
        // /testing-metamorphic for [frankenscipy-2n31z]: textbook
        // identity BetaPrime(α, β) ≡ Beta(α, β) under Y = X/(1+X).
        //   cdf:  BetaPrime(a, b).cdf(x) = Beta(a, b).cdf(x/(1+x))
        //   sf:   BetaPrime(a, b).sf(x)  = Beta(a, b).sf(x/(1+x))
        //   pdf:  BetaPrime(a, b).pdf(x) = Beta(a, b).pdf(x/(1+x)) / (1+x)²
        // Independent verification across two distinct implementations:
        // BetaPrime.cdf and Beta.cdf both go through
        // regularized_incomplete_beta but with different parameterization,
        // and the pdf paths differ entirely.
        let shapes = [(0.5_f64, 1.5), (1.0, 1.0), (2.0, 3.0), (5.0, 0.7)];
        let xs = [0.001_f64, 0.1, 0.5, 1.0, 2.5, 10.0];
        for (a, b) in shapes {
            let bp = BetaDist::new(a, b);
            let bprime = BetaPrime::new(a, b);
            for x in xs {
                let y = x / (1.0 + x);
                let scale_pdf = (1.0 + x) * (1.0 + x);
                assert_close(
                    bprime.pdf(x),
                    bp.pdf(y) / scale_pdf,
                    1e-10 * bp.pdf(y).abs().max(1.0),
                    &format!("BetaPrime({a},{b}).pdf({x}) vs Beta.pdf({y})/(1+{x})²"),
                );
                assert_close(
                    bprime.cdf(x),
                    bp.cdf(y),
                    1e-10,
                    &format!("BetaPrime({a},{b}).cdf({x}) vs Beta.cdf({y})"),
                );
                assert_close(
                    bprime.sf(x),
                    bp.sf(y),
                    1e-10,
                    &format!("BetaPrime({a},{b}).sf({x}) vs Beta.sf({y})"),
                );
            }
        }
    }

    #[test]
    fn skewnorm_cdf_clamps_for_large_a() {
        // /testing-fuzzing regression for [frankenscipy-r7dbb]:
        // For large |a|, Owen's T (10-pt Gauss-Legendre) loses
        // precision in the deep tail and the raw formula
        // Φ(x) − 2·T(x, a) can drift slightly outside [0, 1].
        // scipy.stats.skewnorm clamps via np.clip(cdf, 0, 1);
        // fsci must match.
        let dist = SkewNorm::new(50.0);
        // Pre-fix this returned -0.024.
        let c = dist.cdf(-1.0);
        assert!(
            (0.0..=1.0).contains(&c),
            "SkewNorm(50).cdf(-1) = {c} must be in [0, 1]"
        );
        // Stress sweep: every (a, x) result must lie in [0, 1].
        for &a in &[-50.0_f64, -10.0, -1.0, 0.0, 1.0, 10.0, 50.0] {
            let dist = SkewNorm::new(a);
            for &x in &[-1.0e6_f64, -10.0, -1.0, 0.0, 1.0, 10.0, 1.0e6] {
                let c = dist.cdf(x);
                assert!(
                    (0.0..=1.0).contains(&c),
                    "cdf({x}; a={a}) = {c} must be in [0, 1]"
                );
            }
        }
    }

    #[test]
    fn skewnorm_pdf_cdf_match_scipy() {
        // /porting-to-rust [frankenscipy-cquzz]: scipy reference values.
        let cases = [
            // (a, x, pdf, cdf)
            (
                0.0,
                -1.0,
                0.241_970_724_519_143_37,
                0.158_655_253_931_457_07,
            ),
            (0.0, 0.0, 0.398_942_280_401_432_7, 0.5),
            (0.0, 1.0, 0.241_970_724_519_143_37, 0.841_344_746_068_542_9),
            (0.5, -1.0, 0.149_314_103_573_760_6, 0.072_525_871_689_886_35),
            (0.5, 0.0, 0.398_942_280_401_432_7, 0.352_416_382_349_566_74),
            (0.5, 1.0, 0.334_627_345_464_526_1, 0.755_215_363_826_972_2),
            (
                2.0,
                -1.0,
                0.011_009_731_820_814_06,
                0.001_718_879_945_288_881_4,
            ),
            (2.0, 0.0, 0.398_942_280_401_432_7, 0.147_583_617_650_433_26),
            (2.0, 1.0, 0.472_931_717_217_472_7, 0.684_408_372_082_374_7),
        ];
        for (a, x, pdf_want, cdf_want) in cases {
            let dist = SkewNorm::new(a);
            assert_close(
                dist.pdf(x),
                pdf_want,
                1e-12,
                &format!("SkewNorm({a}).pdf({x})"),
            );
            assert_close(
                dist.cdf(x),
                cdf_want,
                1e-9,
                &format!("SkewNorm({a}).cdf({x})"),
            );
        }
    }

    #[test]
    fn skewnorm_left_tail_cdf_matches_scipy() {
        // Regression (frankenscipy-qg05t): for a > 0 the left-tail cdf via
        // Φ(x) − 2·T(x,a) cancels catastrophically — cdf(-8) was ~8e-30 vs the
        // true ~4e-241 (200+ orders off). The pdf-quadrature fallback (mirroring
        // scipy.stats.skewnorm's own `cdf<1e-6 & a>0` branch) restores it. Both
        // libraries are quadrature-limited here, so compare with a relative
        // tolerance; values from scipy.stats.skewnorm 1.17.1.
        let cases: &[(f64, f64, f64)] = &[
            (0.5, -4.0, 1.126_688_057_257_066_8e-6),
            (1.0, -6.0, 9.733_551_814_821_875e-19),
            (2.0, -8.0, 1.603_960_665_285_063_6e-73),
            (4.0, -8.0, 4.043_632_862_450_817e-241),
        ];
        for &(a, x, want) in cases {
            let got = SkewNorm::new(a).cdf(x);
            let rel = (got - want).abs() / want.abs();
            assert!(
                rel < 1e-3,
                "SkewNorm({a}).cdf({x}) = {got:e}, scipy {want:e} (relerr {rel:e})"
            );
        }
        // Beyond the f64 range the cdf underflows to exactly 0, as scipy returns.
        assert_eq!(SkewNorm::new(4.0).cdf(-15.0), 0.0);
    }

    #[test]
    fn truncpareto_large_c_limit_is_pareto() {
        // /testing-metamorphic for [frankenscipy-rk8zd]: textbook
        // limit TruncPareto(b, c→∞) ≡ Pareto(b, scale=1). The
        // truncation factor (1 − c^(-b)) in the denominator
        // converges to 1, leaving 1 − x^(-b) — Pareto's standard
        // form. For b ≥ 1 the limit is essentially exact at c=1e10
        // (c^(-b) ≤ 1e-10); for b < 1 it converges more slowly.
        // Independent verification: TruncPareto's closed form goes
        // through powf with 1 / (1 - c^(-b)); Pareto goes directly
        // via 1 − (scale/x)^b with scale=1.
        for &b in &[1.0_f64, 1.5, 2.0, 3.0] {
            let tp = TruncPareto::new(b, 1.0e10);
            let p = Pareto::new(b, 1.0);
            for &x in &[1.5_f64, 2.0, 5.0, 100.0] {
                assert_close(
                    tp.cdf(x),
                    p.cdf(x),
                    1e-9,
                    &format!("TruncPareto({b}, 1e10).cdf({x}) vs Pareto({b}, 1).cdf({x})"),
                );
                assert_close(
                    tp.pdf(x),
                    p.pdf(x),
                    1e-9 * p.pdf(x).abs().max(1e-12),
                    &format!("TruncPareto({b}, 1e10).pdf({x}) vs Pareto({b}, 1).pdf({x})"),
                );
            }
        }
    }

    #[test]
    fn irwinhall_pdf_cdf_match_scipy() {
        // /porting-to-rust [frankenscipy-7dxwg]: scipy reference values.
        // irwinhall(2).pdf(0.5) = 0.5; .pdf(1) = 1; .cdf(0.5) = 0.125; .cdf(1) = 0.5
        let h2 = IrwinHall::new(2);
        assert_close(h2.pdf(0.5), 0.5, 1e-12, "h2.pdf(0.5)");
        assert_close(h2.pdf(1.0), 1.0, 1e-12, "h2.pdf(1)");
        assert_close(h2.cdf(0.5), 0.125, 1e-12, "h2.cdf(0.5)");
        assert_close(h2.cdf(1.0), 0.5, 1e-12, "h2.cdf(1)");
        assert_close(h2.cdf(1.8), 0.98, 1e-12, "h2.cdf(1.8)");
        // n=3
        let h3 = IrwinHall::new(3);
        assert_close(h3.pdf(0.5), 0.125, 1e-12, "h3.pdf(0.5)");
        assert_close(h3.pdf(1.5), 0.75, 1e-12, "h3.pdf(1.5)");
        assert_close(h3.cdf(1.5), 0.5, 1e-12, "h3.cdf(1.5)");
        // n=5
        let h5 = IrwinHall::new(5);
        assert_close(h5.pdf(2.5), 0.598_958_333_333_333_3, 1e-12, "h5.pdf(2.5)");
        assert_close(h5.cdf(2.5), 0.5, 1e-12, "h5.cdf(2.5)");
        // Outside support
        assert_eq!(h2.pdf(-0.5), 0.0);
        assert_eq!(h2.pdf(2.5), 0.0);
        assert_eq!(h2.cdf(-0.5), 0.0);
        assert_eq!(h2.cdf(2.5), 1.0);
    }

    #[test]
    fn irwinhall_moments_match_scipy() {
        // /porting-to-rust [frankenscipy-7dxwg]: closed-form moments.
        // n=2: mean=1, var=1/6, skew=0, ex_kurt=-3/5
        // n=3: mean=1.5, var=0.25, skew=0, ex_kurt=-2/5
        // n=5: mean=2.5, var=5/12, skew=0, ex_kurt=-6/25
        let cases = [
            (2_u32, 1.0, 1.0 / 6.0, -3.0 / 5.0),
            (3, 1.5, 0.25, -2.0 / 5.0),
            (5, 2.5, 5.0 / 12.0, -6.0 / 25.0),
            (10, 5.0, 10.0 / 12.0, -6.0 / 50.0),
        ];
        for (n, want_mean, want_var, want_kurt) in cases {
            let dist = IrwinHall::new(n);
            assert_close(dist.mean(), want_mean, 1e-15, &format!("mean({n})"));
            assert_close(dist.var(), want_var, 1e-15, &format!("var({n})"));
            assert_close(dist.skewness(), 0.0, 1e-15, &format!("skew({n})"));
            assert_close(dist.kurtosis(), want_kurt, 1e-15, &format!("kurt({n})"));
        }
    }

    #[test]
    fn irwinhall_cdf_clamps_for_large_n() {
        // /testing-fuzzing regression for [frankenscipy-3f75d]:
        // for large n the alternating-sign sum in cdf accumulates
        // fp error and the raw quotient can drift outside [0, 1].
        // Concrete fuzz finding: IrwinHall(19).cdf(17.1) ≈ 1.0000000037.
        // Verify the clamp now keeps results in valid range across
        // a stress sweep.
        for &n in &[15_u32, 17, 19, 20] {
            let dist = IrwinHall::new(n);
            let nf = n as f64;
            for k in 0..=20 {
                let x = (k as f64) * nf / 20.0;
                let c = dist.cdf(x);
                assert!(
                    (0.0..=1.0).contains(&c),
                    "cdf({x}; n={n}) = {c} must be in [0, 1]"
                );
                let p = dist.pdf(x);
                assert!(
                    p >= 0.0 && p.is_finite(),
                    "pdf({x}; n={n}) = {p} must be ≥ 0 and finite"
                );
            }
        }
    }

