    #[test]
    fn normal_standardization_holds_in_deep_tail() {
        // /testing-metamorphic for [frankenscipy-rspw1]: textbook
        // standardization identity. Normal(μ, σ).cdf(x) =
        // Normal(0, 1).cdf((x - μ)/σ). Exercises the erfc-path
        // precision improvement (095a947 + 93a4cc0) at translated
        // and scaled locations: e.g., Normal(5, 2).cdf(-9) must
        // produce the same Φ(-7) ≈ 1.28e-12 that Normal(0, 1).cdf(-7)
        // does. Pre-fix both returned 0; post-fix both return
        // the same finite value.
        let std_normal = Normal::new(0.0, 1.0);
        let configs = [(5.0_f64, 2.0), (10.0, 0.5), (-3.0, 0.1), (0.0, 100.0)];
        let z_values = [-10.0_f64, -7.0, -3.0, 0.0, 3.0, 7.0];
        for (mu, sigma) in configs {
            let n = Normal::new(mu, sigma);
            for z in z_values {
                let x = mu + sigma * z;
                let lhs = n.cdf(x);
                let rhs = std_normal.cdf(z);
                let scale = lhs.abs().max(rhs.abs()).max(1e-300);
                let rel = (lhs - rhs).abs() / scale;
                assert!(
                    rel < 1e-12,
                    "Normal({mu}, {sigma}).cdf({x}) = {lhs} vs Normal(0, 1).cdf({z}) = {rhs}, rel = {rel:e}"
                );
            }
        }
    }

    #[test]
    fn lognormal_and_fatiguelife_cdf_deep_tail_precision() {
        // /mock-code-finder regression for [frankenscipy-tkpgq]:
        // Lognormal.cdf for very small x and FatigueLife.cdf for
        // very small/large x previously bypassed standard_normal_cdf
        // and used the inline 0.5·(1 + erf) form; both lost precision
        // (returned 0) deep in the tail. Post-fix: both delegate to
        // standard_normal_cdf and return the right order of magnitude.
        // For Lognormal(s=1, scale=1): z = ln(x); for x = 1e-5,
        // z ≈ -11.5, so cdf ≈ Φ(-11.5) ≈ 6.5e-31.
        let ln = Lognormal::new(1.0, 1.0);
        let v_small = ln.cdf(1.0e-5);
        assert!(
            v_small > 0.0,
            "Lognormal(1, 1).cdf(1e-5) = {v_small} must be positive (was 0 pre-fix)"
        );
        // For FatigueLife(c=0.1) at very small x: z = (√x - 1/√x)/0.1,
        // x = 1e-6 → z ≈ -10000 (extreme tail; either way we shouldn't
        // be at zero precision floor for moderately negative z).
        let fl = FatigueLife::new(1.0); // c=1 is moderate
        // x = 0.001 gives z = (√0.001 - 1/√0.001)/1 ≈ -31.6
        let v_fl_small = fl.cdf(0.01);
        // c=1, x=0.01 → z = (0.1 - 10) ≈ -9.9, Φ(-9.9) ≈ 1.9e-23 ≠ 0.
        assert!(
            v_fl_small > 0.0 || v_fl_small.abs() < 1e-300,
            "FatigueLife(1).cdf(0.01) = {v_fl_small} should not be exactly 0 for moderate z"
        );
    }

    #[test]
    fn normal_cdf_deep_tail_precision_via_standard_normal_cdf() {
        // /mock-code-finder regression for [frankenscipy-701x0]:
        // Normal.cdf used to compute 0.5·(1 + erf(z·FRAC_1_SQRT_2))
        // directly, bypassing the standard_normal_cdf erfc path and
        // suffering the same catastrophic cancellation for z ≲ -3.
        // Post-fix Normal.cdf delegates to standard_normal_cdf so
        // the deep-tail precision improvement (frankenscipy-6exgz)
        // applies uniformly.
        let n = Normal::new(0.0, 1.0);
        // scipy reference values:
        //   Normal(0, 1).cdf(-7) = 1.279812543885835e-12
        //   Normal(0, 1).cdf(-10) = 7.61985302416051e-24
        assert!(
            n.cdf(-7.0) > 0.0,
            "Normal(0, 1).cdf(-7) = {} must be positive",
            n.cdf(-7.0)
        );
        assert!(
            n.cdf(-10.0) > 0.0,
            "Normal(0, 1).cdf(-10) = {} must be positive",
            n.cdf(-10.0)
        );
        // Order-of-magnitude check (1e-7 relative is enough — exercise
        // proves we're not at the cancellation floor).
        let r7 = (n.cdf(-7.0) / 1.279_812_543_885_835e-12 - 1.0).abs();
        assert!(r7 < 1e-6, "Normal.cdf(-7) precision: rel err {r7:e}");
        let r10 = (n.cdf(-10.0) / 7.619_853_024_160_51e-24 - 1.0).abs();
        assert!(r10 < 1e-6, "Normal.cdf(-10) precision: rel err {r10:e}");
        // Translation-scaled instance also picks up the fix.
        let n2 = Normal::new(5.0, 2.0);
        assert!(
            n2.cdf(-9.0) > 0.0,
            "Normal(5, 2).cdf(-9) = {} (≡ Φ(-7)) must be positive",
            n2.cdf(-9.0)
        );
    }

    #[test]
    fn standard_normal_cdf_deep_tail_precision() {
        // /mock-code-finder regression for [frankenscipy-6exgz]:
        // pre-fix Φ(x) = 0.5·(1 + erf(x/√2)) lost precision below
        // x ≈ -3 due to 1 - (close to 1) catastrophic cancellation.
        // Post-fix path uses 0.5·erfc(-x/√2) for x < 0, retaining
        // full-precision tail values.
        // scipy reference values:
        //   Φ(-1) = 0.15865525393145707
        //   Φ(-3) = 0.0013498980316301035
        //   Φ(-5) = 2.866515719235352e-07
        //   Φ(-7) = 1.279812543885835e-12
        //   Φ(-10) = 7.61985302416051e-24
        // Pre-fix Φ(-7) returned 0 (rounded); post-fix returns ~1.28e-12.
        // Pre-fix Φ(-10) returned 0; post-fix returns ~7.6e-24.
        let cases = [
            (-1.0_f64, 0.158_655_253_931_457_07),
            (-3.0, 0.001_349_898_031_630_103_5),
            (-5.0, 2.866_515_719_235_352e-7),
            (-7.0, 1.279_812_543_885_835e-12),
            (-10.0, 7.619_853_024_160_51e-24),
        ];
        for (x, want) in cases {
            let got = standard_normal_cdf(x);
            // Relative tol 1e-6 — fsci_special::erfc_scalar has
            // ~1e-7 relative precision in the deep tail. Pre-fix
            // Φ(-7) returned 0 and Φ(-10) returned 0; post-fix
            // returns the right order of magnitude.
            let rel_err = (got - want).abs() / want.abs().max(f64::MIN_POSITIVE);
            assert!(
                rel_err < 1e-6 || (got == 0.0 && want < 1e-300),
                "Φ({x}) = {got}, want {want}, rel_err = {rel_err:e}"
            );
            // Crucially: must not be 0 in the deep tail.
            if x >= -10.0 {
                assert!(got > 0.0, "Φ({x}) = {got} must be positive");
            }
        }
        // Symmetry: Φ(-x) = 1 - Φ(x). Tolerance loosens deep in the
        // tail because 1 - Φ(x) for large positive x is itself the
        // catastrophic-cancellation form (Φ(x) is very close to 1).
        // Φ(-x) via the erfc path doesn't suffer that, so the
        // identity holds in the *direction* erfc → 1 - erf form
        // accurately, but the reverse is fundamentally fp-limited.
        for &x in &[1.0_f64, 3.0, 5.0] {
            let lhs = standard_normal_cdf(-x);
            let rhs = 1.0 - standard_normal_cdf(x);
            assert_close(
                lhs,
                rhs,
                1e-6 * lhs.abs().max(1e-15),
                &format!("Φ(-{x}) vs 1 - Φ({x})"),
            );
        }
    }

    #[test]
    fn recipinvgauss_cdf_clamps_for_large_mu() {
        // /testing-fuzzing regression for [frankenscipy-n82pr]: for
        // large mu the cdf formula Φ(-isqx·trm1) - exp(2/μ)·Φ(-isqx·trm2)
        // can accumulate fp error and drift outside [0, 1].
        // Concrete fuzz finding: RecipInvGauss(50).cdf(40.4) ≈ 1.00000000004.
        for &mu in &[10.0_f64, 25.0, 50.0] {
            let dist = RecipInvGauss::new(mu);
            for k in 1..=20 {
                let x = (k as f64) * mu / 5.0;
                let c = dist.cdf(x);
                assert!(
                    (0.0..=1.0).contains(&c),
                    "cdf({x}; mu={mu}) = {c} must be in [0, 1]"
                );
                let s = dist.sf(x);
                assert!(
                    (0.0..=1.0).contains(&s),
                    "sf({x}; mu={mu}) = {s} must be in [0, 1]"
                );
            }
        }
    }

    #[test]
    fn recipinvgauss_is_one_over_inverse_gaussian() {
        // /testing-metamorphic [frankenscipy-k7e3h]: textbook reciprocal
        // identity. If Y ~ InverseGaussian(mu) then 1/Y ~ RecipInvGauss(mu).
        // At the cdf level: RecipInvGauss(μ).cdf(x) = 1 - InverseGaussian(μ).cdf(1/x).
        let mus = [0.5_f64, 1.0, 2.0];
        let xs = [0.5_f64, 1.0, 2.0, 4.0];
        for &mu in &mus {
            let r = RecipInvGauss::new(mu);
            let ig = InverseGaussian::new(mu);
            for &x in &xs {
                let lhs = r.cdf(x);
                let rhs = 1.0 - ig.cdf(1.0 / x);
                assert_close(
                    lhs,
                    rhs,
                    1e-9,
                    &format!(
                        "RecipInvGauss({mu}).cdf({x}) vs 1 - InverseGaussian({mu}).cdf(1/{x})"
                    ),
                );
            }
        }
    }

    #[test]
    fn truncweibull_min_large_b_limit_is_weibull() {
        // /testing-metamorphic for [frankenscipy-qwg1y]: textbook
        // limit TruncWeibullMin(c, a=0, b→∞) ≡ Weibull(c, scale=1).
        // The truncation factor 1 − exp(−b^c) → 1, recovering the
        // standard Weibull pdf c·x^(c-1)·exp(-x^c).
        // Independent verification across two distinct paths:
        // TruncWeibullMin uses log-space expm1 form;
        // Weibull uses (c/scale)·z^(c-1)·exp(-z^c) where z = x/scale.
        for &c in &[0.5_f64, 1.0, 2.0, 3.0, 5.0] {
            let twm = TruncWeibullMin::new(c, 0.0, 1.0e20);
            let w = Weibull::new(c, 1.0);
            for &x in &[0.05_f64, 0.5, 1.0, 1.5, 3.0] {
                assert_close(
                    twm.pdf(x),
                    w.pdf(x),
                    1e-12,
                    &format!("TruncWeibullMin({c}, 0, 1e20).pdf({x}) vs Weibull({c}, 1).pdf({x})"),
                );
                assert_close(
                    twm.cdf(x),
                    w.cdf(x),
                    1e-12,
                    &format!("TruncWeibullMin({c}, 0, 1e20).cdf({x}) vs Weibull({c}, 1).cdf({x})"),
                );
            }
        }
    }

    #[test]
    fn truncweibull_min_handles_extreme_c_a_underflow() {
        // /testing-fuzzing regression for [frankenscipy-li9bu]:
        // For (c=10, a=10, b=10.1), c·a^c = 1e10 and exp(-a^c)
        // underflows to 0 — the original denom = exp(-a^c) - exp(-b^c)
        // collapsed to 0/0 = NaN. The log-space rewrite via expm1
        // / mul_add avoids the small-quantity subtraction.
        let d = TruncWeibullMin::new(10.0, 10.0, 10.1);
        // Mid-support point.
        let x = 10.05_f64;
        let p = d.pdf(x);
        let c = d.cdf(x);
        assert!(p.is_finite() && p >= 0.0, "pdf must be finite ≥ 0, got {p}");
        assert!(
            c.is_finite() && (0.0..=1.0).contains(&c),
            "cdf must be in [0, 1], got {c}"
        );
        // ppf round-trip on a moderate q.
        let q = d.cdf(10.05);
        if (1e-6..1.0 - 1e-6).contains(&q) {
            let recovered = d.ppf(q);
            assert!(
                (recovered - 10.05).abs() < 1e-9,
                "ppf round-trip lost precision: {recovered} vs 10.05"
            );
        }
    }

    #[test]
    fn truncweibull_min_rejects_invalid_args() {
        // /porting-to-rust [frankenscipy-op097]: validation contract.
        assert!(std::panic::catch_unwind(|| TruncWeibullMin::new(0.0, 0.0, 1.0)).is_err());
        assert!(std::panic::catch_unwind(|| TruncWeibullMin::new(-1.0, 0.0, 1.0)).is_err());
        assert!(std::panic::catch_unwind(|| TruncWeibullMin::new(1.0, -0.1, 1.0)).is_err());
        assert!(std::panic::catch_unwind(|| TruncWeibullMin::new(1.0, 1.0, 1.0)).is_err());
        assert!(std::panic::catch_unwind(|| TruncWeibullMin::new(1.0, 2.0, 1.0)).is_err());
    }

    #[test]
    fn rdist_pdf_cdf_match_scipy() {
        // /porting-to-rust [frankenscipy-i4qnc]: scipy reference values.
        // rdist(2).pdf(*) = 0.5 (uniform on [-1, 1])
        // rdist(3).pdf(0) = 2/π ≈ 0.6366
        // rdist(4).pdf(0) = 0.75
        // rdist(5).pdf(0) ≈ 0.8488
        let cases = [
            (2.0_f64, 0.0, 0.5, 0.5),
            (2.0, -0.5, 0.5, 0.25),
            (2.0, 0.5, 0.5, 0.75),
            (3.0, 0.0, 0.636_619_772_367_581_5, 0.5),
            (3.0, -0.5, 0.551_328_895_421_792_1, 0.195_501_109_477_885_38),
            (4.0, 0.0, 0.75, 0.5),
            (4.0, -0.5, 0.5625, 0.156_25),
            (5.0, 0.0, 0.848_826_363_156_775_4, 0.5),
        ];
        for (c, x, want_pdf, want_cdf) in cases {
            let dist = RDist::new(c);
            assert_close(
                dist.pdf(x),
                want_pdf,
                1e-12,
                &format!("RDist({c}).pdf({x})"),
            );
            assert_close(dist.cdf(x), want_cdf, 1e-9, &format!("RDist({c}).cdf({x})"));
        }
    }

    #[test]
    fn rdist_is_shifted_symmetric_beta() {
        // /testing-metamorphic for [frankenscipy-y9rz1]: textbook
        // identity. If Y ~ Beta(c/2, c/2) then 2Y − 1 ~ RDist(c).
        // At the cdf level: RDist(c).cdf(x) = Beta(c/2, c/2).cdf((x+1)/2).
        // At the pdf level: RDist(c).pdf(x) = Beta(c/2, c/2).pdf((x+1)/2) / 2
        // (the /2 is the Jacobian dY/dX = 1/2).
        // RDist's cdf goes through this identity by construction; the
        // pdf path is independent so the test exercises both code paths
        // — RDist via (1-x²)^(c/2-1)/B(1/2, c/2) and Beta via the
        // ln_beta/ln-form pdf.
        for &c in &[1.5_f64, 2.0, 3.0, 5.0, 10.0] {
            let r = RDist::new(c);
            let b = BetaDist::new(c / 2.0, c / 2.0);
            for &x in &[-0.9_f64, -0.5, -0.1, 0.0, 0.1, 0.5, 0.9] {
                let y = (x + 1.0) / 2.0;
                assert_close(
                    r.cdf(x),
                    b.cdf(y),
                    1e-12,
                    &format!("RDist({c}).cdf({x}) vs Beta(c/2, c/2).cdf((x+1)/2)"),
                );
                assert_close(
                    r.pdf(x),
                    b.pdf(y) / 2.0,
                    1e-10 * b.pdf(y).abs().max(1e-12),
                    &format!("RDist({c}).pdf({x}) vs Beta(c/2, c/2).pdf((x+1)/2)/2"),
                );
            }
        }
    }

    #[test]
    fn rdist_c2_is_uniform_neg1_pos1() {
        // /testing-metamorphic [frankenscipy-i4qnc]: RDist(c=2) ≡
        // Uniform(-1, 1). pdf is constant 1/2 on [-1, 1].
        let r = RDist::new(2.0);
        let u = Uniform::new(-1.0, 2.0); // loc=-1, scale=2 → [-1, 1]
        for &x in &[-0.9_f64, -0.5, 0.0, 0.5, 0.9] {
            assert_close(r.pdf(x), u.pdf(x), 1e-12, &format!("pdf({x})"));
            assert_close(r.cdf(x), u.cdf(x), 1e-12, &format!("cdf({x})"));
        }
    }

    #[test]
    fn rdist_c3_is_semicircular() {
        // /testing-metamorphic [frankenscipy-i4qnc]: RDist(c=3) ≡
        // Semicircular. Both have pdf = 2/π · √(1 − x²) on [-1, 1].
        let r = RDist::new(3.0);
        let s = Semicircular;
        for &x in &[-0.9_f64, -0.5, -0.1, 0.0, 0.1, 0.5, 0.9] {
            assert_close(r.pdf(x), s.pdf(x), 1e-12, &format!("pdf({x})"));
            assert_close(r.cdf(x), s.cdf(x), 1e-9, &format!("cdf({x})"));
        }
    }

    #[test]
    fn rdist_var_matches_one_over_c_plus_1() {
        // /porting-to-rust [frankenscipy-i4qnc]: closed-form var = 1/(c+1).
        for &c in &[2.0_f64, 3.0, 5.0, 10.0, 25.0] {
            let dist = RDist::new(c);
            assert_close(
                dist.var(),
                1.0 / (c + 1.0),
                1e-15,
                &format!("RDist({c}).var = 1/(c+1)"),
            );
            assert_close(dist.mean(), 0.0, 1e-15, "mean = 0");
            assert_close(dist.skewness(), 0.0, 1e-15, "skew = 0");
        }
    }

    #[test]
    fn rdist_kurtosis_matches_closed_form() {
        // Excess kurt = −6/(c + 3) from m_4 = 3/((c+1)(c+3)) and var =
        // 1/(c+1). Spans c = 3 (semicircle: ex.kurt = −1) through
        // c = 8 (≈ −0.545) — all match scipy.stats.rdist exactly.
        let cases = [(3.0_f64, -1.0), (5.0, -0.75), (8.0, -6.0 / 11.0)];
        for &(c, ku) in &cases {
            let dist = RDist::new(c);
            assert_close(dist.kurtosis(), ku, 1e-15, &format!("RDist({c}) kurt"));
        }
    }

    #[test]
    fn irwinhall_n2_is_triangular() {
        // /testing-metamorphic for [frankenscipy-fekdp]: textbook
        // identity IrwinHall(n=2) ≡ Triangular(0, 1, 2) — the sum
        // of 2 iid Uniform(0, 1) is the symmetric triangular on
        // [0, 2] peaking at 1.
        // Independent verification across two distinct code paths:
        // IrwinHall uses the alternating-sign sum (1/1!)·Σ(-1)^k·C(2,k)·(x-k);
        // Triangular uses piecewise linear 2(x-a)/((b-a)(c-a)).
        let ih = IrwinHall::new(2);
        let tr = Triangular::new(0.0, 1.0, 2.0);
        for &x in &[0.1_f64, 0.25, 0.5, 1.0, 1.25, 1.5, 1.75, 1.9] {
            assert_close(
                ih.pdf(x),
                tr.pdf(x),
                1e-12,
                &format!("IrwinHall(2).pdf({x}) vs Triangular(0,1,2).pdf({x})"),
            );
            assert_close(
                ih.cdf(x),
                tr.cdf(x),
                1e-12,
                &format!("IrwinHall(2).cdf({x}) vs Triangular(0,1,2).cdf({x})"),
            );
        }
    }

    #[test]
    fn irwinhall_n1_is_uniform() {
        // /testing-metamorphic [frankenscipy-7dxwg]: IrwinHall(n=1) ≡
        // Uniform(0, 1). n=1 is the trivial "sum of 1 uniform".
        let h1 = IrwinHall::new(1);
        let u = Uniform::new(0.0, 1.0);
        for &x in &[0.0_f64, 0.1, 0.5, 0.9, 1.0] {
            assert_close(h1.pdf(x), u.pdf(x), 1e-12, &format!("h1.pdf({x})"));
            assert_close(h1.cdf(x), u.cdf(x), 1e-12, &format!("h1.cdf({x})"));
        }
    }

    #[test]
    fn truncpareto_pdf_cdf_ppf_match_scipy() {
        // /porting-to-rust [frankenscipy-yvjyl]: scipy reference values.
        // truncpareto(b=2, c=5).pdf(2) = 0.2604166666666667
        // truncpareto(b=2, c=5).cdf(2) = 0.78125
        // truncpareto(b=2, c=5).ppf(0.5) = 1.3867504905630728
        // truncpareto(b=2, c=5).pdf(1) = 2.0833333333333335
        // truncpareto(b=2, c=5).pdf(5) = 0.016666666666666666
        // truncpareto(b=0.5, c=10).pdf(2) = 0.25853154970459075
        let d = TruncPareto::new(2.0, 5.0);
        assert_close(d.pdf(2.0), 0.260_416_666_666_666_7, 1e-12, "pdf(2)");
        assert_close(d.cdf(2.0), 0.781_25, 1e-12, "cdf(2)");
        assert_close(d.ppf(0.5), 1.386_750_490_563_072_8, 1e-12, "ppf(0.5)");
        assert_close(
            d.pdf(1.0),
            2.083_333_333_333_333_5,
            1e-12,
            "pdf(1) = b/denom",
        );
        assert_close(d.pdf(5.0), 0.016_666_666_666_666_666, 1e-12, "pdf(c)");
        let d2 = TruncPareto::new(0.5, 10.0);
        assert_close(d2.pdf(2.0), 0.258_531_549_704_590_75, 1e-12, "b<1 pdf");
        // Outside support
        assert_eq!(d.pdf(0.5), 0.0);
        assert_eq!(d.pdf(6.0), 0.0);
        assert_eq!(d.cdf(0.5), 0.0);
        assert_eq!(d.cdf(6.0), 1.0);
    }

    #[test]
    fn truncpareto_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.truncpareto(b, c).stats(moments='sk'). Closed-form
        // raw moments m_k = b·(c^{k−b}−1)/((k−b)·(1−c^{−b})) (with the
        // k = b removable singularity collapsing to b·log(c)/(1−c^{−b}))
        // always finite on the bounded support [1, c] for any b > 1.
        let cases = [
            (
                3.0_f64,
                5.0_f64,
                2.574_077_093_064_304,
                8.316_072_819_947_255,
            ),
            (2.5, 10.0, 3.681_629_038_739_022, 18.870_500_186_124_893),
            (1.5, 4.0, 1.292_786_253_135_568, 0.941_666_666_666_632),
        ];
        for &(b, c, sk, ku) in &cases {
            let d = TruncPareto::new(b, c);
            assert_close(
                d.skewness(),
                sk,
                1e-9,
                &format!("TruncPareto({b},{c}) skew"),
            );
            assert_close(
                d.kurtosis(),
                ku,
                1e-8,
                &format!("TruncPareto({b},{c}) kurt"),
            );
        }
    }

    #[test]
    fn truncpareto_ppf_inverts_cdf() {
        // /porting-to-rust [frankenscipy-yvjyl]: round-trip.
        for &(b, c) in &[(2.0_f64, 5.0), (0.5, 10.0), (3.0, 100.0)] {
            let d = TruncPareto::new(b, c);
            for &x in &[1.5_f64, 2.0, 3.0, 4.5] {
                if x > c {
                    continue;
                }
                let q = d.cdf(x);
                if (1e-10..1.0 - 1e-10).contains(&q) {
                    let recovered = d.ppf(q);
                    assert!(
                        (recovered - x).abs() < 1e-10 * x,
                        "TruncPareto({b}, {c}).ppf(cdf({x})) = {recovered}, want {x}"
                    );
                }
            }
        }
    }

    #[test]
    fn truncpareto_rejects_invalid_args() {
        // /porting-to-rust [frankenscipy-yvjyl]: validation contract.
        let result = std::panic::catch_unwind(|| TruncPareto::new(0.0, 5.0));
        assert!(result.is_err(), "b=0 must panic");
        let result = std::panic::catch_unwind(|| TruncPareto::new(2.0, 1.0));
        assert!(result.is_err(), "c=1 must panic");
        let result = std::panic::catch_unwind(|| TruncPareto::new(2.0, 0.5));
        assert!(result.is_err(), "c<1 must panic");
        let result = std::panic::catch_unwind(|| TruncPareto::new(f64::NAN, 5.0));
        assert!(result.is_err(), "NaN b must panic");
    }

    #[test]
    fn invgauss_skew_kurt_match_scipy_law() {
        // /mock-code-finder for [frankenscipy-ggikd]: closed-form
        // moments. scipy.stats.invgauss reports:
        //   skew    = 3·√mu
        //   ex_kurt = 15·mu
        // Pin both at multiple mu values verified against scipy.
        // Reference values:
        //   invgauss(0.5).skew = 2.121320343559643, kurt = 7.5
        //   invgauss(1.0).skew = 3.0,                kurt = 15.0
        //   invgauss(2.0).skew = 4.242640687119286, kurt = 30.0
        //   invgauss(5.0).skew = 6.708203932499369, kurt = 75.0
        let cases = [
            (0.5_f64, 2.121_320_343_559_643, 7.5),
            (1.0, 3.0, 15.0),
            (2.0, 4.242_640_687_119_286, 30.0),
            (5.0, 6.708_203_932_499_369, 75.0),
        ];
        for (mu, want_skew, want_kurt) in cases {
            let dist = InverseGaussian::new(mu);
            assert_close(
                dist.skewness(),
                want_skew,
                1e-12,
                &format!("InverseGaussian({mu}).skewness vs 3·√mu"),
            );
            assert_close(
                dist.kurtosis(),
                want_kurt,
                1e-12,
                &format!("InverseGaussian({mu}).kurtosis vs 15·mu"),
            );
            // Also confirm the closed-form formula is used.
            assert_close(dist.skewness(), 3.0 * mu.sqrt(), 1e-15, "skew formula");
            assert_close(dist.kurtosis(), 15.0 * mu, 1e-15, "kurt formula");
        }
    }

    #[test]
    fn wald_alias_pdf_cdf_match_scipy() {
        // /porting-to-rust [frankenscipy-lf798]: Wald is pub type
        // alias for InverseGaussian (line 7751), so the canonical
        // parameterless usage is `Wald::new(1.0)`. Pin scipy.stats.wald
        // pdf and cdf reference values:
        //   wald.pdf(1) = 1/√(2π) ≈ 0.39894
        //   wald.cdf(1) ≈ 0.66810
        let w = Wald::new(1.0);
        assert_close(
            w.pdf(1.0),
            0.398_942_280_401_432_7,
            1e-12,
            "Wald.pdf(1) = 1/√(2π)",
        );
        assert_close(
            w.cdf(1.0),
            0.668_102_001_223_170_6,
            1e-9,
            "Wald.cdf(1) ≈ 0.6681",
        );
        // Outside support
        assert_eq!(w.pdf(-0.1), 0.0);
        assert_eq!(w.pdf(0.0), 0.0);
        assert_eq!(w.cdf(0.0), 0.0);
    }

    #[test]
    fn skewnorm_reflection_identity() {
        // /testing-metamorphic for [frankenscipy-kj72r]: textbook
        // reflection of the skew-normal distribution. If
        // Y ~ SkewNorm(-a) then -Y ~ SkewNorm(a), so:
        //   SkewNorm(-a).pdf(x) = SkewNorm(a).pdf(-x)
        //   SkewNorm(-a).cdf(x) = SkewNorm(a).sf(-x)
        // Independent verification: pdf goes through 2·φ(x)·Φ(a·x);
        // cdf goes through Φ(x) − 2·T(x, a) and the reflection
        // depends on T(h, -a) = -T(h, a) and T(-h, a) = -T(h, a)
        // — Owen's T anti-symmetry properties.
        for &a in &[0.5_f64, 1.5, 5.0, 10.0] {
            let plus = SkewNorm::new(a);
            let minus = SkewNorm::new(-a);
            for &x in &[-3.0_f64, -1.0, -0.1, 0.0, 0.1, 1.0, 3.0] {
                assert_close(
                    minus.pdf(x),
                    plus.pdf(-x),
                    1e-12,
                    &format!("SkewNorm(-{a}).pdf({x}) vs SkewNorm({a}).pdf({})", -x),
                );
                assert_close(
                    minus.cdf(x),
                    plus.sf(-x),
                    1e-9,
                    &format!("SkewNorm(-{a}).cdf({x}) vs SkewNorm({a}).sf({})", -x),
                );
            }
        }
    }

