    #[test]
    fn laplace_asymmetric_pdf_cdf_match_scipy() {
        // Exact scipy.stats.laplace_asymmetric(kappa=2). The suite covers entropy
        // and skew/kurt but no exact pdf/cdf. pdf(1) (fast right decay) and pdf(-1)
        // (slow left decay) exercise the asymmetric branches.
        let l = LaplaceAsymmetric::new(2.0);
        assert!((l.pdf(0.0) - 0.4).abs() < 1e-12, "pdf(0) peak");
        assert!(
            (l.pdf(1.0) - 0.054_134_113_294_645_08).abs() < 1e-12,
            "pdf(1) right"
        );
        assert!(
            (l.pdf(-1.0) - 0.242_612_263_885_053_36).abs() < 1e-12,
            "pdf(-1) left"
        );
        assert!(
            (l.cdf(0.0) - 0.8).abs() < 1e-12,
            "cdf(0)=kappa^2/(1+kappa^2)"
        );
    }

    #[test]
    fn laplace_asymmetric_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.laplace_asymmetric(κ).stats(moments='sk').
        // κ = 1 is the symmetric Laplace (skew = 0, ex.kurt = 3).
        // κ and 1/κ produce skew with opposite signs and identical kurt.
        let cases = [
            (0.5_f64, 1.797_616_985_633, 5.335_640_138_4),
            (1.0, 0.0, 3.0),
            (2.0, -1.797_616_985_633, 5.335_640_138_4),
            (3.0, -1.960_832_950_796, 5.855_443_188_6),
        ];
        for &(k, sk, ku) in &cases {
            let d = LaplaceAsymmetric::new(k);
            assert_close(
                d.skewness(),
                sk,
                1e-9,
                &format!("LaplaceAsymmetric({k}) skew"),
            );
            assert_close(
                d.kurtosis(),
                ku,
                1e-8,
                &format!("LaplaceAsymmetric({k}) kurt"),
            );
        }
    }

    #[test]
    fn laplace_ppf_roundtrip() {
        let l = Laplace::new(3.0, 2.0);
        for q in [0.1, 0.25, 0.5, 0.75, 0.9] {
            let x = l.ppf(q);
            assert_close(l.cdf(x), q, 1e-10, &format!("Laplace ppf at q={q}"));
        }
    }

    #[test]
    fn laplace_mean_var() {
        let l = Laplace::new(5.0, 3.0);
        assert_close(l.mean(), 5.0, 1e-12, "Laplace mean");
        assert_close(l.var(), 18.0, 1e-12, "Laplace var = 2*scale^2");
    }

    // ── Triangular distribution ───────────────────────────────────

    #[test]
    fn triangular_pdf_cdf_segments_match_scipy() {
        // Exact scipy.stats.triang(c=0.3, loc=0, scale=4) = support [0,4], mode 1.2.
        // triangular_pdf_at_mode only checks the peak; this pins the rising and
        // falling pdf/cdf segments.
        let t = Triangular::new(0.0, 1.2, 4.0);
        assert!(
            (t.pdf(0.5) - 0.208_333_333_333_333_34).abs() < 1e-12,
            "pdf(0.5) rising"
        );
        assert!(
            (t.pdf(3.0) - 0.178_571_428_571_428_58).abs() < 1e-12,
            "pdf(3) falling"
        );
        assert!(
            (t.cdf(0.5) - 0.052_083_333_333_333_336).abs() < 1e-12,
            "cdf(0.5)"
        );
        assert!(
            (t.cdf(3.0) - 0.910_714_285_714_285_7).abs() < 1e-12,
            "cdf(3)"
        );
    }

