    #[test]
    fn test_try_fit_with_audit_emits_on_rejection() {
        // br-egba-3: try_fit_with_audit delegates to try_fit and
        // records an AuditAction::FailClosed on the ledger for every
        // error path. Strict-vs-Hardened distinction does not apply to
        // try_fit (it's non-panicking by design), so emission happens
        // whenever the result is Err.
        let ledger = super::sync_audit_ledger();

        // Success path — no emission.
        let _ = Normal::try_fit_with_audit(&[1.0, 2.0, 3.0], &ledger).expect("clean data must fit");
        assert_eq!(
            ledger.lock().unwrap().len(),
            0,
            "successful fit must not emit"
        );

        // Empty data — exactly one emission.
        let _ = Normal::try_fit_with_audit(&[], &ledger).expect_err("empty must error");
        assert_eq!(
            ledger.lock().unwrap().len(),
            1,
            "InsufficientData must emit once"
        );

        // NaN data — another emission.
        let _ =
            Normal::try_fit_with_audit(&[1.0, f64::NAN, 3.0], &ledger).expect_err("NaN must error");
        assert_eq!(ledger.lock().unwrap().len(), 2, "UnsupportedData must emit");

        // NotImplemented distribution — emits too.
        let r =
            <NoFitDistribution as ContinuousDistribution>::try_fit_with_audit(&[1.0, 2.0], &ledger);
        assert!(matches!(r, Err(FitError::NotImplemented { .. })));
        assert_eq!(ledger.lock().unwrap().len(), 3, "NotImplemented must emit");
    }

    #[test]
    fn test_try_fit_default_returns_not_implemented() {
        // br-d692: distributions without a closed-form MLE override
        // must return FitError::NotImplemented from try_fit rather than
        // panic via the legacy fit() default.
        let data = [1.0, 2.0, 3.0];
        let result = <NoFitDistribution as ContinuousDistribution>::try_fit(&data);
        assert!(
            matches!(result, Err(FitError::NotImplemented { .. })),
            "try_fit default should return NotImplemented"
        );
    }

    #[test]
    fn fit_error_maps_to_structured_stats_error() {
        let fit_error = FitError::NotImplemented {
            distribution: "fsci_stats::Chi",
        };
        assert!(matches!(
            StatsError::from(fit_error),
            StatsError::Unsupported {
                operation: "fit",
                distribution: "fsci_stats::Chi"
            }
        ));

        let fit_error = FitError::InsufficientData {
            required: 2,
            actual: 1,
        };
        assert!(matches!(
            StatsError::from(fit_error),
            StatsError::DataTooSmall {
                required: 2,
                got: 1
            }
        ));
    }

    #[test]
    fn unsupported_distribution_moments_return_typed_errors() {
        // /testing-conformance: verify that the trait's NaN-default
        // skewness/kurtosis/entropy surfaces are correctly translated
        // to typed StatsError::Unsupported by try_*. Use a test-local
        // stub distribution that intentionally does not override any
        // of the three so the trait defaults fire. (History: Chi held
        // this fixture role until frankenscipy-fubyp; GenPareto until
        // frankenscipy-ez5vt; Trapezoid until frankenscipy-gjlms — at
        // this point every concrete distribution in the crate overrides
        // at least one of the three, so the dedicated stub is the only
        // way to exercise the all-three-default path.)
        struct UnsupportedTestDist;
        impl ContinuousDistribution for UnsupportedTestDist {
            fn pdf(&self, _x: f64) -> f64 {
                f64::NAN
            }
            fn cdf(&self, _x: f64) -> f64 {
                f64::NAN
            }
            fn ppf(&self, _q: f64) -> f64 {
                f64::NAN
            }
            fn mean(&self) -> f64 {
                f64::NAN
            }
            fn var(&self) -> f64 {
                f64::NAN
            }
        }

        let dist = UnsupportedTestDist;
        assert!(dist.entropy().is_nan());
        assert!(matches!(
            dist.try_entropy(),
            Err(StatsError::Unsupported {
                operation: "entropy",
                ..
            })
        ));
        assert!(matches!(
            dist.try_skewness(),
            Err(StatsError::Unsupported {
                operation: "skewness",
                ..
            })
        ));
        assert!(matches!(
            dist.try_kurtosis(),
            Err(StatsError::Unsupported {
                operation: "kurtosis",
                ..
            })
        ));
    }

