    #[test]
    fn gengamma_entropy_matches_scipy() {
        // Was NaN (default); closed form h = ln(Γ(a)/|c|) + a − (a − 1/c)·ψ(a).
        // Golden values from scipy.stats.gengamma(a, c).entropy().
        let cases: &[(f64, f64, f64)] = &[
            (2.0, 1.5, 1.030_822_445_1),
            (3.0, 2.0, 0.693_039_162_3),
            (1.5, 0.8, 1.593_238_820_2),
            (4.0, 3.0, 0.087_382_396_3),
            (0.7, 1.2, 0.615_875_882_6),
            (2.5, -1.5, 0.152_555_067_0),
        ];
        for &(a, c, golden) in cases {
            let h = GenGamma::new(a, c).entropy();
            assert!(
                (h - golden).abs() < 1e-9,
                "gengamma({a},{c}).entropy() = {h} vs scipy {golden}"
            );
        }
    }

    #[test]
    fn norminvgauss_excess_kurtosis_matches_scipy() {
        // Regression: NIG excess kurtosis 3(1+4β²/α²)/(δγ) is ALREADY Fisher
        // excess; the old `- 3.0` made it 3 too low (even negative). Golden
        // values from scipy.stats.norminvgauss(a, b).stats('k').
        let cases: &[(f64, f64, f64)] = &[
            (1.0, 0.5, 6.928_203_230_275_509),
            (2.0, 0.5, 1.936_491_673_103_709),
            (3.0, -1.5, 2.309_401_076_758_503),
            (5.0, 0.0, 0.6),
            (1.5, 1.0, 7.453_559_924_999_300),
        ];
        for &(a, b, golden) in cases {
            let k = NormInvGauss::new(a, b).kurtosis();
            assert!(
                (k - golden).abs() < 1e-12,
                "norminvgauss({a},{b}).kurtosis() = {k}, scipy {golden}"
            );
            assert!(k >= -2.0, "excess kurtosis cannot be below -2, got {k}");
        }
    }

    #[test]
    fn norminvgauss_left_tail_cdf_matches_scipy() {
        // Regression (frankenscipy-vk2l2): the cdf integrated [mean−20σ, x], a
        // window independent of x. For x far in the left tail that lower bound sat
        // ABOVE x, inverting the window so the integral clamped to 0 (cdf(-60) = 0
        // vs scipy ~1e-42). The tail now integrates a local window [x−W, x].
        // Values from scipy.stats.norminvgauss 1.17.1 (both quadrature-limited).
        let cases: &[(f64, f64, f64, f64)] = &[
            (1.0, 0.5, -40.0, 2.128_298_309_990_625_8e-29),
            (1.5, 0.0, -60.0, 2.510_706_717_317_211e-42),
            (2.0, -1.0, -60.0, 5.785_042_008_718_4e-29),
            (3.0, 2.0, -20.0, 4.941_324_486_630_686e-46),
        ];
        for &(a, b, x, want) in cases {
            let got = NormInvGauss::new(a, b).cdf(x);
            let rel = (got - want).abs() / want.abs();
            assert!(
                rel < 1e-3,
                "NormInvGauss({a},{b}).cdf({x}) = {got:e}, scipy {want:e} (relerr {rel:e})"
            );
        }
        // Beyond the f64 range the cdf underflows to exactly 0, as scipy returns.
        assert_eq!(NormInvGauss::new(3.0, 2.0).cdf(-300.0), 0.0);
    }

    #[test]
    fn isf_deep_right_tail_matches_scipy() {
        // Regression for the isf-tail audit: `1 - q` underflows to exactly 1.0
        // once q < ~1.1e-16, so the historical `ppf(1 - q)` route returned +inf
        // for every distribution in the deep right tail. The default isf now
        // inverts sf(x) = q directly there. Golden values from
        // scipy.stats.<dist>.isf(q) (SciPy 1.17.1).
        let cases: &[(&str, f64, f64, f64)] = &[
            // (label, our isf, q, scipy golden)
            (
                "norm_1e-30",
                Normal::new(0.0, 1.0).isf(1e-30),
                1e-30,
                1.1464024688442578e1,
            ),
            (
                "norm_1e-100",
                Normal::new(0.0, 1.0).isf(1e-100),
                1e-100,
                2.1273453560964981e1,
            ),
            (
                "expon_1e-100",
                Exponential::new(1.0).isf(1e-100),
                1e-100,
                2.3025850929935905e2,
            ),
            (
                "t5_1e-100",
                StudentT::new(5.0).isf(1e-100),
                1e-100,
                1.5683925590997631e20,
            ),
            (
                "chi2_4_1e-30",
                ChiSquared::new(4.0).isf(1e-30),
                1e-30,
                1.4677366344602950e2,
            ),
            (
                "gamma2_1e-100",
                GammaDist::new(2.0, 1.0).isf(1e-100),
                1e-100,
                2.3572541016191974e2,
            ),
            (
                "cauchy_1e-100",
                Cauchy::new(0.0, 1.0).isf(1e-100),
                1e-100,
                3.1830988618377588e99,
            ),
            (
                "rayleigh_1e-30",
                Rayleigh::new(1.0).isf(1e-30),
                1e-30,
                1.1753940002386489e1,
            ),
            (
                "weibull_1e-100",
                Weibull::new(1.5, 1.0).isf(1e-100),
                1e-100,
                3.7567341186477364e1,
            ),
        ];
        for &(label, ours, _q, golden) in cases {
            assert!(
                ours.is_finite(),
                "{label}: isf must be finite in the deep tail, got {ours}"
            );
            let rel = (ours - golden).abs() / golden.abs();
            assert!(
                rel < 1e-9,
                "{label}: isf {ours} vs scipy {golden} (rel {rel:.3e})"
            );
        }
    }

    #[test]
    fn isf_common_range_unchanged_from_ppf() {
        // Normal isf now uses the symmetric −ndtri(q) form (matching
        // scipy.stats.norm.isf), which is NOT byte-identical to ppf(1−q): the
        // trait default forms 1−q first and ndtri near 1 is ill-conditioned, so
        // the two differ by a few ULPs (and ppf(1−q) was ~4.4e-7 off scipy at
        // q=1e-12). Assert scipy golden isf values instead of self-consistency.
        let n = Normal::new(0.0, 1.0);
        let norm_isf_golden = [
            (1e-6, 4.753424308822899),
            (1e-3, 3.090232306167813),
            (0.1, 1.2815515655446004),
            (0.5, 0.0),
            (0.9, -1.2815515655446004),
            (0.999, -3.090232306167813),
            (0.999_999, -4.753424308817087),
        ];
        for &(q, golden) in &norm_isf_golden {
            let got = n.isf(q);
            let rel = if golden == 0.0 {
                got.abs()
            } else {
                (got - golden).abs() / golden.abs()
            };
            assert!(
                rel < 1e-12,
                "norm isf({q}) = {got} vs scipy {golden} (rel {rel:.3e})"
            );
        }
        // Gamma isf delegates to gammainccinv (matching scipy.stats.gamma.isf),
        // which is NOT byte-identical to ppf(1-q) — scipy itself differs here by
        // ~1e-14 (ppf uses gammaincinv, isf uses gammainccinv). Assert parity
        // against scipy golden isf values instead of the old self-consistency.
        let g = GammaDist::new(2.0, 1.0);
        let gamma_isf_golden = [
            (1e-4, 11.756371222495419),
            (1e-2, 6.638352067993813),
            (0.25, 2.6926345288896956),
            (0.75, 0.961278763114777),
            (0.99, 0.148554740253266),
        ];
        for &(q, golden) in &gamma_isf_golden {
            let rel = (g.isf(q) - golden).abs() / golden.abs();
            assert!(
                rel < 1e-9,
                "gamma isf({q}) = {} vs scipy {golden} (rel {rel:.3e})",
                g.isf(q)
            );
        }
    }

