    #[test]
    fn test_isf_is_inverse_of_sf() {
        let n = Normal::new(0.0, 1.0);
        let q = 0.1;
        let x = n.isf(q);
        let sf_x = n.sf(x);
        // Bisection ppf has limited precision
        assert!(
            (sf_x - q).abs() < 1e-6,
            "isf should satisfy sf(isf(q)) = q; got sf({})={}, expected {}",
            x,
            sf_x,
            q
        );
    }

