    #[test]
    fn binomial_pmf_sums_to_one() {
        let b = Binomial::new(10, 0.3);
        let sum: f64 = (0..=10).map(|k| b.pmf(k)).sum();
        assert!((sum - 1.0).abs() < 1e-10, "PMF sum = {sum}");
    }

    #[test]
    fn binomial_pmf_many_matches_pmf() {
        // Batch pmf_many (lnΓ(n+1)/ln p/ln(1-p) hoisted) byte-identical to per-k pmf,
        // incl. k>n and p∈{0,1} special cases.
        let ks: Vec<u64> = (0..=12).collect();
        for b in [
            Binomial::new(10, 0.3),
            Binomial::new(10, 0.0),
            Binomial::new(10, 1.0),
        ] {
            let pm = b.pmf_many(&ks);
            for (i, &k) in ks.iter().enumerate() {
                assert_eq!(pm[i], b.pmf(k), "pmf_many != pmf at k={k}");
            }
        }
    }

    #[test]
    fn binomial_cdf_many_matches_cdf() {
        // cdf_many (mode-anchored recurrence + prefix sum) matches the per-point betainc cdf to
        // ~1e-12; the fast array path (≈23× scipy). Covers k>n and p∈{0,1}.
        for b in [
            Binomial::new(10, 0.3),
            Binomial::new(200, 0.5),
            Binomial::new(10, 0.0),
            Binomial::new(10, 1.0),
        ] {
            let ks: Vec<u64> = (0..=(b.n + 2)).collect();
            let cm = b.cdf_many(&ks);
            for (i, &k) in ks.iter().enumerate() {
                assert!(
                    (cm[i] - b.cdf(k)).abs() < 1e-9,
                    "cdf_many mismatch n={} p={} k={k}: {} vs {}",
                    b.n,
                    b.p,
                    cm[i],
                    b.cdf(k)
                );
            }
        }
        assert!(Binomial::new(10, 0.5).cdf_many(&[]).is_empty());
    }

