    #[test]
    fn fisher_exact_independent_table() {
        // Independent: [[10, 10], [10, 10]] → p ≈ 1
        let result = fisher_exact(&[[10.0, 10.0], [10.0, 10.0]]);
        assert!(
            (result.odds_ratio - 1.0).abs() < 1e-10,
            "OR should be 1: {}",
            result.odds_ratio
        );
        assert!(
            result.pvalue > 0.9,
            "independent p should be ~1: {}",
            result.pvalue
        );
    }

    #[test]
    fn fisher_exact_dependent_table() {
        // Strongly dependent: [[8, 2], [1, 9]]
        let result = fisher_exact(&[[8.0, 2.0], [1.0, 9.0]]);
        assert!(
            result.odds_ratio > 10.0,
            "OR should be large: {}",
            result.odds_ratio
        );
        assert!(
            result.pvalue < 0.01,
            "dependent p should be small: {}",
            result.pvalue
        );
    }

    #[test]
    fn fisher_exact_known_value() {
        // Classic example: [[1, 9], [11, 3]]
        // SciPy: fisher_exact([[1,9],[11,3]]) → odds_ratio ≈ 0.0303, p ≈ 0.0014
        let result = fisher_exact(&[[1.0, 9.0], [11.0, 3.0]]);
        assert!(
            result.odds_ratio < 0.1,
            "OR should be small: {}",
            result.odds_ratio
        );
        assert!(
            result.pvalue < 0.01,
            "p should be very small: {}",
            result.pvalue
        );
    }

    #[test]
    fn fisher_exact_zero_cell() {
        // Table with zero: [[0, 5], [5, 0]]
        let result = fisher_exact(&[[0.0, 5.0], [5.0, 0.0]]);
        assert!(result.pvalue < 0.05, "p should be small: {}", result.pvalue);
    }

    // ── barnard_exact tests ────────────────────────────────────────────

    #[test]
    fn barnard_exact_significant_difference() {
        // Treatment vs control with clear difference
        // Treatment: 8 successes, 2 failures
        // Control: 2 successes, 8 failures
        let table = [[8, 2], [2, 8]];
        let result = barnard_exact(&table);

        assert!(result.statistic.abs() > 0.0, "statistic should be non-zero");
        assert!(
            result.pvalue < 0.05,
            "p-value {} should be significant",
            result.pvalue
        );
    }

    #[test]
    fn barnard_exact_no_difference() {
        // Similar proportions
        let table = [[5, 5], [5, 5]];
        let result = barnard_exact(&table);

        assert!(
            result.pvalue > 0.1,
            "p-value {} should not be significant for equal proportions",
            result.pvalue
        );
    }

    #[test]
    fn barnard_exact_alternative_greater() {
        // Clear greater effect
        let table = [[9, 1], [1, 9]];
        let result = barnard_exact_alternative(&table, "greater");

        assert!(result.statistic > 0.0);
        assert!(
            result.pvalue < 0.05,
            "one-sided p-value should be significant"
        );
    }

    #[test]
    fn barnard_exact_alternative_less() {
        // Clear less effect
        let table = [[1, 9], [9, 1]];
        let result = barnard_exact_alternative(&table, "less");

        assert!(result.statistic < 0.0);
        assert!(
            result.pvalue < 0.05,
            "one-sided p-value should be significant"
        );
    }

    #[test]
    fn barnard_exact_empty_row() {
        // Empty success row matches SciPy: zero statistic and p-value 1.
        let table = [[0, 0], [5, 5]];
        let result = barnard_exact(&table);
        assert_eq!(result.statistic, 0.0);
        assert_eq!(result.pvalue, 1.0);
    }

