    // ── gstd tests ────────────────────────────────────────────────────

    #[test]
    fn gstd_basic() {
        // gstd([1, 2, 4, 8]) = exp(std(log([1,2,4,8])))
        let data = vec![1.0, 2.0, 4.0, 8.0];
        let result = gstd(&data);
        // log values: [0, 0.693, 1.386, 2.079] - mean = 1.04, std ≈ 0.9
        assert!(result > 1.0, "gstd should be > 1 for spread data");
        assert!(result < 5.0, "gstd should be reasonable");
    }

    #[test]
    fn gstd_constant() {
        // All same values → std of logs = 0 → gstd = 1
        let data = vec![5.0, 5.0, 5.0, 5.0];
        let result = gstd(&data);
        assert!((result - 1.0).abs() < 1e-10, "gstd of constant should be 1");
    }

    #[test]
    fn gstd_negative_returns_nan() {
        let data = vec![1.0, -2.0, 3.0];
        assert!(gstd(&data).is_nan(), "negative values should return NaN");
    }

    #[test]
    fn gstd_empty_returns_nan() {
        assert!(gstd(&[]).is_nan());
    }

    #[test]
    fn gstd_single_element_returns_nan() {
        assert!(gstd(&[5.0]).is_nan(), "need at least 2 elements for std");
    }

    // ── percentileofscore tests ──────────────────────────────────────

    #[test]
    fn percentileofscore_rank() {
        let data = vec![1.0, 2.0, 3.0, 4.0];
        // scipy 'rank' for score=3 with left=2, right=3, plus1=1:
        // (2 + 3 + 1) * 50 / 4 = 75
        let result = percentileofscore(&data, 3.0, None);
        assert!((result - 75.0).abs() < 1e-10, "rank method: {}", result);
    }

    #[test]
    fn percentileofscore_weak() {
        let data = vec![1.0, 2.0, 3.0, 4.0];
        // scipy 'weak' = % values <= score. For score=3: 3/4 = 75%
        let result = percentileofscore(&data, 3.0, Some("weak"));
        assert!((result - 75.0).abs() < 1e-10, "weak method: {}", result);
    }

    #[test]
    fn percentileofscore_strict() {
        let data = vec![1.0, 2.0, 3.0, 4.0];
        // scipy 'strict' = % values < score. For score=3: 2/4 = 50%
        let result = percentileofscore(&data, 3.0, Some("strict"));
        assert!((result - 50.0).abs() < 1e-10, "strict method: {}", result);
    }

    #[test]
    fn percentileofscore_mean() {
        let data = vec![1.0, 2.0, 3.0, 4.0];
        // Average of weak (50) and strict (75) = 62.5
        let result = percentileofscore(&data, 3.0, Some("mean"));
        assert!((result - 62.5).abs() < 1e-10, "mean method: {}", result);
    }

    #[test]
    fn percentileofscore_empty() {
        assert!(percentileofscore(&[], 5.0, None).is_nan());
    }

    #[test]
    fn percentileofscore_below_all() {
        let data = vec![10.0, 20.0, 30.0];
        let result = percentileofscore(&data, 5.0, Some("strict"));
        assert!((result - 0.0).abs() < 1e-10, "below all: {}", result);
    }

    #[test]
    fn percentileofscore_above_all() {
        let data = vec![10.0, 20.0, 30.0];
        let result = percentileofscore(&data, 50.0, Some("strict"));
        assert!((result - 100.0).abs() < 1e-10, "above all: {}", result);
    }

    #[test]
    fn percentileofscore_no_double_count_near_equal() {
        // 0.1 + 0.2 != 0.3 but they are within f64::EPSILON. A tolerance-based
        // equality check would count 0.3 as both "< score" and "== score",
        // pushing right above n. scipy uses exact comparisons.
        let score = 0.1 + 0.2; // 0.30000000000000004
        let data = vec![0.3, score];
        // 0.3 < score (strict): 1/2 = 50%
        assert!((percentileofscore(&data, score, Some("strict")) - 50.0).abs() < 1e-10);
        // values <= score (weak): both -> 2/2 = 100%
        assert!((percentileofscore(&data, score, Some("weak")) - 100.0).abs() < 1e-10);
        // rank: left=1, right=2, plus1=1 -> (1+2+1)*50/2 = 100
        assert!((percentileofscore(&data, score, None) - 100.0).abs() < 1e-10);
    }

