    #[test]
    #[ignore = "timing only; run with --ignored --nocapture --release"]
    fn pairwise_distance_matrix_parallel_speedup() {
        let n = 2000usize;
        let d = 16usize;
        let data: Vec<Vec<f64>> = (0..n)
            .map(|i| {
                (0..d)
                    .map(|j| (i as f64 * 0.013 + j as f64 * 0.7).sin())
                    .collect()
            })
            .collect();
        let seq_ref = |data: &[Vec<f64>]| -> Vec<Vec<f64>> {
            let n = data.len();
            let mut m = vec![vec![0.0; n]; n];
            for i in 0..n {
                for j in (i + 1)..n {
                    let dist = data[i]
                        .iter()
                        .zip(data[j].iter())
                        .map(|(l, r)| {
                            let x = l - r;
                            x * x
                        })
                        .sum::<f64>()
                        .sqrt();
                    m[i][j] = dist;
                    m[j][i] = dist;
                }
            }
            m
        };
        let t0 = std::time::Instant::now();
        let par = pairwise_euclidean_distance_matrix(&data);
        let tp = t0.elapsed().as_secs_f64() * 1e3;
        let t1 = std::time::Instant::now();
        let seq = seq_ref(&data);
        let ts = t1.elapsed().as_secs_f64() * 1e3;
        assert_eq!(par.len(), seq.len());
        println!(
            "pairwise n={n} d={d}: seq={ts:.3}ms par={tp:.3}ms speedup={:.2}x",
            ts / tp
        );
    }

    #[test]
    fn pairwise_distance_matrix_parallel_is_bit_identical() {
        // n=300, d=8 => n*n*d = 720k >= the 2^18 gate -> the threaded path runs.
        let data: Vec<Vec<f64>> = (0..300)
            .map(|i| {
                (0..8)
                    .map(|j| (i as f64 * 0.013 + j as f64 * 0.7).sin())
                    .collect()
            })
            .collect();
        let got = pairwise_euclidean_distance_matrix(&data);
        // Verbatim sequential upper-triangle-and-mirror reference.
        let n = data.len();
        let mut want = vec![vec![0.0; n]; n];
        for i in 0..n {
            for j in (i + 1)..n {
                let dist = data[i]
                    .iter()
                    .zip(data[j].iter())
                    .map(|(l, r)| {
                        let d = l - r;
                        d * d
                    })
                    .sum::<f64>()
                    .sqrt();
                want[i][j] = dist;
                want[j][i] = dist;
            }
        }
        assert_eq!(got.len(), n);
        for i in 0..n {
            for j in 0..n {
                assert_eq!(
                    got[i][j].to_bits(),
                    want[i][j].to_bits(),
                    "pairwise distance mismatch at ({i},{j})"
                );
            }
        }
    }

    #[test]
    fn multiscale_graphcorr_mgc_map_matches_on4_reference() {
        // Isomorphism oracle: the O(n^2) prefix-sum compute_mgc_map must match the
        // direct O(n^4) per-scale local_correlation map to tolerance on every cell.
        for &n in &[12usize, 37, 64] {
            let x: Vec<Vec<f64>> = (0..n)
                .map(|i| {
                    vec![
                        (i as f64 * 0.31).sin(),
                        (i as f64 * 0.07 + 1.3).cos(),
                        ((i * i) as f64 * 0.013).sin(),
                    ]
                })
                .collect();
            let y: Vec<Vec<f64>> = (0..n)
                .map(|i| vec![(i as f64 * 0.19 + 0.5).cos(), (i as f64 * 0.23).sin()])
                .collect();
            let dist_x = pairwise_euclidean_distance_matrix(&x);
            let dist_y = pairwise_euclidean_distance_matrix(&y);
            let rank_x = compute_row_ranks(&dist_x);
            let rank_y = compute_row_ranks(&dist_y);
            let cx = double_center_distance_matrix(&dist_x);
            let cy = double_center_distance_matrix(&dist_y);

            let fast = compute_mgc_map(&cx, &cy, &rank_x, &rank_y, n);
            let mut reference = vec![vec![0.0; n]; n];
            for k in 1..=n {
                for l in 1..=n {
                    reference[k - 1][l - 1] =
                        local_correlation(&cx, &cy, &rank_x, &rank_y, k, l, n);
                }
            }
            let mut max_abs = 0.0_f64;
            for k in 0..n {
                for l in 0..n {
                    max_abs = max_abs.max((fast[k][l] - reference[k][l]).abs());
                }
            }
            assert!(
                max_abs < 1e-12,
                "n={n}: prefix-sum mgc_map deviates from O(n^4) reference by {max_abs:e}"
            );
        }
    }

    #[test]
    fn multiscale_graphcorr_permutation_view_matches_materialized_map_bits() {
        let n = 17usize;
        let x: Vec<Vec<f64>> = (0..n)
            .map(|i| vec![(i as f64 * 0.31).sin(), (i as f64 * 0.13 + 0.2).cos()])
            .collect();
        let y: Vec<Vec<f64>> = (0..n)
            .map(|i| {
                vec![
                    (i as f64 * 0.19 + 0.5).cos(),
                    ((i * i + 3) as f64 * 0.017).sin(),
                ]
            })
            .collect();
        let dist_x = pairwise_euclidean_distance_matrix(&x);
        let dist_y = pairwise_euclidean_distance_matrix(&y);
        let rank_x = compute_row_ranks(&dist_x);
        let rank_y = compute_row_ranks(&dist_y);
        let cx = double_center_distance_matrix(&dist_x);
        let cy = double_center_distance_matrix(&dist_y);
        let perm: Vec<usize> = (0..n).map(|i| (i * 7 + 3) % n).collect();

        let perm_cy = permute_matrix(&cy, &perm);
        let perm_rank_y = permute_matrix_usize(&rank_y, &perm);
        let materialized = compute_mgc_map(&cx, &perm_cy, &rank_x, &perm_rank_y, n);
        let viewed = compute_mgc_map_permuted_y(&cx, &cy, &rank_x, &rank_y, &perm, n);

        for k in 0..n {
            for l in 0..n {
                assert_eq!(
                    viewed[k][l].to_bits(),
                    materialized[k][l].to_bits(),
                    "permutation-view MGC map mismatch at ({k},{l})"
                );
            }
        }
    }

    #[test]
    fn multiscale_graphcorr_tracks_perfect_linear_relationship() {
        let x: Vec<Vec<f64>> = (0..8).map(|i| vec![i as f64]).collect();
        let y: Vec<Vec<f64>> = (0..8).map(|i| vec![2.0 * i as f64 + 1.0]).collect();
        let result = multiscale_graphcorr(&x, &y, 0, Some(0)).expect("multiscale_graphcorr");
        assert!(
            result.statistic > 0.99,
            "MGC statistic for perfect linear = {}",
            result.statistic
        );
        assert_eq!(result.pvalue, 1.0, "reps=0 should match SciPy");
        // Full implementation returns n×n mgc_map
        assert_eq!(result.mgc_map.len(), 8);
        assert_eq!(result.mgc_map[0].len(), 8);
        // Optimal scale should be valid
        assert!(result.opt_scale.0 >= 1 && result.opt_scale.0 <= 8);
        assert!(result.opt_scale.1 >= 1 && result.opt_scale.1 <= 8);
        // Statistic should match mgc_map at optimal scale
        let (k, l) = result.opt_scale;
        assert_close(
            result.mgc_map[k - 1][l - 1],
            result.statistic,
            1e-12,
            "mgc_map at opt_scale should equal statistic",
        );
    }

