    // ── VonMises tests ───────────────────────────────────────────────

    #[test]
    fn vonmises_pdf_integrates_to_one() {
        // Numerically integrate von Mises PDF over [-π, π]
        let vm = VonMises::new(2.0, 0.0);
        let n = 1000;
        let h = 2.0 * std::f64::consts::PI / n as f64;
        let mut integral = 0.0;
        for i in 0..n {
            let x = -std::f64::consts::PI + (i as f64 + 0.5) * h;
            integral += vm.pdf(x) * h;
        }
        assert!(
            (integral - 1.0).abs() < 0.01,
            "vonmises integral = {integral}"
        );
    }

    #[test]
    fn vonmises_peak_at_mu() {
        let vm = VonMises::new(5.0, 1.0);
        let at_mu = vm.pdf(1.0);
        let away = vm.pdf(1.0 + 1.0);
        assert!(at_mu > away, "peak should be at mu");
    }

    #[test]
    fn vonmises_circular_variance() {
        // High kappa → low variance
        let vm_high = VonMises::new(100.0, 0.0);
        let vm_low = VonMises::new(0.5, 0.0);
        assert!(
            vm_high.circular_variance() < vm_low.circular_variance(),
            "high kappa should have lower variance"
        );
    }

    // ── MultivariateNormal tests ─────────────────────────────────────

    #[test]
    fn mvn_1d_matches_normal() {
        let mvn = MultivariateNormal::new(&[0.0], &[vec![1.0]]).expect("1D MVN");
        let norm = Normal::standard();
        let x = 1.5;
        let mvn_pdf = mvn.pdf(&[x]).expect("mvn pdf");
        let norm_pdf = norm.pdf(x);
        assert!(
            (mvn_pdf - norm_pdf).abs() < 1e-10,
            "1D MVN should match Normal: {} vs {}",
            mvn_pdf,
            norm_pdf
        );
    }

    #[test]
    fn mvn_peak_at_mean() {
        let mvn =
            MultivariateNormal::new(&[1.0, 2.0], &[vec![1.0, 0.0], vec![0.0, 1.0]]).expect("MVN");
        let at_mean = mvn.pdf(&[1.0, 2.0]).expect("pdf at mean");
        let away = mvn.pdf(&[3.0, 4.0]).expect("pdf away");
        assert!(at_mean > away, "peak should be at mean");
    }

    #[test]
    fn mvn_logpdf_consistent() {
        let mvn =
            MultivariateNormal::new(&[0.0, 0.0], &[vec![1.0, 0.0], vec![0.0, 1.0]]).expect("MVN");
        let x = [1.0, 1.0];
        let pdf = mvn.pdf(&x).expect("pdf");
        let logpdf = mvn.logpdf(&x).expect("logpdf");
        assert!(
            (pdf.ln() - logpdf).abs() < 1e-10,
            "ln(pdf) = {}, logpdf = {}",
            pdf.ln(),
            logpdf
        );
    }

    #[test]
    fn inverse_gamma_pdf_cdf() {
        let ig = InverseGamma::new(3.0);
        assert!(ig.pdf(1.0) > 0.0);
        assert!(ig.pdf(-1.0) == 0.0);
        let c = ig.cdf(1.0);
        assert!(c > 0.0 && c < 1.0);
        assert!((ig.mean() - 0.5).abs() < 1e-10); // 1/(a-1) = 1/2
    }

    /// Exact scipy goldens for InverseGamma pdf/cdf (frankenscipy-o88es).
    ///
    /// `inverse_gamma_pdf_cdf` above is positivity-only — `pdf(1.0) > 0.0` and
    /// `cdf(1.0)` merely inside (0, 1) — and the rest of the suite is skew /
    /// kurtosis / fit. A wrong normalizing constant, or a `1/x` vs `x` slip in
    /// the exponent, keeps the density positive and the cdf inside the unit
    /// interval, so nothing here would have caught it.
    ///
    /// Three shapes: a=3.0 (the value already used above, so the weak assertion
    /// and the exact one cover the same object), a=0.8 (a < 1, where the mean
    /// does not exist and the density is heaviest), and a=5.5 (non-integer,
    /// exercising the gamma-function path rather than a factorial shortcut).
    ///
    /// Reference values from scipy.stats.invgamma(a), SciPy 1.17.1.
    #[test]
    fn inverse_gamma_pdf_cdf_match_scipy() {
        // (a, x, pdf, cdf)
        let cases = [
            (3.0, 0.2, 2.105_608_437_214_207_7, 0.124_652_019_483_081_08),
            (3.0, 0.5, 1.082_682_265_892_901_4, 0.676_676_416_183_063_4),
            (3.0, 1.0, 0.183_939_720_585_721_14, 0.919_698_602_928_605_8),
            (3.0, 2.5, 0.008_580_096_589_256_177, 0.992_073_668_132_746_1),
            (
                0.8,
                0.2,
                0.104_866_052_255_464_86,
                0.004_055_854_936_126_715,
            ),
            (0.8, 0.5, 0.404_786_806_818_339_2, 0.094_289_999_109_381_16),
            (0.8, 1.0, 0.315_985_270_633_835_1, 0.281_429_292_237_066_8),
            (0.8, 2.5, 0.110_650_023_979_159, 0.565_142_359_091_382_9),
            (5.5, 0.2, 4.497_548_466_941_972, 0.530_387_151_001_040_5),
            (5.5, 0.5, 0.234_017_988_188_379, 0.969_917_023_878_774),
            (5.5, 1.0, 0.007_028_275_088_602_66, 0.998_495_881_717_416_2),
            (5.5, 2.5, 3.317_534_014_320_328e-5, 0.999_983_940_395_056_4),
        ];
        for (a, x, want_pdf, want_cdf) in cases {
            let dist = InverseGamma::new(a);
            let got_pdf = dist.pdf(x);
            let got_cdf = dist.cdf(x);
            let rel_pdf = (got_pdf - want_pdf).abs() / want_pdf.abs();
            let rel_cdf = (got_cdf - want_cdf).abs() / want_cdf.abs();
            assert!(
                rel_pdf <= 1e-12,
                "invgamma({a}).pdf({x}): got {got_pdf}, scipy {want_pdf} (rel {rel_pdf:.3e})"
            );
            assert!(
                rel_cdf <= 1e-12,
                "invgamma({a}).cdf({x}): got {got_cdf}, scipy {want_cdf} (rel {rel_cdf:.3e})"
            );
        }
    }

    #[test]
    fn inverse_gamma_fit_recovers_unit_scale_shape_from_mean() {
        let data = [0.25, 0.5, 0.75, 0.5];
        let fit = InverseGamma::try_fit(&data).expect("InverseGamma fit");
        assert_close(fit.a, 3.0, 1e-12, "InverseGamma shape from MoM");
        assert_close(fit.mean(), 0.5, 1e-12, "InverseGamma fitted mean");
    }

    #[test]
    fn inverse_gamma_fit_rejects_too_few_samples() {
        let err = InverseGamma::try_fit(&[1.0]).expect_err("too few samples");
        assert!(matches!(
            err,
            FitError::InsufficientData {
                required: 2,
                actual: 1
            }
        ));
    }

    #[test]
    fn inverse_gamma_fit_rejects_non_positive_or_non_finite_data() {
        for data in [[0.5, 0.0], [0.5, -0.25], [0.5, f64::NAN]] {
            let err = InverseGamma::try_fit(&data).expect_err("invalid sample");
            assert!(matches!(err, FitError::UnsupportedData(_)));
        }
    }

    #[test]
    fn burr12_variance_matches_scipy_reference_values() {
        let cases = [
            (
                (2.0, 3.0),
                (0.589_048_622_548_086_1, 0.153_021_720_274_202_2),
            ),
            (
                (3.0, 2.5),
                (0.727_057_387_946_532_4, 0.110_180_038_392_808_1),
            ),
            (
                (1.5, 4.0),
                (0.417_994_915_214_470_2, 0.123_848_047_436_612_57),
            ),
        ];

        for &((c, d), (mean, var)) in &cases {
            let dist = Burr12::new(c, d);
            assert_close(dist.mean(), mean, 1e-12, "Burr12 mean");
            assert_close(dist.var(), var, 1e-12, "Burr12 variance");
        }
    }

    #[test]
    fn burr12_variance_returns_nan_at_boundary_or_below() {
        assert!(Burr12::new(1.0, 2.0).var().is_nan());
        assert!(Burr12::new(1.5, 4.0 / 3.0).var().is_nan());
    }

    #[test]
    fn burr12_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.burr12(c,d).stats(moments='sk'). All three pairs
        // satisfy cd > 4, so both skew and kurt are finite.
        let cases = [
            (
                3.0_f64,
                2.0_f64,
                1.589_129_215_278_277,
                7.809_454_279_195_59,
            ),
            (5.0, 2.5, 0.410_961_549_738_197, 0.835_278_120_074_757),
            (2.0, 5.0, 1.217_523_220_929_712, 2.831_776_827_387_073),
        ];
        for &(c, d, s, k) in &cases {
            let dist = Burr12::new(c, d);
            assert_close(dist.skewness(), s, 1e-9, &format!("Burr12({c},{d}) skew"));
            assert_close(dist.kurtosis(), k, 1e-8, &format!("Burr12({c},{d}) kurt"));
        }
    }

    #[test]
    fn burr12_skewness_and_kurtosis_nan_at_boundary() {
        // cd ≤ 3 ⇒ skew NaN; cd ≤ 4 ⇒ kurt NaN.
        assert!(Burr12::new(1.5, 2.0).skewness().is_nan()); // cd = 3
        assert!(Burr12::new(1.0, 2.5).skewness().is_nan()); // cd = 2.5
        assert!(Burr12::new(2.0, 2.0).kurtosis().is_nan()); // cd = 4
        assert!(Burr12::new(1.5, 2.0).kurtosis().is_nan()); // cd = 3
    }

