    #[test]
    fn invweibull_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.invweibull(c).stats(moments='sk'). Skew is finite
        // only for c > 3; kurt only for c > 4.
        let cases = [
            (5.0_f64, 3.535_071_604_621_325, 45.091_512_125_815_46),
            (7.0, 2.425_096_816_498_218, 14.534_020_499_272_5),
            (10.0, 1.910_339_134_169_258, 7.978_566_239_345_092),
        ];
        for &(c, s, k) in &cases {
            let d = InvWeibull::new(c);
            assert_close(d.skewness(), s, 1e-9, &format!("InvWeibull({c}) skew"));
            assert_close(d.kurtosis(), k, 1e-8, &format!("InvWeibull({c}) kurt"));
        }
    }

    #[test]
    fn invweibull_skewness_and_kurtosis_nan_at_boundary() {
        // c = 3 makes Γ(1 − 3/c) = Γ(0) — undefined; skew diverges.
        assert!(InvWeibull::new(3.0).skewness().is_nan());
        assert!(InvWeibull::new(2.5).skewness().is_nan());
        // c = 4 makes Γ(1 − 4/c) diverge; kurt undefined.
        assert!(InvWeibull::new(4.0).kurtosis().is_nan());
        assert!(InvWeibull::new(3.5).kurtosis().is_nan());
    }

    #[test]
    fn doubleweibull_pdf_cdf_match_scipy() {
        // Exact scipy.stats.dweibull(c=2). The DoubleWeibull suite covers entropy,
        // ppf, and skew/kurt but no exact pdf/cdf at a point (the dist is symmetric).
        let w = DoubleWeibull::new(2.0);
        assert!(
            (w.pdf(0.5) - 0.389_400_391_535_702_44).abs() < 1e-12,
            "pdf(0.5)"
        );
        assert!(
            (w.pdf(-1.0) - 0.367_879_441_171_442_33).abs() < 1e-12,
            "pdf(-1) neg branch"
        );
        assert!(
            (w.cdf(0.5) - 0.610_599_608_464_297_5).abs() < 1e-12,
            "cdf(0.5)"
        );
    }

    #[test]
    fn doubleweibull_ppf_matches_scipy_reference_values() {
        let dist = DoubleWeibull::new(2.5);
        let qs = [0.001, 0.1, 0.25, 0.5, 0.75, 0.9, 0.999];
        let expected = [
            -2.076_660_482_588_982_5,
            -1.209_677_745_531_848_8,
            -0.863_634_900_602_374_8,
            0.0,
            0.863_634_900_602_374_8,
            1.209_677_745_531_848_8,
            2.076_660_482_588_982_5,
        ];

        assert!(dist.ppf(0.0).is_infinite() && dist.ppf(0.0).is_sign_negative());
        assert!(dist.ppf(1.0).is_infinite() && dist.ppf(1.0).is_sign_positive());

        for (&q, &want) in qs.iter().zip(expected.iter()) {
            assert_close(dist.ppf(q), want, 1e-12, &format!("DoubleWeibull ppf({q})"));
        }
    }

    #[test]
    fn doubleweibull_skewness_and_kurtosis_match_scipy_reference_values() {
        // Symmetric ⇒ skew = 0 for all c. Excess kurt = Γ(1+4/c)/Γ(1+2/c)² − 3.
        let cases = [
            (1.0_f64, 0.0, 3.000_000_000_000_000),
            (1.5, 0.0, -0.169_766_598_184_202),
            (3.0, 0.0, -1.539_001_513_793_682),
            (5.0, 0.0, -1.816_895_453_157_078),
        ];
        for &(c, sk, ku) in &cases {
            let d = DoubleWeibull::new(c);
            assert_close(d.skewness(), sk, 1e-12, &format!("DoubleWeibull({c}) skew"));
            assert_close(d.kurtosis(), ku, 1e-12, &format!("DoubleWeibull({c}) kurt"));
        }
    }

