    #[test]
    fn tukey_lambda_variance_returns_nan_when_undefined() {
        assert!(TukeyLambda::new(-0.5).var().is_nan());
        assert!(TukeyLambda::new(-0.75).var().is_nan());
    }

    #[test]
    fn tukey_lambda_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.tukeylambda(λ).stats(moments='sk'). Symmetric ⇒
        // skew = 0 for all λ. Even moments via the binomial expansion
        // of (q^λ − (1−q)^λ)^4 / λ^4 integrated against Beta kernels.
        let cases = [
            (-0.2_f64, 0.0, 19.212_645_820_4),
            (-0.1, 0.0, 3.785_595_203_5),
            (0.0, 0.0, 1.2),
            (0.5, 0.0, -0.918_303_566_4),
            (1.0, 0.0, -1.2),
        ];
        for &(lam, sk, ku) in &cases {
            let d = TukeyLambda::new(lam);
            assert_close(d.skewness(), sk, 1e-12, &format!("TukeyLambda({lam}) skew"));
            assert_close(d.kurtosis(), ku, 1e-7, &format!("TukeyLambda({lam}) kurt"));
        }
    }

    #[test]
    fn tukey_lambda_kurtosis_returns_nan_when_undefined() {
        // m_4 requires λ > −1/4; below that the (4λ + 1)⁻¹ term
        // diverges and kurt is NaN.
        assert!(TukeyLambda::new(-0.25).kurtosis().is_nan());
        assert!(TukeyLambda::new(-0.5).kurtosis().is_nan());
    }

    fn legacy_tukey_lambda_cdf(dist: &TukeyLambda, x: f64) -> f64 {
        let mut lo = 0.0f64;
        let mut hi = 1.0f64;
        for _ in 0..60 {
            let mid = (lo + hi) / 2.0;
            let q = dist.ppf(mid);
            if q < x {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        (lo + hi) / 2.0
    }

    fn legacy_tukey_lambda_pdf(dist: &TukeyLambda, x: f64) -> f64 {
        let h = 1e-7;
        let c1 = legacy_tukey_lambda_cdf(dist, x + h);
        let c0 = legacy_tukey_lambda_cdf(dist, x - h);
        (c1 - c0) / (2.0 * h)
    }

    #[test]
    fn tukey_lambda_pdf_matches_previous_numerical_reference_values() {
        let lambdas: [f64; 6] = [-1.0, -0.5, 0.0, 0.5, 1.0, 2.0];
        let xs: [f64; 5] = [-2.0, -1.0, 0.0, 1.0, 2.0];

        for &lam in &lambdas {
            let dist = TukeyLambda::new(lam);
            for &x in &xs {
                if lam > 0.0 && x.abs() >= 1.0 / lam {
                    continue;
                }
                assert_close(
                    dist.pdf(x),
                    legacy_tukey_lambda_pdf(&dist, x),
                    1e-8,
                    &format!("TukeyLambda({lam}) pdf({x})"),
                );
            }
        }
    }

    #[test]
    fn tukey_lambda_cdf_ppf_roundtrip_matches_quantiles() {
        let lambdas = [-1.0, -0.5, 0.0, 0.5, 1.0, 2.0];
        let quantiles = [0.01, 0.1, 0.25, 0.5, 0.75, 0.9, 0.99];

        for &lam in &lambdas {
            let dist = TukeyLambda::new(lam);
            for &q in &quantiles {
                assert_close(
                    dist.cdf(dist.ppf(q)),
                    q,
                    1e-10,
                    &format!("TukeyLambda({lam}) cdf(ppf({q}))"),
                );
            }
        }
    }

    #[test]
    fn tukey_lambda_pdf_trapezoid_integrates_to_one() {
        for &lam in &[0.0, 0.5, 1.0, 2.0] {
            let dist = TukeyLambda::new(lam);
            let lower = dist.ppf(1e-8);
            let upper = dist.ppf(1.0 - 1e-8);
            let n = 20_000usize;
            let h = (upper - lower) / n as f64;
            let integral = (0..=n)
                .map(|i| {
                    let x = lower + i as f64 * h;
                    let weight = if i == 0 || i == n { 0.5 } else { 1.0 };
                    weight * dist.pdf(x)
                })
                .sum::<f64>()
                * h;
            assert_close(
                integral,
                1.0,
                1e-6,
                &format!("TukeyLambda({lam}) trapezoid integral"),
            );
        }
    }

