    #[test]
    fn gen_pareto_pdf_cdf_closed_form_reference_values() {
        // GP(c=+0.5, x=2): t = 1 + 0.5·2 = 2; tp = 2^(-2) = 0.25
        //   cdf = 1 - tp = 0.75
        //   pdf = t^(-1/c - 1) = 2^(-3) = 0.125
        let gp_pos = GenPareto::new(0.5);
        assert_close(
            gp_pos.cdf(2.0),
            0.75,
            1e-12,
            "GP(c=+0.5).cdf(2) closed form",
        );
        assert_close(
            gp_pos.pdf(2.0),
            0.125,
            1e-12,
            "GP(c=+0.5).pdf(2) closed form",
        );

        // GP(c=-0.5, x=1): t = 1 - 0.5·1 = 0.5; tp = 0.5^(2) = 0.25
        //   cdf = 1 - tp = 0.75
        //   pdf = t^(-1/c - 1) = 0.5^(2 - 1) = 0.5
        let gp_neg = GenPareto::new(-0.5);
        assert_close(
            gp_neg.cdf(1.0),
            0.75,
            1e-12,
            "GP(c=-0.5).cdf(1) closed form",
        );
        assert_close(gp_neg.pdf(1.0), 0.5, 1e-12, "GP(c=-0.5).pdf(1) closed form");
    }

    #[test]
    fn power_law_cdf_ppf() {
        let pl = PowerLaw::new(2.0);
        assert!((pl.cdf(0.5) - 0.25).abs() < 1e-10); // x^a = 0.25
        assert!((pl.ppf(0.25) - 0.5).abs() < 1e-10);
        assert!((pl.mean() - 2.0 / 3.0).abs() < 1e-10);
    }

    #[test]
    fn half_normal_pdf_cdf() {
        let hn = HalfNormal;
        assert!(hn.pdf(0.0) > 0.0);
        assert!(hn.pdf(-1.0) == 0.0);
        let c = hn.cdf(1.0);
        assert!(c > 0.0 && c < 1.0);
        assert!((hn.mean() - (2.0 / PI).sqrt()).abs() < 1e-10);
    }

    /// Rayleigh skewness/kurtosis closed forms match scipy
    /// (frankenscipy-5cd0j). Scale-invariant — use unit-scale.
    #[test]
    fn rayleigh_skew_kurt_match_scipy() {
        let r = Rayleigh::new(1.0);
        // scipy.stats.rayleigh.stats(moments='sk') = (0.6311106578189364, 0.24508930068763846)
        assert!(
            (r.skewness() - 0.6311106578189364).abs() < 1e-12,
            "Rayleigh.skewness = {}",
            r.skewness()
        );
        assert!(
            (r.kurtosis() - 0.24508930068763846).abs() < 1e-12,
            "Rayleigh.kurtosis = {}",
            r.kurtosis()
        );
        // Confirm scale invariance.
        let r2 = Rayleigh::new(3.7);
        assert!((r2.skewness() - r.skewness()).abs() < 1e-15);
        assert!((r2.kurtosis() - r.kurtosis()).abs() < 1e-15);
    }

