    #[test]
    fn alpha_skewness_and_kurtosis_are_nan_for_all_a() {
        // Alpha pdf ~ 1/(x² Φ(a)) on the right tail, so every raw
        // moment diverges. scipy.stats.alpha.stats(moments='sk')
        // reports NaN — we match by returning NaN explicitly rather
        // than inheriting the trait default.
        for &a in &[0.5_f64, 1.0, 2.0, 5.0] {
            let d = Alpha::new(a);
            assert!(d.skewness().is_nan(), "Alpha({a}) skew NaN");
            assert!(d.kurtosis().is_nan(), "Alpha({a}) kurt NaN");
        }
    }

    #[test]
    fn trunc_normal_within_bounds() {
        let tn = TruncNormal::new(-1.0, 1.0);
        assert!(tn.pdf(0.0) > 0.0);
        assert!(tn.pdf(2.0) == 0.0);
        assert!(tn.cdf(-1.0) == 0.0);
        assert!(tn.cdf(1.0) == 1.0);
    }

    #[test]
    fn folded_normal_pdf_cdf_match_scipy() {
        // Exact scipy.stats.foldnorm(c=1.5). The FoldedNormal suite covers skew/kurt
        // and entropy but no exact pdf/cdf at a point.
        let d = FoldedNormal::new(1.5);
        assert!(
            (d.pdf(0.5) - 0.295_961_691_032_331_44).abs() < 1e-12,
            "pdf(0.5)"
        );
        assert!(
            (d.pdf(2.0) - 0.352_938_009_459_345_3).abs() < 1e-12,
            "pdf(2)"
        );
        assert!(
            (d.cdf(1.0) - 0.302_327_873_400_210_8).abs() < 1e-12,
            "cdf(1)"
        );
    }

    #[test]
    fn folded_normal_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.foldnorm(c).stats(moments='sk'). At c = 0 the
        // distribution collapses to half-normal; large c approaches
        // |N(c,1)| ≈ N(c,1) (small fold) so skew → 0.
        let cases = [
            (0.0_f64, 0.995_271_746_431_157, 0.869_177_303_605_979),
            (0.5, 0.949_923_352_906_325, 0.705_644_819_122_480),
            (1.5, 0.403_227_728_815_873, -0.284_126_089_902_097),
            (3.0, 0.018_791_057_545_856, -0.059_389_974_423_036),
        ];
        for &(c, s, k) in &cases {
            let d = FoldedNormal::new(c);
            assert_close(d.skewness(), s, 1e-10, &format!("FoldedNormal({c}) skew"));
            assert_close(d.kurtosis(), k, 1e-9, &format!("FoldedNormal({c}) kurt"));
        }
    }

    #[test]
    fn truncnormal_pdf_cdf_match_scipy() {
        // Exact scipy.stats.truncnorm(-1, 2). The TruncNormal suite covers entropy
        // and skew/kurt but no exact pdf/cdf at a point.
        let t = TruncNormal::new(-1.0, 2.0);
        assert!(
            (t.pdf(0.0) - 0.487_350_238_469_530_7).abs() < 1e-12,
            "pdf(0)"
        );
        assert!(
            (t.pdf(1.0) - 0.295_592_861_650_033_7).abs() < 1e-12,
            "pdf(1)"
        );
        assert!(
            (t.cdf(0.0) - 0.416_988_751_428_985_9).abs() < 1e-12,
            "cdf(0)"
        );
    }

    #[test]
    fn truncnormal_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.truncnorm(a, b).stats(moments='sk'). Covers a
        // symmetric, an asymmetric, and a wide window to exercise the
        // by-parts recurrence m_k = (a^{k−1}φ(a) − b^{k−1}φ(b))/Δ +
        // (k−1) m_{k−2}.
        let cases = [
            (-1.0_f64, 1.0_f64, 0.0, -1.059_080_080_096_887),
            (0.0, 2.5, 0.754_028_885_696_173, -0.113_503_742_069_617),
            (-2.0, 0.5, -0.467_304_661_758_473, -0.650_977_346_294_152),
            (-3.0, 3.0, 0.0, -0.171_114_436_397_744),
        ];
        for &(a, b, s, k) in &cases {
            let d = TruncNormal::new(a, b);
            assert_close(
                d.skewness(),
                s,
                1e-11,
                &format!("TruncNormal({a},{b}) skew"),
            );
            assert_close(
                d.kurtosis(),
                k,
                1e-10,
                &format!("TruncNormal({a},{b}) kurt"),
            );
        }
    }

    #[test]
    fn chi_dist_cdf() {
        let chi = Chi::new(2.0);
        assert!(chi.pdf(1.0) > 0.0);
        let c = chi.cdf(1.0);
        assert!(c > 0.0 && c < 1.0);
    }

    #[test]
    fn fisk_cdf_ppf() {
        let f = Fisk::new(2.0);
        let x = 1.0;
        let c = f.cdf(x);
        assert!((c - 0.5).abs() < 1e-10); // CDF(1) = 1/(1+1) = 0.5
        assert!((f.ppf(0.5) - 1.0).abs() < 1e-10);
    }

    #[test]
    fn fisk_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.fisk(c).stats(moments='sk'). Skew needs c > 3,
        // kurt needs c > 4. Cases span moderate-to-thin tails.
        let cases = [
            (5.0_f64, 2.485_275_549_686_714, 26.556_191_909_249_137),
            (7.5, 1.330_035_796_244_332, 6.188_671_909_426_15),
            (10.0, 0.936_674_412_127_485, 3.510_209_942_779_613),
        ];
        for &(c, s, k) in &cases {
            let d = Fisk::new(c);
            assert_close(d.skewness(), s, 1e-10, &format!("Fisk({c}) skew"));
            assert_close(d.kurtosis(), k, 1e-9, &format!("Fisk({c}) kurt"));
        }
    }

    #[test]
    fn fisk_skewness_and_kurtosis_nan_at_boundary() {
        // c ≤ 3 ⇒ μ_3 diverges (m_3 has 1/sin(3π/c)).
        assert!(Fisk::new(3.0).skewness().is_nan());
        assert!(Fisk::new(2.5).skewness().is_nan());
        // c ≤ 4 ⇒ μ_4 diverges.
        assert!(Fisk::new(4.0).kurtosis().is_nan());
        assert!(Fisk::new(3.5).kurtosis().is_nan());
    }

    #[test]
    fn loguniform_pdf_cdf_match_scipy() {
        // Exact scipy.stats.loguniform(1,10). loguniform_cdf_ppf only checks cdf
        // boundaries and ppf(0.5); this pins the pdf and an interior cdf point.
        let lu = Loguniform::new(1.0, 10.0);
        assert!(
            (lu.pdf(2.0) - 0.217_147_240_951_625_85).abs() < 1e-12,
            "pdf(2)"
        );
        assert!(
            (lu.pdf(5.0) - 0.086_858_896_380_650_38).abs() < 1e-12,
            "pdf(5)"
        );
        assert!(
            (lu.cdf(5.0) - 0.698_970_004_336_018_7).abs() < 1e-12,
            "cdf(5)"
        );
    }

    #[test]
    fn loguniform_cdf_ppf() {
        let lu = Loguniform::new(1.0, 10.0);
        assert!((lu.cdf(1.0) - 0.0).abs() < 1e-10);
        assert!((lu.cdf(10.0) - 1.0).abs() < 1e-10);
        assert!((lu.ppf(0.5) - (10.0f64).sqrt()).abs() < 1e-10);
    }

    #[test]
    fn loguniform_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.loguniform(a, b).stats(moments='sk'). Note: skew
        // and kurt are scale-invariant (depend only on b/a), so the
        // (0.1, 5.0) and (2.0, 100.0) cases — both at ratio 50 — give
        // identical values.
        let cases = [
            (
                1.0_f64,
                10.0_f64,
                0.771_604_986_766_096,
                -0.546_529_582_810_115,
            ),
            (0.1, 5.0, 1.244_921_194_046_174, 0.506_230_587_523_249),
            (2.0, 100.0, 1.244_921_194_046_174, 0.506_230_587_523_246),
        ];
        for &(a, b, sk, ku) in &cases {
            let d = Loguniform::new(a, b);
            assert_close(
                d.skewness(),
                sk,
                1e-10,
                &format!("Loguniform({a},{b}) skew"),
            );
            assert_close(
                d.kurtosis(),
                ku,
                1e-10,
                &format!("Loguniform({a},{b}) kurt"),
            );
        }
    }

    #[test]
    fn zipf_pmf_sums() {
        let z = Zipf::new(2.0);
        // PMF should be positive and decreasing
        assert!(z.pmf(1) > z.pmf(2));
        assert!(z.pmf(2) > z.pmf(3));
        let c = z.cdf(10);
        assert!(c > 0.9); // most mass in first 10 terms
    }

    #[test]
    fn logseries_pmf_at_p_half_matches_closed_form() {
        // /testing-golden-artifacts for [frankenscipy-7axi5]:
        //   pmf(1; 0.5) = -0.5 / ln(0.5)              ≈ 0.7213475
        //   pmf(2; 0.5) = -0.25 / (2·ln(0.5))         ≈ 0.1803369
        //   pmf(3; 0.5) = -0.125 / (3·ln(0.5))        ≈ 0.0601123
        let dist = LogSeries::new(0.5);
        let log_half = (0.5_f64).ln();
        for &(k, expected) in &[
            (1u64, -0.5 / log_half),
            (2, -0.25 / (2.0 * log_half)),
            (3, -0.125 / (3.0 * log_half)),
        ] {
            let actual = dist.pmf(k);
            assert!(
                (actual - expected).abs() < 1e-12,
                "logser pmf({k}; 0.5) = {actual}, expected {expected}"
            );
        }
        // pmf(0) = 0 (out of support)
        assert_eq!(dist.pmf(0u64), 0.0);
    }

    #[test]
    fn logseries_cdf_converges_to_one_in_tail() {
        // The PMF sums to 1 by construction; cdf at large k should
        // be very close to 1.
        let dist = LogSeries::new(0.7);
        let tail = dist.cdf(200u64);
        assert!(
            (tail - 1.0).abs() < 1e-9,
            "logser cdf(200; 0.7) = {tail}, expected ≈ 1"
        );
    }

    #[test]
    fn logseries_mean_matches_closed_form() {
        // mean = -p / ((1-p) · ln(1-p))  =  p / ((1-p) · norm)
        // For p=0.5: mean = -0.5 / (0.5 · ln(0.5)) = -1/ln(0.5)
        //                 = 1/ln(2) ≈ 1.44269504
        let dist = LogSeries::new(0.5);
        let expected = 1.0 / (2.0_f64).ln();
        assert!(
            (dist.mean() - expected).abs() < 1e-12,
            "logser mean = {}, expected {}",
            dist.mean(),
            expected
        );
    }

    #[test]
    fn logseries_var_is_positive() {
        // Verify variance is positive and finite for interior p.
        for &p in &[0.2_f64, 0.5, 0.8, 0.95] {
            let v = LogSeries::new(p).var();
            assert!(
                v > 0.0 && v.is_finite(),
                "logser({p}).var() = {v}, expected positive finite"
            );
        }
    }

    #[test]
    fn rv_discrete_basic() {
        let xk = vec![1.0, 2.0, 3.0];
        let pk = vec![0.2, 0.5, 0.3];
        let rv = RvDiscrete::new(xk, pk);

        assert!((rv.pmf(1.0) - 0.2).abs() < 1e-10);
        assert!((rv.pmf(2.0) - 0.5).abs() < 1e-10);
        assert!((rv.pmf(3.0) - 0.3).abs() < 1e-10);
        assert!((rv.pmf(4.0) - 0.0).abs() < 1e-10);
    }

    #[test]
    fn rv_discrete_cdf() {
        let xk = vec![1.0, 2.0, 3.0];
        let pk = vec![0.2, 0.5, 0.3];
        let rv = RvDiscrete::new(xk, pk);

        assert!((rv.cdf(0.5) - 0.0).abs() < 1e-10);
        assert!((rv.cdf(1.0) - 0.2).abs() < 1e-10);
        assert!((rv.cdf(1.5) - 0.2).abs() < 1e-10);
        assert!((rv.cdf(2.0) - 0.7).abs() < 1e-10);
        assert!((rv.cdf(3.0) - 1.0).abs() < 1e-10);
    }

    #[test]
    fn rv_discrete_ppf() {
        let xk = vec![1.0, 2.0, 3.0];
        let pk = vec![0.2, 0.5, 0.3];
        let rv = RvDiscrete::new(xk, pk);

        assert!((rv.ppf(0.1) - 1.0).abs() < 1e-10);
        assert!((rv.ppf(0.2) - 1.0).abs() < 1e-10);
        assert!((rv.ppf(0.3) - 2.0).abs() < 1e-10);
        assert!((rv.ppf(0.7) - 2.0).abs() < 1e-10);
        assert!((rv.ppf(0.8) - 3.0).abs() < 1e-10);
    }

    #[test]
    fn rv_discrete_mean_var() {
        let xk = vec![1.0, 2.0, 3.0];
        let pk = vec![0.2, 0.5, 0.3];
        let rv = RvDiscrete::new(xk, pk);

        let expected_mean = 0.2 * 1.0 + 0.5 * 2.0 + 0.3 * 3.0;
        assert!((rv.mean() - expected_mean).abs() < 1e-10);

        let mu = expected_mean;
        let expected_var =
            0.2 * (1.0 - mu).powi(2) + 0.5 * (2.0 - mu).powi(2) + 0.3 * (3.0 - mu).powi(2);
        assert!((rv.var() - expected_var).abs() < 1e-10);
    }

    #[test]
    fn rv_discrete_normalizes() {
        let xk = vec![0.0, 1.0];
        let pk = vec![2.0, 2.0];
        let rv = RvDiscrete::new(xk, pk);
        assert!((rv.pmf(0.0) - 0.5).abs() < 1e-10);
        assert!((rv.pmf(1.0) - 0.5).abs() < 1e-10);
    }

    #[test]
    fn nakagami_pdf_cdf() {
        let n = Nakagami::new(1.0);
        assert!(n.pdf(1.0) > 0.0);
        let c = n.cdf(1.0);
        assert!(c > 0.0 && c < 1.0);
    }

    #[test]
    fn nakagami_pdf_many_matches_pdf() {
        // Batch pdf_many/logpdf_many (coeff/lead hoisted) must be byte-identical to
        // per-point pdf/logpdf, including x<=0.
        let n = Nakagami::new(2.5);
        let xs = [-1.0, 0.0, 0.3, 1.0, 2.0, 4.0];
        let pm = n.pdf_many(&xs);
        let lpm = n.logpdf_many(&xs);
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(pm[i], n.pdf(x), "pdf_many != pdf at {x}");
            assert_eq!(lpm[i], n.logpdf(x), "logpdf_many != logpdf at {x}");
        }
    }

    #[test]
    fn nakagami_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.nakagami(nu).stats(moments='sk').
        // Spans nu < 1 (heavy skew, Rayleigh-like), nu = 1 (Rayleigh),
        // and nu > 1 (closer to half-normal). All converge cleanly via
        // log-space gamma evaluation.
        let cases = [
            (0.7_f64, 0.798_077_579_646_594, 0.481_641_052_514_496),
            (1.0, 0.631_110_657_818_934, 0.245_089_300_687_629),
            (1.5, 0.485_692_828_049_597, 0.108_163_842_816_250),
            (3.0, 0.317_910_876_930_565, 0.025_111_348_684_700),
        ];
        for &(nu, s, k) in &cases {
            let n = Nakagami::new(nu);
            assert_close(n.skewness(), s, 1e-10, &format!("Nakagami({nu}) skew"));
            assert_close(n.kurtosis(), k, 1e-9, &format!("Nakagami({nu}) kurt"));
        }
    }

    #[test]
    fn rice_pdf_positive() {
        let r = Rice::new(1.0);
        assert!(r.pdf(1.0) > 0.0);
        assert!(r.pdf(-1.0) == 0.0);
    }

    #[test]
    fn rice_skewness_and_kurtosis_match_scipy_reference_values() {
        // scipy.stats.rice(b).stats(moments='sk'). Closed forms use
        // L_{1/2} / L_{3/2} Laguerre identities expressed via I_0, I_1.
        // Three b values span the transition from Rayleigh-dominated
        // (b small) to near-Gaussian (b large).
        let cases = [
            (0.5_f64, 0.617_744_246_266_062, 0.210_469_464_882_587),
            (1.5, 0.354_846_416_684_098, -0.157_092_549_606_078),
            (3.0, 0.059_483_147_708_322, -0.073_040_108_277_302),
        ];
        for &(b, s, k) in &cases {
            let d = Rice::new(b);
            assert_close(d.skewness(), s, 1e-9, &format!("Rice({b}) skew"));
            assert_close(d.kurtosis(), k, 1e-8, &format!("Rice({b}) kurt"));
        }
    }

    #[test]
    fn bonferroni_correction() {
        let pvals = vec![0.01, 0.04, 0.03, 0.005];
        let result = multipletests_bonferroni(&pvals, 0.05);
        assert_eq!(result.pvalues_corrected.len(), 4);
        assert!((result.pvalues_corrected[0] - 0.04).abs() < 1e-10); // 0.01 * 4
        assert!((result.pvalues_corrected[3] - 0.02).abs() < 1e-10); // 0.005 * 4
        assert!(result.reject[3]); // 0.02 < 0.05
        assert!(!result.reject[1]); // 0.16 > 0.05
    }

    #[test]
    fn holm_correction() {
        let pvals = vec![0.01, 0.04, 0.03, 0.005];
        let result = multipletests_holm(&pvals, 0.05);
        // Sorted: 0.005, 0.01, 0.03, 0.04
        // Holm: 0.005*4=0.02, 0.01*3=0.03, 0.03*2=0.06, 0.04*1=0.04
        // Monotone enforced: 0.02, 0.03, 0.06, 0.06
        assert!(result.reject[3]); // 0.005 → 0.02 < 0.05
        assert!(result.reject[0]); // 0.01 → 0.03 < 0.05
    }

    #[test]
    fn fdr_bh_correction() {
        let pvals = vec![0.01, 0.04, 0.03, 0.005];
        let result = multipletests_fdr_bh(&pvals, 0.05);
        // All corrected p-values should be <= 1.0
        assert!(result.pvalues_corrected.iter().all(|&p| p <= 1.0));
        // The smallest p-value should still be the most significant
        assert!(result.pvalues_corrected[3] <= result.pvalues_corrected[0]);
    }

    #[test]
    fn combine_pvalues_fisher_matches_closed_form() {
        let pvalues = [0.01, 0.03, 0.2];
        let result = combine_pvalues(&pvalues, Some("fisher"), None).expect("fisher");
        let expected_statistic = -2.0 * pvalues.iter().map(|p| p.ln()).sum::<f64>();
        let expected_pvalue = ChiSquared::new(2.0 * pvalues.len() as f64).sf(expected_statistic);
        assert_close(
            result.statistic,
            expected_statistic,
            1e-12,
            "combine_pvalues fisher statistic",
        );
        assert_close(
            result.pvalue,
            expected_pvalue,
            1e-12,
            "combine_pvalues fisher pvalue",
        );
    }

    #[test]
    fn combine_pvalues_pearson_matches_scipy_reference() {
        let pvalues = [0.01, 0.03, 0.2];
        let result = combine_pvalues(&pvalues, Some("pearson"), None).expect("pearson");
        assert_close(
            result.statistic,
            -0.527_306_189_304_839_5,
            1e-12,
            "combine_pvalues pearson statistic",
        );
        assert_close(
            result.pvalue,
            0.002_509_830_550_904_323_7,
            1e-12,
            "combine_pvalues pearson pvalue",
        );
    }

    #[test]
    fn combine_pvalues_stouffer_supports_weights() {
        let pvalues = [0.01, 0.05, 0.2];
        let weights = [2.0, 1.0, 0.5];
        let result = combine_pvalues(&pvalues, Some("stouffer"), Some(&weights)).expect("stouffer");
        assert!(result.statistic.is_finite());
        assert!(result.pvalue >= 0.0 && result.pvalue <= 1.0);
        assert!(
            result.pvalue < 0.1,
            "combined evidence should remain significant enough"
        );
    }

    #[test]
    fn combine_pvalues_tippett_uses_smallest_pvalue() {
        let pvalues = [0.4, 0.03, 0.8, 0.2];
        let result = combine_pvalues(&pvalues, Some("tippett"), None).expect("tippett");
        assert_close(result.statistic, 0.03, 1e-12, "tippett statistic");
        let expected_pvalue = 1.0 - (1.0 - 0.03_f64).powi(pvalues.len() as i32);
        assert_close(result.pvalue, expected_pvalue, 1e-12, "tippett pvalue");
    }

    #[test]
    fn combine_pvalues_mudholkar_george_basic() {
        let pvalues = [0.01, 0.03, 0.2];
        let result =
            combine_pvalues(&pvalues, Some("mudholkar_george"), None).expect("mudholkar_george");

        let expected_statistic: f64 = -pvalues
            .iter()
            .map(|&p| p.ln() - (1.0 - p).ln())
            .sum::<f64>();
        assert_close(
            result.statistic,
            expected_statistic,
            1e-12,
            "mudholkar_george statistic",
        );

        assert!(result.pvalue >= 0.0 && result.pvalue <= 1.0);
        assert!(
            result.pvalue < 0.1,
            "combined evidence should be significant for small p-values"
        );
    }

    #[test]
    fn combine_pvalues_mudholkar_george_boundary_cases() {
        let result = combine_pvalues(&[0.0, 0.5], Some("mudholkar_george"), None)
            .expect("mudholkar_george zero");
        assert!(result.statistic == f64::NEG_INFINITY);
        assert!((result.pvalue - 1.0).abs() < 1e-12);

        let result = combine_pvalues(&[1.0, 0.5], Some("mudholkar_george"), None)
            .expect("mudholkar_george one");
        assert!(result.statistic == f64::INFINITY);
        assert!(result.pvalue.abs() < 1e-12);

        let result = combine_pvalues(&[0.0, 1.0], Some("mudholkar_george"), None)
            .expect("mudholkar_george both");
        assert!(result.statistic.is_nan());
        assert!(result.pvalue.is_nan());
    }

    #[test]
    fn false_discovery_control_bh_matches_existing_helper() {
        let pvalues = [0.01, 0.04, 0.03, 0.005];
        let corrected = false_discovery_control(&pvalues, Some("bh")).expect("bh");
        let helper = multipletests_fdr_bh(&pvalues, 0.05);
        assert_eq!(corrected.len(), helper.pvalues_corrected.len());
        for (actual, expected) in corrected.iter().zip(helper.pvalues_corrected.iter()) {
            assert_close(*actual, *expected, 1e-12, "fdr bh corrected");
        }
    }

    #[test]
    fn false_discovery_control_by_is_more_conservative() {
        let pvalues = [0.01, 0.04, 0.03, 0.005];
        let bh = false_discovery_control(&pvalues, Some("bh")).expect("bh");
        let by = false_discovery_control(&pvalues, Some("by")).expect("by");
        for (&bh_p, &by_p) in bh.iter().zip(by.iter()) {
            assert!(by_p >= bh_p, "BY should be at least as conservative as BH");
        }
    }

    #[test]
