    #[test]
    fn nine_more_distributions_now_have_try_fit_overrides() {
        // /modes-of-reasoning [frankenscipy-sf2ax] continuation of
        // covaj/v6rct/paejq: the trait-default try_fit returning
        // NotImplemented was inherited by 9 more distributions
        // despite each having a working fit. After the overrides each
        // returns a typed FitError on bad input and a real fitted Self
        // on good input.

        // Good inputs.
        assert!(<BetaDist as ContinuousDistribution>::try_fit(&[0.1, 0.5, 0.9]).is_ok());
        assert!(<GammaDist as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0]).is_ok());
        assert!(<Lognormal as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0]).is_ok());
        assert!(<Rayleigh as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0]).is_ok());
        assert!(<Gumbel as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0, 4.0]).is_ok());
        assert!(<GumbelLeft as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0, 4.0]).is_ok());
        assert!(<Maxwell as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0]).is_ok());
        assert!(<Cauchy as ContinuousDistribution>::try_fit(&[1.0, 2.0, 3.0, 4.0]).is_ok());
        assert!(<Triangular as ContinuousDistribution>::try_fit(&[0.0, 0.5, 1.0, 1.5]).is_ok());

        // Bad inputs surface typed errors, not NotImplemented.
        macro_rules! assert_typed_err {
            ($dist:ty, $data:expr) => {
                let r = <$dist as ContinuousDistribution>::try_fit($data);
                assert!(
                    matches!(
                        r,
                        Err(FitError::InsufficientData { .. })
                            | Err(FitError::UnsupportedData(_))
                            | Err(FitError::NonConvergent(_))
                    ),
                    concat!(
                        stringify!($dist),
                        " try_fit must surface typed error; got {:?}"
                    ),
                    r
                );
            };
        }
        assert_typed_err!(BetaDist, &[]);
        assert_typed_err!(BetaDist, &[1.5]); // out of [0, 1]
        assert_typed_err!(GammaDist, &[1.0, -2.0]); // negative
        assert_typed_err!(Lognormal, &[1.0, 0.0]); // non-positive
        assert_typed_err!(Rayleigh, &[1.0, -0.5]); // negative
        assert_typed_err!(Gumbel, &[1.0, f64::NAN]); // non-finite
        assert_typed_err!(GumbelLeft, &[]);
        assert_typed_err!(Maxwell, &[1.0, -0.5]); // negative
        assert_typed_err!(Cauchy, &[1.0, f64::NAN]);
        assert_typed_err!(Triangular, &[1.0, 2.0]); // need 3+ samples
    }

    #[test]
    fn parameterless_fit_panics_on_bad_data_for_six_more_distributions() {
        // REVIEW MODE [LOW] regression for [frankenscipy-paejq]: extends
        // 39a09ec/v6rct (HypSecant) — same fit-vs-try_fit asymmetry was
        // present in 6 more parameterless distributions. After dropping
        // the fit overrides, each should panic on data that try_fit would
        // reject as out-of-support.
        let bad_neg = [-0.5_f64];
        for label in ["HalfNormal", "HalfLogistic", "HalfCauchy", "Gilbrat"] {
            let panicked = match label {
                "HalfNormal" => std::panic::catch_unwind(|| HalfNormal::fit(&bad_neg)).is_err(),
                "HalfLogistic" => std::panic::catch_unwind(|| HalfLogistic::fit(&bad_neg)).is_err(),
                "HalfCauchy" => std::panic::catch_unwind(|| HalfCauchy::fit(&bad_neg)).is_err(),
                "Gilbrat" => std::panic::catch_unwind(|| Gilbrat::fit(&bad_neg)).is_err(),
                _ => unreachable!(),
            };
            assert!(panicked, "{label}::fit on negative data must panic");
        }
        // Arcsine: out-of-[0,1] data must panic.
        let arc_bad = [1.5_f64];
        assert!(
            std::panic::catch_unwind(|| Arcsine::fit(&arc_bad)).is_err(),
            "Arcsine::fit on out-of-[0,1] data must panic"
        );
        // Semicircular: out-of-[-1,1] data must panic.
        let sc_bad = [1.5_f64];
        assert!(
            std::panic::catch_unwind(|| Semicircular::fit(&sc_bad)).is_err(),
            "Semicircular::fit on out-of-[-1,1] data must panic"
        );
        // Empty data must panic for all six.
        for label in [
            "HalfNormal",
            "HalfLogistic",
            "HalfCauchy",
            "Arcsine",
            "Semicircular",
            "Gilbrat",
        ] {
            let panicked = match label {
                "HalfNormal" => std::panic::catch_unwind(|| HalfNormal::fit(&[])).is_err(),
                "HalfLogistic" => std::panic::catch_unwind(|| HalfLogistic::fit(&[])).is_err(),
                "HalfCauchy" => std::panic::catch_unwind(|| HalfCauchy::fit(&[])).is_err(),
                "Arcsine" => std::panic::catch_unwind(|| Arcsine::fit(&[])).is_err(),
                "Semicircular" => std::panic::catch_unwind(|| Semicircular::fit(&[])).is_err(),
                "Gilbrat" => std::panic::catch_unwind(|| Gilbrat::fit(&[])).is_err(),
                _ => unreachable!(),
            };
            assert!(panicked, "{label}::fit on empty data must panic");
        }
    }

    #[test]
    fn hypsecant_fit_panics_on_bad_data_consistent_with_try_fit() {
        // /mock-code-finder regression for [frankenscipy-v6rct]:
        // pre-fix HypSecant::fit accepted any data (including NaN/empty)
        // while try_fit validated, inverting the trait contract. After
        // dropping the override, fit inherits the default which delegates
        // to try_fit and panics on FitError. Pin the symmetry.
        // Good data: fit accepts.
        assert_eq!(HypSecant::fit(&[0.0, 0.5, -0.5]), HypSecant);
        // Bad data: fit panics (matching try_fit's typed error).
        let panic_result = std::panic::catch_unwind(|| HypSecant::fit(&[]));
        assert!(
            panic_result.is_err(),
            "HypSecant::fit on empty data must panic per trait contract"
        );
        let panic_nan = std::panic::catch_unwind(|| HypSecant::fit(&[0.0, f64::NAN]));
        assert!(
            panic_nan.is_err(),
            "HypSecant::fit on NaN data must panic per trait contract"
        );
    }

