        let data: Vec<f64> = (1..=10).map(|x| x as f64).collect();

        let trimmed1 = trimboth(&data, 0.1).expect("proportion is in range");
        assert_eq!(trimmed1.len(), 8, "trimboth(0.1) should have 8 elements");

